/// Result of parsing an effect body or modal ability.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct EffectParse {
    pub steps: Vec<EffectStep>,
    pub targets: Vec<TargetSpec>,
    pub modal: Option<ModalDef>,
    pub unparsed: Vec<Span>,
}

/// Single bullet line passed to modal parsers (`"• ..."` with absolute span).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ModalBullet<'a> {
    pub text: &'a str,
    pub span: Span,
}

/// Parses an effect text string using the default no-op quoted ability compiler.
pub fn parse_effects(
    text: &str,
    offset: u32,
    context: AbilityContext,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
) -> EffectParse {
    parse_effects_with_quoted(
        text,
        offset,
        context,
        trigger,
        ctx,
        &NoopQuotedAbilityCompiler,
    )
}

/// Parses an effect text string with an explicit [`QuotedAbilityCompiler`] hook for
/// nested quoted abilities (`grant`, `createToken`, `createEmblem`).
pub fn parse_effects_with_quoted(
    text: &str,
    offset: u32,
    context: AbilityContext,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    parse_effects_inner(text, offset, context, trigger, ctx, quoted_compiler)
}

/// Parses an effect text string with an optional trigger intervening-if condition.
pub fn parse_effects_with_quoted_and_cond(
    text: &str,
    offset: u32,
    context: AbilityContext,
    trigger: Option<&TriggerDef>,
    trigger_cond: Option<&Condition>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    parse_effects_inner_with_cond(
        text,
        offset,
        context,
        trigger,
        trigger_cond,
        ctx,
        quoted_compiler,
    )
}

/// Parses a standard modal header + bullet lines using the default no-op quoted compiler.
pub fn parse_modal(
    header: &str,
    bullets: &[ModalBullet<'_>],
    context: AbilityContext,
    header_start: u32,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
) -> EffectParse {
    parse_modal_with_quoted(
        header,
        bullets,
        context,
        header_start,
        trigger,
        ctx,
        &NoopQuotedAbilityCompiler,
    )
}

/// Parses a standard modal header + bullet lines with an explicit [`QuotedAbilityCompiler`].
pub fn parse_modal_with_quoted(
    header: &str,
    bullets: &[ModalBullet<'_>],
    context: AbilityContext,
    header_start: u32,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    parse_modal_inner(
        header,
        bullets,
        context,
        header_start,
        trigger,
        ctx,
        quoted_compiler,
    )
}

/// Parses extended modal headers (Spree, Tiered, Pawprint, conditional ranges/repeats,
/// prefix/suffix effects) using the default no-op quoted compiler.
pub fn parse_expanded_modal(
    header: &str,
    bullets: &[ModalBullet<'_>],
    context: AbilityContext,
    header_start: u32,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
) -> Option<EffectParse> {
    parse_expanded_modal_with_quoted(
        header,
        bullets,
        context,
        header_start,
        trigger,
        ctx,
        &NoopQuotedAbilityCompiler,
    )
}

/// Parses extended modal headers with an explicit [`QuotedAbilityCompiler`].
pub fn parse_expanded_modal_with_quoted(
    header: &str,
    bullets: &[ModalBullet<'_>],
    context: AbilityContext,
    header_start: u32,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> Option<EffectParse> {
    parse_expanded_modal_inner(
        header,
        bullets,
        context,
        header_start,
        trigger,
        ctx,
        quoted_compiler,
    )
}

/// Parses the spell lines of an instant or sorcery into a single [`EffectParse`].
pub fn parse_spell_face(
    lines: &[NormalizedLine],
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    parse_spell_face_inner(lines, ctx, quoted_compiler)
}

/// Returns `true` if a compiled [`EffectParse`] can execute on the IR interpreter
/// (`unparsed` empty, all steps/selectors/targets supported).
pub fn statically_interpretable(parse: &EffectParse, allow_optional_prefix: bool) -> bool {
    statically_interpretable_impl(parse, allow_optional_prefix)
}

/// Returns `true` if all [`TargetSpec`] entries in a triggered ability are supported on the stack.
pub fn trigger_targets_supported(specs: &[TargetSpec]) -> bool {
    trigger_targets_supported_impl(specs)
}

/// Trigger interpretability gate (`statically_interpretable(parse, true) && trigger_targets_supported(&parse.targets)`).
pub fn interpretable_trigger(parse: &EffectParse) -> bool {
    interpretable_trigger_impl(parse)
}

/// Returns `true` if a mana ability step (`AddMana` or self `FreezeUntap`) is complete for mana execution.
pub fn mana_step_complete(step: &EffectStep) -> bool {
    mana_step_complete_impl(step)
}

/// Extracts best-effort [`TargetSpec`]s from unparsed spell/ability text (CR 601.2c target picker fallback).
pub fn extract_unparsed_targets(text: &str, ctx: &mut ParseCtx<'_>) -> Vec<TargetSpec> {
    extract_unparsed_targets_impl(text, ctx)
}

// ============================================================================
// Section 2: ParserState, ParserMark, ParserScope, Step & StepGate Helpers
// ============================================================================

#[derive(Debug, Clone)]
struct ParserMark {
    steps_len: usize,
    targets_len: usize,
    unparsed_len: usize,
    last_object: Option<(Ref, usize)>,
    last_player: Option<Selector>,
    last_optional_step: Option<usize>,
    defined_x: Option<Amount>,
    pronoun_subject: PronounSubject,
    is_each_loop: bool,
    pending_repeat: Option<Amount>,
    pending_dig: Option<usize>,
    alt_pending_dig: Option<usize>,
    prev_sentence_step_start: usize,
    prev_sentence_target_start: usize,
    last_sentence_target_start: usize,
    last_compare: Option<(Amount, Amount)>,
    last_target_counter_cap: Option<(PlayerRef, PlayerCounterKind, i32)>,
    modal: Option<ModalDef>,
    interner_cp: InternCheckpoint,
}

struct ParserState<'a> {
    steps: Vec<EffectStep>,
    targets: Vec<TargetSpec>,
    unparsed: Vec<Span>,
    context: AbilityContext,
    trigger: Option<&'a TriggerDef>,
    last_object: Option<(Ref, usize)>,
    last_player: Option<Selector>,
    last_optional_step: Option<usize>,
    defined_x: Option<Amount>,
    trigger_had_counter: Option<CounterTarget>,
    trigger_has_exiled_with_self: bool,
    pronoun_subject: PronounSubject,
    is_each_loop: bool,
    pending_repeat: Option<Amount>,
    pending_dig: Option<usize>,
    alt_pending_dig: Option<usize>,
    last_sentence_step_start: usize,
    prev_sentence_step_start: usize,
    last_sentence_target_start: usize,
    prev_sentence_target_start: usize,
    last_compare: Option<(Amount, Amount)>,
    last_target_counter_cap: Option<(PlayerRef, PlayerCounterKind, i32)>,
    modal: Option<ModalDef>,
    bind_counter: usize,
    parent_exile_bindings: Vec<String>,
    parent_exile_selectors: Vec<Selector>,
    delayed_depth: u8,
    clause_split_budget: usize,
    quoted_compiler: &'a dyn QuotedAbilityCompiler,
    quoted_cache: HashMap<(String, String), Vec<AbilityDef>>,
}

impl<'a> ParserState<'a> {
    fn new(
        context: AbilityContext,
        trigger: Option<&'a TriggerDef>,
        quoted_compiler: &'a dyn QuotedAbilityCompiler,
    ) -> Self {
        let pronoun_subject = if let Some(t) = trigger {
            if t.event == EventKind::Attached
                || matches!(t.filter.object, Some(TriggerSubject::AttachedTo))
            {
                PronounSubject::AttachedTo
            } else {
                PronounSubject::SelfObj
            }
        } else {
            PronounSubject::SelfObj
        };
        Self {
            steps: Vec::new(),
            targets: Vec::new(),
            unparsed: Vec::new(),
            context,
            trigger,
            last_object: None,
            last_player: None,
            last_optional_step: None,
            defined_x: None,
            trigger_had_counter: None,
            trigger_has_exiled_with_self: false,
            pronoun_subject,
            is_each_loop: false,
            pending_repeat: None,
            pending_dig: None,
            alt_pending_dig: None,
            last_sentence_step_start: 0,
            prev_sentence_step_start: 0,
            last_sentence_target_start: 0,
            prev_sentence_target_start: 0,
            last_compare: None,
            last_target_counter_cap: None,
            modal: None,
            bind_counter: 0,
            parent_exile_bindings: Vec::new(),
            parent_exile_selectors: Vec::new(),
            delayed_depth: 0,
            clause_split_budget: 64,
            quoted_compiler,
            quoted_cache: HashMap::new(),
        }
    }

    fn mark(&self, ctx: &ParseCtx<'_>) -> ParserMark {
        ParserMark {
            steps_len: self.steps.len(),
            targets_len: self.targets.len(),
            unparsed_len: self.unparsed.len(),
            last_object: self.last_object.clone(),
            last_player: self.last_player.clone(),
            last_optional_step: self.last_optional_step,
            defined_x: self.defined_x.clone(),
            pronoun_subject: self.pronoun_subject,
            is_each_loop: self.is_each_loop,
            pending_repeat: self.pending_repeat.clone(),
            pending_dig: self.pending_dig,
            alt_pending_dig: self.alt_pending_dig,
            prev_sentence_step_start: self.prev_sentence_step_start,
            prev_sentence_target_start: self.prev_sentence_target_start,
            last_sentence_target_start: self.last_sentence_target_start,
            last_compare: self.last_compare.clone(),
            last_target_counter_cap: self.last_target_counter_cap.clone(),
            modal: self.modal.clone(),
            interner_cp: ctx.interner.checkpoint(),
        }
    }

    fn rollback(&mut self, mark: ParserMark, ctx: &mut ParseCtx<'_>) {
        self.steps.truncate(mark.steps_len);
        self.targets.truncate(mark.targets_len);
        self.unparsed.truncate(mark.unparsed_len);
        self.last_object = mark.last_object;
        self.last_player = mark.last_player;
        self.last_optional_step = mark.last_optional_step;
        self.defined_x = mark.defined_x;
        self.pronoun_subject = mark.pronoun_subject;
        self.is_each_loop = mark.is_each_loop;
        self.pending_repeat = mark.pending_repeat;
        self.pending_dig = mark.pending_dig;
        self.alt_pending_dig = mark.alt_pending_dig;
        self.prev_sentence_step_start = mark.prev_sentence_step_start;
        self.prev_sentence_target_start = mark.prev_sentence_target_start;
        self.last_sentence_target_start = mark.last_sentence_target_start;
        self.last_compare = mark.last_compare;
        self.last_target_counter_cap = mark.last_target_counter_cap;
        self.modal = mark.modal;
        ctx.interner.rollback(mark.interner_cp);
    }

    fn add_target(&mut self, spec: TargetSpec) -> u16 {
        let idx = self.targets.len() as u16;
        self.targets.push(spec);
        idx
    }

    fn alloc_bind_name(&mut self, prefix: &str) -> String {
        let id = self.bind_counter;
        self.bind_counter += 1;
        format!("{prefix}_{id}")
    }

    fn push_step(&mut self, mut step: EffectStep, sets_it: bool) {
        if let Some(rep) = self.pending_repeat.take() {
            step.amount = Some(Box::new(rep));
        }
        let idx = self.steps.len();
        if let Selector::Target { index } = step.subject {
            if sets_it {
                if matches!(step.op, EffectOp::Damage { .. }) {
                    self.last_object = Some((Ref::Target { index }, idx));
                } else {
                    let bname = self.alloc_bind_name("b");
                    step.bind_as = Some(bname.clone());
                    self.last_object = Some((Ref::Binding { name: bname }, idx));
                }
            }
        } else if sets_it {
            if let Some(ref b) = step.bind_as {
                self.last_object = Some((Ref::Binding { name: b.clone() }, idx));
            } else {
                match &step.subject {
                    Selector::SelfObj => {
                        if matches!(step.op, EffectOp::Transform | EffectOp::Animate { .. }) {
                            let bname = self.alloc_bind_name("b");
                            step.bind_as = Some(bname.clone());
                            self.last_object = Some((Ref::Binding { name: bname }, idx));
                        } else {
                            self.last_object = Some((Ref::SelfObj, idx));
                        }
                    }
                    Selector::EventObject => self.last_object = Some((Ref::EventObject, idx)),
                    Selector::AttachedTo => {
                        if matches!(
                            step.op,
                            EffectOp::Sacrifice { .. }
                                | EffectOp::Destroy { .. }
                                | EffectOp::Exile { .. }
                                | EffectOp::Bounce { .. }
                                | EffectOp::Move { .. }
                        ) && self.trigger.is_some_and(|tr| {
                            matches!(tr.filter.object, Some(TriggerSubject::AttachedTo))
                        }) {
                            self.last_object = Some((Ref::EventObject, idx));
                        } else {
                            self.last_object = Some((Ref::AttachedTo, idx));
                        }
                    }
                    Selector::Binding { name } => {
                        self.last_object = Some((Ref::Binding { name: name.clone() }, idx));
                    }
                    Selector::All { .. } | Selector::LibraryTop { .. } => {
                        let bname = self.alloc_bind_name("b");
                        step.bind_as = Some(bname.clone());
                        self.last_object = Some((Ref::Binding { name: bname }, idx));
                    }
                    _ => {}
                }
            }
        }
        if let Selector::All { ref filter } = step.subject {
            for pred in &filter.extra {
                if let ObjectPredicate::ControllerRef { player }
                | ObjectPredicate::OwnerRef { player } = pred
                    && matches!(player, PlayerRef::Target { .. })
                {
                    self.last_player = Some(Selector::PlayerRef {
                        player: player.clone(),
                    });
                }
            }
        }
        if let Selector::Player { ref filter } = step.subject
            && filter.relation != PlayerRelation::You
        {
            self.last_player = Some(step.subject.clone());
        }
        if step.optional.is_some() {
            self.last_optional_step = Some(idx);
        }
        self.steps.push(step);
    }

    fn compile_quoted(
        &mut self,
        ability_text: &str,
        card_name: &str,
        ctx: &mut ParseCtx<'_>,
    ) -> Vec<AbilityDef> {
        let key = (ability_text.to_string(), card_name.to_string());
        if let Some(cached) = self.quoted_cache.get(&key) {
            return cached.clone();
        }
        let defs =
            self.quoted_compiler
                .compile_quoted_ability(ability_text, card_name, ctx.interner);
        self.quoted_cache.insert(key, defs.clone());
        defs
    }

    fn set_last_player_from_selector(&mut self, sel: &Selector) {
        match sel {
            Selector::Player { .. } | Selector::PlayerRef { .. } | Selector::Target { .. } => {
                self.last_player = Some(sel.clone());
            }
            _ => {}
        }
    }

    fn single_player_ref(&self) -> Option<PlayerRef> {
        match &self.last_player {
            Some(Selector::PlayerRef { player }) => Some(player.clone()),
            Some(Selector::Target { index }) => Some(PlayerRef::Target { index: *index }),
            Some(Selector::Player { filter }) => match filter.relation {
                PlayerRelation::You => Some(PlayerRef::You),
                _ => None,
            },
            _ => None,
        }
    }

    fn parse_sub_effects(
        &mut self,
        text: &str,
        offset: u32,
        context: AbilityContext,
        ctx: &mut ParseCtx<'_>,
    ) -> EffectParse {
        parse_effects_inner(
            text,
            offset,
            context,
            self.trigger,
            ctx,
            self.quoted_compiler,
        )
    }
}

impl ParserScope for ParserState<'_> {
    fn in_trigger_context(&self) -> bool {
        self.context == AbilityContext::Triggered || self.trigger.is_some()
    }

    fn has_prior_step(&self) -> bool {
        !self.steps.is_empty()
    }

    fn trigger_event_is_exile(&self) -> bool {
        self.trigger
            .and_then(|t| t.filter.detail.as_ref())
            .is_some_and(|d| {
                matches!(
                    d,
                    EventDetail::ZoneChange {
                        to: Some(Zone::Exile),
                        ..
                    }
                )
            })
    }

    fn trigger_is_ltb(&self) -> bool {
        self.trigger.is_some_and(|t| {
            matches!(
                t.event,
                EventKind::Sacrificed | EventKind::HauntedCreatureDies
            ) || matches!(
                t.filter.detail.as_ref(),
                Some(EventDetail::ZoneChange { from, .. })
                    if from.intersects(ZoneMask::BATTLEFIELD)
            )
        })
    }

    fn trigger_targets_self(&self) -> bool {
        self.trigger.is_some_and(|t| {
            matches!(
                t.filter.object,
                Some(TriggerSubject::SelfObj) | Some(TriggerSubject::AttachedTo)
            )
        })
    }

    fn trigger_matches_that_noun(&self, noun: &str) -> bool {
        let Some(t) = self.trigger else {
            return false;
        };
        if self.trigger_targets_self() {
            return false;
        }
        let n_low = noun.to_ascii_lowercase();
        if n_low == "spell" {
            return matches!(t.event, EventKind::Cast);
        }
        match &t.filter.object {
            Some(TriggerSubject::Filter { filter }) => match n_low.as_str() {
                "land" => {
                    filter.types_any.contains(CardTypeMask::LAND)
                        || filter.types_all.contains(CardTypeMask::LAND)
                }
                "creature" => {
                    filter.types_any.contains(CardTypeMask::CREATURE)
                        || filter.types_all.contains(CardTypeMask::CREATURE)
                }
                "artifact" => {
                    filter.types_any.contains(CardTypeMask::ARTIFACT)
                        || filter.types_all.contains(CardTypeMask::ARTIFACT)
                }
                "enchantment" => {
                    filter.types_any.contains(CardTypeMask::ENCHANTMENT)
                        || filter.types_all.contains(CardTypeMask::ENCHANTMENT)
                }
                "planeswalker" => {
                    filter.types_any.contains(CardTypeMask::PLANESWALKER)
                        || filter.types_all.contains(CardTypeMask::PLANESWALKER)
                }
                "card" => true,
                _ => false,
            },
            _ => false,
        }
    }

    fn has_sac_step_or_trigger(&self) -> bool {
        self.steps
            .iter()
            .any(|s| matches!(s.op, EffectOp::Sacrifice { .. }))
            || self
                .trigger
                .is_some_and(|t| matches!(t.event, EventKind::Sacrificed))
    }

    fn has_mill_step(&self) -> bool {
        self.steps.iter().any(|s| matches!(s.op, EffectOp::Mill))
    }

    fn it_ref(&self) -> Option<Ref> {
        self.last_object.as_ref().map(|(r, _)| r.clone())
    }

    fn has_reveal_drawn(&self) -> bool {
        self.last_object.is_none()
            && self.steps.last().is_some_and(|s| {
                matches!(
                    s.op,
                    EffectOp::Draw {
                        reveal_drawn: true,
                        ..
                    }
                )
            })
    }

    fn last_player_ref(&self) -> Option<PlayerRef> {
        self.single_player_ref()
    }

    fn defined_x(&self) -> Option<Amount> {
        self.defined_x.clone()
    }

    fn default_pronoun_subject(&self) -> PronounSubject {
        self.pronoun_subject
    }

    fn has_non_self_pronoun_target(&self) -> bool {
        matches!(
            self.last_object,
            Some((Ref::Target { .. } | Ref::Binding { .. }, _))
        )
    }

    fn is_each_loop_player(&self) -> bool {
        self.is_each_loop
    }

    fn alloc_target(&mut self, spec: TargetSpec) -> Option<u16> {
        Some(self.add_target(spec))
    }

    fn get_target(&self, idx: u16) -> Option<&TargetSpec> {
        self.targets.get(idx as usize)
    }

    fn prior_targets_len(&self) -> usize {
        self.targets.len()
    }

    fn truncate_targets(&mut self, len: usize) {
        self.targets.truncate(len);
    }

    fn record_last_player(&mut self, p: PlayerRef) {
        self.last_player = Some(Selector::PlayerRef { player: p });
    }

    fn record_last_target(&mut self, r: Ref) {
        let idx = self.steps.len();
        self.last_object = Some((r, idx));
    }

    fn ensure_last_step_bound(&mut self) -> Option<Ref> {
        if let Some((r, step_idx)) = self.last_object.clone() {
            if let Ref::Binding { ref name } = r
                && let Some(st) = self.steps.get_mut(step_idx)
                && st.bind_as.is_none()
            {
                st.bind_as = Some(name.clone());
            }
            return Some(r);
        }
        None
    }

    fn difference_is_player_counter(&self) -> Option<(PlayerRef, mtg_ir::PlayerCounterKind, i32)> {
        self.last_target_counter_cap.clone()
    }
}

fn make_step(op: EffectOp, subject: Selector, span: Span) -> EffectStep {
    EffectStep {
        op,
        subject,
        actor: None,
        amount: None,
        optional: None,
        gate: None,
        bind_as: None,
        do_this_once_per_turn: false,
        reflexive_trigger: None,
        span,
    }
}

fn you_sel() -> Selector {
    Selector::Player {
        filter: PlayerFilter {
            relation: PlayerRelation::You,
        },
    }
}

fn default_target_spec() -> TargetSpec {
    TargetSpec {
        kind: TargetKind::Object,
        filter: ObjectFilter::default(),
        player: None,
        min: 1,
        max: 1,
        same_owner: false,
        condition: None,
        other_target: false,
        divide_total: None,
        with_single_target: false,
        dynamic_count: None,
        dynamic_up_to: false,
        max_total_mana_value: None,
        also_spells: false,
        per_opponent: false,
        different_controllers: false,
        chosen_by_event_player: false,
        shares_card_type_with_target: None,
        zones: ZoneMask::empty(),
    }
}

fn ref_to_selector(r: &Ref) -> Selector {
    match r {
        Ref::SelfObj => Selector::SelfObj,
        Ref::Target { index } => Selector::Target { index: *index },
        Ref::Binding { name } => Selector::Binding { name: name.clone() },
        Ref::EventObject => Selector::EventObject,
        Ref::AttachedTo => Selector::AttachedTo,
        Ref::Affected | Ref::LinkedExile => Selector::SelfObj,
    }
}

fn attach_gate_condition(gate: &mut Option<StepGate>, cond: Condition) {
    match gate.take() {
        None => {
            *gate = Some(StepGate::Condition {
                condition: Box::new(cond),
            })
        }
        Some(StepGate::Condition {
            condition: existing,
        }) => {
            *gate = Some(StepGate::Condition {
                condition: Box::new(Condition::And {
                    of: vec![cond, *existing],
                }),
            });
        }
        Some(StepGate::IfPrecedingAccepted { step_index }) => {
            *gate = Some(StepGate::Combined {
                if_preceding_accepted: Some(step_index),
                if_preceding_declined: None,
                condition: Some(Box::new(cond)),
            });
        }
        Some(StepGate::IfPrecedingDeclined { step_index }) => {
            *gate = Some(StepGate::Combined {
                if_preceding_accepted: None,
                if_preceding_declined: Some(step_index),
                condition: Some(Box::new(cond)),
            });
        }
        Some(StepGate::Combined {
            if_preceding_accepted,
            if_preceding_declined,
            condition: existing,
        }) => {
            let merged = match existing {
                Some(ex) => Condition::And {
                    of: vec![cond, *ex],
                },
                None => cond,
            };
            *gate = Some(StepGate::Combined {
                if_preceding_accepted,
                if_preceding_declined,
                condition: Some(Box::new(merged)),
            });
        }
    }
}

// ============================================================================
// Section 3: Zero-Regex String / Token Utilities & Clause Splitter
// ============================================================================

#[inline]
fn is_word_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

#[inline]
fn eq_ci(a: &str, b: &str) -> bool {
    a.eq_ignore_ascii_case(b)
}

fn trim_trailing_period(s: &str) -> &str {
    let t = s.trim();
    t.strip_suffix('.').map(str::trim_end).unwrap_or(t)
}

fn strip_outer_quotes(s: &str) -> Option<&str> {
    let t = s.trim();
    if let Some(rest) = t.strip_prefix('"').and_then(|x| x.strip_suffix('"')) {
        return Some(rest);
    }
    if let Some(rest) = t.strip_prefix('“').and_then(|x| x.strip_suffix('”')) {
        return Some(rest);
    }
    if let Some(rest) = t.strip_prefix('\'').and_then(|x| x.strip_suffix('\'')) {
        return Some(rest);
    }
    None
}

fn starts_with_word_ci(s: &str, prefix: &str) -> bool {
    if prefix.is_empty() || s.len() < prefix.len() || !s.is_char_boundary(prefix.len()) {
        return false;
    }
    if !s[..prefix.len()].eq_ignore_ascii_case(prefix) {
        return false;
    }
    let last_is_word = is_word_char(prefix.as_bytes()[prefix.len() - 1]);
    !last_is_word
        || s.as_bytes()
            .get(prefix.len())
            .is_none_or(|b| !is_word_char(*b))
}

fn strip_prefix_word_ci<'a>(s: &'a str, prefix: &str) -> Option<&'a str> {
    if !starts_with_word_ci(s, prefix) {
        return None;
    }
    Some(s[prefix.len()..].trim_start())
}

fn strip_suffix_word_ci<'a>(s: &'a str, suffix: &str) -> Option<&'a str> {
    if suffix.is_empty() || s.len() < suffix.len() {
        return None;
    }
    let idx = s.len() - suffix.len();
    if !s.is_char_boundary(idx) || !s[idx..].eq_ignore_ascii_case(suffix) {
        return None;
    }
    let first_is_word = is_word_char(suffix.as_bytes()[0]);
    if first_is_word && idx > 0 && is_word_char(s.as_bytes()[idx - 1]) {
        return None;
    }
    Some(s[..idx].trim_end())
}

fn find_word_ci(haystack: &str, needle: &str) -> Option<usize> {
    let h = haystack.as_bytes();
    let n = needle.as_bytes();
    let n_len = n.len();
    if n_len == 0 || h.len() < n_len {
        return None;
    }
    let b0_lo = n[0].to_ascii_lowercase();
    let b0_hi = n[0].to_ascii_uppercase();
    let left_needs_boundary = is_word_char(n[0]);
    let right_needs_boundary = is_word_char(n[n_len - 1]);
    let limit = h.len() - n_len;
    let mut i = 0;
    while i <= limit {
        let b = h[i];
        if (b == b0_lo || b == b0_hi)
            && h[i..i + n_len].eq_ignore_ascii_case(n)
            && haystack.is_char_boundary(i)
            && haystack.is_char_boundary(i + n_len)
        {
            let left_ok = !left_needs_boundary || i == 0 || !is_word_char(h[i - 1]);
            let right_ok =
                !right_needs_boundary || i + n_len == h.len() || !is_word_char(h[i + n_len]);
            if left_ok && right_ok {
                return Some(i);
            }
        }
        i += 1;
    }
    None
}

fn contains_word_ci(haystack: &str, needle: &str) -> bool {
    find_word_ci(haystack, needle).is_some()
}

#[inline]
fn find_ascii_ci_from(h: &[u8], n: &[u8], start: usize) -> Option<usize> {
    let n_len = n.len();
    if n_len == 0 || h.len() < start + n_len {
        return None;
    }
    let b0_lo = n[0].to_ascii_lowercase();
    let b0_hi = n[0].to_ascii_uppercase();
    let limit = h.len() - n_len;
    let mut i = start;
    while i <= limit {
        let b = h[i];
        if (b == b0_lo || b == b0_hi) && h[i..i + n_len].eq_ignore_ascii_case(n) {
            return Some(i);
        }
        i += 1;
    }
    None
}

#[inline]
fn contains_ascii_ci(h: &[u8], n: &[u8]) -> bool {
    find_ascii_ci_from(h, n, 0).is_some()
}

#[inline]
fn ends_with_ci(h: &[u8], n: &[u8]) -> bool {
    h.len() >= n.len() && h[h.len() - n.len()..].eq_ignore_ascii_case(n)
}

#[inline]
fn starts_with_ci(h: &str, p: &str) -> bool {
    let hb = h.as_bytes();
    let pb = p.as_bytes();
    hb.len() >= pb.len() && hb[..pb.len()].eq_ignore_ascii_case(pb)
}

#[inline]
fn strip_prefix_ci<'a>(h: &'a str, p: &str) -> Option<&'a str> {
    if starts_with_ci(h, p) && h.is_char_boundary(p.len()) {
        Some(&h[p.len()..])
    } else {
        None
    }
}

#[inline]
fn strip_suffix_ci<'a>(h: &'a str, s: &str) -> Option<&'a str> {
    let hb = h.as_bytes();
    let sb = s.as_bytes();
    if hb.len() >= sb.len() {
        let idx = hb.len() - sb.len();
        if h.is_char_boundary(idx) && hb[idx..].eq_ignore_ascii_case(sb) {
            return Some(&h[..idx]);
        }
    }
    None
}

#[inline]
fn rfind_ascii_ci(h: &[u8], n: &[u8]) -> Option<usize> {
    if n.is_empty() {
        return Some(h.len());
    }
    if h.len() < n.len() {
        return None;
    }
    h.windows(n.len()).rposition(|w| w.eq_ignore_ascii_case(n))
}

fn split_at_top_level_comma(s: &str) -> Option<(&str, &str)> {
    let mut in_dq = false;
    let mut paren = 0usize;
    for (idx, ch) in s.char_indices() {
        match ch {
            '"' | '“' | '”' => in_dq = !in_dq,
            '(' if !in_dq => paren += 1,
            ')' if !in_dq => paren = paren.saturating_sub(1),
            ',' if !in_dq && paren == 0 => {
                return Some((s[..idx].trim(), s[idx + 1..].trim()));
            }
            _ => {}
        }
    }
    None
}

fn split_clauses_quote_aware<'a>(text: &'a str, base_offset: u32) -> Vec<(&'a str, Span)> {
    let bytes = text.as_bytes();
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut in_dq = false;
    let mut paren = 0usize;
    let mut i = 0usize;

    let push_slice = |out: &mut Vec<(&'a str, Span)>, s_idx: usize, e_idx: usize| {
        let raw = &text[s_idx..e_idx];
        let trimmed_start = raw.len() - raw.trim_start().len();
        let trimmed_end = raw.trim_end().len();
        if trimmed_start < trimmed_end {
            let abs_s = s_idx + trimmed_start;
            let abs_e = s_idx + trimmed_end;
            out.push((
                &text[abs_s..abs_e],
                Span {
                    start: base_offset + abs_s as u32,
                    end: base_offset + abs_e as u32,
                },
            ));
        }
    };

    while i < bytes.len() {
        let ch = match text[i..].chars().next() {
            Some(c) => c,
            None => break,
        };
        let clen = ch.len_utf8();
        if ch == '"' || ch == '“' || ch == '”' {
            in_dq = !in_dq;
            i += clen;
            continue;
        }
        if in_dq {
            i += clen;
            continue;
        }
        if ch == '(' {
            paren += 1;
            i += clen;
            continue;
        }
        if ch == ')' {
            paren = paren.saturating_sub(1);
            i += clen;
            continue;
        }
        if paren > 0 {
            i += clen;
            continue;
        }
        if ch == ';' {
            push_slice(&mut out, start, i);
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_whitespace() {
                i += 1;
            }
            start = i;
            continue;
        }
        // ", then " or ", and then " or ". " shouldn't be here (sentences split first), check ", then "
        if ch == ',' {
            let after_comma = text[i + 1..].trim_start();
            let ws_len = text[i + 1..].len() - after_comma.len();
            if starts_with_word_ci(after_comma, "then") {
                push_slice(&mut out, start, i);
                i = i + 1 + ws_len + 4;
                while i < bytes.len() && bytes[i].is_ascii_whitespace() {
                    i += 1;
                }
                start = i;
                continue;
            }
            if starts_with_word_ci(after_comma, "and") {
                let after_and = after_comma[3..].trim_start();
                // Split on ", and <verb>..." if the left side looks complete (avoiding "target A, B, and C" or "white, blue, and black")
                let left = text[start..i].trim();
                if starts_with_clause_verb(after_and)
                    && !ends_with_list_separator(left)
                    && !contains_word_ci(left, "divided as you choose")
                {
                    push_slice(&mut out, start, i);
                    i = i + 1 + ws_len + 3;
                    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
                        i += 1;
                    }
                    start = i;
                    continue;
                }
            }
        }
        // Top-level " and " when right-hand starts a new imperative clause and left-hand isn't a compound target/noun phrase
        if ch.is_ascii_whitespace() && i > start {
            let rest = text[i..].trim_start();
            let ws = text[i..].len() - rest.len();
            if starts_with_word_ci(rest, "and") {
                let after_and = rest[3..].trim_start();
                let left = text[start..i].trim();
                if should_split_on_and(left, after_and) {
                    push_slice(&mut out, start, i);
                    i = i + ws + 3;
                    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
                        i += 1;
                    }
                    start = i;
                    continue;
                }
            }
        }
        i += clen;
    }
    push_slice(&mut out, start, bytes.len());
    out
}

fn ends_with_list_separator(left: &str) -> bool {
    let lb = left.as_bytes();
    contains_ascii_ci(lb, b"between ")
        || ends_with_ci(lb, b"of")
        || ends_with_ci(lb, b"to")
        || ends_with_ci(lb, b"from")
        || ends_with_ci(lb, b"with")
        || ends_with_ci(lb, b"target")
}

fn starts_with_clause_verb(s: &str) -> bool {
    let t = s.trim_start();
    const VERBS: &[&str] = &[
        "add",
        "adapt",
        "amass",
        "attach",
        "blight",
        "bolster",
        "choose",
        "clash",
        "cloak",
        "collect",
        "connive",
        "convert",
        "copy",
        "counter",
        "create",
        "destroy",
        "detain",
        "discard",
        "discover",
        "draw",
        "earthbend",
        "end",
        "endure",
        "exchange",
        "exert",
        "exile",
        "explore",
        "fateseal",
        "fight",
        "flip",
        "forage",
        "gain",
        "goad",
        "harness",
        "incubate",
        "investigate",
        "learn",
        "look",
        "lose",
        "manifest",
        "meld",
        "mill",
        "monstrosity",
        "move",
        "pay",
        "phase",
        "populate",
        "prevent",
        "proliferate",
        "put",
        "regenerate",
        "remove",
        "reveal",
        "roll",
        "sacrifice",
        "saddle",
        "scry",
        "search",
        "shuffle",
        "skip",
        "solve",
        "surveil",
        "suspect",
        "switch",
        "take",
        "tap",
        "tempt",
        "time",
        "transform",
        "turn",
        "untap",
        "venture",
        "vote",
        "win",
        "you",
        "each",
        "that",
        "it",
        "they",
        "target",
        "return",
        "its",
        "their",
        "until",
        "at",
        "when",
        "whenever",
        "if",
    ];
    VERBS.iter().any(|v| starts_with_word_ci(t, v))
}

fn should_split_on_and(left: &str, right: &str) -> bool {
    let l = left.trim();
    let r = right.trim();
    if l.is_empty() || r.is_empty() {
        return false;
    }
    // Never split inside phrases like "create a ... token and ... token" or "add X and Y" or "gains X and Y" or "gets +1/+1 and gains" (handled by predicate/clause parsers)
    // Wait: "gains flying and vigilance" -> right starts with keyword; "gets +1/+1 until end of turn and gains flying" -> handled by clause predicate/grant, or split cleanly?
    // Wait: in MTG, "you gain 2 life and draw a card" -> split!
    // "target player draws two cards and loses 2 life" -> don't split on 'and loses', predicate/player handler handles it!
    // Check if right starts with explicit imperative verb or "you <verb>" or "each <player>" or "then <verb>" or "target <noun> <verb>"
    if starts_with_word_ci(l, "put") && starts_with_word_ci(r, "draw") {
        // e.g. "put it into your hand" vs "You draw cards and lose life" -> OK
    }
    if ends_with_list_separator(l) {
        return false;
    }
    // Protect "power and toughness", "shuffle it and ...", "up to ...", "cards from ... and ..."
    if strip_suffix_word_ci(l, "power").is_some() && starts_with_word_ci(r, "toughness") {
        return false;
    }
    if contains_word_ci(l, "gains")
        && !contains_word_ci(r, "you ")
        && !starts_with_word_ci(r, "create")
        && !starts_with_word_ci(r, "draw")
        && !starts_with_word_ci(r, "gain")
    {
        return false;
    }
    if (contains_word_ci(l, "gets") || contains_word_ci(l, "get"))
        && starts_with_word_ci(r, "gain")
        && !starts_with_word_ci(r, "gain control")
        && !contains_word_ci(r, "life")
    {
        return false;
    }
    if starts_with_word_ci(l, "search")
        && !starts_with_word_ci(r, "you")
        && !starts_with_word_ci(r, "create")
        && !starts_with_word_ci(r, "draw")
    {
        return false;
    }
    if starts_with_word_ci(l, "reveal")
        && (starts_with_word_ci(r, "put") || starts_with_word_ci(r, "exile"))
    {
        return false;
    }
    if starts_with_word_ci(l, "look")
        && (starts_with_word_ci(r, "put") || starts_with_word_ci(r, "exile"))
    {
        return false;
    }
    if starts_with_word_ci(l, "create")
        && (starts_with_word_ci(r, "a")
            || starts_with_word_ci(r, "an")
            || starts_with_word_ci(r, "x")
            || parse_number_token(r).is_some())
    {
        return false;
    }
    if (starts_with_word_ci(r, "shuffles") || starts_with_word_ci(r, "shuffle"))
        && (contains_word_ci(l, "search")
            || contains_word_ci(l, "library")
            || contains_word_ci(l, "graveyard"))
    {
        return false;
    }
    // Allow split when right begins with an unambiguous second action verb/clause
    const SPLIT_RIGHT_STARTS: &[&str] = &[
        "you gain",
        "you lose",
        "you draw",
        "you discard",
        "you mill",
        "you scry",
        "you surveil",
        "you create",
        "you sacrifice",
        "you untap",
        "you tap",
        "you return",
        "you destroy",
        "you exile",
        "you may",
        "draw ",
        "scry ",
        "surveil ",
        "investigate",
        "proliferate",
        "gain ",
        "lose ",
        "mill ",
        "discard ",
        "create ",
        "destroy ",
        "exile ",
        "tap ",
        "untap ",
        "return ",
        "sacrifice ",
        "put ",
        "each ",
        "that player ",
        "they ",
        "then ",
        "add ",
        "populate",
        "explore",
        "connive",
        "blight",
        "endure",
        "forage",
        "attach ",
    ];
    SPLIT_RIGHT_STARTS.iter().any(|p| {
        r.as_bytes()
            .get(..p.len())
            .is_some_and(|b| b.eq_ignore_ascii_case(p.as_bytes()))
    })
}

fn parse_number_token(s: &str) -> Option<i32> {
    let w = s.split_whitespace().next()?;
    parse_small_number(w)
}

fn parse_amount_str(
    s: &str,
    ctx: &mut ParseCtx<'_>,
    scope: &mut dyn ParserScope,
) -> Option<Amount> {
    let t = trim_trailing_period(s);
    if t.is_empty() {
        return None;
    }
    let toks = tokenize(t, 0);
    if toks.is_empty() {
        return None;
    }
    let cp = ctx.interner.checkpoint();
    let tlen = scope.prior_targets_len();
    if let Some((amt, used)) = parse_amount(&toks, ctx, scope)
        && used == toks.len()
    {
        return Some(amt);
    }
    scope.truncate_targets(tlen);
    ctx.interner.rollback(cp);
    if let Some(a) = parse_wave_amount_str(t, ctx, scope) {
        return Some(a);
    }
    scope.truncate_targets(tlen);
    if let Some(p) = find_word_ci(t, " plus ") {
        let lhs = t[..p].trim();
        let rhs = t[p + " plus ".len()..].trim();
        if let Some(a1) = parse_amount_str(lhs, ctx, scope)
            && let Some(a2) = parse_amount_str(rhs, ctx, scope)
        {
            return Some(Amount::Sum { args: vec![a1, a2] });
        }
        scope.truncate_targets(tlen);
    }
    None
}

fn parse_condition_str(
    s: &str,
    ctx: &mut ParseCtx<'_>,
    scope: &mut dyn ParserScope,
) -> Option<Condition> {
    let t = trim_trailing_period(s);
    if t.is_empty() {
        return None;
    }
    let toks = tokenize(t, 0);
    if toks.is_empty() {
        return None;
    }
    let cp = ctx.interner.checkpoint();
    let tlen = scope.prior_targets_len();
    if let Some((cond, used)) = parse_condition(&toks, ctx, scope)
        && used == toks.len()
    {
        return Some(cond);
    }
    scope.truncate_targets(tlen);
    ctx.interner.rollback(cp);
    if let Some(c) = parse_wave_condition_str(t, ctx, scope) {
        return Some(c);
    }
    scope.truncate_targets(tlen);
    let body = strip_prefix_word_ci(t, "if").unwrap_or(t);
    if let Some(or_pos) = find_word_ci(body, " or ") {
        let lhs = body[..or_pos].trim();
        let rhs = body[or_pos + " or ".len()..].trim();
        if let Some(c1) = parse_condition_str(lhs, ctx, scope)
            && let Some(c2) = parse_condition_str(rhs, ctx, scope)
        {
            return Some(Condition::Or { of: vec![c1, c2] });
        }
        scope.truncate_targets(tlen);
    }
    None
}

fn parse_duration_suffix(s: &str) -> (&str, Option<Duration>) {
    let t = trim_trailing_period(s);
    let suffixes: &[(&str, Duration)] = &[
        ("until end of turn", Duration::EndOfTurn),
        ("this turn", Duration::EndOfTurn),
        ("until your next turn", Duration::UntilYourNextTurn),
        ("until end of combat", Duration::UntilEndOfCombat),
        (
            "until end of your next turn",
            Duration::UntilEndOfYourNextTurn,
        ),
        (
            "for as long as you control ~",
            Duration::ForAsLongAsYouControlSelf,
        ),
        (
            "for as long as ~ remains on the battlefield",
            Duration::ForAsLongAsYouControlSelf,
        ),
        (
            "for as long as ~ remains tapped",
            Duration::ForAsLongAsSelfRemainsTapped,
        ),
    ];
    for (suf, dur) in suffixes {
        if let Some(prefix) = strip_suffix_word_ci(t, suf) {
            let p = prefix.trim_end_matches(',').trim();
            return (p, Some(*dur));
        }
    }
    (t, None)
}

fn parse_duration_prefix(s: &str) -> (Option<Duration>, &str) {
    let t = s.trim();
    let prefixes: &[(&str, Duration)] = &[
        ("until end of turn,", Duration::EndOfTurn),
        ("until your next turn,", Duration::UntilYourNextTurn),
        ("until end of combat,", Duration::UntilEndOfCombat),
        (
            "for as long as ~ remains on the battlefield,",
            Duration::ForAsLongAsYouControlSelf,
        ),
        (
            "for as long as this creature remains on the battlefield,",
            Duration::ForAsLongAsYouControlSelf,
        ),
        (
            "for as long as this permanent remains on the battlefield,",
            Duration::ForAsLongAsYouControlSelf,
        ),
        (
            "for as long as it remains on the battlefield,",
            Duration::ForAsLongAsYouControlSelf,
        ),
        (
            "for as long as you control ~,",
            Duration::ForAsLongAsYouControlSelf,
        ),
    ];
    for (pre, dur) in prefixes {
        if t.len() >= pre.len()
            && t.is_char_boundary(pre.len())
            && t[..pre.len()].eq_ignore_ascii_case(pre)
        {
            return (Some(*dur), t[pre.len()..].trim_start());
        }
    }
    (None, t)
}

fn parse_mana_color_char(c: char) -> Option<ManaColor> {
    match c.to_ascii_uppercase() {
        'W' => Some(ManaColor::W),
        'U' => Some(ManaColor::U),
        'B' => Some(ManaColor::B),
        'R' => Some(ManaColor::R),
        'G' => Some(ManaColor::G),
        'C' => Some(ManaColor::C),
        _ => None,
    }
}

fn mana_color_to_mask(c: ManaColor) -> ColorMask {
    match c {
        ManaColor::W => ColorMask::W,
        ManaColor::U => ColorMask::U,
        ManaColor::B => ColorMask::B,
        ManaColor::R => ColorMask::R,
        ManaColor::G => ColorMask::G,
        ManaColor::C => ColorMask::C,
    }
}

fn parse_mana_pip_sequence(s: &str) -> Option<Vec<ManaColor>> {
    let t = s.trim();
    if t.is_empty() {
        return None;
    }
    let bytes = t.as_bytes();
    let mut i = 0;
    let mut out = Vec::new();
    while i < bytes.len() {
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }
        if bytes[i] != b'{' {
            return None;
        }
        let close = t[i..].find('}')?;
        let inner = &t[i + 1..i + close];
        if inner.len() != 1 {
            return None;
        }
        let mc = parse_mana_color_char(inner.chars().next()?)?;
        out.push(mc);
        i += close + 1;
    }
    if out.is_empty() { None } else { Some(out) }
}

fn parse_color_list_str(s: &str) -> ColorMask {
    let mut mask = ColorMask::empty();
    for raw_part in s.split(|c: char| c == ',' || c.is_ascii_whitespace()) {
        let w = raw_part.trim();
        if w.is_empty() || eq_ci(w, "and") || eq_ci(w, "or") || eq_ci(w, "and/or") {
            continue;
        }
        if let Some(cm) = parse_color_word(w) {
            mask |= cm;
        }
    }
    mask
}

fn parse_keyword_list_ids(raw: &str, ctx: &mut ParseCtx<'_>) -> Option<SmallVec<[KeywordId; 2]>> {
    let cleaned = raw.trim().replace(", and ", ", ").replace(" and ", ", ");
    let mut out = SmallVec::new();
    for part in cleaned.split(',') {
        let kw = trim_trailing_period(part).trim();
        if kw.is_empty() {
            continue;
        }
        if !is_grantable_or_wave_keyword(kw) {
            return None;
        }
        let canonical = canonical_keyword_case(kw);
        out.push(ctx.interner.intern_keyword(&canonical));
    }
    if out.is_empty() { None } else { Some(out) }
}

fn is_grantable_or_wave_keyword(kw: &str) -> bool {
    let low = kw.trim().to_ascii_lowercase();
    if GRANTABLE_KEYWORDS
        .iter()
        .any(|g| g.eq_ignore_ascii_case(&low))
        || is_known_keyword(&low)
    {
        return true;
    }
    // Parameterized keywords: "annihilator N", "firebending N", "crew N", "ward {N}", "protection from ..."
    if starts_with_word_ci(&low, "protection from ") {
        return true;
    }
    for prefix in [
        "annihilator ",
        "firebending ",
        "crew ",
        "afflict ",
        "absorb ",
        "bushido ",
        "frenzy ",
        "modular ",
        "poisonous ",
        "rampage ",
        "renown ",
        "toxic ",
    ] {
        if let Some(rest) = low.strip_prefix(prefix)
            && rest.trim().parse::<u32>().is_ok()
        {
            return true;
        }
    }
    low == "sunburst" || low == "annihilator" || low.starts_with("ward ")
}

fn canonical_keyword_case(kw: &str) -> String {
    let trimmed = kw.trim();
    for g in GRANTABLE_KEYWORDS {
        if g.eq_ignore_ascii_case(trimmed) {
            return (*g).to_string();
        }
    }
    let mut chars = trimmed.chars();
    match chars.next() {
        Some(first) => {
            let mut s = String::new();
            s.extend(first.to_uppercase());
            s.push_str(&chars.as_str().to_ascii_lowercase());
            s
        }
        None => String::new(),
    }
}

