fn find_predefined_token(name: &str) -> Option<&'static PredefinedTokenEntry> {
    let low = name.trim().to_ascii_lowercase();
    PREDEFINED_TOKENS.iter().find(|e| e.key == low)
}

fn build_predefined_token_spec(
    entry: &PredefinedTokenEntry,
    tapped: bool,
    ctx: &mut ParseCtx<'_>,
) -> TokenSpec {
    let mut kws = SmallVec::new();
    for k in entry.keywords {
        kws.push(ctx.interner.intern_keyword(k));
    }
    let subs = smallvec![ctx.interner.intern_subtype(entry.subtype)];
    TokenSpec {
        name: entry.name.to_string(),
        power: entry.power,
        toughness: entry.toughness,
        colors: entry.colors,
        types: entry.types,
        supertypes: SupertypeMask::empty(),
        subtypes: subs,
        type_line: entry.type_line.to_string(),
        keywords: kws,
        tapped,
        quoted_abilities: Vec::new(),
        legendary: false,
    }
}

#[allow(clippy::too_many_arguments)]
fn build_token_spec_from_desc(
    power: i32,
    toughness: i32,
    desc: &str,
    kw_raw: &str,
    extra_types: CardTypeMask,
    tapped: bool,
    legendary: bool,
    explicit_name: Option<&str>,
    quoted_abilities: Vec<String>,
    ctx: &mut ParseCtx<'_>,
) -> TokenSpec {
    let colors = parse_color_list_str(desc) & !ColorMask::C;
    let mut subtypes = SmallVec::new();
    let mut sub_names = Vec::new();
    for raw_w in desc.split_whitespace() {
        let w = raw_w.trim_matches(|c: char| c == ',');
        if w.is_empty()
            || parse_color_word(w).is_some()
            || eq_ci(w, "and")
            || eq_ci(w, "or")
            || eq_ci(w, "artifact")
            || eq_ci(w, "enchantment")
            || eq_ci(w, "creature")
        {
            continue;
        }
        let st = singular_subtype(w).unwrap_or_else(|| canonical_keyword_case(w));
        subtypes.push(ctx.interner.intern_subtype(&st));
        sub_names.push(st);
    }
    if sub_names.is_empty() {
        sub_names.push("Spirit".to_string());
        subtypes.push(ctx.interner.intern_subtype("Spirit"));
    }
    let sub_line = sub_names.join(" ");
    let mut types = extra_types;
    if types.is_empty() {
        types = CardTypeMask::CREATURE;
    }
    let mut tl = String::from("Token");
    if legendary {
        tl.push_str(" Legendary");
    }
    if types.contains(CardTypeMask::ARTIFACT) {
        tl.push_str(" Artifact");
    }
    if types.contains(CardTypeMask::ENCHANTMENT) {
        tl.push_str(" Enchantment");
    }
    if types.contains(CardTypeMask::CREATURE) {
        tl.push_str(" Creature");
    }
    tl.push_str(" — ");
    tl.push_str(&sub_line);

    let keywords = if kw_raw.trim().is_empty() {
        SmallVec::new()
    } else {
        parse_keyword_list_ids(kw_raw, ctx)
            .map(|v| {
                let mut sv = SmallVec::new();
                for id in v {
                    sv.push(id);
                }
                sv
            })
            .unwrap_or_default()
    };

    let name = explicit_name
        .map(str::to_string)
        .unwrap_or_else(|| format!("{sub_line} Token"));

    TokenSpec {
        name,
        power,
        toughness,
        colors,
        types,
        supertypes: if legendary {
            SupertypeMask::LEGENDARY
        } else {
            SupertypeMask::empty()
        },
        subtypes,
        type_line: tl,
        keywords,
        tapped,
        quoted_abilities,
        legendary,
    }
}

pub(crate) fn parse_static_extra_token(phrase: &str, ctx: &mut ParseCtx<'_>) -> Option<TokenSpec> {
    let mut s = phrase.trim();
    s = strip_prefix_word_ci(s, "that many")
        .or_else(|| strip_prefix_word_ci(s, "a"))
        .or_else(|| strip_prefix_word_ci(s, "an"))
        .unwrap_or(s)
        .trim();
    let tok_desc =
        strip_suffix_word_ci(s, "tokens").or_else(|| strip_suffix_word_ci(s, "token"))?;
    let mut spec = if let Some(pre) = find_predefined_token(tok_desc) {
        let mut sp = build_predefined_token_spec(pre, false, ctx);
        if pre.key == "mutagen" {
            sp.quoted_abilities.push(
                "{1}, {T}, Sacrifice this token: Put a +1/+1 counter on target creature. Activate only as a sorcery.".to_string(),
            );
        }
        sp
    } else {
        let first_tok = tok_desc.split_whitespace().next()?;
        let (p_str, t_str) = first_tok.split_once('/')?;
        let pw = p_str.parse::<i32>().ok()?;
        let tg = t_str.parse::<i32>().ok()?;
        let desc_after_pt = tok_desc[first_tok.len()..].trim();
        let mut extra_types = CardTypeMask::empty();
        if contains_word_ci(desc_after_pt, "artifact") {
            extra_types |= CardTypeMask::ARTIFACT;
        }
        if contains_word_ci(desc_after_pt, "enchantment") {
            extra_types |= CardTypeMask::ENCHANTMENT;
        }
        if contains_word_ci(desc_after_pt, "creature") {
            extra_types |= CardTypeMask::CREATURE;
        }
        build_token_spec_from_desc(
            pw,
            tg,
            desc_after_pt,
            "",
            extra_types,
            false,
            false,
            None,
            Vec::new(),
            ctx,
        )
    };
    if let Some(stripped) = spec.name.strip_suffix(" Token") {
        spec.name = stripped.to_string();
    }
    if let Some(stripped) = spec.type_line.strip_prefix("Token ") {
        spec.type_line = stripped.to_string();
    }
    Some(spec)
}

fn parse_role_token_kind(s: &str) -> Option<RoleTokenKind> {
    let t = trim_trailing_period(s);
    let body =
        strip_prefix_word_ci(t, "create a").or_else(|| strip_prefix_word_ci(t, "create an"))?;
    let name = strip_suffix_word_ci(body, "role token")?;
    if eq_ci(name, "cursed") {
        Some(RoleTokenKind::Cursed)
    } else if eq_ci(name, "monster") {
        Some(RoleTokenKind::Monster)
    } else if eq_ci(name, "royal") {
        Some(RoleTokenKind::Royal)
    } else if eq_ci(name, "sorcerer") {
        Some(RoleTokenKind::Sorcerer)
    } else if eq_ci(name, "virtuous") {
        Some(RoleTokenKind::Virtuous)
    } else if eq_ci(name, "wicked") {
        Some(RoleTokenKind::Wicked)
    } else if eq_ci(name, "young hero") {
        Some(RoleTokenKind::YoungHero)
    } else {
        None
    }
}

enum ParsedObj {
    SelfObj,
    AttachedTo,
    EventObject,
    Target(u16),
    All(ObjectFilter),
    Binding(String),
}

impl ParsedObj {
    fn into_selector(self) -> Selector {
        match self {
            ParsedObj::SelfObj => Selector::SelfObj,
            ParsedObj::AttachedTo => Selector::AttachedTo,
            ParsedObj::EventObject => Selector::EventObject,
            ParsedObj::Target(index) => Selector::Target { index },
            ParsedObj::All(filter) => Selector::All {
                filter: Box::new(filter),
            },
            ParsedObj::Binding(name) => Selector::Binding { name },
        }
    }
}

fn parse_object_selector(
    phrase: &str,
    default_zone: ZoneMask,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> Option<ParsedObj> {
    let t = trim_trailing_period(phrase);
    if t.is_empty() {
        return None;
    }
    if eq_ci(t, "~")
        || eq_ci(t, "this spell")
        || eq_ci(t, "this card")
        || eq_ci(t, "this permanent")
        || eq_ci(t, "this creature")
        || eq_ci(t, "this equipment")
        || eq_ci(t, "this aura")
        || eq_ci(t, "this artifact")
        || eq_ci(t, "this enchantment")
        || eq_ci(t, "this land")
        || eq_ci(t, "this planeswalker")
        || eq_ci(t, "this vehicle")
        || eq_ci(t, "this saga")
        || eq_ci(t, "this room")
        || eq_ci(t, "this battle")
        || eq_ci(t, "this class")
        || eq_ci(t, "this case")
    {
        return Some(ParsedObj::SelfObj);
    }
    if eq_ci(t, "enchanted creature")
        || eq_ci(t, "equipped creature")
        || eq_ci(t, "enchanted permanent")
        || eq_ci(t, "attached creature")
        || eq_ci(t, "enchanted land")
        || eq_ci(t, "enchanted artifact")
    {
        return Some(ParsedObj::AttachedTo);
    }
    if eq_ci(t, "it")
        || eq_ci(t, "them")
        || eq_ci(t, "they")
        || (eq_ci(t, "each of them") && state.last_object.is_some())
    {
        if let Some((r, _)) = &state.last_object {
            return match r {
                Ref::SelfObj => Some(ParsedObj::SelfObj),
                Ref::AttachedTo => Some(ParsedObj::AttachedTo),
                Ref::EventObject => Some(ParsedObj::EventObject),
                Ref::Target { index } => Some(ParsedObj::Target(*index)),
                Ref::Binding { name } => Some(ParsedObj::Binding(name.clone())),
                _ => Some(ParsedObj::SelfObj),
            };
        }
        return match state.pronoun_subject {
            PronounSubject::AttachedTo => {
                if state.in_trigger_context() && state.trigger_is_ltb() {
                    Some(ParsedObj::EventObject)
                } else {
                    Some(ParsedObj::AttachedTo)
                }
            }
            PronounSubject::SelfObj => {
                let cast_targets_self = state.trigger.is_some_and(|tr| {
                    matches!(tr.event, EventKind::Cast)
                        && matches!(
                            &tr.filter.object,
                            Some(TriggerSubject::Filter { filter })
                                if filter.extra.iter().any(|p| matches!(
                                    p,
                                    ObjectPredicate::TargetsFilter { .. }
                                        | ObjectPredicate::SingleTargetFilter { .. }
                                ))
                        )
                });
                if state.in_trigger_context()
                    && !matches!(
                        state.trigger.map(|tr| tr.event),
                        Some(EventKind::StateTriggered)
                    )
                    && !cast_targets_self
                    && (!state.trigger_targets_self() || state.trigger_is_ltb())
                {
                    Some(ParsedObj::EventObject)
                } else {
                    Some(ParsedObj::SelfObj)
                }
            }
        };
    }
    if eq_ci(t, "the exiled card") || eq_ci(t, "the exiled cards") {
        if let Some(b) = state.parent_exile_bindings.last() {
            return Some(ParsedObj::Binding(b.clone()));
        }
        if let Some(b) = state.steps.iter().rev().find_map(|s| {
            if matches!(s.op, EffectOp::Exile { .. }) {
                s.bind_as.clone()
            } else {
                None
            }
        }) {
            return Some(ParsedObj::Binding(b));
        }
    }
    if eq_ci(t, "the token") || eq_ci(t, "the tokens") {
        if let Some((r, step_idx)) = &state.last_object
            && state.steps.get(*step_idx).is_some_and(|s| {
                matches!(
                    s.op,
                    EffectOp::CreateToken { .. } | EffectOp::CopyPermanent { .. }
                )
            })
        {
            return match r {
                Ref::SelfObj => Some(ParsedObj::SelfObj),
                Ref::AttachedTo => Some(ParsedObj::AttachedTo),
                Ref::EventObject => Some(ParsedObj::EventObject),
                Ref::Target { index } => Some(ParsedObj::Target(*index)),
                Ref::Binding { name } => Some(ParsedObj::Binding(name.clone())),
                _ => Some(ParsedObj::EventObject),
            };
        }
        if let Some(b) = state.steps.iter().rev().find_map(|s| {
            if matches!(
                s.op,
                EffectOp::CreateToken { .. } | EffectOp::CopyPermanent { .. }
            ) {
                s.bind_as.clone()
            } else {
                None
            }
        }) {
            return Some(ParsedObj::Binding(b));
        }
    }
    if eq_ci(t, "the chosen creature")
        || eq_ci(t, "the chosen creatures")
        || eq_ci(t, "the chosen card")
        || eq_ci(t, "the chosen cards")
        || eq_ci(t, "the chosen permanent")
        || eq_ci(t, "the chosen permanents")
    {
        if let Some((Ref::Binding { name }, _)) = &state.last_object {
            return Some(ParsedObj::Binding(name.clone()));
        }
        if let Some(b) = state.steps.iter().rev().find_map(|s| {
            if matches!(
                s.op,
                EffectOp::ForEachPlayerLoop {
                    choose_object_to_bind: Some(_),
                    ..
                }
            ) {
                s.bind_as.clone()
            } else {
                None
            }
        }) {
            return Some(ParsedObj::Binding(b));
        }
    }
    let that_subj = strip_prefix_word_ci(t, "each of").unwrap_or(t);
    if let Some(noun_raw) =
        strip_prefix_word_ci(that_subj, "that").or_else(|| strip_prefix_word_ci(that_subj, "those"))
        && (eq_ci(noun_raw, "creature")
            || eq_ci(noun_raw, "permanent")
            || eq_ci(noun_raw, "spell")
            || eq_ci(noun_raw, "card")
            || eq_ci(noun_raw, "creatures")
            || eq_ci(noun_raw, "cards")
            || eq_ci(noun_raw, "permanents")
            || eq_ci(noun_raw, "artifact")
            || eq_ci(noun_raw, "enchantment")
            || eq_ci(noun_raw, "land")
            || eq_ci(noun_raw, "token")
            || eq_ci(noun_raw, "tokens"))
    {
        if eq_ci(noun_raw, "creatures")
            && state.trigger.is_some_and(|tr| {
                tr.event == EventKind::Attacks
                    && tr.filter.one_or_more
                    && tr.filter.player.is_none()
            })
        {
            return Some(ParsedObj::All(ObjectFilter {
                zones: ZoneMask::BATTLEFIELD,
                types_any: CardTypeMask::CREATURE,
                flags: FilterFlags::ATTACKING,
                ..Default::default()
            }));
        }
        if let Some((r, step_idx)) = &state.last_object {
            if matches!(r, Ref::SelfObj)
                && let Some(tidx) = state.steps.iter().rev().find_map(|s| {
                    if let EffectOp::BecomeCopy { copy_source, .. } = &s.op
                        && let Selector::Target { index } = **copy_source
                    {
                        Some(index)
                    } else {
                        None
                    }
                })
            {
                return Some(ParsedObj::Target(tidx));
            }
            let noun_sing = noun_raw.trim_end_matches('s');
            if (matches!(r, Ref::SelfObj | Ref::AttachedTo)
                || (matches!(r, Ref::Binding { .. })
                    && !eq_ci(noun_sing, "card")
                    && state.steps.get(*step_idx).is_some_and(|s| {
                        matches!(
                            s.op,
                            EffectOp::Discard { .. } | EffectOp::Draw { .. } | EffectOp::Mill
                        )
                    })))
                && state.in_trigger_context()
                && state.trigger_matches_that_noun(noun_sing)
            {
                return Some(ParsedObj::EventObject);
            }
            return match r {
                Ref::SelfObj => Some(ParsedObj::SelfObj),
                Ref::AttachedTo => Some(ParsedObj::AttachedTo),
                Ref::EventObject => Some(ParsedObj::EventObject),
                Ref::Target { index } => Some(ParsedObj::Target(*index)),
                Ref::Binding { name } => Some(ParsedObj::Binding(name.clone())),
                _ => Some(ParsedObj::EventObject),
            };
        }
        if state.in_trigger_context() {
            return Some(ParsedObj::EventObject);
        }
    } else if eq_ci(t, "each of them") {
        if let Some((r, _)) = &state.last_object {
            return match r {
                Ref::SelfObj => Some(ParsedObj::SelfObj),
                Ref::AttachedTo => Some(ParsedObj::AttachedTo),
                Ref::EventObject => Some(ParsedObj::EventObject),
                Ref::Target { index } => Some(ParsedObj::Target(*index)),
                Ref::Binding { name } => Some(ParsedObj::Binding(name.clone())),
                _ => Some(ParsedObj::EventObject),
            };
        }
        if state.in_trigger_context() {
            return Some(ParsedObj::EventObject);
        }
    }
    if strip_suffix_word_ci(t, "chosen this way").is_some()
        && let Some((Ref::Binding { name }, _)) = &state.last_object
        && name == "chosen_by_loop"
    {
        return Some(ParsedObj::Binding(name.clone()));
    }

    if let Some((base_s, rel)) = strip_suffix_word_ci(t, "target player controls")
        .map(|b| (b, PlayerRelation::Any))
        .or_else(|| {
            strip_suffix_word_ci(t, "target opponent controls")
                .map(|b| (b, PlayerRelation::Opponent))
        })
    {
        let cp = ctx.interner.checkpoint();
        let targets_cp = state.targets.len();
        if let Some(ParsedObj::All(mut f)) =
            parse_object_selector(base_s.trim(), default_zone, ctx, state)
        {
            let pidx = state.add_target(TargetSpec {
                kind: TargetKind::Player,
                player: Some(PlayerFilter { relation: rel }),
                min: 1,
                max: 1,
                ..default_target_spec()
            });
            let pref = PlayerRef::Target { index: pidx };
            state.last_player = Some(Selector::Target { index: pidx });
            f.extra
                .push(ObjectPredicate::ControllerRef { player: pref });
            return Some(ParsedObj::All(f));
        }
        ctx.interner.rollback(cp);
        state.targets.truncate(targets_cp);
    }

    let toks = tokenize(t, 0);
    if toks.is_empty() {
        return None;
    }
    let has_each_of = strip_prefix_word_ci(t, "each of")
        .filter(|_| toks.len() >= 3 && toks[0].eq_ci("each") && toks[1].eq_ci("of"));
    let (target_src, target_toks) = if let Some(rest) = has_each_of {
        (rest, &toks[2..])
    } else {
        (t, toks.as_slice())
    };

    // Try target spec first when phrase contains target / targets
    if target_toks
        .iter()
        .any(|tk| tk.eq_ci("target") || tk.eq_ci("targets"))
    {
        let cp = ctx.interner.checkpoint();
        let targets_cp = state.targets.len();
        if let Some((mut spec, used)) = parse_target_spec(target_toks, ctx, state)
            && used == target_toks.len()
        {
            if (spec.filter.zones == ZoneMask::BATTLEFIELD
                && default_zone != ZoneMask::BATTLEFIELD
                && !contains_word_ci(target_src, "battlefield"))
                || (spec.filter.zones.is_empty() && spec.zones.is_empty())
            {
                spec.filter.zones = default_zone;
            }
            let idx = state.add_target(spec);
            return Some(ParsedObj::Target(idx));
        }
        ctx.interner.rollback(cp);
        state.targets.truncate(targets_cp);
    }

    // Strip leading "each " / "all " for filter parsing
    let opts = FilterOpts {
        default_zone,
        allow_plural_and_disjunction: true,
        allow_spell_noun: default_zone == ZoneMask::STACK,
        strip_trailing_card: default_zone != ZoneMask::BATTLEFIELD,
        expand_outlaw_subtypes: false,
    };
    let ftoks_owned;
    let ftoks_opt: Option<&[_]> = if has_each_of.is_some() {
        Some(&toks[2..])
    } else if let Some(fp) = strip_prefix_word_ci(t, "each of") {
        ftoks_owned = tokenize(fp, 0);
        Some(ftoks_owned.as_slice())
    } else if let Some(fp) =
        strip_prefix_word_ci(t, "each").or_else(|| strip_prefix_word_ci(t, "all"))
    {
        if toks.len() >= 2 && (toks[0].eq_ci("each") || toks[0].eq_ci("all")) {
            Some(&toks[1..])
        } else {
            ftoks_owned = tokenize(fp, 0);
            Some(ftoks_owned.as_slice())
        }
    } else {
        None
    };
    if let Some(ftoks) = ftoks_opt {
        let cp2 = ctx.interner.checkpoint();
        if let Some((mut f, used)) = parse_object_filter(ftoks, ctx, opts, state)
            && used == ftoks.len()
        {
            if f.zones.is_empty() {
                f.zones = default_zone;
            }
            return Some(ParsedObj::All(f));
        }
        ctx.interner.rollback(cp2);
    }

    if eq_ci(t, "your commander") {
        return Some(ParsedObj::All(ObjectFilter {
            zones: default_zone,
            owner: Some(RelativeControl::You),
            flags: FilterFlags::IS_COMMANDER,
            ..Default::default()
        }));
    }

    if let Some(pos) = find_word_ci(t, " and each ")
        && let Some(lhs) = strip_prefix_word_ci(t[..pos].trim(), "each")
    {
        let rhs = t[pos + " and each ".len()..].trim();
        let combined = format!("{lhs} and {rhs}");
        let ctoks = tokenize(&combined, 0);
        let cp = ctx.interner.checkpoint();
        if !ctoks.is_empty()
            && let Some((mut f, used)) = parse_object_filter(
                &ctoks,
                ctx,
                FilterOpts {
                    default_zone,
                    allow_plural_and_disjunction: true,
                    allow_spell_noun: default_zone == ZoneMask::STACK,
                    strip_trailing_card: default_zone != ZoneMask::BATTLEFIELD,
                    expand_outlaw_subtypes: false,
                },
                state,
            )
            && used == ctoks.len()
        {
            if f.zones.is_empty() {
                f.zones = default_zone;
            }
            return Some(ParsedObj::All(f));
        }
        ctx.interner.rollback(cp);
    }

    let cp3 = ctx.interner.checkpoint();
    if let Some((mut f, used)) = parse_object_filter(&toks, ctx, opts, state)
        && used == toks.len()
    {
        if f.zones.is_empty() {
            f.zones = default_zone;
        }
        return Some(ParsedObj::All(f));
    }
    ctx.interner.rollback(cp3);
    None
}

fn parse_player_selector(
    phrase: &str,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> Option<Selector> {
    let t = trim_trailing_period(phrase);
    if t.is_empty() || t == "~" {
        return None;
    }
    if eq_ci(t, "you") {
        return Some(you_sel());
    }
    if eq_ci(t, "each player") || eq_ci(t, "all players") {
        return Some(Selector::Player {
            filter: PlayerFilter {
                relation: PlayerRelation::EachPlayer,
            },
        });
    }
    if eq_ci(t, "each opponent") || eq_ci(t, "each of your opponents") {
        return Some(Selector::Player {
            filter: PlayerFilter {
                relation: PlayerRelation::EachOpponent,
            },
        });
    }
    if eq_ci(t, "each other player") {
        return Some(Selector::Player {
            filter: PlayerFilter {
                relation: PlayerRelation::EachOpponent,
            },
        });
    }
    if eq_ci(t, "defending player") {
        return Some(Selector::PlayerRef {
            player: PlayerRef::DefendingPlayer,
        });
    }
    if eq_ci(t, "that player") || eq_ci(t, "that opponent") || eq_ci(t, "they") {
        if let Some(pref) = state.last_player_ref() {
            return Some(Selector::PlayerRef { player: pref });
        }
        if state.is_each_loop {
            return Some(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            });
        }
        if !state.in_trigger_context()
            && let Some(idx) = state
                .targets
                .iter()
                .rposition(|tgt| tgt.kind == TargetKind::Player)
        {
            return Some(Selector::PlayerRef {
                player: PlayerRef::Target { index: idx as u16 },
            });
        }
        if let Some((r @ (Ref::Target { .. } | Ref::Binding { .. }), _)) = &state.last_object
            && (!state.in_trigger_context()
                || state
                    .trigger
                    .is_none_or(|tr| tr.filter.player.is_none() && tr.scope.is_none()))
        {
            return Some(Selector::PlayerRef {
                player: PlayerRef::ControllerOf {
                    of: Box::new(r.clone()),
                },
            });
        }
        if state.in_trigger_context() {
            return Some(Selector::PlayerRef {
                player: PlayerRef::EventPlayer,
            });
        }
    }
    if eq_ci(t, "its controller")
        || eq_ci(t, "their controller")
        || eq_ci(t, "that creature's controller")
        || eq_ci(t, "that permanent's controller")
        || eq_ci(t, "that artifact's controller")
        || eq_ci(t, "that enchantment's controller")
        || eq_ci(t, "that land's controller")
        || eq_ci(t, "that card's controller")
        || eq_ci(t, "that spell's controller")
    {
        if let Some((r, _)) = &state.last_object {
            let sel = Selector::PlayerRef {
                player: PlayerRef::ControllerOf {
                    of: Box::new(r.clone()),
                },
            };
            state.set_last_player_from_selector(&sel);
            return Some(sel);
        }
        if state.in_trigger_context() {
            let sel = Selector::PlayerRef {
                player: PlayerRef::ControllerOf {
                    of: Box::new(Ref::EventObject),
                },
            };
            state.set_last_player_from_selector(&sel);
            return Some(sel);
        }
    }
    if eq_ci(t, "that player or that planeswalker's controller")
        || eq_ci(t, "its controller or the controller of that planeswalker")
    {
        let idx = state
            .targets
            .iter()
            .rposition(|sp| sp.kind == TargetKind::ObjectOrPlayer)
            .unwrap_or(0) as u16;
        let sel = Selector::PlayerRef {
            player: PlayerRef::ControllerOrControllerOfPlaneswalker { target_index: idx },
        };
        state.set_last_player_from_selector(&sel);
        return Some(sel);
    }
    if t.len() > "'s controller".len()
        && t.is_char_boundary(t.len() - "'s controller".len())
        && t[t.len() - "'s controller".len()..].eq_ignore_ascii_case("'s controller")
        && starts_with_word_ci(t[..t.len() - "'s controller".len()].trim(), "target")
    {
        let obj_s = t[..t.len() - "'s controller".len()].trim();
        let dz = if contains_word_ci(obj_s, "spell") {
            ZoneMask::STACK
        } else {
            ZoneMask::BATTLEFIELD
        };
        if let Some(ParsedObj::Target(idx)) = parse_object_selector(obj_s, dz, ctx, state) {
            let tref = Ref::Target { index: idx };
            state.last_object = Some((tref.clone(), state.steps.len()));
            let sel = Selector::PlayerRef {
                player: PlayerRef::ControllerOf { of: Box::new(tref) },
            };
            state.set_last_player_from_selector(&sel);
            return Some(sel);
        }
    }
    if eq_ci(t, "its owner")
        || eq_ci(t, "their owner")
        || eq_ci(t, "that creature's owner")
        || eq_ci(t, "that permanent's owner")
        || eq_ci(t, "that card's owner")
    {
        if let Some((r, _)) = &state.last_object {
            let sel = Selector::PlayerRef {
                player: PlayerRef::OwnerOf {
                    of: Box::new(r.clone()),
                },
            };
            state.set_last_player_from_selector(&sel);
            return Some(sel);
        }
        if state.in_trigger_context() {
            let sel = Selector::PlayerRef {
                player: PlayerRef::OwnerOf {
                    of: Box::new(Ref::EventObject),
                },
            };
            state.set_last_player_from_selector(&sel);
            return Some(sel);
        }
    }
    if eq_ci(t, "the player to your right") {
        let sel = Selector::PlayerRef {
            player: PlayerRef::PlayerToYourRight,
        };
        state.set_last_player_from_selector(&sel);
        return Some(sel);
    }
    if eq_ci(t, "the exiled card's owner") && state.in_trigger_context() && state.it_ref().is_none()
    {
        let sel = Selector::PlayerRef {
            player: PlayerRef::OwnerOf {
                of: Box::new(Ref::LinkedExile),
            },
        };
        state.set_last_player_from_selector(&sel);
        return Some(sel);
    }
    if (eq_ci(t, "the chosen player") || eq_ci(t, "the chosen opponent"))
        && let Some(lp) = &state.last_player
    {
        return Some(lp.clone());
    }
    if eq_ci(t, "any number of target players") || eq_ci(t, "any number of target opponents") {
        let rel = if eq_ci(t, "any number of target opponents") {
            PlayerRelation::Opponent
        } else {
            PlayerRelation::Any
        };
        let mut sp = default_target_spec();
        sp.kind = TargetKind::Player;
        sp.player = Some(PlayerFilter { relation: rel });
        sp.min = 0;
        sp.max = 99;
        let idx = state.add_target(sp);
        let sel = Selector::Target { index: idx };
        state.set_last_player_from_selector(&sel);
        return Some(sel);
    }
    {
        let (up_to, rem_p) = if let Some(r) = strip_prefix_word_ci(t, "up to") {
            (true, r)
        } else {
            (false, t)
        };
        if let Some((num_w, after_num)) = rem_p.split_once(char::is_whitespace)
            && let Some(n) = parse_small_number(num_w)
            && (eq_ci(after_num.trim(), "target players")
                || eq_ci(after_num.trim(), "target opponents"))
        {
            let rel = if contains_word_ci(after_num, "opponent") {
                PlayerRelation::Opponent
            } else {
                PlayerRelation::Any
            };
            let mut sp = default_target_spec();
            sp.kind = TargetKind::Player;
            sp.player = Some(PlayerFilter { relation: rel });
            sp.min = if up_to { 0 } else { n.max(1) as u16 };
            sp.max = n.max(1) as u16;
            let idx = state.add_target(sp);
            let sel = Selector::Target { index: idx };
            state.set_last_player_from_selector(&sel);
            return Some(sel);
        }
    }
    if eq_ci(t, "target player") || eq_ci(t, "target opponent") {
        let rel = if eq_ci(t, "target opponent") {
            PlayerRelation::Opponent
        } else {
            PlayerRelation::Any
        };
        let mut sp = default_target_spec();
        sp.kind = TargetKind::Player;
        sp.player = Some(PlayerFilter { relation: rel });
        let idx = state.add_target(sp);
        let sel = Selector::PlayerRef {
            player: PlayerRef::Target { index: idx },
        };
        state.set_last_player_from_selector(&sel);
        return Some(sel);
    }

    let toks = tokenize(t, 0);
    let tlen_pr = state.targets.len();
    if let Some((pref, used)) = parse_player_ref(&toks, state)
        && used == toks.len()
    {
        let sel = Selector::PlayerRef { player: pref };
        state.set_last_player_from_selector(&sel);
        return Some(sel);
    }
    state.targets.truncate(tlen_pr);
    if let Some((pf, used)) = parse_player_filter(&toks)
        && used == toks.len()
    {
        let sel = Selector::Player { filter: pf };
        state.set_last_player_from_selector(&sel);
        return Some(sel);
    }
    if toks
        .iter()
        .any(|tk| tk.eq_ci("target") || tk.eq_ci("targets"))
        && toks.iter().any(|tk| {
            tk.eq_ci("player")
                || tk.eq_ci("players")
                || tk.eq_ci("opponent")
                || tk.eq_ci("opponents")
                || tk.eq_ci("planeswalker")
                || tk.eq_ci("planeswalkers")
                || tk.eq_ci("any")
                || tk.eq_ci("targets")
        })
    {
        let cp = ctx.interner.checkpoint();
        let tlen = state.targets.len();
        if let Some((spec, used)) = parse_target_spec(&toks, ctx, state)
            && used == toks.len()
            && matches!(spec.kind, TargetKind::Player | TargetKind::ObjectOrPlayer)
        {
            let idx = state.add_target(spec);
            let sel = Selector::Target { index: idx };
            state.set_last_player_from_selector(&sel);
            return Some(sel);
        }
        ctx.interner.rollback(cp);
        state.targets.truncate(tlen);
    }
    None
}

fn parse_any_recipient_selector(
    phrase: &str,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> Option<Selector> {
    if let Some(p) = parse_player_selector(phrase, ctx, state) {
        return Some(p);
    }
    parse_object_selector(phrase, ZoneMask::BATTLEFIELD, ctx, state).map(ParsedObj::into_selector)
}

// ============================================================================
// Section 5: AddMana (All 8+ Precon Variants) & Token Creation
// ============================================================================

fn parse_mana_or_list(s: &str) -> Option<(Vec<ManaColor>, Vec<Vec<ManaColor>>)> {
    let t = s.trim().replace(", or ", " or ").replace(", ", " or ");
    let parts: Vec<&str> = t
        .split(" or ")
        .map(str::trim)
        .filter(|x| !x.is_empty())
        .collect();
    if parts.len() < 2 {
        return None;
    }
    let mut seqs = Vec::with_capacity(parts.len());
    for part in parts {
        seqs.push(parse_mana_pip_sequence(part)?);
    }
    let all_single = seqs.iter().all(|v| v.len() == 1);
    if all_single {
        let single_colors: Vec<ManaColor> = seqs.into_iter().map(|v| v[0]).collect();
        Some((single_colors, Vec::new()))
    } else {
        Some((Vec::new(), seqs))
    }
}

fn parse_mana_spending_restriction_full(
    raw: &str,
    ctx: &mut ParseCtx<'_>,
) -> Option<(
    Option<ManaRestrictionTag>,
    Option<Box<ManaSpendingRestriction>>,
)> {
    let t = trim_trailing_period(raw);
    if t.eq_ignore_ascii_case("this mana can't be spent to cast a nonartifact spell")
        || t.eq_ignore_ascii_case(
            "spend this mana only to cast artifact spells or activate abilities of artifacts",
        )
    {
        return Some((Some(ManaRestrictionTag::ArtifactSpellOrNonSpell), None));
    }
    if t.eq_ignore_ascii_case("this mana can't be spent to pay generic mana costs") {
        return Some((
            None,
            Some(Box::new(ManaSpendingRestriction {
                disallow_generic: true,
                ..Default::default()
            })),
        ));
    }
    if t.eq_ignore_ascii_case(
        "spend this mana only to cast a creature spell of the chosen type, and that spell can't be countered",
    ) {
        let f = mtg_ir::PlainManaFilter {
            types_any: CardTypeMask::CREATURE,
            of_chosen_type: true,
            ..Default::default()
        };
        return Some((
            None,
            Some(Box::new(ManaSpendingRestriction {
                allow_spells: Some(AllowSpellsRestriction {
                    filter: Some(f),
                    ..Default::default()
                }),
                on_spend_cant_be_countered: true,
                ..Default::default()
            })),
        ));
    }
    if t.eq_ignore_ascii_case(
        "spend this mana only to cast a creature spell of the chosen type or activate an ability of a creature source of the chosen type",
    ) {
        let pf = mtg_ir::PlainManaFilter {
            types_any: CardTypeMask::CREATURE,
            of_chosen_type: true,
            ..Default::default()
        };
        return Some((
            None,
            Some(Box::new(ManaSpendingRestriction {
                allow_spells: Some(AllowSpellsRestriction {
                    filter: Some(pf.clone()),
                    ..Default::default()
                }),
                allow_abilities: Some(AllowAbilitiesRestriction {
                    source_filter: Some(pf),
                    ..Default::default()
                }),
                ..Default::default()
            })),
        ));
    }
    if let Some(spec) = parse_mana_spending_restriction(t, ctx) {
        return Some((None, Some(Box::new(spec))));
    }
    None
}

fn parse_add_mana_sentence(
    raw: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let t = trim_trailing_period(raw);

    // 1. Follow-up mana riders & conditions attached to previous AddMana step(s)
    if eq_ci(
        t,
        "until end of turn, you don't lose this mana as steps and phases end",
    ) {
        let mut attached = false;
        for st in state.steps.iter_mut().rev() {
            if let EffectOp::AddMana {
                ref mut retain_until_eot,
                ..
            } = st.op
            {
                *retain_until_eot = true;
                attached = true;
            }
        }
        if attached {
            return true;
        }
    }

    if eq_ci(
        t,
        "if you spend this mana to cast your commander, it enters with a number of additional +1/+1 counters on it equal to the number of times it's been cast from the command zone this game",
    ) {
        let mut attached = false;
        for st in state.steps.iter_mut().rev() {
            if let EffectOp::AddMana {
                ref mut restriction_spec,
                ..
            } = st.op
            {
                let spec = restriction_spec
                    .get_or_insert_with(|| Box::new(ManaSpendingRestriction::default()));
                spec.on_spend_commander_bonus_counters = true;
                attached = true;
            } else {
                break;
            }
        }
        if attached {
            return true;
        }
    }

    if eq_ci(
        t,
        "if ~ has a +1/+1 counter on it, add three mana of that type instead",
    ) && let Some(prev) = state.steps.last_mut()
        && matches!(prev.op, EffectOp::AddMana { .. })
    {
        let ctr_id = ctx.interner.intern_counter("+1/+1");
        prev.amount = Some(Box::new(Amount::Conditional {
            condition: Box::new(Condition::SourceHasCounter {
                counter: ctr_id,
                min: Some(1),
            }),
            then_amt: Box::new(Amount::Const { n: 3 }),
            else_amt: Box::new(Amount::Const { n: 1 }),
        }));
        return true;
    }

    if let Some(rest) = strip_prefix_word_ci(t, "if you played a land this turn, add")
        && let Some(col_raw) = strip_suffix_word_ci(rest, "instead")
        && let Some(new_syms) = parse_mana_pip_sequence(col_raw)
        && let Some(prev) = state.steps.last_mut()
        && let EffectOp::AddMana {
            production: ManaProduction::Fixed { ref symbols },
            ..
        } = prev.op.clone()
    {
        let prev_span = prev.span;
        let orig_syms = symbols.clone();
        prev.gate = Some(StepGate::Condition {
            condition: Box::new(Condition::Not {
                of: Box::new(Condition::PlayedLandThisTurn),
            }),
        });
        prev.op = EffectOp::AddMana {
            production: ManaProduction::Fixed { symbols: orig_syms },
            restriction: None,
            restriction_spec: None,
            retain_until_eot: false,
            delayed_rider: None,
        };
        let mut s2 = make_step(
            EffectOp::AddMana {
                production: ManaProduction::Fixed {
                    symbols: SmallVec::from_vec(new_syms),
                },
                restriction: None,
                restriction_spec: None,
                retain_until_eot: false,
                delayed_rider: None,
            },
            you_sel(),
            Span {
                start: prev_span.start.max(span.start),
                end: span.end,
            },
        );
        s2.gate = Some(StepGate::Condition {
            condition: Box::new(Condition::PlayedLandThisTurn),
        });
        state.push_step(s2, false);
        return true;
    }

    if let Some((tag, spec)) = parse_mana_spending_restriction_full(t, ctx) {
        let mut attached = false;
        for st in state.steps.iter_mut().rev() {
            if let EffectOp::AddMana {
                ref mut restriction,
                ref mut restriction_spec,
                ..
            } = st.op
            {
                if tag.is_some() {
                    *restriction = tag;
                }
                if spec.is_some() {
                    *restriction_spec = spec.clone();
                }
                attached = true;
            }
        }
        if attached {
            return true;
        }
    }

    // Delayed mana rider: "When (you spend this|that) mana (is spent )?to cast <filter>, <effect>"
    if let Some(after_when) = strip_prefix_word_ci(t, "when you spend this mana to cast")
        .or_else(|| strip_prefix_word_ci(t, "when that mana is spent to cast"))
        && let Some((subj_part, eff_part)) = split_at_top_level_comma(after_when)
        && matches!(
            state.steps.last().map(|s| &s.op),
            Some(EffectOp::AddMana { .. })
        )
    {
        let sub_parse =
            state.parse_sub_effects(eff_part, span.start, AbilityContext::Triggered, ctx);
        if sub_parse.unparsed.is_empty() && !sub_parse.steps.is_empty() {
            let spell_word = strip_suffix_word_ci(subj_part, "spell").unwrap_or(subj_part);
            let obj_filter = parse_object_phrase(
                spell_word,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_spell_noun: true,
                    ..Default::default()
                },
            )
            .or_else(|| {
                parse_object_phrase(
                    subj_part,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::empty(),
                        allow_spell_noun: true,
                        ..Default::default()
                    },
                )
            });
            let mut tf = EventFilter::default();
            if let Some(f) = obj_filter {
                tf.object = Some(TriggerSubject::Filter {
                    filter: Box::new(f),
                });
            }
            if let Some(prev) = state.steps.last_mut()
                && let EffectOp::AddMana {
                    ref mut delayed_rider,
                    ..
                } = prev.op
            {
                *delayed_rider = Some(Box::new(DelayedTriggerPayload {
                    trigger: Box::new(TriggerDef {
                        event: EventKind::Cast,
                        filter: tf,
                        scope: None,
                        from_zones: None,
                        only_once_per_turn: false,
                        do_this_once_per_turn: false,
                        is_state_trigger: false,
                        or: Vec::new(),
                        chapter_numbers: SmallVec::new(),
                        is_chapter_ability: false,
                        spell_delayed: None,
                    }),
                    effect: sub_parse.steps,
                    targets: sub_parse.targets,
                    next_turn: false,
                }));
                return true;
            }
        }
    }

    // 2. "For each color among permanents you control, add one mana of that color" (*Faeburrow Elder*)
    if eq_ci(
        t,
        "for each color among permanents you control, add one mana of that color",
    ) {
        state.push_step(
            make_step(
                EffectOp::AddMana {
                    production: ManaProduction::PerColorControlled,
                    restriction: None,
                    restriction_spec: None,
                    retain_until_eot: false,
                    delayed_rider: None,
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }

    // 3. "For each opponent, add {C}" / "For each <X>, add {G}"
    if let Some(after_fe) = strip_prefix_word_ci(t, "for each")
        && let Some((count_phrase, add_part)) = split_at_top_level_comma(after_fe)
        && starts_with_word_ci(add_part, "add")
        && let Some(amt) = parse_amount_str(&format!("for each {count_phrase}"), ctx, state)
            .or_else(|| parse_amount_str(count_phrase, ctx, state))
    {
        let mark = state.mark(ctx);
        if parse_add_mana_core(add_part, span, ctx, state)
            && let Some(last) = state.steps.last_mut()
            && matches!(last.op, EffectOp::AddMana { .. })
        {
            last.amount = Some(Box::new(amt));
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 4. "<Add ...>, where X is <expr>"
    if let Some((main_add, where_expr)) = split_where_x_is(t)
        && starts_with_word_ci(main_add, "add")
        && let Some(x_amt) = parse_amount_str(where_expr, ctx, state)
    {
        let prev_x = state.defined_x.clone();
        state.defined_x = Some(x_amt.clone());
        let mark = state.mark(ctx);
        let ok = parse_add_mana_core(main_add, span, ctx, state);
        state.defined_x = prev_x;
        if ok {
            if let Some(last) = state.steps.last_mut()
                && let Some(ref mut amt) = last.amount
                && matches!(**amt, Amount::X)
            {
                **amt = x_amt;
            }
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 4b. "<Add ...> for each <count_phrase>" (*Coalition Relic*, *Jeska's Will*)
    if starts_with_word_ci(t, "add")
        && let Some(fe_pos) = find_word_ci(t, " for each ")
    {
        let main_add = t[..fe_pos].trim();
        if !contains_word_ci(main_add, "mana of that color")
            && !contains_word_ci(main_add, "mana of the chosen color")
        {
            let each_phrase = t[fe_pos + 1..].trim();
            let each_core = t[fe_pos + " for each ".len()..].trim();
            if let Some(each_amt) = parse_amount_str(each_phrase, ctx, state)
                .or_else(|| parse_amount_str(each_core, ctx, state))
            {
                let mark = state.mark(ctx);
                if parse_add_mana_core(main_add, span, ctx, state)
                    && let Some(last) = state.steps.last_mut()
                    && matches!(last.op, EffectOp::AddMana { .. })
                {
                    let scaled = match last.amount.as_deref() {
                        Some(Amount::Const { n }) if *n > 1 => Amount::Mul {
                            factor: *n,
                            of: Box::new(each_amt),
                        },
                        _ => each_amt,
                    };
                    last.amount = Some(Box::new(scaled));
                    return true;
                }
                state.rollback(mark, ctx);
            }
        }
    }

    // 5. Core "add ..." sentence (optionally with inline trailing mana spending restriction sentence if same sentence)
    parse_add_mana_core(t, span, ctx, state)
}

fn parse_add_mana_core(
    raw: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let t = trim_trailing_period(raw);
    let body = match strip_prefix_word_ci(t, "add").or_else(|| strip_prefix_word_ci(t, "you add")) {
        Some(b) => b,
        None => return false,
    };

    // Strip optional trailing "to your mana pool"
    let body = strip_suffix_word_ci(body, "to your mana pool").unwrap_or(body);

    // Strip optional trailing condition/restriction phrase after ", " (e.g. ", spend this mana only ...")
    let (body_main_raw, inline_restr) = if let Some((left, right)) = split_at_top_level_comma(body)
    {
        if starts_with_word_ci(right, "spend this mana only")
            || starts_with_word_ci(right, "this mana can't")
        {
            if let Some(r) = parse_mana_spending_restriction_full(right, ctx) {
                (left, Some(r))
            } else {
                (body, None)
            }
        } else {
            (body, None)
        }
    } else {
        (body, None)
    };
    let body_main = strip_prefix_word_ci(body_main_raw, "an additional").unwrap_or(body_main_raw);

    let make_mana_step = |production: ManaProduction, amount: Option<Amount>| {
        let (tag, spec) = inline_restr.clone().unwrap_or((None, None));
        let mut st = make_step(
            EffectOp::AddMana {
                production,
                restriction: tag,
                restriction_spec: spec,
                retain_until_eot: false,
                delayed_rider: None,
            },
            Selector::None,
            span,
        );
        if let Some(a) = amount {
            st.amount = Some(Box::new(a));
        }
        st
    };

    let low = body_main.to_ascii_lowercase();

    // Variant: FromExiledColors (*Chrome Mox*, *Pit of Offerings*)
    if low == "one mana of any of the exiled card's colors"
        || low == "one mana of any of the exiled cards' colors"
        || low == "mana of any of the exiled card's colors"
    {
        state.push_step(
            make_mana_step(
                ManaProduction::FromExiledColors,
                Some(Amount::Const { n: 1 }),
            ),
            false,
        );
        return true;
    }

    // Variant: OrChosenColor — "{G} or one mana of the chosen color"
    if let Some((left_pip, right_txt)) = body_main.split_once(" or ") {
        let r_low = right_txt.trim().to_ascii_lowercase();
        if (r_low == "one mana of the chosen color" || r_low == "one mana of that color")
            && let Some(syms) = parse_mana_pip_sequence(left_pip)
        {
            let mut cm = ColorMask::empty();
            for s in syms {
                cm |= mana_color_to_mask(s);
            }
            state.push_step(
                make_mana_step(
                    ManaProduction::OrChosenColor { colors: cm },
                    Some(Amount::Const { n: 1 }),
                ),
                false,
            );
            return true;
        }
    }

    // Variant: WithChosenColor — "{R} and one mana of the chosen color"
    if let Some((left_pip, right_txt)) = body_main.split_once(" and ") {
        let r_low = right_txt.trim().to_ascii_lowercase();
        if (r_low == "one mana of the chosen color" || r_low == "one mana of that color")
            && let Some(syms) = parse_mana_pip_sequence(left_pip)
        {
            let mut cm = ColorMask::empty();
            for s in syms {
                cm |= mana_color_to_mask(s);
            }
            state.push_step(
                make_mana_step(
                    ManaProduction::WithChosenColor { colors: cm },
                    Some(Amount::Const { n: 2 }),
                ),
                false,
            );
            return true;
        }
    }

    // Variant: ChosenColorAmount — "an amount of [N] mana of that color [equal to / for each <expr>]"
    if let Some(rest) = strip_prefix_word_ci(body_main, "an amount of mana of that color")
        .or_else(|| strip_prefix_word_ci(body_main, "an amount of mana of the chosen color"))
    {
        let expr_raw = strip_prefix_word_ci(rest, "equal to")
            .or_else(|| strip_prefix_word_ci(rest, "for each"))
            .unwrap_or(rest);
        let amt = if eq_ci(expr_raw, "your devotion to that color") {
            Amount::Devotion {
                colors: ColorMask::W,
                player: None,
            }
        } else {
            let Some(a) = parse_amount_str(expr_raw, ctx, state) else {
                return false;
            };
            a
        };
        let mut st = make_mana_step(
            ManaProduction::ChosenColorAmount {
                amount: Box::new(amt.clone()),
            },
            Some(amt),
        );
        st.subject = you_sel();
        state.push_step(st, false);
        return true;
    }
    if contains_word_ci(body_main, "mana of that color")
        || contains_word_ci(body_main, "mana of the chosen color")
    {
        let mut amt = Amount::Const { n: 1 };
        let head = body_main.split("mana of ").next().unwrap_or("").trim();
        if !head.is_empty()
            && let Some(parsed_a) = parse_amount_str(head, ctx, state)
        {
            amt = parsed_a;
        }
        let is_chosen_amount_phrase = body_main.contains("equal to")
            || body_main.contains("for each")
            || !matches!(amt, Amount::Const { n: 1 });
        if is_chosen_amount_phrase {
            if let Some(pos) = find_word_ci(body_main, "equal to") {
                if let Some(parsed_a) = parse_amount_str(&body_main[pos + 8..], ctx, state) {
                    amt = parsed_a;
                }
            } else if let Some(pos) = find_word_ci(body_main, "for each")
                && let Some(parsed_a) = parse_amount_str(&body_main[pos..], ctx, state)
            {
                amt = parsed_a;
            }
            let mut st = make_mana_step(
                ManaProduction::ChosenColorAmount {
                    amount: Box::new(amt.clone()),
                },
                Some(amt),
            );
            st.subject = you_sel();
            state.push_step(st, false);
            return true;
        } else {
            state.push_step(
                make_mana_step(
                    ManaProduction::Choice {
                        kind: ManaChoiceKind::ChosenColor,
                        colors: ColorMask::empty(),
                    },
                    Some(Amount::Const { n: 1 }),
                ),
                false,
            );
            return true;
        }
    }

    // Variant: Combination — "<N> mana in any combination of [colors | <color-pips>]"
    if let Some(idx) = find_word_ci(body_main, "mana in any combination of") {
        let count_raw = body_main[..idx].trim();
        let after = body_main[idx + "mana in any combination of".len()..].trim();
        let amt = parse_amount_str(count_raw, ctx, state).unwrap_or(Amount::Const { n: 1 });
        if eq_ci(after, "colors") || eq_ci(after, "any colors") {
            state.push_step(
                make_mana_step(
                    ManaProduction::Combination {
                        any_color: true,
                        colors: ColorMask::empty(),
                    },
                    Some(amt),
                ),
                false,
            );
            return true;
        }
        let mut cm = ColorMask::empty();
        for ch in after.chars() {
            if let Some(mc) = parse_mana_color_char(ch)
                && after.contains(&format!("{{{ch}}}"))
            {
                cm |= mana_color_to_mask(mc);
            }
        }
        if cm.is_empty() {
            cm = parse_color_list_str(after);
        }
        if !cm.is_empty() {
            state.push_step(
                make_mana_step(
                    ManaProduction::Combination {
                        any_color: false,
                        colors: cm,
                    },
                    Some(amt),
                ),
                false,
            );
            return true;
        }
    }

    // Variant: Fixed — pure pip sequence "{G}", "{C}{C}", "{W}{U}"
    if let Some(syms) = parse_mana_pip_sequence(body_main) {
        let amt = Amount::Const {
            n: syms.len() as i32,
        };
        state.push_step(
            make_mana_step(
                ManaProduction::Fixed {
                    symbols: SmallVec::from_vec(syms),
                },
                Some(amt),
            ),
            false,
        );
        return true;
    }

    // Variant: "that much <pips>" / "that many <pips>" (Neheb, Dreadhorde Champion)
    if let Some(pip_s) = strip_prefix_word_ci(body_main, "that much")
        .or_else(|| strip_prefix_word_ci(body_main, "that many"))
        && let Some(syms) = parse_mana_pip_sequence(pip_s)
    {
        let amt = resolve_that_many_amount(state);
        let mut st = make_mana_step(
            ManaProduction::Fixed {
                symbols: SmallVec::from_vec(syms),
            },
            Some(amt),
        );
        st.subject = you_sel();
        state.push_step(st, false);
        return true;
    }

    // Variant: Fixed mana scaled by "for each <filter>" or "equal to <expr>" ("{B} for each basic Swamp you control")
    if let Some((pip_s, expr_s, is_for_each)) = find_word_ci(body_main, " for each ")
        .map(|p| {
            (
                body_main[..p].trim(),
                body_main[p + " for each ".len()..].trim(),
                true,
            )
        })
        .or_else(|| {
            find_word_ci(body_main, " equal to ").map(|p| {
                (
                    body_main[..p].trim(),
                    body_main[p + " equal to ".len()..].trim(),
                    false,
                )
            })
        })
        && let Some(syms) = parse_mana_pip_sequence(pip_s)
    {
        let full_expr = if is_for_each {
            format!("for each {expr_s}")
        } else {
            expr_s.to_string()
        };
        if let Some(amt) = parse_amount_str(&full_expr, ctx, state)
            .or_else(|| parse_amount_str(expr_s, ctx, state))
        {
            state.push_step(
                make_mana_step(
                    ManaProduction::Fixed {
                        symbols: SmallVec::from_vec(syms),
                    },
                    Some(amt),
                ),
                false,
            );
            return true;
        }
    }

    // Variant: "an amount of {C} equal to ..." or "<N> {R}"
    if let Some(rest) = strip_prefix_word_ci(body_main, "an amount of")
        && let Some((pip_s, expr_s)) = rest
            .split_once(" equal to ")
            .or_else(|| rest.split_once(" for each "))
        && let Some(syms) = parse_mana_pip_sequence(pip_s)
        && let Some(amt) = parse_amount_str(expr_s.trim(), ctx, state)
    {
        state.push_step(
            make_mana_step(
                ManaProduction::Fixed {
                    symbols: SmallVec::from_vec(syms),
                },
                Some(amt),
            ),
            false,
        );
        return true;
    }

    // Variant: Bundles or Choice::Colors ("{W} or {U}", "{W}, {U}, {B}, {R}, or {G}", "{W}{W}, {W}{B}, or {B}{B}")
    if let Some((single_colors, bundle_seqs)) = parse_mana_or_list(body_main) {
        if !bundle_seqs.is_empty() {
            let bundle_n = bundle_seqs.first().map_or(1, |b| b.len() as i32);
            let options = bundle_seqs.into_iter().map(SmallVec::from_vec).collect();
            state.push_step(
                make_mana_step(
                    ManaProduction::Bundles { options },
                    Some(Amount::Const { n: bundle_n }),
                ),
                false,
            );
            return true;
        } else if !single_colors.is_empty() {
            let mut cm = ColorMask::empty();
            for c in single_colors {
                cm |= mana_color_to_mask(c);
            }
            state.push_step(
                make_mana_step(
                    ManaProduction::Choice {
                        kind: ManaChoiceKind::Colors,
                        colors: cm,
                    },
                    Some(Amount::Const { n: 1 }),
                ),
                false,
            );
            return true;
        }
    }

    // Variant: Choice kinds ("one mana of any color", "commander's color identity", "controlled land", "opponent land", "event produced")
    if let Some(idx) = find_word_ci(body_main, "mana of ") {
        let cnt_str = body_main[..idx].trim();
        let after = body_main[idx + "mana of ".len()..].trim();
        let amt = if cnt_str.is_empty() {
            Amount::Const { n: 1 }
        } else {
            parse_amount_str(cnt_str, ctx, state).unwrap_or(Amount::Const { n: 1 })
        };
        let a_low = after.to_ascii_lowercase();
        let kind = if a_low == "any color" || a_low == "any one color" {
            Some(ManaChoiceKind::Any)
        } else if a_low.contains("commander's color identity") {
            Some(ManaChoiceKind::CommanderIdentity)
        } else if a_low.contains("land you control could produce") {
            if a_low.contains("type") {
                Some(ManaChoiceKind::ControlledLandProducedTypes)
            } else {
                Some(ManaChoiceKind::ControlledLandProducedColors)
            }
        } else if a_low.contains("land an opponent controls could produce") {
            Some(ManaChoiceKind::OpponentLandColors)
        } else if a_low.contains("that land produced") || a_low.contains("that permanent produced")
        {
            if a_low.contains("type") {
                Some(ManaChoiceKind::EventProducedTypes)
            } else {
                Some(ManaChoiceKind::EventProducedColors)
            }
        } else {
            None
        };
        if let Some(k) = kind {
            state.push_step(
                make_mana_step(
                    ManaProduction::Choice {
                        kind: k,
                        colors: ColorMask::empty(),
                    },
                    Some(amt),
                ),
                false,
            );
            return true;
        }
    }

    false
}

fn split_where_x_is(t: &str) -> Option<(&str, &str)> {
    let bytes = t.as_bytes();
    let needle = ", where x is ";
    if bytes.len() <= needle.len() || !bytes.contains(&b',') {
        return None;
    }
    for i in 0..=bytes.len() - needle.len() {
        if bytes[i] == b','
            && t.is_char_boundary(i + needle.len())
            && t[i..i + needle.len()].eq_ignore_ascii_case(needle)
        {
            return Some((t[..i].trim(), t[i + needle.len()..].trim()));
        }
    }
    None
}

fn parse_token_creation_clause(
    raw: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let t = trim_trailing_period(raw);
    if !starts_with_word_ci(t, "create") && !starts_with_word_ci(t, "you create") {
        return false;
    }

    // 0. Role token: "create a <Kind> Role token"
    if let Some(role) = parse_role_token_kind(t) {
        let mut st = make_step(EffectOp::CreateRoleToken { role }, you_sel(), span);
        if let Some(r) = state.it_ref() {
            st.subject = ref_to_selector(&r);
        }
        state.push_step(st, false);
        return true;
    }

    // 1. Compound token creation: "create <A tokens> and <B tokens>"
    if let Some(after_create) =
        strip_prefix_word_ci(t, "create").or_else(|| strip_prefix_word_ci(t, "you create"))
        && let Some(and_pos) = find_word_ci(after_create, " and ")
    {
        let left = after_create[..and_pos].trim();
        let right = after_create[and_pos + 5..].trim();
        if (contains_word_ci(left, "token") || contains_word_ci(left, "tokens"))
            && (contains_word_ci(right, "token") || contains_word_ci(right, "tokens"))
            && !starts_with_word_ci(right, "that")
            && !contains_word_ci(left, " and ")
        {
            let mark = state.mark(ctx);
            if parse_token_creation_clause(&format!("create {left}"), span, ctx, state)
                && parse_token_creation_clause(&format!("create {right}"), span, ctx, state)
            {
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    // 2. "create [tapped] <body...>, where X is <expr>"
    if let Some((left, x_expr)) = split_where_x_is(t)
        && let Some(amt_expr) = parse_amount_str(x_expr, ctx, state)
    {
        let prev_x = state.defined_x.clone();
        state.defined_x = Some(amt_expr.clone());
        let mark = state.mark(ctx);
        if parse_token_creation_clause(left, span, ctx, state) {
            state.defined_x = prev_x;
            if let Some(st) = state.steps.last_mut() {
                if let Some(ref mut a) = st.amount
                    && matches!(**a, Amount::X)
                {
                    **a = amt_expr.clone();
                }
                if let EffectOp::CreateToken {
                    dynamic_pt: Some((ref mut pw, ref mut tg)),
                    ..
                } = st.op
                {
                    if matches!(**pw, Amount::X) {
                        **pw = amt_expr.clone();
                    }
                    if matches!(**tg, Amount::X) {
                        **tg = amt_expr;
                    }
                }
            }
            return true;
        }
        state.defined_x = prev_x;
        state.rollback(mark, ctx);
    }

    // 3. "create <tok> for each <expr>"
    if let Some(idx) = find_word_ci(t, " for each ") {
        let left = t[..idx].trim();
        let right = t[idx + " for each ".len()..].trim();
        if contains_word_ci(left, "token")
            && let Some(amt) = parse_amount_str(&format!("for each {right}"), ctx, state)
                .or_else(|| parse_amount_str(right, ctx, state))
        {
            let mark = state.mark(ctx);
            if parse_token_creation_clause(left, span, ctx, state)
                && let Some(st) = state.steps.last_mut()
                && matches!(st.op, EffectOp::CreateToken { .. })
            {
                st.amount = Some(Box::new(amt));
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    let Some(body_raw) =
        strip_prefix_word_ci(t, "create").or_else(|| strip_prefix_word_ci(t, "you create"))
    else {
        return false;
    };
    let body = body_raw.trim();

    // 4. Token copy: "a token that's a copy of ..." / "N tokens that are copies of ..."
    if contains_word_ci(body, "that's a copy of")
        || contains_word_ci(body, "that is a copy of")
        || contains_word_ci(body, "that are copies of")
    {
        return parse_token_copy_body(body, span, ctx, state);
    }

    // 5. Quoted-ability / named / predefined / P/T token creation
    // Extract trailing quoted abilities (`with ... "..."`) first so we don't choke on inner commas/spaces
    let (head_part, quoted_list, plain_kw_with) = extract_token_with_clause(body);
    let mut quoted_abilities = Vec::new();
    for q in &quoted_list {
        let norm_q = q.replace(['\u{2018}', '\u{2019}'], "'");
        let _ = state.compile_quoted(&norm_q, "Token", ctx);
        quoted_abilities.push(norm_q);
    }

    // Strip leading amount + modifiers ("a", "two", "twice X", "X", "tapped", "and attacking", "legendary", "a number of ... equal to ...")
    let mut rest = head_part.trim();
    let mut tapped = false;
    let mut tapped_and_attacking = false;
    let mut legendary = false;
    let mut explicit_name: Option<&str> = None;

    // Check "a number of <X> equal to <Y>"
    let mut amount = Amount::Const { n: 1 };
    if let Some(after_num) = strip_prefix_word_ci(rest, "a number of")
        && let Some(eq_idx) = find_word_ci(after_num, " equal to ")
    {
        let tok_body = after_num[..eq_idx].trim();
        let expr_s = after_num[eq_idx + " equal to ".len()..].trim();
        if let Some(a) = parse_amount_str(expr_s, ctx, state) {
            amount = a;
            rest = tok_body;
        }
    } else if let Some(after_twice) = strip_prefix_word_ci(rest, "twice x") {
        amount = Amount::Mul {
            factor: 2,
            of: Box::new(state.defined_x.clone().unwrap_or(Amount::X)),
        };
        rest = after_twice;
    } else if let Some(after_that_many) = strip_prefix_word_ci(rest, "that many") {
        amount = resolve_that_many_amount(state);
        rest = after_that_many;
    } else {
        // Parse leading number word or digit or "X"
        let first_word = rest.split_whitespace().next().unwrap_or("");
        if eq_ci(first_word, "x") {
            amount = state.defined_x.clone().unwrap_or(Amount::X);
            rest = rest[first_word.len()..].trim_start();
        } else if let Some(n) = parse_small_number(first_word) {
            amount = Amount::Const { n };
            rest = rest[first_word.len()..].trim_start();
        } else if eq_ci(first_word, "a") || eq_ci(first_word, "an") {
            rest = rest[first_word.len()..].trim_start();
        } else {
            // Check named legendary token: "<Name>, a [legendary] P/T ..."
            if let Some((name_s, after_comma)) = split_at_top_level_comma(rest)
                && (starts_with_word_ci(after_comma, "a ")
                    || starts_with_word_ci(after_comma, "an "))
            {
                explicit_name = Some(name_s.trim());
                let after_art = strip_prefix_word_ci(after_comma, "a")
                    .or_else(|| strip_prefix_word_ci(after_comma, "an"))
                    .unwrap_or(after_comma);
                rest = after_art.trim();
            }
        }
    }

    // Consume modifiers: tapped, tapped and attacking, legendary
    loop {
        if let Some(r) = strip_prefix_word_ci(rest, "tapped and attacking") {
            tapped = true;
            tapped_and_attacking = true;
            rest = r;
        } else if let Some(r) = strip_prefix_word_ci(rest, "tapped") {
            tapped = true;
            rest = r;
        } else if let Some(r) = strip_prefix_word_ci(rest, "legendary") {
            legendary = true;
            rest = r;
        } else {
            break;
        }
    }

    // Check trailing "that are tapped [and attacking]"
    for (pat, atk) in [
        ("that are tapped and attacking", true),
        ("that's tapped and attacking", true),
        ("that is tapped and attacking", true),
        ("that are tapped", false),
        ("that's tapped", false),
        ("that is tapped", false),
    ] {
        if let Some(r) = strip_suffix_word_ci(rest, pat) {
            tapped = true;
            if atk {
                tapped_and_attacking = true;
            }
            rest = r;
            break;
        }
    }

    // Check trailing " named <Name>"
    if let Some(n_pos) = find_word_ci(rest, " named ") {
        explicit_name = Some(rest[n_pos + 7..].trim());
        rest = rest[..n_pos].trim();
    }

    // Strip trailing "token" / "tokens"
    let Some(tok_desc) =
        strip_suffix_word_ci(rest, "tokens").or_else(|| strip_suffix_word_ci(rest, "token"))
    else {
        return false;
    };

    // Predefined token check (e.g. "Treasure", "Food", "Clue", "Map", etc.)
    if plain_kw_with.is_empty()
        && quoted_abilities.is_empty()
        && let Some(pre) = find_predefined_token(tok_desc)
    {
        let spec = build_predefined_token_spec(pre, tapped, ctx);
        let mut st = make_step(
            EffectOp::CreateToken {
                token: Some(Box::new(spec)),
                dynamic_pt: None,
                tapped_and_attacking,
                per_opponent_tapped_attacking: None,
                multiply_by_opponents_did_this_way: false,
                benthic_anomaly_clone: false,
            },
            Selector::None,
            span,
        );
        st.amount = Some(Box::new(amount));
        st.bind_as = Some(state.alloc_bind_name("created"));
        state.push_step(st, true);
        return true;
    }

    // Standard P/T token: "<P>/<T> <desc>" or "X/X <desc>" or CDA creature token
    let first_tok = tok_desc.split_whitespace().next().unwrap_or("");
    let mut extra_types = CardTypeMask::empty();
    let mut dynamic_pt = None;
    let (pw, tg, desc_after_pt) = if let Some((p_str, t_str)) = first_tok.split_once('/') {
        let rest_desc = tok_desc[first_tok.len()..].trim();
        if eq_ci(p_str, "x") || eq_ci(t_str, "x") || p_str == "*" || t_str == "*" {
            let p_amt = if eq_ci(p_str, "x") {
                state.defined_x.clone().unwrap_or(Amount::X)
            } else if p_str == "*" {
                Amount::X
            } else if let Ok(n) = p_str.parse::<i32>() {
                Amount::Const { n }
            } else {
                return false;
            };
            let t_amt = if eq_ci(t_str, "x") {
                state.defined_x.clone().unwrap_or(Amount::X)
            } else if t_str == "*" {
                Amount::X
            } else if let Ok(n) = t_str.parse::<i32>() {
                Amount::Const { n }
            } else {
                return false;
            };
            dynamic_pt = Some((Box::new(p_amt), Box::new(t_amt)));
            (0, 0, rest_desc)
        } else if let (Ok(pw), Ok(tg)) = (p_str.parse::<i32>(), t_str.parse::<i32>()) {
            (pw, tg, rest_desc)
        } else {
            return false;
        }
    } else if contains_word_ci(tok_desc, "creature") && !quoted_abilities.is_empty() {
        (0, 0, tok_desc)
    } else {
        return false;
    };

    if contains_word_ci(desc_after_pt, "artifact") {
        extra_types |= CardTypeMask::ARTIFACT;
    }
    if contains_word_ci(desc_after_pt, "enchantment") {
        extra_types |= CardTypeMask::ENCHANTMENT;
    }
    if contains_word_ci(desc_after_pt, "creature") {
        extra_types |= CardTypeMask::CREATURE;
    }

    let (plain_kw_with, explicit_name) = if explicit_name.is_none()
        && let Some(n_pos) = find_word_ci(plain_kw_with, " named ")
    {
        (
            plain_kw_with[..n_pos].trim_end_matches(',').trim(),
            Some(plain_kw_with[n_pos + 7..].trim()),
        )
    } else {
        (plain_kw_with, explicit_name)
    };

    if !plain_kw_with.trim().is_empty() && parse_keyword_list_ids(plain_kw_with, ctx).is_none() {
        return false;
    }

    let spec = build_token_spec_from_desc(
        pw,
        tg,
        desc_after_pt,
        plain_kw_with,
        extra_types,
        tapped,
        legendary,
        explicit_name,
        quoted_abilities,
        ctx,
    );
    let mut st = make_step(
        EffectOp::CreateToken {
            token: Some(Box::new(spec)),
            dynamic_pt,
            tapped_and_attacking,
            per_opponent_tapped_attacking: None,
            multiply_by_opponents_did_this_way: false,
            benthic_anomaly_clone: false,
        },
        Selector::None,
        span,
    );
    st.amount = Some(Box::new(amount));
    st.bind_as = Some(state.alloc_bind_name("created"));
    state.push_step(st, true);
    true
}

fn extract_token_with_clause(body: &str) -> (&str, Vec<&str>, &str) {
    // Look for " with " after "token" or "tokens"
    let Some(tok_pos) = find_word_ci(body, "token").or_else(|| find_word_ci(body, "tokens")) else {
        return (body, Vec::new(), "");
    };
    let word_len = if body[tok_pos..].len() >= 6
        && body[tok_pos..tok_pos + 6].eq_ignore_ascii_case("tokens")
    {
        6
    } else {
        5
    };
    let head = &body[..tok_pos + word_len];
    let tail = body[tok_pos + word_len..].trim();
    let Some(with_rest) = strip_prefix_word_ci(tail, "with") else {
        return (body, Vec::new(), "");
    };
    // Extract quoted substrings if present
    let mut quotes = Vec::new();
    let mut plain_end = with_rest.len();
    let mut cur = with_rest;
    if let Some(q_start) = with_rest.find(['"', '“']) {
        plain_end = q_start;
        let q_char = with_rest[q_start..].chars().next().unwrap();
        let close_ch = if q_char == '“' { '”' } else { '"' };
        let after_open = &with_rest[q_start + q_char.len_utf8()..];
        if let Some(q_end) = after_open.find(close_ch) {
            quotes.push(after_open[..q_end].trim());
            cur = "";
        }
    }
    let _ = cur;
    let plain = with_rest[..plain_end]
        .trim()
        .trim_end_matches(" and")
        .trim_end_matches(',')
        .trim();
    (head, quotes, plain)
}

fn resolve_that_many_amount(state: &ParserState<'_>) -> Amount {
    for step in state.steps.iter().rev() {
        match &step.op {
            EffectOp::Discard { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::DiscardedThisWay,
                };
            }
            EffectOp::Sacrifice { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::SacrificedThisWay,
                };
            }
            EffectOp::Destroy { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::DestroyedThisWay,
                };
            }
            EffectOp::Exile { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::ExiledThisWay,
                };
            }
            EffectOp::Mill => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::MilledThisWay,
                };
            }
            EffectOp::Tap { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::TappedThisWay,
                };
            }
            EffectOp::Draw { .. } => {
                if let Some(ct) = state.trigger_had_counter
                    && matches!(step.amount.as_deref(), Some(Amount::LkiCounterCount { .. }))
                {
                    return Amount::LkiCounterCount { counter: ct };
                }
                if let Some(amt) = step.amount.as_deref()
                    && matches!(amt, Amount::CountedThisWay { .. })
                {
                    return amt.clone();
                }
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::DrawnThisWay,
                };
            }
            EffectOp::Bounce { .. }
            | EffectOp::Move {
                to: Some(Zone::Hand),
                ..
            } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::ReturnedToHandThisWay,
                };
            }
            EffectOp::Damage { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::DamageDealtThisWay,
                };
            }
            EffectOp::Reveal { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::RevealedThisWay,
                };
            }
            EffectOp::PreventDamage { .. } => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::DamagePrevented,
                };
            }
            EffectOp::GainLife { .. } | EffectOp::LoseLife => {
                if let Some(amt) = &step.amount {
                    return (**amt).clone();
                }
            }
            EffectOp::Grant {
                pay_any_mana_for_damage: Some(_),
                ..
            } => {
                return Amount::LastEffectAmount;
            }
            _ => {}
        }
    }
    if let Some(ct) = state.trigger_had_counter
        && !state.steps.iter().any(|s| {
            matches!(
                s.op,
                EffectOp::Discard { .. }
                    | EffectOp::Sacrifice { .. }
                    | EffectOp::Destroy { .. }
                    | EffectOp::Exile { .. }
                    | EffectOp::Mill
                    | EffectOp::Bounce { .. }
                    | EffectOp::Move { .. }
                    | EffectOp::Damage { .. }
                    | EffectOp::Reveal { .. }
            )
        })
    {
        return Amount::LkiCounterCount { counter: ct };
    }
    if let Some(trig) = state.trigger {
        match trig.event {
            EventKind::Sacrificed => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::SacrificedThisWay,
                };
            }
            EventKind::Discard => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::DiscardedThisWay,
                };
            }
            EventKind::DrawCard => {
                return Amount::CountedThisWay {
                    kind: CountedThisWayKind::DrawnThisWay,
                };
            }
            EventKind::DealsDamage
            | EventKind::DealtDamage
            | EventKind::GainLife
            | EventKind::LoseLife
            | EventKind::CounterPlaced
            | EventKind::CounterRemoved
            | EventKind::Attacks => return Amount::EventAmount,
            EventKind::CombatDamageBatchPlayer if trig.filter.one_or_more => {
                return Amount::Const { n: 1 };
            }
            EventKind::ZoneChange => {
                if matches!(
                    trig.filter.detail.as_ref(),
                    Some(EventDetail::ZoneChange {
                        to: Some(Zone::Exile),
                        ..
                    })
                ) {
                    return Amount::CountedThisWay {
                        kind: CountedThisWayKind::ExiledThisWay,
                    };
                }
            }
            _ => {}
        }
    }
    if state.has_sac_step_or_trigger() {
        Amount::CountedThisWay {
            kind: CountedThisWayKind::SacrificedThisWay,
        }
    } else {
        Amount::CountedThisWay {
            kind: CountedThisWayKind::ExiledThisWay,
        }
    }
}

fn parse_token_copy_body(
    body: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let mut rest = body.trim();
    let mut amount = Amount::Const { n: 1 };
    if let Some(after_num) = strip_prefix_word_ci(rest, "a number of")
        && let Some(eq_idx) = find_word_ci(after_num, " equal to ")
    {
        let tok_body = after_num[..eq_idx].trim();
        let after_eq = after_num[eq_idx + " equal to ".len()..].trim();
        let (expr_s, tail_copy) = if let Some(idx) = find_word_ci(after_eq, ", except ") {
            (after_eq[..idx].trim(), &after_eq[idx..])
        } else {
            (after_eq, "")
        };
        if let Some(a) = parse_amount_str(expr_s, ctx, state) {
            amount = a;
            if tok_body.contains("copy of ") || tok_body.contains("copies of ") {
                rest = tok_body;
            } else {
                let _ = tail_copy;
            }
        }
    } else if let Some(after_that_many) = strip_prefix_word_ci(rest, "that many") {
        amount = resolve_that_many_amount(state);
        rest = after_that_many;
    } else {
        let first = rest.split_whitespace().next().unwrap_or("");
        if eq_ci(first, "x") {
            amount = state.defined_x.clone().unwrap_or(Amount::X);
            rest = rest[1..].trim_start();
        } else if eq_ci(first, "a") || eq_ci(first, "an") {
            rest = rest[first.len()..].trim_start();
        } else if let Some(n) = parse_small_number(first) {
            amount = Amount::Const { n };
            rest = rest[first.len()..].trim_start();
        }
    }

    let mut tapped = false;
    let mut tapped_and_attacking = false;
    if let Some(r) = strip_prefix_word_ci(rest, "tapped and attacking") {
        tapped = true;
        tapped_and_attacking = true;
        rest = r;
    } else if let Some(r) = strip_prefix_word_ci(rest, "tapped") {
        tapped = true;
        rest = r;
    }

    let after_marker = if let Some(idx) = find_word_ci(rest, "that's a copy of ") {
        rest[idx + "that's a copy of ".len()..].trim()
    } else if let Some(idx) = find_word_ci(rest, "that is a copy of ") {
        rest[idx + "that is a copy of ".len()..].trim()
    } else if let Some(idx) = find_word_ci(rest, "that are copies of ") {
        rest[idx + "that are copies of ".len()..].trim()
    } else {
        return false;
    };

    let (target_part, except_part) = if let Some(ex_idx) = find_word_ci(after_marker, ", except ") {
        (
            after_marker[..ex_idx].trim(),
            Some(after_marker[ex_idx + 9..].trim()),
        )
    } else {
        (after_marker, None)
    };
    let mut target_part = target_part;
    if let Some(s) = strip_suffix_word_ci(target_part, "tapped and attacking") {
        tapped_and_attacking = true;
        target_part = s;
    } else if let Some(s) = strip_suffix_word_ci(target_part, "tapped") {
        tapped = true;
        target_part = s;
    }

    let Some(obj) = parse_object_selector(target_part, ZoneMask::BATTLEFIELD, ctx, state) else {
        return false;
    };

    let mut select = SelectionMod::default();
    if matches!(obj, ParsedObj::All { .. })
        && (starts_with_word_ci(target_part, "a ") || starts_with_word_ci(target_part, "an "))
    {
        select.choice_count = Some(Box::new(Amount::Const { n: 1 }));
    }

    let mut not_legendary = false;
    let mut copy_mod: Option<Box<CopyModificationSpec>> = None;
    let mut except_pt = None;
    if let Some(ex) = except_part {
        let mut cm = CopyModificationSpec::default();
        let ex_low = ex.to_ascii_lowercase();
        if ex_low.contains("isn't legendary") || ex_low.contains("aren't legendary") {
            not_legendary = true;
            cm.remove_supertypes |= SupertypeMask::LEGENDARY;
        }
        if ex_low.contains("it has haste") || ex_low.contains("they have haste") {
            cm.add_keywords.push(ctx.interner.intern_keyword("Haste"));
        }
        if ex_low.contains("flying") {
            cm.add_keywords.push(ctx.interner.intern_keyword("Flying"));
        }
        if ex_low.contains("at the beginning of the end step, sacrifice ~") {
            cm.added_ability_texts
                .push("At the beginning of the end step, sacrifice ~.".to_string());
        }
        if ex_low.contains("loses all other card types") {
            let mut types = CardTypeMask::empty();
            if ex_low.contains("artifact") {
                types |= CardTypeMask::ARTIFACT;
            }
            if ex_low.contains("enchantment") {
                types |= CardTypeMask::ENCHANTMENT;
            }
            if ex_low.contains("creature") {
                types |= CardTypeMask::CREATURE;
            }
            if ex_low.contains("land") {
                types |= CardTypeMask::LAND;
            }
            if ex_low.contains("planeswalker") {
                types |= CardTypeMask::PLANESWALKER;
            }
            if !types.is_empty() {
                cm.set_types = Some(types);
            }
        }
        if ex_low.contains("half that creature's power") {
            cm.halve_pt = Some(RoundMode::Up);
        }
        if ex_low.contains("it's ")
            || ex_low.contains("they're ")
            || ex_low.contains("token is ")
            || ex_low.contains("tokens are ")
        {
            for raw_w in ex.split_whitespace() {
                let w = raw_w.trim_matches(|c: char| matches!(c, ',' | '.' | ';'));
                if let Some((ps, ts)) = w.split_once('/')
                    && let (Ok(p), Ok(t)) = (ps.parse::<i32>(), ts.parse::<i32>())
                {
                    except_pt = Some((p, t));
                    cm.power = Some(p);
                    cm.toughness = Some(t);
                    break;
                }
            }
            if except_pt.is_some() {
                let in_addition = ex_low.contains("in addition to");
                let mut types = CardTypeMask::empty();
                if ex_low.contains("creature") {
                    types |= CardTypeMask::CREATURE;
                }
                if ex_low.contains("artifact") {
                    types |= CardTypeMask::ARTIFACT;
                }
                if ex_low.contains("enchantment") {
                    types |= CardTypeMask::ENCHANTMENT;
                }
                let mut colors = ColorMask::empty();
                for (cname, mask) in [
                    ("white", ColorMask::W),
                    ("blue", ColorMask::U),
                    ("black", ColorMask::B),
                    ("red", ColorMask::R),
                    ("green", ColorMask::G),
                ] {
                    if find_word_ci(&ex_low, cname).is_some() {
                        colors |= mask;
                    }
                }
                let mut subs: SmallVec<[mtg_ir::SubtypeId; 2]> = SmallVec::new();
                for raw_w in ex.split_whitespace() {
                    let w = raw_w.trim_matches(|c: char| matches!(c, ',' | '.' | ';'));
                    if w.len() >= 2
                        && w.starts_with(|c: char| c.is_ascii_uppercase())
                        && !matches!(
                            w,
                            "It's"
                                | "They're"
                                | "Except"
                                | "In"
                                | "White"
                                | "Blue"
                                | "Black"
                                | "Red"
                                | "Green"
                                | "Artifact"
                                | "Creature"
                                | "Enchantment"
                                | "Flying"
                                | "Haste"
                        )
                    {
                        let sing = if w.ends_with('s') && w.len() > 3 {
                            &w[..w.len() - 1]
                        } else {
                            w
                        };
                        subs.push(ctx.interner.intern_subtype(sing));
                    }
                }
                if in_addition {
                    cm.add_types |= types;
                    cm.add_colors |= colors;
                    for s in subs {
                        if !cm.add_subtypes.contains(&s) {
                            cm.add_subtypes.push(s);
                        }
                    }
                } else {
                    if !types.is_empty() && cm.set_types.is_none() {
                        cm.set_types = Some(types);
                    }
                    if !colors.is_empty() && cm.set_colors.is_none() {
                        cm.set_colors = Some(colors);
                    }
                    if !subs.is_empty() && cm.set_subtypes.is_none() {
                        cm.set_subtypes = Some(subs);
                    }
                }
            }
        }
        copy_mod = Some(Box::new(cm));
    }

    let mut st = make_step(
        EffectOp::CopyPermanent {
            select,
            not_legendary,
            tapped,
            tapped_and_attacking,
            per_opponent_tapped_attacking: None,
            copy_mod,
            except_pt,
        },
        obj.into_selector(),
        span,
    );
    if !matches!(amount, Amount::Const { n: 1 }) {
        st.amount = Some(Box::new(amount));
    }
    st.bind_as = Some("created".to_string());
    state.push_step(st, true);
    true
}

// ============================================================================
// Section 6: Wave Amount/Condition Fallbacks & Core Imperative Verb Handlers
// ============================================================================

fn parse_wave_amount_str(
    raw: &str,
    ctx: &mut ParseCtx<'_>,
    scope: &mut dyn ParserScope,
) -> Option<Amount> {
    let t = trim_trailing_period(raw);
    let stripped = strip_prefix_word_ci(t, "the").unwrap_or(t);
    let low = stripped.to_ascii_lowercase();

    if eq_ci(t, "twice x") {
        return Some(Amount::Mul {
            factor: 2,
            of: Box::new(Amount::X),
        });
    }
    if low == "difference" {
        if let Some(pref) = scope.last_player_ref() {
            return Some(Amount::HandSizeDifference {
                target_player: Some(pref),
                cap: None,
            });
        }
        return Some(Amount::HandSizeDifference {
            target_player: None,
            cap: Some(7),
        });
    }
    if low == "number of cards in defending player's hand minus the number of cards in your hand" {
        return Some(Amount::HandSizeDifference {
            target_player: Some(PlayerRef::DefendingPlayer),
            cap: None,
        });
    }
    if low == "number of coins that came up heads" {
        return Some(Amount::CoinHeadsCount);
    }
    if low == "number of different mana values among cards in your graveyard" {
        return Some(Amount::DistinctManaValuesInGraveyard { filter: None });
    }
    if low == "number of different powers among creatures you control" {
        return Some(Amount::DistinctPowersControlled);
    }
    if low == "number of differently named tokens you control" {
        let f = ObjectFilter {
            zones: ZoneMask::BATTLEFIELD,
            controller: Some(RelativeControl::You),
            flags: FilterFlags::TOKEN,
            ..Default::default()
        };
        return Some(Amount::DistinctNamesCount { of: Box::new(f) });
    }
    if low == "amount of life you gained" {
        return Some(Amount::EventAmount);
    }
    if low == "amount of life you gained this turn" {
        return Some(Amount::LifeGainedThisTurn);
    }
    if low == "number of tokens you created this turn" {
        return Some(Amount::TokensCreatedThisTurn { player: None });
    }
    if low == "nontoken creatures that died under your control this turn"
        || low == "nontoken creature that died under your control this turn"
        || low == "number of nontoken creatures that died under your control this turn"
    {
        return Some(Amount::NontokenCreaturesDiedThisTurn {
            controller: Some(RelativeControl::You),
        });
    }
    if low == "nontoken creatures that died this turn"
        || low == "nontoken creature that died this turn"
        || low == "number of nontoken creatures that died this turn"
    {
        return Some(Amount::NontokenCreaturesDiedThisTurn {
            controller: Some(RelativeControl::Any),
        });
    }
    if low
        == "number of cards that were put into your graveyard from your hand or library this turn"
    {
        return Some(Amount::CardsPutIntoGraveyardFromHandOrLibraryThisTurn { player: None });
    }
    if low == "damage dealt to your opponents this turn"
        || low == "amount of damage dealt to your opponents this turn"
    {
        return Some(Amount::DamageDealtToOpponentsThisTurn);
    }
    if low == "number of players who lost life this turn"
        || low == "players who lost life this turn"
        || low == "player who lost life this turn"
    {
        return Some(Amount::PlayersLostLifeThisTurnCount);
    }
    if let Some((base_frac, round)) = low
        .strip_suffix(", rounded up")
        .map(|b| (b.trim(), RoundMode::Up))
        .or_else(|| {
            low.strip_suffix(", rounded down")
                .map(|b| (b.trim(), RoundMode::Down))
        })
    {
        let (denom, who_life) = if let Some(r) = base_frac.strip_prefix("a third of ") {
            (Some(3u16), r.trim())
        } else if let Some(r) = base_frac
            .strip_prefix("half of ")
            .or_else(|| base_frac.strip_prefix("half "))
        {
            (Some(2u16), r.trim())
        } else {
            (None, "")
        };
        if let Some(denominator) = denom {
            let pref = match who_life {
                "their life" | "their life total" => Some(if scope.is_each_loop_player() {
                    PlayerRef::EachLoopPlayer
                } else {
                    scope.last_player_ref().unwrap_or(PlayerRef::You)
                }),
                "your life" | "your life total" => Some(PlayerRef::You),
                _ => None,
            };
            if let Some(player) = pref {
                return Some(Amount::FractionalLifeLoss {
                    player,
                    denominator,
                    round,
                });
            }
        }
    }
    if low == "number of colors of mana spent to cast ~" {
        return Some(Amount::ColorsOfManaSpentToCast);
    }
    if low == "your ring-bearer's power" {
        return Some(Amount::RingBearerPower { player: None });
    }
    if low == "sacrificed creature's power" {
        return Some(Amount::SacrificedCostStat {
            stat: mtg_ir::SacrificedStatKind::Power,
        });
    }
    if let Some(stat) = match low.as_str() {
        "its power" | "their power" => Some(mtg_ir::StatKind::Power),
        "its toughness" | "their toughness" => Some(mtg_ir::StatKind::Toughness),
        "its mana value" | "their mana value" => Some(mtg_ir::StatKind::ManaValue),
        _ => None,
    } {
        let of = scope.it_ref().unwrap_or_else(|| {
            if scope.in_trigger_context() && !scope.has_prior_step() {
                Ref::EventObject
            } else {
                Ref::SelfObj
            }
        });
        let lki = !matches!(of, Ref::SelfObj) || scope.has_sac_step_or_trigger();
        return Some(Amount::Stat { of, stat, lki });
    }
    for (suf, stat) in [
        ("'s power", mtg_ir::StatKind::Power),
        ("’s power", mtg_ir::StatKind::Power),
        ("'s toughness", mtg_ir::StatKind::Toughness),
        ("’s toughness", mtg_ir::StatKind::Toughness),
        ("'s mana value", mtg_ir::StatKind::ManaValue),
        ("’s mana value", mtg_ir::StatKind::ManaValue),
    ] {
        let slen = suf.len();
        if t.len() > slen
            && t.is_char_boundary(t.len() - slen)
            && t[t.len() - slen..].eq_ignore_ascii_case(suf)
        {
            let ref_s = t[..t.len() - slen].trim();
            let rtoks = tokenize(ref_s, 0);
            if let Some((of, used)) = crate::parser::value::parse_ref(&rtoks, scope)
                && used == rtoks.len()
            {
                let lki = scope.has_sac_step_or_trigger()
                    || (!matches!(of, Ref::SelfObj)
                        && (scope.it_ref().is_some() || scope.in_trigger_context()));
                return Some(Amount::Stat { of, stat, lki });
            }
        }
    }
    if low == "mana value of the sacrificed permanent" {
        return Some(Amount::SacrificedCostStat {
            stat: mtg_ir::SacrificedStatKind::ManaValue,
        });
    }
    for (pref, stat) in [
        ("power of ", mtg_ir::StatKind::Power),
        ("toughness of ", mtg_ir::StatKind::Toughness),
        ("mana value of ", mtg_ir::StatKind::ManaValue),
    ] {
        if stripped.len() > pref.len()
            && stripped.is_char_boundary(pref.len())
            && stripped[..pref.len()].eq_ignore_ascii_case(pref)
        {
            let ref_s = stripped[pref.len()..].trim();
            let rtoks = tokenize(ref_s, 0);
            if let Some((of, used)) = crate::parser::value::parse_ref(&rtoks, scope)
                && used == rtoks.len()
            {
                let lki = scope.has_sac_step_or_trigger()
                    || (!matches!(of, Ref::SelfObj)
                        && (scope.it_ref().is_some() || scope.in_trigger_context()));
                return Some(Amount::Stat { of, stat, lki });
            }
        }
    }
    if low == "total mana value of those cards" && scope.has_mill_step() {
        return Some(Amount::CountedThisWay {
            kind: CountedThisWayKind::MilledTotalManaValue,
        });
    }
    if (low == "total mana value of those cards"
        || low == "the total mana value of those cards"
        || low == "their total mana value")
        && !scope.has_mill_step()
        && let Some(Ref::Target { index }) = scope.it_ref()
    {
        return Some(Amount::TotalManaValueOfTargetSpec { index });
    }
    if low == "opponents you have"
        || low == "opponent you have"
        || low == "number of opponents you have"
        || low == "opponents"
    {
        return Some(Amount::OpponentCount);
    }
    if low == "number of counters on it" || low == "number of counters on ~" {
        let of_ref = scope.it_ref().unwrap_or(Ref::SelfObj);
        return Some(Amount::CountersOn {
            counter: CounterTarget::Any,
            of: of_ref,
        });
    }
    if let Some(after) = strip_prefix_word_ci(stripped, "number of counters among") {
        if let Some((base_s, rel)) = strip_suffix_word_ci(after, "target player controls")
            .map(|b| (b, PlayerRelation::Any))
            .or_else(|| {
                strip_suffix_word_ci(after, "target opponent controls")
                    .map(|b| (b, PlayerRelation::Opponent))
            })
        {
            let btoks = tokenize(base_s.trim(), 0);
            let cp = ctx.interner.checkpoint();
            if let Some((mut f, used)) = parse_object_filter(
                &btoks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::BATTLEFIELD,
                    allow_plural_and_disjunction: true,
                    ..Default::default()
                },
                scope,
            ) && used == btoks.len()
                && f.controller.is_none()
                && let Some(idx) = scope.alloc_target(TargetSpec {
                    kind: TargetKind::Player,
                    player: Some(PlayerFilter { relation: rel }),
                    min: 1,
                    max: 1,
                    ..default_target_spec()
                })
            {
                f.zones = ZoneMask::empty();
                return Some(Amount::CountersAmongControlled {
                    filter: Box::new(f),
                    player: PlayerRef::Target { index: idx },
                });
            }
            ctx.interner.rollback(cp);
        }
        let ftoks = tokenize(after, 0);
        if let Some((mut f, used)) = parse_object_filter(
            &ftoks,
            ctx,
            FilterOpts {
                default_zone: ZoneMask::BATTLEFIELD,
                allow_plural_and_disjunction: true,
                ..Default::default()
            },
            scope,
        ) && used == ftoks.len()
        {
            f.zones = ZoneMask::BATTLEFIELD;
            return Some(Amount::TotalCountersAmong {
                filter: Box::new(f),
            });
        }
    }
    if let Some(after) = strip_prefix_word_ci(stripped, "for each") {
        if let Some(on_pos) =
            find_word_ci(after, " counters on ").or_else(|| find_word_ci(after, " counter on "))
        {
            let word_len = if after[on_pos..].len() >= " counters on ".len()
                && after[on_pos..on_pos + " counters on ".len()]
                    .eq_ignore_ascii_case(" counters on ")
            {
                " counters on ".len()
            } else {
                " counter on ".len()
            };
            let ctr_raw = after[..on_pos].trim();
            let obj_raw = after[on_pos + word_len..].trim();
            let counter = if ctr_raw.is_empty() {
                Some(CounterTarget::Any)
            } else {
                normalize_counter_name(ctr_raw)
                    .map(|name| CounterTarget::Specific(ctx.interner.intern_counter(&name)))
            };
            let of_ref = if eq_ci(obj_raw, "it") {
                Some(scope.it_ref().unwrap_or_else(|| {
                    if scope.in_trigger_context() && !scope.has_prior_step() {
                        Ref::EventObject
                    } else {
                        Ref::SelfObj
                    }
                }))
            } else if eq_ci(obj_raw, "~")
                || eq_ci(obj_raw, "this creature")
                || eq_ci(obj_raw, "this artifact")
                || eq_ci(obj_raw, "this enchantment")
                || eq_ci(obj_raw, "this permanent")
            {
                Some(Ref::SelfObj)
            } else {
                None
            };
            if let (Some(counter), Some(of)) = (counter, of_ref) {
                return Some(Amount::CountersOn { counter, of });
            }
        }
        if let Some(att_pos) = find_word_ci(after, " attached to ") {
            let left = after[..att_pos].trim();
            let right = after[att_pos + " attached to ".len()..].trim();
            let owner_target = if eq_ci(right, "~")
                || eq_ci(right, "this creature")
                || eq_ci(right, "this artifact")
                || eq_ci(right, "this enchantment")
                || eq_ci(right, "this permanent")
            {
                Some(mtg_ir::AttachmentOwnerTarget::SelfObj)
            } else if eq_ci(right, "equipped creature")
                || eq_ci(right, "enchanted creature")
                || eq_ci(right, "enchanted permanent")
            {
                Some(mtg_ir::AttachmentOwnerTarget::AttachedTo)
            } else if eq_ci(right, "it") {
                Some(
                    if scope.it_ref() == Some(Ref::AttachedTo)
                        || (scope.it_ref().is_none()
                            && matches!(
                                scope.default_pronoun_subject(),
                                PronounSubject::AttachedTo
                            ))
                    {
                        mtg_ir::AttachmentOwnerTarget::AttachedTo
                    } else {
                        mtg_ir::AttachmentOwnerTarget::SelfObj
                    },
                )
            } else {
                None
            };
            if let Some(target) = owner_target {
                if eq_ci(left, "permanent") || eq_ci(left, "card") || left.is_empty() {
                    return Some(Amount::AttachmentsOn {
                        target,
                        filter: None,
                    });
                }
                let ftoks = tokenize(left, 0);
                if let Some((mut f, used)) = parse_object_filter(
                    &ftoks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::BATTLEFIELD,
                        allow_plural_and_disjunction: true,
                        ..Default::default()
                    },
                    scope,
                ) && used == ftoks.len()
                {
                    f.zones = ZoneMask::BATTLEFIELD;
                    return Some(Amount::AttachmentsOn {
                        target,
                        filter: Some(Box::new(f)),
                    });
                }
            }
        }
        if let Some((base_s, rel)) = strip_suffix_word_ci(after, "target opponent controls")
            .map(|b| (b, PlayerRelation::Opponent))
            .or_else(|| {
                strip_suffix_word_ci(after, "target player controls")
                    .map(|b| (b, PlayerRelation::Any))
            })
        {
            let btoks = tokenize(base_s.trim(), 0);
            let cp = ctx.interner.checkpoint();
            if let Some((mut f, used)) = parse_object_filter(
                &btoks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::BATTLEFIELD,
                    allow_plural_and_disjunction: true,
                    ..Default::default()
                },
                scope,
            ) && used == btoks.len()
                && f.controller.is_none()
                && let Some(idx) = scope.alloc_target(TargetSpec {
                    kind: TargetKind::Player,
                    player: Some(PlayerFilter { relation: rel }),
                    min: 1,
                    max: 1,
                    ..default_target_spec()
                })
            {
                if f.zones.is_empty() {
                    f.zones = ZoneMask::BATTLEFIELD;
                }
                f.extra.push(ObjectPredicate::ControllerRef {
                    player: PlayerRef::Target { index: idx },
                });
                return Some(Amount::Count { of: Box::new(f) });
            }
            ctx.interner.rollback(cp);
        }
        let ftoks = tokenize(after, 0);
        if let Some((mut f, used)) = parse_object_filter(
            &ftoks,
            ctx,
            FilterOpts {
                default_zone: ZoneMask::BATTLEFIELD,
                allow_plural_and_disjunction: true,
                ..Default::default()
            },
            scope,
        ) && used == ftoks.len()
        {
            if f.zones.is_empty() {
                f.zones = ZoneMask::BATTLEFIELD;
            }
            return Some(Amount::Count { of: Box::new(f) });
        }
    }
    None
}

fn parse_wave_condition_str(
    raw: &str,
    ctx: &mut ParseCtx<'_>,
    scope: &mut dyn ParserScope,
) -> Option<Condition> {
    let t = trim_trailing_period(raw);
    let body = strip_prefix_word_ci(t, "if").unwrap_or(t);
    if body.eq_ignore_ascii_case("~ was cast from your hand")
        || body.eq_ignore_ascii_case("this spell was cast from your hand")
    {
        Some(Condition::SpellCastFromZone { zone: Zone::Hand })
    } else if body.eq_ignore_ascii_case("~ was cast from a graveyard")
        || body.eq_ignore_ascii_case("this spell was cast from a graveyard")
    {
        Some(Condition::SpellCastFromZone {
            zone: Zone::Graveyard,
        })
    } else if body.eq_ignore_ascii_case("~ was cast from exile")
        || body.eq_ignore_ascii_case("this spell was cast from exile")
    {
        Some(Condition::SpellCastFromZone { zone: Zone::Exile })
    } else if body.eq_ignore_ascii_case("~ was kicked")
        || body.eq_ignore_ascii_case("this spell was kicked")
    {
        Some(Condition::Kicked {
            tag: None,
            min_count: None,
        })
    } else if starts_with_ci(body, "~ was cast using ")
        || starts_with_ci(body, "this spell was cast using ")
        || starts_with_ci(body, "it was cast using ")
    {
        let tag = rfind_ascii_ci(body.as_bytes(), b" cast using ")
            .and_then(|pos| body.get(pos + " cast using ".len()..))
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_ascii_lowercase);
        tag.map(|t| Condition::Kicked {
            tag: Some(t),
            min_count: None,
        })
    } else if body.eq_ignore_ascii_case("you control a commander")
        || body.eq_ignore_ascii_case("you control a commander as you cast this spell")
        || body.eq_ignore_ascii_case("you control a commander as you cast ~")
    {
        Some(Condition::ControlCommander)
    } else if body.eq_ignore_ascii_case("the gift was promised") {
        Some(Condition::GiftPromised)
    } else if body.eq_ignore_ascii_case("you haven't cast a spell this turn") {
        Some(Condition::NoSpellCastThisTurn)
    } else if body.eq_ignore_ascii_case("you played a land this turn") {
        Some(Condition::PlayedLandThisTurn)
    } else if body.eq_ignore_ascii_case("you didn't draw cards this way") {
        Some(Condition::NotDrawnCardsThisWay)
    } else if body.eq_ignore_ascii_case("you revealed it this way") {
        Some(Condition::DidRevealThisWay)
    } else if body.eq_ignore_ascii_case("a creature card was discarded this way") {
        Some(Condition::DiscardedCreatureThisWay)
    } else if body.eq_ignore_ascii_case("a noncreature card was discarded this way") {
        Some(Condition::DiscardedNoncreatureThisWay)
    } else if body.eq_ignore_ascii_case("the discarded card wasn't a land card") {
        Some(Condition::DiscardedNonlandThisWay)
    } else if body.eq_ignore_ascii_case("a land card was milled this way") {
        Some(Condition::LandCardMilledThisWay)
    } else if body.eq_ignore_ascii_case("the player mills at least one creature card this way") {
        Some(Condition::CreatureCardMilledThisWay)
    } else if body.eq_ignore_ascii_case("a nonland permanent is sacrificed this way") {
        Some(Condition::SacrificedNonlandThisWay)
    } else if body.eq_ignore_ascii_case("you don't put the card onto the battlefield") {
        Some(Condition::DidntPutOntoBattlefieldThisWay)
    } else if body.eq_ignore_ascii_case("you cast a creature spell this way") {
        Some(Condition::CastTriggerCreatureSpell)
    } else if body.eq_ignore_ascii_case("you control an attacking legendary creature") {
        Some(Condition::ControlAttackingLegendary)
    } else if body
        .eq_ignore_ascii_case("there are three or more card types among the sacrificed permanents")
        || body.eq_ignore_ascii_case(
            "there were three or more card types among the sacrificed permanents",
        )
    {
        Some(Condition::DistinctCardTypesAmongSacrificedAtLeast { min: 3 })
    } else if body.eq_ignore_ascii_case("two or more cards are exiled this way") {
        Some(Condition::ExiledCountAtLeast { min: 2 })
    } else if body.eq_ignore_ascii_case("it's the first combat phase of your turn")
        || body.eq_ignore_ascii_case("it's the first combat phase of the turn")
        || body.eq_ignore_ascii_case("this is the first combat phase of the turn")
    {
        Some(Condition::FirstCombatPhaseOfTurn)
    } else if body.eq_ignore_ascii_case("it's your turn") {
        Some(Condition::IsYourTurn)
    } else if body.eq_ignore_ascii_case("its power is greater than each other creature's power") {
        Some(Condition::EventObjectGreatestPowerAmongAll)
    } else if body.eq_ignore_ascii_case("you won the clash") || body.eq_ignore_ascii_case("you win")
    {
        Some(Condition::WonClashThisWay)
    } else if body.eq_ignore_ascii_case("that player has more cards in hand than you") {
        Some(Condition::OpponentHasMoreCardsInHandThan {
            who: scope.last_player_ref().unwrap_or(PlayerRef::You),
        })
    } else if body.eq_ignore_ascii_case("you have fewer than seven cards in hand") {
        Some(Condition::PlayerHasFewerHandThan {
            target_player: None,
            max: Some(7),
        })
    } else if body.eq_ignore_ascii_case("target player has fewer than nine poison counters") {
        Some(Condition::TargetHasFewerCountersThan {
            counter: PlayerCounterKind::Poison,
            max: 9,
        })
    } else {
        if let Some(after) = strip_prefix_word_ci(body, "the exiled card's mana value is ")
            && let Some(num_s) = strip_suffix_word_ci(after, "or greater")
            && let Some(n) = parse_small_number(num_s)
        {
            return Some(Condition::Compare {
                left: Box::new(Amount::Stat {
                    of: Ref::EventObject,
                    stat: mtg_ir::StatKind::ManaValue,
                    lki: true,
                }),
                op: mtg_ir::CompareOp::Ge,
                right: Box::new(Amount::Const { n }),
            });
        }
        if let Some((of_ref, after)) = strip_prefix_word_ci(body, "~ has power ")
            .map(|r| (Ref::SelfObj, r))
            .or_else(|| {
                strip_prefix_word_ci(body, "it has power ")
                    .map(|r| (scope.it_ref().unwrap_or(Ref::SelfObj), r))
            })
            && let Some(num_s) = strip_suffix_word_ci(after, "or greater")
            && let Some(n) = parse_small_number(num_s)
        {
            return Some(Condition::Compare {
                left: Box::new(Amount::Stat {
                    of: of_ref,
                    stat: mtg_ir::StatKind::Power,
                    lki: false,
                }),
                op: mtg_ir::CompareOp::Ge,
                right: Box::new(Amount::Const { n }),
            });
        }
        if let Some((of_ref, after)) = strip_prefix_word_ci(body, "~ has toughness ")
            .map(|r| (Ref::SelfObj, r))
            .or_else(|| {
                strip_prefix_word_ci(body, "it has toughness ")
                    .map(|r| (scope.it_ref().unwrap_or(Ref::SelfObj), r))
            })
            && let Some(num_s) = strip_suffix_word_ci(after, "or greater")
            && let Some(n) = parse_small_number(num_s)
        {
            return Some(Condition::Compare {
                left: Box::new(Amount::Stat {
                    of: of_ref,
                    stat: mtg_ir::StatKind::Toughness,
                    lki: false,
                }),
                op: mtg_ir::CompareOp::Ge,
                right: Box::new(Amount::Const { n }),
            });
        }
        if body.eq_ignore_ascii_case("that creature has greater power than ~")
            || body.eq_ignore_ascii_case("that creature has greater power than this creature")
            || body.eq_ignore_ascii_case("it has greater power than ~")
        {
            let lhs_ref = scope.it_ref().unwrap_or(Ref::Target { index: 0 });
            let rhs_ref = match scope.default_pronoun_subject() {
                PronounSubject::AttachedTo => Ref::AttachedTo,
                PronounSubject::SelfObj => Ref::SelfObj,
            };
            return Some(Condition::Compare {
                left: Box::new(Amount::Stat {
                    of: lhs_ref,
                    stat: mtg_ir::StatKind::Power,
                    lki: false,
                }),
                op: mtg_ir::CompareOp::Gt,
                right: Box::new(Amount::Stat {
                    of: rhs_ref,
                    stat: mtg_ir::StatKind::Power,
                    lki: false,
                }),
            });
        }
        if let Some(after_ret) = strip_prefix_word_ci(body, "returned")
            && let Some(f_raw) = strip_suffix_word_ci(after_ret, "to your hand this way")
        {
            let clean = strip_prefix_word_ci(f_raw, "a")
                .or_else(|| strip_prefix_word_ci(f_raw, "an"))
                .unwrap_or(f_raw);
            let ftoks = tokenize(clean, 0);
            let cp = ctx.interner.checkpoint();
            if let Some((mut f, used)) = parse_object_filter(
                &ftoks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: true,
                    ..Default::default()
                },
                scope,
            ) && used == ftoks.len()
            {
                f.zones = ZoneMask::empty();
                return Some(Condition::ReturnedFilterToHandThisWay {
                    filter: Box::new(f),
                });
            }
            ctx.interner.rollback(cp);
        }
        if let Some(after_ctrl) =
            strip_prefix_word_ci(body, "you control the creature with the greatest")
                .or_else(|| strip_prefix_word_ci(body, "you control a creature with the greatest"))
        {
            let after_ctrl = strip_suffix_word_ci(after_ctrl, "among creatures on the battlefield")
                .or_else(|| strip_suffix_word_ci(after_ctrl, "on the battlefield"))
                .unwrap_or(after_ctrl);
            let stat = if eq_ci(after_ctrl, "power or tied for the greatest power")
                || eq_ci(after_ctrl, "power")
            {
                Some(mtg_ir::StatKind::Power)
            } else if eq_ci(after_ctrl, "toughness or tied for the greatest toughness")
                || eq_ci(after_ctrl, "toughness")
            {
                Some(mtg_ir::StatKind::Toughness)
            } else if eq_ci(after_ctrl, "mana value or tied for the greatest mana value")
                || eq_ci(after_ctrl, "mana value")
            {
                Some(mtg_ir::StatKind::ManaValue)
            } else {
                None
            };
            if let Some(stat) = stat {
                return Some(Condition::PlayerControlsFilter {
                    player: PlayerRef::You,
                    filter: Box::new(ObjectFilter {
                        types_any: CardTypeMask::CREATURE,
                        extra: vec![ObjectPredicate::GreatestStatAmongControlled {
                            stat,
                            scope_types: CardTypeMask::empty(),
                        }],
                        ..Default::default()
                    }),
                });
            }
        }
        if let Some(mid) =
            strip_suffix_word_ci(body, "entered the battlefield under your control this turn")
                .or_else(|| strip_suffix_word_ci(body, "entered under your control this turn"))
                .or_else(|| {
                    strip_prefix_word_ci(body, "you had ").and_then(|after_had| {
                        strip_suffix_word_ci(
                            after_had,
                            "enter the battlefield under your control this turn",
                        )
                        .or_else(|| {
                            strip_suffix_word_ci(after_had, "enter under your control this turn")
                        })
                    })
                })
            && let Some(f_raw) = strip_prefix_word_ci(mid, "one or more")
                .or_else(|| strip_prefix_word_ci(mid, "a"))
                .or_else(|| strip_prefix_word_ci(mid, "an"))
                .or_else(|| starts_with_word_ci(mid, "another").then_some(mid))
        {
            let cp = ctx.interner.checkpoint();
            if let Some(f) = crate::parser::trigger::parse_trigger_object_phrase(f_raw, ctx, false)
                && f.controller.is_none()
            {
                return Some(Condition::EnteredUnderYourControlThisTurn {
                    filter: Box::new(f),
                    min: None,
                });
            }
            ctx.interner.rollback(cp);
        }
        if let Some((is_neg, obj_s)) = strip_prefix_word_ci(body, "you don't control ")
            .map(|r| (true, r))
            .or_else(|| strip_prefix_word_ci(body, "you control ").map(|r| (false, r)))
        {
            let obj_toks = tokenize(obj_s.trim(), 0);
            if let Some((mut r, used)) = crate::parser::value::parse_ref(&obj_toks, scope)
                && used == obj_toks.len()
            {
                if obj_s.trim().eq_ignore_ascii_case("it")
                    && matches!(r, Ref::SelfObj)
                    && scope.it_ref().is_none()
                    && scope.in_trigger_context()
                {
                    r = Ref::EventObject;
                }
                let inner = Condition::MatchesFilter {
                    target: Some(r),
                    filter: Box::new(ObjectFilter {
                        controller: Some(RelativeControl::You),
                        ..Default::default()
                    }),
                    any: false,
                };
                return Some(if is_neg {
                    Condition::Not {
                        of: Box::new(inner),
                    }
                } else {
                    inner
                });
            }
        }
        if let Some(after) = strip_prefix_word_ci(body, "you attacked with ")
            && let Some(num_s) = strip_suffix_word_ci(after, "or more creatures this turn")
            && let Some(n) = parse_small_number(num_s)
        {
            return Some(Condition::CreaturesAttackedCountThisTurn { min: n as u16 });
        }
        if let Some(after) = strip_prefix_word_ci(body, "an opponent was dealt ")
            && let Some(num_s) = strip_suffix_word_ci(after, "or more damage this turn")
            && let Some(n) = parse_small_number(num_s)
        {
            return Some(Condition::PlayerLostLifeAtLeastThisTurn {
                min: n,
                opponent_only: true,
            });
        }
        if let Some(after) = strip_prefix_word_ci(body, "creatures you control have total power ")
            && let Some(num_s) = strip_suffix_word_ci(after, "or greater")
            && let Some(n) = parse_small_number(num_s)
        {
            return Some(Condition::Compare {
                left: Box::new(Amount::TotalStatAmong {
                    filter: Box::new(ObjectFilter {
                        zones: ZoneMask::BATTLEFIELD,
                        types_any: CardTypeMask::CREATURE,
                        controller: Some(RelativeControl::You),
                        ..Default::default()
                    }),
                    stat: mtg_ir::StatKind::Power,
                }),
                op: mtg_ir::CompareOp::Ge,
                right: Box::new(Amount::Const { n }),
            });
        }
        if body.eq_ignore_ascii_case("it's legendary")
            || body.eq_ignore_ascii_case("it is legendary")
            || body.eq_ignore_ascii_case("that creature is legendary")
            || body.eq_ignore_ascii_case("that permanent is legendary")
        {
            return Some(Condition::MatchesFilter {
                target: Some(scope.it_ref().unwrap_or(Ref::EventObject)),
                filter: Box::new(ObjectFilter {
                    supertypes_any: SupertypeMask::LEGENDARY,
                    ..Default::default()
                }),
                any: false,
            });
        }
        if body.eq_ignore_ascii_case("it was attacking")
            || body.eq_ignore_ascii_case("it is attacking")
            || body.eq_ignore_ascii_case("that creature was attacking")
            || body.eq_ignore_ascii_case("that creature is attacking")
        {
            return Some(Condition::MatchesFilter {
                target: Some(scope.it_ref().unwrap_or(Ref::EventObject)),
                filter: Box::new(ObjectFilter {
                    flags: FilterFlags::ATTACKING,
                    ..Default::default()
                }),
                any: false,
            });
        }
        if let Some(after_it) = strip_prefix_word_ci(body, "it's a")
            .or_else(|| strip_prefix_word_ci(body, "it's an"))
            .or_else(|| strip_prefix_word_ci(body, "it is a"))
            .or_else(|| strip_prefix_word_ci(body, "it is an"))
            .or_else(|| strip_prefix_word_ci(body, "that card is a"))
            .or_else(|| strip_prefix_word_ci(body, "that card is an"))
        {
            let ftoks = tokenize(after_it.trim(), 0);
            let cp = ctx.interner.checkpoint();
            if let Some((mut f, used)) = parse_object_filter(
                &ftoks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: true,
                    ..Default::default()
                },
                scope,
            ) && used == ftoks.len()
            {
                f.zones = ZoneMask::empty();
                return Some(Condition::MatchesFilter {
                    target: Some(scope.it_ref().unwrap_or(Ref::EventObject)),
                    filter: Box::new(f),
                    any: false,
                });
            }
            ctx.interner.rollback(cp);
        }
        None
    }
}

fn substitute_defined_x_in_amount(amt: &mut Amount, x_amt: &Amount) {
    match amt {
        Amount::X => *amt = x_amt.clone(),
        Amount::Negate { of } | Amount::Mul { of, .. } | Amount::Half { of, .. } => {
            substitute_defined_x_in_amount(of, x_amt);
        }
        Amount::Sum { args } | Amount::Min { args } | Amount::Max { args } => {
            for a in args {
                substitute_defined_x_in_amount(a, x_amt);
            }
        }
        Amount::Difference { left, right } => {
            substitute_defined_x_in_amount(left, x_amt);
            substitute_defined_x_in_amount(right, x_amt);
        }
        Amount::Conditional {
            then_amt, else_amt, ..
        } => {
            substitute_defined_x_in_amount(then_amt, x_amt);
            substitute_defined_x_in_amount(else_amt, x_amt);
        }
        _ => {}
    }
}

fn substitute_defined_x_in_steps(steps: &mut [EffectStep], x_amt: &Amount) {
    for st in steps {
        if let Some(ref mut a) = st.amount {
            substitute_defined_x_in_amount(a, x_amt);
        }
        if let Some(ref mut opt) = st.optional {
            for c in &mut opt.cost {
                match c {
                    mtg_ir::CostDef::PayLife { amount, .. } => {
                        substitute_defined_x_in_amount(amount, x_amt);
                    }
                    mtg_ir::CostDef::Sacrifice { count, .. }
                    | mtg_ir::CostDef::Discard { count, .. }
                    | mtg_ir::CostDef::ExileFrom { count, .. } => {
                        substitute_defined_x_in_amount(count, x_amt);
                    }
                    _ => {}
                }
            }
        }
        match &mut st.op {
            EffectOp::Pump {
                toughness: Some(t), ..
            } => {
                substitute_defined_x_in_amount(t, x_amt);
            }
            EffectOp::CreateToken {
                dynamic_pt: Some((pw, tg)),
                ..
            } => {
                substitute_defined_x_in_amount(pw, x_amt);
                substitute_defined_x_in_amount(tg, x_amt);
            }
            _ => {}
        }
    }
}

fn substitute_defined_x_in_cmp(cmp: &mut Option<mtg_ir::Compare>, x_amt: &Amount) {
    if let Some(c) = cmp {
        substitute_defined_x_in_amount(&mut c.value, x_amt);
    }
}

fn substitute_defined_x_in_targets(targets: &mut [TargetSpec], x_amt: &Amount) {
    for t in targets {
        if let Some(ref mut dc) = t.dynamic_count {
            substitute_defined_x_in_amount(dc, x_amt);
        }
        if let Some(ref mut dt) = t.divide_total {
            substitute_defined_x_in_amount(dt, x_amt);
        }
        substitute_defined_x_in_cmp(&mut t.filter.mana_value, x_amt);
        substitute_defined_x_in_cmp(&mut t.filter.power, x_amt);
        substitute_defined_x_in_cmp(&mut t.filter.toughness, x_amt);
    }
}

fn parse_core_imperative(
    raw: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let t = trim_trailing_period(raw);
    if t.is_empty() {
        return false;
    }

    let where_x = split_where_x_is(t);
    if let Some((left, x_expr)) = where_x {
        let uses_obj_pronoun = contains_word_ci(x_expr, "its")
            || contains_word_ci(x_expr, "their")
            || contains_word_ci(x_expr, "it")
            || contains_word_ci(x_expr, "them")
            || contains_word_ci(x_expr, "that creature")
            || contains_word_ci(x_expr, "that permanent")
            || contains_word_ci(x_expr, "that artifact")
            || contains_word_ci(x_expr, "that land")
            || contains_word_ci(x_expr, "that enchantment")
            || contains_word_ci(x_expr, "that token")
            || contains_word_ci(x_expr, "that card")
            || (contains_word_ci(x_expr, "that spell")
                && !state.trigger.is_some_and(|tr| {
                    matches!(tr.event, EventKind::Cast) && !state.has_prior_step()
                }));
        let uses_player_pronoun = contains_word_ci(x_expr, "they")
            || contains_word_ci(x_expr, "their")
            || contains_word_ci(x_expr, "that player");
        let trigger_owns_pronoun = state.in_trigger_context()
            && !state.has_prior_step()
            && !contains_word_ci(left, "target")
            && !contains_word_ci(left, "choose ");
        let needs_deferred =
            (uses_obj_pronoun && state.last_object.is_none() && !trigger_owns_pronoun)
                || (uses_player_pronoun && state.last_player.is_none());
        if !needs_deferred && let Some(x_amt) = parse_amount_str(x_expr, ctx, state) {
            let prev_x = state.defined_x.clone();
            state.defined_x = Some(x_amt.clone());
            let before = state.steps.len();
            let before_t = state.targets.len();
            let mark_x = state.mark(ctx);
            let ok = (parse_core_imperative(left, span, ctx, state)
                || parse_clauses_into(left, span.start, ctx, state))
                && state.steps.len() > before;
            if ok {
                substitute_defined_x_in_steps(&mut state.steps[before..], &x_amt);
                substitute_defined_x_in_targets(&mut state.targets[before_t..], &x_amt);
                return true;
            }
            state.defined_x = prev_x;
            state.rollback(mark_x, ctx);
        }
    }

    let prev_x = state.defined_x.clone();
    let before = state.steps.len();
    let before_t = state.targets.len();
    let mark = state.mark(ctx);
    if parse_core_imperative_inner(t, span, ctx, state) {
        if let Some(ref x_amt) = prev_x {
            substitute_defined_x_in_steps(&mut state.steps[before..], x_amt);
            substitute_defined_x_in_targets(&mut state.targets[before_t..], x_amt);
        }
        return true;
    }
    state.rollback(mark, ctx);

    // General ", where X is <expr>" fallback for sentences/clauses with defined X.
    // Parse `left` first if `x_expr` contains pronouns needing target/last_player resolution,
    // otherwise parse `x_expr` first and still substitute `Amount::X` on emitted steps.
    if let Some((left, x_expr)) = where_x {
        let before = state.steps.len();
        let before_t = state.targets.len();
        let mark_post = state.mark(ctx);
        if (parse_core_imperative(left, span, ctx, state)
            || parse_clauses_into(left, span.start, ctx, state))
            && state.steps.len() > before
            && let Some(x_amt) = parse_amount_str(x_expr, ctx, state)
        {
            state.defined_x = Some(x_amt.clone());
            substitute_defined_x_in_steps(&mut state.steps[before..], &x_amt);
            substitute_defined_x_in_targets(&mut state.targets[before_t..], &x_amt);
            return true;
        }
        state.rollback(mark_post, ctx);

        if let Some(x_amt) = parse_amount_str(x_expr, ctx, state) {
            let prev_x = state.defined_x.clone();
            state.defined_x = Some(x_amt.clone());
            let before = state.steps.len();
            let before_t = state.targets.len();
            let mark_x = state.mark(ctx);
            let ok = (parse_core_imperative(left, span, ctx, state)
                || parse_clauses_into(left, span.start, ctx, state))
                && state.steps.len() > before;
            if ok {
                substitute_defined_x_in_steps(&mut state.steps[before..], &x_amt);
                substitute_defined_x_in_targets(&mut state.targets[before_t..], &x_amt);
                return true;
            }
            state.defined_x = prev_x;
            state.rollback(mark_x, ctx);
        }
    }

    // Trailing conditional fallback: "<effect>[,] if <condition>"
    if let Some(if_pos) = find_word_ci(t, " if ")
        && if_pos > 0
    {
        let eff_part = t[..if_pos].trim_end_matches(',').trim();
        let cond_part = t[if_pos + 4..].trim();
        if !starts_with_word_ci(cond_part, "able")
            && !starts_with_word_ci(cond_part, "you do")
            && !starts_with_word_ci(cond_part, "you don't")
        {
            let prev_last_obj = state.last_object.clone();
            let before = state.steps.len();
            let mark2 = state.mark(ctx);
            if parse_core_imperative_inner(eff_part, span, ctx, state) && state.steps.len() > before
            {
                let after_last_obj = state.last_object.clone();
                let gate_it_ref = match &state.steps[before].subject {
                    Selector::Target { index } => Some((Ref::Target { index: *index }, before)),
                    Selector::Binding { name } => {
                        Some((Ref::Binding { name: name.clone() }, before))
                    }
                    Selector::SelfObj => Some((Ref::SelfObj, before)),
                    Selector::EventObject => Some((Ref::EventObject, before)),
                    Selector::AttachedTo => Some((Ref::AttachedTo, before)),
                    _ => prev_last_obj,
                };
                state.last_object = gate_it_ref;
                let cond_opt = parse_condition_str(cond_part, ctx, state);
                state.last_object = after_last_obj;
                if let Some(mut cond) = cond_opt {
                    if contains_ascii_ci(cond_part.as_bytes(), b"the exiled card")
                        && let Condition::Compare { left, .. } = &mut cond
                        && let Amount::Stat {
                            of: of_ref @ Ref::EventObject,
                            stat: mtg_ir::StatKind::ManaValue,
                            ..
                        } = left.as_mut()
                        && let Some(ex_idx) = state.steps[..before]
                            .iter()
                            .rposition(|s| matches!(s.op, EffectOp::Exile { .. }))
                    {
                        let b = if let Some(existing) = state.steps[ex_idx].bind_as.clone() {
                            existing
                        } else {
                            let name = state.alloc_bind_name("exiled");
                            state.steps[ex_idx].bind_as = Some(name.clone());
                            name
                        };
                        *of_ref = Ref::Binding { name: b };
                    }
                    for st in &mut state.steps[before..] {
                        attach_gate_condition(&mut st.gate, cond.clone());
                    }
                    return true;
                }
            }
            state.rollback(mark2, ctx);
        }
    }
    if let Some(un_pos) = find_word_ci(t, " unless ")
        && un_pos > 0
    {
        let eff_part = t[..un_pos].trim_end_matches(',').trim();
        let cond_part = t[un_pos + " unless ".len()..].trim();
        if !starts_with_word_ci(cond_part, "that player")
            && !starts_with_word_ci(cond_part, "they ")
            && !starts_with_word_ci(cond_part, "he or she")
            && !starts_with_word_ci(cond_part, "its controller")
            && !starts_with_word_ci(cond_part, "their controller")
            && !starts_with_word_ci(cond_part, "any player")
            && !starts_with_word_ci(cond_part, "any opponent")
            && !starts_with_word_ci(cond_part, "you pay")
        {
            let prev_last_obj = state.last_object.clone();
            let before = state.steps.len();
            let mark2 = state.mark(ctx);
            if parse_core_imperative_inner(eff_part, span, ctx, state) && state.steps.len() > before
            {
                let after_last_obj = state.last_object.clone();
                let gate_it_ref = match &state.steps[before].subject {
                    Selector::Target { index } => Some((Ref::Target { index: *index }, before)),
                    Selector::Binding { name } => {
                        Some((Ref::Binding { name: name.clone() }, before))
                    }
                    Selector::SelfObj => Some((Ref::SelfObj, before)),
                    Selector::EventObject => Some((Ref::EventObject, before)),
                    Selector::AttachedTo => Some((Ref::AttachedTo, before)),
                    _ => prev_last_obj,
                };
                state.last_object = gate_it_ref;
                let cond_opt = parse_condition_str(cond_part, ctx, state);
                state.last_object = after_last_obj;
                if let Some(cond) = cond_opt {
                    let neg = Condition::Not { of: Box::new(cond) };
                    for st in &mut state.steps[before..] {
                        attach_gate_condition(&mut st.gate, neg.clone());
                    }
                    return true;
                }
            }
            state.rollback(mark2, ctx);
        }
    }
    false
}

fn parse_core_imperative_inner(
    raw: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let t0 = trim_trailing_period(raw);
    let t = strip_prefix_word_ci(t0, "then,")
        .or_else(|| strip_prefix_word_ci(t0, "then"))
        .unwrap_or(t0);
    if t.is_empty() {
        return false;
    }

    let parse_have_clause = |have_body: &str,
                             make_optional: bool,
                             state: &mut ParserState<'_>,
                             ctx: &mut ParseCtx<'_>|
     -> bool {
        let have_trim = have_body.trim();
        let try_have = |cand: &str, state: &mut ParserState<'_>, ctx: &mut ParseCtx<'_>| -> bool {
            let before = state.steps.len();
            let mark = state.mark(ctx);
            if (parse_core_imperative(cand, span, ctx, state)
                || parse_clauses_into(cand, span.start, ctx, state))
                && state.steps.len() > before
            {
                if make_optional {
                    state.steps[before].optional = Some(OptionalSpec {
                        chooser: PlayerRef::You,
                        cost: Vec::new(),
                        mode: OptionalMode::DoIfPaid,
                    });
                    for extra_st in &mut state.steps[before + 1..] {
                        if extra_st.gate.is_none() {
                            extra_st.gate = Some(StepGate::IfPrecedingAccepted {
                                step_index: before as u16,
                            });
                        }
                    }
                    state.last_optional_step = Some(before);
                }
                return true;
            }
            state.rollback(mark, ctx);
            false
        };
        if try_have(have_trim, state, ctx) {
            return true;
        }
        for (inf, fin) in [
            (" deal ", " deals "),
            (" lose ", " loses "),
            (" gain ", " gains "),
            (" draw ", " draws "),
            (" discard ", " discards "),
            (" sacrifice ", " sacrifices "),
            (" mill ", " mills "),
            (" exile ", " exiles "),
            (" return ", " returns "),
            (" put ", " puts "),
            (" take ", " takes "),
            (" destroy ", " destroys "),
            (" tap ", " taps "),
            (" untap ", " untaps "),
            (" create ", " creates "),
            (" shuffle ", " shuffles "),
            (" fight ", " fights "),
            (" become ", " becomes "),
        ] {
            if let Some(pos) = find_word_ci(have_trim, inf) {
                let inflected = format!(
                    "{}{}{}",
                    &have_trim[..pos],
                    fin,
                    &have_trim[pos + inf.len()..]
                );
                if try_have(&inflected, state, ctx) {
                    return true;
                }
            }
        }
        false
    };

    if let Some(have_body) = strip_prefix_word_ci(t, "have")
        && parse_have_clause(have_body, false, state, ctx)
    {
        return true;
    }

    // Check leading optionality ("you may ...") at clause level
    if let Some(may_body) = strip_prefix_word_ci(t, "you may") {
        if let Some(have_body) = strip_prefix_word_ci(may_body, "have")
            && parse_have_clause(have_body, true, state, ctx)
        {
            return true;
        }
        let body_trim = may_body.trim();
        if (starts_with_word_ci(body_trim, "remove ")
            || ((starts_with_word_ci(body_trim, "tap ")
                || starts_with_word_ci(body_trim, "exile "))
                && !contains_word_ci(body_trim, "~")))
            && !contains_word_ci(body_trim, "target")
            && !contains_word_ci(body_trim, "up to")
            && !contains_word_ci(body_trim, "all")
            && !eq_ci(body_trim, "exile it")
            && !starts_with_word_ci(body_trim, "exile this ")
        {
            let cp = ctx.interner.checkpoint();
            let cost_p = crate::parser::cost::parse_cost_list(body_trim, span.start, ctx);
            if cost_p.defs.len() == 1
                && cost_p.unparsed.is_empty()
                && matches!(
                    cost_p.defs[0],
                    mtg_ir::CostDef::RemoveCounters { .. }
                        | mtg_ir::CostDef::TapOthers { .. }
                        | mtg_ir::CostDef::ExileFrom {
                            zone: Zone::Graveyard,
                            ..
                        }
                )
            {
                let is_exile_from = matches!(cost_p.defs[0], mtg_ir::CostDef::ExileFrom { .. });
                let is_tap_x = matches!(
                    &cost_p.defs[0],
                    mtg_ir::CostDef::TapOthers { count, .. } if matches!(**count, Amount::X)
                );
                let mut st = make_step(EffectOp::PayCost, Selector::None, span);
                st.optional = Some(OptionalSpec {
                    chooser: PlayerRef::You,
                    cost: cost_p.defs,
                    mode: OptionalMode::DoIfPaid,
                });
                let idx = state.steps.len();
                state.push_step(st, false);
                state.last_optional_step = Some(idx);
                if is_exile_from {
                    state.last_object = Some((Ref::EventObject, idx));
                }
                if is_tap_x {
                    state.defined_x = Some(Amount::CountedThisWay {
                        kind: CountedThisWayKind::TappedThisWay,
                    });
                }
                return true;
            }
            ctx.interner.rollback(cp);
        }
        // Defer optional modal/choice-cost cases only when sub-parse handles the imperative cleanly
        if !starts_with_word_ci(may_body, "pay")
            && !starts_with_word_ci(may_body, "have ")
            && !starts_with_word_ci(may_body, "choose ")
            && !starts_with_word_ci(may_body, "cast ")
            && !starts_with_word_ci(may_body, "play ")
            && (!starts_with_word_ci(may_body, "discard ")
                || contains_word_ci(may_body, "any number"))
            && (!starts_with_word_ci(may_body, "exile ")
                || contains_word_ci(may_body, "target")
                || eq_ci(may_body, "exile it")
                || eq_ci(may_body, "exile ~")
                || starts_with_word_ci(may_body, "exile this "))
        {
            let before = state.steps.len();
            let mark = state.mark(ctx);
            let parsed_may = parse_core_imperative(may_body, span, ctx, state) || {
                if starts_with_word_ci(may_body, "reveal ")
                    && let Some(and_pos) = find_word_ci(may_body, " and ")
                    && starts_with_word_ci(may_body[and_pos + 5..].trim(), "put ")
                {
                    state.rollback(mark.clone(), ctx);
                    let lhs = may_body[..and_pos].trim();
                    let rhs = may_body[and_pos + 5..].trim();
                    parse_core_imperative(lhs, span, ctx, state)
                        && parse_core_imperative(rhs, span, ctx, state)
                } else {
                    false
                }
            };
            if parsed_may && state.steps.len() > before {
                if !matches!(
                    &state.steps[before].op,
                    EffectOp::Move {
                        to: Some(Zone::Graveyard),
                        ..
                    }
                ) && (matches!(state.steps[before].subject, Selector::All { .. })
                    || (matches!(state.steps[before].subject, Selector::Binding { .. })
                        && matches!(
                            &state.steps[before].op,
                            EffectOp::Move { select, .. } if select.choice_count.is_some()
                        )))
                    && (starts_with_word_ci(may_body, "put ")
                        || starts_with_word_ci(may_body, "return ")
                        || starts_with_word_ci(may_body, "turn "))
                {
                    match &mut state.steps[before].op {
                        EffectOp::Move { select, .. }
                        | EffectOp::Bounce { select }
                        | EffectOp::TurnFace { select, .. } => {
                            select.up_to = true;
                            return true;
                        }
                        _ => {}
                    }
                }
                if matches!(state.steps[before].op, EffectOp::PunisherChoice { .. }) {
                    state.rollback(mark, ctx);
                } else {
                    let opt_spec = OptionalSpec {
                        chooser: PlayerRef::You,
                        cost: Vec::new(),
                        mode: OptionalMode::DoIfPaid,
                    };
                    if state.steps.len() == before + 2
                        && matches!(
                            state.steps[before].op,
                            EffectOp::Reveal {
                                look_only: false,
                                ..
                            }
                        )
                        && matches!(state.steps[before + 1].op, EffectOp::Move { .. })
                        && state.steps[before + 1].optional.is_none()
                    {
                        state.steps[before + 1].optional = Some(opt_spec.clone());
                    }
                    state.steps[before].optional = Some(opt_spec);
                    state.last_optional_step = Some(before);
                    return true;
                }
            } else {
                state.rollback(mark, ctx);
            }
        }
    }

    // Dispatch by first word (O(1) fast-reject for unrelated clauses)
    let first = t.split_whitespace().next().unwrap_or("");
    let mut first_buf = [0u8; 24];
    let first_low: &str = if first.is_ascii() && first.len() <= first_buf.len() {
        for (dst, &src) in first_buf[..first.len()].iter_mut().zip(first.as_bytes()) {
            *dst = src.to_ascii_lowercase();
        }
        // SAFETY: `first.is_ascii()` guarantees every byte in `first_buf[..first.len()]` is valid ASCII UTF-8.
        std::str::from_utf8(&first_buf[..first.len()]).unwrap_or("")
    } else {
        ""
    };

    match first_low {
        "draw" => {
            if parse_draw_clause(t, you_sel(), None, span, ctx, state) {
                return true;
            }
        }
        "gain" => {
            if let Some(amt) = parse_life_amount(t, "gain", ctx, state) {
                let mut st = make_step(
                    EffectOp::GainLife {
                        set_life_total: false,
                    },
                    you_sel(),
                    span,
                );
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
            if let Some(rest) = strip_prefix_word_ci(t, "gain control of") {
                return parse_gain_control_clause(rest, None, false, span, ctx, state);
            }
        }
        "lose" => {
            if let Some(amt) = parse_life_amount(t, "lose", ctx, state) {
                let mut st = make_step(EffectOp::LoseLife, you_sel(), span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "scry" => {
            let arg = strip_prefix_word_ci(t, "scry").unwrap_or("");
            if let Some(amt) = parse_amount_str(arg, ctx, state) {
                let mut st = make_step(EffectOp::Scry, you_sel(), span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "surveil" => {
            let arg = strip_prefix_word_ci(t, "surveil").unwrap_or("");
            if let Some(amt) = parse_amount_str(arg, ctx, state) {
                let mut st = make_step(EffectOp::Surveil, you_sel(), span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "fateseal" => {
            let arg = strip_prefix_word_ci(t, "fateseal").unwrap_or("");
            if let Some(amt) = parse_amount_str(arg, ctx, state) {
                let mut st = make_step(EffectOp::Fateseal, you_sel(), span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "mill" => return parse_mill_clause(t, you_sel(), None, span, ctx, state),
        "discard" => return parse_discard_clause(t, you_sel(), None, span, ctx, state),
        "investigate" => {
            let arg = strip_prefix_word_ci(t, "investigate").unwrap_or("").trim();
            let amt = if arg.is_empty() || eq_ci(arg, "once") {
                Amount::Const { n: 1 }
            } else if eq_ci(arg, "twice") {
                Amount::Const { n: 2 }
            } else if let Some(after_once) = strip_prefix_word_ci(arg, "once") {
                let Some(parsed) = parse_amount_str(after_once.trim(), ctx, state) else {
                    return false;
                };
                parsed
            } else if let Some(after_twice) = strip_prefix_word_ci(arg, "twice") {
                let Some(parsed) = parse_amount_str(after_twice.trim(), ctx, state) else {
                    return false;
                };
                Amount::Mul {
                    factor: 2,
                    of: Box::new(parsed),
                }
            } else if let Some(rest) =
                strip_suffix_word_ci(arg, "times").or_else(|| strip_suffix_word_ci(arg, "time"))
            {
                let Some(parsed) = parse_amount_str(rest, ctx, state) else {
                    return false;
                };
                parsed
            } else {
                let Some(parsed) = parse_amount_str(arg, ctx, state) else {
                    return false;
                };
                parsed
            };
            let mut st = make_step(EffectOp::Investigate, you_sel(), span);
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
        "proliferate" => {
            let arg = strip_prefix_word_ci(t, "proliferate").unwrap_or("");
            let amt = if arg.is_empty() {
                None
            } else if let Some(rest) =
                strip_suffix_word_ci(arg, "times").or_else(|| strip_suffix_word_ci(arg, "time"))
            {
                let Some(parsed) = parse_amount_str(rest, ctx, state) else {
                    return false;
                };
                Some(parsed)
            } else {
                return false;
            };
            let mut st = make_step(EffectOp::Proliferate, Selector::None, span);
            st.amount = amt.map(Box::new);
            state.push_step(st, false);
            return true;
        }
        "populate" => {
            if eq_ci(t, "populate") {
                state.push_step(make_step(EffectOp::Populate, you_sel(), span), false);
                return true;
            }
        }
        "forage" => {
            if eq_ci(t, "forage") {
                state.push_step(make_step(EffectOp::Forage, you_sel(), span), false);
                return true;
            }
        }
        "clash" => {
            if eq_ci(t, "clash with an opponent") {
                state.push_step(make_step(EffectOp::Clash, you_sel(), span), false);
                return true;
            }
        }
        "learn" => {
            if eq_ci(t, "learn") {
                state.push_step(make_step(EffectOp::Learn, you_sel(), span), false);
                return true;
            }
        }
        "amass" => return parse_amass_clause(t, span, ctx, state),
        "incubate" => {
            if let Some(arg) = strip_prefix_word_ci(t, "incubate")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let mut st = make_step(EffectOp::Incubate { count: None }, you_sel(), span);
                st.amount = Some(Box::new(amt));
                st.bind_as = Some(state.alloc_bind_name("incubated"));
                state.push_step(st, true);
                return true;
            }
        }
        "manifest" => {
            if eq_ci(t, "manifest dread") {
                let mut st = make_step(EffectOp::ManifestDread, you_sel(), span);
                st.bind_as = Some(state.alloc_bind_name("manifest"));
                state.push_step(st, true);
                return true;
            }
            if starts_with_word_ci(t, "manifest the top card of your library") {
                let mut st = make_step(
                    EffectOp::Manifest,
                    Selector::LibraryTop { player: None },
                    span,
                );
                st.amount = Some(Box::new(Amount::Const { n: 1 }));
                state.push_step(st, true);
                return true;
            }
            if let Some(after_eq) = strip_prefix_word_ci(
                t,
                "manifest a number of cards from the top of your library equal to",
            ) && let Some(amt) = parse_amount_str(after_eq, ctx, state)
            {
                let mut st = make_step(
                    EffectOp::Manifest,
                    Selector::LibraryTop { player: None },
                    span,
                );
                st.amount = Some(Box::new(amt));
                state.push_step(st, true);
                return true;
            }
        }
        "bolster" => {
            if let Some(arg) = strip_prefix_word_ci(t, "bolster")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let mut st = make_step(EffectOp::Bolster, you_sel(), span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "adapt" => {
            if let Some(arg) = strip_prefix_word_ci(t, "adapt")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let mut st = make_step(EffectOp::Adapt, Selector::SelfObj, span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "monstrosity" => {
            if let Some(arg) = strip_prefix_word_ci(t, "monstrosity")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let mut st = make_step(EffectOp::Monstrosity, Selector::SelfObj, span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "discover" => {
            if let Some(arg) = strip_prefix_word_ci(t, "discover")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let mut st = make_step(EffectOp::Discover, Selector::None, span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "endure" => {
            if let Some(arg) = strip_prefix_word_ci(t, "endure")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let mut st = make_step(EffectOp::Endure, Selector::SelfObj, span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "time" => {
            if eq_ci(t, "time travel") {
                state.push_step(make_step(EffectOp::TimeTravel, you_sel(), span), false);
                return true;
            }
        }
        "blight" => {
            if let Some(arg) = strip_prefix_word_ci(t, "blight")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let mut st = make_step(EffectOp::Blight, you_sel(), span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        "earthbend" => {
            if let Some(arg) = strip_prefix_word_ci(t, "earthbend")
                && let Some(amt) = parse_amount_str(arg, ctx, state)
            {
                let f = ObjectFilter {
                    zones: ZoneMask::BATTLEFIELD,
                    types_any: CardTypeMask::LAND,
                    controller: Some(RelativeControl::You),
                    ..Default::default()
                };
                let mut sp = default_target_spec();
                sp.filter = f;
                let idx = state.add_target(sp);
                let mut st = make_step(EffectOp::Earthbend, Selector::Target { index: idx }, span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, true);
                return true;
            }
        }
        "support" => {
            if let Some(arg) = strip_prefix_word_ci(t, "support") {
                let (max_n, dyn_amt, dyn_up_to) = if eq_ci(arg, "x") {
                    (
                        99u16,
                        Some(Box::new(state.defined_x.clone().unwrap_or(Amount::X))),
                        true,
                    )
                } else if let Some(Amount::Const { n }) = parse_amount_str(arg, ctx, state)
                    && n >= 1
                {
                    (n as u16, None, false)
                } else {
                    (0, None, false)
                };
                if max_n > 0 {
                    let mut f = ObjectFilter {
                        zones: ZoneMask::BATTLEFIELD,
                        types_any: CardTypeMask::CREATURE,
                        ..Default::default()
                    };
                    if matches!(
                        state.context,
                        AbilityContext::Triggered | AbilityContext::Activated
                    ) {
                        f.flags |= FilterFlags::OTHER;
                    }
                    let mut sp = default_target_spec();
                    sp.filter = f;
                    sp.min = 0;
                    sp.max = max_n;
                    sp.dynamic_count = dyn_amt;
                    sp.dynamic_up_to = dyn_up_to;
                    let idx = state.add_target(sp);
                    let plus_one = ctx.interner.intern_counter("+1/+1");
                    let mut st = make_step(
                        EffectOp::PutCounters {
                            counter: Some(plus_one),
                            multi_counters: Vec::new(),
                            select: SelectionMod::default(),
                            divided: false,
                            allow_exile_counters: false,
                            remove_instead_of_add: false,
                            copy_counters_from: None,
                            choose_counter_on_subject_and_add_one: false,
                            conditional_counter_on_type: None,
                            cast_bolas_bonus_loyalty: false,
                        },
                        Selector::Target { index: idx },
                        span,
                    );
                    st.amount = Some(Box::new(Amount::Const { n: 1 }));
                    state.push_step(st, true);
                    return true;
                }
            }
        }
        "exert" => {
            if eq_ci(t, "exert ~")
                || eq_ci(t, "exert ~ as it attacks")
                || eq_ci(t, "you may exert ~ as it attacks")
                || eq_ci(t, "exert it")
                || eq_ci(t, "exert it as it attacks")
            {
                let subj = if eq_ci(t, "exert it") || eq_ci(t, "exert it as it attacks") {
                    state
                        .it_ref()
                        .map(|r| ref_to_selector(&r))
                        .unwrap_or(Selector::SelfObj)
                } else {
                    Selector::SelfObj
                };
                state.push_step(make_step(EffectOp::Exert, subj, span), false);
                return true;
            }
        }
        "harness" => {
            if eq_ci(t, "harness ~") {
                state.push_step(make_step(EffectOp::Harness, Selector::SelfObj, span), false);
                return true;
            }
        }
        "transform" => {
            if let Some(arg) = strip_prefix_word_ci(t, "transform")
                && let Some(obj) = parse_object_selector(arg, ZoneMask::BATTLEFIELD, ctx, state)
            {
                state.push_step(
                    make_step(EffectOp::Transform, obj.into_selector(), span),
                    true,
                );
                return true;
            }
        }
        "convert" => {
            if let Some(arg) = strip_prefix_word_ci(t, "convert")
                && let Some(obj) = parse_object_selector(arg, ZoneMask::BATTLEFIELD, ctx, state)
            {
                state.push_step(
                    make_step(EffectOp::Convert, obj.into_selector(), span),
                    true,
                );
                return true;
            }
        }
        "destroy" => {
            if parse_destroy_clause(t, span, ctx, state) {
                return true;
            }
        }
        "exile" => {
            if parse_exile_clause(t, span, ctx, state) {
                return true;
            }
        }
        "return" => {
            if parse_return_clause(t, span, ctx, state) {
                return true;
            }
        }
        "sacrifice" => {
            if parse_sacrifice_clause(t, you_sel(), None, span, ctx, state) {
                return true;
            }
        }
        "tap" => {
            if parse_tap_untap_clause(t, true, span, ctx, state) {
                return true;
            }
        }
        "untap" => {
            if parse_tap_untap_clause(t, false, span, ctx, state) {
                return true;
            }
        }
        "counter" => {
            if parse_counter_spell_clause(t, span, ctx, state) {
                return true;
            }
        }
        "put" => {
            if parse_put_clause(t, span, ctx, state) {
                return true;
            }
        }
        "remove" => {
            if parse_remove_clause(t, span, ctx, state) {
                return true;
            }
        }
        "move" => {
            if parse_move_counters_clause(t, span, ctx, state) {
                return true;
            }
        }
        "regenerate" => {
            if let Some(arg) = strip_prefix_word_ci(t, "regenerate")
                && let Some(obj) = parse_object_selector(arg, ZoneMask::BATTLEFIELD, ctx, state)
            {
                state.push_step(
                    make_step(EffectOp::Regenerate, obj.into_selector(), span),
                    true,
                );
                return true;
            }
        }
        "goad" => {
            if let Some(arg) = strip_prefix_word_ci(t, "goad") {
                let (subj_raw, dur) = parse_duration_suffix(arg);
                if let Some(obj) =
                    parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state)
                {
                    state.push_step(
                        make_step(
                            EffectOp::Goad {
                                duration: dur.or(Some(Duration::UntilYourNextTurn)),
                            },
                            obj.into_selector(),
                            span,
                        ),
                        true,
                    );
                    return true;
                }
            }
        }
        "detain" => {
            if let Some(arg) = strip_prefix_word_ci(t, "detain")
                && let Some(obj) = parse_object_selector(arg, ZoneMask::BATTLEFIELD, ctx, state)
            {
                state.push_step(make_step(EffectOp::Detain, obj.into_selector(), span), true);
                return true;
            }
        }
        "suspect" => {
            if let Some(arg) = strip_prefix_word_ci(t, "suspect")
                && let Some(obj) = parse_object_selector(arg, ZoneMask::BATTLEFIELD, ctx, state)
            {
                state.push_step(
                    make_step(
                        EffectOp::Suspect { unsuspect: false },
                        obj.into_selector(),
                        span,
                    ),
                    true,
                );
                return true;
            }
        }
        "attach" => {
            if parse_attach_clause(t, span, ctx, state) {
                return true;
            }
        }
        "prevent" => {
            if parse_prevent_damage_clause(t, span, ctx, state) {
                return true;
            }
        }
        "shuffle" => {
            if parse_shuffle_clause(t, span, ctx, state) {
                return true;
            }
        }
        "double" => {
            if parse_double_or_triple_clause(t, 2, span, ctx, state) {
                return true;
            }
        }
        "triple" => {
            if parse_double_or_triple_clause(t, 3, span, ctx, state) {
                return true;
            }
        }
        "exchange" => {
            if parse_exchange_clause(t, span, ctx, state) {
                return true;
            }
        }
        "switch" => {
            if parse_switch_pt_clause(t, span, ctx, state) {
                return true;
            }
        }
        "create" => {
            if parse_token_creation_clause(t, span, ctx, state)
                || parse_emblem_clause(t, span, state)
            {
                return true;
            }
        }
        "add" => {
            if parse_add_mana_sentence(t, span, ctx, state) {
                return true;
            }
        }
        "reveal" => {
            if parse_reveal_clause(t, you_sel(), None, span, ctx, state) {
                return true;
            }
        }
        "look" => {
            if parse_look_clause(t, you_sel(), None, span, ctx, state)
                || parse_exile_clause(t, span, ctx, state)
            {
                return true;
            }
        }
        "search" => {
            if parse_search_clause(t, you_sel(), None, span, ctx, state) {
                return true;
            }
        }
        "flip" => {
            if parse_flip_coin_clause(t, span, ctx, state) {
                return true;
            }
        }
        "roll" => {
            if parse_roll_die_clause(t, span, ctx, state) {
                return true;
            }
        }
        "take" => {
            if eq_ci(t, "take the initiative") {
                state.push_step(make_step(EffectOp::TakeInitiative, you_sel(), span), false);
                return true;
            }
            if eq_ci(t, "take an extra turn after this one") {
                state.push_step(make_step(EffectOp::ExtraTurn, you_sel(), span), false);
                return true;
            }
        }
        "venture" => {
            if eq_ci(t, "venture into the dungeon") {
                state.push_step(
                    make_step(
                        EffectOp::VentureIntoDungeon { undercity: false },
                        you_sel(),
                        span,
                    ),
                    false,
                );
                return true;
            }
            if eq_ci(t, "venture into the undercity") {
                state.push_step(
                    make_step(
                        EffectOp::VentureIntoDungeon { undercity: true },
                        you_sel(),
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
        "end" => {
            if eq_ci(t, "end the turn") {
                state.push_step(
                    make_step(
                        EffectOp::EndTurn {
                            active_player_may: false,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            if eq_ci(t, "end the combat phase") {
                state.push_step(
                    make_step(EffectOp::EndCombatPhase, Selector::None, span),
                    false,
                );
                return true;
            }
        }
        "choose" => {
            if parse_choose_clause(t, span, ctx, state) {
                return true;
            }
        }
        "copy" => {
            if parse_copy_imperative(t, span, ctx, state) {
                return true;
            }
        }
        "deal" | "~" | "it" => {
            if parse_damage_or_object_predicate(t, span, ctx, state) {
                return true;
            }
        }
        "you" | "each" | "target" | "that" | "they" | "defending" | "any" | "up" | "another"
        | "its" | "their" => {
            if first_low == "you" && parse_exchange_clause(t, span, ctx, state) {
                return true;
            }
            if parse_player_or_object_subject_clause(t, span, ctx, state) {
                return true;
            }
        }
        "the" => {
            if eq_ci(t, "the ring tempts you") {
                state.push_step(make_step(EffectOp::TemptWithRing, you_sel(), span), false);
                return true;
            }
            if eq_ci(t, "the spell's controller may choose new targets for it") {
                state.push_step(
                    make_step(
                        EffectOp::RedirectTargets {
                            spec: RedirectTargetsSpec {
                                mode: RedirectMode::ChooseNewTargets,
                                force_target_self: false,
                            },
                        },
                        Selector::EventObject,
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
        "until" | "for" | "instead" | "when" | "whenever" | "at" | "if"
            if parse_add_mana_sentence(t, span, ctx, state)
                || parse_prefixed_or_conditional_clause(t, span, ctx, state) =>
        {
            return true;
        }
        _ => {}
    }

    // Fallback: try object predicate / player predicate / Wave 10-11 / trailing delayed phase clauses
    let may_be_prefixed_fallback =
        !matches!(
            first_low,
            "until" | "for" | "instead" | "when" | "whenever" | "at" | "if"
        ) && (matches!(first_low, "starting" | "each" | "an" | "otherwise,")
            || contains_ascii_ci(t.as_bytes(), b"at the beginning of ")
            || contains_ascii_ci(t.as_bytes(), b"at end of combat")
            || contains_ascii_ci(t.as_bytes(), b"at the end of "));
    parse_damage_or_object_predicate(t, span, ctx, state)
        || parse_player_or_object_subject_clause(t, span, ctx, state)
        || parse_wave10_11_sentence(t, span, ctx, state)
        || (may_be_prefixed_fallback && parse_prefixed_or_conditional_clause(t, span, ctx, state))
}

fn parse_life_amount(
    t: &str,
    verb: &str,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> Option<Amount> {
    let rest = strip_prefix_word_ci(t, verb)?;
    if let Some(for_pos) = find_word_ci(rest, " life for each ") {
        let base_raw = rest[..for_pos].trim();
        let per_raw = rest[for_pos + " life ".len()..].trim();
        if let Some(Amount::Const { n }) = parse_amount_str(base_raw, ctx, state)
            && let Some(per_amt) = parse_amount_str(per_raw, ctx, state)
        {
            if n == 1 {
                return Some(per_amt);
            }
            return Some(Amount::Mul {
                factor: n,
                of: Box::new(per_amt),
            });
        }
    }
    let (round_suf, base_rest) = if let Some(r) = strip_suffix_word_ci(rest, ", rounded up") {
        (Some(", rounded up"), r)
    } else if let Some(r) = strip_suffix_word_ci(rest, ", rounded down") {
        (Some(", rounded down"), r)
    } else {
        (None, rest)
    };
    if let Some(after_eq) = strip_prefix_word_ci(base_rest, "life equal to") {
        if let Some(suf) = round_suf {
            return parse_amount_str(&format!("{after_eq}{suf}"), ctx, state);
        }
        return parse_amount_str(after_eq, ctx, state);
    }
    let amt_raw = strip_suffix_word_ci(base_rest, "life")?;
    if amt_raw.is_empty() {
        return None;
    }
    if eq_ci(amt_raw, "that much") {
        return Some(resolve_that_many_amount(state));
    }
    if let Some(suf) = round_suf {
        return parse_amount_str(&format!("{amt_raw} life{suf}"), ctx, state);
    }
    parse_amount_str(amt_raw, ctx, state)
}

fn parse_draw_clause(
    t: &str,
    subj: Selector,
    actor: Option<PlayerRef>,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "draws").or_else(|| strip_prefix_word_ci(t, "draw"))
    else {
        return false;
    };
    let (up_to, after_up_to) = if let Some(r) = strip_prefix_word_ci(rest, "up to") {
        (true, r)
    } else {
        (false, rest)
    };
    let (reveal_drawn, body) = if let Some(r) = strip_suffix_word_ci(after_up_to, "and reveal it") {
        (true, r)
    } else {
        (false, after_up_to)
    };
    if let Some(for_each_rest) = strip_prefix_word_ci(body, "an additional card for each")
        .or_else(|| strip_prefix_word_ci(body, "a card for each"))
        .or_else(|| strip_prefix_word_ci(body, "cards for each"))
    {
        let full_expr = format!("for each {for_each_rest}");
        if let Some(amt) = parse_amount_str(&full_expr, ctx, state) {
            let mut st = make_step(
                EffectOp::Draw {
                    up_to,
                    reveal_drawn,
                },
                subj,
                span,
            );
            let _ = actor;
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
    }
    let amt = if eq_ci(body, "an additional card") {
        Some(Amount::Const { n: 1 })
    } else if let Some(plus_s) = strip_prefix_word_ci(body, "that many cards plus")
        .or_else(|| strip_prefix_word_ci(body, "that many card plus"))
    {
        parse_amount_str(plus_s, ctx, state).map(|plus_amt| Amount::Sum {
            args: vec![resolve_that_many_amount(state), plus_amt],
        })
    } else if let Some(eq_after) = strip_prefix_word_ci(body, "a number of cards equal to")
        .or_else(|| strip_prefix_word_ci(body, "cards equal to"))
    {
        parse_amount_str(eq_after, ctx, state)
    } else {
        let amt_raw = strip_suffix_word_ci(body, "cards")
            .or_else(|| strip_suffix_word_ci(body, "card"))
            .unwrap_or(body);
        if eq_ci(amt_raw, "a") || eq_ci(amt_raw, "an") {
            Some(Amount::Const { n: 1 })
        } else if eq_ci(amt_raw, "that many") {
            Some(resolve_that_many_amount(state))
        } else {
            parse_amount_str(amt_raw, ctx, state)
        }
    };
    if let Some(amt) = amt {
        let mut st = make_step(
            EffectOp::Draw {
                up_to,
                reveal_drawn,
            },
            subj,
            span,
        );
        let _ = actor;
        st.amount = Some(Box::new(amt));
        state.push_step(st, false);
        return true;
    }
    false
}

fn parse_mill_clause(
    t: &str,
    subj: Selector,
    actor: Option<PlayerRef>,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "mills").or_else(|| strip_prefix_word_ci(t, "mill"))
    else {
        return false;
    };
    let rest = strip_suffix_word_ci(rest, "for each 1 damage dealt to them")
        .or_else(|| strip_suffix_word_ci(rest, "for each 1 damage dealt to that player"));
    if let Some(unit_raw) = rest
        && (eq_ci(unit_raw, "a card") || eq_ci(unit_raw, "1 card"))
    {
        let mut st = make_step(EffectOp::Mill, subj, span);
        let _ = actor;
        st.amount = Some(Box::new(Amount::EventAmount));
        let b = state.alloc_bind_name("milled");
        st.bind_as = Some(b);
        state.push_step(st, true);
        return true;
    }
    let rest = strip_prefix_word_ci(t, "mills")
        .or_else(|| strip_prefix_word_ci(t, "mill"))
        .unwrap();
    let amt_raw = strip_suffix_word_ci(rest, "cards")
        .or_else(|| strip_suffix_word_ci(rest, "card"))
        .unwrap_or(rest);
    let amt_raw = if eq_ci(amt_raw, "a") {
        "1"
    } else if let Some(eq_after) = strip_prefix_word_ci(amt_raw, "cards equal to") {
        eq_after
    } else {
        amt_raw
    };
    if let Some(amt) = parse_amount_str(amt_raw, ctx, state) {
        let mut st = make_step(EffectOp::Mill, subj, span);
        let _ = actor;
        st.amount = Some(Box::new(amt));
        let b = state.alloc_bind_name("milled");
        st.bind_as = Some(b);
        state.push_step(st, true);
        return true;
    }
    false
}

fn parse_discard_clause(
    t: &str,
    subj: Selector,
    actor: Option<PlayerRef>,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if contains_word_ci(t, "their hand") || contains_word_ci(t, "your hand") {
        let mut body = t;
        let mut draw_that_many = false;
        let mut draw_after = None;
        for suf in [
            ", then draws that many cards",
            ", then draw that many cards",
            " and draws that many cards",
            " and draw that many cards",
        ] {
            if let Some(pre) = strip_suffix_word_ci(t, suf) {
                body = pre;
                draw_that_many = true;
                break;
            }
        }
        if !draw_that_many {
            for sep in [" and draws ", " and draw ", ", then draws ", ", then draw "] {
                if let Some(pos) = find_word_ci(t, sep) {
                    let pre = t[..pos].trim_end();
                    let rhs = t[pos + sep.len()..].trim();
                    let amt_raw = strip_suffix_word_ci(rhs, "cards")
                        .or_else(|| strip_suffix_word_ci(rhs, "card"))
                        .unwrap_or(rhs);
                    let amt_raw = if eq_ci(amt_raw, "a") { "1" } else { amt_raw };
                    if let Some(amt) = parse_amount_str(amt_raw, ctx, state) {
                        body = pre;
                        draw_after = Some(Box::new(amt));
                        break;
                    }
                }
            }
        }
        if starts_with_word_ci(body, "discard your hand")
            || starts_with_word_ci(body, "discards their hand")
            || starts_with_word_ci(body, "discard their hand")
        {
            let mut st = make_step(
                EffectOp::DiscardHand {
                    draw_that_many,
                    draw_after,
                },
                subj,
                span,
            );
            st.actor = actor;
            state.push_step(st, false);
            return true;
        }
    }

    let Some(rest) =
        strip_prefix_word_ci(t, "discards").or_else(|| strip_prefix_word_ci(t, "discard"))
    else {
        return false;
    };
    let (rest, unless_opt) = if let Some(pos) = find_word_ci(rest, " unless you ") {
        let l = rest[..pos].trim();
        let cost_str = rest[pos + " unless you ".len()..].trim();
        let cp_cost = crate::parser::cost::parse_cost_list(cost_str, span.start, ctx);
        if cp_cost.unparsed.is_empty() && !cp_cost.defs.is_empty() {
            (
                l,
                Some(OptionalSpec {
                    chooser: PlayerRef::You,
                    cost: cp_cost.defs,
                    mode: OptionalMode::DoUnlessPaid,
                }),
            )
        } else {
            (rest, None)
        }
    } else {
        (rest, None)
    };
    let (at_random, rest_body) = if let Some(r) = strip_suffix_word_ci(rest, "at random") {
        (true, r)
    } else {
        (false, rest)
    };
    let (up_to, rest_body) = if eq_ci(rest_body, "any number of cards") {
        let mut st = make_step(
            EffectOp::Discard {
                select: SelectionMod {
                    up_to: true,
                    at_random,
                    ..Default::default()
                },
            },
            subj,
            span,
        );
        let _ = actor;
        st.amount = Some(Box::new(Amount::Const { n: 99 }));
        state.push_step(st, false);
        return true;
    } else if let Some(r) = strip_prefix_word_ci(rest_body, "up to") {
        (true, r)
    } else {
        (false, rest_body)
    };
    if let Some(fe_pos) = find_word_ci(rest_body, " for each ")
        && {
            let fe_lhs = rest_body[..fe_pos].trim();
            eq_ci(fe_lhs, "a card") || eq_ci(fe_lhs, "cards") || eq_ci(fe_lhs, "card")
        }
        && let Some(amt) = parse_amount_str(
            &format!("for each {}", rest_body[fe_pos + 10..].trim()),
            ctx,
            state,
        )
    {
        let mut st = make_step(
            EffectOp::Discard {
                select: SelectionMod {
                    up_to,
                    at_random,
                    ..Default::default()
                },
            },
            subj,
            span,
        );
        let _ = actor;
        st.amount = Some(Box::new(amt));
        if unless_opt.is_some() {
            st.optional = unless_opt;
        } else {
            let b = state.alloc_bind_name("discarded");
            st.bind_as = Some(b);
        }
        state.push_step(st, true);
        return true;
    }
    let amt_raw = strip_suffix_word_ci(rest_body, "cards")
        .or_else(|| strip_suffix_word_ci(rest_body, "card"))
        .unwrap_or(rest_body);
    let amt_raw = if eq_ci(amt_raw, "a") || eq_ci(amt_raw, "an") || eq_ci(amt_raw, "it") {
        "1"
    } else {
        amt_raw
    };
    if let Some(amt) = parse_amount_str(amt_raw, ctx, state) {
        let mut st = make_step(
            EffectOp::Discard {
                select: SelectionMod {
                    up_to,
                    at_random,
                    ..Default::default()
                },
            },
            subj,
            span,
        );
        let _ = actor;
        st.amount = Some(Box::new(amt));
        if unless_opt.is_some() {
            st.optional = unless_opt;
        } else {
            let b = state.alloc_bind_name("discarded");
            st.bind_as = Some(b);
        }
        state.push_step(st, true);
        return true;
    }
    if let Some(after_oom) = strip_prefix_word_ci(rest_body, "one or more")
        && let Some(f) = parse_object_phrase(
            after_oom,
            ctx,
            FilterOpts {
                default_zone: ZoneMask::empty(),
                allow_plural_and_disjunction: true,
                strip_trailing_card: true,
                ..Default::default()
            },
        )
    {
        let mut st = make_step(
            EffectOp::Discard {
                select: SelectionMod {
                    up_to: true,
                    at_random,
                    filter: Some(Box::new(f)),
                    ..Default::default()
                },
            },
            subj,
            span,
        );
        let _ = actor;
        st.amount = Some(Box::new(Amount::Const { n: 99 }));
        if unless_opt.is_some() {
            st.optional = unless_opt;
        } else {
            let b = state.alloc_bind_name("discarded");
            st.bind_as = Some(b);
        }
        state.push_step(st, true);
        return true;
    }
    false
}

fn parse_amass_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "amass") else {
        return false;
    };
    let parts: Vec<&str> = rest.split_whitespace().collect();
    if parts.is_empty() {
        return false;
    }
    let (subtype, amt_str) = if parts.len() >= 2
        && let Some(amt) = parse_amount_str(parts.last().copied().unwrap_or(""), ctx, state)
    {
        let sub_word = parts[..parts.len() - 1].join(" ");
        let st = singular_subtype(&sub_word).unwrap_or(sub_word);
        (Some(ctx.interner.intern_subtype(&st)), amt)
    } else if let Some(amt) = parse_amount_str(rest, ctx, state) {
        (Some(ctx.interner.intern_subtype("Army")), amt)
    } else {
        return false;
    };
    let mut st = make_step(EffectOp::Amass { subtype }, you_sel(), span);
    st.amount = Some(Box::new(amt_str));
    state.push_step(st, true);
    true
}

fn parse_destroy_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "destroy") else {
        return false;
    };
    let (cant_regen, subj_raw) = if let Some(r) =
        strip_suffix_word_ci(rest, ". they can't be regenerated")
            .or_else(|| strip_suffix_word_ci(rest, ". it can't be regenerated"))
    {
        (true, r)
    } else {
        (false, rest)
    };
    if let Some(and_pos) = find_word_ci(subj_raw, " and all ") {
        let lhs_s = subj_raw[..and_pos].trim();
        let rhs_s_raw = subj_raw[and_pos + " and all ".len()..].trim();
        let rhs_s = if let Some(after_other) = strip_prefix_word_ci(rhs_s_raw, "other")
            && contains_word_ci(after_other, "with the same name as that")
        {
            after_other
        } else {
            rhs_s_raw
        };
        let mark = state.mark(ctx);
        let before = state.steps.len();
        let synth1 = format!("destroy {lhs_s}");
        let synth2 = format!("destroy all {rhs_s}");
        if parse_destroy_clause(&synth1, span, ctx, state)
            && parse_destroy_clause(&synth2, span, ctx, state)
        {
            if cant_regen {
                for st in &mut state.steps[before..] {
                    if let EffectOp::Destroy {
                        cant_be_regenerated,
                        ..
                    } = &mut st.op
                    {
                        *cant_be_regenerated = true;
                    }
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }
    if find_word_ci(subj_raw, "target").is_some()
        && (subj_raw.contains(',') || find_word_ci(subj_raw, " and target ").is_some())
    {
        let mut parts: Vec<&str> = Vec::new();
        for seg in subj_raw.split(',') {
            let s = seg.trim();
            if s.is_empty() {
                continue;
            }
            let s = strip_prefix_word_ci(s, "and").unwrap_or(s);
            if let Some(p) = find_word_ci(s, " and target ") {
                parts.push(s[..p].trim());
                parts.push(s[p + 5..].trim());
            } else {
                parts.push(s);
            }
        }
        if parts.len() >= 2 && parts.iter().all(|p| starts_with_word_ci(p, "target")) {
            let mark = state.mark(ctx);
            let before = state.steps.len();
            let mut ok = true;
            for p in parts {
                if !parse_destroy_clause(&format!("destroy {p}"), span, ctx, state) {
                    ok = false;
                    break;
                }
            }
            if ok {
                if cant_regen {
                    for st in &mut state.steps[before..] {
                        if let EffectOp::Destroy {
                            cant_be_regenerated,
                            ..
                        } = &mut st.op
                        {
                            *cant_be_regenerated = true;
                        }
                    }
                }
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    let obj = if let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state)
    {
        obj
    } else if let Some((all_s, is_lhs_power, rel_s)) = find_word_ci(subj_raw, " with power ")
        .map(|p| {
            (
                subj_raw[..p].trim(),
                true,
                subj_raw[p + " with power ".len()..].trim(),
            )
        })
        .or_else(|| {
            find_word_ci(subj_raw, " with toughness ").map(|p| {
                (
                    subj_raw[..p].trim(),
                    false,
                    subj_raw[p + " with toughness ".len()..].trim(),
                )
            })
        })
    {
        let mark = state.mark(ctx);
        let parsed = (|| -> Option<ParsedObj> {
            let (cmp_op, after_cmp) =
                if let Some(r) = strip_prefix_word_ci(rel_s, "greater than or equal to") {
                    (mtg_ir::CompareOp::Ge, r)
                } else if let Some(r) = strip_prefix_word_ci(rel_s, "less than or equal to") {
                    (mtg_ir::CompareOp::Le, r)
                } else if let Some(r) = strip_prefix_word_ci(rel_s, "greater than") {
                    (mtg_ir::CompareOp::Gt, r)
                } else {
                    let r = strip_prefix_word_ci(rel_s, "less than")?;
                    (mtg_ir::CompareOp::Lt, r)
                };
            let (tgt_s, rhs_stat) = if let Some(r) = strip_suffix_word_ci(after_cmp, "'s power") {
                (r, mtg_ir::StatKind::Power)
            } else {
                let r = strip_suffix_word_ci(after_cmp, "'s toughness")?;
                (r, mtg_ir::StatKind::Toughness)
            };
            let ParsedObj::All(mut filter) =
                parse_object_selector(all_s, ZoneMask::BATTLEFIELD, ctx, state)?
            else {
                return None;
            };
            let rhs_obj = parse_object_selector(tgt_s, ZoneMask::BATTLEFIELD, ctx, state)?;
            let rhs_ref = match rhs_obj {
                ParsedObj::SelfObj => Ref::SelfObj,
                ParsedObj::AttachedTo => Ref::AttachedTo,
                ParsedObj::EventObject => Ref::EventObject,
                ParsedObj::Target(index) => Ref::Target { index },
                ParsedObj::Binding(name) => Ref::Binding { name },
                ParsedObj::All(_) => return None,
            };
            let cmp = mtg_ir::Compare {
                op: cmp_op,
                value: Box::new(Amount::Stat {
                    of: rhs_ref,
                    stat: rhs_stat,
                    lki: false,
                }),
            };
            if is_lhs_power {
                filter.power = Some(cmp);
            } else {
                filter.toughness = Some(cmp);
            }
            Some(ParsedObj::All(filter))
        })();
        let Some(obj) = parsed else {
            state.rollback(mark, ctx);
            return false;
        };
        obj
    } else {
        return false;
    };
    let mut st = make_step(
        EffectOp::Destroy {
            cant_be_regenerated: cant_regen,
            select: SelectionMod::default(),
        },
        obj.into_selector(),
        span,
    );
    let b = state.alloc_bind_name("destroyed");
    st.bind_as = Some(b);
    state.push_step(st, true);
    true
}

fn parse_exile_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let rewritten_look: String;
    let t_eff = if starts_with_word_ci(t, "look at the top ") {
        let mut s = None;
        for (sep, fd) in [
            (", then exile it face down", true),
            (", then exile them face down", true),
            (" and exile those cards face down", true),
            (", then exile it", false),
            (", then exile them", false),
            (" and exile those cards", false),
        ] {
            if let Some(pre) = strip_suffix_word_ci(t, sep)
                && let Some(after_look) = strip_prefix_word_ci(pre, "look at")
            {
                s = Some(if fd {
                    format!("exile {after_look} face down")
                } else {
                    format!("exile {after_look}")
                });
                break;
            }
        }
        if let Some(rw) = s {
            rewritten_look = rw;
            rewritten_look.as_str()
        } else {
            t
        }
    } else {
        t
    };
    let Some(rest) = strip_prefix_word_ci(t_eff, "exile") else {
        return false;
    };

    // "exile the top N cards of [target player's | your] library [face down [and look at it]]"
    let (face_down, look_only, rest_fd) = if let Some(r) =
        strip_suffix_word_ci(rest, "face down and look at it")
            .or_else(|| strip_suffix_word_ci(rest, "face down and look at them"))
    {
        (true, true, r)
    } else if let Some(r) = strip_suffix_word_ci(rest, "face down") {
        (true, false, r)
    } else {
        (false, false, rest)
    };
    if let Some((amt_s, owner_s, is_single)) =
        if let Some(after_top) = strip_prefix_word_ci(rest_fd, "the top") {
            if let Some(pos) = find_word_ci(after_top, " cards of ") {
                Some((
                    after_top[..pos].trim(),
                    after_top[pos + " cards of ".len()..].trim(),
                    false,
                ))
            } else if let Some(owner) = strip_prefix_word_ci(after_top, "card of") {
                Some(("", owner, true))
            } else if eq_ci(after_top, "card") {
                Some(("", "your library", true))
            } else {
                strip_suffix_word_ci(after_top, "cards").map(|amt_s| (amt_s, "your library", false))
            }
        } else if let Some(after_num) =
            strip_prefix_word_ci(rest_fd, "a number of cards from the top of")
            && let Some(eq_pos) = find_word_ci(after_num, " equal to ")
        {
            Some((
                after_num[eq_pos + " equal to ".len()..].trim(),
                after_num[..eq_pos].trim(),
                false,
            ))
        } else {
            None
        }
    {
        let amt_opt = if is_single && amt_s.is_empty() {
            Some(Amount::Const { n: 1 })
        } else if !is_single {
            parse_amount_str(amt_s, ctx, state)
        } else {
            None
        };
        if let Some(amt) = amt_opt {
            if eq_ci(owner_s, "each player's library") || eq_ci(owner_s, "each opponent's library")
            {
                let players = if eq_ci(owner_s, "each opponent's library") {
                    LoopPlayersKind::EachOpponent
                } else {
                    LoopPlayersKind::EachPlayer
                };
                let mut inner = make_step(
                    EffectOp::Exile {
                        select: SelectionMod::default(),
                        duration: None,
                        until_source_leaves: false,
                        until_opponent_becomes_monarch: false,
                        exile_all_except_bottom: false,
                        face_down,
                        look_only,
                        exile_with_counters: None,
                    },
                    Selector::LibraryTop {
                        player: Some(PlayerRef::EachLoopPlayer),
                    },
                    span,
                );
                inner.amount = Some(Box::new(amt));
                inner.bind_as = Some("exiled".to_string());
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players,
                            steps: vec![inner],
                            choose_random_opponent: false,
                            exclude_attacked_last_combat: false,
                            exclude_event_player: false,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                state.last_object = Some((
                    Ref::Binding {
                        name: "exiled".to_string(),
                    },
                    state.steps.len().saturating_sub(1),
                ));
                return true;
            }
            let player = if eq_ci(owner_s, "your library") {
                None
            } else {
                let p_raw = strip_suffix_word_ci(owner_s, "'s library")
                    .or_else(|| strip_suffix_word_ci(owner_s, "library"))
                    .unwrap_or(owner_s);
                let p_lookup = if eq_ci(p_raw, "their") {
                    "that player"
                } else {
                    p_raw
                };
                let is_opp_turn_that_player = eq_ci(p_raw, "that player")
                    && state.last_player.is_none()
                    && state.trigger.is_some_and(|tr| {
                        tr.filter.during_turn == Some(mtg_ir::DuringTurnKind::Opponent)
                            && tr
                                .filter
                                .player
                                .as_ref()
                                .is_some_and(|pf| pf.relation == PlayerRelation::You)
                    });
                if is_opp_turn_that_player {
                    Some(PlayerRef::ActivePlayer)
                } else {
                    let Some(sel) = parse_player_selector(p_lookup, ctx, state) else {
                        return false;
                    };
                    match sel {
                        Selector::Target { index } => Some(PlayerRef::Target { index }),
                        Selector::PlayerRef { player } => Some(player),
                        Selector::Player {
                            filter:
                                PlayerFilter {
                                    relation: PlayerRelation::You,
                                },
                        } => Some(PlayerRef::You),
                        _ => None,
                    }
                }
            };
            let mut st = make_step(
                EffectOp::Exile {
                    select: SelectionMod::default(),
                    duration: None,
                    until_source_leaves: false,
                    until_opponent_becomes_monarch: false,
                    exile_all_except_bottom: false,
                    face_down,
                    look_only,
                    exile_with_counters: None,
                },
                Selector::LibraryTop { player },
                span,
            );
            st.amount = Some(Box::new(amt));
            st.bind_as = Some("exiled".to_string());
            state.push_step(st, true);
            return true;
        }
    }

    // "exile ... until ~ leaves the battlefield" / "until an opponent becomes the monarch"
    let (until_leaves, until_monarch, body_leaves) = if let Some(r) =
        strip_suffix_word_ci(rest_fd, "until ~ leaves the battlefield")
    {
        (true, false, r)
    } else if let Some(r) = strip_suffix_word_ci(rest_fd, "until an opponent becomes the monarch") {
        (false, true, r)
    } else {
        (false, false, rest_fd)
    };
    let (dur_body, dur) = parse_duration_suffix(body_leaves);
    let (with_counters, dur_body) = if contains_ascii_ci(dur_body.as_bytes(), b"counter") {
        let (wc, prefix) = extract_with_counters(dur_body, ctx);
        if wc.is_some()
            && (eq_ci(prefix, "~")
                || eq_ci(prefix, "it")
                || eq_ci(prefix, "that card")
                || eq_ci(prefix, "them")
                || ends_with_ci(prefix.as_bytes(), b"graveyard"))
        {
            (wc, prefix)
        } else {
            (None, dur_body)
        }
    } else {
        (None, dur_body)
    };
    if eq_ci(dur_body, "all graveyards")
        || eq_ci(dur_body, "all cards from all graveyards")
        || eq_ci(dur_body, "all cards in all graveyards")
    {
        let mut st = make_step(
            EffectOp::Exile {
                select: SelectionMod::default(),
                duration: if until_leaves || until_monarch {
                    None
                } else {
                    dur
                },
                until_source_leaves: until_leaves,
                until_opponent_becomes_monarch: until_monarch,
                exile_all_except_bottom: false,
                face_down,
                look_only: false,
                exile_with_counters: None,
            },
            Selector::All {
                filter: Box::new(ObjectFilter {
                    zones: ZoneMask::GRAVEYARD,
                    ..Default::default()
                }),
            },
            span,
        );
        st.bind_as = Some("exiled".to_string());
        state.push_step(st, true);
        return true;
    }
    if eq_ci(dur_body, "all opponents' graveyards")
        || eq_ci(dur_body, "all cards from all opponents' graveyards")
        || eq_ci(dur_body, "all cards from your opponents' graveyards")
    {
        let mut st = make_step(
            EffectOp::Exile {
                select: SelectionMod::default(),
                duration: if until_leaves || until_monarch {
                    None
                } else {
                    dur
                },
                until_source_leaves: until_leaves,
                until_opponent_becomes_monarch: until_monarch,
                exile_all_except_bottom: false,
                face_down,
                look_only: false,
                exile_with_counters: None,
            },
            Selector::All {
                filter: Box::new(ObjectFilter {
                    zones: ZoneMask::GRAVEYARD,
                    owner: Some(RelativeControl::Opponent),
                    ..Default::default()
                }),
            },
            span,
        );
        st.bind_as = Some("exiled".to_string());
        state.push_step(st, true);
        return true;
    }
    if let Some(after_bot) = strip_prefix_word_ci(dur_body, "all but the bottom card of")
        && let Some(who_raw) = strip_suffix_word_ci(after_bot, "'s library")
        && let Some(psel) = parse_player_selector(who_raw, ctx, state)
    {
        state.push_step(
            make_step(
                EffectOp::Exile {
                    select: SelectionMod::default(),
                    duration: if until_leaves || until_monarch {
                        None
                    } else {
                        dur
                    },
                    until_source_leaves: until_leaves,
                    until_opponent_becomes_monarch: until_monarch,
                    exile_all_except_bottom: true,
                    face_down,
                    look_only: false,
                    exile_with_counters: None,
                },
                psel,
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(owner_raw) = ["'s graveyard", "s' graveyards", "'s graveyards"]
        .iter()
        .find_map(|suf| {
            let db_low = dur_body.to_ascii_lowercase();
            db_low
                .ends_with(suf)
                .then(|| dur_body[..dur_body.len() - suf.len()].trim())
        })
        && let Some(psel) = parse_player_selector(owner_raw, ctx, state)
    {
        let mut f = ObjectFilter {
            zones: ZoneMask::GRAVEYARD,
            ..Default::default()
        };
        match psel {
            Selector::PlayerRef { player } => {
                f.extra.push(ObjectPredicate::ControllerRef { player });
            }
            Selector::Target { index } => {
                f.extra.push(ObjectPredicate::ControllerRef {
                    player: PlayerRef::Target { index },
                });
            }
            Selector::Player { filter } => match filter.relation {
                PlayerRelation::You => f.owner = Some(RelativeControl::You),
                PlayerRelation::Opponent | PlayerRelation::EachOpponent => {
                    f.owner = Some(RelativeControl::Opponent);
                }
                _ => {}
            },
            _ => {}
        }
        let mut st = make_step(
            EffectOp::Exile {
                select: SelectionMod::default(),
                duration: if until_leaves || until_monarch {
                    None
                } else {
                    dur
                },
                until_source_leaves: until_leaves,
                until_opponent_becomes_monarch: until_monarch,
                exile_all_except_bottom: false,
                face_down,
                look_only: false,
                exile_with_counters: None,
            },
            Selector::All {
                filter: Box::new(f),
            },
            span,
        );
        st.bind_as = Some("exiled".to_string());
        state.push_step(st, true);
        return true;
    }
    if let Some(and_pos) = find_word_ci(dur_body, " and all ") {
        let lhs_s = dur_body[..and_pos].trim();
        let rhs_s = dur_body[and_pos + " and all ".len()..].trim();
        let mark = state.mark(ctx);
        let synth1 = format!("exile {lhs_s}");
        let synth2 = format!("exile all {rhs_s}");
        let saved_player = state.last_player.clone();
        if parse_exile_clause(&synth1, span, ctx, state) {
            if let Some(last_t) = state.targets.len().checked_sub(1) {
                state.last_player = Some(Selector::PlayerRef {
                    player: PlayerRef::ControllerOf {
                        of: Box::new(Ref::Target {
                            index: last_t as u16,
                        }),
                    },
                });
            }
            if parse_exile_clause(&synth2, span, ctx, state) {
                return true;
            }
        }
        state.last_player = saved_player;
        state.rollback(mark, ctx);
    }
    if let Some(from_pos) = find_word_ci(dur_body, " from ") {
        let lhs = dur_body[..from_pos].trim();
        let rhs = dur_body[from_pos + " from ".len()..].trim();
        if eq_ci(rhs, "each graveyard") && !contains_word_ci(lhs, "target") {
            let singular_lhs = starts_with_word_ci(lhs, "a ") || starts_with_word_ci(lhs, "an ");
            let clean_lhs = strip_prefix_word_ci(lhs, "all")
                .or_else(|| strip_prefix_word_ci(lhs, "a"))
                .or_else(|| strip_prefix_word_ci(lhs, "an"))
                .map(|r| r.trim())
                .unwrap_or(lhs);
            let ftoks = tokenize(clean_lhs, 0);
            let cp = ctx.interner.checkpoint();
            if !ftoks.is_empty()
                && let Some((mut f, used)) = parse_object_filter(
                    &ftoks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::GRAVEYARD,
                        allow_plural_and_disjunction: true,
                        strip_trailing_card: true,
                        ..Default::default()
                    },
                    state,
                )
                && used == ftoks.len()
            {
                f.zones = ZoneMask::GRAVEYARD;
                f.extra.push(ObjectPredicate::OwnerRef {
                    player: PlayerRef::EachLoopPlayer,
                });
                let mut inner_st = make_step(
                    EffectOp::Exile {
                        select: SelectionMod {
                            choice_count: singular_lhs.then(|| Box::new(Amount::Const { n: 1 })),
                            ..SelectionMod::default()
                        },
                        duration: if until_leaves || until_monarch {
                            None
                        } else {
                            dur
                        },
                        until_source_leaves: until_leaves,
                        until_opponent_becomes_monarch: until_monarch,
                        exile_all_except_bottom: false,
                        face_down,
                        look_only: false,
                        exile_with_counters: None,
                    },
                    Selector::All {
                        filter: Box::new(f),
                    },
                    span,
                );
                if singular_lhs {
                    inner_st.amount = Some(Box::new(Amount::Const { n: 1 }));
                }
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: LoopPlayersKind::EachPlayer,
                            steps: vec![inner_st],
                            choose_random_opponent: false,
                            exclude_attacked_last_combat: false,
                            exclude_event_player: false,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            ctx.interner.rollback(cp);
        }
        if let Some(owner_raw) = ["'s graveyard", "s' graveyards", "'s graveyards"]
            .iter()
            .find_map(|suf| {
                let r_low = rhs.to_ascii_lowercase();
                r_low
                    .ends_with(suf)
                    .then(|| rhs[..rhs.len() - suf.len()].trim())
            })
            && let Some(psel) = parse_player_selector(owner_raw, ctx, state)
        {
            if contains_word_ci(lhs, "target") {
                let ftoks = tokenize(lhs, 0);
                let cp = ctx.interner.checkpoint();
                if let Some((mut spec, used)) = parse_target_spec(&ftoks, ctx, state)
                    && used == ftoks.len()
                {
                    spec.filter.zones = ZoneMask::GRAVEYARD;
                    match psel {
                        Selector::PlayerRef { player } => {
                            spec.filter.extra.push(ObjectPredicate::OwnerRef { player });
                        }
                        Selector::Target { index } => {
                            spec.filter.extra.push(ObjectPredicate::OwnerRef {
                                player: PlayerRef::Target { index },
                            });
                        }
                        Selector::Player { filter } => match filter.relation {
                            PlayerRelation::You => spec.filter.owner = Some(RelativeControl::You),
                            PlayerRelation::Opponent | PlayerRelation::EachOpponent => {
                                spec.filter.owner = Some(RelativeControl::Opponent);
                            }
                            _ => {}
                        },
                        _ => {}
                    }
                    let idx = state.add_target(spec);
                    let mut st = make_step(
                        EffectOp::Exile {
                            select: SelectionMod::default(),
                            duration: if until_leaves || until_monarch {
                                None
                            } else {
                                dur
                            },
                            until_source_leaves: until_leaves,
                            until_opponent_becomes_monarch: until_monarch,
                            exile_all_except_bottom: false,
                            face_down,
                            look_only: false,
                            exile_with_counters: None,
                        },
                        Selector::Target { index: idx },
                        span,
                    );
                    st.bind_as = Some("exiled".to_string());
                    state.push_step(st, true);
                    return true;
                }
                ctx.interner.rollback(cp);
            }
            let (lhs_at_random, lhs_no_rand) =
                if let Some(r) = strip_suffix_word_ci(lhs, "at random") {
                    (true, r)
                } else {
                    (false, lhs)
                };
            let clean_lhs = strip_prefix_word_ci(lhs_no_rand, "all")
                .map(|r| r.trim())
                .unwrap_or(lhs_no_rand);
            let ftoks = tokenize(clean_lhs, 0);
            let cp = ctx.interner.checkpoint();
            let singular_lhs =
                starts_with_word_ci(lhs_no_rand, "a ") || starts_with_word_ci(lhs_no_rand, "an ");
            if !ftoks.is_empty()
                && let Some((mut f, used)) = parse_object_filter(
                    &ftoks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::GRAVEYARD,
                        allow_plural_and_disjunction: true,
                        strip_trailing_card: true,
                        ..Default::default()
                    },
                    state,
                )
                && used == ftoks.len()
            {
                f.zones = ZoneMask::GRAVEYARD;
                if let Selector::Player { filter } = &psel
                    && matches!(
                        filter.relation,
                        PlayerRelation::EachOpponent | PlayerRelation::EachPlayer
                    )
                    && (lhs_at_random || singular_lhs)
                {
                    let loop_kind = if filter.relation == PlayerRelation::EachOpponent {
                        LoopPlayersKind::EachOpponent
                    } else {
                        LoopPlayersKind::EachPlayer
                    };
                    f.extra.push(ObjectPredicate::ControllerRef {
                        player: PlayerRef::EachLoopPlayer,
                    });
                    let mut inner_st = make_step(
                        EffectOp::Exile {
                            select: SelectionMod {
                                choice_count: (!lhs_at_random && singular_lhs)
                                    .then(|| Box::new(Amount::Const { n: 1 })),
                                at_random: lhs_at_random,
                                ..SelectionMod::default()
                            },
                            duration: if until_leaves || until_monarch {
                                None
                            } else {
                                dur
                            },
                            until_source_leaves: until_leaves,
                            until_opponent_becomes_monarch: until_monarch,
                            exile_all_except_bottom: false,
                            face_down,
                            look_only: false,
                            exile_with_counters: None,
                        },
                        Selector::All {
                            filter: Box::new(f),
                        },
                        span,
                    );
                    if lhs_at_random {
                        inner_st.amount = Some(Box::new(Amount::Const { n: 1 }));
                    }
                    inner_st.bind_as = Some("exiled".to_string());
                    state.push_step(
                        make_step(
                            EffectOp::ForEachPlayerLoop {
                                players: loop_kind,
                                steps: vec![inner_st],
                                choose_random_opponent: false,
                                exclude_attacked_last_combat: false,
                                exclude_event_player: false,
                                choose_object_to_bind: None,
                            },
                            Selector::None,
                            span,
                        ),
                        false,
                    );
                    state.last_object = Some((
                        Ref::Binding {
                            name: "exiled".to_string(),
                        },
                        state.steps.len().saturating_sub(1),
                    ));
                    return true;
                }
                match psel {
                    Selector::PlayerRef { player } => {
                        f.extra.push(ObjectPredicate::OwnerRef { player });
                    }
                    Selector::Target { index } => {
                        f.extra.push(ObjectPredicate::OwnerRef {
                            player: PlayerRef::Target { index },
                        });
                    }
                    Selector::Player { filter } => match filter.relation {
                        PlayerRelation::You => f.owner = Some(RelativeControl::You),
                        PlayerRelation::Opponent | PlayerRelation::EachOpponent => {
                            f.owner = Some(RelativeControl::Opponent);
                        }
                        _ => {}
                    },
                    _ => {}
                }
                let mut st = make_step(
                    EffectOp::Exile {
                        select: SelectionMod {
                            choice_count: (!lhs_at_random && singular_lhs)
                                .then(|| Box::new(Amount::Const { n: 1 })),
                            at_random: lhs_at_random,
                            ..SelectionMod::default()
                        },
                        duration: if until_leaves || until_monarch {
                            None
                        } else {
                            dur
                        },
                        until_source_leaves: until_leaves,
                        until_opponent_becomes_monarch: until_monarch,
                        exile_all_except_bottom: false,
                        face_down,
                        look_only: false,
                        exile_with_counters: None,
                    },
                    Selector::All {
                        filter: Box::new(f),
                    },
                    span,
                );
                if lhs_at_random && singular_lhs {
                    st.amount = Some(Box::new(Amount::Const { n: 1 }));
                }
                st.bind_as = Some("exiled".to_string());
                state.push_step(st, true);
                return true;
            }
            ctx.interner.rollback(cp);
        }
    }
    let (dur_body_clean, ex_dz, ex_owner, ex_owner_ref) = if let Some(b) =
        strip_suffix_word_ci(dur_body, "from graveyards")
            .or_else(|| strip_suffix_word_ci(dur_body, "from a graveyard"))
            .or_else(|| strip_suffix_word_ci(dur_body, "from any graveyard"))
    {
        (b, ZoneMask::GRAVEYARD, None, None)
    } else if let Some(b) = strip_suffix_word_ci(dur_body, "from your graveyard") {
        (b, ZoneMask::GRAVEYARD, Some(RelativeControl::You), None)
    } else if let Some(b) = strip_suffix_word_ci(dur_body, "from their graveyard")
        .or_else(|| strip_suffix_word_ci(dur_body, "from that player's graveyard"))
    {
        (
            b,
            ZoneMask::GRAVEYARD,
            None,
            Some(state.single_player_ref().unwrap_or(PlayerRef::EventPlayer)),
        )
    } else if let Some(b) = strip_suffix_word_ci(dur_body, "from its owner's graveyard") {
        let r = state.it_ref().unwrap_or(Ref::EventObject);
        (
            b,
            ZoneMask::GRAVEYARD,
            None,
            Some(PlayerRef::OwnerOf { of: Box::new(r) }),
        )
    } else {
        (dur_body, ZoneMask::BATTLEFIELD, None, None)
    };
    let (dur_body_clean, power_lte_revealed) = if let Some(b) = strip_suffix_word_ci(
        dur_body_clean,
        "if its power is less than or equal to the revealed card's power",
    ) {
        (b, true)
    } else {
        (dur_body_clean, false)
    };
    let (dur_body_clean, only_colored_from_unless) = if let Some(b) = strip_suffix_word_ci(
        dur_body_clean,
        "unless it's colorless or it's only the color its controller chose",
    ) {
        (b, true)
    } else {
        (dur_body_clean, false)
    };
    let (dur_body_clean, at_random_exile) =
        if let Some(b) = strip_suffix_word_ci(dur_body_clean, "at random") {
            (b, true)
        } else {
            (dur_body_clean, false)
        };
    let dur_body_clean = strip_suffix_word_ci(dur_body_clean, "again")
        .filter(|b| eq_ci(b, "it") || eq_ci(b, "them"))
        .unwrap_or(dur_body_clean);
    let apply_ex_owner = |f: &mut ObjectFilter| {
        if let Some(own) = ex_owner
            && f.owner.is_none()
            && f.extra
                .iter()
                .all(|p| !matches!(p, ObjectPredicate::OwnerRef { .. }))
        {
            f.owner = Some(own);
        }
        if let Some(ref pref) = ex_owner_ref
            && f.owner.is_none()
            && f.extra
                .iter()
                .all(|p| !matches!(p, ObjectPredicate::OwnerRef { .. }))
        {
            f.extra.push(ObjectPredicate::OwnerRef {
                player: pref.clone(),
            });
        }
    };
    let mut obj = if let Some(obj) = parse_object_selector(dur_body_clean, ex_dz, ctx, state) {
        obj
    } else {
        let toks = tokenize(dur_body_clean, 0);
        if toks.len() >= 2
            && !eq_ci(toks[0].raw, "a")
            && !eq_ci(toks[0].raw, "an")
            && let Some(amt) = parse_amount_str(toks[0].raw, ctx, state)
        {
            let cp = ctx.interner.checkpoint();
            if let Some((mut f, used)) = parse_object_filter(
                &toks[1..],
                ctx,
                FilterOpts {
                    default_zone: ex_dz,
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: ex_dz != ZoneMask::BATTLEFIELD,
                    ..Default::default()
                },
                state,
            ) && used == toks[1..].len()
            {
                if f.zones.is_empty() {
                    f.zones = ex_dz;
                }
                apply_ex_owner(&mut f);
                let mut st = make_step(
                    EffectOp::Exile {
                        select: SelectionMod {
                            at_random: at_random_exile,
                            ..SelectionMod::default()
                        },
                        duration: if until_leaves || until_monarch {
                            None
                        } else {
                            dur
                        },
                        until_source_leaves: until_leaves,
                        until_opponent_becomes_monarch: until_monarch,
                        exile_all_except_bottom: false,
                        face_down,
                        look_only: false,
                        exile_with_counters: with_counters,
                    },
                    Selector::All {
                        filter: Box::new(f),
                    },
                    span,
                );
                st.amount = Some(Box::new(amt));
                st.bind_as = Some("exiled".to_string());
                state.push_step(st, true);
                return true;
            }
            ctx.interner.rollback(cp);
        }
        return false;
    };
    apply_extracted_from_owner(&mut obj, ex_owner, state);
    if let ParsedObj::All(ref mut f) = obj {
        apply_ex_owner(f);
        if only_colored_from_unless {
            f.flags |= FilterFlags::IS_COLORED;
        }
    } else if let ParsedObj::Target(idx) = &obj
        && let Some(ref pref) = ex_owner_ref
        && let Some(spec) = state.targets.get_mut(*idx as usize)
        && spec.filter.owner.is_none()
        && spec
            .filter
            .extra
            .iter()
            .all(|p| !matches!(p, ObjectPredicate::OwnerRef { .. }))
    {
        spec.filter.extra.push(ObjectPredicate::OwnerRef {
            player: pref.clone(),
        });
    }
    let singular_obj = matches!(obj, ParsedObj::All(_))
        && (starts_with_word_ci(dur_body_clean, "a ")
            || starts_with_word_ci(dur_body_clean, "an "));
    let use_amount_one = singular_obj && at_random_exile;
    let mut st = make_step(
        EffectOp::Exile {
            select: SelectionMod {
                choice_count: (singular_obj && !use_amount_one)
                    .then(|| Box::new(Amount::Const { n: 1 })),
                at_random: at_random_exile,
                filter: power_lte_revealed.then(|| {
                    Box::new(ObjectFilter {
                        extra: vec![ObjectPredicate::PowerLteRevealedCostCard],
                        ..Default::default()
                    })
                }),
                ..SelectionMod::default()
            },
            duration: if until_leaves || until_monarch {
                None
            } else {
                dur
            },
            until_source_leaves: until_leaves,
            until_opponent_becomes_monarch: until_monarch,
            exile_all_except_bottom: false,
            face_down,
            look_only: false,
            exile_with_counters: with_counters,
        },
        obj.into_selector(),
        span,
    );
    if use_amount_one {
        st.amount = Some(Box::new(Amount::Const { n: 1 }));
    }
    st.bind_as = Some("exiled".to_string());
    state.push_step(st, true);
    true
}

fn extract_with_counters<'a>(
    s: &'a str,
    ctx: &mut ParseCtx<'_>,
) -> (Option<(CounterId, u16)>, &'a str) {
    let Some(before_on) =
        strip_suffix_word_ci(s, "on it").or_else(|| strip_suffix_word_ci(s, "on them"))
    else {
        return (None, s);
    };
    let Some(before_ctr) = strip_suffix_word_ci(before_on, "counter")
        .or_else(|| strip_suffix_word_ci(before_on, "counters"))
    else {
        return (None, s);
    };
    let Some(wpos) = before_ctr
        .as_bytes()
        .windows(6)
        .rposition(|w| w.eq_ignore_ascii_case(b" with "))
    else {
        return (None, s);
    };
    let prefix = before_ctr[..wpos].trim_end_matches(',').trim();
    let spec = before_ctr[wpos + 6..].trim();
    let (cnt, ctr_raw) = if let Some(r) = strip_prefix_word_ci(spec, "an additional") {
        (1u16, r)
    } else {
        let spec = strip_prefix_word_ci(spec, "additional").unwrap_or(spec);
        if let Some(r) =
            strip_prefix_word_ci(spec, "a").or_else(|| strip_prefix_word_ci(spec, "an"))
        {
            (1u16, r)
        } else {
            let mut ws = spec.splitn(2, char::is_whitespace);
            let first = ws.next().unwrap_or("");
            let second = ws.next().unwrap_or("").trim();
            if let Some(n) = parse_small_number(first) {
                let second = strip_prefix_word_ci(second, "additional").unwrap_or(second);
                (n.max(1) as u16, second)
            } else {
                return (None, s);
            }
        }
    };
    if let Some(norm) = normalize_counter_name(ctr_raw) {
        let cid = ctx.interner.intern_counter(&norm);
        (Some((cid, cnt)), prefix)
    } else {
        (None, s)
    }
}

fn parse_return_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "return") else {
        return false;
    };

    // "return <obj> to its/their owner's hand(s) [for each <expr>]" -> Bounce / Move
    let (return_body, return_for_each_amt) = if let Some(fe_pos) = find_word_ci(rest, " for each ")
    {
        let left = rest[..fe_pos].trim();
        let fe_s = format!("for each {}", rest[fe_pos + " for each ".len()..].trim());
        if let Some(amt) = parse_amount_str(&fe_s, ctx, state) {
            (left, Some(amt))
        } else {
            (rest, None)
        }
    } else {
        (rest, None)
    };
    let (return_body, except_subs_raw) = if let Some(ep) = find_word_ci(return_body, " except for ")
    {
        (
            return_body[..ep].trim(),
            Some(return_body[ep + " except for ".len()..].trim()),
        )
    } else if let Some(ep) = find_word_ci(return_body, " except ") {
        (
            return_body[..ep].trim(),
            Some(return_body[ep + " except ".len()..].trim()),
        )
    } else {
        (return_body, None)
    };
    for hand_suf in [
        "to its owner's hand",
        "to their owner's hand",
        "to their owners' hands",
        "to your hand",
    ] {
        if let Some(subj_raw) = strip_suffix_word_ci(return_body, hand_suf) {
            let (from_zone, from_owner, clean_subj_raw) = extract_from_zone(subj_raw);
            let (clean_subj, chooser_override) =
                if let Some(c) = strip_suffix_word_ci(clean_subj_raw, "of an opponent's choice") {
                    (c.trim(), Some(mtg_ir::ChooserOverride::Opponent))
                } else {
                    (clean_subj_raw, None)
                };
            let dz = from_zone
                .map(ZoneMask::from_zone)
                .unwrap_or(ZoneMask::BATTLEFIELD);
            if let Some(same_pos) = find_word_ci(clean_subj, " and all other ")
                && let rhs = &clean_subj[same_pos + " and all other ".len()..]
                && (contains_word_ci(rhs, "with the same name as that card")
                    || contains_word_ci(rhs, "with the same name as that creature"))
            {
                let lhs = clean_subj[..same_pos].trim();
                let mark_sr = state.mark(ctx);
                if let Some(mut first_obj) = parse_object_selector(lhs, dz, ctx, state) {
                    apply_extracted_from_owner(&mut first_obj, from_owner, state);
                    if let ParsedObj::Target(idx) = first_obj {
                        let same_filter = ObjectFilter {
                            zones: dz,
                            owner: from_owner,
                            extra: vec![ObjectPredicate::SameNameAsTarget { index: idx }],
                            ..Default::default()
                        };
                        let mk_hand_move = |sel: Selector| {
                            make_step(
                                EffectOp::Move {
                                    from: from_zone,
                                    to: Some(Zone::Hand),
                                    select: SelectionMod::default(),
                                    tapped: false,
                                    under_your_control: false,
                                    topmost_only: false,
                                    may_shuffle: false,
                                    position: None,
                                    from_top: None,
                                    library_choice_by: None,
                                    random_order: false,
                                    entered_transformed: false,
                                    entered_flipped: false,
                                    enters_tapped_and_attacking: false,
                                    as_enchantment_only: false,
                                    unearth: false,
                                    with_counters: None,
                                    attached_to: None,
                                    condition: None,
                                    choose_at_random_from_exiled_with_self: false,
                                    leave_chosen_in_graveyard_rest_to_hand: false,
                                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                                },
                                sel,
                                span,
                            )
                        };
                        state.push_step(mk_hand_move(Selector::Target { index: idx }), true);
                        state.push_step(
                            mk_hand_move(Selector::All {
                                filter: Box::new(same_filter),
                            }),
                            false,
                        );
                        return true;
                    }
                }
                state.rollback(mark_sr, ctx);
            }
            let Some(mut obj) = parse_object_selector(clean_subj, dz, ctx, state) else {
                return false;
            };
            if let Some(ex_s) = except_subs_raw {
                let mut ex_ids: SmallVec<[SubtypeId; 2]> = SmallVec::new();
                for comma_seg in ex_s.split(',') {
                    let s = comma_seg.trim();
                    if s.is_empty() {
                        continue;
                    }
                    let s = strip_prefix_word_ci(s, "and").unwrap_or(s).trim();
                    if s.is_empty() {
                        continue;
                    }
                    if let Some(p) = find_word_ci(s, " and ") {
                        for sub_raw in [s[..p].trim(), s[p + 5..].trim()] {
                            let sub_norm = singular_subtype(sub_raw)
                                .unwrap_or_else(|| canonical_keyword_case(sub_raw));
                            ex_ids.push(ctx.interner.intern_subtype(&sub_norm));
                        }
                    } else {
                        let sub_norm =
                            singular_subtype(s).unwrap_or_else(|| canonical_keyword_case(s));
                        ex_ids.push(ctx.interner.intern_subtype(&sub_norm));
                    }
                }
                if let ParsedObj::All(ref mut f) = obj {
                    f.subtypes_none.extend(ex_ids);
                } else {
                    return false;
                }
            }
            apply_extracted_from_owner(&mut obj, from_owner, state);
            let trig_from_zone = if from_zone.is_none()
                && matches!(obj, ParsedObj::EventObject)
                && let Some(EventDetail::ZoneChange {
                    to: Some(z @ (Zone::Graveyard | Zone::Exile)),
                    ..
                }) = state.trigger.and_then(|tr| tr.filter.detail.as_ref())
            {
                Some(*z)
            } else {
                from_zone
            };
            let singular_choice = matches!(obj, ParsedObj::All(_))
                && (starts_with_word_ci(clean_subj, "a")
                    || starts_with_word_ci(clean_subj, "an")
                    || starts_with_word_ci(clean_subj, "another"));
            let choice_count = return_for_each_amt
                .clone()
                .map(Box::new)
                .or_else(|| singular_choice.then(|| Box::new(Amount::Const { n: 1 })));
            let is_non_bf_target = trig_from_zone.is_none()
                && matches!(obj, ParsedObj::Target(idx) if state.targets.get(idx as usize).is_some_and(|t| {
                    let tz = t.filter.zones;
                    tz.intersects(ZoneMask::GRAVEYARD | ZoneMask::EXILE)
                        && !tz.contains(ZoneMask::BATTLEFIELD)
                }));
            if (trig_from_zone.is_some() && trig_from_zone != Some(Zone::Battlefield))
                || is_non_bf_target
            {
                let mut st = make_step(
                    EffectOp::Move {
                        from: trig_from_zone,
                        to: Some(Zone::Hand),
                        select: SelectionMod {
                            choice_count,
                            up_to: return_for_each_amt.is_some(),
                            chooser: chooser_override,
                            ..Default::default()
                        },
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: false,
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    obj.into_selector(),
                    span,
                );
                if let Some(amt) = return_for_each_amt {
                    st.amount = Some(Box::new(amt));
                }
                st.bind_as = Some(state.alloc_bind_name("moved"));
                state.push_step(st, true);
                return true;
            }
            let st = make_step(
                EffectOp::Bounce {
                    select: SelectionMod {
                        choice_count: singular_choice.then(|| Box::new(Amount::Const { n: 1 })),
                        chooser: chooser_override,
                        ..Default::default()
                    },
                },
                obj.into_selector(),
                span,
            );
            state.push_step(st, true);
            return true;
        }
    }

    for gy_suf in [
        "to its owner's graveyard",
        "to their owner's graveyard",
        "to their owners' graveyards",
        "to your graveyard",
        "to the graveyard",
    ] {
        if let Some(subj_raw) = strip_suffix_word_ci(return_body, gy_suf) {
            let (from_zone, from_owner, clean_subj) = extract_from_zone(subj_raw);
            let dz = from_zone.map(ZoneMask::from_zone).unwrap_or_else(|| {
                if contains_word_ci(clean_subj, "exiled") {
                    ZoneMask::EXILE
                } else {
                    ZoneMask::BATTLEFIELD
                }
            });
            if let Some(mut obj) = parse_object_selector(clean_subj, dz, ctx, state) {
                apply_extracted_from_owner(&mut obj, from_owner, state);
                let is_exiled_with_self = matches!(
                    &obj,
                    ParsedObj::All(f)
                        if f.extra
                            .iter()
                            .any(|p| matches!(p, ObjectPredicate::ExiledWithSelf))
                );
                let eff_from = from_zone.or(is_exiled_with_self.then_some(Zone::Exile));
                let st = make_step(
                    EffectOp::Move {
                        from: eff_from,
                        to: Some(Zone::Graveyard),
                        select: SelectionMod::default(),
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: false,
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    obj.into_selector(),
                    span,
                );
                state.push_step(st, true);
                return true;
            }
        }
    }

    // "return <obj> [from your graveyard] to the battlefield [tapped] [under your/its owner's control] [with <N> <ctr> counter(s) on it] [attached to <obj>]"
    let (attached_raw, rest_att) =
        if let Some(idx) = rfind_ascii_ci(rest.as_bytes(), b" attached to ") {
            let pre = rest[..idx].trim_end();
            let rhs = rest[idx + " attached to ".len()..].trim();
            if (contains_word_ci(pre, "to the battlefield")
                || contains_word_ci(pre, "onto the battlefield"))
                && !rhs.is_empty()
            {
                (Some(rhs), pre)
            } else {
                (None, rest)
            }
        } else {
            (None, rest)
        };
    let (wc0, rest0) = extract_with_counters(rest_att, ctx);
    let (tr0, rest0) = if let Some(r) = strip_suffix_word_ci(rest0, "transformed") {
        (true, r)
    } else {
        (false, rest0)
    };
    let (tapped, attacking0, body1) =
        if let Some(r) = strip_suffix_word_ci(rest0, "tapped and attacking") {
            (true, true, r)
        } else if let Some(r) = strip_suffix_word_ci(rest0, "tapped") {
            (true, false, r)
        } else {
            (false, false, rest0)
        };
    let (wc1, body1) = if wc0.is_none() {
        extract_with_counters(body1, ctx)
    } else {
        (wc0, body1)
    };
    let (under_your, body2) = if let Some(r) = strip_suffix_word_ci(body1, "under your control") {
        (true, r)
    } else if let Some(r) = strip_suffix_word_ci(body1, "under its owner's control")
        .or_else(|| strip_suffix_word_ci(body1, "under their owner's control"))
        .or_else(|| strip_suffix_word_ci(body1, "under their owners' control"))
        .or_else(|| strip_suffix_word_ci(body1, "under that player's control"))
    {
        (false, r)
    } else {
        (false, body1)
    };
    let (with_counters, body2) = if wc1.is_none() {
        extract_with_counters(body2, ctx)
    } else {
        (wc1, body2)
    };
    let (tr1, body2) = if let Some(r) = strip_suffix_word_ci(body2, "transformed") {
        (true, r)
    } else {
        (false, body2)
    };
    let (tapped, enters_tapped_and_attacking, body3) =
        if let Some(r) = strip_suffix_word_ci(body2, "tapped and attacking") {
            (true, true, r)
        } else if let Some(r) = strip_suffix_word_ci(body2, "tapped") {
            (true, attacking0, r)
        } else {
            (tapped, attacking0, body2)
        };
    let (tr2, body3) = if let Some(r) = strip_suffix_word_ci(body3, "transformed") {
        (true, r)
    } else {
        (false, body3)
    };
    let entered_transformed = tr0 || tr1 || tr2;
    if let Some(subj_raw) = strip_suffix_word_ci(body3, "to the battlefield")
        .or_else(|| strip_suffix_word_ci(body3, "onto the battlefield"))
    {
        let (topmost_only, subj_no_top) = if let Some(after_top) =
            strip_prefix_word_ci(subj_raw, "the top")
            && contains_word_ci(after_top, "graveyard")
        {
            (true, after_top)
        } else {
            (false, subj_raw)
        };
        let (from_zone, from_owner, clean_subj_raw) = if topmost_only {
            if let Some(l) = strip_suffix_word_ci(subj_no_top, "of your graveyard") {
                (Some(Zone::Graveyard), Some(RelativeControl::You), l)
            } else if let Some(l) = strip_suffix_word_ci(subj_no_top, "of a graveyard") {
                (Some(Zone::Graveyard), None, l)
            } else {
                extract_from_zone(subj_no_top)
            }
        } else {
            extract_from_zone(subj_no_top)
        };
        let (ret_up_to, ret_choice_count, clean_subj) =
            if !contains_word_ci(clean_subj_raw, "target") {
                if let Some(after_ut) = strip_prefix_word_ci(clean_subj_raw, "up to")
                    && let Some(first_w) = after_ut.split_whitespace().next()
                    && let Some(n) = parse_small_number(first_w)
                {
                    (
                        true,
                        Some(Box::new(Amount::Const { n })),
                        after_ut[first_w.len()..].trim(),
                    )
                } else if let Some(after_all) = strip_prefix_word_ci(clean_subj_raw, "all") {
                    (false, None, after_all)
                } else {
                    (false, None, clean_subj_raw)
                }
            } else {
                (false, None, clean_subj_raw)
            };
        let dz = from_zone
            .map(ZoneMask::from_zone)
            .unwrap_or(ZoneMask::GRAVEYARD);
        let (mut ret_sel_filter, put_gy_way_obj) = if let Some(lhs) =
            strip_suffix_word_ci(clean_subj, "put into a graveyard this way")
                .or_else(|| strip_suffix_word_ci(clean_subj, "put into graveyards this way"))
            && let Some(destr_idx) = state
                .steps
                .iter()
                .rposition(|s| matches!(s.op, EffectOp::Destroy { .. }))
        {
            let f_str = strip_prefix_word_ci(lhs, "a")
                .or_else(|| strip_prefix_word_ci(lhs, "an"))
                .or_else(|| strip_prefix_word_ci(lhs, "one"))
                .unwrap_or(lhs);
            let parsed_f = parse_object_phrase(
                f_str,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    strip_trailing_card: true,
                    ..Default::default()
                },
            );
            let same_as_destr = match (&state.steps[destr_idx].subject, &parsed_f) {
                (Selector::All { filter: df }, Some(pf)) => {
                    df.types_any == pf.types_any
                        && df.types_none == pf.types_none
                        && df.supertypes_any == pf.supertypes_any
                        && df.extra.is_empty()
                        && pf.extra.is_empty()
                }
                _ => false,
            };
            let sel_filt = if same_as_destr {
                None
            } else {
                parsed_f.map(|mut pf| {
                    pf.zones = ZoneMask::empty();
                    Box::new(pf)
                })
            };
            let bname = if let Some(b) = state.steps[destr_idx].bind_as.clone() {
                b
            } else {
                let b = state.alloc_bind_name("b");
                state.steps[destr_idx].bind_as = Some(b.clone());
                b
            };
            (sel_filt, Some(ParsedObj::Binding(bname)))
        } else {
            (None, None)
        };
        let mut obj = if let Some(o) = put_gy_way_obj {
            o
        } else if let Some(o) = parse_object_selector(clean_subj, dz, ctx, state) {
            o
        } else {
            return false;
        };
        {
            let attached_to = match attached_raw {
                Some(att_str) => {
                    let Some(att) =
                        parse_object_selector(att_str, ZoneMask::BATTLEFIELD, ctx, state)
                    else {
                        return false;
                    };
                    Some(Box::new(att.into_selector()))
                }
                None => None,
            };
            apply_extracted_from_owner(&mut obj, from_owner, state);
            let singular_choice = !topmost_only
                && ret_choice_count.is_none()
                && (matches!(obj, ParsedObj::All(_))
                    || (matches!(obj, ParsedObj::Binding(_))
                        && (starts_with_word_ci(clean_subj, "a")
                            || starts_with_word_ci(clean_subj, "an")
                            || starts_with_word_ci(clean_subj, "one"))))
                && (starts_with_word_ci(clean_subj, "a")
                    || starts_with_word_ci(clean_subj, "an")
                    || starts_with_word_ci(clean_subj, "one"));
            let sel = obj.into_selector();
            let from_exile = from_zone.is_none()
                && (matches!(&sel, Selector::Binding { name } if state.steps.iter().rev().any(|s| {
                    s.bind_as.as_deref() == Some(name.as_str())
                        && matches!(s.op, EffectOp::Exile { .. })
                }) || state.parent_exile_bindings.iter().any(|b| b == name))
                    || (matches!(sel, Selector::EventObject) && state.trigger_event_is_exile())
                    || state
                        .steps
                        .iter()
                        .rev()
                        .any(|s| matches!(s.op, EffectOp::Exile { .. }) && s.subject == sel)
                    || state.parent_exile_selectors.iter().any(|s| s == &sel));
            let trigger_multi_zone_dest = matches!(sel, Selector::EventObject)
                && state.trigger.is_some_and(|t| {
                    !t.or.is_empty()
                        && t.or.iter().any(|o| {
                            matches!(
                                o.filter.detail,
                                Some(EventDetail::ZoneChange {
                                    to: Some(Zone::Exile),
                                    ..
                                })
                            )
                        })
                });
            let default_from = if trigger_multi_zone_dest {
                None
            } else if from_exile {
                Some(Zone::Exile)
            } else {
                Some(Zone::Graveyard)
            };
            let mut st = make_step(
                EffectOp::Move {
                    from: from_zone.or(default_from),
                    to: Some(Zone::Battlefield),
                    select: SelectionMod {
                        choice_count: ret_choice_count
                            .or_else(|| singular_choice.then(|| Box::new(Amount::Const { n: 1 }))),
                        up_to: ret_up_to,
                        filter: ret_sel_filter.take(),
                        ..Default::default()
                    },
                    tapped,
                    under_your_control: under_your
                        || (enters_tapped_and_attacking && matches!(sel, Selector::SelfObj)),
                    topmost_only,
                    may_shuffle: false,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed,
                    entered_flipped: false,
                    enters_tapped_and_attacking,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters,
                    attached_to,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                sel,
                span,
            );
            st.bind_as = Some(state.alloc_bind_name("moved"));
            state.push_step(st, true);
            return true;
        }
    }

    if let Some(subj_raw) = strip_suffix_word_ci(return_body, "to the command zone") {
        let (from_zone, from_owner, clean_subj) = extract_from_zone(subj_raw);
        let dz = from_zone
            .map(ZoneMask::from_zone)
            .unwrap_or(ZoneMask::BATTLEFIELD);
        if let Some(mut obj) = parse_object_selector(clean_subj, dz, ctx, state) {
            apply_extracted_from_owner(&mut obj, from_owner, state);
            state.push_step(
                make_step(
                    EffectOp::Move {
                        from: from_zone,
                        to: Some(Zone::Command),
                        select: SelectionMod::default(),
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: false,
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
    }

    false
}

fn apply_extracted_from_owner(
    obj: &mut ParsedObj,
    from_owner: Option<RelativeControl>,
    state: &mut ParserState<'_>,
) {
    let Some(owner) = from_owner else {
        return;
    };
    match obj {
        ParsedObj::Target(idx) => {
            if let Some(spec) = state.targets.get_mut(*idx as usize)
                && spec.filter.owner.is_none()
            {
                spec.filter.owner = Some(owner);
            }
        }
        ParsedObj::All(f) if f.owner.is_none() => {
            f.owner = Some(owner);
        }
        _ => {}
    }
}

fn extract_from_zone(s: &str) -> (Option<Zone>, Option<RelativeControl>, &str) {
    for (pat, z, owner) in [
        (
            "from your graveyard",
            Zone::Graveyard,
            Some(RelativeControl::You),
        ),
        (
            "from an opponent's graveyard",
            Zone::Graveyard,
            Some(RelativeControl::Opponent),
        ),
        ("from all graveyards", Zone::Graveyard, None),
        ("from each graveyard", Zone::Graveyard, None),
        ("from any graveyard", Zone::Graveyard, None),
        ("from a graveyard", Zone::Graveyard, None),
        ("from their graveyard", Zone::Graveyard, None),
        ("from your hand", Zone::Hand, Some(RelativeControl::You)),
        ("from exile", Zone::Exile, None),
        ("from the battlefield", Zone::Battlefield, None),
        ("from the command zone", Zone::Command, None),
    ] {
        if let Some(pre) = strip_suffix_word_ci(s, pat) {
            return (Some(z), owner, pre);
        }
    }
    (None, None, s)
}

fn extract_from_zone_or_mask(
    s: &str,
) -> (
    Option<Zone>,
    Option<ZoneMask>,
    Option<RelativeControl>,
    &str,
) {
    for (pat, mask, owner) in [
        (
            "from your hand and/or graveyard",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::GRAVEYARD.bits()),
            Some(RelativeControl::You),
        ),
        (
            "from your graveyard and/or hand",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::GRAVEYARD.bits()),
            Some(RelativeControl::You),
        ),
        (
            "from a hand and/or graveyard",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::GRAVEYARD.bits()),
            None,
        ),
        (
            "from your hand and/or library",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::LIBRARY.bits()),
            Some(RelativeControl::You),
        ),
        (
            "from your hand or graveyard",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::GRAVEYARD.bits()),
            Some(RelativeControl::You),
        ),
        (
            "from your graveyard or hand",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::GRAVEYARD.bits()),
            Some(RelativeControl::You),
        ),
        (
            "from a hand or graveyard",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::GRAVEYARD.bits()),
            None,
        ),
        (
            "from a graveyard or hand",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::GRAVEYARD.bits()),
            None,
        ),
        (
            "from your hand or library",
            ZoneMask::from_bits_truncate(ZoneMask::HAND.bits() | ZoneMask::LIBRARY.bits()),
            Some(RelativeControl::You),
        ),
    ] {
        if let Some(pre) = strip_suffix_word_ci(s, pat) {
            return (None, Some(mask), owner, pre);
        }
    }
    let (z, owner, pre) = extract_from_zone(s);
    (z, z.map(ZoneMask::from_zone), owner, pre)
}

fn parse_sacrifice_clause(
    t: &str,
    actor_sel: Selector,
    actor: Option<PlayerRef>,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) =
        strip_prefix_word_ci(t, "sacrifices").or_else(|| strip_prefix_word_ci(t, "sacrifice"))
    else {
        return false;
    };
    let (rest_no_unless, unless_opt) = if let Some(pos) = find_word_ci(rest, " unless you pay ") {
        let lhs = rest[..pos].trim();
        let cost_raw = rest[pos + " unless you pay ".len()..].trim();
        let cost_parse = crate::parser::cost::parse_cost_list(cost_raw, span.start, ctx);
        if !cost_parse.defs.is_empty() && cost_parse.unparsed.is_empty() {
            (
                lhs,
                Some(OptionalSpec {
                    chooser: PlayerRef::You,
                    cost: cost_parse.defs,
                    mode: OptionalMode::DoUnlessPaid,
                }),
            )
        } else {
            (rest, None)
        }
    } else {
        (rest, None)
    };
    let clean = strip_suffix_word_ci(rest_no_unless, "of their choice").unwrap_or(rest_no_unless);

    let each_loop_kind = match &actor_sel {
        Selector::Player { filter: pf } if pf.relation == PlayerRelation::EachOpponent => Some((
            LoopPlayersKind::EachOpponent,
            Some(PunisherPlayersKind::EachOpponent),
        )),
        Selector::Player { filter: pf } if pf.relation == PlayerRelation::EachPlayer => Some((
            LoopPlayersKind::EachPlayer,
            Some(PunisherPlayersKind::EachPlayer),
        )),
        Selector::PlayerRef {
            player: PlayerRef::EachLoopPlayer,
        } => Some((LoopPlayersKind::EachPlayer, None)),
        _ => None,
    };
    if let Some((loop_kind, pun_kind)) = each_loop_kind {
        if let Some(pun_players) = pun_kind
            && !starts_with_word_ci(clean, "all ")
            && !contains_word_ci(clean, "one or more")
            && find_word_ci(clean, " or ").is_some()
        {
            let cost_str = format!("sacrifice {clean}");
            let cp = ctx.interner.checkpoint();
            let cost_parse = crate::parser::cost::parse_cost_list(&cost_str, span.start, ctx);
            if !cost_parse.defs.is_empty() && cost_parse.unparsed.is_empty() {
                state.push_step(
                    make_step(
                        EffectOp::PunisherChoice {
                            spec: PunisherSpec {
                                players: Some(pun_players),
                                default_steps: Vec::new(),
                                unless_cost: cost_parse.defs,
                                unless_effect: Vec::new(),
                                unless_who: PlayerRef::EachLoopPlayer,
                                repeat_count: None,
                                may_first: false,
                                mandatory_if_able: true,
                                track_not_done_kind: None,
                                track_done_kind: None,
                            },
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            ctx.interner.rollback(cp);
        }

        if let Some(after_all) = strip_prefix_word_ci(clean, "all") {
            let f_str = if let Some(pos) = find_word_ci(after_all, " they control") {
                let left = after_all[..pos].trim();
                let right = after_all[pos + " they control".len()..].trim();
                if right.is_empty() {
                    left.to_string()
                } else {
                    format!("{left} {right}")
                }
            } else {
                after_all.to_string()
            };
            let toks = tokenize(&f_str, 0);
            let cp = ctx.interner.checkpoint();
            if let Some((mut f, used)) = parse_object_filter(
                &toks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::BATTLEFIELD,
                    allow_plural_and_disjunction: true,
                    ..Default::default()
                },
                state,
            ) && used == toks.len()
            {
                f.zones = ZoneMask::BATTLEFIELD;
                if f.controller.is_none() {
                    f.extra.push(ObjectPredicate::ControllerRef {
                        player: PlayerRef::EachLoopPlayer,
                    });
                }
                let mut inner = make_step(
                    EffectOp::Sacrifice {
                        select: SelectionMod::default(),
                    },
                    Selector::All {
                        filter: Box::new(f),
                    },
                    span,
                );
                inner.actor = Some(PlayerRef::EachLoopPlayer);
                if state.is_each_loop {
                    state.push_step(inner, false);
                } else {
                    state.push_step(
                        make_step(
                            EffectOp::ForEachPlayerLoop {
                                players: loop_kind,
                                steps: vec![inner],
                                choose_random_opponent: false,
                                exclude_attacked_last_combat: false,
                                exclude_event_player: false,
                                choose_object_to_bind: None,
                            },
                            Selector::None,
                            span,
                        ),
                        false,
                    );
                }
                return true;
            }
            ctx.interner.rollback(cp);
        }

        let mut greatest_pred: Option<ObjectPredicate> = None;
        let mut shares_type_binding: Option<String> = None;
        let mut sac_body = clean;
        for suf in [
            " of their choice that shares a card type with it",
            " that shares a card type with it",
        ] {
            if let Some(prefix) = strip_suffix_word_ci(sac_body, suf.trim()) {
                if let Some(b) = state.steps.iter().rev().find_map(|s| {
                    if matches!(s.op, EffectOp::Sacrifice { .. }) {
                        s.bind_as.clone()
                    } else {
                        None
                    }
                }) {
                    shares_type_binding = Some(b);
                    sac_body = prefix;
                }
                break;
            }
        }
        for (sep, stat) in [
            (" with the greatest mana value among ", StatKind::ManaValue),
            (" with the greatest power among ", StatKind::Power),
            (" with the greatest toughness among ", StatKind::Toughness),
        ] {
            if let Some(pos) = find_word_ci(sac_body, sep) {
                let lhs = sac_body[..pos].trim();
                let rhs = sac_body[pos + sep.len()..].trim();
                if let Some(scope_s) = strip_suffix_word_ci(rhs, "they control")
                    .or_else(|| strip_suffix_word_ci(rhs, "that player controls"))
                {
                    let stoks = tokenize(scope_s, 0);
                    let scp = ctx.interner.checkpoint();
                    if let Some((sf, sused)) = parse_object_filter(
                        &stoks,
                        ctx,
                        FilterOpts {
                            default_zone: ZoneMask::BATTLEFIELD,
                            allow_plural_and_disjunction: true,
                            ..Default::default()
                        },
                        state,
                    ) && sused == stoks.len()
                    {
                        greatest_pred = Some(ObjectPredicate::GreatestStatAmongControlled {
                            stat,
                            scope_types: sf.types_any,
                        });
                        sac_body = lhs;
                    } else {
                        ctx.interner.rollback(scp);
                    }
                }
                break;
            }
        }

        let toks = tokenize(sac_body, 0);
        if toks.len() >= 2 {
            let cnt_amt = match toks[0].kind {
                crate::lexer::TokenKind::Number(n) | crate::lexer::TokenKind::NumberWord(n) => {
                    Some(Amount::Const { n: n as i32 })
                }
                _ => {
                    let low = toks[0].raw.to_ascii_lowercase();
                    if low == "a" || low == "an" {
                        Some(Amount::Const { n: 1 })
                    } else {
                        parse_small_number(&low).map(|n| Amount::Const { n })
                    }
                }
            };
            if let Some(amt) = cnt_amt {
                let cp = ctx.interner.checkpoint();
                if let Some((mut f, used)) = parse_object_filter(
                    &toks[1..],
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::BATTLEFIELD,
                        allow_plural_and_disjunction: true,
                        ..Default::default()
                    },
                    state,
                ) && used == toks[1..].len()
                    && f.controller.is_none()
                {
                    f.zones = ZoneMask::BATTLEFIELD;
                    f.extra.push(ObjectPredicate::ControllerRef {
                        player: PlayerRef::EachLoopPlayer,
                    });
                    if let Some(gp) = greatest_pred {
                        f.extra.push(gp);
                    }
                    if let Some(b) = shares_type_binding {
                        f.extra
                            .push(ObjectPredicate::SharesCardTypeWithBinding { binding: b });
                    }
                    let mut inner = make_step(
                        EffectOp::Sacrifice {
                            select: SelectionMod::default(),
                        },
                        Selector::All {
                            filter: Box::new(f),
                        },
                        span,
                    );
                    inner.actor = Some(PlayerRef::EachLoopPlayer);
                    inner.amount = Some(Box::new(amt));
                    if state.is_each_loop {
                        state.push_step(inner, false);
                    } else {
                        state.push_step(
                            make_step(
                                EffectOp::ForEachPlayerLoop {
                                    players: loop_kind,
                                    steps: vec![inner],
                                    choose_random_opponent: false,
                                    exclude_attacked_last_combat: false,
                                    exclude_event_player: false,
                                    choose_object_to_bind: None,
                                },
                                Selector::None,
                                span,
                            ),
                            false,
                        );
                    }
                    return true;
                }
                ctx.interner.rollback(cp);
            }
        }
    }

    if let Some(after_any) = strip_prefix_word_ci(rest, "any number of")
        && let Some(mut obj) = parse_object_selector(after_any, ZoneMask::BATTLEFIELD, ctx, state)
    {
        if actor.is_none()
            && let ParsedObj::All(ref mut f) = obj
            && f.controller.is_none()
            && f.extra
                .iter()
                .all(|p| !matches!(p, ObjectPredicate::ControllerRef { .. }))
        {
            f.controller = Some(RelativeControl::You);
        } else if let Some(ref act) = actor
            && !matches!(act, PlayerRef::You)
            && let ParsedObj::All(ref mut f) = obj
            && f.controller.is_none()
            && !f
                .extra
                .iter()
                .any(|p| matches!(p, ObjectPredicate::ControllerRef { .. }))
        {
            f.extra.push(ObjectPredicate::ControllerRef {
                player: act.clone(),
            });
        }
        let mut st = make_step(
            EffectOp::Sacrifice {
                select: SelectionMod::default(),
            },
            obj.into_selector(),
            span,
        );
        st.actor = actor;
        st.amount = Some(Box::new(Amount::AnyNumber));
        state.push_step(st, true);
        return true;
    }
    let (clean_sac_lhs, sac_for_each_amt) = if let Some(fe_pos) = find_word_ci(clean, " for each ")
        && let Some(amt) = parse_amount_str(
            &format!("for each {}", clean[fe_pos + 10..].trim()),
            ctx,
            state,
        ) {
        (clean[..fe_pos].trim(), Some(amt))
    } else {
        (clean, None)
    };
    let clean_sac = strip_suffix_word_ci(clean_sac_lhs, "of their choice")
        .or_else(|| strip_suffix_word_ci(clean_sac_lhs, "of that player's choice"))
        .or_else(|| strip_suffix_word_ci(clean_sac_lhs, "of your choice"))
        .unwrap_or(clean_sac_lhs);
    if eq_ci(clean_sac, "one of them")
        && state.last_object.is_none()
        && let Some(tr) = state.trigger
        && let Some(TriggerSubject::Filter { filter }) = &tr.filter.object
    {
        let mut f = (**filter).clone();
        if f.zones.is_empty() {
            f.zones = ZoneMask::BATTLEFIELD;
        }
        if let Some(ref act) = actor
            && !matches!(act, PlayerRef::You)
            && f.controller.is_none()
            && !f
                .extra
                .iter()
                .any(|p| matches!(p, ObjectPredicate::ControllerRef { .. }))
        {
            f.extra.push(ObjectPredicate::ControllerRef {
                player: act.clone(),
            });
        }
        let mut st = make_step(
            EffectOp::Sacrifice {
                select: SelectionMod::default(),
            },
            Selector::All {
                filter: Box::new(f),
            },
            span,
        );
        st.actor = actor;
        st.amount = Some(Box::new(Amount::Const { n: 1 }));
        st.bind_as = Some(state.alloc_bind_name("sac"));
        if unless_opt.is_some() {
            st.optional = unless_opt;
        }
        state.push_step(st, true);
        return true;
    }
    if let Some(mut obj) = parse_object_selector(clean_sac, ZoneMask::BATTLEFIELD, ctx, state) {
        let single_ref = matches!(
            obj,
            ParsedObj::SelfObj | ParsedObj::EventObject | ParsedObj::Binding(_)
        );
        if let Some(ref act) = actor
            && !matches!(act, PlayerRef::You)
            && let ParsedObj::All(ref mut f) = obj
            && f.controller.is_none()
            && !f
                .extra
                .iter()
                .any(|p| matches!(p, ObjectPredicate::ControllerRef { .. }))
        {
            f.extra.push(ObjectPredicate::ControllerRef {
                player: act.clone(),
            });
        }
        let mut st = make_step(
            EffectOp::Sacrifice {
                select: SelectionMod::default(),
            },
            obj.into_selector(),
            span,
        );
        st.actor = actor;
        if let Some(amt) = sac_for_each_amt {
            st.amount = Some(Box::new(amt));
        } else if !single_ref {
            st.amount = Some(Box::new(Amount::Const { n: 1 }));
            if st.bind_as.is_none() {
                st.bind_as = Some(state.alloc_bind_name("sac"));
            }
        }
        if unless_opt.is_some() {
            st.optional = unless_opt;
        }
        state.push_step(st, true);
        return true;
    }
    let toks = tokenize(clean, 0);
    if toks.len() >= 2
        && !eq_ci(toks[0].raw, "a")
        && !eq_ci(toks[0].raw, "an")
        && let Some(amt) = parse_amount_str(toks[0].raw, ctx, state)
    {
        let cp = ctx.interner.checkpoint();
        if let Some((mut f, used)) = parse_object_filter(
            &toks[1..],
            ctx,
            FilterOpts {
                default_zone: ZoneMask::BATTLEFIELD,
                allow_plural_and_disjunction: true,
                ..Default::default()
            },
            state,
        ) && used == toks[1..].len()
        {
            f.zones = ZoneMask::BATTLEFIELD;
            if let Some(ref act) = actor
                && !matches!(act, PlayerRef::You)
                && f.controller.is_none()
                && !f
                    .extra
                    .iter()
                    .any(|p| matches!(p, ObjectPredicate::ControllerRef { .. }))
            {
                f.extra.push(ObjectPredicate::ControllerRef {
                    player: act.clone(),
                });
            }
            let mut st = make_step(
                EffectOp::Sacrifice {
                    select: SelectionMod::default(),
                },
                Selector::All {
                    filter: Box::new(f),
                },
                span,
            );
            st.actor = actor;
            st.amount = Some(Box::new(amt));
            state.push_step(st, true);
            return true;
        }
        ctx.interner.rollback(cp);
    }
    false
}

fn parse_tap_untap_clause(
    t: &str,
    is_tap: bool,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let kw = if is_tap { "tap" } else { "untap" };
    if let Some(rest) = strip_prefix_word_ci(t, "tap or untap")
        && let Some(obj) = parse_object_selector(rest, ZoneMask::BATTLEFIELD, ctx, state)
    {
        state.push_step(
            make_step(EffectOp::TapOrUntap, obj.into_selector(), span),
            true,
        );
        return true;
    }
    let Some(rest) = strip_prefix_word_ci(t, kw) else {
        return false;
    };
    let (freeze, subj_raw) = if is_tap
        && let Some(r) = strip_suffix_word_ci(
            rest,
            ". it doesn't untap during its controller's next untap step",
        )
        .or_else(|| {
            strip_suffix_word_ci(
                rest,
                "and it doesn't untap during its controller's next untap step",
            )
        }) {
        (true, r)
    } else {
        (false, rest)
    };
    let (select_mod, sel) = if let Some(after_up_to) = strip_prefix_word_ci(subj_raw, "up to")
        && !contains_word_ci(after_up_to, "target")
        && let Some((cnt_s, filt_s)) = after_up_to.split_once(char::is_whitespace)
        && let Some(amt) = parse_amount_str(cnt_s.trim(), ctx, state)
        && let Some(f) = parse_object_phrase(
            filt_s.trim(),
            ctx,
            FilterOpts {
                default_zone: ZoneMask::BATTLEFIELD,
                allow_plural_and_disjunction: true,
                allow_spell_noun: false,
                strip_trailing_card: false,
                expand_outlaw_subtypes: false,
            },
        ) {
        (
            SelectionMod {
                choice_count: Some(Box::new(amt)),
                up_to: true,
                ..Default::default()
            },
            Selector::All {
                filter: Box::new(f),
            },
        )
    } else if let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state) {
        (SelectionMod::default(), obj.into_selector())
    } else {
        let mut off = 0usize;
        while let Some(idx) = find_ascii_ci_from(subj_raw.as_bytes(), b" and ", off) {
            off = idx + 5;
            let lhs = subj_raw[..idx].trim();
            let rhs = subj_raw[idx + 5..].trim();
            if lhs.is_empty() || rhs.is_empty() {
                continue;
            }
            let mark = state.mark(ctx);
            if parse_tap_untap_clause(&format!("{kw} {lhs}"), is_tap, span, ctx, state)
                && parse_tap_untap_clause(&format!("{kw} {rhs}"), is_tap, span, ctx, state)
            {
                return true;
            }
            state.rollback(mark, ctx);
        }
        return false;
    };
    let op = if is_tap {
        EffectOp::Tap { select: select_mod }
    } else {
        EffectOp::Untap { select: select_mod }
    };
    let mut st = make_step(op, sel.clone(), span);
    if is_tap && matches!(sel, Selector::All { .. }) {
        st.bind_as = Some(state.alloc_bind_name("tapped"));
    }
    state.push_step(st, true);
    if freeze {
        let f_sel = state.it_ref().map(|r| ref_to_selector(&r)).unwrap_or(sel);
        state.push_step(
            make_step(EffectOp::FreezeUntap { duration: None }, f_sel, span),
            false,
        );
    }
    true
}

fn parse_counter_spell_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "counter") else {
        return false;
    };
    enum UnlessPay {
        None,
        Dynamic(Box<Amount>),
        OptionalCost(Vec<mtg_ir::CostDef>),
    }
    let (unless_pay, subj_raw) =
        if let Some(idx) = find_word_ci(rest, " unless its controller pays ") {
            let amt_s = rest[idx + " unless its controller pays ".len()..].trim();
            let cp_opt = if !contains_word_ci(amt_s, "for each") {
                let cp = crate::parser::cost::parse_cost_list(amt_s, 0, ctx);
                if !cp.defs.is_empty() && cp.unparsed.is_empty() {
                    Some(cp.defs)
                } else {
                    None
                }
            } else {
                None
            };
            if let Some(defs) = cp_opt {
                (UnlessPay::OptionalCost(defs), rest[..idx].trim())
            } else if let Some(fe_pos) = find_word_ci(amt_s, " for each ") {
                let mult_s = amt_s[..fe_pos]
                    .trim()
                    .trim_matches(|c| c == '{' || c == '}');
                let per_s = amt_s[fe_pos + 1..].trim();
                let Some(Amount::Const { n: factor }) = parse_amount_str(mult_s, ctx, state) else {
                    return false;
                };
                let Some(per_amt) = parse_amount_str(per_s, ctx, state) else {
                    return false;
                };
                let amt = if factor == 1 {
                    per_amt
                } else {
                    Amount::Mul {
                        factor,
                        of: Box::new(per_amt),
                    }
                };
                (UnlessPay::Dynamic(Box::new(amt)), rest[..idx].trim())
            } else {
                let clean_amt = amt_s.trim_matches(|c| c == '{' || c == '}');
                let Some(amt) = parse_amount_str(clean_amt, ctx, state) else {
                    return false;
                };
                (UnlessPay::Dynamic(Box::new(amt)), rest[..idx].trim())
            }
        } else {
            (UnlessPay::None, rest)
        };
    let (repl_zone, subj_raw2) = if let Some(r) = strip_suffix_word_ci(
        subj_raw,
        ". if that spell is countered this way, exile it instead of putting it into its owner's graveyard",
    ) {
        (Some(CounterReplacementZone::Exile), r)
    } else {
        (None, subj_raw)
    };
    let Some(obj) = parse_object_selector(subj_raw2, ZoneMask::STACK, ctx, state) else {
        return false;
    };
    let (unless_amt, opt_spec) = match unless_pay {
        UnlessPay::None => (None, None),
        UnlessPay::Dynamic(amt) => (Some(amt), None),
        UnlessPay::OptionalCost(cost) => {
            let of_ref = match &obj {
                ParsedObj::Target(index) => Ref::Target { index: *index },
                ParsedObj::SelfObj => Ref::SelfObj,
                ParsedObj::AttachedTo => Ref::AttachedTo,
                ParsedObj::EventObject => Ref::EventObject,
                ParsedObj::Binding(name) => Ref::Binding { name: name.clone() },
                ParsedObj::All(_) => Ref::EventObject,
            };
            (
                None,
                Some(OptionalSpec {
                    chooser: PlayerRef::ControllerOf {
                        of: Box::new(of_ref),
                    },
                    cost,
                    mode: OptionalMode::DoUnlessPaid,
                }),
            )
        }
    };
    let mut st = make_step(
        EffectOp::CounterSpell {
            replacement_zone: repl_zone,
            unless_pays_generic: unless_amt,
            on_countered_steal_filter: None,
        },
        obj.into_selector(),
        span,
    );
    st.optional = opt_spec;
    state.push_step(st, true);
    true
}

fn parse_put_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "put") else {
        return false;
    };

    if (rest.contains(',') || contains_word_ci(rest, " and "))
        && !contains_word_ci(rest, "if it's")
        && (contains_word_ci(rest, " counter on ") || contains_word_ci(rest, " counters on "))
        && !contains_word_ci(rest, "onto the battlefield")
        && !contains_word_ci(rest, "into your hand")
    {
        let mut parts: Vec<&str> = Vec::new();
        for seg in rest.split(',') {
            let s = seg.trim();
            if s.is_empty() {
                continue;
            }
            if let Some(after_and) = strip_prefix_word_ci(s, "and") {
                parts.push(after_and.trim());
            } else if let Some(p) = find_word_ci(s, " and ") {
                let l = s[..p].trim();
                let r = s[p + 5..].trim();
                if contains_word_ci(l, " on ") && contains_word_ci(r, " on ") {
                    parts.push(l);
                    parts.push(r);
                } else {
                    parts.push(s);
                }
            } else {
                parts.push(s);
            }
        }
        if parts.len() >= 2
            && parts.iter().all(|p| {
                contains_word_ci(p, " counter on ") || contains_word_ci(p, " counters on ")
            })
        {
            let mark = state.mark(ctx);
            let mut all_ok = true;
            for p in parts {
                let synth = format!("put {p}");
                if !parse_put_clause(&synth, span, ctx, state) {
                    all_ok = false;
                    break;
                }
            }
            if all_ok {
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    if let Some((dest_s, copy_src)) = strip_prefix_word_ci(rest, "~'s counters on")
        .or_else(|| strip_prefix_word_ci(rest, "all counters from ~ on"))
        .or_else(|| strip_prefix_word_ci(rest, "its counters on"))
        .map(|d| (d, Selector::SelfObj))
        .or_else(|| {
            strip_prefix_word_ci(rest, "those counters on").map(|d| {
                let src = if state.in_trigger_context() {
                    Selector::EventObject
                } else {
                    state
                        .it_ref()
                        .map(|r| ref_to_selector(&r))
                        .unwrap_or(Selector::SelfObj)
                };
                (d, src)
            })
        })
        && let Some(obj) = parse_object_selector(dest_s, ZoneMask::BATTLEFIELD, ctx, state)
    {
        state.push_step(
            make_step(
                EffectOp::PutCounters {
                    counter: None,
                    multi_counters: Vec::new(),
                    select: SelectionMod::default(),
                    divided: false,
                    allow_exile_counters: false,
                    remove_instead_of_add: false,
                    copy_counters_from: Some(Box::new(copy_src)),
                    choose_counter_on_subject_and_add_one: false,
                    conditional_counter_on_type: None,
                    cast_bolas_bonus_loyalty: false,
                },
                obj.into_selector(),
                span,
            ),
            true,
        );
        return true;
    }

    if contains_word_ci(rest, "if it's a creature")
        && contains_word_ci(rest, "if it's a planeswalker")
        && let Some(and_pos) = find_word_ci(rest, " and ")
        && let Some(p1_body) = strip_suffix_word_ci(rest[..and_pos].trim(), "if it's a creature")
        && let Some(p2_body) =
            strip_suffix_word_ci(rest[and_pos + 5..].trim(), "if it's a planeswalker")
    {
        fn extract_one<'a>(s: &'a str, ctx: &mut ParseCtx<'_>) -> Option<(CounterId, &'a str)> {
            let on_pos =
                find_word_ci(s, " counter on ").or_else(|| find_word_ci(s, " counters on "))?;
            let sep_len = if s[on_pos..].len() >= 13
                && s[on_pos..on_pos + 13].eq_ignore_ascii_case(" counters on ")
            {
                13
            } else {
                12
            };
            let lhs = s[..on_pos].trim();
            let target_s = s[on_pos + sep_len..].trim();
            let c_raw = strip_prefix_word_ci(lhs, "a")
                .or_else(|| strip_prefix_word_ci(lhs, "an"))
                .unwrap_or(lhs);
            let cname = normalize_counter_name(c_raw)?;
            Some((ctx.interner.intern_counter(&cname), target_s))
        }
        if let Some((c1, tgt1)) = extract_one(p1_body.trim(), ctx)
            && let Some((c2, tgt2)) = extract_one(p2_body.trim(), ctx)
            && (eq_ci(tgt2, "it") || eq_ci(tgt2, tgt1))
            && let Some(obj) = parse_object_selector(tgt1, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let mut st = make_step(
                EffectOp::PutCounters {
                    counter: None,
                    multi_counters: Vec::new(),
                    select: SelectionMod::default(),
                    divided: false,
                    allow_exile_counters: false,
                    remove_instead_of_add: false,
                    copy_counters_from: None,
                    choose_counter_on_subject_and_add_one: false,
                    conditional_counter_on_type: Some((c1, c2, false)),
                    cast_bolas_bonus_loyalty: false,
                },
                obj.into_selector(),
                span,
            );
            st.amount = Some(Box::new(Amount::Const { n: 1 }));
            state.push_step(st, true);
            return true;
        }
    }

    // Pattern A0: "put a number of <kind> counters [on <obj>] equal to <amt> [on <obj>]" (Szarel, Conformer Shuriken)
    if let Some(after_num_of) = strip_prefix_word_ci(rest, "a number of")
        && let Some((eq_pos, sep_len)) = find_word_ci(after_num_of, " counters equal to ")
            .map(|p| (p, " counters equal to ".len()))
            .or_else(|| {
                find_word_ci(after_num_of, " counter equal to ")
                    .map(|p| (p, " counter equal to ".len()))
            })
        && let Some(ctr_name) = normalize_counter_name(after_num_of[..eq_pos].trim())
    {
        let ctr_id = ctx.interner.intern_counter(&ctr_name);
        let after_eq = after_num_of[eq_pos + sep_len..].trim();
        let lower_eq = after_eq.to_ascii_lowercase();
        let mut on_positions = Vec::new();
        let mut off = 0usize;
        while let Some(rel) = lower_eq[off..].find(" on ") {
            on_positions.push(off + rel);
            off += rel + 4;
        }
        for pos in on_positions.into_iter().rev() {
            let amt_s = after_eq[..pos].trim();
            let target_raw = after_eq[pos + 4..].trim();
            let mark = state.mark(ctx);
            if let Some(amt) = parse_amount_str(amt_s, ctx, state)
                && let Some(obj) =
                    parse_object_selector(target_raw, ZoneMask::BATTLEFIELD, ctx, state)
            {
                let mut st = make_step(
                    EffectOp::PutCounters {
                        counter: Some(ctr_id),
                        multi_counters: Vec::new(),
                        select: SelectionMod::default(),
                        divided: false,
                        allow_exile_counters: false,
                        remove_instead_of_add: false,
                        copy_counters_from: None,
                        choose_counter_on_subject_and_add_one: false,
                        conditional_counter_on_type: None,
                        cast_bolas_bonus_loyalty: false,
                    },
                    obj.into_selector(),
                    span,
                );
                st.amount = Some(Box::new(amt));
                state.push_step(st, true);
                return true;
            }
            state.rollback(mark, ctx);
        }
    } else if let Some(after_num_of) = strip_prefix_word_ci(rest, "a number of")
        && let Some((on_pos, sep_len)) = find_word_ci(after_num_of, " counters on ")
            .map(|p| (p, " counters on ".len()))
            .or_else(|| {
                find_word_ci(after_num_of, " counter on ").map(|p| (p, " counter on ".len()))
            })
        && let Some(eq_pos) = find_word_ci(&after_num_of[on_pos + sep_len..], " equal to ")
        && let Some(ctr_name) = normalize_counter_name(after_num_of[..on_pos].trim())
    {
        let ctr_id = ctx.interner.intern_counter(&ctr_name);
        let tail = &after_num_of[on_pos + sep_len..];
        let target_raw = tail[..eq_pos].trim();
        let amt_s = tail[eq_pos + " equal to ".len()..].trim();
        let mark = state.mark(ctx);
        let amt_opt = if eq_ci(amt_s, "the difference") {
            state
                .last_compare
                .as_ref()
                .map(|(l, r)| Amount::Difference {
                    left: Box::new(l.clone()),
                    right: Box::new(r.clone()),
                })
        } else {
            None
        }
        .or_else(|| parse_amount_str(amt_s, ctx, state));
        if let Some(amt) = amt_opt
            && let Some(obj) = parse_object_selector(target_raw, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let mut st = make_step(
                EffectOp::PutCounters {
                    counter: Some(ctr_id),
                    multi_counters: Vec::new(),
                    select: SelectionMod::default(),
                    divided: false,
                    allow_exile_counters: false,
                    remove_instead_of_add: false,
                    copy_counters_from: None,
                    choose_counter_on_subject_and_add_one: false,
                    conditional_counter_on_type: None,
                    cast_bolas_bonus_loyalty: false,
                },
                obj.into_selector(),
                span,
            );
            st.amount = Some(Box::new(amt));
            state.push_step(st, true);
            return true;
        }
        state.rollback(mark, ctx);
    }

    // Pattern A: "put <N> <kind> counter(s) on <obj> [for each <expr>]"
    if let Some(on_pos) =
        find_word_ci(rest, " counter on ").or_else(|| find_word_ci(rest, " counters on "))
    {
        let word_len = if rest[on_pos..].len() >= " counters on ".len()
            && rest[on_pos..on_pos + " counters on ".len()].eq_ignore_ascii_case(" counters on ")
        {
            " counters on ".len()
        } else {
            " counter on ".len()
        };
        let left = rest[..on_pos].trim();
        let target_and_for = rest[on_pos + word_len..].trim();
        let (target_raw, for_each_s) = if let Some(fp) = find_word_ci(target_and_for, " for each ")
        {
            (
                target_and_for[..fp].trim(),
                Some(target_and_for[fp + " for each ".len()..].trim()),
            )
        } else {
            (target_and_for, None)
        };
        if for_each_s.is_none()
            && state.steps.is_empty()
            && state.targets.is_empty()
            && state.modal.is_none()
            && let Some(choice_body) = strip_prefix_word_ci(left, "your choice of")
            && let Some(or_pos) = find_word_ci(choice_body, " or ")
        {
            let parse_opt =
                |raw_opt: &str, ctx: &mut ParseCtx<'_>| -> Option<(Amount, CounterId)> {
                    let s = strip_suffix_word_ci(raw_opt.trim(), "counters")
                        .or_else(|| strip_suffix_word_ci(raw_opt.trim(), "counter"))
                        .unwrap_or(raw_opt.trim());
                    let (amt_w, ctr_w) = s.split_once(char::is_whitespace)?;
                    let amt = if eq_ci(amt_w.trim(), "a") || eq_ci(amt_w.trim(), "an") {
                        Amount::Const { n: 1 }
                    } else if let Some(n) = parse_small_number(amt_w.trim())
                        && n >= 1
                    {
                        Amount::Const { n }
                    } else {
                        return None;
                    };
                    let cname = normalize_counter_name(ctr_w.trim())?;
                    Some((amt, ctx.interner.intern_counter(&cname)))
                };
            let opt1_raw = choice_body[..or_pos].trim();
            let opt2_raw = choice_body[or_pos + " or ".len()..].trim();
            if let (Some((amt1, c1)), Some((amt2, c2))) =
                (parse_opt(opt1_raw, ctx), parse_opt(opt2_raw, ctx))
            {
                let mut build_mode = |amt: Amount, cid: CounterId| -> Option<ModalMode> {
                    let mut mstate =
                        ParserState::new(state.context, state.trigger, state.quoted_compiler);
                    let obj =
                        parse_object_selector(target_raw, ZoneMask::BATTLEFIELD, ctx, &mut mstate)?;
                    let mut st = make_step(
                        EffectOp::PutCounters {
                            counter: Some(cid),
                            multi_counters: Vec::new(),
                            select: SelectionMod::default(),
                            divided: false,
                            allow_exile_counters: false,
                            remove_instead_of_add: false,
                            copy_counters_from: None,
                            choose_counter_on_subject_and_add_one: false,
                            conditional_counter_on_type: None,
                            cast_bolas_bonus_loyalty: false,
                        },
                        obj.into_selector(),
                        span,
                    );
                    st.amount = Some(Box::new(amt));
                    mstate.push_step(st, false);
                    Some(ModalMode {
                        targets: mstate.targets,
                        effect: mstate.steps,
                        span,
                    })
                };
                if let (Some(m1), Some(m2)) = (build_mode(amt1, c1), build_mode(amt2, c2)) {
                    state.modal = Some(ModalDef {
                        min: 1,
                        max: 1,
                        allow_repeat: false,
                        once_per_turn_unique: false,
                        up_to: false,
                        conditional_choose_all: None,
                        modes: vec![m1, m2],
                        per_mode_costs: Vec::new(),
                        unchosen_permanent: false,
                        opponent_chooses: None,
                        pawprint_budget: None,
                        pawprint_costs: Vec::new(),
                        dynamic_max: None,
                        random_mode: false,
                        prefix_effect: Vec::new(),
                        suffix_effect: Vec::new(),
                        conditional_choose_range: None,
                        conditional_not_random: None,
                        different_player_targets_per_mode: false,
                    });
                    return true;
                }
            }
        }
        if for_each_s.is_none()
            && let Some(or_pos) = find_word_ci(left, " counter or ")
        {
            let c1_part = left[..or_pos].trim();
            let c2_part = left[or_pos + " counter or ".len()..].trim();
            let c1_clean = strip_prefix_word_ci(c1_part, "a")
                .or_else(|| strip_prefix_word_ci(c1_part, "an"))
                .unwrap_or(c1_part);
            let c2_clean = strip_prefix_word_ci(c2_part, "a")
                .or_else(|| strip_prefix_word_ci(c2_part, "an"))
                .unwrap_or(c2_part);
            if let (Some(n1), Some(n2)) = (
                normalize_counter_name(c1_clean),
                normalize_counter_name(c2_clean),
            ) {
                let c1 = ctx.interner.intern_counter(&n1);
                let c2 = ctx.interner.intern_counter(&n2);
                if let Some(obj) =
                    parse_object_selector(target_raw, ZoneMask::BATTLEFIELD, ctx, state)
                {
                    let mut st = make_step(
                        EffectOp::PutCounters {
                            counter: None,
                            multi_counters: Vec::new(),
                            select: SelectionMod::default(),
                            divided: false,
                            allow_exile_counters: false,
                            remove_instead_of_add: false,
                            copy_counters_from: None,
                            choose_counter_on_subject_and_add_one: false,
                            conditional_counter_on_type: Some((c1, c2, true)),
                            cast_bolas_bonus_loyalty: false,
                        },
                        obj.into_selector(),
                        span,
                    );
                    st.amount = Some(Box::new(Amount::Const { n: 1 }));
                    state.push_step(st, true);
                    return true;
                }
            }
        }
        if for_each_s.is_none() && (left.contains(',') || contains_word_ci(left, " and ")) {
            let mut items_raw: Vec<&str> = Vec::new();
            for seg in left.split(',') {
                let s = seg.trim();
                if s.is_empty() {
                    continue;
                }
                if let Some(after_and) = strip_prefix_word_ci(s, "and") {
                    items_raw.push(after_and.trim());
                } else if let Some(p) = find_word_ci(s, " and ") {
                    items_raw.push(s[..p].trim());
                    items_raw.push(s[p + 5..].trim());
                } else {
                    items_raw.push(s);
                }
            }
            if items_raw.len() >= 2 {
                let mut parsed_items: Vec<(CounterId, Box<Amount>)> = Vec::new();
                let mut ok = true;
                let mark_mc = state.mark(ctx);
                for it in &items_raw {
                    let s = strip_suffix_word_ci(it.trim(), "counters")
                        .or_else(|| strip_suffix_word_ci(it.trim(), "counter"))
                        .unwrap_or(it.trim())
                        .trim();
                    let Some((aw, cw)) = s.split_once(char::is_whitespace) else {
                        ok = false;
                        break;
                    };
                    let amt = if eq_ci(aw.trim(), "a") || eq_ci(aw.trim(), "an") {
                        Amount::Const { n: 1 }
                    } else if let Some(a) = parse_amount_str(aw.trim(), ctx, state) {
                        a
                    } else {
                        ok = false;
                        break;
                    };
                    let Some(cname) = normalize_counter_name(cw.trim()) else {
                        ok = false;
                        break;
                    };
                    parsed_items.push((ctx.interner.intern_counter(&cname), Box::new(amt)));
                }
                if ok
                    && parsed_items.len() >= 2
                    && let Some(obj) =
                        parse_object_selector(target_raw, ZoneMask::BATTLEFIELD, ctx, state)
                {
                    let mut st = make_step(
                        EffectOp::PutCounters {
                            counter: None,
                            multi_counters: parsed_items,
                            select: SelectionMod::default(),
                            divided: false,
                            allow_exile_counters: false,
                            remove_instead_of_add: false,
                            copy_counters_from: None,
                            choose_counter_on_subject_and_add_one: false,
                            conditional_counter_on_type: None,
                            cast_bolas_bonus_loyalty: false,
                        },
                        obj.into_selector(),
                        span,
                    );
                    st.amount = Some(Box::new(Amount::Const { n: 1 }));
                    state.push_step(st, true);
                    return true;
                }
                state.rollback(mark_mc, ctx);
            }
        }
        let (amt_s, ctr_s_owned, had_that_num) = if let Some(after_tn) =
            strip_prefix_word_ci(left, "that number of")
                .or_else(|| strip_prefix_word_ci(left, "that many"))
        {
            ("", after_tn.trim().to_string(), true)
        } else {
            let parts: Vec<&str> = left.split_whitespace().collect();
            if parts.len() >= 2 {
                (parts[0], parts[1..].join(" "), false)
            } else {
                ("", String::new(), false)
            }
        };
        if !ctr_s_owned.is_empty() {
            let ctr_s = ctr_s_owned;
            let base_amt = if had_that_num {
                if state.trigger_had_counter == Some(CounterTarget::Any) {
                    Some(Amount::LkiTotalCounters {
                        of: Ref::EventObject,
                    })
                } else {
                    Some(resolve_that_many_amount(state))
                }
            } else if eq_ci(amt_s, "a") || eq_ci(amt_s, "an") {
                Some(Amount::Const { n: 1 })
            } else {
                parse_amount_str(amt_s, ctx, state)
            };
            let amt = match (base_amt, for_each_s) {
                (Some(b), Some(fe)) => parse_amount_str(&format!("for each {fe}"), ctx, state)
                    .or_else(|| parse_amount_str(fe, ctx, state))
                    .map(|each_a| match b {
                        Amount::Const { n: 1 } => each_a,
                        Amount::Const { n } => Amount::Mul {
                            factor: n,
                            of: Box::new(each_a),
                        },
                        other => other,
                    }),
                (Some(b), None) => Some(b),
                _ => None,
            };
            if let Some(amt) = amt
                && let Some(ctr_name) = normalize_counter_name(&ctr_s)
            {
                let ctr_id = ctx.interner.intern_counter(&ctr_name);
                // Check if target is "you" / "target player" -> PutPlayerCounters
                if (eq_ci(target_raw, "you")
                    || eq_ci(target_raw, "target player")
                    || eq_ci(target_raw, "target opponent")
                    || eq_ci(target_raw, "each opponent")
                    || eq_ci(target_raw, "each player"))
                    && let Some(pkind) = player_counter_kind_from_name(&ctr_name)
                    && let Some(psel) = parse_player_selector(target_raw, ctx, state)
                {
                    let mut st =
                        make_step(EffectOp::PutPlayerCounters { counter: pkind }, psel, span);
                    st.amount = Some(Box::new(amt));
                    state.push_step(st, false);
                    return true;
                }
                if let Some(after_each_up) = strip_prefix_word_ci(target_raw, "each of up to")
                    && !contains_word_ci(after_each_up, "target")
                    && let Some((cnt_w, filt_s)) = after_each_up.split_once(char::is_whitespace)
                    && let Some(cnt_amt) = parse_amount_str(cnt_w.trim(), ctx, state)
                    && let Some(f) = parse_object_phrase(
                        filt_s.trim(),
                        ctx,
                        FilterOpts {
                            default_zone: ZoneMask::BATTLEFIELD,
                            allow_plural_and_disjunction: true,
                            allow_spell_noun: false,
                            strip_trailing_card: false,
                            expand_outlaw_subtypes: false,
                        },
                    )
                {
                    let mut st = make_step(
                        EffectOp::PutCounters {
                            counter: Some(ctr_id),
                            multi_counters: Vec::new(),
                            select: SelectionMod {
                                choice_count: Some(Box::new(cnt_amt)),
                                up_to: true,
                                ..Default::default()
                            },
                            divided: false,
                            allow_exile_counters: false,
                            remove_instead_of_add: false,
                            copy_counters_from: None,
                            choose_counter_on_subject_and_add_one: false,
                            conditional_counter_on_type: None,
                            cast_bolas_bonus_loyalty: false,
                        },
                        Selector::All {
                            filter: Box::new(f),
                        },
                        span,
                    );
                    st.amount = Some(Box::new(amt));
                    state.push_step(st, true);
                    return true;
                }
                if let Some(obj) =
                    parse_object_selector(target_raw, ZoneMask::BATTLEFIELD, ctx, state)
                {
                    let singular_obj = matches!(obj, ParsedObj::All(_))
                        && (starts_with_word_ci(target_raw, "a ")
                            || starts_with_word_ci(target_raw, "an "));
                    let mut st = make_step(
                        EffectOp::PutCounters {
                            counter: Some(ctr_id),
                            multi_counters: Vec::new(),
                            select: SelectionMod {
                                choice_count: singular_obj
                                    .then(|| Box::new(Amount::Const { n: 1 })),
                                ..Default::default()
                            },
                            divided: false,
                            allow_exile_counters: false,
                            remove_instead_of_add: false,
                            copy_counters_from: None,
                            choose_counter_on_subject_and_add_one: false,
                            conditional_counter_on_type: None,
                            cast_bolas_bonus_loyalty: false,
                        },
                        obj.into_selector(),
                        span,
                    );
                    st.amount = Some(Box::new(amt));
                    state.push_step(st, true);
                    return true;
                }
            }
        }
    }

    // Pattern B: "put <obj> on (the top|bottom) of <player>'s library" or "onto the battlefield" / "into <zone>"
    if let Some(onto_pos) = find_word_ci(rest, " onto the battlefield") {
        let obj_s = rest[..onto_pos].trim();
        let after_raw = rest[onto_pos + " onto the battlefield".len()..].trim();
        let (after_raw, attach_tail) = if let Some(ap) = find_word_ci(after_raw, "and attach ") {
            (
                after_raw[..ap].trim(),
                Some(after_raw[ap + "and attach ".len()..].trim()),
            )
        } else if let Some(rest_att) = strip_prefix_word_ci(after_raw, "attach") {
            ("", Some(rest_att))
        } else {
            (after_raw, None)
        };
        let after_raw = if state
            .steps
            .iter()
            .any(|s| matches!(s.op, EffectOp::Vote { .. }))
            && let Some(r) = strip_suffix_word_ci(after_raw, "for each free vote")
        {
            r
        } else {
            after_raw
        };
        let mark = state.mark(ctx);
        let (with_counters, after) = extract_with_counters(after_raw, ctx);
        if find_word_ci(after, "if ").is_some()
            || find_word_ci(after, "when ").is_some()
            || find_word_ci(after, "unless ").is_some()
            || find_word_ci(after, "where ").is_some()
        {
            state.rollback(mark, ctx);
            return false;
        }
        let mut tapped = false;
        let mut attacking = false;
        let mut under_your = false;
        let mut under_owner = false;
        let mut rem = after.trim();
        loop {
            if let Some(r) = strip_prefix_word_ci(rem, "tapped and attacking") {
                tapped = true;
                attacking = true;
                rem = r.trim();
            } else if let Some(r) = strip_prefix_word_ci(rem, "tapped") {
                tapped = true;
                rem = r.trim();
            } else if !tapped && let Some(r) = strip_prefix_word_ci(rem, "and tapped") {
                tapped = true;
                rem = r.trim();
            } else if let Some(r) = strip_prefix_word_ci(rem, "under your control") {
                under_your = true;
                rem = r.trim();
            } else if let Some(r) = strip_prefix_word_ci(rem, "under its owner's control")
                .or_else(|| strip_prefix_word_ci(rem, "under their owner's control"))
                .or_else(|| strip_prefix_word_ci(rem, "under their owners' control"))
            {
                under_owner = true;
                rem = r.trim();
            } else {
                break;
            }
        }
        if !rem.is_empty() {
            state.rollback(mark, ctx);
            return false;
        }
        let (from_z, from_mask, from_owner, clean_obj) = extract_from_zone_or_mask(obj_s);
        let dz = from_mask.unwrap_or(ZoneMask::HAND);
        if eq_ci(clean_obj, "one of them")
            && matches!(
                state.trigger.and_then(|tr| tr.filter.detail.as_ref()),
                Some(EventDetail::ZoneChange {
                    to: Some(Zone::Graveyard),
                    ..
                })
            )
        {
            let mut st = make_step(
                EffectOp::Move {
                    from: from_z.or(Some(Zone::Graveyard)),
                    to: Some(Zone::Battlefield),
                    select: SelectionMod {
                        choice_count: Some(Box::new(Amount::Const { n: 1 })),
                        ..SelectionMod::default()
                    },
                    tapped,
                    under_your_control: under_your || !under_owner,
                    topmost_only: false,
                    may_shuffle: false,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: attacking,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                Selector::EventObject,
                span,
            );
            st.bind_as = Some(state.alloc_bind_name("moved"));
            state.push_step(st, true);
            if let Some(att_s) = attach_tail {
                let att_clause = format!("attach {att_s}");
                if !parse_attach_clause(&att_clause, span, ctx, state) {
                    state.rollback(mark, ctx);
                    return false;
                }
            }
            return true;
        }
        if let Some(before_among) = strip_suffix_word_ci(clean_obj, "from among them")
            && let Some(mill_idx) = state
                .steps
                .iter()
                .rposition(|s| matches!(s.op, EffectOp::Mill))
        {
            let (up_to_among, elem_raw) =
                if let Some(r) = strip_prefix_word_ci(before_among, "up to") {
                    (true, r)
                } else {
                    (false, before_among)
                };
            let first_w = elem_raw.split_whitespace().next().unwrap_or("");
            let cnt_n = if eq_ci(first_w, "a") || eq_ci(first_w, "an") {
                1u16
            } else if let Some(n) = parse_small_number(first_w) {
                n.max(1) as u16
            } else {
                1u16
            };
            let filt_s = if eq_ci(first_w, "a")
                || eq_ci(first_w, "an")
                || parse_small_number(first_w).is_some()
            {
                elem_raw[first_w.len()..].trim()
            } else {
                elem_raw
            };
            if let Some(mut f) = parse_object_phrase(
                filt_s,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: true,
                    ..Default::default()
                },
            ) {
                f.zones = ZoneMask::empty();
                let bname = if let Some(existing) = state.steps[mill_idx].bind_as.clone() {
                    existing
                } else {
                    let b = state.alloc_bind_name("b");
                    state.steps[mill_idx].bind_as = Some(b.clone());
                    b
                };
                let mut st = make_step(
                    EffectOp::Move {
                        from: from_z,
                        to: Some(Zone::Battlefield),
                        select: SelectionMod {
                            choice_count: Some(Box::new(Amount::Const { n: cnt_n as i32 })),
                            up_to: up_to_among,
                            filter: Some(Box::new(f)),
                            ..SelectionMod::default()
                        },
                        tapped,
                        under_your_control: under_your,
                        topmost_only: false,
                        may_shuffle: false,
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: attacking,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    Selector::Binding { name: bname },
                    span,
                );
                st.bind_as = Some(state.alloc_bind_name("moved"));
                state.push_step(st, true);
                if let Some(att_s) = attach_tail {
                    let att_clause = format!("attach {att_s}");
                    if !parse_attach_clause(&att_clause, span, ctx, state) {
                        state.rollback(mark, ctx);
                        return false;
                    }
                }
                return true;
            }
            state.rollback(mark.clone(), ctx);
        }
        let mut up_to_amt_override: Option<(bool, Amount)> = None;
        let mut is_any_number = false;
        let obj_opt = if let Some(after_any) = strip_prefix_word_ci(clean_obj, "any number of")
            && !contains_word_ci(after_any, "target")
            && let Some(o) = parse_object_selector(after_any.trim(), dz, ctx, state)
            && matches!(&o, ParsedObj::All(_))
        {
            is_any_number = true;
            Some(o)
        } else if let Some(o) = parse_object_selector(clean_obj, dz, ctx, state) {
            Some(o)
        } else if !contains_word_ci(clean_obj, "target")
            && let Some((up_to_flag, after_up)) = strip_prefix_word_ci(clean_obj, "up to")
                .map(|r| (true, r))
                .or(Some((false, clean_obj)))
            && let Some((amt_tok, filt_s)) = after_up.split_once(char::is_whitespace)
            && !eq_ci(amt_tok.trim(), "a")
            && !eq_ci(amt_tok.trim(), "an")
            && let Some(amt) = parse_amount_str(amt_tok.trim(), ctx, state)
            && let Some(o) = parse_object_selector(filt_s.trim(), dz, ctx, state)
            && matches!(&o, ParsedObj::All(_))
        {
            up_to_amt_override = Some((up_to_flag, amt));
            Some(o)
        } else {
            None
        };
        if let Some(mut obj) = obj_opt {
            apply_extracted_from_owner(&mut obj, from_owner, state);
            if let ParsedObj::All(ref mut f) = obj
                && from_z == Some(Zone::Exile)
                && !f.extra.iter().any(|p| {
                    matches!(
                        p,
                        ObjectPredicate::ExiledWithSelf | ObjectPredicate::ExiledByAnyPlayer
                    )
                })
            {
                f.extra.push(ObjectPredicate::ExiledByAnyPlayer);
            }
            let from_z = from_z.or_else(|| match &obj {
                ParsedObj::All(f)
                    if f.extra
                        .iter()
                        .any(|e| matches!(e, ObjectPredicate::ExiledWithSelf)) =>
                {
                    Some(Zone::Exile)
                }
                ParsedObj::Binding(bname) => state.steps.iter().rev().find_map(|s| {
                    if s.bind_as.as_deref() == Some(bname.as_str())
                        && let EffectOp::ForEachPlayerLoop {
                            choose_object_to_bind: Some((f, _)),
                            ..
                        } = &s.op
                    {
                        if f.zones == ZoneMask::GRAVEYARD {
                            Some(Zone::Graveyard)
                        } else if f.zones == ZoneMask::EXILE {
                            Some(Zone::Exile)
                        } else if f.zones == ZoneMask::HAND {
                            Some(Zone::Hand)
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                }),
                _ => None,
            });
            let (up_to_lead, select_cnt, move_amt) = if is_any_number {
                (true, Some(Amount::Const { n: 99 }), None)
            } else if let Some((up_f, ov_amt)) = up_to_amt_override {
                (up_f, Some(ov_amt.clone()), Some(ov_amt))
            } else {
                let (up_to_lead, cnt_rest) =
                    if let Some(r) = strip_prefix_word_ci(clean_obj, "up to") {
                        (true, r)
                    } else {
                        (false, clean_obj)
                    };
                let first_w = cnt_rest.split_whitespace().next().unwrap_or("");
                let move_amt = if matches!(&obj, ParsedObj::All(_)) {
                    if eq_ci(first_w, "a") || eq_ci(first_w, "an") {
                        Some(Amount::Const { n: 1 })
                    } else {
                        parse_small_number(first_w).map(|n| Amount::Const { n })
                    }
                } else {
                    None
                };
                (up_to_lead, move_amt.clone(), move_amt)
            };
            let mut st = make_step(
                EffectOp::Move {
                    from: from_z,
                    to: Some(Zone::Battlefield),
                    select: SelectionMod {
                        up_to: up_to_lead,
                        choice_count: select_cnt.map(Box::new),
                        ..SelectionMod::default()
                    },
                    tapped,
                    under_your_control: under_your,
                    topmost_only: false,
                    may_shuffle: false,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: attacking,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                obj.into_selector(),
                span,
            );
            if let Some(a) = move_amt {
                st.amount = Some(Box::new(a));
            }
            st.bind_as = Some(state.alloc_bind_name("moved"));
            state.push_step(st, true);
            if let Some(att_s) = attach_tail {
                let att_clause = format!("attach {att_s}");
                if !parse_attach_clause(&att_clause, span, ctx, state) {
                    state.rollback(mark, ctx);
                    return false;
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }

    let (random_order, rest_lib) = if let Some(r) = strip_suffix_word_ci(rest, "in a random order")
    {
        (true, r)
    } else {
        (false, rest)
    };
    let is_valid_lib_tail = |tail: &str| -> bool {
        let lib = strip_suffix_word_ci(tail.trim(), "in any order")
            .unwrap_or(tail.trim())
            .trim();
        eq_ci(lib, "your library")
            || eq_ci(lib, "their library")
            || eq_ci(lib, "that library")
            || eq_ci(lib, "that player's library")
            || eq_ci(lib, "its owner's library")
            || eq_ci(lib, "their owner's library")
            || eq_ci(lib, "their owners' library")
            || eq_ci(lib, "their owners' libraries")
    };
    let lib_dest = find_word_ci(rest_lib, " on top of ")
        .and_then(|p| {
            is_valid_lib_tail(&rest_lib[p + " on top of ".len()..]).then_some((p, false, None))
        })
        .or_else(|| {
            find_word_ci(rest_lib, " on the top of ").and_then(|p| {
                is_valid_lib_tail(&rest_lib[p + " on the top of ".len()..])
                    .then_some((p, false, None))
            })
        })
        .or_else(|| {
            find_word_ci(rest_lib, " on the bottom of ").and_then(|p| {
                is_valid_lib_tail(&rest_lib[p + " on the bottom of ".len()..])
                    .then_some((p, true, None))
            })
        })
        .or_else(|| {
            for marker in [
                " into its owner's library ",
                " into their owner's library ",
                " into their owners' libraries ",
                " into your library ",
            ] {
                if let Some(p) = find_word_ci(rest_lib, marker) {
                    let tail = rest_lib[p + marker.len()..].trim();
                    if let Some(ord_s) = strip_suffix_word_ci(tail, "from the top") {
                        let n: Option<u16> = if eq_ci(ord_s, "first") {
                            Some(1)
                        } else if eq_ci(ord_s, "second") {
                            Some(2)
                        } else if eq_ci(ord_s, "third") {
                            Some(3)
                        } else if eq_ci(ord_s, "fourth") {
                            Some(4)
                        } else if eq_ci(ord_s, "fifth") {
                            Some(5)
                        } else if eq_ci(ord_s, "sixth") {
                            Some(6)
                        } else if eq_ci(ord_s, "seventh") {
                            Some(7)
                        } else if eq_ci(ord_s, "eighth") {
                            Some(8)
                        } else if eq_ci(ord_s, "ninth") {
                            Some(9)
                        } else if eq_ci(ord_s, "tenth") {
                            Some(10)
                        } else {
                            None
                        };
                        if let Some(ft) = n {
                            return Some((p, false, Some(ft)));
                        }
                    }
                }
            }
            None
        });
    if let Some((pos, is_bottom, from_top_val)) = lib_dest {
        let obj_s = rest_lib[..pos].trim();
        let (from_zone, from_owner, clean_subj) = extract_from_zone(obj_s);
        let dz = from_zone
            .map(ZoneMask::from_zone)
            .unwrap_or(ZoneMask::BATTLEFIELD);
        let (count_amt, count_rest) = if let Some(r) = strip_prefix_word_ci(clean_subj, "up to") {
            let fw = r.split_whitespace().next().unwrap_or("");
            if let Some(n) = parse_small_number(fw) {
                let tail = r[fw.len()..].trim_start();
                (Some((Amount::Const { n }, true)), tail)
            } else {
                (None, clean_subj)
            }
        } else {
            let fw = clean_subj.split_whitespace().next().unwrap_or("");
            if eq_ci(fw, "a") || eq_ci(fw, "an") {
                (
                    Some((Amount::Const { n: 1 }, false)),
                    clean_subj[fw.len()..].trim_start(),
                )
            } else if let Some(n) = parse_small_number(fw) {
                (
                    Some((Amount::Const { n }, false)),
                    clean_subj[fw.len()..].trim_start(),
                )
            } else {
                (None, clean_subj)
            }
        };
        let obj_opt = if eq_ci(clean_subj, "all the cards") || eq_ci(clean_subj, "all cards") {
            Some(ParsedObj::All(ObjectFilter {
                zones: dz,
                ..Default::default()
            }))
        } else {
            parse_object_selector(clean_subj, dz, ctx, state).or_else(|| {
                let (_, up_to_flag) = count_amt.as_ref().map(|(a, u)| (a, *u))?;
                let _ = up_to_flag;
                if eq_ci(count_rest, "card") || eq_ci(count_rest, "cards") {
                    Some(ParsedObj::All(ObjectFilter {
                        zones: dz,
                        ..Default::default()
                    }))
                } else {
                    parse_object_selector(count_rest, dz, ctx, state)
                }
            })
        };
        if let Some(mut obj) = obj_opt {
            apply_extracted_from_owner(&mut obj, from_owner, state);
            let eff_from = from_zone.or_else(|| {
                if matches!(obj, ParsedObj::SelfObj | ParsedObj::EventObject)
                    && state.trigger.is_some_and(|tr| {
                        matches!(
                            tr.filter.detail.as_ref(),
                            Some(EventDetail::ZoneChange {
                                to: Some(Zone::Graveyard),
                                ..
                            })
                        )
                    })
                {
                    Some(Zone::Graveyard)
                } else if matches!(obj, ParsedObj::Target(_)) && from_top_val.is_some() {
                    Some(Zone::Battlefield)
                } else {
                    None
                }
            });
            let is_all_sel = matches!(obj, ParsedObj::All(_));
            let (choice_count, up_to, step_amt) = if is_all_sel && let Some((amt, u)) = count_amt {
                (Some(Box::new(amt.clone())), u, Some(Box::new(amt)))
            } else {
                (None, false, None)
            };
            let mut st = make_step(
                EffectOp::Move {
                    from: eff_from,
                    to: Some(Zone::Library),
                    select: SelectionMod {
                        choice_count,
                        up_to,
                        ..SelectionMod::default()
                    },
                    tapped: false,
                    under_your_control: false,
                    topmost_only: false,
                    may_shuffle: false,
                    position: Some(if is_bottom {
                        LibraryPosition::Bottom
                    } else {
                        LibraryPosition::Top
                    }),
                    from_top: from_top_val,
                    library_choice_by: None,
                    random_order,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                obj.into_selector(),
                span,
            );
            if let Some(a) = step_amt {
                st.amount = Some(a);
            }
            state.push_step(st, true);
            return true;
        }
    }

    let (trail_from, trail_owner, rest_no_from) = extract_from_zone(rest);
    if let Some(obj_s) = strip_suffix_word_ci(rest, "into your hand")
        .or_else(|| trail_from.and_then(|_| strip_suffix_word_ci(rest_no_from, "into your hand")))
    {
        let (eff_trail_from, eff_trail_owner) =
            if strip_suffix_word_ci(rest, "into your hand").is_some() {
                (None, None)
            } else {
                (trail_from, trail_owner)
            };
        if let Some(fa_pos) = find_word_ci(obj_s, " from among ") {
            let filter_raw = obj_s[..fa_pos].trim();
            let src_raw = obj_s[fa_pos + " from among ".len()..].trim();
            let src_sel = if src_raw.to_ascii_lowercase().contains("milled this way")
                || eq_ci(src_raw, "them")
                || eq_ci(src_raw, "those cards")
            {
                state.it_ref().map(|r| ref_to_selector(&r))
            } else {
                parse_object_selector(src_raw, ZoneMask::GRAVEYARD, ctx, state)
                    .map(ParsedObj::into_selector)
            };
            if let Some(subj) = src_sel {
                let fw = filter_raw.split_whitespace().next().unwrap_or("");
                let (cnt_opt, f_tail) = if eq_ci(fw, "a") || eq_ci(fw, "an") {
                    (Some(Amount::Const { n: 1 }), filter_raw[fw.len()..].trim())
                } else if let Some(n) = parse_small_number(fw) {
                    (Some(Amount::Const { n }), filter_raw[fw.len()..].trim())
                } else {
                    (None, filter_raw)
                };
                let bare_card = eq_ci(f_tail, "card") || eq_ci(f_tail, "cards");
                let ftoks = tokenize(f_tail, 0);
                let cp = ctx.interner.checkpoint();
                let parsed_filter = if bare_card {
                    Some(None)
                } else if let Some((mut f, used)) = parse_object_filter(
                    &ftoks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::empty(),
                        allow_plural_and_disjunction: true,
                        strip_trailing_card: true,
                        ..Default::default()
                    },
                    state,
                ) && used == ftoks.len()
                {
                    f.zones = ZoneMask::empty();
                    Some(Some(Box::new(f)))
                } else {
                    None
                };
                if let Some(sel_filter) = parsed_filter {
                    let from_zone = if let Selector::Binding { ref name } = subj
                        && state.steps.iter().rev().any(|s| {
                            s.bind_as.as_deref() == Some(name.as_str())
                                && matches!(s.op, EffectOp::Mill)
                        }) {
                        Some(Zone::Graveyard)
                    } else {
                        None
                    };
                    let st = make_step(
                        EffectOp::Move {
                            from: from_zone,
                            to: Some(Zone::Hand),
                            select: SelectionMod {
                                choice_count: cnt_opt.map(Box::new),
                                filter: sel_filter,
                                ..SelectionMod::default()
                            },
                            tapped: false,
                            under_your_control: false,
                            topmost_only: false,
                            may_shuffle: false,
                            position: None,
                            from_top: None,
                            library_choice_by: None,
                            random_order: false,
                            entered_transformed: false,
                            entered_flipped: false,
                            enters_tapped_and_attacking: false,
                            as_enchantment_only: false,
                            unearth: false,
                            with_counters: None,
                            attached_to: None,
                            condition: None,
                            choose_at_random_from_exiled_with_self: false,
                            leave_chosen_in_graveyard_rest_to_hand: false,
                            split_exiled_cost_cards_to_bottom_and_battlefield: false,
                        },
                        subj,
                        span,
                    );
                    state.push_step(st, true);
                    return true;
                }
                ctx.interner.rollback(cp);
            }
        }
        let (from_z, from_owner, clean_obj) = extract_from_zone(obj_s);
        let from_z = from_z.or(eff_trail_from);
        let from_owner = from_owner.or(eff_trail_owner);
        let dz = from_z.map(ZoneMask::from_zone).unwrap_or(ZoneMask::LIBRARY);
        let mark = state.mark(ctx);
        if let Some(mut obj) = parse_object_selector(clean_obj, dz, ctx, state) {
            apply_extracted_from_owner(&mut obj, from_owner, state);
            let cmd_choice = matches!(&obj, ParsedObj::All(f) if from_z == Some(Zone::Command) && f.flags.contains(FilterFlags::IS_COMMANDER));
            let sel = obj.into_selector();
            let eff_from = from_z.or_else(|| {
                if let Selector::Binding { name } = &sel {
                    if state.parent_exile_bindings.iter().any(|b| b == name)
                        || state.steps.iter().rev().any(|s| {
                            (s.bind_as.as_deref() == Some(name.as_str())
                                && matches!(
                                    s.op,
                                    EffectOp::Exile { .. } | EffectOp::ExileUntil { .. }
                                ))
                                || (name == "exiled" && matches!(s.op, EffectOp::ExileUntil { .. }))
                        })
                    {
                        Some(Zone::Exile)
                    } else if state.steps.iter().rev().any(|s| {
                        s.bind_as.as_deref() == Some(name.as_str())
                            && matches!(s.op, EffectOp::Reveal { .. })
                            && matches!(s.subject, Selector::LibraryTop { .. })
                    }) {
                        Some(Zone::Library)
                    } else {
                        None
                    }
                } else {
                    None
                }
            });
            state.push_step(
                make_step(
                    EffectOp::Move {
                        from: eff_from,
                        to: Some(Zone::Hand),
                        select: SelectionMod {
                            choice_count: cmd_choice.then(|| Box::new(Amount::Const { n: 1 })),
                            ..SelectionMod::default()
                        },
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: false,
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    sel,
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }

    for gy_suf in [
        "into their owners' graveyards",
        "into their owner's graveyard",
        "into its owner's graveyard",
        "into your graveyard",
        "into a graveyard",
        "to their owners' graveyards",
        "to their owner's graveyard",
        "to its owner's graveyard",
        "to your graveyard",
        "to a graveyard",
    ] {
        if let Some(obj_raw) = strip_suffix_word_ci(rest, gy_suf) {
            let (from_zone, from_owner, clean_obj) = extract_from_zone(obj_raw);
            let dz = from_zone
                .map(ZoneMask::from_zone)
                .unwrap_or(ZoneMask::EXILE);
            let (up_to_flag, after_up) = if let Some(r) = strip_prefix_word_ci(clean_obj, "up to") {
                (true, r)
            } else {
                (false, clean_obj)
            };
            let fw = after_up.split_whitespace().next().unwrap_or("");
            let (cnt_amt, filter_s) = if eq_ci(fw, "a") || eq_ci(fw, "an") {
                (Some(Amount::Const { n: 1 }), after_up[fw.len()..].trim())
            } else if let Some(n) = parse_small_number(fw) {
                (Some(Amount::Const { n }), after_up[fw.len()..].trim())
            } else {
                (None, after_up)
            };
            let mark = state.mark(ctx);
            let obj_opt = parse_object_selector(filter_s, dz, ctx, state)
                .or_else(|| parse_object_selector(clean_obj, dz, ctx, state));
            if let Some(mut obj) = obj_opt {
                apply_extracted_from_owner(&mut obj, from_owner, state);
                let is_all = matches!(&obj, ParsedObj::All(_));
                if let ParsedObj::All(ref mut f) = obj
                    && from_zone == Some(Zone::Exile)
                    && !f.extra.iter().any(|p| {
                        matches!(
                            p,
                            ObjectPredicate::ExiledWithSelf | ObjectPredicate::ExiledByAnyPlayer
                        )
                    })
                {
                    f.extra.push(ObjectPredicate::ExiledByAnyPlayer);
                }
                let inferred_from = from_zone.or_else(|| {
                    if contains_word_ci(obj_raw, "exiled with")
                        || matches!(&obj, ParsedObj::All(f) if f.extra.iter().any(|p| matches!(p, ObjectPredicate::ExiledWithSelf)))
                    {
                        Some(Zone::Exile)
                    } else {
                        None
                    }
                });
                let mut st = make_step(
                    EffectOp::Move {
                        from: inferred_from,
                        to: Some(Zone::Graveyard),
                        select: if is_all {
                            SelectionMod {
                                choice_count: cnt_amt.as_ref().map(|a| Box::new(a.clone())),
                                up_to: up_to_flag,
                                ..SelectionMod::default()
                            }
                        } else {
                            SelectionMod::default()
                        },
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: false,
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    obj.into_selector(),
                    span,
                );
                if is_all && let Some(a) = cnt_amt {
                    st.amount = Some(Box::new(a));
                }
                state.push_step(st, true);
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    false
}

fn player_counter_kind_from_name(name: &str) -> Option<PlayerCounterKind> {
    match name.to_ascii_lowercase().as_str() {
        "poison" => Some(PlayerCounterKind::Poison),
        "experience" => Some(PlayerCounterKind::Experience),
        "energy" => Some(PlayerCounterKind::Energy),
        "rad" => Some(PlayerCounterKind::Rad),
        "ticket" => Some(PlayerCounterKind::Ticket),
        _ => None,
    }
}

fn parse_remove_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "remove") else {
        return false;
    };
    if let Some(subj_raw) = strip_suffix_word_ci(rest, "from combat")
        && let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state)
    {
        state.push_step(
            make_step(EffectOp::RemoveFromCombat, obj.into_selector(), span),
            true,
        );
        return true;
    }
    if let Some(from_pos) =
        find_word_ci(rest, " counters from ").or_else(|| find_word_ci(rest, " counter from "))
    {
        let word_len = if rest[from_pos..].len() >= " counters from ".len()
            && rest[from_pos..from_pos + " counters from ".len()]
                .eq_ignore_ascii_case(" counters from ")
        {
            " counters from ".len()
        } else {
            " counter from ".len()
        };
        let left = rest[..from_pos].trim();
        let (is_among, subj_clean) =
            if let Some(r) = strip_prefix_word_ci(rest[from_pos + word_len..].trim(), "among") {
                (true, r)
            } else {
                (false, rest[from_pos + word_len..].trim())
            };
        let (up_to, is_any_number, left_clean) =
            if let Some(r) = strip_prefix_word_ci(left, "up to") {
                (true, false, r)
            } else if let Some(r) = strip_prefix_word_ci(left, "any number of") {
                (true, true, r)
            } else {
                (false, false, left)
            };
        if is_any_number
            && let Some(mut obj) =
                parse_object_selector(subj_clean, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let ctr_s = if left_clean.is_empty() {
                "any"
            } else {
                left_clean
            };
            let cid = if eq_ci(ctr_s, "any") {
                Some(ctx.interner.intern_counter("any"))
            } else {
                normalize_counter_name(ctr_s).map(|n| ctx.interner.intern_counter(&n))
            };
            if is_among && let ParsedObj::All(ref mut f) = obj {
                f.flags |= FilterFlags::HAS_ANY_COUNTER;
            }
            let mut st = make_step(
                EffectOp::RemoveCounters {
                    counter: cid,
                    up_to: true,
                    if_unable_sacrifice_self: false,
                    remove_all_from_target_or_player: false,
                },
                obj.into_selector(),
                span,
            );
            st.amount = Some(Box::new(Amount::Const { n: 99 }));
            state.push_step(st, true);
            return true;
        }
        let parts: Vec<&str> = left_clean.split_whitespace().collect();
        if !parts.is_empty() {
            let (amt_s, ctr_s) = if parts.len() == 1 {
                (parts[0], "any".to_string())
            } else {
                (parts[0], parts[1..].join(" "))
            };
            let amt = if eq_ci(amt_s, "a") || eq_ci(amt_s, "an") {
                Some(Amount::Const { n: 1 })
            } else if eq_ci(amt_s, "all") {
                Some(Amount::Const { n: 999 })
            } else {
                parse_amount_str(amt_s, ctx, state)
            };
            if let Some(amt) = amt
                && let Some(mut obj) =
                    parse_object_selector(subj_clean, ZoneMask::BATTLEFIELD, ctx, state)
            {
                if is_among && let ParsedObj::All(ref mut f) = obj {
                    f.flags |= FilterFlags::HAS_ANY_COUNTER;
                }
                let cid = if eq_ci(&ctr_s, "any") {
                    Some(ctx.interner.intern_counter("any"))
                } else {
                    normalize_counter_name(&ctr_s).map(|n| ctx.interner.intern_counter(&n))
                };
                let mut st = make_step(
                    EffectOp::RemoveCounters {
                        counter: cid,
                        up_to,
                        if_unable_sacrifice_self: false,
                        remove_all_from_target_or_player: eq_ci(amt_s, "all")
                            && eq_ci(&ctr_s, "any"),
                    },
                    obj.into_selector(),
                    span,
                );
                st.amount = Some(Box::new(amt));
                state.push_step(st, true);
                return true;
            }
        }
    }
    false
}

fn parse_move_counters_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "move") else {
        return false;
    };
    let Some(from_pos) = find_word_ci(rest, " from ") else {
        return false;
    };
    let left = rest[..from_pos].trim();
    let after_from = rest[from_pos + 6..].trim();
    let Some(onto_pos) =
        find_word_ci(after_from, " onto ").or_else(|| find_word_ci(after_from, " to "))
    else {
        return false;
    };
    let sep_len = if after_from[onto_pos..].len() >= 6
        && after_from[onto_pos..onto_pos + 6].eq_ignore_ascii_case(" onto ")
    {
        6
    } else {
        4
    };
    let (from_any_permanents, src_clean) =
        if let Some(after_among) = strip_prefix_word_ci(after_from[..onto_pos].trim(), "among") {
            (true, after_among)
        } else {
            (false, after_from[..onto_pos].trim())
        };
    let dst_raw = after_from[onto_pos + sep_len..].trim();
    let Some(src) = parse_object_selector(src_clean, ZoneMask::BATTLEFIELD, ctx, state) else {
        return false;
    };
    let Some(dst) = parse_object_selector(dst_raw, ZoneMask::BATTLEFIELD, ctx, state) else {
        return false;
    };
    let is_all = starts_with_word_ci(left, "all");
    let is_any_num = starts_with_word_ci(left, "any number of");
    let is_one_or_more = starts_with_word_ci(left, "one or more");
    let is_each_kind_not_on_dest = contains_word_ci(left, "of each kind not on ");
    let ctr_strip = strip_suffix_word_ci(left, "counters")
        .or_else(|| strip_suffix_word_ci(left, "counter"))
        .unwrap_or("");
    let ctr_name_raw = if is_each_kind_not_on_dest {
        ""
    } else if let Some(r) = strip_prefix_word_ci(ctr_strip, "any number of") {
        r
    } else if let Some(r) = strip_prefix_word_ci(ctr_strip, "one or more") {
        r
    } else if let Some(r) = strip_prefix_word_ci(ctr_strip, "all") {
        r
    } else if let Some(r) =
        strip_prefix_word_ci(ctr_strip, "a").or_else(|| strip_prefix_word_ci(ctr_strip, "an"))
    {
        r
    } else {
        ctr_strip
    };
    let ctr_id = if ctr_name_raw.is_empty() {
        None
    } else {
        normalize_counter_name(ctr_name_raw).map(|n| ctx.interner.intern_counter(&n))
    };

    if let (Some(cid), ParsedObj::SelfObj, ParsedObj::All(f)) = (ctr_id, &src, &dst) {
        let mut st = make_step(
            EffectOp::MoveCounters {
                counter: Some(cid),
                to_filter: Some(Box::new(f.clone())),
                spec: None,
            },
            Selector::SelfObj,
            span,
        );
        if is_all || is_any_num {
            st.amount = Some(Box::new(Amount::Const { n: 999 }));
        }
        state.push_step(st, true);
        return true;
    }

    let mut st = make_step(
        EffectOp::MoveCounters {
            counter: None,
            to_filter: None,
            spec: Some(MoveCounterSpec {
                from: Box::new(src.into_selector()),
                counter: ctr_id
                    .map(CounterTarget::Specific)
                    .unwrap_or(CounterTarget::Any),
                all: is_all || is_any_num,
                up_to: false,
                each_kind_not_on_dest: is_each_kind_not_on_dest,
                one_or_more: is_one_or_more,
                from_any_permanents,
                choose_kind_on_permanent: !is_each_kind_not_on_dest
                    && ctr_id.is_none()
                    && !is_all
                    && !is_any_num
                    && !is_one_or_more,
                put_or_remove_kind: false,
                any_number: is_any_num,
            }),
        },
        dst.into_selector(),
        span,
    );
    st.amount = Some(Box::new(if is_all || is_any_num {
        Amount::Const { n: 999 }
    } else {
        Amount::Const { n: 1 }
    }));
    state.push_step(st, true);
    true
}

fn parse_attach_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "attach") else {
        return false;
    };
    let mut search_from = 0usize;
    let mut to_positions = Vec::new();
    while let Some(rel) = find_word_ci(&rest[search_from..], " to ") {
        let pos = search_from + rel;
        let before = rest[..pos].trim_end();
        let preceded_by_up = strip_suffix_word_ci(before, "up").is_some();
        if !preceded_by_up {
            to_positions.push(pos);
        }
        search_from = pos + 4;
    }
    for to_pos in to_positions.into_iter().rev() {
        let obj_raw = rest[..to_pos].trim();
        let dest_raw = rest[to_pos + 4..].trim();
        let mark = state.mark(ctx);
        if (eq_ci(obj_raw, "an equipment that was attached to ~")
            || eq_ci(obj_raw, "an equipment that was attached to it"))
            && let Some(host_obj) =
                parse_object_selector(dest_raw, ZoneMask::BATTLEFIELD, ctx, state)
        {
            state.push_step(
                make_step(
                    EffectOp::Attach {
                        attach_object: None,
                        select: SelectionMod::default(),
                        attach_equipment_from_self_lki: true,
                    },
                    host_obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark.clone(), ctx);
        if let Some(eq_obj) = parse_object_selector(obj_raw, ZoneMask::BATTLEFIELD, ctx, state)
            && let Some(host_obj) =
                parse_object_selector(dest_raw, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let singular_obj = matches!(eq_obj, ParsedObj::All(_))
                && (starts_with_word_ci(obj_raw, "a ") || starts_with_word_ci(obj_raw, "an "));
            let singular_host = matches!(host_obj, ParsedObj::All(_))
                && (starts_with_word_ci(dest_raw, "a ") || starts_with_word_ci(dest_raw, "an "));
            let attach_object = match eq_obj {
                ParsedObj::SelfObj => None,
                other => Some(Box::new(other.into_selector())),
            };
            state.push_step(
                make_step(
                    EffectOp::Attach {
                        attach_object,
                        select: SelectionMod {
                            choice_count: (singular_obj || singular_host)
                                .then(|| Box::new(Amount::Const { n: 1 })),
                            ..Default::default()
                        },
                        attach_equipment_from_self_lki: false,
                    },
                    host_obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    false
}

fn parse_gain_control_clause(
    rest: &str,
    dur_override: Option<Duration>,
    untap: bool,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let (subj_raw, dur) = parse_duration_suffix(rest);
    let dur = match dur {
        Some(Duration::ForAsLongAsYouControlSelf) => Some(Duration::UntilSourceLeaves),
        other => other,
    };
    let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state) else {
        return false;
    };
    state.push_step(
        make_step(
            EffectOp::GainControl {
                duration: dur_override.or(dur).or(Some(Duration::Permanent)),
                untap,
            },
            obj.into_selector(),
            span,
        ),
        true,
    );
    true
}

fn parse_prevent_damage_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "prevent") else {
        return false;
    };
    let low = rest.to_ascii_lowercase();
    if low
        == "all damage that would be dealt to you and planeswalkers you control this turn by sources you don't control"
        || low
            == "all damage that would be dealt this turn to you and planeswalkers you control by sources you don't control"
    {
        state.push_step(
            make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::All,
                        combat_only: false,
                        scope: PreventScope::Subject,
                        from_source: None,
                        also_prevent_dealt_by_subject: false,
                        choose_source: false,
                        next_damage_event_only: false,
                        on_prevented: None,
                        redirect_to: None,
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: true,
                        from_sources_you_dont_control: true,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if low == "that damage" {
        state.push_step(
            make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::All,
                        combat_only: false,
                        scope: PreventScope::Any,
                        from_source: None,
                        also_prevent_dealt_by_subject: false,
                        choose_source: false,
                        next_damage_event_only: false,
                        on_prevented: None,
                        redirect_to: None,
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: false,
                        from_sources_you_dont_control: false,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if low == "all combat damage that would be dealt this turn"
        || low == "all damage that would be dealt this turn"
    {
        let combat_only = low.starts_with("all combat");
        state.push_step(
            make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::All,
                        combat_only,
                        scope: PreventScope::Any,
                        from_source: None,
                        also_prevent_dealt_by_subject: false,
                        choose_source: false,
                        next_damage_event_only: false,
                        on_prevented: None,
                        redirect_to: None,
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: false,
                        from_sources_you_dont_control: false,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if let Some((combat_only, after_wbd, from_source_colors)) =
        strip_prefix_word_ci(rest, "all combat damage that")
            .map(|r| (true, r))
            .or_else(|| strip_prefix_word_ci(rest, "all damage that").map(|r| (false, r)))
            .and_then(|(co, after_that)| {
                if let Some(wbd) = strip_prefix_word_ci(after_that, "would be dealt") {
                    Some((co, wbd, ColorMask::empty()))
                } else if let Some((src_s, wbd)) = find_word_ci(after_that, "sources would deal")
                    .map(|p| {
                        (
                            after_that[..p].trim(),
                            after_that[p + "sources would deal".len()..].trim(),
                        )
                    })
                    .or_else(|| {
                        find_word_ci(after_that, "source would deal").map(|p| {
                            (
                                after_that[..p].trim(),
                                after_that[p + "source would deal".len()..].trim(),
                            )
                        })
                    })
                {
                    let mut cm = ColorMask::empty();
                    let mut ok = !src_s.is_empty();
                    for tok in src_s.split(|c: char| !c.is_ascii_alphabetic()) {
                        if tok.is_empty() || eq_ci(tok, "and") || eq_ci(tok, "or") {
                            continue;
                        }
                        if eq_ci(tok, "white") {
                            cm |= ColorMask::W;
                        } else if eq_ci(tok, "blue") {
                            cm |= ColorMask::U;
                        } else if eq_ci(tok, "black") {
                            cm |= ColorMask::B;
                        } else if eq_ci(tok, "red") {
                            cm |= ColorMask::R;
                        } else if eq_ci(tok, "green") {
                            cm |= ColorMask::G;
                        } else {
                            ok = false;
                            break;
                        }
                    }
                    if ok && !cm.is_empty() {
                        Some((co, wbd, cm))
                    } else {
                        None
                    }
                } else {
                    None
                }
            })
    {
        let without_lead_turn = strip_prefix_word_ci(after_wbd, "this turn").unwrap_or(after_wbd);
        if let Some(after_to) = strip_prefix_word_ci(without_lead_turn, "to") {
            let (subj_part, from_source) = if let Some(by_pos) = find_word_ci(after_to, " by ") {
                let s_raw = after_to[..by_pos].trim();
                let src_raw = after_to[by_pos + 4..].trim();
                let src_clean = strip_suffix_word_ci(src_raw, "this turn").unwrap_or(src_raw);
                let src_sel = parse_object_selector(src_clean, ZoneMask::BATTLEFIELD, ctx, state)
                    .map(|p| Box::new(p.into_selector()));
                (s_raw, src_sel)
            } else {
                (after_to, None)
            };
            let subj_clean = strip_suffix_word_ci(subj_part, "this turn").unwrap_or(subj_part);
            let mark = state.mark(ctx);
            if let Some(subj) = parse_any_recipient_selector(subj_clean, ctx, state) {
                state.push_step(
                    make_step(
                        EffectOp::PreventDamage {
                            spec: Box::new(DamagePreventionSpec {
                                mode: PreventMode::All,
                                combat_only,
                                scope: PreventScope::Subject,
                                from_source,
                                also_prevent_dealt_by_subject: false,
                                choose_source: false,
                                next_damage_event_only: false,
                                on_prevented: None,
                                redirect_to: None,
                                redirect_source_color_filter: ColorMask::empty(),
                                redirect_source_kind: None,
                                min_life_floor: None,
                                all_damage_to_you_and_perms: false,
                                you_and_planeswalkers_you_control: false,
                                from_sources_you_dont_control: false,
                                from_source_colors,
                                from_source_not_subtypes: SmallVec::new(),
                                on_prevented_creature: None,
                                on_prevented_noncreature: None,
                                on_prevented_to_damage_source_controller: false,
                            }),
                        },
                        subj,
                        span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        } else if let Some(after_by) = strip_prefix_word_ci(without_lead_turn, "by") {
            let src_clean = strip_suffix_word_ci(after_by, "this turn").unwrap_or(after_by);
            let mark = state.mark(ctx);
            if let Some(src_sel) =
                parse_object_selector(src_clean, ZoneMask::BATTLEFIELD, ctx, state)
            {
                let (from_source, from_source_not_subtypes) = match &src_sel {
                    ParsedObj::All(f)
                        if f.types_any == CardTypeMask::CREATURE
                            && f.types_all.is_empty()
                            && f.types_none.is_empty()
                            && f.supertypes_any.is_empty()
                            && f.supertypes_none.is_empty()
                            && f.colors_any.is_empty()
                            && f.colors_all.is_empty()
                            && f.colors_none.is_empty()
                            && f.subtypes_any.is_empty()
                            && f.subtypes_all.is_empty()
                            && !f.subtypes_none.is_empty()
                            && f.controller.is_none()
                            && f.owner.is_none()
                            && f.flags.is_empty()
                            && f.extra.is_empty() =>
                    {
                        (None, f.subtypes_none.clone())
                    }
                    _ => (Some(Box::new(src_sel.into_selector())), SmallVec::new()),
                };
                let target_idx = match &from_source {
                    Some(b) if matches!(**b, Selector::Target { .. }) => match **b {
                        Selector::Target { index } => Some(index),
                        _ => None,
                    },
                    _ => None,
                };
                state.push_step(
                    make_step(
                        EffectOp::PreventDamage {
                            spec: Box::new(DamagePreventionSpec {
                                mode: PreventMode::All,
                                combat_only,
                                scope: PreventScope::Any,
                                from_source,
                                also_prevent_dealt_by_subject: false,
                                choose_source: false,
                                next_damage_event_only: false,
                                on_prevented: None,
                                redirect_to: None,
                                redirect_source_color_filter: ColorMask::empty(),
                                redirect_source_kind: None,
                                min_life_floor: None,
                                all_damage_to_you_and_perms: false,
                                you_and_planeswalkers_you_control: false,
                                from_sources_you_dont_control: false,
                                from_source_colors: ColorMask::empty(),
                                from_source_not_subtypes,
                                on_prevented_creature: None,
                                on_prevented_noncreature: None,
                                on_prevented_to_damage_source_controller: false,
                            }),
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                if let Some(index) = target_idx {
                    state.last_object = Some((Ref::Target { index }, state.steps.len() - 1));
                }
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    if let Some(after_next) = strip_prefix_word_ci(rest, "the next")
        && let Some(pos) = find_word_ci(after_next, " damage that would be dealt to ")
    {
        let amt_s = after_next[..pos].trim();
        let after_to = after_next[pos + " damage that would be dealt to ".len()..].trim();
        let subj_s = strip_suffix_word_ci(after_to, "this turn").unwrap_or(after_to);
        if let Some(amt) = parse_amount_str(amt_s, ctx, state)
            && let Some(subj) = parse_any_recipient_selector(subj_s, ctx, state)
        {
            let mut st = make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::Next,
                        combat_only: false,
                        scope: PreventScope::Subject,
                        from_source: None,
                        also_prevent_dealt_by_subject: false,
                        choose_source: false,
                        next_damage_event_only: false,
                        on_prevented: None,
                        redirect_to: None,
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: false,
                        from_sources_you_dont_control: false,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                subj,
                span,
            );
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
    }
    false
}

fn parse_shuffle_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if eq_ci(t, "shuffle your hand and graveyard into your library")
        || eq_ci(t, "shuffle their hand and graveyard into their library")
    {
        let owner = if contains_word_ci(t, "your") {
            Some(RelativeControl::You)
        } else {
            None
        };
        state.push_step(
            make_step(
                EffectOp::Move {
                    from: None,
                    to: Some(Zone::Library),
                    select: SelectionMod::default(),
                    tapped: false,
                    under_your_control: false,
                    topmost_only: false,
                    may_shuffle: true,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                Selector::All {
                    filter: Box::new(ObjectFilter {
                        zones: ZoneMask::HAND | ZoneMask::GRAVEYARD,
                        owner,
                        ..Default::default()
                    }),
                },
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(t, "shuffle")
        || eq_ci(t, "shuffle your library")
        || eq_ci(t, "then shuffle")
        || eq_ci(t, "then shuffle your library")
    {
        // Check if preceding step is a Search step: Search already shuffles on resolve, or emit Move Library->Library
        if state
            .steps
            .last()
            .is_some_and(|s| matches!(s.op, EffectOp::Search { .. }))
        {
            return true;
        }
        state.push_step(
            make_step(
                EffectOp::Move {
                    from: Some(Zone::Library),
                    to: Some(Zone::Library),
                    select: SelectionMod::default(),
                    tapped: false,
                    under_your_control: false,
                    topmost_only: false,
                    may_shuffle: true,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: true,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(rest_raw) = strip_prefix_word_ci(t, "shuffle") {
        let (from_zone, rest) = if let Some(r) =
            strip_suffix_word_ci(rest_raw, "from your graveyard")
                .or_else(|| strip_suffix_word_ci(rest_raw, "from a graveyard"))
        {
            (Some(Zone::Graveyard), r)
        } else if let Some(r) = strip_suffix_word_ci(rest_raw, "from exile") {
            (Some(Zone::Exile), r)
        } else {
            (None, rest_raw)
        };
        if let Some(obj_s) = strip_suffix_word_ci(rest, "into its owner's library")
            .or_else(|| strip_suffix_word_ci(rest, "into their owner's library"))
            .or_else(|| strip_suffix_word_ci(rest, "into their owners' libraries"))
            .or_else(|| strip_suffix_word_ci(rest, "into your library"))
            && let Some(obj) = parse_object_selector(obj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            state.push_step(
                make_step(
                    EffectOp::Move {
                        from: from_zone,
                        to: Some(Zone::Library),
                        select: SelectionMod::default(),
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: from_zone.is_none(),
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
    }
    false
}

fn parse_double_or_triple_clause(
    t: &str,
    factor: u8,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let kw = if factor == 2 { "double" } else { "triple" };
    let Some(rest) = strip_prefix_word_ci(t, kw) else {
        return false;
    };
    let (body_dur, dur) = parse_duration_suffix(rest);
    let (body, repeat_factor_count) = if let Some(before_times) =
        strip_suffix_word_ci(body_dur, "times")
        && let Some((left, cnt_raw)) = before_times.rsplit_once(' ')
        && let Some(amt) = parse_amount_str(cnt_raw.trim(), ctx, state)
    {
        (left.trim(), Some(Box::new(amt)))
    } else {
        (body_dur, None)
    };
    if eq_ci(body, "your life total") {
        state.push_step(
            make_step(
                EffectOp::DoubleOrTriple {
                    spec: DoubleOrTripleSpec {
                        factor,
                        target: DoubleTarget::Life,
                        counter: None,
                        duration: None,
                        repeat_factor_count,
                    },
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(pl_raw) = strip_suffix_word_ci(body, "'s life total") {
        let mark = state.mark(ctx);
        if let Some(psel) = parse_player_selector(pl_raw, ctx, state) {
            state.push_step(
                make_step(
                    EffectOp::DoubleOrTriple {
                        spec: DoubleOrTripleSpec {
                            factor,
                            target: DoubleTarget::Life,
                            counter: None,
                            duration: None,
                            repeat_factor_count,
                        },
                    },
                    psel,
                    span,
                ),
                false,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_raw) = strip_suffix_word_ci(body, "'s power and toughness")
        .or_else(|| strip_prefix_word_ci(body, "the power and toughness of"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(
                    EffectOp::DoubleOrTriple {
                        spec: DoubleOrTripleSpec {
                            factor,
                            target: DoubleTarget::Pt,
                            counter: None,
                            duration: dur,
                            repeat_factor_count,
                        },
                    },
                    obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_raw) = strip_suffix_word_ci(body, "'s power")
        .or_else(|| strip_prefix_word_ci(body, "the power of"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(
                    EffectOp::DoubleOrTriple {
                        spec: DoubleOrTripleSpec {
                            factor,
                            target: DoubleTarget::Power,
                            counter: None,
                            duration: dur,
                            repeat_factor_count,
                        },
                    },
                    obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_raw) = strip_suffix_word_ci(body, "'s toughness")
        .or_else(|| strip_prefix_word_ci(body, "the toughness of"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(
                    EffectOp::DoubleOrTriple {
                        spec: DoubleOrTripleSpec {
                            factor,
                            target: DoubleTarget::Toughness,
                            counter: None,
                            duration: dur,
                            repeat_factor_count,
                        },
                    },
                    obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(after_num) = strip_prefix_word_ci(body, "the number of")
        && let Some(on_pos) = find_word_ci(after_num, " on ")
    {
        let ctr_part = after_num[..on_pos].trim();
        let subj_raw = after_num[on_pos + 4..].trim();
        let ctr_target = if eq_ci(ctr_part, "counters")
            || eq_ci(ctr_part, "each kind of counter")
            || eq_ci(ctr_part, "counters of each kind")
        {
            Some(CounterTarget::Any)
        } else if let Some(kind_raw) = strip_suffix_word_ci(ctr_part, "counters")
            .or_else(|| strip_suffix_word_ci(ctr_part, "counter"))
        {
            if kind_raw.is_empty() {
                Some(CounterTarget::Any)
            } else {
                normalize_counter_name(kind_raw)
                    .map(|n| CounterTarget::Specific(ctx.interner.intern_counter(&n)))
            }
        } else {
            None
        };
        if let Some(counter) = ctr_target {
            let mark = state.mark(ctx);
            if let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state) {
                let st = make_step(
                    EffectOp::DoubleOrTriple {
                        spec: DoubleOrTripleSpec {
                            factor,
                            target: DoubleTarget::Counters,
                            counter: Some(counter),
                            duration: None,
                            repeat_factor_count,
                        },
                    },
                    obj.into_selector(),
                    span,
                );
                state.push_step(st, false);
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    false
}

fn parse_exchange_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if eq_ci(
        t,
        "exchange your life total with target player's life total",
    ) {
        let mut sp = default_target_spec();
        sp.kind = TargetKind::Player;
        sp.player = Some(PlayerFilter {
            relation: PlayerRelation::Any,
        });
        let idx = state.add_target(sp);
        state.push_step(
            make_step(
                EffectOp::Exchange {
                    spec: mtg_ir::ExchangeSpec {
                        kind: mtg_ir::ExchangeKind::LifeTotals,
                        second: Some(Box::new(Selector::Target { index: idx })),
                        duration: None,
                    },
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(
        t,
        "exchange target opponent's life total with ~'s toughness",
    ) || eq_ci(
        t,
        "exchange target opponent's life total with this creature's toughness",
    ) || eq_ci(t, "exchange target player's life total with ~'s toughness")
        || eq_ci(
            t,
            "exchange target player's life total with this creature's toughness",
        )
    {
        let rel = if contains_word_ci(t, "opponent") {
            PlayerRelation::Opponent
        } else {
            PlayerRelation::Any
        };
        let mut sp = default_target_spec();
        sp.kind = TargetKind::Player;
        sp.player = Some(PlayerFilter { relation: rel });
        let idx = state.add_target(sp);
        state.push_step(
            make_step(
                EffectOp::Exchange {
                    spec: mtg_ir::ExchangeSpec {
                        kind: mtg_ir::ExchangeKind::LifeAndToughness,
                        second: Some(Box::new(Selector::SelfObj)),
                        duration: None,
                    },
                },
                Selector::Target { index: idx },
                span,
            ),
            false,
        );
        return true;
    }
    {
        let (ex_body, dur) = parse_duration_suffix(t);
        if let Some(after_you) = strip_prefix_word_ci(ex_body, "you and")
            && let Some(pos) = find_word_ci(
                after_you,
                " each gain control of all creatures the other controls",
            )
            && after_you[pos + " each gain control of all creatures the other controls".len()..]
                .trim()
                .is_empty()
            && let Some(opp_sel) = parse_player_selector(after_you[..pos].trim(), ctx, state)
        {
            let second_sel = match opp_sel {
                Selector::PlayerRef {
                    player: PlayerRef::Target { index },
                } => Selector::Target { index },
                other => other,
            };
            let bname = state.alloc_bind_name("b");
            let idx = state.steps.len();
            let mut st = make_step(
                EffectOp::Exchange {
                    spec: mtg_ir::ExchangeSpec {
                        kind: mtg_ir::ExchangeKind::SwapAllControlledCreatures,
                        second: Some(Box::new(second_sel)),
                        duration: dur,
                    },
                },
                you_sel(),
                span,
            );
            st.bind_as = Some(bname.clone());
            state.push_step(st, false);
            state.last_object = Some((Ref::Binding { name: bname }, idx));
            return true;
        }
    }
    if let Some(rest) = strip_prefix_word_ci(t, "exchange control of") {
        if let Some((a_raw, b_raw)) = rest.split_once(" and ")
            && let Some(a) = parse_object_selector(a_raw.trim(), ZoneMask::BATTLEFIELD, ctx, state)
            && let Some(b) = parse_object_selector(b_raw.trim(), ZoneMask::BATTLEFIELD, ctx, state)
        {
            state.push_step(
                make_step(
                    EffectOp::Exchange {
                        spec: mtg_ir::ExchangeSpec {
                            kind: mtg_ir::ExchangeKind::Control,
                            second: Some(Box::new(b.into_selector())),
                            duration: None,
                        },
                    },
                    a.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        let (shares_type, obj_body) =
            if let Some(b) = strip_suffix_word_ci(rest, "that share a card type") {
                (true, b)
            } else {
                (false, rest)
            };
        if let Some(filt_s) = strip_prefix_word_ci(obj_body, "two target") {
            let norm_f = filt_s.replace(',', " ");
            let toks = tokenize(&norm_f, 0);
            let cp = ctx.interner.checkpoint();
            if !toks.is_empty()
                && let Some((mut f, used)) = parse_object_filter(
                    &toks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::BATTLEFIELD,
                        allow_plural_and_disjunction: true,
                        ..Default::default()
                    },
                    state,
                )
                && used == toks.len()
            {
                if f.zones.is_empty() {
                    f.zones = ZoneMask::BATTLEFIELD;
                }
                let mut sp0 = default_target_spec();
                sp0.kind = TargetKind::Object;
                sp0.filter = f.clone();
                let idx0 = state.add_target(sp0);
                let mut sp1 = default_target_spec();
                sp1.kind = TargetKind::Object;
                sp1.filter = f;
                if shares_type {
                    sp1.other_target = true;
                    sp1.shares_card_type_with_target = Some(idx0);
                }
                let idx1 = state.add_target(sp1);
                state.push_step(
                    make_step(
                        EffectOp::Exchange {
                            spec: mtg_ir::ExchangeSpec {
                                kind: mtg_ir::ExchangeKind::Control,
                                second: Some(Box::new(Selector::Target { index: idx1 })),
                                duration: None,
                            },
                        },
                        Selector::Target { index: idx0 },
                        span,
                    ),
                    true,
                );
                return true;
            }
            ctx.interner.rollback(cp);
        }
    }
    false
}

fn parse_switch_pt_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "switch") else {
        return false;
    };
    let (body, dur) = parse_duration_suffix(rest);
    let subj_opt = strip_suffix_word_ci(body, "'s power and toughness")
        .or_else(|| strip_prefix_word_ci(body, "the power and toughness of"))
        .or_else(|| strip_prefix_word_ci(body, "power and toughness of"));
    if let Some(subj_raw) = subj_opt
        && let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state)
    {
        state.push_step(
            make_step(
                EffectOp::SwitchPt { duration: dur },
                obj.into_selector(),
                span,
            ),
            true,
        );
        return true;
    }
    false
}

fn parse_emblem_clause(t: &str, span: Span, state: &mut ParserState<'_>) -> bool {
    if let Some(rest) = strip_prefix_word_ci(t, "create an emblem with")
        .or_else(|| strip_prefix_word_ci(t, "you get an emblem with"))
        && let Some(q) = strip_outer_quotes(rest)
    {
        state.push_step(
            make_step(
                EffectOp::CreateEmblem {
                    abilities: vec![q.to_string()],
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    false
}

fn parse_reveal_clause(
    t: &str,
    _subj: Selector,
    actor: Option<PlayerRef>,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if eq_ci(t, "reveal your hand") || eq_ci(t, "reveals their hand") {
        let mut st = make_step(
            EffectOp::Reveal {
                select: SelectionMod::default(),
                look_only: false,
                special_tag: None,
            },
            Selector::All {
                filter: Box::new(ObjectFilter {
                    zones: ZoneMask::HAND,
                    owner: Some(RelativeControl::You),
                    ..Default::default()
                }),
            },
            span,
        );
        st.actor = actor;
        state.push_step(st, false);
        return true;
    }
    if let Some(after_any) = strip_prefix_word_ci(t, "reveal any number of") {
        let mut filt_s = after_any.trim();
        let in_your_hand = if let Some(r) = strip_suffix_word_ci(filt_s, "in your hand")
            .or_else(|| strip_suffix_word_ci(filt_s, "from your hand"))
        {
            filt_s = r.trim();
            true
        } else {
            false
        };
        let toks = tokenize(filt_s, 0);
        let cp = ctx.interner.checkpoint();
        if !toks.is_empty()
            && let Some((mut f, used)) = parse_object_filter(
                &toks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::HAND,
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: true,
                    ..Default::default()
                },
                state,
            )
            && used == toks.len()
        {
            if in_your_hand {
                f.zones = ZoneMask::HAND;
                f.owner = Some(RelativeControl::You);
            }
            let mut st = make_step(
                EffectOp::Reveal {
                    select: SelectionMod {
                        choice_count: Some(Box::new(Amount::Const { n: 99 })),
                        up_to: true,
                        ..Default::default()
                    },
                    look_only: false,
                    special_tag: None,
                },
                Selector::All {
                    filter: Box::new(f),
                },
                span,
            );
            st.actor = actor;
            state.push_step(st, false);
            return true;
        }
        ctx.interner.rollback(cp);
    }
    if (eq_ci(t, "reveal it")
        || eq_ci(t, "reveal that card")
        || eq_ci(t, "reveal them")
        || eq_ci(t, "reveal those cards"))
        && let Some(r) = state.it_ref()
    {
        let mut st = make_step(
            EffectOp::Reveal {
                select: SelectionMod::default(),
                look_only: false,
                special_tag: None,
            },
            ref_to_selector(&r),
            span,
        );
        st.actor = actor;
        state.push_step(st, false);
        return true;
    }
    if eq_ci(t, "reveal the top card of your library") {
        let mut st = make_step(
            EffectOp::Reveal {
                select: SelectionMod::default(),
                look_only: false,
                special_tag: None,
            },
            Selector::LibraryTop { player: None },
            span,
        );
        st.actor = actor;
        state.push_step(st, true);
        return true;
    }
    false
}

fn parse_look_clause(
    t: &str,
    subj: Selector,
    actor: Option<PlayerRef>,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "look at the top") else {
        return false;
    };
    // "look at the top N cards of your library, then put them back in any order"
    if let Some(pos) = find_word_ci(rest, " cards of your library") {
        let amt_s = rest[..pos].trim();
        let after = rest[pos + " cards of your library".len()..].trim();
        if let Some(amt) = parse_amount_str(amt_s, ctx, state)
            && after.contains("any order")
        {
            let mut st = make_step(
                EffectOp::LookAndReorder {
                    may_shuffle: contains_word_ci(after, "may shuffle"),
                },
                subj,
                span,
            );
            st.actor = actor;
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
    }
    if eq_ci(rest, "card of your library") {
        let mut st = make_step(
            EffectOp::Reveal {
                select: SelectionMod::default(),
                look_only: true,
                special_tag: None,
            },
            Selector::LibraryTop { player: None },
            span,
        );
        st.actor = actor;
        st.amount = Some(Box::new(Amount::Const { n: 1 }));
        st.bind_as = Some("looked".to_string());
        state.push_step(st, true);
        return true;
    }
    false
}

fn parse_search_clause(
    t: &str,
    subj: Selector,
    actor: Option<PlayerRef>,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let (rest, search_zones, shuffle_only_if_lib, searched_player_rel) = if let Some(r) =
        strip_prefix_word_ci(t, "search your library and/or graveyard for")
            .or_else(|| strip_prefix_word_ci(t, "search your graveyard and/or library for"))
    {
        (r, ZoneMask::LIBRARY | ZoneMask::GRAVEYARD, true, None)
    } else if let Some(r) =
        strip_prefix_word_ci(t, "search your graveyard, hand, and/or library for")
            .or_else(|| strip_prefix_word_ci(t, "search your library, hand, and/or graveyard for"))
            .or_else(|| strip_prefix_word_ci(t, "search your library, hand, and graveyard for"))
    {
        (
            r,
            ZoneMask::LIBRARY | ZoneMask::HAND | ZoneMask::GRAVEYARD,
            true,
            None,
        )
    } else if let Some(r) = strip_prefix_word_ci(
        t,
        "search target opponent's graveyard, hand, and library for",
    )
    .or_else(|| {
        strip_prefix_word_ci(
            t,
            "search target opponent's library, graveyard, and hand for",
        )
    }) {
        (
            r,
            ZoneMask::LIBRARY | ZoneMask::HAND | ZoneMask::GRAVEYARD,
            false,
            Some(PlayerRelation::Opponent),
        )
    } else if let Some(r) =
        strip_prefix_word_ci(t, "search target player's graveyard, hand, and library for")
    {
        (
            r,
            ZoneMask::LIBRARY | ZoneMask::HAND | ZoneMask::GRAVEYARD,
            false,
            Some(PlayerRelation::Any),
        )
    } else if let Some(r) = strip_prefix_word_ci(t, "search your library for")
        .or_else(|| strip_prefix_word_ci(t, "searches their library for"))
        .or_else(|| strip_prefix_word_ci(t, "search their library for"))
    {
        (r, ZoneMask::empty(), false, None)
    } else {
        return false;
    };
    let (body, shuffle_seen, mut post_shuffle_and) =
        if let Some(pos) = find_word_ci(rest, ", then shuffle and ") {
            (
                rest[..pos].trim(),
                true,
                Some(rest[pos + ", then shuffle and ".len()..].trim()),
            )
        } else if let Some(pos) = find_word_ci(rest, ", then shuffle, and ") {
            (
                rest[..pos].trim(),
                true,
                Some(rest[pos + ", then shuffle, and ".len()..].trim()),
            )
        } else if let Some(p) = strip_suffix_word_ci(rest, ", then shuffle")
            .or_else(|| strip_suffix_word_ci(rest, ", then shuffle your library"))
            .or_else(|| strip_suffix_word_ci(rest, ", then shuffle if you searched your library"))
        {
            (p, true, None)
        } else {
            (rest, false, None)
        };
    let _ = shuffle_seen;
    let parse_dest_slice =
        |s: &str, allow_lead_put: bool, allow_bare_prep: bool| -> Option<SearchDestination> {
            let mut s = s.trim();
            if allow_lead_put {
                s = strip_prefix_word_ci(s, "put")?.trim();
            }
            let dest = [
                "that card",
                "those cards",
                "one of them",
                "the other",
                "the rest",
                "them",
                "it",
                "one",
            ]
            .into_iter()
            .find_map(|p| strip_prefix_word_ci(s, p))
            .map(str::trim)
            .or_else(|| allow_bare_prep.then_some(s))?;

            if let Some(after_bf) = strip_prefix_word_ci(dest, "onto the battlefield") {
                let after_bf = after_bf.trim();
                let tapped =
                    if eq_ci(after_bf, "tapped") || eq_ci(after_bf, "tapped under your control") {
                        true
                    } else if after_bf.is_empty() || eq_ci(after_bf, "under your control") {
                        false
                    } else {
                        return None;
                    };
                return Some(SearchDestination {
                    zone: Zone::Battlefield,
                    tapped,
                    on_top: false,
                });
            }
            if eq_ci(dest, "into your hand")
                || eq_ci(dest, "into their hand")
                || eq_ci(dest, "into that player's hand")
                || eq_ci(dest, "into its owner's hand")
            {
                return Some(SearchDestination {
                    zone: Zone::Hand,
                    tapped: false,
                    on_top: false,
                });
            }
            if eq_ci(dest, "into your graveyard")
                || eq_ci(dest, "into their graveyard")
                || eq_ci(dest, "into that player's graveyard")
                || eq_ci(dest, "into its owner's graveyard")
            {
                return Some(SearchDestination {
                    zone: Zone::Graveyard,
                    tapped: false,
                    on_top: false,
                });
            }
            if eq_ci(dest, "into exile") {
                return Some(SearchDestination {
                    zone: Zone::Exile,
                    tapped: false,
                    on_top: false,
                });
            }
            if let Some(after_top) = strip_prefix_word_ci(dest, "on top") {
                let lib = strip_suffix_word_ci(after_top.trim(), "in any order")
                    .unwrap_or(after_top.trim())
                    .trim();
                if lib.is_empty()
                    || eq_ci(lib, "of your library")
                    || eq_ci(lib, "of their library")
                    || eq_ci(lib, "of that player's library")
                    || eq_ci(lib, "of its owner's library")
                {
                    return Some(SearchDestination {
                        zone: Zone::Library,
                        tapped: false,
                        on_top: true,
                    });
                }
            }
            None
        };
    let mut cast_free = false;
    let put_split = find_word_ci(body, ", put ")
        .map(|p| (p, 6))
        .or_else(|| find_word_ci(body, ", and put ").map(|p| (p, 10)))
        .or_else(|| find_word_ci(body, " and put ").map(|p| (p, 9)));
    let (filter_raw, mut dests, reveal, tapped_op) = if let Some((pos, sep_len)) = put_split {
        let f_s = body[..pos].trim();
        let tail = body[pos + sep_len..].trim();
        let clean_f = strip_suffix_word_ci(f_s, ", reveal it")
            .or_else(|| strip_suffix_word_ci(f_s, ", reveal that card"))
            .or_else(|| strip_suffix_word_ci(f_s, ", reveal those cards"))
            .or_else(|| strip_suffix_word_ci(f_s, ", reveal them"))
            .unwrap_or(f_s);
        let has_reveal = clean_f.len() != f_s.len();
        let parsed_dests = if let Some((split_pos, dlen)) = find_word_ci(tail, " and the other ")
            .map(|p| (p, " and the other ".len()))
            .or_else(|| find_word_ci(tail, " and the rest ").map(|p| (p, " and the rest ".len())))
        {
            let Some(d1) = parse_dest_slice(tail[..split_pos].trim(), false, false) else {
                return false;
            };
            let Some(d2) = parse_dest_slice(tail[split_pos + dlen..].trim(), false, true) else {
                return false;
            };
            vec![d1, d2]
        } else {
            let Some(d1) = parse_dest_slice(tail, false, false) else {
                return false;
            };
            vec![d1]
        };
        let t_op = parsed_dests.first().is_some_and(|d| d.tapped);
        (clean_f, parsed_dests, has_reveal, t_op)
    } else if let Some(tail) = post_shuffle_and
        && (starts_with_word_ci(tail, "put it ")
            || starts_with_word_ci(tail, "put that card ")
            || starts_with_word_ci(tail, "put that ")
            || starts_with_word_ci(tail, "put them ")
            || starts_with_word_ci(tail, "put those cards "))
    {
        post_shuffle_and = None;
        let clean_f = strip_suffix_word_ci(body, ", reveal it")
            .or_else(|| strip_suffix_word_ci(body, ", reveal that card"))
            .or_else(|| strip_suffix_word_ci(body, ", reveal those cards"))
            .or_else(|| strip_suffix_word_ci(body, ", reveal them"))
            .unwrap_or(body);
        let has_reveal = clean_f.len() != body.len();
        let Some(d1) = parse_dest_slice(tail, true, false) else {
            return false;
        };
        let parsed_dests = vec![d1];
        let t_op = parsed_dests.first().is_some_and(|d| d.tapped);
        (clean_f, parsed_dests, has_reveal, t_op)
    } else if let Some(pos) = find_word_ci(body, ", reveal ") {
        let f_s = body[..pos].trim();
        let tail = body[pos + ", reveal ".len()..].trim();
        if !(eq_ci(tail, "it")
            || eq_ci(tail, "them")
            || eq_ci(tail, "that card")
            || eq_ci(tail, "those cards"))
        {
            return false;
        }
        (
            f_s,
            vec![SearchDestination {
                zone: Zone::Hand,
                tapped: false,
                on_top: false,
            }],
            true,
            false,
        )
    } else if let Some(f_s) =
        strip_suffix_word_ci(body, "and cast that card without paying its mana cost")
            .or_else(|| strip_suffix_word_ci(body, "and cast it without paying its mana cost"))
    {
        cast_free = true;
        (
            f_s.trim_end_matches(',').trim(),
            vec![SearchDestination {
                zone: Zone::Library,
                tapped: false,
                on_top: false,
            }],
            false,
            false,
        )
    } else if let Some(f_s) = strip_suffix_word_ci(body, "and exile them")
        .or_else(|| strip_suffix_word_ci(body, "and exile it"))
        .or_else(|| strip_suffix_word_ci(body, "and exile those cards"))
        .or_else(|| strip_suffix_word_ci(body, "and exile that card"))
    {
        (
            f_s.trim_end_matches(',').trim(),
            vec![SearchDestination {
                zone: Zone::Exile,
                tapped: false,
                on_top: false,
            }],
            false,
            false,
        )
    } else if let Some(pos) = find_word_ci(body, ", exile ") {
        let f_s = body[..pos].trim();
        let tail = body[pos + ", exile ".len()..].trim();
        if !(eq_ci(tail, "it")
            || eq_ci(tail, "them")
            || eq_ci(tail, "that card")
            || eq_ci(tail, "those cards"))
        {
            return false;
        }
        (
            f_s,
            vec![SearchDestination {
                zone: Zone::Exile,
                tapped: false,
                on_top: false,
            }],
            false,
            false,
        )
    } else if let Some(f_s) = strip_suffix_word_ci(body, "and reveal them")
        .or_else(|| strip_suffix_word_ci(body, "and reveal those cards"))
        .or_else(|| strip_suffix_word_ci(body, "and reveal it"))
        .or_else(|| strip_suffix_word_ci(body, "and reveal that card"))
    {
        (
            f_s.trim_end_matches(',').trim(),
            vec![SearchDestination {
                zone: Zone::Hand,
                tapped: false,
                on_top: false,
            }],
            true,
            false,
        )
    } else {
        (
            body,
            vec![SearchDestination {
                zone: Zone::Hand,
                tapped: false,
                on_top: false,
            }],
            false,
            false,
        )
    };

    let search_mark = state.mark(ctx);
    let filter_raw = if let Some(w_idx) = find_word_ci(filter_raw, ", where x is ") {
        let x_expr = filter_raw[w_idx + ", where x is ".len()..].trim();
        let Some(mut amt) = parse_amount_str(x_expr, ctx, state) else {
            state.rollback(search_mark, ctx);
            return false;
        };
        let is_dies_trig = matches!(
            state.trigger.and_then(|tr| tr.filter.detail.as_ref()),
            Some(EventDetail::ZoneChange {
                to: Some(Zone::Graveyard),
                ..
            })
        );
        if is_dies_trig && let Amount::Stat { ref mut lki, .. } = amt {
            *lki = true;
        }
        state.defined_x = Some(amt);
        filter_raw[..w_idx].trim()
    } else {
        filter_raw
    };

    let (up_to, after_up_to) = if let Some(r) = strip_prefix_word_ci(filter_raw, "up to") {
        (true, r)
    } else {
        (false, filter_raw)
    };
    let mut count = 1u16;
    let mut x_amount: Option<Amount> = None;
    let mut is_capenna_m = false;
    let mut filter_str = after_up_to;
    let first_w = after_up_to.split_whitespace().next().unwrap_or("");
    if let Some(after_tm) = strip_prefix_word_ci(after_up_to, "that many") {
        filter_str = after_tm;
        let resolved = resolve_that_many_amount(state);
        if let Amount::Const { n } = resolved {
            count = n.max(1) as u16;
        } else {
            x_amount = Some(resolved);
        }
    } else if let Some(after_any) = strip_prefix_word_ci(after_up_to, "any number of") {
        filter_str = after_any;
    } else if eq_ci(first_w, "a") || eq_ci(first_w, "an") {
        filter_str = after_up_to[first_w.len()..].trim();
    } else if eq_ci(first_w, "x") {
        filter_str = after_up_to[first_w.len()..].trim();
        if up_to {
            count = 99;
        }
        x_amount = Some(state.defined_x.clone().unwrap_or(Amount::X));
    } else if let Some(n) = parse_small_number(first_w) {
        count = n.max(1) as u16;
        filter_str = after_up_to[first_w.len()..].trim();
    }
    if dests.len() == 1 && count > 1 && contains_word_ci(body, "put them") {
        let d0 = dests[0].clone();
        while dests.len() < count as usize {
            dests.push(d0.clone());
        }
    }
    let filter_has_quality = |f: &ObjectFilter| -> bool {
        !f.types_any.is_empty()
            || !f.types_all.is_empty()
            || !f.types_none.is_empty()
            || !f.supertypes_any.is_empty()
            || !f.supertypes_none.is_empty()
            || !f.colors_any.is_empty()
            || !f.colors_all.is_empty()
            || !f.colors_none.is_empty()
            || !f.subtypes_any.is_empty()
            || !f.subtypes_all.is_empty()
            || !f.subtypes_none.is_empty()
            || !f.flags.is_empty()
            || f.mana_value.is_some()
            || f.power.is_some()
            || f.toughness.is_some()
            || !f.extra.is_empty()
    };
    let is_numeric_mana_pip = |s: &str| -> bool {
        let s = s.trim();
        s.len() >= 3
            && s.starts_with('{')
            && s.ends_with('}')
            && s[1..s.len() - 1].bytes().all(|b| b.is_ascii_digit())
    };
    let is_numeric_mana_cost_disjunction = |s: &str| -> bool {
        let s = s.trim();
        if s.is_empty() {
            return false;
        }
        if is_numeric_mana_pip(s) {
            return true;
        }
        let mut parts: Vec<&str> = Vec::new();
        for seg in s.split(',') {
            let seg = seg.trim();
            if seg.is_empty() {
                return false;
            }
            let mut rest = seg;
            loop {
                if let Some(or_pos) = find_word_ci(rest, " or ") {
                    parts.push(rest[..or_pos].trim());
                    rest = rest[or_pos + 4..].trim();
                } else if let Some(after_or) = strip_prefix_word_ci(rest, "or") {
                    parts.push(after_or.trim());
                    break;
                } else {
                    parts.push(rest);
                    break;
                }
            }
        }
        parts.len() >= 2
            && contains_word_ci(s, "or")
            && parts.iter().all(|p| is_numeric_mana_pip(p))
    };
    let filter = if let Some(after_basic) = strip_prefix_word_ci(filter_str, "basic")
        && let Some(mid) = strip_suffix_word_ci(after_basic, "card")
            .or_else(|| strip_suffix_word_ci(after_basic, "cards"))
        && (contains_word_ci(mid, "or") || mid.contains(','))
    {
        let mut sub_filters = Vec::new();
        let mut ok = true;
        for comma_part in mid.split(',') {
            let p = comma_part.trim();
            if p.is_empty() {
                continue;
            }
            for or_part in p.split(" or ") {
                let s = strip_prefix_word_ci(or_part.trim(), "or").unwrap_or(or_part.trim());
                if s.is_empty() || s.contains(char::is_whitespace) {
                    ok = false;
                    break;
                }
                let Some(sub) = singular_subtype(s) else {
                    ok = false;
                    break;
                };
                let sid = ctx.interner.intern_subtype(&sub);
                sub_filters.push(ObjectFilter {
                    subtypes_any: smallvec![sid],
                    ..Default::default()
                });
            }
            if !ok {
                break;
            }
        }
        let clean_filter_str = strip_suffix_word_ci(filter_str, "that have different names")
            .or_else(|| strip_suffix_word_ci(filter_str, "with different names"))
            .or_else(|| strip_suffix_word_ci(filter_str, "that share a land type"))
            .unwrap_or(filter_str);
        if ok && sub_filters.len() >= 2 {
            is_capenna_m = true;
            ObjectFilter {
                types_any: CardTypeMask::LAND,
                supertypes_any: SupertypeMask::BASIC,
                extra: vec![ObjectPredicate::AnyOf {
                    filters: sub_filters,
                }],
                ..Default::default()
            }
        } else {
            let Some(f) = parse_object_phrase(
                clean_filter_str,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: true,
                    ..Default::default()
                },
            ) else {
                state.rollback(search_mark, ctx);
                return false;
            };
            f
        }
    } else if eq_ci(filter_str, "cards with that name") || eq_ci(filter_str, "card with that name")
    {
        ObjectFilter {
            extra: vec![ObjectPredicate::OfChosenName],
            ..Default::default()
        }
    } else if eq_ci(filter_str, "cards with the same name as that card")
        || eq_ci(filter_str, "card with the same name as that card")
    {
        ObjectFilter::default()
    } else {
        let clean_filter_str = strip_suffix_word_ci(filter_str, "that have different names")
            .or_else(|| strip_suffix_word_ci(filter_str, "with different names"))
            .or_else(|| strip_suffix_word_ci(filter_str, "that share a land type"))
            .unwrap_or(filter_str);
        let opts = FilterOpts {
            default_zone: ZoneMask::empty(),
            allow_plural_and_disjunction: true,
            strip_trailing_card: true,
            ..Default::default()
        };
        if let Some(f) = parse_object_phrase(clean_filter_str, ctx, opts) {
            f
        } else if let Some(mc_pos) = find_word_ci(clean_filter_str, " with mana cost ")
            && let Some(f) = parse_object_phrase(clean_filter_str[..mc_pos].trim(), ctx, opts)
            && filter_has_quality(&f)
            && is_numeric_mana_cost_disjunction(
                clean_filter_str[mc_pos + " with mana cost ".len()..].trim(),
            )
        {
            f
        } else if let Some(mv_pos) = find_word_ci(
            clean_filter_str,
            " with mana value equal to 1 plus the sacrificed creature's mana value",
        ) && let Some(mut f) =
            parse_object_phrase(clean_filter_str[..mv_pos].trim(), ctx, opts)
        {
            f.mana_value = Some(mtg_ir::Compare {
                op: mtg_ir::CompareOp::Eq,
                value: Box::new(Amount::Sum {
                    args: vec![
                        Amount::Const { n: 1 },
                        Amount::SacrificedCostStat {
                            stat: mtg_ir::SacrificedStatKind::ManaValue,
                        },
                    ],
                }),
            });
            f
        } else {
            state.rollback(search_mark, ctx);
            return false;
        }
    };
    let searched_player = searched_player_rel.map(|rel| {
        let mut sp = default_target_spec();
        sp.kind = TargetKind::Player;
        sp.player = Some(PlayerFilter { relation: rel });
        let idx = state.add_target(sp);
        PlayerRef::Target { index: idx }
    });
    let has_quality = filter_has_quality(&filter);
    let step_subject = if matches!(subj, Selector::Player { filter: p } if p.relation == PlayerRelation::You)
        || matches!(subj, Selector::PlayerRef { .. })
    {
        Selector::None
    } else {
        subj
    };
    let mut st = make_step(
        EffectOp::Search {
            tapped: if is_capenna_m { false } else { tapped_op },
            spec: Box::new(SearchSpec {
                filter: Box::new(filter),
                count,
                up_to,
                stated_quality: has_quality,
                destinations: dests,
                reveal,
                description: Some(filter_raw.to_string()),
                zones: search_zones,
                different_names: contains_word_ci(filter_raw, "different names"),
                shuffle_only_if_library: shuffle_only_if_lib,
                searched_player,
                cast_free,
                target_controller_as_actor: false,
            }),
        },
        step_subject,
        span,
    );
    st.actor = actor;
    if is_capenna_m {
        st.amount = None;
        st.bind_as = None;
    } else {
        st.amount = Some(Box::new(
            x_amount.unwrap_or(Amount::Const { n: count as i32 }),
        ));
        st.bind_as = Some("searched".to_string());
    }
    state.push_step(st, true);
    if let Some(after_sh) = post_shuffle_and
        && !parse_clauses_into(after_sh, span.start, ctx, state)
    {
        state.rollback(search_mark, ctx);
        return false;
    }
    true
}

fn parse_flip_coin_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if let Some(cnt_s) = strip_prefix_word_ci(t, "flip")
        .and_then(|r| strip_suffix_word_ci(r, "coins").or_else(|| strip_suffix_word_ci(r, "coin")))
        && let Some(amt) = parse_amount_str(if eq_ci(cnt_s, "a") { "1" } else { cnt_s }, ctx, state)
    {
        let mut st = make_step(
            EffectOp::FlipCoin {
                until_lose: false,
                win_effect: Vec::new(),
                lose_effect: Vec::new(),
            },
            you_sel(),
            span,
        );
        if !matches!(amt, Amount::Const { n: 1 }) {
            st.amount = Some(Box::new(amt));
        }
        state.push_step(st, false);
        return true;
    }
    if eq_ci(t, "flip a coin until you lose a flip") {
        state.push_step(
            make_step(
                EffectOp::FlipCoin {
                    until_lose: true,
                    win_effect: Vec::new(),
                    lose_effect: Vec::new(),
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(rest) = strip_prefix_word_ci(t, "flip a coin. if you win the flip,") {
        let sub = state.parse_sub_effects(rest, span.start, state.context, ctx);
        if sub.unparsed.is_empty() && !sub.steps.is_empty() {
            state.targets.extend(sub.targets);
            state.push_step(
                make_step(
                    EffectOp::FlipCoin {
                        until_lose: false,
                        win_effect: sub.steps,
                        lose_effect: Vec::new(),
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }
    }
    false
}

fn parse_roll_die_clause(
    t: &str,
    span: Span,
    _ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if let Some(after_a) = strip_prefix_word_ci(t, "roll a")
        .or_else(|| strip_prefix_word_ci(t, "roll an"))
        .or_else(|| strip_prefix_word_ci(t, "you roll a"))
        .or_else(|| strip_prefix_word_ci(t, "you roll an"))
    {
        let sides_opt: Option<u16> = if after_a
            .as_bytes()
            .first()
            .is_some_and(|b| b.eq_ignore_ascii_case(&b'd'))
        {
            after_a[1..].trim().parse::<u16>().ok()
        } else if let Some(prefix) = strip_suffix_word_ci(after_a.trim(), "-sided die")
            .or_else(|| strip_suffix_word_ci(after_a.trim(), " sided die"))
        {
            let p = prefix.trim();
            if eq_ci(p, "four") || p == "4" {
                Some(4)
            } else if eq_ci(p, "six") || p == "6" {
                Some(6)
            } else if eq_ci(p, "eight") || p == "8" {
                Some(8)
            } else if eq_ci(p, "ten") || p == "10" {
                Some(10)
            } else if eq_ci(p, "twelve") || p == "12" {
                Some(12)
            } else if eq_ci(p, "twenty") || p == "20" {
                Some(20)
            } else {
                p.parse::<u16>().ok()
            }
        } else {
            None
        };
        if let Some(sides) = sides_opt
            && sides >= 2
        {
            state.push_step(
                make_step(
                    EffectOp::RollDie {
                        sides,
                        bonus: None,
                        table: Vec::new(),
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }
    }
    false
}

fn parse_choose_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if eq_ci(t, "choose a color") || eq_ci(t, "each player chooses a color") {
        state.push_step(
            make_step(
                EffectOp::ChooseDesignation {
                    kind: DesignationKind::Color,
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(t, "choose a creature type") || eq_ci(t, "each player chooses a creature type") {
        state.push_step(
            make_step(
                EffectOp::ChooseDesignation {
                    kind: DesignationKind::CreatureType,
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(t, "choose a card name") {
        state.push_step(
            make_step(
                EffectOp::ChooseDesignation {
                    kind: DesignationKind::CardName,
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(t, "choose a nonland card name") {
        state.push_step(
            make_step(
                EffectOp::ChooseDesignation {
                    kind: DesignationKind::NonlandCardName,
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(
        t,
        "choose any target, then choose another target for each time ~ was kicked",
    ) || eq_ci(
        t,
        "choose any target, then choose another target for each time this spell was kicked",
    ) {
        let ttoks = tokenize("any target", 0);
        let cp = ctx.interner.checkpoint();
        if let Some((mut sp, used)) = parse_target_spec(&ttoks, ctx, state)
            && used == ttoks.len()
        {
            sp.min = 1;
            sp.max = 99;
            sp.dynamic_count = Some(Box::new(Amount::Sum {
                args: vec![
                    Amount::Const { n: 1 },
                    Amount::KickedCount {
                        tag: None,
                        multiplier: None,
                    },
                ],
            }));
            let idx = state.add_target(sp);
            let step_idx = state.steps.len();
            state.last_object = Some((Ref::Target { index: idx }, step_idx));
            return true;
        }
        ctx.interner.rollback(cp);
    }
    if (eq_ci(t, "choose another target for each time ~ was kicked")
        || eq_ci(
            t,
            "choose another target for each time this spell was kicked",
        ))
        && let Some(last_t) = state.targets.last_mut()
    {
        last_t.max = 99;
        last_t.dynamic_count = Some(Box::new(Amount::Sum {
            args: vec![
                Amount::Const { n: 1 },
                Amount::KickedCount {
                    tag: None,
                    multiplier: None,
                },
            ],
        }));
        let idx = (state.targets.len() - 1) as u16;
        let step_idx = state.steps.len();
        state.last_object = Some((Ref::Target { index: idx }, step_idx));
        return true;
    }
    if let Some(rest) = strip_prefix_word_ci(t, "choose")
        && contains_word_ci(rest, "target")
    {
        let dz = if contains_word_ci(rest, "exiled this way") || contains_word_ci(rest, "in exile")
        {
            ZoneMask::EXILE
        } else if contains_word_ci(rest, "graveyard") {
            ZoneMask::GRAVEYARD
        } else {
            ZoneMask::BATTLEFIELD
        };
        if let Some(ParsedObj::Target(idx)) = parse_object_selector(rest, dz, ctx, state) {
            let step_idx = state.steps.len();
            state.last_object = Some((Ref::Target { index: idx }, step_idx));
            return true;
        }
    }
    if let Some(rest) = strip_prefix_word_ci(t, "choose")
        && !contains_word_ci(rest, "target")
        && !contains_word_ci(rest, "type")
        && !contains_word_ci(rest, "name")
        && !contains_word_ci(rest, "color")
        && !contains_word_ci(rest, " and ")
        && !contains_word_ci(rest, " then ")
        && !contains_word_ci(rest, " from ")
        && !contains_word_ci(rest, " in ")
        && let Some(filt_s) =
            strip_prefix_word_ci(rest, "a").or_else(|| strip_prefix_word_ci(rest, "an"))
        && let ftoks = tokenize(filt_s, 0)
        && !ftoks.is_empty()
    {
        let dz = if starts_with_word_ci(filt_s, "exiled ") {
            ZoneMask::EXILE
        } else {
            ZoneMask::BATTLEFIELD
        };
        let cp = ctx.interner.checkpoint();
        if let Some((mut f, used)) = parse_object_filter(
            &ftoks,
            ctx,
            FilterOpts {
                default_zone: dz,
                allow_plural_and_disjunction: true,
                allow_spell_noun: false,
                strip_trailing_card: false,
                expand_outlaw_subtypes: false,
            },
            state,
        ) && used == ftoks.len()
        {
            if f.zones.is_empty() {
                f.zones = dz;
            }
            let op = if f.zones == ZoneMask::EXILE {
                EffectOp::Exile {
                    select: SelectionMod {
                        choice_count: Some(Box::new(Amount::Const { n: 1 })),
                        ..Default::default()
                    },
                    duration: None,
                    until_source_leaves: false,
                    until_opponent_becomes_monarch: false,
                    exile_all_except_bottom: false,
                    face_down: false,
                    look_only: false,
                    exile_with_counters: None,
                }
            } else {
                EffectOp::Reveal {
                    select: SelectionMod {
                        choice_count: Some(Box::new(Amount::Const { n: 1 })),
                        ..Default::default()
                    },
                    look_only: true,
                    special_tag: None,
                }
            };
            let mut st = make_step(
                op,
                Selector::All {
                    filter: Box::new(f),
                },
                span,
            );
            st.bind_as =
                Some(state.alloc_bind_name(if dz == ZoneMask::EXILE { "b" } else { "chosen" }));
            state.push_step(st, true);
            return true;
        }
        ctx.interner.rollback(cp);
    }
    false
}

fn parse_copy_imperative(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let Some(rest) = strip_prefix_word_ci(t, "copy") else {
        return false;
    };
    let (may_new, subj_raw) =
        if let Some(pos) = find_word_ci(rest, ". you may choose new targets for") {
            (true, rest[..pos].trim())
        } else if let Some(pos) = find_word_ci(rest, ", you may choose new targets") {
            (true, rest[..pos].trim())
        } else if let Some(pos) = find_word_ci(rest, " and may choose a new target") {
            (true, rest[..pos].trim())
        } else if let Some(pos) = find_word_ci(rest, " and may choose new targets") {
            (true, rest[..pos].trim())
        } else if let Some(pos) = find_word_ci(rest, " and you may choose new targets") {
            (true, rest[..pos].trim())
        } else {
            (false, rest)
        };
    if eq_ci(subj_raw, "that ability") || eq_ci(subj_raw, "that triggered ability") {
        state.push_step(
            make_step(
                EffectOp::CopySpell {
                    count: None,
                    may_choose_new_targets: may_new,
                    non_legendary: false,
                    except_colors: ColorMask::empty(),
                    copy_event_ability: true,
                    copy_per_sacrificed_cost: false,
                    copy_all_controlled_spells_and_other_abilities: false,
                },
                Selector::EventObject,
                span,
            ),
            true,
        );
        return true;
    }
    if let Some(obj) = parse_object_selector(subj_raw, ZoneMask::STACK, ctx, state) {
        let target_idx = match obj {
            ParsedObj::Target(idx) => Some(idx),
            _ => None,
        };
        let step_idx = state.steps.len();
        state.push_step(
            make_step(
                EffectOp::CopySpell {
                    count: Some(Box::new(Amount::Const { n: 1 })),
                    may_choose_new_targets: may_new,
                    non_legendary: false,
                    except_colors: ColorMask::empty(),
                    copy_event_ability: false,
                    copy_per_sacrificed_cost: false,
                    copy_all_controlled_spells_and_other_abilities: false,
                },
                obj.into_selector(),
                span,
            ),
            false,
        );
        if let Some(idx) = target_idx {
            state.last_object = Some((Ref::Target { index: idx }, step_idx));
        }
        return true;
    }
    false
}
// ============================================================================
// Section 6c: Damage, Object Predicates, Player Predicates, Delayed & Reflexive
// ============================================================================

fn parse_damage_or_object_predicate(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let first_w = t.split_whitespace().next().unwrap_or("");
    if eq_ci(first_w, "draw")
        || eq_ci(first_w, "destroy")
        || eq_ci(first_w, "exile")
        || eq_ci(first_w, "create")
        || eq_ci(first_w, "put")
        || eq_ci(first_w, "return")
        || eq_ci(first_w, "sacrifice")
        || eq_ci(first_w, "discard")
        || eq_ci(first_w, "mill")
        || eq_ci(first_w, "tap")
        || eq_ci(first_w, "untap")
        || eq_ci(first_w, "search")
        || eq_ci(first_w, "reveal")
        || eq_ci(first_w, "look")
        || eq_ci(first_w, "add")
        || eq_ci(first_w, "choose")
        || eq_ci(first_w, "counter")
        || eq_ci(first_w, "prevent")
        || eq_ci(first_w, "shuffle")
        || eq_ci(first_w, "gain")
        || eq_ci(first_w, "lose")
        || eq_ci(first_w, "scry")
        || eq_ci(first_w, "surveil")
        || eq_ci(first_w, "investigate")
        || eq_ci(first_w, "proliferate")
    {
        return false;
    }
    if state.in_trigger_context()
        && state
            .trigger
            .is_some_and(|tr| matches!(tr.event, EventKind::Cast) && tr.spell_delayed.is_none())
        && let Some(ent_pos) = find_word_ci(t, " enters with ")
    {
        let subj_s = t[..ent_pos].trim();
        let after_ent = t[ent_pos + " enters with ".len()..].trim();
        let body = strip_suffix_word_ci(after_ent, "on it")
            .or_else(|| strip_suffix_word_ci(after_ent, "on them"))
            .unwrap_or(after_ent);
        if (starts_with_word_ci(subj_s, "that ") || eq_ci(subj_s, "it"))
            && let Some(add_pos) = find_word_ci(body, " additional ")
            && let Some(ctr_body) =
                strip_suffix_word_ci(body[add_pos + " additional ".len()..].trim(), "counters")
                    .or_else(|| {
                        strip_suffix_word_ci(
                            body[add_pos + " additional ".len()..].trim(),
                            "counter",
                        )
                    })
            && let Some(amt) = parse_amount_str(body[..add_pos].trim(), ctx, state)
        {
            let ctr_id = ctx.interner.intern_counter(ctr_body.trim());
            let mut st = make_step(
                EffectOp::PutCounters {
                    counter: Some(ctr_id),
                    multi_counters: Vec::new(),
                    select: SelectionMod::default(),
                    divided: false,
                    allow_exile_counters: false,
                    remove_instead_of_add: false,
                    copy_counters_from: None,
                    choose_counter_on_subject_and_add_one: false,
                    conditional_counter_on_type: None,
                    cast_bolas_bonus_loyalty: false,
                },
                Selector::EventObject,
                span,
            );
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
    }
    // 1. "<source> deals <amt> damage to <recipient>" (or "divided as you choose among ..."),
    //    "<source> deals damage equal to <amt> to <recipient>", or
    //    "<source> deals damage to <recipient> equal to <amt>"
    if let Some(deals_pos) = find_word_ci(t, " deals ") {
        let src_raw = t[..deals_pos].trim();
        let after_deals = t[deals_pos + " deals ".len()..].trim();
        let mark_dmg = state.mark(ctx);

        let resolve_src = |src_raw: &str,
                           ctx: &mut ParseCtx<'_>,
                           state: &mut ParserState<'_>|
         -> Option<Selector> {
            if eq_ci(src_raw, "~") || eq_ci(src_raw, "it") {
                if eq_ci(src_raw, "it") {
                    Some(state.it_ref().map(|r| ref_to_selector(&r)).unwrap_or({
                        if state.in_trigger_context() {
                            Selector::EventObject
                        } else {
                            Selector::SelfObj
                        }
                    }))
                } else {
                    Some(Selector::SelfObj)
                }
            } else {
                parse_object_selector(src_raw, ZoneMask::BATTLEFIELD, ctx, state)
                    .map(ParsedObj::into_selector)
            }
        };

        if let Some(each_body) = strip_prefix_word_ci(src_raw, "each")
            && let Some((to_controller, amt_opt_raw)) =
                strip_prefix_word_ci(after_deals, "damage to itself equal to")
                    .map(|r| (false, Some(r)))
                    .or_else(|| {
                        strip_prefix_word_ci(after_deals, "damage to its controller equal to")
                            .map(|r| (true, Some(r)))
                    })
                    .or_else(|| {
                        strip_suffix_word_ci(after_deals, "damage to itself")
                            .map(|r| (false, Some(r)))
                    })
                    .or_else(|| {
                        strip_suffix_word_ci(after_deals, "damage to its controller")
                            .map(|r| (true, Some(r)))
                    })
            && !eq_ci(each_body, "player")
            && !eq_ci(each_body, "opponent")
            && let Some(filter) = parse_object_phrase(
                each_body,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    strip_trailing_card: false,
                    ..Default::default()
                },
            )
        {
            let amt_s = amt_opt_raw.unwrap_or("").trim();
            let amount_res = if eq_ci(amt_s, "its power") {
                Some(None)
            } else {
                parse_amount_str(amt_s, ctx, state).map(|a| Some(Box::new(a)))
            };
            if let Some(amount) = amount_res {
                let st = make_step(
                    EffectOp::Damage {
                        source: None,
                        also_players: None,
                        divided: false,
                        excess_to_controller: false,
                        excess_to_controller_if_trample: false,
                        or_planeswalker_controlled_by: None,
                        damage_attacked_target_by_self: false,
                        soulfire_exile_damage_per_target: false,
                        each_creature_deals: Some(EachCreatureDealsDamage {
                            filter: Box::new(filter),
                            to_controller,
                            amount,
                        }),
                    },
                    Selector::None,
                    span,
                );
                state.push_step(st, false);
                return true;
            }
            state.rollback(mark_dmg.clone(), ctx);
        }

        let mut handled_eq = false;
        if let Some(after_eq) = strip_prefix_word_ci(after_deals, "damage equal to")
            && let Some(src_sel) = resolve_src(src_raw, ctx, state)
        {
            handled_eq = true;
            let prev_last = state.last_object.clone();
            match &src_sel {
                Selector::Target { index } => {
                    state.last_object = Some((Ref::Target { index: *index }, state.steps.len()));
                }
                Selector::EventObject if state.last_object.is_none() => {
                    state.last_object = Some((Ref::EventObject, state.steps.len()));
                }
                Selector::Binding { name } => {
                    state.last_object =
                        Some((Ref::Binding { name: name.clone() }, state.steps.len()));
                }
                _ => {}
            }
            // Split "<amt_raw> to <recip_raw>" trying " to " positions from right to left
            let mut to_positions = Vec::new();
            let mut off = 0usize;
            while let Some(pos) = find_ascii_ci_from(after_eq.as_bytes(), b" to ", off) {
                to_positions.push(pos);
                off = pos + 4;
            }
            let mut matched = None;
            for pos in to_positions.into_iter().rev() {
                let amt_s = after_eq[..pos].trim();
                let recip_s = after_eq[pos + 4..].trim();
                let mark_try = state.mark(ctx);
                if (eq_ci(
                    recip_s,
                    "that player or a planeswalker that player controls",
                ) || eq_ci(
                    recip_s,
                    "that opponent or a planeswalker that opponent controls",
                )) && matches!(
                    &state.last_player,
                    Some(Selector::PlayerRef {
                        player: PlayerRef::ChosenOpponent
                    })
                ) && let Some(amt) = parse_amount_str(amt_s, ctx, state)
                {
                    matched = Some((amt, Selector::None, Some(PlayerRef::ChosenOpponent)));
                    break;
                }
                state.rollback(mark_try.clone(), ctx);
                if let Some(amt) = parse_amount_str(amt_s, ctx, state)
                    && let Some(recip_sel) = parse_any_recipient_selector(recip_s, ctx, state)
                {
                    matched = Some((amt, recip_sel, None));
                    break;
                }
                state.rollback(mark_try, ctx);
            }
            state.last_object = prev_last;
            if let Some((amt, recip_sel, or_pw)) = matched {
                let src_ref = match &src_sel {
                    Selector::Target { index } => Some(Ref::Target { index: *index }),
                    Selector::Binding { name } => Some(Ref::Binding { name: name.clone() }),
                    Selector::EventObject => Some(Ref::EventObject),
                    Selector::SelfObj => Some(Ref::SelfObj),
                    _ => None,
                };
                let recip_allows_player = matches!(&recip_sel, Selector::Target { index } if state.targets.get(*index as usize).is_some_and(|t| t.player.is_some()));
                let mut st = make_step(
                    EffectOp::Damage {
                        source: if matches!(src_sel, Selector::SelfObj) {
                            None
                        } else {
                            Some(Box::new(src_sel))
                        },
                        also_players: None,
                        divided: false,
                        excess_to_controller: false,
                        excess_to_controller_if_trample: false,
                        or_planeswalker_controlled_by: or_pw,
                        damage_attacked_target_by_self: false,
                        soulfire_exile_damage_per_target: false,
                        each_creature_deals: None,
                    },
                    recip_sel,
                    span,
                );
                st.amount = Some(Box::new(amt));
                if recip_allows_player && let Some(sref) = src_ref {
                    let step_idx = state.steps.len();
                    state.push_step(st, false);
                    state.last_object = Some((sref, step_idx));
                } else {
                    state.push_step(st, true);
                }
                return true;
            }
        }
        if !handled_eq
            && let Some(after_to) = strip_prefix_word_ci(after_deals, "damage to")
            && let Some(eq_pos) = find_word_ci(after_to, " equal to ")
            && let Some(src_sel) = resolve_src(src_raw, ctx, state)
        {
            handled_eq = true;
            let recip_s = after_to[..eq_pos].trim();
            let amt_s = after_to[eq_pos + " equal to ".len()..].trim();
            let prev_last = state.last_object.clone();
            let loop_kind = if eq_ci(recip_s, "each player") {
                Some(LoopPlayersKind::EachPlayer)
            } else if eq_ci(recip_s, "each opponent") {
                Some(LoopPlayersKind::EachOpponent)
            } else if eq_ci(recip_s, "each other player") {
                Some(LoopPlayersKind::EachOtherPlayer)
            } else {
                None
            };
            if let Some(lk) = loop_kind
                && (contains_word_ci(amt_s, "they")
                    || contains_word_ci(amt_s, "their")
                    || contains_word_ci(amt_s, "that player"))
            {
                let prev_loop = state.is_each_loop;
                state.is_each_loop = true;
                let parsed_amt = parse_amount_str(amt_s, ctx, state);
                state.is_each_loop = prev_loop;
                if let Some(amt) = parsed_amt {
                    state.last_object = prev_last;
                    let mut inner = make_step(
                        EffectOp::Damage {
                            source: if matches!(src_sel, Selector::SelfObj) {
                                None
                            } else {
                                Some(Box::new(src_sel))
                            },
                            also_players: None,
                            divided: false,
                            excess_to_controller: false,
                            excess_to_controller_if_trample: false,
                            or_planeswalker_controlled_by: None,
                            damage_attacked_target_by_self: false,
                            soulfire_exile_damage_per_target: false,
                            each_creature_deals: None,
                        },
                        Selector::PlayerRef {
                            player: PlayerRef::EachLoopPlayer,
                        },
                        span,
                    );
                    inner.amount = Some(Box::new(amt));
                    state.push_step(
                        make_step(
                            EffectOp::ForEachPlayerLoop {
                                players: lk,
                                steps: vec![inner],
                                choose_random_opponent: false,
                                exclude_attacked_last_combat: false,
                                exclude_event_player: false,
                                choose_object_to_bind: None,
                            },
                            Selector::None,
                            span,
                        ),
                        false,
                    );
                    return true;
                }
            } else if let Some(recip_sel) = parse_any_recipient_selector(recip_s, ctx, state)
                && let Some(amt) = parse_amount_str(amt_s, ctx, state)
            {
                state.last_object = prev_last;
                let mut st = make_step(
                    EffectOp::Damage {
                        source: if matches!(src_sel, Selector::SelfObj) {
                            None
                        } else {
                            Some(Box::new(src_sel))
                        },
                        also_players: None,
                        divided: false,
                        excess_to_controller: false,
                        excess_to_controller_if_trample: false,
                        or_planeswalker_controlled_by: None,
                        damage_attacked_target_by_self: false,
                        soulfire_exile_damage_per_target: false,
                        each_creature_deals: None,
                    },
                    recip_sel,
                    span,
                );
                st.amount = Some(Box::new(amt));
                state.push_step(st, true);
                return true;
            }
            state.last_object = prev_last;
        }
        if handled_eq {
            state.rollback(mark_dmg, ctx);
        } else if let Some(dmg_pos) = find_word_ci(after_deals, " damage ") {
            let amt_raw = after_deals[..dmg_pos].trim();
            let rest = after_deals[dmg_pos + " damage ".len()..].trim();

            if let Some(src_sel) = resolve_src(src_raw, ctx, state)
                && let Some(amt) = parse_amount_str(amt_raw, ctx, state)
            {
                // Check divided damage: "divided as you choose among <target_spec>"
                if let Some(after_div) = strip_prefix_word_ci(rest, "divided as you choose among") {
                    let toks = tokenize(after_div, 0);
                    let cp = ctx.interner.checkpoint();
                    let tlen = state.targets.len();
                    if let Some((mut spec, used)) = parse_target_spec(&toks, ctx, state)
                        && used == toks.len()
                    {
                        spec.divide_total = Some(Box::new(amt.clone()));
                        let idx = state.add_target(spec);
                        let mut st = make_step(
                            EffectOp::Damage {
                                source: if matches!(src_sel, Selector::SelfObj) {
                                    None
                                } else {
                                    Some(Box::new(src_sel))
                                },
                                also_players: None,
                                divided: true,
                                excess_to_controller: false,
                                excess_to_controller_if_trample: false,
                                or_planeswalker_controlled_by: None,
                                damage_attacked_target_by_self: false,
                                soulfire_exile_damage_per_target: false,
                                each_creature_deals: None,
                            },
                            Selector::Target { index: idx },
                            span,
                        );
                        st.amount = Some(Box::new(amt));
                        state.push_step(st, true);
                        return true;
                    }
                    ctx.interner.rollback(cp);
                    state.targets.truncate(tlen);
                }

                // Dual damage: "<src> deals <amt> damage to <A> and <amt2> damage to <B>"
                if let Some(recip_raw) = strip_prefix_word_ci(rest, "to")
                    && let Some(dmg_idx) = find_word_ci(recip_raw, "damage to")
                    && let Some(and_idx) =
                        rfind_ascii_ci(&recip_raw.as_bytes()[..dmg_idx], b" and ")
                {
                    let mark_dual = state.mark(ctx);
                    let src_eff = if matches!(src_sel, Selector::SelfObj) && eq_ci(src_raw, "it") {
                        "~"
                    } else {
                        src_raw
                    };
                    let lhs_recip = recip_raw[..and_idx].trim();
                    let rhs_tail = recip_raw[and_idx + 5..].trim();
                    if parse_damage_or_object_predicate(
                        &format!("{src_eff} deals {amt_raw} damage to {lhs_recip}"),
                        span,
                        ctx,
                        state,
                    ) && parse_damage_or_object_predicate(
                        &format!("{src_eff} deals {rhs_tail}"),
                        span,
                        ctx,
                        state,
                    ) {
                        return true;
                    }
                    state.rollback(mark_dual, ctx);
                }

                // Standard "to <recipient>"
                if let Some(recip_raw) = strip_prefix_word_ci(rest, "to") {
                    let (recip_clean, excess_ctrl) = if let Some(r) =
                        strip_suffix_word_ci(recip_raw, "and the excess to its controller")
                    {
                        (r, true)
                    } else {
                        (recip_raw, false)
                    };
                    let (recip_body, also_players) = if let Some(lhs) =
                        strip_suffix_word_ci(recip_clean, "and each opponent")
                    {
                        (
                            lhs.trim(),
                            Some(PlayerFilter {
                                relation: PlayerRelation::EachOpponent,
                            }),
                        )
                    } else if let Some(lhs) = strip_suffix_word_ci(recip_clean, "and each player") {
                        (
                            lhs.trim(),
                            Some(PlayerFilter {
                                relation: PlayerRelation::EachPlayer,
                            }),
                        )
                    } else {
                        (recip_clean, None)
                    };
                    let recip_sel = if also_players.is_some() {
                        let Some(ParsedObj::All(f)) =
                            parse_object_selector(recip_body, ZoneMask::BATTLEFIELD, ctx, state)
                        else {
                            state.rollback(mark_dmg, ctx);
                            return false;
                        };
                        Selector::All {
                            filter: Box::new(f),
                        }
                    } else if eq_ci(recip_clean, "each other opponent") {
                        let is_self_src = matches!(src_sel, Selector::SelfObj)
                            || (matches!(src_sel, Selector::EventObject)
                                && state.trigger.is_some_and(|tr| {
                                    matches!(
                                        tr.filter.object,
                                        Some(mtg_ir::TriggerSubject::SelfObj)
                                    )
                                }));
                        let mut inner = make_step(
                            EffectOp::Damage {
                                source: if is_self_src {
                                    None
                                } else {
                                    Some(Box::new(src_sel))
                                },
                                also_players: None,
                                divided: false,
                                excess_to_controller: excess_ctrl,
                                excess_to_controller_if_trample: false,
                                or_planeswalker_controlled_by: None,
                                damage_attacked_target_by_self: false,
                                soulfire_exile_damage_per_target: false,
                                each_creature_deals: None,
                            },
                            Selector::PlayerRef {
                                player: PlayerRef::EachLoopPlayer,
                            },
                            span,
                        );
                        inner.amount = Some(Box::new(amt));
                        state.push_step(
                            make_step(
                                EffectOp::ForEachPlayerLoop {
                                    players: LoopPlayersKind::EachOpponent,
                                    steps: vec![inner],
                                    choose_random_opponent: false,
                                    exclude_attacked_last_combat: false,
                                    exclude_event_player: true,
                                    choose_object_to_bind: None,
                                },
                                Selector::None,
                                span,
                            ),
                            false,
                        );
                        return true;
                    } else if eq_ci(recip_clean, "the player or planeswalker it's attacking")
                        || eq_ci(recip_clean, "the player or planeswalker ~ is attacking")
                        || eq_ci(
                            recip_clean,
                            "the defending player or a planeswalker they control",
                        )
                    {
                        let mut st = make_step(
                            EffectOp::Damage {
                                source: if matches!(src_sel, Selector::SelfObj) {
                                    None
                                } else {
                                    Some(Box::new(src_sel))
                                },
                                also_players,
                                divided: false,
                                excess_to_controller: excess_ctrl,
                                excess_to_controller_if_trample: false,
                                or_planeswalker_controlled_by: None,
                                damage_attacked_target_by_self: true,
                                soulfire_exile_damage_per_target: false,
                                each_creature_deals: None,
                            },
                            Selector::None,
                            span,
                        );
                        st.amount = Some(Box::new(amt));
                        state.push_step(st, false);
                        return true;
                    } else if eq_ci(
                        recip_clean,
                        "each opponent who discarded their hand this way",
                    ) {
                        let is_self_src = matches!(src_sel, Selector::SelfObj)
                            || (matches!(src_sel, Selector::EventObject)
                                && state.trigger.is_some_and(|tr| {
                                    matches!(
                                        tr.filter.object,
                                        Some(mtg_ir::TriggerSubject::SelfObj)
                                    )
                                }));
                        let mut inner = make_step(
                            EffectOp::Damage {
                                source: if is_self_src {
                                    None
                                } else {
                                    Some(Box::new(src_sel))
                                },
                                also_players: None,
                                divided: false,
                                excess_to_controller: excess_ctrl,
                                excess_to_controller_if_trample: false,
                                or_planeswalker_controlled_by: None,
                                damage_attacked_target_by_self: false,
                                soulfire_exile_damage_per_target: false,
                                each_creature_deals: None,
                            },
                            Selector::PlayerRef {
                                player: PlayerRef::EachLoopPlayer,
                            },
                            span,
                        );
                        inner.amount = Some(Box::new(amt));
                        inner.gate = Some(StepGate::Condition {
                            condition: Box::new(Condition::PlayerDiscardedHandThisWay),
                        });
                        state.push_step(
                            make_step(
                                EffectOp::ForEachPlayerLoop {
                                    players: LoopPlayersKind::EachOpponent,
                                    steps: vec![inner],
                                    choose_random_opponent: false,
                                    exclude_attacked_last_combat: false,
                                    exclude_event_player: false,
                                    choose_object_to_bind: None,
                                },
                                Selector::None,
                                span,
                            ),
                            false,
                        );
                        return true;
                    } else if eq_ci(recip_clean, "that creature or planeswalker") {
                        let Some(sel) = state.it_ref().map(|r| ref_to_selector(&r)) else {
                            state.rollback(mark_dmg, ctx);
                            return false;
                        };
                        sel
                    } else {
                        let Some(sel) = parse_any_recipient_selector(recip_clean, ctx, state)
                        else {
                            state.rollback(mark_dmg, ctx);
                            return false;
                        };
                        sel
                    };
                    let mut st = make_step(
                        EffectOp::Damage {
                            source: if matches!(src_sel, Selector::SelfObj) {
                                None
                            } else {
                                Some(Box::new(src_sel))
                            },
                            also_players,
                            divided: false,
                            excess_to_controller: excess_ctrl,
                            excess_to_controller_if_trample: false,
                            or_planeswalker_controlled_by: None,
                            damage_attacked_target_by_self: false,
                            soulfire_exile_damage_per_target: false,
                            each_creature_deals: None,
                        },
                        recip_sel,
                        span,
                    );
                    st.amount = Some(Box::new(amt));
                    state.push_step(st, true);
                    return true;
                }
            }
            state.rollback(mark_dmg, ctx);
        } else {
            state.rollback(mark_dmg, ctx);
        }
    }

    // 2. Object predicates: "<obj> <predicate...>"
    if let Some((pron, after_its)) = strip_prefix_word_ci(t, "it's")
        .map(|r| ("it", r))
        .or_else(|| strip_prefix_word_ci(t, "they're").map(|r| ("they", r)))
        && contains_word_ci(after_its, "in addition to")
    {
        let mark = state.mark(ctx);
        let verb = if pron == "they" { "are" } else { "is" };
        let pred = format!("{verb} {after_its}");
        if let Some(obj) = parse_object_selector(pron, ZoneMask::BATTLEFIELD, ctx, state)
            && parse_object_predicate_tail(obj.into_selector(), &pred, span, ctx, state)
        {
            return true;
        }
        state.rollback(mark, ctx);
    }

    // Check common split verbs: gets, gains, gain, get, loses, fights, fight, becomes, become, can't, is, are
    for (verb_tok, is_plural) in [
        (" also gets ", false),
        (" also get ", true),
        (" also gains ", false),
        (" also gain ", true),
        (" gets ", false),
        (" get ", true),
        (" gains ", false),
        (" gain ", true),
        (" loses ", false),
        (" lose ", true),
        (" fights ", false),
        (" fight ", true),
        (" attacks ", false),
        (" attack ", true),
        (" becomes ", false),
        (" become ", true),
        (" can't ", false),
        (" isn't ", false),
        (" aren't ", true),
        (" is not ", false),
        (" are not ", true),
        (" is ", false),
        (" are ", true),
        (" has ", false),
        (" have ", true),
    ] {
        let _ = is_plural;
        if (verb_tok == " is " || verb_tok == " are ") && !contains_word_ci(t, "in addition to") {
            continue;
        }
        if (verb_tok == " has " || verb_tok == " have ")
            && !contains_word_ci(t, "base power and toughness")
        {
            continue;
        }
        if let Some(vpos) = find_word_ci(t, verb_tok) {
            let subj_raw = t[..vpos].trim();
            let subj_raw = strip_prefix_word_ci(subj_raw, "each of").unwrap_or(subj_raw);
            // Skip player subjects so player_predicate handles "you gain life" etc.
            if eq_ci(subj_raw, "you")
                || eq_ci(subj_raw, "each player")
                || eq_ci(subj_raw, "each opponent")
                || eq_ci(subj_raw, "target player")
                || eq_ci(subj_raw, "target opponent")
                || eq_ci(subj_raw, "that player")
            {
                continue;
            }
            let pred_raw = t[vpos..].trim();
            let pred = strip_prefix_word_ci(pred_raw, "also").unwrap_or(pred_raw);
            if let Some(base_subj) = strip_suffix_word_ci(subj_raw, "each")
                && let Some(and_pos) = find_word_ci(base_subj, " and ")
            {
                let mark0 = state.mark(ctx);
                let s1 = base_subj[..and_pos].trim();
                let s2 = base_subj[and_pos + " and ".len()..].trim();
                let o1 = parse_object_selector(s1, ZoneMask::BATTLEFIELD, ctx, state);
                let o2 = parse_object_selector(s2, ZoneMask::BATTLEFIELD, ctx, state);
                if let Some(o1) = o1
                    && let Some(o2) = o2
                    && parse_object_predicate_tail(o1.into_selector(), pred, span, ctx, state)
                    && parse_object_predicate_tail(o2.into_selector(), pred, span, ctx, state)
                {
                    return true;
                }
                state.rollback(mark0, ctx);
            }
            let mark = state.mark(ctx);
            let subj_no_each = strip_suffix_word_ci(subj_raw, "each").unwrap_or(subj_raw);
            if let Some(obj) =
                parse_object_selector(subj_no_each, ZoneMask::BATTLEFIELD, ctx, state)
                && parse_object_predicate_tail(obj.into_selector(), pred, span, ctx, state)
            {
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    false
}

fn parse_pt_pair(pt: &str) -> Option<(Amount, Amount)> {
    let (p_s, t_s) = pt.trim().split_once('/')?;
    let parse_signed = |s: &str| -> Option<Amount> {
        let s = s.trim();
        if eq_ci(s, "+X") {
            Some(Amount::X)
        } else if eq_ci(s, "-X") {
            Some(Amount::Negate {
                of: Box::new(Amount::X),
            })
        } else if let Ok(n) = s.parse::<i32>() {
            Some(Amount::Const { n })
        } else {
            None
        }
    };
    Some((parse_signed(p_s)?, parse_signed(t_s)?))
}

fn parse_object_predicate_tail(
    subj: Selector,
    pred: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let (pred_body, where_x_amt) = if let Some((l, x_expr)) = split_where_x_is(pred) {
        if let Some(amt) = parse_amount_str(x_expr, ctx, state) {
            (l, Some(amt))
        } else {
            (pred, state.defined_x.clone())
        }
    } else {
        (pred, state.defined_x.clone())
    };
    let resolve_x = |amt: &mut Amount| {
        if let Some(ref x_val) = where_x_amt {
            if matches!(amt, Amount::X) {
                *amt = x_val.clone();
            } else if let Amount::Negate { of } = amt
                && matches!(**of, Amount::X)
            {
                **of = x_val.clone();
            }
        }
    };
    let (body_no_dur, dur_opt) = parse_duration_suffix(pred_body);
    let dur = dur_opt.or(Some(Duration::EndOfTurn));

    // "gets +P/+T" or "gets +P/+T and gains <kws>"
    if let Some(after_gets_raw) = strip_prefix_word_ci(body_no_dur, "gets")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "get"))
    {
        let after_gets =
            strip_prefix_word_ci(after_gets_raw, "an additional").unwrap_or(after_gets_raw);
        if let Some(cb_pos) = find_word_ci(after_gets, " and can't be blocked") {
            let pt_raw = after_gets[..cb_pos].trim();
            let cb_tail = after_gets[cb_pos + " and can't be blocked".len()..].trim();
            let (cb_clean, cb_dur) = parse_duration_suffix(cb_tail);
            let (pt_clean, pt_dur) = parse_duration_suffix(pt_raw);
            let final_pump_dur = dur_opt.or(pt_dur).or(Some(Duration::EndOfTurn));
            let final_cb_dur = match cb_dur.or(dur_opt) {
                Some(Duration::EndOfTurn) | None => None,
                other => other,
            };
            if cb_clean.is_empty()
                && let Some((mut pw, mut tg)) = parse_pt_pair(pt_clean)
            {
                resolve_x(&mut pw);
                resolve_x(&mut tg);
                let mut p_step = make_step(
                    EffectOp::Pump {
                        toughness: Some(Box::new(tg)),
                        duration: final_pump_dur,
                        pump_choices: Vec::new(),
                    },
                    subj.clone(),
                    span,
                );
                p_step.amount = Some(Box::new(pw));
                state.push_step(p_step, true);
                state.push_step(
                    make_step(
                        EffectOp::CombatRestriction {
                            spec: Some(TimedCombatRestrictionSpec {
                                kind: TimedCombatRestrictionKind::CantBeBlocked,
                                except_by: None,
                            }),
                            duration: final_cb_dur,
                            choose_odd_or_even_cant_block: false,
                            must_attack_next_combat: false,
                            must_attack_player: None,
                            until_your_next_turn_directive: None,
                        },
                        subj,
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
        if let Some((and_gains_pos, sep_len)) = find_word_ci(after_gets, " and gains ")
            .map(|p| (p, " and gains ".len()))
            .or_else(|| find_word_ci(after_gets, " and gain ").map(|p| (p, " and gain ".len())))
        {
            let pt_raw = after_gets[..and_gains_pos].trim();
            let kw_raw = after_gets[and_gains_pos + sep_len..].trim();
            let (kw_no_atk, must_atk) = if let Some(l) =
                strip_suffix_word_ci(kw_raw, "and attacks this combat if able")
                    .or_else(|| strip_suffix_word_ci(kw_raw, "and attack this combat if able"))
                    .or_else(|| strip_suffix_word_ci(kw_raw, "and attacks this turn if able"))
                    .or_else(|| strip_suffix_word_ci(kw_raw, "and attack this turn if able"))
            {
                (l, true)
            } else {
                (kw_raw, false)
            };
            let (kw_clean, inner_kw_dur) = if must_atk || dur_opt.is_none() {
                parse_duration_suffix(kw_no_atk)
            } else {
                (kw_no_atk, None)
            };
            let (pt_clean, pt_dur) = parse_duration_suffix(pt_raw);
            let final_dur = dur_opt
                .or(pt_dur)
                .or(inner_kw_dur)
                .or(Some(Duration::EndOfTurn));
            let parsed_kw_or_q = if let Some(kws) = parse_keyword_list_ids(kw_clean, ctx) {
                Some((kws, Vec::new()))
            } else {
                [" and \"", " and “"].iter().find_map(|sep| {
                    let pos = find_word_ci(kw_clean, sep)?;
                    let kw_part = kw_clean[..pos].trim();
                    let q_part = kw_clean[pos + 5..].trim();
                    let q = strip_outer_quotes(q_part)?;
                    let kws = parse_keyword_list_ids(kw_part, ctx)?;
                    Some((kws, vec![q.to_string()]))
                })
            };
            if let Some((mut pw, mut tg)) = parse_pt_pair(pt_clean)
                && let Some((kws, granted_texts)) = parsed_kw_or_q
            {
                resolve_x(&mut pw);
                resolve_x(&mut tg);
                for q in &granted_texts {
                    state.compile_quoted(q, "Creature", ctx);
                }
                let mut p_step = make_step(
                    EffectOp::Pump {
                        toughness: Some(Box::new(tg)),
                        duration: final_dur,
                        pump_choices: Vec::new(),
                    },
                    subj.clone(),
                    span,
                );
                p_step.amount = Some(Box::new(pw));
                state.push_step(p_step, true);
                state.push_step(
                    make_step(
                        EffectOp::Grant {
                            keywords: kws,
                            remove_keywords: SmallVec::new(),
                            cant_have_or_gain: false,
                            duration: final_dur,
                            granted_ability_texts: granted_texts,
                            choose_keyword_options: SmallVec::new(),
                            choose_lose_keyword_options: SmallVec::new(),
                            choose_protection_color: false,
                            remove_all_abilities: false,
                            can_attack_no_defender: false,
                            must_attack_this_turn: must_atk,
                            must_be_blocked_this_turn: false,
                            must_block_this_turn: false,
                            must_block_self_this_turn: false,
                            cant_block_self_this_turn: false,
                            cant_be_blocked_by_opponents_creatures: false,
                            assigns_no_combat_damage_this_turn: false,
                            grant_suspend_if_missing: false,
                            exile_resolving_spell_to_linked: false,
                            grant_trigger_spell_sunburst: false,
                            pay_any_mana_for_damage: None,
                            pay_up_to_life_gained_mana_to_draw: false,
                            gambit_combat_directive: false,
                        },
                        subj,
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
        if let Some(each_pos) = find_word_ci(after_gets, " for each ") {
            let left_raw = after_gets[..each_pos].trim();
            let each_raw = after_gets[each_pos + " for each ".len()..].trim();
            let (pt_side, dur_each) = parse_duration_suffix(left_raw);
            let final_dur = dur_opt.or(dur_each).or(Some(Duration::EndOfTurn));
            if let Some((pw_raw, tg_raw)) = parse_pt_pair(pt_side)
                && let Some(cnt) = parse_amount_str(&format!("for each {each_raw}"), ctx, state)
                    .or_else(|| parse_amount_str(each_raw, ctx, state))
            {
                let scale_pt = |a: Amount, cnt: &Amount| -> Amount {
                    match a {
                        Amount::Const { n: 0 } => Amount::Const { n: 0 },
                        Amount::Const { n: 1 } => cnt.clone(),
                        Amount::Const { n: -1 } => Amount::Negate {
                            of: Box::new(cnt.clone()),
                        },
                        Amount::Const { n } => Amount::Mul {
                            factor: n,
                            of: Box::new(cnt.clone()),
                        },
                        other => other,
                    }
                };
                let pw = scale_pt(pw_raw, &cnt);
                let tg = scale_pt(tg_raw, &cnt);
                let mut st = make_step(
                    EffectOp::Pump {
                        toughness: Some(Box::new(tg)),
                        duration: final_dur,
                        pump_choices: Vec::new(),
                    },
                    subj,
                    span,
                );
                st.amount = Some(Box::new(pw));
                state.push_step(st, true);
                return true;
            }
        }
        if let Some((mut pw, mut tg)) = parse_pt_pair(after_gets) {
            resolve_x(&mut pw);
            resolve_x(&mut tg);
            let mut st = make_step(
                EffectOp::Pump {
                    toughness: Some(Box::new(tg)),
                    duration: dur,
                    pump_choices: Vec::new(),
                },
                subj,
                span,
            );
            st.amount = Some(Box::new(pw));
            state.push_step(st, true);
            return true;
        }
    }

    // "gains <kw/quoted ability>"
    if let Some(after_gains) = strip_prefix_word_ci(body_no_dur, "gains")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "gain"))
    {
        if let Some((and_gets_pos, sep_len)) = find_word_ci(after_gains, " and gets ")
            .map(|p| (p, " and gets ".len()))
            .or_else(|| find_word_ci(after_gains, " and get ").map(|p| (p, " and get ".len())))
        {
            let kw_raw = after_gains[..and_gets_pos].trim();
            let pt_raw = after_gains[and_gets_pos + sep_len..].trim();
            let (kw_clean, kw_dur) = parse_duration_suffix(kw_raw);
            let final_dur = dur_opt.or(kw_dur).or(Some(Duration::EndOfTurn));
            if let Some(kws) = parse_keyword_list_ids(kw_clean, ctx)
                && let Some((mut pw, mut tg)) = parse_pt_pair(pt_raw)
            {
                resolve_x(&mut pw);
                resolve_x(&mut tg);
                state.push_step(
                    make_step(
                        EffectOp::Grant {
                            keywords: kws,
                            remove_keywords: SmallVec::new(),
                            cant_have_or_gain: false,
                            duration: final_dur,
                            granted_ability_texts: Vec::new(),
                            choose_keyword_options: SmallVec::new(),
                            choose_lose_keyword_options: SmallVec::new(),
                            choose_protection_color: false,
                            remove_all_abilities: false,
                            can_attack_no_defender: false,
                            must_attack_this_turn: false,
                            must_be_blocked_this_turn: false,
                            must_block_this_turn: false,
                            must_block_self_this_turn: false,
                            cant_block_self_this_turn: false,
                            cant_be_blocked_by_opponents_creatures: false,
                            assigns_no_combat_damage_this_turn: false,
                            grant_suspend_if_missing: false,
                            exile_resolving_spell_to_linked: false,
                            grant_trigger_spell_sunburst: false,
                            pay_any_mana_for_damage: None,
                            pay_up_to_life_gained_mana_to_draw: false,
                            gambit_combat_directive: false,
                        },
                        subj.clone(),
                        span,
                    ),
                    true,
                );
                let mut p_step = make_step(
                    EffectOp::Pump {
                        toughness: Some(Box::new(tg)),
                        duration: final_dur,
                        pump_choices: Vec::new(),
                    },
                    subj,
                    span,
                );
                p_step.amount = Some(Box::new(pw));
                state.push_step(p_step, false);
                return true;
            }
        }
        let gain_dur = dur_opt.or(Some(Duration::Permanent));
        if let Some(q) = strip_outer_quotes(after_gains) {
            let q_low = q.to_ascii_lowercase();
            if dur_opt.is_none()
                && q_low.contains(
                    "would leave the battlefield, exile it instead of putting it anywhere else",
                )
            {
                state.push_step(
                    make_step(
                        EffectOp::ExileInsteadOfDying {
                            duration: Some(Duration::Permanent),
                        },
                        subj,
                        span,
                    ),
                    true,
                );
                return true;
            }
            state.compile_quoted(q, "Creature", ctx);
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: SmallVec::new(),
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: gain_dur,
                        granted_ability_texts: vec![q.to_string()],
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
        if eq_ci(after_gains, "protection from the color of your choice")
            || eq_ci(after_gains, "protection from a color of your choice")
            || eq_ci(
                after_gains,
                "protection from colorless or from the color of your choice",
            )
            || eq_ci(
                after_gains,
                "protection from colorless or from a color of your choice",
            )
        {
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: SmallVec::new(),
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: gain_dur,
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: true,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
        if eq_ci(after_gains, "protection from each color") {
            let mut kws = SmallVec::new();
            for kw in [
                "Protection from white",
                "Protection from blue",
                "Protection from black",
                "Protection from red",
                "Protection from green",
            ] {
                kws.push(ctx.interner.intern_keyword(kw));
            }
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: kws,
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: gain_dur,
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
        if eq_ci(after_gains, "sunburst")
            && matches!(&subj, Selector::EventObject)
            && state
                .trigger
                .is_some_and(|tr| matches!(tr.event, EventKind::Cast))
        {
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: SmallVec::new(),
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: gain_dur,
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: true,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
        let (gains_kw_raw, must_atk) = if let Some(l) =
            strip_suffix_word_ci(after_gains, "and attacks this combat if able")
                .or_else(|| strip_suffix_word_ci(after_gains, "and attack this combat if able"))
                .or_else(|| strip_suffix_word_ci(after_gains, "and attacks this turn if able"))
                .or_else(|| strip_suffix_word_ci(after_gains, "and attack this turn if able"))
        {
            (l, true)
        } else {
            (after_gains, false)
        };
        let (gains_kw_clean, inner_dur) = if must_atk {
            parse_duration_suffix(gains_kw_raw)
        } else {
            (gains_kw_raw, None)
        };
        let eff_gain_dur = dur_opt.or(inner_dur).or(Some(Duration::Permanent));
        let parsed_kw_or_q = if !eq_ci(gains_kw_clean, "flashback")
            && let Some(kws) = parse_keyword_list_ids(gains_kw_clean, ctx)
        {
            Some((kws, Vec::new()))
        } else {
            [" and \"", " and “"].iter().find_map(|sep| {
                let pos = find_word_ci(gains_kw_clean, sep)?;
                let kw_part = gains_kw_clean[..pos].trim();
                let q_part = gains_kw_clean[pos + 5..].trim();
                let q = strip_outer_quotes(q_part)?;
                let kws = parse_keyword_list_ids(kw_part, ctx)?;
                Some((kws, vec![q.to_string()]))
            })
        };
        if let Some((kws, granted_texts)) = parsed_kw_or_q {
            for q in &granted_texts {
                state.compile_quoted(q, "Creature", ctx);
            }
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: kws,
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: eff_gain_dur,
                        granted_ability_texts: granted_texts,
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: must_atk,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
    }

    // "loses all abilities"
    if eq_ci(body_no_dur, "loses all abilities") || eq_ci(body_no_dur, "lose all abilities") {
        state.push_step(
            make_step(
                EffectOp::Animate {
                    duration: dur,
                    add_types: CardTypeMask::empty(),
                    set_types: None,
                    remove_types: CardTypeMask::empty(),
                    add_subtypes: SmallVec::new(),
                    set_subtypes: None,
                    set_colors: None,
                    add_colors: ColorMask::empty(),
                    add_keywords: SmallVec::new(),
                    set_power: None,
                    set_toughness: None,
                    keep_existing_types: true,
                    still_a_land: false,
                    remove_all_abilities: true,
                    granted_ability_texts: Vec::new(),
                    choose_creature_type: false,
                    choose_basic_land_type: false,
                    choose_color: None,
                },
                subj,
                span,
            ),
            true,
        );
        return true;
    }

    // "loses <kws> [and can't have [or gain] <kws>]"
    if let Some(after_lose) = strip_prefix_word_ci(body_no_dur, "loses")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "lose"))
    {
        let (kw_part, cant_have_or_gain) =
            if let Some(cpos) = find_word_ci(after_lose, " and can't ") {
                let tail_c = after_lose[cpos + " and can't ".len()..].trim();
                let is_cant_kw =
                    starts_with_word_ci(tail_c, "have") || starts_with_word_ci(tail_c, "gain");
                if is_cant_kw {
                    (after_lose[..cpos].trim(), true)
                } else {
                    (after_lose, false)
                }
            } else {
                (after_lose, false)
            };
        if let Some(rm_kws) = parse_keyword_list_ids(kw_part, ctx) {
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: SmallVec::new(),
                        remove_keywords: rm_kws,
                        cant_have_or_gain,
                        duration: dur,
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
    }

    // "fights <obj>"
    if let Some(after_fights) = strip_prefix_word_ci(body_no_dur, "fights")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "fight"))
        && let Some(other) = parse_object_selector(after_fights, ZoneMask::BATTLEFIELD, ctx, state)
    {
        state.push_step(
            make_step(
                EffectOp::Fight {
                    with: Box::new(other.into_selector()),
                    excess_damage_to_mana: None,
                },
                subj,
                span,
            ),
            true,
        );
        return true;
    }

    if eq_ci(pred, "attacks that player this combat if able")
        || eq_ci(pred, "attack that player this combat if able")
    {
        let atk_player = state
            .single_player_ref()
            .unwrap_or(PlayerRef::ChosenOpponent);
        state.push_step(
            make_step(
                EffectOp::CombatRestriction {
                    spec: None,
                    duration: None,
                    choose_odd_or_even_cant_block: false,
                    must_attack_next_combat: false,
                    must_attack_player: Some(atk_player),
                    until_your_next_turn_directive: None,
                },
                subj,
                span,
            ),
            true,
        );
        return true;
    }

    if eq_ci(
        pred,
        "attacks during its controller's next combat phase if able",
    ) || eq_ci(
        pred,
        "attack during its controller's next combat phase if able",
    ) || eq_ci(
        pred,
        "attacks during their controller's next combat phase if able",
    ) || eq_ci(
        pred,
        "attack during their controller's next combat phase if able",
    ) {
        state.push_step(
            make_step(
                EffectOp::CombatRestriction {
                    spec: None,
                    duration: None,
                    choose_odd_or_even_cant_block: false,
                    must_attack_next_combat: true,
                    must_attack_player: None,
                    until_your_next_turn_directive: None,
                },
                subj,
                span,
            ),
            true,
        );
        return true;
    }

    // "can't block" / "can't be blocked" / "can't attack" / "can't attack or block"
    if let Some(after_cant) = strip_prefix_word_ci(body_no_dur, "can't") {
        let kind = if eq_ci(after_cant, "block") {
            Some(TimedCombatRestrictionKind::CantBlock)
        } else if eq_ci(after_cant, "be blocked") {
            Some(TimedCombatRestrictionKind::CantBeBlocked)
        } else if eq_ci(after_cant, "attack") {
            Some(TimedCombatRestrictionKind::CantAttack)
        } else if eq_ci(after_cant, "attack or block") {
            Some(TimedCombatRestrictionKind::CantAttackOrBlock)
        } else {
            None
        };
        if let Some(k) = kind {
            state.push_step(
                make_step(
                    EffectOp::CombatRestriction {
                        spec: Some(TimedCombatRestrictionSpec {
                            kind: k,
                            except_by: None,
                        }),
                        duration: if dur == Some(Duration::EndOfTurn) {
                            None
                        } else {
                            dur
                        },
                        choose_odd_or_even_cant_block: false,
                        must_attack_next_combat: false,
                        must_attack_player: None,
                        until_your_next_turn_directive: None,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
        if eq_ci(
            after_cant,
            "be the target of spells or abilities your opponents control",
        ) {
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: smallvec![ctx.interner.intern_keyword("hexproof")],
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: dur,
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
        if eq_ci(after_cant, "be blocked by creatures your opponents control") {
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: SmallVec::new(),
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: dur,
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: true,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
    }

    // "becomes a copy of <obj>"
    if let Some(after_copy) = strip_prefix_word_ci(body_no_dur, "becomes a copy of")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "become a copy of"))
    {
        let (target_s_raw, except_s) = if let Some(pos) = find_word_ci(after_copy, ", except ") {
            (after_copy[..pos].trim(), Some(after_copy[pos + 9..].trim()))
        } else {
            (after_copy, None)
        };
        let (target_s, inner_copy_dur) = parse_duration_suffix(target_s_raw);
        let copy_dur = dur_opt.or(inner_copy_dur).or(Some(Duration::Permanent));
        if let Some(src_obj) = parse_object_selector(target_s, ZoneMask::BATTLEFIELD, ctx, state) {
            let mut cm = CopyModificationSpec::default();
            let mut has_mod = false;
            if let Some(ex) = except_s {
                let ex_low = ex.to_ascii_lowercase();
                if ex_low.contains("name is ~") {
                    cm.keep_self_name = true;
                    has_mod = true;
                }
                if ex_low.contains("this ability") {
                    cm.keep_this_ability = true;
                    has_mod = true;
                }
                if ex_low.contains("legendary") {
                    cm.add_supertypes |= SupertypeMask::LEGENDARY;
                    has_mod = true;
                }
                for has_kw in ["it has ", "they have ", "has "] {
                    if let Some(hp) = find_word_ci(ex, has_kw) {
                        let mut kw_part = ex[hp + has_kw.len()..].trim();
                        for tail_cut in [" and this ability", ", and this ability", " this ability"]
                        {
                            if let Some(p) = strip_suffix_word_ci(kw_part, tail_cut.trim()) {
                                kw_part = p.trim_end_matches(',').trim();
                            }
                        }
                        if let Some(kws) = parse_keyword_list_ids(kw_part, ctx) {
                            cm.add_keywords.extend(kws);
                            has_mod = true;
                        }
                        break;
                    }
                }
            }
            state.push_step(
                make_step(
                    EffectOp::BecomeCopy {
                        copy_source: Box::new(src_obj.into_selector()),
                        duration: copy_dur,
                        copy_mod: if has_mod { Some(Box::new(cm)) } else { None },
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
    }

    let parse_animate_with =
        |with_s: &str, ctx: &mut ParseCtx<'_>| -> Option<(Vec<String>, SmallVec<[KeywordId; 2]>)> {
            let w = with_s.trim();
            if let Some(q) = strip_outer_quotes(w) {
                return Some((vec![q.to_string()], SmallVec::new()));
            }
            for sep in [" and \"", " and “"] {
                if let Some(pos) = find_word_ci(w, sep) {
                    let kw_part = w[..pos].trim();
                    let q_part = w[pos + 5..].trim();
                    if let Some(q) = strip_outer_quotes(q_part)
                        && let Some(kws) = parse_keyword_list_ids(kw_part, ctx)
                    {
                        return Some((vec![q.to_string()], kws));
                    }
                }
            }
            parse_keyword_list_ids(w, ctx).map(|kws| (Vec::new(), kws))
        };

    fn strip_animate_retention(s: &str) -> (&str, bool, bool) {
        let mut cur = s.trim();
        let mut keep_types = false;
        let mut keep_colors = false;
        loop {
            if let Some(r) = strip_suffix_word_ci(cur, "in addition to its other colors and types")
                .or_else(|| {
                    strip_suffix_word_ci(cur, "in addition to their other colors and types")
                })
            {
                cur = r.trim_end_matches(',').trim();
                keep_types = true;
                keep_colors = true;
            } else if let Some(r) = strip_suffix_word_ci(cur, "in addition to its other types")
                .or_else(|| strip_suffix_word_ci(cur, "in addition to their other types"))
            {
                cur = r.trim_end_matches(',').trim();
                keep_types = true;
            } else if let Some(r) = strip_suffix_word_ci(cur, "in addition to its other colors")
                .or_else(|| strip_suffix_word_ci(cur, "in addition to their other colors"))
            {
                cur = r.trim_end_matches(',').trim();
                keep_colors = true;
            } else if let Some(r) = strip_suffix_word_ci(cur, "that's still a land")
                .or_else(|| strip_suffix_word_ci(cur, "and is still a land"))
                .or_else(|| strip_suffix_word_ci(cur, "it's still a land"))
                .or_else(|| strip_suffix_word_ci(cur, "they're still lands"))
            {
                cur = r.trim_end_matches(',').trim();
                keep_types = true;
            } else {
                break;
            }
        }
        (cur, keep_types, keep_colors)
    }

    // "becomes a <P/T> <desc> creature [with <kw/quoted>]" / "is a 1/1 Spirit in addition to its other types"
    if let Some(after_bec) = strip_prefix_word_ci(body_no_dur, "becomes a")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "becomes an"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "become"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "is a"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "is an"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "are a"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "are an"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "are"))
        && let Some(first_w) = after_bec.split_whitespace().next()
        && let Some((pw, tg)) = first_w.split_once('/')
        && let Some((p_amt, t_amt)) =
            if let (Ok(p_n), Ok(t_n)) = (pw.parse::<i32>(), tg.parse::<i32>()) {
                Some((Amount::Const { n: p_n }, Amount::Const { n: t_n }))
            } else if eq_ci(pw, "x") && eq_ci(tg, "x") {
                let x_amt = state.defined_x.clone().unwrap_or(Amount::X);
                Some((x_amt.clone(), x_amt))
            } else {
                None
            }
    {
        let rest_desc = after_bec[first_w.len()..].trim();
        let (rest_desc_clean, keep_types, keep_colors) = strip_animate_retention(rest_desc);
        let (clean_desc, with_kw) = if let Some(wp) = find_word_ci(rest_desc_clean, " with ") {
            (
                rest_desc_clean[..wp].trim(),
                Some(rest_desc_clean[wp + 6..].trim()),
            )
        } else {
            (rest_desc_clean, None)
        };
        let colors = parse_color_list_str(clean_desc);
        let mut add_subtypes = SmallVec::new();
        for raw_w in clean_desc.split_whitespace() {
            if parse_color_word(raw_w).is_none()
                && !eq_ci(raw_w, "and")
                && !eq_ci(raw_w, "creature")
                && !eq_ci(raw_w, "creatures")
                && !eq_ci(raw_w, "artifact")
                && !eq_ci(raw_w, "artifacts")
                && !eq_ci(raw_w, "enchantment")
                && !eq_ci(raw_w, "enchantments")
                && !raw_w.contains('/')
            {
                let st = singular_subtype(raw_w).unwrap_or_else(|| canonical_keyword_case(raw_w));
                add_subtypes.push(ctx.interner.intern_subtype(&st));
            }
        }
        let (granted_ability_texts, kws) = with_kw
            .and_then(|kw| parse_animate_with(kw, ctx))
            .unwrap_or_default();
        for q in &granted_ability_texts {
            state.compile_quoted(q, "Creature", ctx);
        }
        let mut type_mask = CardTypeMask::CREATURE;
        if contains_word_ci(clean_desc, "artifact") {
            type_mask |= CardTypeMask::ARTIFACT;
        }
        if contains_word_ci(clean_desc, "enchantment") {
            type_mask |= CardTypeMask::ENCHANTMENT;
        }
        let is_artifact_creature = contains_word_ci(clean_desc, "artifact creature")
            || contains_word_ci(clean_desc, "artifact creatures");
        let add_types_flag = keep_types || is_artifact_creature;
        let eff_keep_existing = keep_types || (is_artifact_creature && add_subtypes.is_empty());
        state.push_step(
            make_step(
                EffectOp::Animate {
                    duration: dur_opt.or(Some(Duration::Permanent)),
                    add_types: if add_types_flag {
                        type_mask
                    } else {
                        CardTypeMask::empty()
                    },
                    set_types: if add_types_flag {
                        None
                    } else {
                        Some(type_mask)
                    },
                    remove_types: CardTypeMask::empty(),
                    add_subtypes: if keep_types {
                        add_subtypes.clone()
                    } else {
                        SmallVec::new()
                    },
                    set_subtypes: if eff_keep_existing {
                        None
                    } else {
                        Some(add_subtypes)
                    },
                    set_colors: if !keep_colors && !colors.is_empty() {
                        Some(colors)
                    } else {
                        None
                    },
                    add_colors: if keep_colors {
                        colors
                    } else {
                        ColorMask::empty()
                    },
                    add_keywords: kws,
                    set_power: Some(Box::new(p_amt)),
                    set_toughness: Some(Box::new(t_amt)),
                    keep_existing_types: eff_keep_existing,
                    still_a_land: false,
                    remove_all_abilities: false,
                    granted_ability_texts,
                    choose_creature_type: false,
                    choose_basic_land_type: false,
                    choose_color: None,
                },
                subj,
                span,
            ),
            true,
        );
        return true;
    }

    // "(has|have) base power and toughness <P>/<T> [and gains <kws>]" (*Jolrael, Mwonvuli Recluse*, *Flayer of Loyalties*)
    if let Some(pt_raw) = strip_prefix_word_ci(body_no_dur, "have base power and toughness")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "has base power and toughness"))
    {
        let (pt_only, kws_opt) = if let Some(gp) = find_word_ci(pt_raw, " and gains ") {
            (
                pt_raw[..gp].trim(),
                Some(pt_raw[gp + " and gains ".len()..].trim()),
            )
        } else if let Some(gp) = find_word_ci(pt_raw, " and gain ") {
            (
                pt_raw[..gp].trim(),
                Some(pt_raw[gp + " and gain ".len()..].trim()),
            )
        } else if let Some(gp) = find_word_ci(pt_raw, " and has ") {
            (
                pt_raw[..gp].trim(),
                Some(pt_raw[gp + " and has ".len()..].trim()),
            )
        } else if let Some(gp) = find_word_ci(pt_raw, " and have ") {
            (
                pt_raw[..gp].trim(),
                Some(pt_raw[gp + " and have ".len()..].trim()),
            )
        } else {
            (pt_raw.trim(), None)
        };
        let add_keywords = match kws_opt {
            Some(ks) => parse_keyword_list_ids(ks, ctx),
            None => Some(SmallVec::new()),
        };
        if let Some(add_keywords) = add_keywords
            && let Some((pw, tg)) = pt_only.split_once('/')
        {
            let p_opt = if eq_ci(pw, "x") {
                Some(where_x_amt.clone().unwrap_or(Amount::X))
            } else {
                pw.parse::<i32>().ok().map(|n| Amount::Const { n })
            };
            let t_opt = if eq_ci(tg, "x") {
                Some(where_x_amt.clone().unwrap_or(Amount::X))
            } else {
                tg.parse::<i32>().ok().map(|n| Amount::Const { n })
            };
            if let (Some(p_amt), Some(t_amt)) = (p_opt, t_opt) {
                state.push_step(
                    make_step(
                        EffectOp::Animate {
                            duration: dur_opt.or(Some(Duration::Permanent)),
                            add_types: CardTypeMask::empty(),
                            set_types: None,
                            remove_types: CardTypeMask::empty(),
                            add_subtypes: SmallVec::new(),
                            set_subtypes: None,
                            set_colors: None,
                            add_colors: ColorMask::empty(),
                            add_keywords,
                            set_power: Some(Box::new(p_amt)),
                            set_toughness: Some(Box::new(t_amt)),
                            keep_existing_types: true,
                            still_a_land: false,
                            remove_all_abilities: false,
                            granted_ability_texts: Vec::new(),
                            choose_creature_type: false,
                            choose_basic_land_type: false,
                            choose_color: None,
                        },
                        subj,
                        span,
                    ),
                    true,
                );
                return true;
            }
        }
    }

    // "becomes a/an <desc> [artifact|land|enchantment|creature] [with \"...\"|with base power and toughness P/T] [in addition to ...] [and loses all other card types [and abilities]]"
    if let Some((is_is_verb, after_bec)) = strip_prefix_word_ci(body_no_dur, "becomes a")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "becomes an"))
        .map(|r| (false, r))
        .or_else(|| {
            strip_prefix_word_ci(body_no_dur, "is a")
                .or_else(|| strip_prefix_word_ci(body_no_dur, "is an"))
                .or_else(|| strip_prefix_word_ci(body_no_dur, "are a"))
                .or_else(|| strip_prefix_word_ci(body_no_dur, "are an"))
                .or_else(|| strip_prefix_word_ci(body_no_dur, "are"))
                .map(|r| (true, r))
        })
    {
        let mut work = after_bec.trim();
        let mut loses_other_types = false;
        let mut remove_all_abilities = false;
        if let Some(r) = strip_suffix_word_ci(work, "and loses all other card types and abilities")
        {
            work = r;
            loses_other_types = true;
            remove_all_abilities = true;
        } else if let Some(r) = strip_suffix_word_ci(work, "and loses all other card types") {
            work = r;
            loses_other_types = true;
        } else if let Some(r) = strip_suffix_word_ci(work, "and loses all abilities") {
            work = r;
            remove_all_abilities = true;
        }
        let (work_clean, in_addition, keep_colors) = strip_animate_retention(work);
        if is_is_verb && !in_addition {
            return false;
        }
        work = work_clean;
        let mut set_power_opt: Option<Box<Amount>> = None;
        let mut set_toughness_opt: Option<Box<Amount>> = None;
        let (desc_raw, granted_ability_texts, add_keywords) =
            if let Some(wp) = find_word_ci(work, " with ") {
                let left = work[..wp].trim();
                let mut right = work[wp + 6..].trim();
                if let Some(after_bpt) = strip_prefix_word_ci(right, "base power and toughness") {
                    let mut ws = after_bpt.split_whitespace();
                    if let Some(pt_tok) = ws.next()
                        && let Some((pw, tg)) = pt_tok.split_once('/')
                        && let (Ok(pn), Ok(tn)) = (pw.parse::<i32>(), tg.parse::<i32>())
                    {
                        set_power_opt = Some(Box::new(Amount::Const { n: pn }));
                        set_toughness_opt = Some(Box::new(Amount::Const { n: tn }));
                        let tail_kw = after_bpt[pt_tok.len()..].trim();
                        let after_and = strip_prefix_word_ci(tail_kw, "and")
                            .unwrap_or(tail_kw)
                            .trim();
                        right = strip_prefix_word_ci(after_and, "gains")
                            .or_else(|| strip_prefix_word_ci(after_and, "gain"))
                            .or_else(|| strip_prefix_word_ci(after_and, "has"))
                            .or_else(|| strip_prefix_word_ci(after_and, "have"))
                            .unwrap_or(after_and)
                            .trim();
                    }
                }
                if right.is_empty() {
                    (left, Vec::new(), SmallVec::new())
                } else if let Some((qs, kws)) = parse_animate_with(right, ctx) {
                    (left, qs, kws)
                } else {
                    (work, Vec::new(), SmallVec::new())
                }
            } else {
                (work, Vec::new(), SmallVec::new())
            };
        let mut type_mask = CardTypeMask::empty();
        if contains_word_ci(desc_raw, "artifact") {
            type_mask |= CardTypeMask::ARTIFACT;
        }
        if contains_word_ci(desc_raw, "enchantment") {
            type_mask |= CardTypeMask::ENCHANTMENT;
        }
        if contains_word_ci(desc_raw, "creature") {
            type_mask |= CardTypeMask::CREATURE;
        }
        if contains_word_ci(desc_raw, "land") {
            type_mask |= CardTypeMask::LAND;
        }
        if contains_word_ci(desc_raw, "planeswalker") {
            type_mask |= CardTypeMask::PLANESWALKER;
        }
        let colors = parse_color_list_str(desc_raw);
        let mut subs = SmallVec::new();
        for raw_w in desc_raw.split_whitespace() {
            if parse_color_word(raw_w).is_none()
                && !eq_ci(raw_w, "and")
                && !eq_ci(raw_w, "artifact")
                && !eq_ci(raw_w, "enchantment")
                && !eq_ci(raw_w, "creature")
                && !eq_ci(raw_w, "land")
                && !eq_ci(raw_w, "planeswalker")
                && !eq_ci(raw_w, "token")
                && !raw_w.contains('/')
                && raw_w.starts_with(|c: char| c.is_ascii_uppercase())
            {
                let st = singular_subtype(raw_w).unwrap_or_else(|| canonical_keyword_case(raw_w));
                subs.push(ctx.interner.intern_subtype(&st));
            }
        }
        if type_mask.is_empty() && set_power_opt.is_some() && !subs.is_empty() {
            type_mask |= CardTypeMask::CREATURE;
        }
        if !type_mask.is_empty() || (in_addition && (!subs.is_empty() || !colors.is_empty())) {
            for q in &granted_ability_texts {
                state.compile_quoted(q, "Artifact", ctx);
            }
            let is_artifact_creature = !loses_other_types
                && (contains_word_ci(desc_raw, "artifact creature")
                    || contains_word_ci(desc_raw, "artifact creatures"));
            let keep_types = in_addition && !loses_other_types;
            let add_types_flag = keep_types || is_artifact_creature;
            let eff_keep_existing = keep_types || (is_artifact_creature && subs.is_empty());
            state.push_step(
                make_step(
                    EffectOp::Animate {
                        duration: dur_opt.or(Some(Duration::Permanent)),
                        add_types: if add_types_flag {
                            type_mask
                        } else {
                            CardTypeMask::empty()
                        },
                        set_types: if add_types_flag {
                            None
                        } else {
                            Some(type_mask)
                        },
                        remove_types: CardTypeMask::empty(),
                        add_subtypes: if keep_types {
                            subs.clone()
                        } else {
                            SmallVec::new()
                        },
                        set_subtypes: if eff_keep_existing || subs.is_empty() {
                            None
                        } else {
                            Some(subs)
                        },
                        set_colors: if !keep_colors && !colors.is_empty() {
                            Some(colors)
                        } else {
                            None
                        },
                        add_colors: if keep_colors {
                            colors
                        } else {
                            ColorMask::empty()
                        },
                        add_keywords,
                        set_power: set_power_opt,
                        set_toughness: set_toughness_opt,
                        keep_existing_types: eff_keep_existing,
                        still_a_land: false,
                        remove_all_abilities,
                        granted_ability_texts,
                        choose_creature_type: false,
                        choose_basic_land_type: false,
                        choose_color: None,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
    }

    // "(isn't|aren't) [a|an] <type(s)>" (*Weeping Angel*)
    if let Some(after_not) = strip_prefix_word_ci(body_no_dur, "isn't a")
        .or_else(|| strip_prefix_word_ci(body_no_dur, "isn't an"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "isn't"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "is not a"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "is not an"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "aren't"))
        .or_else(|| strip_prefix_word_ci(body_no_dur, "are not"))
    {
        let mask = if eq_ci(after_not, "creature") || eq_ci(after_not, "creatures") {
            CardTypeMask::CREATURE
        } else if eq_ci(after_not, "artifact") || eq_ci(after_not, "artifacts") {
            CardTypeMask::ARTIFACT
        } else if eq_ci(after_not, "enchantment") || eq_ci(after_not, "enchantments") {
            CardTypeMask::ENCHANTMENT
        } else if eq_ci(after_not, "land") || eq_ci(after_not, "lands") {
            CardTypeMask::LAND
        } else {
            CardTypeMask::empty()
        };
        if !mask.is_empty() {
            state.push_step(
                make_step(
                    EffectOp::Animate {
                        duration: dur_opt.or(Some(Duration::Permanent)),
                        add_types: CardTypeMask::empty(),
                        set_types: None,
                        remove_types: mask,
                        add_subtypes: SmallVec::new(),
                        set_subtypes: None,
                        set_colors: None,
                        add_colors: ColorMask::empty(),
                        add_keywords: SmallVec::new(),
                        set_power: None,
                        set_toughness: None,
                        keep_existing_types: true,
                        still_a_land: false,
                        remove_all_abilities: false,
                        granted_ability_texts: Vec::new(),
                        choose_creature_type: false,
                        choose_basic_land_type: false,
                        choose_color: None,
                    },
                    subj,
                    span,
                ),
                true,
            );
            return true;
        }
    }

    false
}

fn parse_player_or_object_subject_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let (t_freeze, freeze_dur) = if let Some(p) =
        strip_suffix_word_ci(t, "for as long as ~ remains tapped")
            .or_else(|| strip_suffix_word_ci(t, "for as long as this artifact remains tapped"))
            .or_else(|| strip_suffix_word_ci(t, "for as long as this creature remains tapped"))
            .or_else(|| strip_suffix_word_ci(t, "for as long as this permanent remains tapped"))
    {
        (p.trim(), Some(Duration::ForAsLongAsSelfRemainsTapped))
    } else if let Some(p) = strip_suffix_word_ci(t, "for as long as you control ~")
        .or_else(|| strip_suffix_word_ci(t, "for as long as ~ remains on the battlefield"))
    {
        (p.trim(), Some(Duration::ForAsLongAsYouControlSelf))
    } else {
        (t, None)
    };
    let tb = t_freeze.as_bytes();
    if tb.len() >= 10
        && (tb[tb.len() - 4..].eq_ignore_ascii_case(b"step")
            || tb[tb.len() - 5..].eq_ignore_ascii_case(b"steps"))
    {
        let subj_opt = strip_suffix_word_ci(
            t_freeze,
            "doesn't untap during its controller's next untap step",
        )
        .or_else(|| {
            strip_suffix_word_ci(
                t_freeze,
                "don't untap during their controllers' next untap steps",
            )
        })
        .or_else(|| {
            strip_suffix_word_ci(
                t_freeze,
                "don't untap during their controller's next untap step",
            )
        })
        .or_else(|| strip_suffix_word_ci(t_freeze, "doesn't untap during your next untap step"))
        .or_else(|| {
            if freeze_dur.is_some() {
                strip_suffix_word_ci(t_freeze, "doesn't untap during its controller's untap step")
                    .or_else(|| {
                        strip_suffix_word_ci(
                            t_freeze,
                            "don't untap during their controllers' untap steps",
                        )
                    })
                    .or_else(|| {
                        strip_suffix_word_ci(
                            t_freeze,
                            "don't untap during their controller's untap step",
                        )
                    })
                    .or_else(|| {
                        strip_suffix_word_ci(t_freeze, "doesn't untap during your untap step")
                    })
            } else {
                None
            }
        });
        if let Some(subj_raw) = subj_opt
            && let Some(obj) =
                parse_object_selector(subj_raw.trim(), ZoneMask::BATTLEFIELD, ctx, state)
        {
            state.push_step(
                make_step(
                    EffectOp::FreezeUntap {
                        duration: freeze_dur,
                    },
                    obj.into_selector(),
                    span,
                ),
                false,
            );
            return true;
        }
    }
    if let Some(after_you) = strip_prefix_word_ci(t, "your life total becomes")
        && let Some(amt) = parse_amount_str(after_you, ctx, state)
    {
        let mut st = make_step(
            EffectOp::GainLife {
                set_life_total: true,
            },
            you_sel(),
            span,
        );
        st.amount = Some(Box::new(amt));
        state.push_step(st, false);
        return true;
    }
    if let Some(pos) = find_word_ci(t, "'s life total becomes ") {
        let player_s = t[..pos].trim();
        let amt_s = t[pos + "'s life total becomes ".len()..].trim();
        let mark = state.mark(ctx);
        if let Some(psel) = parse_player_selector(player_s, ctx, state)
            && let Some(amt) = parse_amount_str(amt_s, ctx, state)
        {
            let subj = match psel {
                Selector::Target { index } => Selector::PlayerRef {
                    player: PlayerRef::Target { index },
                },
                other => other,
            };
            let mut st = make_step(
                EffectOp::GainLife {
                    set_life_total: true,
                },
                subj,
                span,
            );
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
        state.rollback(mark, ctx);
    }

    if let Some(after_you_and) = strip_prefix_word_ci(t, "you and")
        && let Some(each_pos) = find_word_ci(after_you_and, " each ")
    {
        let other_p_s = after_you_and[..each_pos].trim();
        let pred_s = after_you_and[each_pos + 6..].trim();
        if !other_p_s.is_empty() && !pred_s.is_empty() {
            let mark = state.mark(ctx);
            if let Some(other_psel) = parse_player_selector(other_p_s, ctx, state) {
                let other_actor = match &other_psel {
                    Selector::Target { index } => Some(PlayerRef::Target { index: *index }),
                    Selector::PlayerRef { player } => Some(player.clone()),
                    _ => None,
                };
                let before = state.steps.len();
                if parse_player_predicate(you_sel(), None, pred_s, span, ctx, state) {
                    let you_steps = state.steps.split_off(before);
                    if parse_player_predicate(other_psel, other_actor, pred_s, span, ctx, state) {
                        let other_steps = state.steps.split_off(before);
                        state.steps.extend(you_steps);
                        state.steps.extend(other_steps);
                        return true;
                    }
                    state.steps.extend(you_steps);
                }
            }
            state.rollback(mark, ctx);
        }
    }

    if let Some(after_who) = strip_prefix_word_ci(t, "each opponent who doesn't control")
        && let Some(loses_pos) = find_word_ci(after_who, " loses the game")
        && after_who[loses_pos + " loses the game".len()..]
            .trim()
            .is_empty()
    {
        let f_str = after_who[..loses_pos].trim();
        let toks = tokenize(f_str, 0);
        let cp = ctx.interner.checkpoint();
        if !toks.is_empty()
            && let Some((f, used)) = parse_object_filter(
                &toks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_plural_and_disjunction: true,
                    ..Default::default()
                },
                state,
            )
            && used == toks.len()
        {
            let cond = Condition::Not {
                of: Box::new(Condition::PlayerControlsFilter {
                    player: PlayerRef::EachLoopPlayer,
                    filter: Box::new(f),
                }),
            };
            let inner = make_step(
                EffectOp::Lose {
                    condition: Some(Box::new(cond)),
                },
                Selector::PlayerRef {
                    player: PlayerRef::EachLoopPlayer,
                },
                span,
            );
            state.push_step(
                make_step(
                    EffectOp::ForEachPlayerLoop {
                        players: LoopPlayersKind::EachOpponent,
                        steps: vec![inner],
                        choose_random_opponent: false,
                        exclude_attacked_last_combat: false,
                        exclude_event_player: false,
                        choose_object_to_bind: None,
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }
        ctx.interner.rollback(cp);
    }

    for (pref, loop_kind) in [
        ("each player who controls", LoopPlayersKind::EachPlayer),
        ("each opponent who controls", LoopPlayersKind::EachOpponent),
    ] {
        if let Some(after_who) = strip_prefix_word_ci(t, pref) {
            let clean_who = strip_prefix_word_ci(after_who, "a")
                .or_else(|| strip_prefix_word_ci(after_who, "an"))
                .unwrap_or(after_who);
            let toks = tokenize(clean_who, 0);
            let cp = ctx.interner.checkpoint();
            if !toks.is_empty()
                && let Some((f, used)) = parse_object_filter(
                    &toks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::empty(),
                        allow_plural_and_disjunction: true,
                        ..Default::default()
                    },
                    state,
                )
                && used > 0
                && used < toks.len()
            {
                let pred_s = clean_who[toks[used].span.start as usize..].trim();
                let initial_targets_len = state.targets.len();
                let mut sub_state =
                    ParserState::new(state.context, state.trigger, state.quoted_compiler);
                sub_state.is_each_loop = true;
                sub_state.targets = state.targets.clone();
                sub_state.last_object = state.last_object.clone();
                sub_state.last_player = Some(Selector::PlayerRef {
                    player: PlayerRef::EachLoopPlayer,
                });
                sub_state.defined_x = state.defined_x.clone();
                sub_state.bind_counter = state.bind_counter;
                let loop_subj = Selector::PlayerRef {
                    player: PlayerRef::EachLoopPlayer,
                };
                if parse_player_predicate(
                    loop_subj,
                    Some(PlayerRef::EachLoopPlayer),
                    pred_s,
                    span,
                    ctx,
                    &mut sub_state,
                ) && !sub_state.steps.is_empty()
                {
                    let cond = Condition::PlayerControlsFilter {
                        player: PlayerRef::EachLoopPlayer,
                        filter: Box::new(f),
                    };
                    let mut inner_steps = sub_state.steps;
                    if inner_steps.len() == 1
                        && let EffectOp::ForEachPlayerLoop { steps, .. } = &mut inner_steps[0].op
                    {
                        inner_steps = std::mem::take(steps);
                    }
                    for st in &mut inner_steps {
                        attach_gate_condition(&mut st.gate, cond.clone());
                    }
                    if sub_state.targets.len() > initial_targets_len {
                        state
                            .targets
                            .extend(sub_state.targets.drain(initial_targets_len..));
                    }
                    state.bind_counter = sub_state.bind_counter;
                    state.push_step(
                        make_step(
                            EffectOp::ForEachPlayerLoop {
                                players: loop_kind,
                                steps: inner_steps,
                                choose_random_opponent: false,
                                exclude_attacked_last_combat: false,
                                exclude_event_player: false,
                                choose_object_to_bind: None,
                            },
                            Selector::None,
                            span,
                        ),
                        false,
                    );
                    return true;
                }
            }
            ctx.interner.rollback(cp);
        }
    }

    for (pref, loop_kind) in [
        (
            "each opponent dealt combat damage this game by a creature named ~",
            LoopPlayersKind::EachOpponent,
        ),
        (
            "each opponent dealt combat damage this game by ~",
            LoopPlayersKind::EachOpponent,
        ),
    ] {
        if let Some(pred_s) = strip_prefix_word_ci(t, pref)
            && !pred_s.is_empty()
        {
            let mark = state.mark(ctx);
            let initial_targets_len = state.targets.len();
            let mut sub_state =
                ParserState::new(state.context, state.trigger, state.quoted_compiler);
            sub_state.is_each_loop = true;
            sub_state.targets = state.targets.clone();
            sub_state.last_object = state.last_object.clone();
            sub_state.last_player = Some(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            });
            sub_state.defined_x = state.defined_x.clone();
            sub_state.bind_counter = state.bind_counter;
            let loop_subj = Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            };
            if parse_player_predicate(
                loop_subj,
                Some(PlayerRef::EachLoopPlayer),
                pred_s,
                span,
                ctx,
                &mut sub_state,
            ) && !sub_state.steps.is_empty()
            {
                let cond = Condition::WasDealtCombatDamageBySelfNameThisGame {
                    player: PlayerRef::EachLoopPlayer,
                };
                let mut inner_steps = sub_state.steps;
                if inner_steps.len() == 1
                    && let EffectOp::ForEachPlayerLoop { steps, .. } = &mut inner_steps[0].op
                {
                    inner_steps = std::mem::take(steps);
                }
                for st in &mut inner_steps {
                    attach_gate_condition(&mut st.gate, cond.clone());
                }
                if sub_state.targets.len() > initial_targets_len {
                    state
                        .targets
                        .extend(sub_state.targets.drain(initial_targets_len..));
                }
                state.bind_counter = sub_state.bind_counter;
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: loop_kind,
                            steps: inner_steps,
                            choose_random_opponent: false,
                            exclude_attacked_last_combat: false,
                            exclude_event_player: false,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    for (pref, loop_kind, merge_if_prev_optional) in [
        (
            "each player who drew a card this way",
            LoopPlayersKind::EachPlayer,
            true,
        ),
        (
            "each opponent who drew a card this way",
            LoopPlayersKind::EachOpponent,
            true,
        ),
        (
            "each player who discarded a card this way",
            LoopPlayersKind::EachPlayer,
            false,
        ),
        (
            "each opponent who discarded a card this way",
            LoopPlayersKind::EachOpponent,
            false,
        ),
    ] {
        if let Some(pred_s) = strip_prefix_word_ci(t, pref)
            && !pred_s.is_empty()
        {
            let mark = state.mark(ctx);
            let initial_targets_len = state.targets.len();
            let mut sub_state =
                ParserState::new(state.context, state.trigger, state.quoted_compiler);
            sub_state.is_each_loop = true;
            sub_state.targets = state.targets.clone();
            sub_state.last_object = state.last_object.clone();
            sub_state.last_player = Some(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            });
            sub_state.defined_x = state.defined_x.clone();
            sub_state.bind_counter = state.bind_counter;
            let loop_subj = Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            };
            if parse_player_predicate(
                loop_subj,
                Some(PlayerRef::EachLoopPlayer),
                pred_s,
                span,
                ctx,
                &mut sub_state,
            ) && !sub_state.steps.is_empty()
            {
                let mut inner_steps = sub_state.steps;
                if inner_steps.len() == 1
                    && let EffectOp::ForEachPlayerLoop { steps, .. } = &mut inner_steps[0].op
                {
                    inner_steps = std::mem::take(steps);
                }
                if sub_state.targets.len() > initial_targets_len {
                    state
                        .targets
                        .extend(sub_state.targets.drain(initial_targets_len..));
                }
                state.bind_counter = sub_state.bind_counter;
                if merge_if_prev_optional
                    && let Some(last) = state.steps.last_mut()
                    && let EffectOp::ForEachPlayerLoop { players, steps, .. } = &mut last.op
                    && *players == loop_kind
                    && !steps.is_empty()
                    && steps[0].optional.is_some()
                {
                    for st in &mut inner_steps {
                        if st.gate.is_none() {
                            st.gate = Some(StepGate::IfPrecedingAccepted { step_index: 0 });
                        }
                    }
                    steps.extend(inner_steps);
                    return true;
                }
                for st in &mut inner_steps {
                    attach_gate_condition(&mut st.gate, Condition::DidLastOptionalStep);
                }
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: loop_kind,
                            steps: inner_steps,
                            choose_random_opponent: false,
                            exclude_attacked_last_combat: false,
                            exclude_event_player: false,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    for (pref, loop_kind, expected_rel) in [
        (
            "each player who didn't discard a nonland card this way",
            LoopPlayersKind::EachPlayer,
            PlayerRelation::EachPlayer,
        ),
        (
            "each opponent who didn't discard a nonland card this way",
            LoopPlayersKind::EachOpponent,
            PlayerRelation::EachOpponent,
        ),
    ] {
        if let Some(pred_s) = strip_prefix_word_ci(t, pref)
            && !pred_s.is_empty()
        {
            let mark = state.mark(ctx);
            let initial_targets_len = state.targets.len();
            let mut sub_state =
                ParserState::new(state.context, state.trigger, state.quoted_compiler);
            sub_state.is_each_loop = true;
            sub_state.targets = state.targets.clone();
            sub_state.last_object = state.last_object.clone();
            sub_state.last_player = Some(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            });
            sub_state.defined_x = state.defined_x.clone();
            sub_state.bind_counter = state.bind_counter;
            let loop_subj = Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            };
            if parse_player_predicate(
                loop_subj,
                Some(PlayerRef::EachLoopPlayer),
                pred_s,
                span,
                ctx,
                &mut sub_state,
            ) && !sub_state.steps.is_empty()
            {
                let mut inner_steps = sub_state.steps;
                if inner_steps.len() == 1
                    && let EffectOp::ForEachPlayerLoop { steps, .. } = &mut inner_steps[0].op
                {
                    inner_steps = std::mem::take(steps);
                }
                for st in &mut inner_steps {
                    attach_gate_condition(
                        &mut st.gate,
                        Condition::PlayerDidntDiscardNonlandThisWay,
                    );
                }
                if sub_state.targets.len() > initial_targets_len {
                    state
                        .targets
                        .extend(sub_state.targets.drain(initial_targets_len..));
                }
                state.bind_counter = sub_state.bind_counter;
                if let Some(last) = state.steps.last_mut()
                    && let EffectOp::ForEachPlayerLoop { players, steps, .. } = &mut last.op
                    && *players == loop_kind
                {
                    steps.extend(inner_steps);
                    return true;
                }
                if let Some(mut prev_disc) = state.steps.pop() {
                    if let EffectOp::Discard { .. } = prev_disc.op
                        && matches!(
                            &prev_disc.subject,
                            Selector::Player { filter } if filter.relation == expected_rel
                        )
                    {
                        prev_disc.subject = Selector::PlayerRef {
                            player: PlayerRef::EachLoopPlayer,
                        };
                        let mut loop_steps = vec![prev_disc];
                        loop_steps.extend(inner_steps);
                        state.push_step(
                            make_step(
                                EffectOp::ForEachPlayerLoop {
                                    players: loop_kind,
                                    steps: loop_steps,
                                    choose_random_opponent: false,
                                    exclude_attacked_last_combat: false,
                                    exclude_event_player: false,
                                    choose_object_to_bind: None,
                                },
                                Selector::None,
                                span,
                            ),
                            false,
                        );
                        return true;
                    }
                    state.steps.push(prev_disc);
                }
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: loop_kind,
                            steps: inner_steps,
                            choose_random_opponent: false,
                            exclude_attacked_last_combat: false,
                            exclude_event_player: false,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    for (pref, loop_kind) in [
        (
            "each player who lost life this turn",
            LoopPlayersKind::EachPlayer,
        ),
        (
            "each opponent who lost life this turn",
            LoopPlayersKind::EachOpponent,
        ),
    ] {
        if let Some(pred_s) = strip_prefix_word_ci(t, pref)
            && !pred_s.is_empty()
        {
            let mark = state.mark(ctx);
            let initial_targets_len = state.targets.len();
            let mut sub_state =
                ParserState::new(state.context, state.trigger, state.quoted_compiler);
            sub_state.is_each_loop = true;
            sub_state.targets = state.targets.clone();
            sub_state.last_object = state.last_object.clone();
            sub_state.last_player = Some(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            });
            sub_state.defined_x = state.defined_x.clone();
            sub_state.bind_counter = state.bind_counter;
            let loop_subj = Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            };
            if parse_player_predicate(
                loop_subj,
                Some(PlayerRef::EachLoopPlayer),
                pred_s,
                span,
                ctx,
                &mut sub_state,
            ) && !sub_state.steps.is_empty()
            {
                let cond = Condition::PlayerLostLifeThisTurn {
                    player: PlayerRef::EachLoopPlayer,
                };
                let mut inner_steps = sub_state.steps;
                if inner_steps.len() == 1
                    && let EffectOp::ForEachPlayerLoop { steps, .. } = &mut inner_steps[0].op
                {
                    inner_steps = std::mem::take(steps);
                }
                for st in &mut inner_steps {
                    attach_gate_condition(&mut st.gate, cond.clone());
                }
                if sub_state.targets.len() > initial_targets_len {
                    state
                        .targets
                        .extend(sub_state.targets.drain(initial_targets_len..));
                }
                state.bind_counter = sub_state.bind_counter;
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: loop_kind,
                            steps: inner_steps,
                            choose_random_opponent: false,
                            exclude_attacked_last_combat: false,
                            exclude_event_player: false,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    if let Some((after_each, def_kind)) = strip_prefix_word_ci(t, "those players each")
        .map(|b| (b, LoopPlayersKind::EachPlayer))
        .or_else(|| {
            strip_prefix_word_ci(t, "those opponents each")
                .map(|b| (b, LoopPlayersKind::EachOpponent))
        })
    {
        let loop_kind = match &state.last_player {
            Some(Selector::Player { filter })
                if filter.relation == PlayerRelation::EachOpponent =>
            {
                LoopPlayersKind::EachOpponent
            }
            Some(Selector::Player { filter }) if filter.relation == PlayerRelation::EachPlayer => {
                LoopPlayersKind::EachPlayer
            }
            _ => def_kind,
        };
        let mark = state.mark(ctx);
        let initial_targets_len = state.targets.len();
        let mut sub_state = ParserState::new(state.context, state.trigger, state.quoted_compiler);
        sub_state.is_each_loop = true;
        sub_state.targets = state.targets.clone();
        sub_state.last_object = state.last_object.clone();
        sub_state.last_player = Some(Selector::PlayerRef {
            player: PlayerRef::EachLoopPlayer,
        });
        sub_state.defined_x = state.defined_x.clone();
        sub_state.bind_counter = state.bind_counter;
        let loop_subj = Selector::PlayerRef {
            player: PlayerRef::EachLoopPlayer,
        };
        if parse_player_predicate(
            loop_subj,
            Some(PlayerRef::EachLoopPlayer),
            after_each,
            span,
            ctx,
            &mut sub_state,
        ) && !sub_state.steps.is_empty()
        {
            if sub_state.targets.len() > initial_targets_len {
                state
                    .targets
                    .extend(sub_state.targets.drain(initial_targets_len..));
            }
            state.bind_counter = sub_state.bind_counter;
            state.push_step(
                make_step(
                    EffectOp::ForEachPlayerLoop {
                        players: loop_kind,
                        steps: sub_state.steps,
                        choose_random_opponent: false,
                        exclude_attacked_last_combat: false,
                        exclude_event_player: false,
                        choose_object_to_bind: None,
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }

    // Player prefixes: "you ", "each player ", "each opponent ", "target player ", "target opponent ", "that player ", "defending player ", "they "
    let first_pw = t.split_whitespace().next().unwrap_or("");
    let may_match_player_prefix = eq_ci(first_pw, "you")
        || eq_ci(first_pw, "each")
        || eq_ci(first_pw, "two")
        || eq_ci(first_pw, "three")
        || eq_ci(first_pw, "up")
        || eq_ci(first_pw, "target")
        || eq_ci(first_pw, "any")
        || eq_ci(first_pw, "the")
        || eq_ci(first_pw, "that")
        || eq_ci(first_pw, "defending")
        || eq_ci(first_pw, "they")
        || eq_ci(first_pw, "its")
        || eq_ci(first_pw, "their");
    let player_prefixes: &[&str] = if !may_match_player_prefix {
        &[]
    } else if eq_ci(first_pw, "you") {
        &["you"]
    } else {
        &[
            "each player",
            "each opponent",
            "each of your opponents",
            "each other player",
            "two target players",
            "three target players",
            "two target opponents",
            "three target opponents",
            "up to one target player",
            "up to one target opponent",
            "up to two target players",
            "up to two target opponents",
            "target player",
            "target opponent",
            "any number of target players",
            "any number of target opponents",
            "the chosen player",
            "the chosen opponent",
            "that player or that planeswalker's controller",
            "its controller or the controller of that planeswalker",
            "that player",
            "that opponent",
            "defending player",
            "they",
            "its controller",
            "their controller",
            "that creature's controller",
            "that permanent's controller",
            "that artifact's controller",
            "that enchantment's controller",
            "that land's controller",
            "that card's controller",
            "that spell's controller",
            "its owner",
            "their owner",
            "that creature's owner",
            "that permanent's owner",
            "that card's owner",
            "the player to your right",
            "the exiled card's owner",
        ]
    };
    if let Some(after_ex) = strip_prefix_word_ci(t, "each player exiles")
        && let Some(sac_pos) = find_word_ci(after_ex, ", then sacrifices ")
        && let ex_part = after_ex[..sac_pos].trim()
        && let after_sac = after_ex[sac_pos + ", then sacrifices ".len()..].trim()
        && let Some(put_pos) = find_word_ci(after_sac, ", then puts ")
        && let sac_part = after_sac[..put_pos].trim()
        && let put_part = after_sac[put_pos + ", then puts ".len()..].trim()
        && let Some(ex_obj_s) = strip_suffix_word_ci(ex_part, "from their graveyard")
        && let Some(sac_obj_s) = strip_suffix_word_ci(sac_part, "they control")
        && eq_ci(
            put_part,
            "all cards they exiled this way onto the battlefield",
        )
    {
        let ex_clean = strip_prefix_word_ci(ex_obj_s, "all").unwrap_or(ex_obj_s);
        let sac_clean = strip_prefix_word_ci(sac_obj_s, "all").unwrap_or(sac_obj_s);
        let mark_ld = state.mark(ctx);
        if let Some(ParsedObj::All(ex_f)) =
            parse_object_selector(ex_clean, ZoneMask::GRAVEYARD, ctx, state)
            && let Some(ParsedObj::All(mut sac_f)) =
                parse_object_selector(sac_clean, ZoneMask::BATTLEFIELD, ctx, state)
        {
            if sac_f.controller.is_none() {
                sac_f.controller = Some(RelativeControl::Any);
            }
            let bname = state.alloc_bind_name("exiled");
            let mut ex_st = make_step(
                EffectOp::Exile {
                    select: SelectionMod::default(),
                    duration: None,
                    until_source_leaves: false,
                    until_opponent_becomes_monarch: false,
                    exile_all_except_bottom: false,
                    face_down: false,
                    look_only: false,
                    exile_with_counters: None,
                },
                Selector::All {
                    filter: Box::new(ex_f),
                },
                span,
            );
            ex_st.bind_as = Some(bname.clone());
            state.push_step(ex_st, true);
            let sac_st = make_step(
                EffectOp::Sacrifice {
                    select: SelectionMod::default(),
                },
                Selector::All {
                    filter: Box::new(sac_f),
                },
                span,
            );
            state.push_step(sac_st, true);
            let mv_st = make_step(
                EffectOp::Move {
                    from: Some(Zone::Exile),
                    to: Some(Zone::Battlefield),
                    select: SelectionMod::default(),
                    tapped: false,
                    under_your_control: false,
                    topmost_only: false,
                    may_shuffle: false,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                Selector::Binding { name: bname },
                span,
            );
            state.push_step(mv_st, true);
            return true;
        }
        state.rollback(mark_ld, ctx);
    }
    if eq_ci(t, "each player chooses a color") {
        state.push_step(
            make_step(
                EffectOp::ChooseDesignation {
                    kind: DesignationKind::Color,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(t, "each player chooses a creature type") {
        state.push_step(
            make_step(
                EffectOp::ChooseDesignation {
                    kind: DesignationKind::CreatureType,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    for &prefix in player_prefixes {
        if let Some(after) = strip_prefix_word_ci(t, prefix) {
            let is_exile_gy_cost = starts_with_word_ci(after, "may exile ")
                && !contains_word_ci(after, "up to")
                && !contains_word_ci(after, "target")
                && {
                    let cp = ctx.interner.checkpoint();
                    let body = after.trim_start()[3..].trim();
                    let cost_parse = crate::parser::cost::parse_cost_list(body, span.start, ctx);
                    let ok = cost_parse.defs.len() == 1
                        && cost_parse.unparsed.is_empty()
                        && matches!(
                            cost_parse.defs[0],
                            mtg_ir::CostDef::ExileFrom {
                                zone: Zone::Graveyard,
                                target: Some(mtg_ir::CostObjectTarget::Filter { .. }),
                                ..
                            }
                        );
                    ctx.interner.rollback(cp);
                    ok
                };
            if prefix == "you"
                && !is_exile_gy_cost
                && (starts_with_word_ci(after, "may ")
                    || starts_with_word_ci(after, "gain ")
                    || starts_with_word_ci(after, "lose ")
                    || starts_with_word_ci(after, "draw ")
                    || starts_with_word_ci(after, "discard ")
                    || starts_with_word_ci(after, "mill ")
                    || starts_with_word_ci(after, "create ")
                    || starts_with_word_ci(after, "scry ")
                    || starts_with_word_ci(after, "surveil ")
                    || starts_with_word_ci(after, "win ")
                    || starts_with_word_ci(after, "lose the game")
                    || starts_with_word_ci(after, "become the monarch")
                    || starts_with_word_ci(after, "get ")
                    || starts_with_word_ci(after, "exert ")
                    || starts_with_word_ci(after, "take ")
                    || starts_with_word_ci(after, "return ")
                    || starts_with_word_ci(after, "put "))
            {
                let mark = state.mark(ctx);
                if parse_player_predicate(you_sel(), None, after, span, ctx, state) {
                    return true;
                }
                state.rollback(mark, ctx);
            } else if prefix != "you" {
                let mark = state.mark(ctx);
                if let Some(psel) = parse_player_selector(prefix, ctx, state) {
                    let is_hand_discard = contains_word_ci(after, "hand")
                        && (contains_word_ci(after, "discard")
                            || contains_word_ci(after, "discards"));
                    let is_frac_life = (contains_word_ci(after, "lose")
                        || contains_word_ci(after, "loses"))
                        && contains_word_ci(after, "of their life");
                    let is_sac_then = (starts_with_word_ci(after, "sacrifice")
                        || starts_with_word_ci(after, "sacrifices"))
                        && contains_word_ci(after, ", then ");
                    let is_sac_for_each = (starts_with_word_ci(after, "sacrifice")
                        || starts_with_word_ci(after, "sacrifices"))
                        && contains_word_ci(after, " for each ");
                    let is_tempt_may = starts_with_word_ci(after, "may ")
                        && (contains_word_ci(after, "search ")
                            || contains_word_ci(after, " and create ")
                            || contains_word_ci(after, "create x "));
                    let is_may_each = starts_with_word_ci(after, "may ");
                    let needs_per_player_eval = is_sac_then
                        || is_sac_for_each
                        || is_tempt_may
                        || ((starts_with_word_ci(after, "reveals ")
                            || starts_with_word_ci(after, "reveal "))
                            && contains_word_ci(after, "their library"))
                        || (!starts_with_word_ci(after, "sacrifice")
                            && !starts_with_word_ci(after, "sacrifices")
                            && !contains_word_ci(after, "destroyed this way")
                            && (contains_word_ci(after, "their graveyard")
                                || contains_word_ci(after, "that player's graveyard")
                                || contains_word_ci(after, "they control")
                                || contains_word_ci(after, "they controlled")
                                || contains_word_ci(after, "that player controls")
                                || contains_word_ci(after, "that player controlled")));
                    if (prefix == "each other player")
                        || (matches!(
                            &psel,
                            Selector::Player { filter: pf }
                                if matches!(
                                    pf.relation,
                                    PlayerRelation::EachPlayer | PlayerRelation::EachOpponent
                                )
                        ) && (is_hand_discard
                            || is_frac_life
                            || needs_per_player_eval
                            || is_may_each))
                    {
                        let loop_kind = if prefix == "each other player" {
                            LoopPlayersKind::EachOtherPlayer
                        } else if matches!(
                            &psel,
                            Selector::Player { filter: pf } if pf.relation == PlayerRelation::EachOpponent
                        ) {
                            LoopPlayersKind::EachOpponent
                        } else {
                            LoopPlayersKind::EachPlayer
                        };
                        let before = state.steps.len();
                        let prev_loop = state.is_each_loop;
                        state.is_each_loop = true;
                        let loop_actor = if is_hand_discard || needs_per_player_eval || is_may_each
                        {
                            Some(PlayerRef::EachLoopPlayer)
                        } else {
                            None
                        };
                        let ok = parse_player_predicate(
                            Selector::PlayerRef {
                                player: PlayerRef::EachLoopPlayer,
                            },
                            loop_actor,
                            after,
                            span,
                            ctx,
                            state,
                        );
                        state.is_each_loop = prev_loop;
                        if ok && state.steps.len() > before {
                            let mut inner_steps = state.steps.split_off(before);
                            for st in &mut inner_steps {
                                if let Some(StepGate::IfPrecedingAccepted { step_index }) =
                                    &mut st.gate
                                {
                                    *step_index = step_index.saturating_sub(before as u16);
                                }
                            }
                            if is_tempt_may
                                && let Some(first) = inner_steps.first_mut()
                                && first.actor.is_none()
                                && matches!(first.op, EffectOp::Draw { .. })
                            {
                                first.actor = Some(PlayerRef::EachLoopPlayer);
                            }
                            state.push_step(
                                make_step(
                                    EffectOp::ForEachPlayerLoop {
                                        players: loop_kind,
                                        steps: inner_steps,
                                        choose_random_opponent: false,
                                        exclude_attacked_last_combat: false,
                                        exclude_event_player: false,
                                        choose_object_to_bind: None,
                                    },
                                    Selector::None,
                                    span,
                                ),
                                false,
                            );
                            return true;
                        }
                        state.rollback(mark, ctx);
                        continue;
                    }
                    let actor = match &psel {
                        Selector::Target { index } => Some(PlayerRef::Target { index: *index }),
                        Selector::PlayerRef { player } => Some(player.clone()),
                        _ => None,
                    };
                    if parse_player_predicate(psel, actor, after, span, ctx, state) {
                        return true;
                    }
                }
                state.rollback(mark, ctx);
            }
        }
    }
    if let Some(psel) = state.last_player.clone()
        && (starts_with_word_ci(t, "sacrifices")
            || starts_with_word_ci(t, "discards")
            || starts_with_word_ci(t, "draws")
            || starts_with_word_ci(t, "loses")
            || starts_with_word_ci(t, "mills")
            || starts_with_word_ci(t, "gains")
            || starts_with_word_ci(t, "exiles")
            || starts_with_word_ci(t, "returns")
            || starts_with_word_ci(t, "puts"))
    {
        let actor = match &psel {
            Selector::Target { index } => Some(PlayerRef::Target { index: *index }),
            Selector::PlayerRef { player } => Some(player.clone()),
            _ => None,
        };
        let mark = state.mark(ctx);
        if parse_player_predicate(psel, actor, t, span, ctx, state) {
            return true;
        }
        state.rollback(mark, ctx);
    }
    false
}

fn parse_player_predicate(
    subj: Selector,
    actor: Option<PlayerRef>,
    pred: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if let Selector::PlayerRef { ref player } = subj {
        state.last_player = Some(Selector::PlayerRef {
            player: player.clone(),
        });
    }
    let pred = strip_prefix_word_ci(pred, "each").unwrap_or(pred);
    if let Some(mana_rest) =
        strip_prefix_word_ci(pred, "adds").or_else(|| strip_prefix_word_ci(pred, "add"))
    {
        let before = state.steps.len();
        let synthetic = format!("add {mana_rest}");
        if parse_add_mana_core(&synthetic, span, ctx, state) {
            for st in &mut state.steps[before..] {
                st.subject = Selector::None;
                st.actor = actor.clone();
            }
            return true;
        }
    }
    if eq_ci(pred, "exert ~") || eq_ci(pred, "exert it") {
        let tgt = if eq_ci(pred, "exert it") {
            state
                .it_ref()
                .map(|r| ref_to_selector(&r))
                .unwrap_or(Selector::SelfObj)
        } else {
            Selector::SelfObj
        };
        state.push_step(make_step(EffectOp::Exert, tgt, span), false);
        return true;
    }
    if eq_ci(pred, "take the initiative") || eq_ci(pred, "takes the initiative") {
        state.push_step(make_step(EffectOp::TakeInitiative, subj, span), false);
        return true;
    }
    if eq_ci(pred, "take an extra turn after this one")
        || eq_ci(pred, "takes an extra turn after this one")
    {
        state.push_step(make_step(EffectOp::ExtraTurn, subj, span), false);
        return true;
    }
    if eq_ci(pred, "become the monarch") || eq_ci(pred, "becomes the monarch") {
        state.push_step(make_step(EffectOp::BecomeMonarch, subj, span), false);
        return true;
    }
    if eq_ci(pred, "win the game") {
        state.push_step(
            make_step(EffectOp::Win { condition: None }, subj, span),
            false,
        );
        return true;
    }
    if eq_ci(pred, "lose the game") || eq_ci(pred, "loses the game") {
        state.push_step(
            make_step(EffectOp::Lose { condition: None }, subj, span),
            false,
        );
        return true;
    }
    if eq_ci(pred, "can't cast spells this turn") {
        let gp_subj = match subj {
            Selector::Target { index } => Selector::PlayerRef {
                player: PlayerRef::Target { index },
            },
            other => other,
        };
        state.push_step(
            make_step(
                EffectOp::GrantPlayer {
                    rules: vec![PlayerRuleKind::CantCastSpellsThisTurn],
                    duration: Some(Duration::EndOfTurn),
                    extra_land_plays: None,
                    next_spell_types: None,
                    spend_mana_as_any_color_top_of_library: false,
                    steal_opponent_entering_creatures_until_eot: false,
                    opponents_spells_cost_more_until_next_turn: None,
                    attack_tax_until_your_next_turn: None,
                    next_spell_cost_reduction_generic: None,
                    next_creature_enters_with_plus_counters: None,
                    next_main_phase_add_mana: None,
                    double_tokens_this_turn: false,
                    flash_cast_condition: None,
                    next_spell_cascade: None,
                    extra_loyalty_activations_this_turn: None,
                    planar_action: None,
                },
                gp_subj,
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(after_same) = strip_prefix_word_ci(pred, "can't cast spells with the same name as")
    {
        let (obj_s, dur) = parse_duration_suffix(after_same);
        let obj_clean = obj_s.trim();
        let name_ref = if let Some((r, _)) = &state.last_object
            && (eq_ci(obj_clean, "it")
                || eq_ci(obj_clean, "that creature")
                || eq_ci(obj_clean, "that permanent")
                || eq_ci(obj_clean, "that card")
                || eq_ci(obj_clean, "that spell"))
        {
            r.clone()
        } else {
            Ref::SelfObj
        };
        state.push_step(
            make_step(
                EffectOp::CastNameLock {
                    name_ref,
                    duration: dur.or(Some(Duration::UntilYourNextTurn)),
                },
                subj,
                span,
            ),
            false,
        );
        return true;
    }
    if (starts_with_word_ci(pred, "draws") || starts_with_word_ci(pred, "draw"))
        && parse_draw_clause(pred, subj.clone(), actor.clone(), span, ctx, state)
    {
        return true;
    }
    if (starts_with_word_ci(pred, "discards") || starts_with_word_ci(pred, "discard"))
        && parse_discard_clause(pred, subj.clone(), actor.clone(), span, ctx, state)
    {
        return true;
    }
    if (starts_with_word_ci(pred, "mills") || starts_with_word_ci(pred, "mill"))
        && parse_mill_clause(pred, subj.clone(), actor.clone(), span, ctx, state)
    {
        return true;
    }
    if (starts_with_word_ci(pred, "sacrifices") || starts_with_word_ci(pred, "sacrifice"))
        && parse_sacrifice_clause(pred, subj.clone(), actor.clone(), span, ctx, state)
    {
        return true;
    }
    if let Some(after_ret) =
        strip_prefix_word_ci(pred, "returns").or_else(|| strip_prefix_word_ci(pred, "return"))
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        let synth = format!("return {after_ret}");
        if parse_return_clause(&synth, span, ctx, state) && state.steps.len() > before {
            let has_their = contains_word_ci(pred, "their");
            for st in &mut state.steps[before..] {
                if st.actor.is_none() && !matches!(st.op, EffectOp::Move { .. }) {
                    st.actor = actor.clone();
                }
                if state.is_each_loop
                    && has_their
                    && let Selector::All { ref mut filter } = st.subject
                    && filter.owner.is_none()
                    && !filter
                        .extra
                        .iter()
                        .any(|p| matches!(p, ObjectPredicate::OwnerRef { .. }))
                {
                    filter.extra.push(ObjectPredicate::OwnerRef {
                        player: PlayerRef::EachLoopPlayer,
                    });
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }
    if (eq_ci(pred, "reveals the top card of their library")
        || eq_ci(pred, "reveal the top card of their library"))
        && state.is_each_loop
    {
        state.push_step(
            make_step(
                EffectOp::Reveal {
                    select: SelectionMod::default(),
                    look_only: false,
                    special_tag: None,
                },
                Selector::LibraryTop {
                    player: Some(PlayerRef::EachLoopPlayer),
                },
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(after_rev) = strip_prefix_word_ci(
        pred,
        "reveals cards from the top of their library until they reveal",
    )
    .or_else(|| {
        strip_prefix_word_ci(
            pred,
            "reveal cards from the top of their library until they reveal",
        )
    }) && let Some((until_raw, rest_tail)) = split_at_top_level_comma(after_rev)
        && contains_word_ci(rest_tail, "into their graveyard")
    {
        let filt_s = strip_prefix_word_ci(until_raw.trim(), "a")
            .or_else(|| strip_prefix_word_ci(until_raw.trim(), "an"))
            .unwrap_or(until_raw.trim());
        let cp = ctx.interner.checkpoint();
        if let Some(f) = parse_object_phrase(
            filt_s,
            ctx,
            FilterOpts {
                default_zone: ZoneMask::empty(),
                allow_plural_and_disjunction: true,
                strip_trailing_card: true,
                ..Default::default()
            },
        ) {
            let mut st = make_step(
                EffectOp::Dig {
                    spec: Box::new(DigSpec {
                        keep: 0,
                        up_to: false,
                        keep_filter: None,
                        keep_all_matching: false,
                        keep_label: None,
                        keep_to: DigKeepTo::Graveyard,
                        keep_tapped: false,
                        keep_attacking: false,
                        keep_attacking_player: None,
                        reveal_all: true,
                        reveal_kept: false,
                        rest: DigRestTo::Graveyard,
                        rest_random: false,
                        rest_order: None,
                        until_filter: Some(Box::new(f)),
                        rest_to_hand: false,
                        shuffle_rest: false,
                        keep_max_mana_value: None,
                        keep_max_mv_strict_lt: false,
                        choose_one_of_exiled: false,
                        play_from_exile: None,
                        partitions: Vec::new(),
                        destination_buckets: Vec::new(),
                    }),
                    look_only: false,
                },
                subj.clone(),
                span,
            );
            st.actor = None;
            state.push_step(st, false);
            return true;
        }
        ctx.interner.rollback(cp);
    }
    if let Some(after_ex) =
        strip_prefix_word_ci(pred, "exiles").or_else(|| strip_prefix_word_ci(pred, "exile"))
    {
        if starts_with_word_ci(after_ex, "cards from the top of")
            && contains_word_ci(after_ex, " until ")
        {
            let before = state.steps.len();
            let mark = state.mark(ctx);
            let synth = format!("exile {after_ex}");
            if parse_core_imperative(&synth, span, ctx, state) && state.steps.len() > before {
                return true;
            }
            state.rollback(mark, ctx);
        }
        let before = state.steps.len();
        let mark = state.mark(ctx);
        let synth = format!("exile {after_ex}");
        if parse_exile_clause(&synth, span, ctx, state) && state.steps.len() > before {
            let has_their = contains_word_ci(pred, "their");
            let has_they_ctrl = contains_word_ci(pred, "they control");
            for st in &mut state.steps[before..] {
                if let Selector::LibraryTop { ref mut player } = st.subject
                    && player.is_none()
                {
                    *player = actor.clone();
                }
                if st.actor.is_none() {
                    st.actor = actor.clone();
                }
                if state.is_each_loop
                    && let Selector::All { ref mut filter } = st.subject
                {
                    if has_they_ctrl
                        && filter.controller.is_none()
                        && !filter
                            .extra
                            .iter()
                            .any(|p| matches!(p, ObjectPredicate::ControllerRef { .. }))
                    {
                        filter.extra.push(ObjectPredicate::ControllerRef {
                            player: PlayerRef::EachLoopPlayer,
                        });
                    } else if has_their
                        && filter.owner.is_none()
                        && !filter
                            .extra
                            .iter()
                            .any(|p| matches!(p, ObjectPredicate::OwnerRef { .. }))
                    {
                        filter.extra.push(ObjectPredicate::OwnerRef {
                            player: PlayerRef::EachLoopPlayer,
                        });
                    }
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(after_ex) =
        strip_prefix_word_ci(pred, "exiles").or_else(|| strip_prefix_word_ci(pred, "exile"))
    {
        if eq_ci(
            after_ex,
            "a card from their hand or a permanent they control",
        ) {
            let mut f = ObjectFilter {
                zones: ZoneMask::HAND | ZoneMask::BATTLEFIELD,
                ..Default::default()
            };
            if let Some(ref act) = actor {
                f.extra.push(ObjectPredicate::ControllerRef {
                    player: act.clone(),
                });
            } else if let Selector::PlayerRef { ref player } = subj {
                f.extra.push(ObjectPredicate::ControllerRef {
                    player: player.clone(),
                });
            }
            let mut st = make_step(
                EffectOp::Exile {
                    select: SelectionMod {
                        choice_count: Some(Box::new(Amount::Const { n: 1 })),
                        ..SelectionMod::default()
                    },
                    duration: None,
                    until_source_leaves: false,
                    until_opponent_becomes_monarch: false,
                    exile_all_except_bottom: false,
                    face_down: false,
                    look_only: false,
                    exile_with_counters: None,
                },
                Selector::All {
                    filter: Box::new(f),
                },
                span,
            );
            st.actor = actor.clone();
            st.amount = Some(Box::new(Amount::Const { n: 1 }));
            state.push_step(st, false);
            return true;
        }
        if let Some(cnt_s) = strip_suffix_word_ci(after_ex, "cards from their hand")
            .or_else(|| strip_suffix_word_ci(after_ex, "card from their hand"))
            .or_else(|| strip_suffix_word_ci(after_ex, "cards from that player's hand"))
            .or_else(|| strip_suffix_word_ci(after_ex, "card from that player's hand"))
            && let Some(amt) = parse_amount_str(
                if eq_ci(cnt_s, "a") || eq_ci(cnt_s, "an") {
                    "1"
                } else {
                    cnt_s
                },
                ctx,
                state,
            )
        {
            let mut f = ObjectFilter {
                zones: ZoneMask::HAND,
                ..Default::default()
            };
            match &subj {
                Selector::Player { filter: pf } => match pf.relation {
                    PlayerRelation::You => f.owner = Some(RelativeControl::You),
                    PlayerRelation::Opponent | PlayerRelation::EachOpponent => {
                        f.owner = Some(RelativeControl::Opponent);
                    }
                    _ => {}
                },
                Selector::Target { index } => {
                    f.extra.push(ObjectPredicate::OwnerRef {
                        player: PlayerRef::Target { index: *index },
                    });
                }
                Selector::PlayerRef { player } => {
                    f.extra.push(ObjectPredicate::OwnerRef {
                        player: player.clone(),
                    });
                }
                _ => {}
            }
            let mut st = make_step(
                EffectOp::Exile {
                    select: SelectionMod::default(),
                    duration: None,
                    until_source_leaves: false,
                    until_opponent_becomes_monarch: false,
                    exile_all_except_bottom: false,
                    face_down: false,
                    look_only: false,
                    exile_with_counters: None,
                },
                Selector::All {
                    filter: Box::new(f),
                },
                span,
            );
            st.actor = if state.is_each_loop {
                actor.clone()
            } else {
                None
            };
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
    }
    if let Some(after_put) =
        strip_prefix_word_ci(pred, "puts").or_else(|| strip_prefix_word_ci(pred, "put"))
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        let synth = format!("put {after_put}");
        if parse_put_clause(&synth, span, ctx, state) && state.steps.len() > before {
            let has_their_gy = contains_word_ci(pred, "their graveyard");
            for st in &mut state.steps[before..] {
                if has_their_gy
                    && let Some(ref act) = actor
                    && let Selector::All { ref mut filter } = st.subject
                    && filter.owner.is_none()
                    && !filter
                        .extra
                        .iter()
                        .any(|p| matches!(p, ObjectPredicate::OwnerRef { .. }))
                {
                    filter.extra.push(ObjectPredicate::OwnerRef {
                        player: act.clone(),
                    });
                } else if st.actor.is_none() {
                    st.actor = actor.clone();
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(after_draw) = strip_prefix_word_ci(pred, "draw cards and lose life equal to")
        .or_else(|| strip_prefix_word_ci(pred, "draws cards and loses life equal to"))
        && let Some(amt) = parse_amount_str(after_draw, ctx, state)
    {
        let mut d = make_step(
            EffectOp::Draw {
                up_to: false,
                reveal_drawn: false,
            },
            subj.clone(),
            span,
        );
        d.amount = Some(Box::new(amt.clone()));
        state.push_step(d, false);
        let mut l = make_step(EffectOp::LoseLife, subj, span);
        l.amount = Some(Box::new(amt));
        state.push_step(l, false);
        return true;
    }
    if let Some(rest) = strip_prefix_word_ci(pred, "gains control of")
        .or_else(|| strip_prefix_word_ci(pred, "gain control of"))
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        if parse_gain_control_clause(rest, None, false, span, ctx, state)
            && state.steps.len() > before
        {
            if let Some(ref act) = actor
                && (!state.is_each_loop || starts_with_word_ci(pred, "gains control of"))
            {
                for st in &mut state.steps[before..] {
                    if st.actor.is_none() {
                        st.actor = Some(act.clone());
                    }
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(amt) = parse_life_amount(pred, "gains", ctx, state)
        .or_else(|| parse_life_amount(pred, "gain", ctx, state))
    {
        let mut st = make_step(
            EffectOp::GainLife {
                set_life_total: false,
            },
            subj,
            span,
        );
        st.amount = Some(Box::new(amt));
        state.push_step(st, false);
        return true;
    }
    if let Some(amt) = parse_life_amount(pred, "loses", ctx, state)
        .or_else(|| parse_life_amount(pred, "lose", ctx, state))
    {
        let mut st = make_step(EffectOp::LoseLife, subj, span);
        st.amount = Some(Box::new(amt));
        state.push_step(st, false);
        return true;
    }
    if let Some(rest) =
        strip_prefix_word_ci(pred, "gets").or_else(|| strip_prefix_word_ci(pred, "get"))
        && let Some((amt_raw, counter)) = [
            ("poison", PlayerCounterKind::Poison),
            ("experience", PlayerCounterKind::Experience),
            ("energy", PlayerCounterKind::Energy),
            ("rad", PlayerCounterKind::Rad),
            ("ticket", PlayerCounterKind::Ticket),
        ]
        .into_iter()
        .find_map(|(kw, kind)| {
            let suf_pl = format!("{kw} counters");
            let suf_sg = format!("{kw} counter");
            if let Some(a) =
                strip_suffix_word_ci(rest, &suf_pl).or_else(|| strip_suffix_word_ci(rest, &suf_sg))
            {
                return Some((a, kind));
            }
            if let Some(after_num) = strip_prefix_word_ci(rest, "a number of") {
                let mid_pl = format!("{kw} counters equal to");
                let mid_sg = format!("{kw} counter equal to");
                if let Some(rhs) = strip_prefix_word_ci(after_num, &mid_pl)
                    .or_else(|| strip_prefix_word_ci(after_num, &mid_sg))
                {
                    return Some((rhs, kind));
                }
            }
            None
        })
    {
        let amt_clean = if eq_ci(amt_raw, "a") || eq_ci(amt_raw, "an") {
            "1"
        } else {
            amt_raw
        };
        if let Some(amt) = parse_amount_str(amt_clean, ctx, state) {
            let mut st = make_step(EffectOp::PutPlayerCounters { counter }, subj, span);
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
    }
    if (starts_with_word_ci(pred, "search") || starts_with_word_ci(pred, "searches"))
        && parse_search_clause(pred, subj.clone(), actor.clone(), span, ctx, state)
    {
        return true;
    }
    if eq_ci(pred, "shuffles")
        || eq_ci(pred, "shuffle")
        || eq_ci(pred, "shuffles their library")
        || eq_ci(pred, "shuffle their library")
    {
        if state.steps.last().is_some_and(
            |s| matches!(&s.op, EffectOp::Search { spec, .. } if spec.searched_player.is_some()),
        ) {
            return true;
        }
        state.push_step(
            make_step(
                EffectOp::Move {
                    from: Some(Zone::Library),
                    to: Some(Zone::Library),
                    select: SelectionMod::default(),
                    tapped: false,
                    under_your_control: false,
                    topmost_only: false,
                    may_shuffle: true,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: true,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                subj,
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(pred, "shuffles their hand and graveyard into their library")
        || eq_ci(pred, "shuffle their hand and graveyard into their library")
    {
        state.push_step(
            make_step(
                EffectOp::Move {
                    from: None,
                    to: Some(Zone::Library),
                    select: SelectionMod::default(),
                    tapped: false,
                    under_your_control: false,
                    topmost_only: false,
                    may_shuffle: true,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                Selector::All {
                    filter: Box::new(ObjectFilter {
                        zones: ZoneMask::HAND | ZoneMask::GRAVEYARD,
                        ..Default::default()
                    }),
                },
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(
        pred,
        "copy this spell and may choose a new target for that copy",
    ) || eq_ci(
        pred,
        "copy this spell and may choose new targets for that copy",
    ) || eq_ci(pred, "copy ~ and may choose a new target for that copy")
        || eq_ci(pred, "copy ~ and may choose new targets for that copy")
        || eq_ci(pred, "copy this spell")
        || eq_ci(pred, "copy ~")
    {
        let mut st = make_step(
            EffectOp::CopySpell {
                count: None,
                may_choose_new_targets: contains_word_ci(pred, "may choose"),
                non_legendary: false,
                except_colors: ColorMask::empty(),
                copy_event_ability: false,
                copy_per_sacrificed_cost: false,
                copy_all_controlled_spells_and_other_abilities: false,
            },
            Selector::SelfObj,
            span,
        );
        st.actor = actor;
        state.push_step(st, false);
        return true;
    }
    if starts_with_word_ci(pred, "create") || starts_with_word_ci(pred, "creates") {
        let norm = if starts_with_word_ci(pred, "creates") {
            format!("create {}", pred[7..].trim_start())
        } else {
            pred.to_string()
        };
        let before = state.steps.len();
        if parse_token_creation_clause(&norm, span, ctx, state) {
            for st in &mut state.steps[before..] {
                if !matches!(st.op, EffectOp::CopyPermanent { .. }) {
                    st.subject = Selector::None;
                }
                if actor.is_some() {
                    st.actor = actor.clone();
                }
            }
            return true;
        }
    }
    if (starts_with_word_ci(pred, "manifest") || starts_with_word_ci(pred, "manifests"))
        && (contains_ascii_ci(pred.as_bytes(), b"the top card of their library")
            || contains_ascii_ci(pred.as_bytes(), b"the top card of your library")
            || contains_ascii_ci(pred.as_bytes(), b"the top card of that player's library")
            || contains_ascii_ci(pred.as_bytes(), b"the top card of its library"))
    {
        let mut st = make_step(
            EffectOp::Manifest,
            Selector::LibraryTop { player: None },
            span,
        );
        st.actor = actor;
        st.amount = Some(Box::new(Amount::Const { n: 1 }));
        state.steps.push(st);
        return true;
    }
    if starts_with_word_ci(pred, "may") {
        let may_body = pred[3..].trim_start();
        let before = state.steps.len();
        let mark = state.mark(ctx);
        let parsed_may =
            (parse_player_predicate(subj.clone(), actor.clone(), may_body, span, ctx, state)
                || (starts_with_word_ci(may_body, "have ")
                    && parse_core_imperative(may_body, span, ctx, state)))
                && state.steps.len() > before
                && !matches!(state.steps[before].op, EffectOp::PunisherChoice { .. });
        if parsed_may {
            let chooser = actor.unwrap_or(PlayerRef::You);
            state.steps[before].optional = Some(OptionalSpec {
                chooser,
                cost: Vec::new(),
                mode: OptionalMode::DoIfPaid,
            });
            if state.is_each_loop {
                for extra_st in &mut state.steps[before + 1..] {
                    if extra_st.gate.is_none() {
                        extra_st.gate = Some(StepGate::IfPrecedingAccepted {
                            step_index: before as u16,
                        });
                    }
                }
            }
            state.last_optional_step = Some(before);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(then_pos) = find_word_ci(pred, ", then ") {
        let left = pred[..then_pos].trim();
        let right = pred[then_pos + 7..].trim();
        if !left.is_empty() && !right.is_empty() {
            let mark = state.mark(ctx);
            if parse_player_predicate(subj.clone(), actor.clone(), left, span, ctx, state)
                && parse_player_predicate(subj.clone(), actor.clone(), right, span, ctx, state)
            {
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    if let Some(and_pos) = find_word_ci(pred, "and") {
        let left = pred[..and_pos].trim().trim_end_matches(',').trim();
        let right = pred[and_pos + 3..].trim();
        if !left.is_empty() && !right.is_empty() {
            let mark = state.mark(ctx);
            if parse_player_predicate(subj.clone(), actor.clone(), left, span, ctx, state)
                && parse_player_predicate(subj.clone(), actor.clone(), right, span, ctx, state)
            {
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    if let Some(comma_pos) = pred.find(", ") {
        let left = pred[..comma_pos].trim();
        let right = pred[comma_pos + 2..].trim();
        if !left.is_empty() && !right.is_empty() && !starts_with_word_ci(right, "then ") {
            let mark = state.mark(ctx);
            if parse_player_predicate(subj.clone(), actor.clone(), left, span, ctx, state)
                && parse_player_predicate(subj.clone(), actor.clone(), right, span, ctx, state)
            {
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    if let Some(you_pred) = strip_prefix_word_ci(pred, "you") {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        if (parse_player_predicate(you_sel(), None, you_pred, span, ctx, state)
            || parse_core_imperative(you_pred, span, ctx, state))
            && state.steps.len() > before
        {
            return true;
        }
        state.rollback(mark, ctx);
    }
    if matches!(&subj, Selector::Player { filter } if filter.relation == PlayerRelation::You)
        && actor.is_none()
        && !starts_with_word_ci(pred, "you ")
        && !starts_with_word_ci(pred, "may ")
        && !starts_with_word_ci(pred, "remove ")
        && !starts_with_word_ci(pred, "exile ")
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        if parse_core_imperative(pred, span, ctx, state) && state.steps.len() > before {
            return true;
        }
        state.rollback(mark, ctx);
    }
    false
}

fn parse_prefixed_or_conditional_clause(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    // 1. Reflexive trigger: "When you do, <effect>" / "Whenever a <filter> is (exiled|sacrificed|discarded|dies) this way, <effect>"
    if let Some(after) = strip_prefix_word_ci(t, "when you do,") {
        if state.steps.is_empty()
            && (eq_ci(after, "copy ~ for each creature sacrificed this way")
                || eq_ci(
                    after,
                    "copy this spell for each creature sacrificed this way",
                )
                || (starts_with_word_ci(after, "copy ~ for each ")
                    && find_word_ci(after, "sacrificed this way").is_some()))
        {
            let mut st = make_step(
                EffectOp::CopySpell {
                    count: None,
                    may_choose_new_targets: true,
                    non_legendary: false,
                    except_colors: ColorMask::empty(),
                    copy_event_ability: false,
                    copy_per_sacrificed_cost: true,
                    copy_all_controlled_spells_and_other_abilities: false,
                },
                Selector::SelfObj,
                span,
            );
            st.gate = Some(StepGate::Condition {
                condition: Box::new(Condition::AdditionalCostPaid { mana_cost: None }),
            });
            state.push_step(st, false);
            return true;
        }
        if let Some(opt_idx) = state.steps.len().checked_sub(1)
            && matches!(
                state.steps[opt_idx].op,
                EffectOp::Grant {
                    pay_any_mana_for_damage: Some(_),
                    ..
                }
            )
        {
            let before = state.steps.len();
            if parse_clauses_into(after.trim(), span.start, ctx, state)
                && state.steps.len() > before
            {
                for st in &mut state.steps[before..] {
                    st.gate = Some(StepGate::IfPrecedingAccepted {
                        step_index: opt_idx as u16,
                    });
                }
                return true;
            }
        }
        return attach_reflexive_trigger(
            ReflexiveEventFilter::WhenYouDo,
            None,
            after.trim(),
            span,
            ctx,
            state,
        );
    }
    if (starts_with_word_ci(t, "when ") || starts_with_word_ci(t, "whenever "))
        && let Some((hdr, body)) = split_at_top_level_comma(t)
        && let Some(ev_filter) = detect_reflexive_event_filter(hdr)
    {
        let obj_filter = extract_reflexive_object_filter(hdr, ctx, state);
        return attach_reflexive_trigger(ev_filter, obj_filter, body, span, ctx, state);
    }
    if (starts_with_word_ci(t, "when you reveal ")
        || starts_with_word_ci(t, "whenever you reveal "))
        && state
            .steps
            .last()
            .is_some_and(|s| matches!(s.op, EffectOp::Dig { .. }))
        && let Some((hdr, body)) = split_at_top_level_comma(t)
        && contains_word_ci(hdr, "this way")
    {
        let before = state.steps.len();
        let before_t = state.targets.len();
        let saved_obj = state.last_object.clone();
        let saved_x = state.defined_x.clone();
        let mark = state.mark(ctx);
        state.last_object = Some((
            Ref::Binding {
                name: "revealed".to_string(),
            },
            before,
        ));
        let ok = if let Some((left, x_expr)) = split_where_x_is(body.trim())
            && let Some(x_amt) = parse_amount_str(x_expr, ctx, state)
        {
            state.defined_x = Some(x_amt.clone());
            let parsed = (parse_core_imperative(left, span, ctx, state)
                || parse_clauses_into(left, span.start, ctx, state))
                && state.steps.len() > before;
            if parsed {
                substitute_defined_x_in_steps(&mut state.steps[before..], &x_amt);
                substitute_defined_x_in_targets(&mut state.targets[before_t..], &x_amt);
            }
            state.defined_x = saved_x;
            parsed
        } else {
            parse_core_imperative(body.trim(), span, ctx, state)
                || parse_clauses_into(body.trim(), span.start, ctx, state)
        };
        if ok && state.steps.len() > before {
            for st in &mut state.steps[before..] {
                attach_gate_condition(&mut st.gate, Condition::DidRevealThisWay);
            }
            return true;
        }
        state.last_object = saved_obj;
        state.rollback(mark, ctx);
    }

    // 2. Delayed trigger: "At the beginning of [the next|your next] [end step|upkeep], <effect>"
    //    or "<effect> at the beginning of [the|your] next [end step|upkeep]"
    //    or "Until end of turn, whenever ..." or "When that creature dies this turn, ..."
    if !eq_ci(
        t,
        "when you next cast an instant or sorcery spell this turn, copy that spell",
    ) && !eq_ci(
        t,
        "when you cast your next instant or sorcery spell this turn, copy it",
    ) && !eq_ci(
        t,
        "when you next cast an artifact spell this turn, that spell gains sunburst",
    ) && !eq_ci(
        t,
        "when you cast your next artifact spell this turn, that spell gains sunburst",
    ) && (starts_with_word_ci(t, "at the beginning of")
        || starts_with_word_ci(t, "whenever ")
        || starts_with_word_ci(t, "when ")
        || starts_with_word_ci(t, "until end of turn, whenever ")
        || starts_with_word_ci(t, "until your next turn, whenever ")
        || contains_word_ci(t, "at the beginning of ")
        || strip_suffix_word_ci(t, "at end of combat").is_some()
        || strip_suffix_word_ci(t, "at the end of combat").is_some()
        || strip_suffix_word_ci(t, "at the end of that combat").is_some())
        && parse_delayed_trigger_sentence(t, span, ctx, state)
    {
        return true;
    }

    // 3. Duration prefix: "Until end of turn, <body...>"
    let (dur_pre, rest_dur) = parse_duration_prefix(t);
    if let Some(dur) = dur_pre {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        let parsed_dur_body = parse_clauses_into(rest_dur, span.start, ctx, state) || {
            state.rollback(mark.clone(), ctx);
            if rest_dur.contains(',') {
                let mut segs: Vec<&str> = Vec::new();
                let mut start = 0usize;
                let mut depth = 0usize;
                for (idx, ch) in rest_dur.char_indices() {
                    match ch {
                        '(' => depth += 1,
                        ')' => depth = depth.saturating_sub(1),
                        ',' if depth == 0 => {
                            let s = rest_dur[start..idx].trim();
                            if !s.is_empty() {
                                segs.push(s);
                            }
                            start = idx + 1;
                        }
                        _ => {}
                    }
                }
                let last = rest_dur[start..].trim();
                if !last.is_empty() {
                    segs.push(last);
                }
                segs.len() >= 2
                    && segs.iter().enumerate().all(|(i, s)| {
                        let seg = if i > 0 {
                            strip_prefix_word_ci(s, "and").unwrap_or(s)
                        } else {
                            *s
                        };
                        parse_core_imperative(seg, span, ctx, state)
                    })
            } else {
                false
            }
        };
        if parsed_dur_body && state.steps.len() > before {
            for st in &mut state.steps[before..] {
                match &mut st.op {
                    EffectOp::Pump { duration, .. }
                    | EffectOp::Grant { duration, .. }
                    | EffectOp::Animate { duration, .. }
                    | EffectOp::CombatRestriction { duration, .. }
                    | EffectOp::GainControl { duration, .. }
                    | EffectOp::Goad { duration }
                    | EffectOp::SwitchPt { duration }
                    | EffectOp::BecomeCopy { duration, .. }
                    | EffectOp::FreezeUntap { duration } => {
                        *duration = Some(dur);
                    }
                    EffectOp::DoubleOrTriple { spec } => {
                        spec.duration = Some(dur);
                    }
                    _ => {}
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 4a. "For each [other] opponent, create <tok> that's tapped and attacking that player [or a planeswalker they control]" (*Adeline*, *Shredder*)
    if let Some((is_other_opp, body)) = strip_prefix_word_ci(t, "for each opponent,")
        .map(|b| (false, b))
        .or_else(|| strip_prefix_word_ci(t, "for each other opponent,").map(|b| (true, b)))
        && starts_with_word_ci(body, "create ")
        && let Some(clean_body) = [
            "that player or a planeswalker they control",
            "that opponent or a planeswalker they control",
            "that player",
            "that opponent",
        ]
        .iter()
        .find_map(|pat| {
            if let Some(s) = strip_suffix_word_ci(body, pat) {
                return Some(s.to_string());
            }
            let needle = format!(" {pat},");
            if let Some(pos) = find_word_ci(body, &needle) {
                let left = body[..pos].trim_end();
                let right = body[pos + needle.len() - 1..].trim_start();
                return Some(format!("{left}{right}"));
            }
            None
        })
        && contains_word_ci(&clean_body, "tapped and attacking")
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        let mode = if is_other_opp {
            PerOpponentAttackMode::Other
        } else {
            PerOpponentAttackMode::All
        };
        if parse_token_creation_clause(&clean_body, span, ctx, state)
            && state.steps.len() == before + 1
            && let Some(st) = state.steps.get_mut(before)
        {
            match st.op {
                EffectOp::CreateToken {
                    ref mut per_opponent_tapped_attacking,
                    ..
                } => {
                    st.subject = you_sel();
                    *per_opponent_tapped_attacking = Some(mode);
                    return true;
                }
                EffectOp::CopyPermanent {
                    ref mut per_opponent_tapped_attacking,
                    ..
                } => {
                    *per_opponent_tapped_attacking = Some(mode);
                    return true;
                }
                _ => {}
            }
        }
        state.rollback(mark, ctx);
    }

    // 4. "For each <opponent|player>, <clauses>" and TurnOrder / ChooseRandomOpponent loops
    {
        let any_num_opponents = starts_with_word_ci(t, "for any number of opponents,");
        let loop_spec = if let Some(b) = strip_prefix_word_ci(t, "for each opponent,")
            .or_else(|| strip_prefix_word_ci(t, "for each of your opponents,"))
            .or_else(|| strip_prefix_word_ci(t, "for any number of opponents,"))
        {
            Some((LoopPlayersKind::EachOpponent, b, false, false, false))
        } else if let Some(b) = strip_prefix_word_ci(t, "for each other player,") {
            Some((LoopPlayersKind::EachOtherPlayer, b, false, false, false))
        } else if let Some(b) = strip_prefix_word_ci(t, "for each player,") {
            Some((LoopPlayersKind::EachPlayer, b, false, false, false))
        } else if let Some(b) = strip_prefix_word_ci(t, "for each other opponent,")
            .or_else(|| strip_prefix_word_ci(t, "for each opponent other than that player,"))
        {
            Some((LoopPlayersKind::EachOpponent, b, false, false, true))
        } else if let Some(b) = strip_prefix_word_ci(
            t,
            "for each opponent who didn't attack you during their last combat,",
        )
        .or_else(|| {
            strip_prefix_word_ci(
                t,
                "for each opponent who didn't attack you during their last turn,",
            )
        }) {
            Some((LoopPlayersKind::EachOpponent, b, false, true, false))
        } else if let Some(b) = strip_prefix_word_ci(t, "starting with you, each player")
            && !starts_with_word_ci(b, "votes")
        {
            Some((
                LoopPlayersKind::TurnOrderStartingWithYou,
                b,
                false,
                false,
                false,
            ))
        } else if let Some(b) = strip_prefix_word_ci(
            t,
            "starting with the next opponent in turn order, each opponent",
        )
        .or_else(|| {
            strip_prefix_word_ci(
                t,
                "starting with the next opponent in turn order, each player",
            )
        })
        .or_else(|| strip_prefix_word_ci(t, "each opponent in turn order,"))
        {
            Some((
                LoopPlayersKind::TurnOrderStartingWithNextOpponent,
                b,
                false,
                false,
                false,
            ))
        } else {
            strip_prefix_word_ci(t, "an opponent chosen at random")
                .map(|b| (LoopPlayersKind::ChooseRandomOpponent, b, true, false, false))
        };
        if let Some((
            loop_kind,
            body,
            choose_random_opponent,
            exclude_attacked_last_combat,
            exclude_event_player,
        )) = loop_spec
        {
            let initial_targets_len = state.targets.len();
            let mut sub_state =
                ParserState::new(state.context, state.trigger, state.quoted_compiler);
            sub_state.is_each_loop = true;
            sub_state.targets = state.targets.clone();
            sub_state.last_object = state.last_object.clone();
            sub_state.last_player = Some(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            });
            sub_state.defined_x = state.defined_x.clone();
            sub_state.bind_counter = state.bind_counter;

            let loop_subj = Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            };
            let loop_actor = Some(PlayerRef::EachLoopPlayer);
            let body_trimmed = body.trim();
            if let Some((choose_opt, choose_s)) = strip_prefix_word_ci(body_trimmed, "may choose")
                .map(|r| (true, r))
                .or_else(|| strip_prefix_word_ci(body_trimmed, "chooses").map(|r| (false, r)))
                .or_else(|| strip_prefix_word_ci(body_trimmed, "choose").map(|r| (false, r)))
                && !contains_word_ci(choose_s, "with the greatest")
                && !contains_word_ci(choose_s, "at random")
                && let Some(clean_obj) = strip_prefix_word_ci(choose_s, "a")
                    .or_else(|| strip_prefix_word_ci(choose_s, "an"))
            {
                let (not_yet_chosen, clean_obj) =
                    if let Some(r) = strip_suffix_word_ci(clean_obj, "that hasn't been chosen") {
                        (true, r)
                    } else {
                        (false, clean_obj)
                    };
                let toks = tokenize(clean_obj, 0);
                let cp = ctx.interner.checkpoint();
                if !toks.is_empty()
                    && let Some((mut f, used)) = parse_object_filter(
                        &toks,
                        ctx,
                        FilterOpts {
                            default_zone: ZoneMask::BATTLEFIELD,
                            allow_plural_and_disjunction: true,
                            strip_trailing_card: true,
                            ..Default::default()
                        },
                        &sub_state,
                    )
                    && used == toks.len()
                {
                    if f.zones.is_empty() {
                        f.zones = ZoneMask::BATTLEFIELD;
                    }
                    if not_yet_chosen {
                        f.extra.push(ObjectPredicate::NotYetChosenInStep);
                    }
                    let mut st = make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: loop_kind,
                            steps: Vec::new(),
                            choose_random_opponent,
                            exclude_attacked_last_combat,
                            exclude_event_player,
                            choose_object_to_bind: Some((Box::new(f), choose_opt)),
                        },
                        Selector::None,
                        span,
                    );
                    st.bind_as = Some("chosen_by_loop".to_string());
                    let idx = state.steps.len();
                    state.last_object = Some((
                        Ref::Binding {
                            name: "chosen_by_loop".to_string(),
                        },
                        idx,
                    ));
                    state.steps.push(st);
                    return true;
                }
                ctx.interner.rollback(cp);
            }
            let is_imperative_targeted = contains_word_ci(body_trimmed, "target")
                && ((starts_with_word_ci(body_trimmed, "exile")
                    && !starts_with_word_ci(body_trimmed, "exiles"))
                    || (starts_with_word_ci(body_trimmed, "destroy")
                        && !starts_with_word_ci(body_trimmed, "destroys"))
                    || (starts_with_word_ci(body_trimmed, "return")
                        && !starts_with_word_ci(body_trimmed, "returns"))
                    || (starts_with_word_ci(body_trimmed, "put")
                        && !starts_with_word_ci(body_trimmed, "puts"))
                    || (starts_with_word_ci(body_trimmed, "tap")
                        && !starts_with_word_ci(body_trimmed, "taps"))
                    || (starts_with_word_ci(body_trimmed, "untap")
                        && !starts_with_word_ci(body_trimmed, "untaps")));
            let eff_loop_actor = if is_imperative_targeted {
                None
            } else {
                loop_actor
            };
            let cp_loop = ctx.interner.checkpoint();
            let parsed_ok = if !body_trimmed.is_empty() {
                if parse_player_predicate(
                    loop_subj,
                    eff_loop_actor,
                    body_trimmed,
                    span,
                    ctx,
                    &mut sub_state,
                ) && !sub_state.steps.is_empty()
                {
                    true
                } else {
                    sub_state.steps.clear();
                    sub_state.targets.truncate(initial_targets_len);
                    if parse_clauses_into(body_trimmed, span.start, ctx, &mut sub_state) {
                        if !sub_state.steps.is_empty() {
                            true
                        } else if starts_with_word_ci(body_trimmed, "choose ")
                            && contains_word_ci(body_trimmed, "target")
                            && sub_state.targets.len() == initial_targets_len + 1
                        {
                            let mut sp = sub_state.targets.pop().unwrap();
                            sp.filter.extra.retain(|p| {
                                !matches!(
                                    p,
                                    ObjectPredicate::ControllerRef {
                                        player: PlayerRef::EachLoopPlayer
                                    } | ObjectPredicate::OwnerRef {
                                        player: PlayerRef::EachLoopPlayer
                                    }
                                )
                            });
                            if matches!(loop_kind, LoopPlayersKind::EachOpponent) {
                                if sp.filter.controller.is_none()
                                    && contains_word_ci(body_trimmed, "controls")
                                {
                                    sp.filter.controller = Some(RelativeControl::Opponent);
                                }
                                sp.per_opponent = true;
                            }
                            if any_num_opponents {
                                sp.min = 0;
                            }
                            sp.max = 99;
                            let idx = state.add_target(sp);
                            state.last_object =
                                Some((Ref::Target { index: idx }, state.steps.len()));
                            return true;
                        } else {
                            false
                        }
                    } else {
                        false
                    }
                }
            } else {
                false
            };
            if parsed_ok {
                let target_base = state.targets.len() as u16;
                state.bind_counter = sub_state.bind_counter;
                if matches!(loop_kind, LoopPlayersKind::EachOpponent)
                    && !choose_random_opponent
                    && !exclude_attacked_last_combat
                    && !exclude_event_player
                    && sub_state.targets.len() == initial_targets_len + 1
                    && sub_state.steps.len() == 1
                    && matches!(sub_state.steps[0].subject, Selector::Target { index } if index == target_base)
                    && !sub_state.targets[initial_targets_len]
                        .filter
                        .extra
                        .iter()
                        .any(|p| matches!(p, ObjectPredicate::ManaValueParity { .. }))
                    && sub_state.targets[initial_targets_len]
                        .filter
                        .extra
                        .iter()
                        .any(|p| {
                            matches!(
                                p,
                                ObjectPredicate::ControllerRef {
                                    player: PlayerRef::EachLoopPlayer
                                }
                            )
                        })
                {
                    let mut sp = sub_state.targets.pop().unwrap();
                    sp.filter.extra.retain(|p| {
                        !matches!(
                            p,
                            ObjectPredicate::ControllerRef {
                                player: PlayerRef::EachLoopPlayer
                            }
                        )
                    });
                    sp.filter.controller = Some(RelativeControl::Opponent);
                    sp.per_opponent = true;
                    if any_num_opponents {
                        sp.min = 0;
                    }
                    sp.max = 99;
                    state.targets.push(sp);
                    let mut st = sub_state.steps.pop().unwrap();
                    st.subject = Selector::Target { index: target_base };
                    state.push_step(st, true);
                    return true;
                }
                if sub_state.targets.len() > initial_targets_len {
                    state
                        .targets
                        .extend(sub_state.targets.drain(initial_targets_len..));
                }
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: loop_kind,
                            steps: sub_state.steps,
                            choose_random_opponent,
                            exclude_attacked_last_combat,
                            exclude_event_player,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
            ctx.interner.rollback(cp_loop);
        }
    }

    // Soulfire Eruption: "For each of them, exile the top card of your library, then ~ deals damage equal to that card's mana value to that permanent or player"
    if eq_ci(
        t,
        "for each of them, exile the top card of your library, then ~ deals damage equal to that card's mana value to that permanent or player",
    ) && let Some((Ref::Target { index }, _)) = &state.last_object
    {
        let idx = *index;
        state.push_step(
            make_step(
                EffectOp::Damage {
                    source: None,
                    also_players: None,
                    divided: false,
                    excess_to_controller: false,
                    excess_to_controller_if_trample: false,
                    or_planeswalker_controlled_by: None,
                    damage_attacked_target_by_self: false,
                    soulfire_exile_damage_per_target: true,
                    each_creature_deals: None,
                },
                Selector::Target { index: idx },
                span,
            ),
            false,
        );
        state.last_object = Some((Ref::Target { index: idx }, state.steps.len() - 1));
        return true;
    }

    // Mysterious Stranger: "for each graveyard with <filter> in it, exile target <filter2> from that graveyard"
    if let Some(after_gy) = strip_prefix_word_ci(t, "for each graveyard with")
        && let Some(in_it_pos) = find_word_ci(after_gy, " in it, exile ")
    {
        let tgt_raw = after_gy[in_it_pos + " in it, exile ".len()..].trim();
        let tgt_clean = strip_suffix_word_ci(tgt_raw, "from that graveyard").unwrap_or(tgt_raw);
        let ttoks = tokenize(tgt_clean, 0);
        let cp = ctx.interner.checkpoint();
        if !ttoks.is_empty()
            && let Some((mut sp, used)) = parse_target_spec(&ttoks, ctx, state)
            && used == ttoks.len()
        {
            sp.filter.zones = ZoneMask::GRAVEYARD;
            sp.min = 0;
            sp.max = 99;
            let idx = state.add_target(sp);
            let mut st = make_step(
                EffectOp::Exile {
                    select: SelectionMod::default(),
                    duration: None,
                    until_source_leaves: false,
                    until_opponent_becomes_monarch: false,
                    exile_all_except_bottom: false,
                    face_down: false,
                    look_only: false,
                    exile_with_counters: None,
                },
                Selector::Target { index: idx },
                span,
            );
            st.bind_as = Some("exiled".to_string());
            state.push_step(st, true);
            return true;
        }
        ctx.interner.rollback(cp);
    }

    // 4b-pre. "For each <object filter>, <effect referencing that object/it>" (*Redoubled Stormsinger*)
    if starts_with_word_ci(t, "for each")
        && let Some((hdr, body)) = split_at_top_level_comma(t)
        && let Some(fe_filter_str) = strip_prefix_word_ci(hdr.trim(), "for each")
        && state.last_object.is_none()
        && (contains_word_ci(body, "that ")
            || contains_word_ci(body, "it")
            || contains_word_ci(body, "them"))
    {
        let toks = tokenize(fe_filter_str, 0);
        let cp = ctx.interner.checkpoint();
        if !toks.is_empty()
            && let Some((mut fe_filter, used)) = parse_object_filter(
                &toks,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::BATTLEFIELD,
                    allow_plural_and_disjunction: true,
                    ..Default::default()
                },
                state,
            )
            && used == toks.len()
        {
            if fe_filter.zones.is_empty() {
                fe_filter.zones = ZoneMask::BATTLEFIELD;
            }
            let before = state.steps.len();
            let mark = state.mark(ctx);
            state.last_object = Some((Ref::EventObject, 0));
            if parse_clauses_into(body.trim(), span.start, ctx, state)
                && state.steps.len() == before + 1
                && matches!(state.steps[before].subject, Selector::EventObject)
            {
                state.steps[before].subject = Selector::All {
                    filter: Box::new(fe_filter),
                };
                if let Some(ref b) = state.steps[before].bind_as {
                    state.last_object = Some((Ref::Binding { name: b.clone() }, before));
                } else {
                    state.last_object = None;
                }
                return true;
            }
            state.rollback(mark, ctx);
        }
        ctx.interner.rollback(cp);
    }

    // 4b. Leading "For each <count expr>, <effect(s)>" (*Eumidian Hatchery*, *Selvala, Explorer Returned*)
    if starts_with_word_ci(t, "for each")
        && let Some((hdr, body)) = split_at_top_level_comma(t)
        && let Some(fe_amt) = parse_amount_str(hdr.trim(), ctx, state)
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        if parse_clauses_into(body.trim(), span.start, ctx, state) && state.steps.len() > before {
            if state.steps.len() == before + 1
                && contains_word_ci(hdr, "exiled this way")
                && matches!(state.steps[before].op, EffectOp::CopyPermanent { .. })
                && matches!(state.steps[before].subject, Selector::Binding { .. })
                && state.steps[before].amount.is_none()
            {
                return true;
            }
            let mut all_ok = true;
            for st in &mut state.steps[before..] {
                let existing = st.amount.take();
                let combined = match existing.as_deref() {
                    None | Some(Amount::Const { n: 1 }) => Some(Box::new(fe_amt.clone())),
                    Some(Amount::Const { n }) => Some(Box::new(Amount::Mul {
                        factor: *n,
                        of: Box::new(fe_amt.clone()),
                    })),
                    _ => None,
                };
                if let Some(new_amt) = combined {
                    st.amount = Some(new_amt);
                } else {
                    all_ok = false;
                    break;
                }
            }
            if all_ok {
                return true;
            }
        }
        state.rollback(mark, ctx);
    }

    // 5. "If you do, <effect>" / "If you don't, <effect>" / "Otherwise, <effect>"
    if let Some(after) = strip_prefix_word_ci(t, "if you do,")
        .or_else(|| strip_prefix_word_ci(t, "if the player does,"))
        .or_else(|| strip_prefix_word_ci(t, "if that player does,"))
        .or_else(|| strip_prefix_word_ci(t, "if they do,"))
        .or_else(|| strip_prefix_word_ci(t, "if a creature is destroyed this way,"))
        .or_else(|| strip_prefix_word_ci(t, "if that creature is destroyed this way,"))
        .or_else(|| strip_prefix_word_ci(t, "if a permanent is destroyed this way,"))
        .or_else(|| strip_prefix_word_ci(t, "if that creature dies this way,"))
        .or_else(|| strip_prefix_word_ci(t, "if it dies this way,"))
        && let Some(opt_idx) = state
            .last_optional_step
            .or_else(|| state.steps.iter().rposition(|s| s.optional.is_some()))
            .or_else(|| state.steps.len().checked_sub(1))
    {
        let use_source_exiled = state.steps[opt_idx].optional.is_none()
            && matches!(state.steps[opt_idx].op, EffectOp::Exile { .. })
            && matches!(state.steps[opt_idx].subject, Selector::SelfObj);
        let is_destroy_way = contains_word_ci(t, "destroyed this way");
        let is_dies_way = contains_word_ci(t, "dies this way");
        if (is_destroy_way || is_dies_way)
            && matches!(state.steps[opt_idx].op, EffectOp::Destroy { .. })
            && state.steps[opt_idx].bind_as.is_none()
        {
            let bname = state.alloc_bind_name("b");
            state.steps[opt_idx].bind_as = Some(bname.clone());
            state.last_object = Some((Ref::Binding { name: bname }, opt_idx));
        }
        let dies_bind_name = if is_dies_way {
            state.steps[opt_idx].bind_as.clone()
        } else {
            None
        };
        let before = state.steps.len();
        let mark_do = state.mark(ctx);
        if parse_clauses_into(after, span.start, ctx, state) && state.steps.len() > before {
            for st in &mut state.steps[before..] {
                if is_destroy_way
                    && let Some(ref mut a) = st.amount
                    && let Amount::Stat { ref mut lki, .. } = **a
                {
                    *lki = true;
                }
                st.gate = Some(if let Some(ref bname) = dies_bind_name {
                    StepGate::Condition {
                        condition: Box::new(Condition::DiedThisWay {
                            of: Some(Ref::Binding {
                                name: bname.clone(),
                            }),
                        }),
                    }
                } else if use_source_exiled {
                    StepGate::Condition {
                        condition: Box::new(Condition::SourceExiledThisWay),
                    }
                } else {
                    StepGate::IfPrecedingAccepted {
                        step_index: opt_idx as u16,
                    }
                });
            }
            return true;
        }
        state.rollback(mark_do, ctx);
    }
    if let Some(after) = strip_prefix_word_ci(t, "otherwise,")
        && state.steps.len() > state.prev_sentence_step_start
        && !state
            .last_optional_step
            .is_some_and(|idx| idx >= state.prev_sentence_step_start)
        && let Some(StepGate::Condition { condition }) =
            state.steps[state.prev_sentence_step_start].gate.clone()
        && state.steps[state.prev_sentence_step_start..]
            .iter()
            .all(|s| {
                matches!(
                    &s.gate,
                    Some(StepGate::Condition { condition: c }) if c == &condition
                )
            })
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        if let Some((Ref::Binding { .. }, idx)) = &state.last_object
            && *idx >= state.prev_sentence_step_start
            && let Some(then0) = state.steps.get(state.prev_sentence_step_start)
        {
            state.last_object = match &then0.subject {
                Selector::Target { index } => Some((
                    Ref::Target { index: *index },
                    state.prev_sentence_step_start,
                )),
                Selector::SelfObj => Some((Ref::SelfObj, state.prev_sentence_step_start)),
                Selector::AttachedTo => Some((Ref::AttachedTo, state.prev_sentence_step_start)),
                Selector::EventObject => Some((Ref::EventObject, state.prev_sentence_step_start)),
                Selector::Binding { name } => Some((
                    Ref::Binding { name: name.clone() },
                    state.prev_sentence_step_start,
                )),
                _ => None,
            };
        }
        if parse_clauses_into(after, span.start, ctx, state) && state.steps.len() > before {
            let else_steps = state.steps.split_off(before);
            let mut then_steps = state.steps.split_off(state.prev_sentence_step_start);
            for st in &mut then_steps {
                st.gate = None;
            }
            state.push_step(
                make_step(
                    EffectOp::ConditionalSequence {
                        condition,
                        then_steps,
                        else_steps,
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    let didnt_put_bf_after =
        strip_prefix_word_ci(t, "if you don't put the card onto the battlefield,")
            .or_else(|| strip_prefix_word_ci(t, "if you don't put that card onto the battlefield,"))
            .or_else(|| strip_prefix_word_ci(t, "if you don't put it onto the battlefield,"))
            .or_else(|| strip_prefix_word_ci(t, "if you didn't put it onto the battlefield,"));
    if let Some((after, is_didnt_put_bf, is_cant)) = strip_prefix_word_ci(t, "if you don't,")
        .or_else(|| strip_prefix_word_ci(t, "if the player doesn't,"))
        .or_else(|| strip_prefix_word_ci(t, "if that player doesn't,"))
        .or_else(|| strip_prefix_word_ci(t, "if they don't,"))
        .or_else(|| strip_prefix_word_ci(t, "otherwise,"))
        .map(|a| (a, false, false))
        .or_else(|| {
            strip_prefix_word_ci(t, "if you can't,")
                .or_else(|| strip_prefix_word_ci(t, "if that player can't,"))
                .or_else(|| strip_prefix_word_ci(t, "if they can't,"))
                .map(|a| (a, false, true))
        })
        .or_else(|| didnt_put_bf_after.map(|a| (a, true, false)))
        && let Some(opt_idx) = state
            .last_optional_step
            .or_else(|| state.steps.iter().rposition(|s| s.optional.is_some()))
            .or_else(|| {
                if !is_cant
                    && let Some(last_idx) = state.steps.len().checked_sub(1)
                    && matches!(state.steps[last_idx].op, EffectOp::CastFree { .. })
                {
                    state.steps[last_idx].optional = Some(OptionalSpec {
                        chooser: PlayerRef::You,
                        cost: Vec::new(),
                        mode: OptionalMode::DoIfPaid,
                    });
                    state.last_optional_step = Some(last_idx);
                    Some(last_idx)
                } else {
                    None
                }
            })
            .or_else(|| is_cant.then(|| state.steps.len().checked_sub(1)).flatten())
    {
        let use_cond_gate = is_didnt_put_bf
            && matches!(
                state.steps[opt_idx].gate,
                Some(StepGate::Condition { .. } | StepGate::Combined { .. })
            );
        let saved_last_obj = state.last_object.clone();
        if (use_cond_gate
            || matches!(&state.last_object, Some((Ref::Binding { .. }, idx)) if *idx == opt_idx))
            && let Selector::Binding { ref name } = state.steps[opt_idx].subject
        {
            state.last_object = Some((Ref::Binding { name: name.clone() }, opt_idx));
        }
        let before = state.steps.len();
        let ok = parse_clauses_into(after, span.start, ctx, state) && state.steps.len() > before;
        if !ok {
            state.last_object = saved_last_obj;
        } else {
            for st in &mut state.steps[before..] {
                st.gate = Some(if use_cond_gate {
                    StepGate::Condition {
                        condition: Box::new(Condition::DidntPutOntoBattlefieldThisWay),
                    }
                } else {
                    StepGate::IfPrecedingDeclined {
                        step_index: opt_idx as u16,
                    }
                });
            }
            return true;
        }
    }

    // 6. General leading "If <condition>, <clauses>"
    if starts_with_word_ci(t, "if ")
        && !(eq_ci(
            t,
            "if it's a permanent card, they put it onto the battlefield",
        ) && state.steps.last().is_some_and(|prev| {
            matches!(prev.op, EffectOp::Reveal { .. })
                && matches!(
                    prev.subject,
                    Selector::LibraryTop {
                        player: Some(PlayerRef::OwnerOf { .. })
                    }
                )
        }))
        && let Some((cond_part, body_part)) = split_at_top_level_comma(t)
    {
        let targets_before_cond = state.targets.len();
        let saved_last_obj_if = state.last_object.clone();
        let mark = state.mark(ctx);
        if let Some(mut cond) = parse_condition_str(cond_part, ctx, state) {
            let before = state.steps.len();
            if contains_ascii_ci(cond_part.as_bytes(), b"the exiled card")
                && let Condition::Compare { left, .. } = &mut cond
                && let Amount::Stat {
                    of: of_ref @ Ref::EventObject,
                    stat: mtg_ir::StatKind::ManaValue,
                    ..
                } = left.as_mut()
                && let Some(ex_idx) = state.steps[..before]
                    .iter()
                    .rposition(|s| matches!(s.op, EffectOp::Exile { .. }))
            {
                let b = if let Some(existing) = state.steps[ex_idx].bind_as.clone() {
                    existing
                } else {
                    let name = state.alloc_bind_name("exiled");
                    state.steps[ex_idx].bind_as = Some(name.clone());
                    name
                };
                *of_ref = Ref::Binding { name: b };
            }
            let saved_cmp = state.last_compare.take();
            let saved_cap = state.last_target_counter_cap.take();
            if let Condition::Compare { left, right, .. } = &cond {
                state.last_compare = Some((*left.clone(), *right.clone()));
            }
            if let Condition::TargetHasFewerCountersThan { counter, max } = &cond {
                let idx = if state.targets.len() > targets_before_cond {
                    (state.targets.len() - 1) as u16
                } else {
                    state.add_target(TargetSpec {
                        kind: TargetKind::Player,
                        player: Some(PlayerFilter {
                            relation: PlayerRelation::Any,
                        }),
                        min: 1,
                        max: 1,
                        ..default_target_spec()
                    })
                };
                let pref = PlayerRef::Target { index: idx };
                state.last_player = Some(Selector::Target { index: idx });
                state.last_target_counter_cap = Some((pref, *counter, *max as i32));
            }
            let targets_before = state.targets.len();
            let parsed = parse_clauses_into(body_part, span.start, ctx, state);
            state.last_compare = saved_cmp;
            state.last_target_counter_cap = saved_cap;
            if parsed && state.steps.len() > before {
                if ends_with_ci(cond_part.as_bytes(), b" on it")
                    && let Condition::Compare { left, .. } = &mut cond
                    && let Amount::CountersOn {
                        of: of_ref @ Ref::SelfObj,
                        ..
                    } = left.as_mut()
                    && state.steps[..before].last().is_some_and(|prev| {
                        matches!(prev.op, EffectOp::PutCounters { .. })
                            && matches!(prev.subject, Selector::SelfObj)
                            && prev.bind_as.is_none()
                    })
                {
                    let b = state.alloc_bind_name("ctr");
                    if let Some(prev) = state.steps[..before].last_mut() {
                        prev.bind_as = Some(b.clone());
                    }
                    *of_ref = Ref::Binding { name: b };
                }
                for st in &mut state.steps[before..] {
                    attach_gate_condition(&mut st.gate, cond.clone());
                }
                for tgt in &mut state.targets[targets_before..] {
                    if tgt.condition.is_none() {
                        tgt.condition = Some(Box::new(cond.clone()));
                    }
                }
                if matches!(
                    &cond,
                    Condition::MatchesFilter {
                        target: Some(Ref::Binding { .. }),
                        ..
                    }
                ) {
                    state.last_object = saved_last_obj_if;
                }
                return true;
            }
        }
        state.rollback(mark, ctx);
    }

    false
}

fn detect_reflexive_event_filter(hdr: &str) -> Option<ReflexiveEventFilter> {
    let low = hdr.to_ascii_lowercase();
    if low == "when you do" {
        Some(ReflexiveEventFilter::WhenYouDo)
    } else if low.contains("sacrificed this way")
        || (low.contains("sacrifice") && low.contains("this way"))
    {
        Some(ReflexiveEventFilter::SacrificedThisWay)
    } else if low.contains("died this way")
        || low.contains("dies this way")
        || low.contains("dealt damage this way dies")
    {
        Some(ReflexiveEventFilter::DiedThisWay)
    } else if low.contains("discarded this way")
        || (low.contains("discard") && low.contains("this way"))
    {
        Some(ReflexiveEventFilter::DiscardedThisWay)
    } else if low.contains("exiled this way") || (low.contains("exile") && low.contains("this way"))
    {
        Some(ReflexiveEventFilter::ExiledThisWay)
    } else if low.contains("counter") && low.contains("removed this way") {
        Some(ReflexiveEventFilter::RemovedCounterThisWay)
    } else {
        None
    }
}

fn extract_reflexive_object_filter(
    hdr: &str,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> Option<Box<ObjectFilter>> {
    let rest = strip_prefix_word_ci(hdr.trim(), "whenever")
        .or_else(|| strip_prefix_word_ci(hdr.trim(), "when"))?
        .trim();
    let subj_raw = strip_prefix_word_ci(rest, "one or more")
        .or_else(|| strip_prefix_word_ci(rest, "an"))
        .or_else(|| strip_prefix_word_ci(rest, "a"))?
        .trim();
    let noun = [
        " is exiled this way",
        " are exiled this way",
        " is discarded this way",
        " are discarded this way",
        " is sacrificed this way",
        " are sacrificed this way",
        " dealt damage this way dies",
        " dies this way",
        " die this way",
        " died this way",
    ]
    .iter()
    .find_map(|suf| strip_suffix_word_ci(subj_raw, suf.trim()))?
    .trim();
    let low = noun.to_ascii_lowercase();
    if low.is_empty()
        || matches!(
            low.as_str(),
            "card" | "cards" | "permanent" | "permanents" | "spell" | "spells" | "it" | "they"
        )
    {
        return None;
    }
    let toks = tokenize(noun, 0);
    if toks.is_empty() {
        return None;
    }
    let cp = ctx.interner.checkpoint();
    if let Some((f, used)) = parse_object_filter(
        &toks,
        ctx,
        FilterOpts {
            default_zone: ZoneMask::empty(),
            strip_trailing_card: true,
            allow_plural_and_disjunction: true,
            ..Default::default()
        },
        state,
    ) && used == toks.len()
        && f != ObjectFilter::default()
    {
        return Some(Box::new(f));
    }
    ctx.interner.rollback(cp);
    None
}

fn attach_reflexive_trigger(
    ev_filter: ReflexiveEventFilter,
    obj_filter: Option<Box<ObjectFilter>>,
    body: &str,
    _span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if state.steps.is_empty() {
        return false;
    }
    let mut sub_state = ParserState::new(
        AbilityContext::Triggered,
        state.trigger,
        state.quoted_compiler,
    );
    sub_state.last_object = state.last_object.clone();
    sub_state.last_player = state.last_player.clone();
    sub_state.defined_x = state
        .defined_x
        .clone()
        .or_else(|| Some(resolve_that_many_amount(state)));
    sub_state.bind_counter = state.bind_counter;

    let trimmed_body = body.trim();
    if trimmed_body.is_empty() {
        return false;
    }
    let sents = split_sentences(trimmed_body, 0);
    for sent in &sents {
        let st = sent.text.trim();
        if st.is_empty() {
            continue;
        }
        sub_state.prev_sentence_step_start = sub_state.last_sentence_step_start;
        sub_state.last_sentence_step_start = sub_state.steps.len();
        let mark = sub_state.mark(ctx);
        if parse_core_imperative(st, sent.span, ctx, &mut sub_state) {
            continue;
        }
        sub_state.rollback(mark, ctx);
        let mark2 = sub_state.mark(ctx);
        if parse_clauses_into(st, sent.span.start, ctx, &mut sub_state) {
            continue;
        }
        sub_state.rollback(mark2, ctx);
        return false;
    }
    if sub_state.steps.is_empty() {
        return false;
    }
    state.bind_counter = sub_state.bind_counter;
    let target_idx = match ev_filter {
        ReflexiveEventFilter::DiscardedThisWay => state.steps.iter().rposition(|s| {
            matches!(
                s.op,
                EffectOp::Discard { .. } | EffectOp::DiscardHand { .. }
            )
        }),
        ReflexiveEventFilter::SacrificedThisWay => state
            .steps
            .iter()
            .rposition(|s| matches!(s.op, EffectOp::Sacrifice { .. })),
        ReflexiveEventFilter::ExiledThisWay => state
            .steps
            .iter()
            .rposition(|s| matches!(s.op, EffectOp::Exile { .. })),
        ReflexiveEventFilter::RemovedCounterThisWay => state.steps.iter().rposition(|s| {
            matches!(
                s.op,
                EffectOp::PutCounters {
                    remove_instead_of_add: true,
                    ..
                }
            )
        }),
        ReflexiveEventFilter::WhenYouDo | ReflexiveEventFilter::DiedThisWay => None,
    }
    .unwrap_or_else(|| state.steps.len() - 1);
    let last = &mut state.steps[target_idx];
    last.reflexive_trigger = Some(Box::new(ReflexiveTriggerSpec {
        targets: sub_state.targets,
        effect: sub_state.steps,
        modal: None,
        text: Some(body.to_string()),
        event_filter: Some(ev_filter),
        object_filter: obj_filter,
    }));
    true
}

fn parse_delayed_trigger_sentence(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    // Strip "until end of turn, " if present for inline delayed triggers
    let (dur_inline, trig_text) =
        if let Some(after_eot) = strip_prefix_word_ci(t, "until end of turn,") {
            (Some(DelayedInlineDuration::ThisTurn), after_eot.trim())
        } else if let Some(after_ny) = strip_prefix_word_ci(t, "until your next turn,") {
            (
                Some(DelayedInlineDuration::UntilYourNextTurn),
                after_ny.trim(),
            )
        } else {
            (None, t)
        };

    if dur_inline.is_none()
        && let Some(after_mp) =
            strip_prefix_word_ci(trig_text, "at the beginning of your next main phase,")
        && let Some(after_add) = strip_prefix_word_ci(after_mp, "add an amount of")
        && let Some(eq_pos) = find_word_ci(after_add, " equal to ")
    {
        let pip_s = after_add[..eq_pos].trim();
        let expr_s = after_add[eq_pos + " equal to ".len()..].trim();
        let syms = parse_mana_pip_sequence(pip_s);
        if let Some(syms) = syms
            && syms.len() == 1
        {
            let prev_len = state.steps.len();
            if prev_len > 0
                && matches!(state.steps[prev_len - 1].op, EffectOp::CounterSpell { .. })
                && state.steps[prev_len - 1].bind_as.is_none()
                && (contains_word_ci(expr_s, "that spell") || contains_word_ci(expr_s, "its"))
            {
                let bname = state.alloc_bind_name("b");
                state.steps[prev_len - 1].bind_as = Some(bname.clone());
                state.last_object = Some((Ref::Binding { name: bname }, prev_len - 1));
            }
            if let Some(mut amt) = parse_amount_str(expr_s, ctx, state) {
                if let Amount::Stat { ref mut lki, .. } = amt
                    && state
                        .steps
                        .last()
                        .is_some_and(|s| matches!(s.op, EffectOp::CounterSpell { .. }))
                {
                    *lki = true;
                }
                state.push_step(
                    make_step(
                        EffectOp::GrantPlayer {
                            rules: Vec::new(),
                            duration: None,
                            extra_land_plays: None,
                            next_spell_types: None,
                            spend_mana_as_any_color_top_of_library: false,
                            steal_opponent_entering_creatures_until_eot: false,
                            opponents_spells_cost_more_until_next_turn: None,
                            attack_tax_until_your_next_turn: None,
                            next_spell_cost_reduction_generic: None,
                            next_creature_enters_with_plus_counters: None,
                            next_main_phase_add_mana: Some((syms[0], Box::new(amt))),
                            double_tokens_this_turn: false,
                            flash_cast_condition: None,
                            next_spell_cascade: None,
                            extra_loyalty_activations_this_turn: None,
                            planar_action: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
    }

    if state.delayed_depth >= 4 || state.clause_split_budget == 0 {
        return false;
    }
    state.clause_split_budget -= 1;
    let trig_base = span.start + (t.len() - trig_text.len()) as u32;
    let mut hdr_next_turn = false;
    let mut matched_hdr: Option<&str> = None;
    let mut trailing_phase_hit: Option<(TriggerDef, bool, &str)> = None;
    if dur_inline.is_none()
        && !starts_with_word_ci(trig_text, "at the beginning of")
        && !starts_with_word_ci(trig_text, "when ")
        && !starts_with_word_ci(trig_text, "whenever ")
        && trig_text.matches('"').count() % 2 == 0
    {
        for suf in [
            "at the beginning of the next turn's upkeep",
            "at the beginning of the upkeep of the next turn",
            "at the beginning of your next end step",
            "at the beginning of the next end step",
            "at the beginning of the end step",
            "at the beginning of your next upkeep",
            "at the beginning of the next upkeep",
            "at the beginning of the upkeep",
            "at the beginning of your next first main phase",
            "at the beginning of your next precombat main phase",
            "at the beginning of your next combat phase",
            "at the beginning of the next combat phase",
            "at the beginning of that combat",
            "at the beginning of combat",
            "at the end of that combat",
            "at the end of combat",
            "at end of combat",
        ] {
            if let Some(before) = strip_suffix_word_ci(trig_text, suf) {
                let eff = before.trim_end_matches(',').trim();
                if !eff.is_empty()
                    && let Some((pt, nt)) = parse_delayed_phase_header(suf)
                {
                    trailing_phase_hit = Some((pt, nt, eff));
                    break;
                }
            }
        }
    }

    let (trig, eff_text, eff_offset) = if let Some((pt, nt, eff)) = trailing_phase_hit {
        hdr_next_turn = nt;
        (pt, eff, trig_base)
    } else if let Some(tp) = parse_trigger_header(trig_text, trig_base, ctx)
        && let Some(tr) = tp.trigger
    {
        let eff_rel = tp.effect_start.saturating_sub(trig_base) as usize;
        let et = trig_text.get(eff_rel..).unwrap_or("").trim();
        matched_hdr = trig_text.get(..eff_rel);
        (tr, et, tp.effect_start)
    } else if let Some((hdr, body)) = split_at_top_level_comma(trig_text)
        && let Some((phase_trig, nt)) = parse_delayed_phase_header(hdr)
    {
        hdr_next_turn = nt;
        let eff_rel = trig_text.len() - body.len();
        matched_hdr = Some(hdr);
        (phase_trig, body.trim(), trig_base + eff_rel as u32)
    } else if let Some((hdr, body)) = split_at_top_level_comma(trig_text)
        && let Some(hdr_no_turn) = strip_suffix_word_ci(hdr, "this turn")
        && let rebuilt = format!("{hdr_no_turn}, {body}")
        && let Some(tp) = parse_trigger_header(&rebuilt, trig_base, ctx)
        && let Some(tr) = tp.trigger
    {
        let eff_rel = tp.effect_start.saturating_sub(trig_base) as usize;
        let _ = eff_rel;
        matched_hdr = Some(hdr);
        let body_off = (trig_text.len() - body.len()) as u32;
        (tr, body.trim(), trig_base + body_off)
    } else if state.it_ref().is_some()
        && let Some((hdr, body)) = split_at_top_level_comma(trig_text)
        && let Some((kw, after_that)) = strip_prefix_word_ci(hdr, "when that")
            .map(|r| ("when", r))
            .or_else(|| strip_prefix_word_ci(hdr, "whenever that").map(|r| ("whenever", r)))
        && let Some(ev_rest) = strip_prefix_word_ci(after_that, "token")
            .or_else(|| strip_prefix_word_ci(after_that, "creature"))
            .or_else(|| strip_prefix_word_ci(after_that, "permanent"))
            .or_else(|| strip_prefix_word_ci(after_that, "artifact"))
            .or_else(|| strip_prefix_word_ci(after_that, "enchantment"))
            .or_else(|| strip_prefix_word_ci(after_that, "land"))
        && let rebuilt = format!("{kw} a permanent {ev_rest}, {body}")
        && let Some(tp) = parse_trigger_header(&rebuilt, trig_base, ctx)
        && let Some(mut tr) = tp.trigger
    {
        if let Some(TriggerSubject::Filter { ref mut filter }) = tr.filter.object {
            filter.types_any = CardTypeMask::empty();
        }
        matched_hdr = Some(hdr);
        let body_off = (trig_text.len() - body.len()) as u32;
        (tr, body.trim(), trig_base + body_off)
    } else {
        return false;
    };
    if eff_text.is_empty() {
        return false;
    }

    let sub_trigger = if matches!(trig.event, EventKind::PhaseBegin) {
        state.trigger
    } else {
        Some(&trig)
    };
    let mut sub_state = ParserState::new(
        AbilityContext::Triggered,
        sub_trigger,
        state.quoted_compiler,
    );
    sub_state.delayed_depth = state.delayed_depth + 1;
    sub_state.clause_split_budget = state.clause_split_budget;
    let hdr_uses_it = matched_hdr.is_some_and(|h| {
        contains_word_ci(h, "that")
            || contains_word_ci(h, "it")
            || contains_word_ci(h, "them")
            || contains_word_ci(h, "those")
    });
    sub_state.last_object = if matches!(trig.event, EventKind::ZoneChange) && hdr_uses_it {
        Some((Ref::EventObject, 0))
    } else {
        state.last_object.clone()
    };
    sub_state.last_player = state.last_player.clone();
    sub_state.defined_x = state.defined_x.clone();
    sub_state.bind_counter = state.bind_counter;
    sub_state.parent_exile_bindings = state.parent_exile_bindings.clone();
    sub_state.parent_exile_selectors = state.parent_exile_selectors.clone();
    for s in &state.steps {
        if matches!(s.op, EffectOp::Exile { .. }) {
            if let Some(ref b) = s.bind_as {
                sub_state.parent_exile_bindings.push(b.clone());
            }
            sub_state.parent_exile_selectors.push(s.subject.clone());
        }
    }

    let mut return_target_and_sacrificed_at_upkeep = false;
    if contains_word_ci(eff_text, "the sacrificed") && starts_with_word_ci(eff_text, "return ") {
        let tapped = contains_word_ci(eff_text, "tapped");
        let under_your = contains_word_ci(eff_text, "under your control");
        let subj = state
            .it_ref()
            .map(|r| ref_to_selector(&r))
            .unwrap_or(Selector::Target { index: 0 });
        sub_state.push_step(
            make_step(
                EffectOp::Move {
                    from: Some(Zone::Graveyard),
                    to: Some(Zone::Battlefield),
                    select: SelectionMod::default(),
                    tapped,
                    under_your_control: under_your,
                    topmost_only: false,
                    may_shuffle: false,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                subj,
                span,
            ),
            false,
        );
        return_target_and_sacrificed_at_upkeep = true;
    } else {
        let ok = parse_clauses_into(eff_text, eff_offset, ctx, &mut sub_state);
        state.clause_split_budget = sub_state.clause_split_budget;
        if !ok || sub_state.steps.is_empty() {
            return false;
        }
    }
    state.bind_counter = sub_state.bind_counter;
    let sub = EffectParse {
        steps: sub_state.steps,
        targets: sub_state.targets,
        modal: None,
        unparsed: sub_state.unparsed,
    };

    let next_turn = hdr_next_turn
        || (dur_inline.is_none() && contains_word_ci(trig_text, "during your next turn"));

    let is_inline = dur_inline.is_some() || !matches!(trig.event, EventKind::PhaseBegin);
    let hdr_uses_it = matched_hdr.is_some_and(|h| {
        contains_word_ci(h, "that")
            || contains_word_ci(h, "it")
            || contains_word_ci(h, "them")
            || contains_word_ci(h, "those")
    });
    let subj = if is_inline
        && hdr_uses_it
        && let Some(r) = state.it_ref()
    {
        ref_to_selector(&r)
    } else {
        Selector::None
    };

    let mut trig = trig;
    if trig.spell_delayed.is_none() {
        trig.spell_delayed = dur_inline.and_then(|d| match d {
            DelayedInlineDuration::ThisTurn => Some(mtg_ir::SpellDelayedDuration::ThisTurn),
            DelayedInlineDuration::UntilYourNextTurn => {
                Some(mtg_ir::SpellDelayedDuration::UntilYourNextTurn)
            }
            DelayedInlineDuration::NextCombat => None,
        });
    }

    let inline_spec = if is_inline {
        Some(DelayedInlineTriggerSpec {
            duration: dur_inline.unwrap_or(DelayedInlineDuration::ThisTurn),
            sub_trigger_index: None,
            bind_subject_as_watched: !matches!(subj, Selector::None),
        })
    } else {
        None
    };

    state.push_step(
        make_step(
            EffectOp::DelayedTrigger {
                delayed: Some(DelayedTriggerPayload {
                    trigger: Box::new(trig),
                    effect: sub.steps,
                    targets: sub.targets,
                    next_turn,
                }),
                inline_delayed: inline_spec,
                return_target_and_sacrificed_at_upkeep,
            },
            subj,
            span,
        ),
        false,
    );
    true
}

fn parse_delayed_phase_header(hdr: &str) -> Option<(TriggerDef, bool)> {
    let low = hdr.trim().to_ascii_lowercase();
    let (phase, scope, spell_delayed, next_turn) = if low == "at the beginning of the next end step"
        || low == "at the beginning of the end step"
    {
        (
            GamePhase::EndStep,
            None,
            Some(mtg_ir::SpellDelayedDuration::ThisTurn),
            false,
        )
    } else if low == "at the beginning of your next end step"
        || low == "at the beginning of that turn's end step"
    {
        (
            GamePhase::EndStep,
            Some(mtg_ir::TriggerScope::ControllerTurn),
            None,
            false,
        )
    } else if low == "at the beginning of the next turn's upkeep"
        || low == "at the beginning of the upkeep of the next turn"
    {
        (GamePhase::Upkeep, None, None, true)
    } else if low == "at the beginning of your next upkeep" {
        (
            GamePhase::Upkeep,
            Some(mtg_ir::TriggerScope::ControllerTurn),
            None,
            true,
        )
    } else if low == "at the beginning of the next upkeep"
        || low == "at the beginning of the upkeep"
    {
        (
            GamePhase::Upkeep,
            None,
            Some(mtg_ir::SpellDelayedDuration::NextUpkeep),
            false,
        )
    } else if low == "at the beginning of your next first main phase"
        || low == "at the beginning of your next precombat main phase"
    {
        (
            GamePhase::Main1,
            Some(mtg_ir::TriggerScope::ControllerTurn),
            None,
            false,
        )
    } else if low == "at end of combat"
        || low == "at the end of combat"
        || low == "at the end of that combat"
    {
        (GamePhase::EndCombat, None, None, false)
    } else if low == "at the beginning of combat"
        || low == "at the beginning of the next combat phase"
        || low == "at the beginning of that combat"
    {
        (GamePhase::BeginCombat, None, None, false)
    } else if low == "at the beginning of your next combat phase" {
        (
            GamePhase::BeginCombat,
            Some(mtg_ir::TriggerScope::ControllerTurn),
            None,
            false,
        )
    } else {
        return None;
    };
    let filter = EventFilter {
        detail: Some(EventDetail::Phase {
            phase: Some(phase),
            any_main_phase: false,
            enchanted_controller_upkeep: false,
            enchanted_player_upkeep: false,
            enchanted_opponent_end_step: false,
            phase_chosen_player: false,
            turn_filter: None,
        }),
        ..Default::default()
    };
    Some((
        TriggerDef {
            event: EventKind::PhaseBegin,
            filter,
            scope,
            from_zones: None,
            only_once_per_turn: false,
            do_this_once_per_turn: false,
            is_state_trigger: false,
            or: Vec::new(),
            chapter_numbers: SmallVec::new(),
            is_chapter_ability: false,
            spell_delayed,
        },
        next_turn,
    ))
}
// ============================================================================
// Section 7: Wave 5-11 Sentences & Main Effect Driver
// ============================================================================

fn build_dig_spec(rest_dig: &str, ctx: &mut ParseCtx<'_>) -> DigSpec {
    let rest_clean = trim_trailing_period(rest_dig);
    let rest_low = rest_clean.to_ascii_lowercase();

    // Multi-partition dig clause: "Put one of them into your hand, put one of them on the bottom of your library, and exile one of them"
    if !contains_word_ci(&rest_low, "the rest")
        && (contains_word_ci(&rest_low, ", and ") || contains_word_ci(&rest_low, " and "))
    {
        let normalized = rest_clean
            .replace(", and ", ", ")
            .replace(", And ", ", ")
            .replace(" and ", ", ");
        let clauses: Vec<&str> = normalized
            .split(',')
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .collect();
        let has_group_ref =
            |c: &str| contains_word_ci(c, "of them") || contains_word_ci(c, "of those cards");
        let starts_count = |c: &str| {
            c.split_whitespace().next().is_some_and(|w| {
                let lw = w.to_ascii_lowercase();
                matches!(lw.as_str(), "a" | "an" | "one") || parse_small_number(&lw).is_some()
            })
        };
        if clauses.len() >= 2
            && has_group_ref(clauses[0])
            && clauses[1..]
                .iter()
                .all(|c| has_group_ref(c) || starts_count(c))
        {
            let mut partitions: Vec<mtg_ir::DigPartition> = Vec::with_capacity(clauses.len());
            let mut ok = true;
            for cl in &clauses {
                let cl_low = cl.to_ascii_lowercase();
                let mut count: u16 = 1;
                for w in cl_low.split_whitespace() {
                    if matches!(w, "into" | "on" | "to" | "in") {
                        break;
                    }
                    if let Some(n) = parse_small_number(w) {
                        count = n.max(1) as u16;
                        break;
                    }
                    if matches!(w, "a" | "an" | "one") {
                        count = 1;
                        break;
                    }
                }
                if cl_low.contains("into your hand") {
                    partitions.push(mtg_ir::DigPartition {
                        count,
                        to: DigRestTo::LibraryBottom,
                        to_hand: true,
                        playable_this_turn: false,
                    });
                } else if cl_low.contains("bottom of your library") {
                    partitions.push(mtg_ir::DigPartition {
                        count,
                        to: DigRestTo::LibraryBottom,
                        to_hand: false,
                        playable_this_turn: false,
                    });
                } else if cl_low.contains("top of your library") {
                    partitions.push(mtg_ir::DigPartition {
                        count,
                        to: DigRestTo::LibraryTop,
                        to_hand: false,
                        playable_this_turn: false,
                    });
                } else if cl_low.contains("graveyard") {
                    partitions.push(mtg_ir::DigPartition {
                        count,
                        to: DigRestTo::Graveyard,
                        to_hand: false,
                        playable_this_turn: false,
                    });
                } else if cl_low.contains("exile") {
                    partitions.push(mtg_ir::DigPartition {
                        count,
                        to: DigRestTo::Exile,
                        to_hand: false,
                        playable_this_turn: false,
                    });
                } else {
                    ok = false;
                    break;
                }
            }
            if ok && !partitions.is_empty() {
                let keep_n = partitions
                    .iter()
                    .find(|p| p.to_hand)
                    .map_or(partitions[0].count, |p| p.count);
                return DigSpec {
                    keep: keep_n,
                    up_to: false,
                    keep_filter: None,
                    keep_all_matching: false,
                    keep_label: None,
                    keep_to: DigKeepTo::Hand,
                    keep_tapped: false,
                    keep_attacking: false,
                    keep_attacking_player: None,
                    reveal_all: false,
                    reveal_kept: false,
                    rest: DigRestTo::LibraryBottom,
                    rest_random: false,
                    rest_order: None,
                    until_filter: None,
                    rest_to_hand: false,
                    shuffle_rest: false,
                    keep_max_mana_value: None,
                    keep_max_mv_strict_lt: false,
                    choose_one_of_exiled: false,
                    play_from_exile: None,
                    partitions,
                    destination_buckets: Vec::new(),
                };
            }
        }
    }

    let (keep_raw, rest_part) = if let Some((pos, sep_len)) = [
        ", then put the rest",
        ", then put the other",
        ", then shuffle the rest",
        ", then shuffle the other",
        ", and put the rest",
        ", and put the other",
        ", and shuffle the rest",
        ", and shuffle the other",
        "and put the rest",
        "and put the other",
        "and the rest",
        "and the other",
    ]
    .iter()
    .filter_map(|sep| find_word_ci(rest_clean, sep).map(|p| (p, sep.len())))
    .min_by_key(|&(p, _)| p)
    {
        (
            rest_clean[..pos].trim(),
            rest_clean[pos + sep_len..].to_ascii_lowercase(),
        )
    } else {
        (rest_clean, String::new())
    };
    let keep_low = keep_raw.to_ascii_lowercase();
    let keep_to = if keep_low.contains("onto the battlefield") {
        DigKeepTo::Battlefield
    } else if keep_low.contains("into exile") || keep_low.contains("exile") {
        DigKeepTo::Exile
    } else if keep_low.contains("into your graveyard") {
        DigKeepTo::Graveyard
    } else if keep_low.contains("on top of your library") {
        DigKeepTo::LibraryTop
    } else {
        DigKeepTo::Hand
    };
    let rest_check = if rest_part.is_empty() {
        &rest_low
    } else {
        &rest_part
    };
    let rest_to = if rest_check.contains("graveyard")
        && (rest_part.contains("graveyard") || keep_to != DigKeepTo::Graveyard)
    {
        DigRestTo::Graveyard
    } else if rest_check.contains("exile")
        && (rest_part.contains("exile") || keep_to != DigKeepTo::Exile)
    {
        DigRestTo::Exile
    } else if rest_check.contains("top of") && !rest_part.is_empty() {
        DigRestTo::LibraryTop
    } else {
        DigRestTo::LibraryBottom
    };

    let rest_to_hand = rest_part.contains("hand") || rest_low.contains("the rest into your hand");
    let up_to = contains_word_ci(&keep_low, "up to")
        || contains_word_ci(&keep_low, "you may")
        || contains_word_ci(&keep_low, "any number of");
    let mut keep_n: u16 = if contains_word_ci(&keep_low, "any number of") {
        999
    } else {
        1
    };
    let mut keep_filter = None;

    let mut head = keep_raw.trim().trim_start_matches(',').trim();
    for p in [
        "then ",
        "you may ",
        "reveal ",
        "put ",
        "up to ",
        "any number of ",
    ] {
        if let Some(h) = strip_prefix_word_ci(head, p.trim()) {
            head = h;
        }
    }
    if let Some(first_tok) = head.split_whitespace().next() {
        if let Some(n) = parse_small_number(first_tok) {
            keep_n = n.max(1) as u16;
        } else if eq_ci(first_tok, "a") || eq_ci(first_tok, "an") || eq_ci(first_tok, "one") {
            keep_n = 1;
        }
    }
    if let Some(pos) = find_word_ci(head, " from among them") {
        let mut filt_str = head[..pos].trim();
        if let Some(first_tok) = filt_str.split_whitespace().next()
            && (parse_small_number(first_tok).is_some()
                || eq_ci(first_tok, "a")
                || eq_ci(first_tok, "an")
                || eq_ci(first_tok, "one"))
        {
            filt_str = filt_str[first_tok.len()..].trim();
        }
        if !filt_str.is_empty() && !eq_ci(filt_str, "card") && !eq_ci(filt_str, "cards") {
            keep_filter = parse_object_phrase(
                filt_str,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_plural_and_disjunction: true,
                    allow_spell_noun: false,
                    strip_trailing_card: true,
                    expand_outlaw_subtypes: false,
                },
            )
            .map(Box::new);
        }
    }

    let rest_random = rest_check.contains("random order");
    let rest_order = if rest_random {
        Some(DigRestOrder::Random)
    } else if rest_check.contains("any order")
        && !matches!(rest_to, DigRestTo::Graveyard | DigRestTo::Exile)
    {
        Some(DigRestOrder::Any)
    } else {
        None
    };

    DigSpec {
        keep: keep_n,
        up_to,
        keep_filter,
        keep_all_matching: false,
        keep_label: None,
        keep_to,
        keep_tapped: keep_low.contains("tapped"),
        keep_attacking: false,
        keep_attacking_player: None,
        reveal_all: rest_low.contains("reveal all"),
        reveal_kept: keep_low.contains("reveal"),
        rest: rest_to,
        rest_random,
        rest_order,
        until_filter: None,
        rest_to_hand,
        shuffle_rest: rest_low.contains("shuffle"),
        keep_max_mana_value: None,
        keep_max_mv_strict_lt: false,
        choose_one_of_exiled: false,
        play_from_exile: None,
        partitions: Vec::new(),
        destination_buckets: Vec::new(),
    }
}

fn try_complete_pending_dig(
    s_text: &str,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let clean = trim_trailing_period(s_text);
    if let Some(idx) = state.pending_dig.take() {
        let is_optional_dig = state.steps.get(idx).is_some_and(|s| s.optional.is_some());
        let clean_dig =
            if is_optional_dig && let Some(after_do) = strip_prefix_word_ci(clean, "if you do") {
                after_do.trim_start_matches(',').trim()
            } else {
                clean
            };
        let is_put_follow = (starts_with_word_ci(clean_dig, "put")
            || starts_with_word_ci(clean_dig, "you may put")
            || starts_with_word_ci(clean_dig, "reveal")
            || starts_with_word_ci(clean_dig, "you may reveal")
            || starts_with_word_ci(clean_dig, "exile"))
            && (contains_word_ci(clean_dig, "of them")
                || contains_word_ci(clean_dig, "from among them")
                || contains_word_ci(clean_dig, "of those cards")
                || contains_word_ci(clean_dig, "from among those cards")
                || ((contains_word_ci(clean_dig, "that card")
                    || contains_word_ci(clean_dig, "those cards")
                    || contains_word_ci(clean_dig, "those creature cards"))
                    && contains_word_ci(clean_dig, "the rest")));
        let is_cast_follow = (starts_with_word_ci(clean, "you may cast")
            || starts_with_word_ci(clean, "you may play"))
            && (contains_word_ci(clean, "from among cards revealed this way")
                || contains_word_ci(clean, "from among them"))
            && contains_word_ci(clean, "without paying");
        if is_cast_follow {
            if let Some(st) = state.steps.get_mut(idx) {
                let old_reveal = matches!(
                    &st.op,
                    EffectOp::Dig { spec: old_spec, .. } if old_spec.reveal_all
                );
                let (max_mv, strict_lt) = if let Some(mv_pos) = find_word_ci(clean, "mana value ") {
                    let after_mv = clean[mv_pos + "mana value ".len()..].trim();
                    if starts_with_word_ci(after_mv, "less than x") {
                        (Some(Box::new(Amount::X)), true)
                    } else if starts_with_word_ci(after_mv, "x or less") {
                        (Some(Box::new(Amount::X)), false)
                    } else if let Some(w) = after_mv.split_whitespace().next()
                        && let Some(n) = parse_small_number(w)
                    {
                        (Some(Box::new(Amount::Const { n })), false)
                    } else {
                        (None, false)
                    }
                } else {
                    (None, false)
                };
                let mut spec = DigSpec {
                    keep: 1,
                    up_to: true,
                    keep_filter: None,
                    keep_all_matching: false,
                    keep_label: None,
                    keep_to: DigKeepTo::CastFree,
                    keep_tapped: false,
                    keep_attacking: false,
                    keep_attacking_player: None,
                    reveal_all: old_reveal,
                    reveal_kept: false,
                    rest: DigRestTo::LibraryBottom,
                    rest_random: false,
                    rest_order: None,
                    until_filter: None,
                    rest_to_hand: false,
                    shuffle_rest: false,
                    keep_max_mana_value: max_mv,
                    keep_max_mv_strict_lt: strict_lt,
                    choose_one_of_exiled: false,
                    play_from_exile: None,
                    partitions: Vec::new(),
                    destination_buckets: Vec::new(),
                };
                if let Some(pos) = find_word_ci(clean, " and put ") {
                    let tail = &clean[pos + 9..];
                    spec.rest_random = contains_ascii_ci(tail.as_bytes(), b"random order");
                    if spec.rest_random {
                        spec.rest_order = Some(DigRestOrder::Random);
                    }
                    if contains_ascii_ci(tail.as_bytes(), b"graveyard") {
                        spec.rest = DigRestTo::Graveyard;
                    } else if contains_ascii_ci(tail.as_bytes(), b"exile") {
                        spec.rest = DigRestTo::Exile;
                    }
                }
                st.op = EffectOp::Dig {
                    spec: Box::new(spec),
                    look_only: false,
                };
                st.bind_as = None;
                return true;
            }
            return false;
        }
        if !is_put_follow {
            return false;
        }
        let spec = build_dig_spec(clean_dig, ctx);
        let is_face_down_dig = contains_word_ci(clean_dig, "face down");
        let preserve_plural_keep = contains_word_ci(clean_dig, "those cards")
            || contains_word_ci(clean_dig, "those creature cards");
        let apply_dig_spec = |st: &mut EffectStep, base: &DigSpec| -> bool {
            let mut s = base.clone();
            if let EffectOp::Dig { spec: old_spec, .. } = &st.op {
                if old_spec.reveal_all {
                    s.reveal_all = true;
                }
                if s.until_filter.is_none() && old_spec.until_filter.is_some() {
                    s.until_filter = old_spec.until_filter.clone();
                }
                if preserve_plural_keep && old_spec.keep > s.keep {
                    s.keep = old_spec.keep;
                }
            }
            let keep_exile_bind = s.keep_to == DigKeepTo::Exile;
            st.op = EffectOp::Dig {
                spec: Box::new(s),
                look_only: is_face_down_dig,
            };
            st.bind_as = if keep_exile_bind {
                Some("exiled".to_string())
            } else {
                None
            };
            keep_exile_bind
        };
        if let Some(alt_idx) = state.alt_pending_dig.take()
            && let Some(alt_st) = state.steps.get_mut(alt_idx)
        {
            apply_dig_spec(alt_st, &spec);
        }
        if let Some(st) = state.steps.get_mut(idx) {
            if apply_dig_spec(st, &spec) {
                state.last_object = Some((
                    Ref::Binding {
                        name: "exiled".to_string(),
                    },
                    idx,
                ));
            }
            return true;
        }
        return false;
    }

    if (eq_ci(clean, "you may play the exiled card this turn")
        || eq_ci(clean, "you may cast the exiled card this turn"))
        && let Some(last_step) = state.steps.last_mut()
        && let EffectOp::Dig {
            spec,
            look_only: false,
        } = &mut last_step.op
        && !spec.partitions.is_empty()
    {
        let mut touched = false;
        for part in &mut spec.partitions {
            if part.to == DigRestTo::Exile {
                part.playable_this_turn = true;
                touched = true;
            }
        }
        if touched {
            return true;
        }
    }

    if eq_ci(clean, "you may shuffle")
        && let Some(last_step) = state.steps.last_mut()
        && let EffectOp::LookAndReorder { may_shuffle } = &mut last_step.op
    {
        *may_shuffle = true;
        return true;
    }

    if (eq_ci(clean, "choose one of them") || eq_ci(clean, "choose one"))
        && let Some(last_step) = state.steps.last_mut()
        && matches!(last_step.op, EffectOp::Exile { .. })
        && matches!(last_step.subject, Selector::LibraryTop { .. })
    {
        last_step.subject = Selector::None;
        last_step.bind_as = None;
        last_step.op = EffectOp::Dig {
            spec: Box::new(DigSpec {
                keep: 1,
                up_to: false,
                keep_filter: None,
                keep_all_matching: false,
                keep_label: None,
                keep_to: DigKeepTo::Exile,
                keep_tapped: false,
                keep_attacking: false,
                keep_attacking_player: None,
                reveal_all: false,
                reveal_kept: false,
                rest: DigRestTo::Exile,
                rest_random: false,
                rest_order: None,
                until_filter: None,
                rest_to_hand: false,
                shuffle_rest: false,
                keep_max_mana_value: None,
                keep_max_mv_strict_lt: false,
                choose_one_of_exiled: true,
                play_from_exile: None,
                partitions: Vec::new(),
                destination_buckets: Vec::new(),
            }),
            look_only: false,
        };
        return true;
    }

    if (contains_ascii_ci(clean.as_bytes(), b"you may play that card")
        || contains_ascii_ci(clean.as_bytes(), b"you may cast that card")
        || contains_ascii_ci(clean.as_bytes(), b"you may play the exiled card")
        || contains_ascii_ci(clean.as_bytes(), b"you may cast the exiled card")
        || contains_ascii_ci(clean.as_bytes(), b"you may play the card exiled this way")
        || contains_ascii_ci(clean.as_bytes(), b"you may cast the card exiled this way"))
        && !contains_ascii_ci(clean.as_bytes(), b"look at")
        && let Some(last_step) = state.steps.last_mut()
        && let EffectOp::Dig {
            spec,
            look_only: false,
        } = &mut last_step.op
        && (spec.choose_one_of_exiled || spec.keep_to == DigKeepTo::Exile)
        && spec.play_from_exile.is_none()
    {
        let dur = if contains_ascii_ci(clean.as_bytes(), b"until your next end step")
            || contains_ascii_ci(clean.as_bytes(), b"until the end of your next end step")
        {
            PlayFromExileDuration::UntilYourNextEndStep
        } else if contains_ascii_ci(clean.as_bytes(), b"until the end of your next turn")
            || contains_ascii_ci(clean.as_bytes(), b"until end of your next turn")
        {
            PlayFromExileDuration::UntilEndOfYourNextTurn
        } else if contains_ascii_ci(clean.as_bytes(), b"for as long as it remains exiled") {
            PlayFromExileDuration::AsLongAsExiled
        } else {
            PlayFromExileDuration::ThisTurn
        };
        spec.play_from_exile = Some(PlayFromExileSpec {
            duration: dur,
            spend_mana_as_any_color: contains_ascii_ci(clean.as_bytes(), b"any color")
                || contains_ascii_ci(clean.as_bytes(), b"any type"),
            spells_only: contains_ascii_ci(clean.as_bytes(), b"you may cast"),
            without_paying_mana_cost: contains_ascii_ci(clean.as_bytes(), b"without paying"),
            alternative_mana_cost: None,
            pay_life_equal_mana_value: false,
            cost_reduction_generic: None,
            plotted: false,
            total_max_mv: None,
        });
        return true;
    }

    if (eq_ci(clean, "they can't be regenerated") || eq_ci(clean, "it can't be regenerated"))
        && let Some(last_step) = state.steps.last_mut()
        && let EffectOp::Destroy {
            cant_be_regenerated,
            ..
        } = &mut last_step.op
    {
        *cant_be_regenerated = true;
        return true;
    }

    if let Some(last_step) = state.steps.last_mut()
        && let EffectOp::PreventDamage { spec } = &mut last_step.op
    {
        if starts_with_ci(
            clean,
            "if damage from a creature source is prevented this way",
        ) && contains_ascii_ci(clean.as_bytes(), b"deals that much damage to that creature")
        {
            spec.on_prevented_creature = Some(PreventReflectTarget::SourceCreature);
            return true;
        }
        if starts_with_ci(
            clean,
            "if damage from a noncreature source is prevented this way",
        ) && contains_ascii_ci(
            clean.as_bytes(),
            b"deals that much damage to the source's controller",
        ) {
            spec.on_prevented_noncreature = Some(PreventReflectTarget::SourceController);
            return true;
        }
    }

    if let Some(last_step) = state.steps.last_mut()
        && let EffectOp::Dig {
            spec,
            look_only: false,
        } = &mut last_step.op
        && (starts_with_word_ci(clean, "then put the rest")
            || starts_with_word_ci(clean, "put the rest"))
    {
        if contains_ascii_ci(clean.as_bytes(), b"graveyard") {
            spec.rest = DigRestTo::Graveyard;
            spec.rest_order = None;
            spec.rest_random = false;
        } else if contains_ascii_ci(clean.as_bytes(), b"exile") {
            spec.rest = DigRestTo::Exile;
            spec.rest_order = None;
            spec.rest_random = false;
        } else if contains_ascii_ci(clean.as_bytes(), b"top of") {
            spec.rest = DigRestTo::LibraryTop;
            spec.rest_random = contains_ascii_ci(clean.as_bytes(), b"random order");
            spec.rest_order =
                if !spec.rest_random && contains_ascii_ci(clean.as_bytes(), b"any order") {
                    Some(DigRestOrder::Any)
                } else {
                    None
                };
        } else {
            spec.rest = DigRestTo::LibraryBottom;
            spec.rest_random = contains_ascii_ci(clean.as_bytes(), b"random order");
            spec.rest_order =
                if !spec.rest_random && contains_ascii_ci(clean.as_bytes(), b"any order") {
                    Some(DigRestOrder::Any)
                } else {
                    None
                };
        }
        if contains_ascii_ci(clean.as_bytes(), b"shuffle") {
            spec.shuffle_rest = true;
        }
        return true;
    }

    if let Some(last_step) = state.steps.last_mut()
        && let EffectOp::Dig {
            spec,
            look_only: false,
        } = &mut last_step.op
        && contains_word_ci(clean, "revealed this way")
        && (starts_with_word_ci(clean, "put all") || starts_with_word_ci(clean, "then put all"))
    {
        let mut rest = clean;
        if let Some(r) = strip_prefix_word_ci(rest, "then") {
            rest = r.trim_start();
        }
        let segments: Vec<&str> = if let Some(idx) = find_word_ci(rest, " and put ") {
            vec![rest[..idx].trim(), rest[idx + 5..].trim()]
        } else {
            vec![rest]
        };
        let mut added = false;
        for seg in segments {
            let mut s = seg.trim();
            if let Some(r) = strip_prefix_word_ci(s, "put") {
                s = r.trim_start();
            }
            if let Some(r) = strip_prefix_word_ci(s, "all") {
                s = r.trim_start();
            }
            let Some(rev_idx) = find_word_ci(s, "revealed this way") else {
                continue;
            };
            let filter_part = s[..rev_idx].trim();
            let dest_part = s[rev_idx + "revealed this way".len()..].trim();
            let (destination, tapped) = if starts_with_ci(dest_part, "onto the battlefield tapped")
            {
                (Zone::Battlefield, true)
            } else if starts_with_ci(dest_part, "onto the battlefield") {
                (Zone::Battlefield, false)
            } else if starts_with_ci(dest_part, "into your hand")
                || starts_with_ci(dest_part, "to your hand")
            {
                (Zone::Hand, false)
            } else if starts_with_ci(dest_part, "into your graveyard") {
                (Zone::Graveyard, false)
            } else if starts_with_ci(dest_part, "into exile") {
                (Zone::Exile, false)
            } else {
                continue;
            };
            if let Some(mut filter) = parse_object_phrase(
                filter_part,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    strip_trailing_card: true,
                    ..Default::default()
                },
            ) {
                filter.zones = ZoneMask::empty();
                spec.destination_buckets
                    .push(mtg_ir::effect::DigDestinationBucket {
                        filter: Box::new(filter),
                        destination,
                        tapped,
                    });
                added = true;
            }
        }
        if added {
            return true;
        }
    }

    if let Some(last_step) = state.steps.last_mut()
        && let EffectOp::Search { spec, tapped } = &mut last_step.op
    {
        if eq_ci(clean, "then shuffle")
            || eq_ci(clean, "then shuffle your library")
            || eq_ci(clean, "shuffle your library")
        {
            return true;
        }
        if eq_ci(clean, "if you search your library this way, shuffle")
            || eq_ci(clean, "if you search your library this way, shuffle it")
            || eq_ci(clean, "if you searched your library this way, shuffle")
        {
            spec.shuffle_only_if_library = true;
            return true;
        }
        let refs_searched = contains_word_ci(clean, "it")
            || contains_word_ci(clean, "them")
            || contains_word_ci(clean, "that card")
            || contains_word_ci(clean, "those cards");
        let is_search_follow = (starts_with_word_ci(clean, "reveal")
            || starts_with_word_ci(clean, "put"))
            && refs_searched
            && (contains_word_ci(clean, "into your hand")
                || contains_word_ci(clean, "onto the battlefield")
                || contains_word_ci(clean, "on top of your library"));
        if is_search_follow {
            if contains_word_ci(clean, "reveal") {
                spec.reveal = true;
            }
            if contains_word_ci(clean, "onto the battlefield") {
                let tap = contains_word_ci(clean, "tapped");
                spec.destinations = vec![SearchDestination {
                    zone: Zone::Battlefield,
                    tapped: tap,
                    on_top: false,
                }];
                *tapped = tap;
            } else if contains_word_ci(clean, "into your hand") {
                spec.destinations = vec![SearchDestination {
                    zone: Zone::Hand,
                    tapped: false,
                    on_top: false,
                }];
            } else if contains_word_ci(clean, "on top of your library") {
                spec.destinations = vec![SearchDestination {
                    zone: Zone::Library,
                    tapped: false,
                    on_top: true,
                }];
            }
            return true;
        }
    }

    if let Some(last_step) = state.steps.last_mut()
        && let EffectOp::CreateToken {
            token: Some(tok), ..
        } = &mut last_step.op
        && let Some(after_has) = strip_prefix_word_ci(clean, "they have")
            .or_else(|| strip_prefix_word_ci(clean, "it has"))
            .or_else(|| strip_prefix_word_ci(clean, "that token has"))
            .or_else(|| strip_prefix_word_ci(clean, "those tokens have"))
    {
        let norm_q = after_has.replace(['\u{201C}', '\u{201D}'], "\"");
        let mut rest_q = norm_q.as_str();
        let mut added = false;
        while let Some(s) = rest_q.find('"') {
            let after_open = &rest_q[s + 1..];
            let Some(e) = after_open.find('"') else {
                break;
            };
            let q = after_open[..e]
                .trim()
                .replace("This token", "~")
                .replace("this token", "~")
                .replace("This creature", "~")
                .replace("this creature", "~");
            if !q.is_empty() {
                tok.quoted_abilities.push(q);
                added = true;
            }
            rest_q = &after_open[e + 1..];
        }
        if added {
            return true;
        }
    }

    // Two-sentence PunisherChoice: "Each player sacrifices <X>. Each player who can't <Y>." (Plaguecrafter / Fandaniel)
    if let Some((pun_players, def_raw)) = strip_prefix_word_ci(clean, "each player who can't")
        .or_else(|| strip_prefix_word_ci(clean, "each player who doesn't"))
        .map(|r| (PunisherPlayersKind::EachPlayer, r))
        .or_else(|| {
            strip_prefix_word_ci(clean, "each opponent who can't")
                .or_else(|| strip_prefix_word_ci(clean, "each opponent who doesn't"))
                .map(|r| (PunisherPlayersKind::EachOpponent, r))
        })
        && let Some(last_step) = state.steps.last()
    {
        let mut may_first = last_step.optional.is_some();
        let extracted_sac = match &last_step.op {
            EffectOp::ForEachPlayerLoop {
                steps: loop_steps, ..
            } if loop_steps.len() == 1 => {
                if loop_steps[0].optional.is_some() {
                    may_first = true;
                }
                if let EffectOp::Sacrifice { .. } = &loop_steps[0].op
                    && let Selector::All { filter } = &loop_steps[0].subject
                {
                    let sac_amt = loop_steps[0]
                        .amount
                        .as_deref()
                        .cloned()
                        .unwrap_or(Amount::Const { n: 1 });
                    let mut sac_filter = (**filter).clone();
                    sac_filter
                        .extra
                        .retain(|p| !matches!(p, ObjectPredicate::ControllerRef { .. }));
                    sac_filter.zones = ZoneMask::empty();
                    sac_filter.controller = Some(RelativeControl::You);
                    Some((sac_amt, sac_filter))
                } else {
                    None
                }
            }
            EffectOp::PunisherChoice { spec }
                if spec.default_steps.is_empty() && spec.unless_cost.len() == 1 =>
            {
                may_first = spec.may_first;
                if let mtg_ir::CostDef::Sacrifice {
                    count,
                    target: mtg_ir::CostObjectTarget::Filter { filter },
                    ..
                } = &spec.unless_cost[0]
                {
                    Some(((**count).clone(), (**filter).clone()))
                } else {
                    None
                }
            }
            _ => None,
        };
        if let Some((sac_amt, sac_filter)) = extracted_sac {
            let loop_subj = Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            };
            let loop_actor = Some(PlayerRef::EachLoopPlayer);
            let step_span = last_step.span;
            let before_def = state.steps.len();
            let mark = state.mark(ctx);
            if parse_player_predicate(loop_subj, loop_actor, def_raw, step_span, ctx, state)
                && state.steps.len() > before_def
            {
                let mut default_steps = state.steps.split_off(before_def);
                for st in &mut default_steps {
                    st.bind_as = None;
                }
                state.steps.pop(); // remove preceding ForEachPlayerLoop / partial PunisherChoice
                state.push_step(
                    make_step(
                        EffectOp::PunisherChoice {
                            spec: PunisherSpec {
                                players: Some(pun_players),
                                default_steps,
                                unless_cost: vec![mtg_ir::CostDef::Sacrifice {
                                    count: Box::new(sac_amt),
                                    target: mtg_ir::CostObjectTarget::Filter {
                                        filter: Box::new(sac_filter),
                                    },
                                    sacrifice_all: false,
                                    half_rounded_up: false,
                                    attached_creature: false,
                                    one_or_more: false,
                                    up_to: None,
                                    different_names: false,
                                }],
                                unless_effect: Vec::new(),
                                unless_who: PlayerRef::EachLoopPlayer,
                                repeat_count: None,
                                may_first,
                                mandatory_if_able: !may_first,
                                track_not_done_kind: None,
                                track_done_kind: None,
                            },
                        },
                        Selector::None,
                        step_span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    // Two-sentence PunisherChoice: "Each opponent/player [may] (discard|sacrifice) ... For each opponent/player who can't/doesn't, <effect>." (Refurbished Familiar / Fandaniel)
    if let Some((pun_players, def_raw)) =
        strip_prefix_word_ci(clean, "for each opponent who doesn't,")
            .or_else(|| strip_prefix_word_ci(clean, "for each opponent who can't,"))
            .or_else(|| strip_prefix_word_ci(clean, "for each opponent who doesn't"))
            .or_else(|| strip_prefix_word_ci(clean, "for each opponent who can't"))
            .map(|r| (PunisherPlayersKind::EachOpponent, r))
            .or_else(|| {
                strip_prefix_word_ci(clean, "for each player who doesn't,")
                    .or_else(|| strip_prefix_word_ci(clean, "for each player who can't,"))
                    .or_else(|| strip_prefix_word_ci(clean, "for each player who doesn't"))
                    .or_else(|| strip_prefix_word_ci(clean, "for each player who can't"))
                    .map(|r| (PunisherPlayersKind::EachPlayer, r))
            })
        && let Some(last_step) = state.steps.last()
    {
        let mut may_first = last_step.optional.is_some();
        let extracted_cost = match &last_step.op {
            EffectOp::Discard { .. } if matches!(&last_step.subject, Selector::Player { .. }) => {
                let disc_amt = last_step
                    .amount
                    .as_deref()
                    .cloned()
                    .unwrap_or(Amount::Const { n: 1 });
                Some(vec![mtg_ir::CostDef::Discard {
                    count: Box::new(disc_amt),
                    target: None,
                    random: false,
                    same_name_pair: false,
                    same_name_as_controlled: None,
                    different_names: false,
                }])
            }
            EffectOp::ForEachPlayerLoop {
                steps: loop_steps, ..
            } if loop_steps.len() == 1 => {
                if loop_steps[0].optional.is_some() {
                    may_first = true;
                }
                match &loop_steps[0].op {
                    EffectOp::Sacrifice { .. } => {
                        if let Selector::All { filter } = &loop_steps[0].subject {
                            let sac_amt = loop_steps[0]
                                .amount
                                .as_deref()
                                .cloned()
                                .unwrap_or(Amount::Const { n: 1 });
                            let mut sac_filter = (**filter).clone();
                            sac_filter
                                .extra
                                .retain(|p| !matches!(p, ObjectPredicate::ControllerRef { .. }));
                            sac_filter.zones = ZoneMask::empty();
                            sac_filter.controller = None;
                            Some(vec![mtg_ir::CostDef::Sacrifice {
                                count: Box::new(sac_amt),
                                target: mtg_ir::CostObjectTarget::Filter {
                                    filter: Box::new(sac_filter),
                                },
                                sacrifice_all: false,
                                half_rounded_up: false,
                                attached_creature: false,
                                one_or_more: false,
                                up_to: None,
                                different_names: false,
                            }])
                        } else {
                            None
                        }
                    }
                    EffectOp::Discard { .. } => {
                        let disc_amt = loop_steps[0]
                            .amount
                            .as_deref()
                            .cloned()
                            .unwrap_or(Amount::Const { n: 1 });
                        Some(vec![mtg_ir::CostDef::Discard {
                            count: Box::new(disc_amt),
                            target: None,
                            random: false,
                            same_name_pair: false,
                            same_name_as_controlled: None,
                            different_names: false,
                        }])
                    }
                    _ => None,
                }
            }
            _ => None,
        };
        if let Some(unless_cost) = extracted_cost {
            let step_span = last_step.span;
            let before_def = state.steps.len();
            let mark = state.mark(ctx);
            let saved_last_player = state.last_player.clone();
            let saved_is_each_loop = state.is_each_loop;
            state.last_player = Some(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            });
            state.is_each_loop = true;
            let parsed_def = parse_clauses_into(def_raw.trim(), step_span.start, ctx, state)
                && state.steps.len() > before_def;
            state.last_player = saved_last_player;
            state.is_each_loop = saved_is_each_loop;
            if parsed_def {
                let default_steps = state.steps.split_off(before_def);
                let prev_gate = state.steps.pop().and_then(|s| s.gate);
                let mut st = make_step(
                    EffectOp::PunisherChoice {
                        spec: PunisherSpec {
                            players: Some(pun_players),
                            default_steps,
                            unless_cost,
                            unless_effect: Vec::new(),
                            unless_who: PlayerRef::EachLoopPlayer,
                            repeat_count: None,
                            may_first,
                            mandatory_if_able: !may_first,
                            track_not_done_kind: None,
                            track_done_kind: None,
                        },
                    },
                    Selector::None,
                    step_span,
                );
                let is_sac_cost = matches!(
                    &st.op,
                    EffectOp::PunisherChoice { spec }
                        if matches!(spec.unless_cost.first(), Some(mtg_ir::CostDef::Sacrifice { .. }))
                );
                if !is_sac_cost {
                    st.amount = Some(Box::new(Amount::Const { n: 1 }));
                }
                st.gate = prev_gate;
                state.push_step(st, false);
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    false
}

fn parse_wave10_11_sentence(
    raw: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    let t = trim_trailing_period(raw);

    // 0. Follow-up mana restrictions / riders ("This mana can't...", "Spend this mana only...")
    if (starts_with_word_ci(t, "this mana") || starts_with_word_ci(t, "spend this mana"))
        && parse_add_mana_sentence(t, span, ctx, state)
    {
        return true;
    }

    // 1. Solve Case (*Murders at Karlov Manor*)
    if eq_ci(t, "solve ~") || eq_ci(t, "solve this case") || eq_ci(t, "this case is solved") {
        state.push_step(
            make_step(EffectOp::SolveCase, Selector::SelfObj, span),
            false,
        );
        return true;
    }

    // 2. RetainMana (*Kruphix*, *Horizon Stone*, *Omnath*)
    if eq_ci(t, "you don't lose this mana as steps and phases end")
        || eq_ci(
            t,
            "until end of turn, you don't lose this mana as steps and phases end",
        )
    {
        state.push_step(
            make_step(
                EffectOp::RetainMana {
                    colors: ColorMask::ALL_COLORS | ColorMask::C,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(after) = strip_prefix_word_ci(t, "you don't lose unspent")
        .or_else(|| strip_prefix_word_ci(t, "until end of turn, you don't lose unspent"))
        && let Some(mid) = strip_suffix_word_ci(after, "as steps and phases end")
    {
        let col_str = strip_suffix_word_ci(mid, "mana").unwrap_or(mid).trim();
        let colors = if col_str.is_empty() {
            ColorMask::ALL_COLORS | ColorMask::C
        } else {
            parse_color_list_str(col_str)
        };
        if !colors.is_empty() {
            state.push_step(
                make_step(EffectOp::RetainMana { colors }, Selector::None, span),
                false,
            );
            return true;
        }
    }

    // 3. ExtraCombatPhase / SkipCombatPhase / SkipTurn / EndTurn
    if eq_ci(
        t,
        "after this main phase, there is an additional combat phase",
    ) || eq_ci(t, "after this phase, there is an additional combat phase")
        || eq_ci(t, "there is an additional combat phase after this one")
        || eq_ci(t, "there is an additional combat phase after this phase")
        || eq_ci(t, "there's an additional combat phase after this phase")
        || eq_ci(t, "there's an additional combat phase after this one")
        || eq_ci(
            t,
            "after this main phase, there's an additional combat phase",
        )
    {
        state.push_step(
            make_step(EffectOp::ExtraCombatPhase, Selector::None, span),
            false,
        );
        return true;
    }
    if eq_ci(t, "the player whose turn it is may end the turn") {
        state.push_step(
            make_step(
                EffectOp::EndTurn {
                    active_player_may: true,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(t, "skip your next combat phase")
        || eq_ci(t, "you skip your next combat phase")
        || eq_ci(t, "target player skips their next combat phase")
        || eq_ci(t, "target opponent skips their next combat phase")
    {
        let subj = if starts_with_word_ci(t, "target opponent") {
            parse_player_selector("target opponent", ctx, state).unwrap_or_else(you_sel)
        } else if starts_with_word_ci(t, "target") {
            parse_player_selector("target player", ctx, state).unwrap_or_else(you_sel)
        } else {
            you_sel()
        };
        let mut st = make_step(EffectOp::SkipCombatPhase, subj, span);
        st.amount = Some(Box::new(Amount::Const { n: 1 }));
        state.push_step(st, false);
        return true;
    }
    if eq_ci(t, "skip your next turn") || eq_ci(t, "you skip your next turn") {
        let mut st = make_step(EffectOp::SkipTurn, you_sel(), span);
        st.amount = Some(Box::new(Amount::Const { n: 1 }));
        state.push_step(st, false);
        return true;
    }
    if let Some(after) = strip_prefix_word_ci(t, "target opponent skips their next")
        .or_else(|| strip_prefix_word_ci(t, "target player skips their next"))
        && let Some(amt_s) =
            strip_suffix_word_ci(after, "turns").or_else(|| strip_suffix_word_ci(after, "turn"))
        && let Some(amt) = parse_amount_str(amt_s, ctx, state)
        && let Some(psel) = parse_player_selector(
            if starts_with_word_ci(t, "target opponent") {
                "target opponent"
            } else {
                "target player"
            },
            ctx,
            state,
        )
    {
        let mut st = make_step(EffectOp::SkipTurn, psel, span);
        st.amount = Some(Box::new(amt));
        state.push_step(st, false);
        return true;
    }

    // 4. RepeatSequence: "Repeat the following process X times" / "If <cond>, repeat this process"
    if let Some(after) = strip_prefix_word_ci(t, "repeat the following process")
        && let Some(amt_s) = strip_suffix_word_ci(after, "times")
        && let Some(amt) = parse_amount_str(amt_s, ctx, state)
    {
        state.pending_repeat = Some(amt);
        return true;
    }
    if let Some((hdr, tail)) = split_at_top_level_comma(t)
        && eq_ci(tail, "repeat this process")
        && !state.steps.is_empty()
    {
        let cond = if eq_ci(hdr, "if you win") {
            Some(Condition::WonClashThisWay)
        } else if eq_ci(hdr, "if you do") {
            Some(Condition::DidLastOptionalStep)
        } else {
            parse_condition_str(hdr, ctx, state)
        };
        if let Some(c) = cond {
            let start_idx = if state.last_sentence_step_start < state.steps.len() {
                state.last_sentence_step_start
            } else {
                state.prev_sentence_step_start
            }
            .min(state.steps.len());
            let body_steps = state.steps.split_off(start_idx);
            state.push_step(
                make_step(
                    EffectOp::RepeatSequence {
                        steps: body_steps,
                        condition: Box::new(c),
                        max_iterations: Some(20),
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }
    }

    // 5. ConditionalSequence: "If <cond>, <steps...>. Otherwise, <steps...>" or Ribbon counter check
    if eq_ci(
        t,
        "then if there are three or more ribbon counters on ~, remove those counters and untap it",
    ) || eq_ci(
        t,
        "if there are three or more ribbon counters on ~, remove those counters and untap it",
    ) {
        let ribbon = ctx.interner.intern_counter("ribbon");
        let cond = Condition::SourceHasCounter {
            counter: ribbon,
            min: Some(3),
        };
        let mut rem = make_step(
            EffectOp::RemoveCounters {
                counter: Some(ribbon),
                up_to: false,
                if_unable_sacrifice_self: false,
                remove_all_from_target_or_player: false,
            },
            Selector::SelfObj,
            span,
        );
        rem.amount = Some(Box::new(Amount::Const { n: 999 }));
        let untap = make_step(
            EffectOp::Untap {
                select: SelectionMod::default(),
            },
            Selector::SelfObj,
            span,
        );
        state.push_step(
            make_step(
                EffectOp::ConditionalSequence {
                    condition: Box::new(cond),
                    then_steps: vec![rem, untap],
                    else_steps: Vec::new(),
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }

    // 6. PunisherChoice: "<effect> unless <that player|they|its controller|you> <cost|effect>"
    if let Some(pos) = find_word_ci(t, " unless ") {
        let eff_part = t[..pos].trim();
        let right = t[pos + 8..].trim();
        for (who_tok, default_who_ref) in [
            ("that player ", PlayerRef::EventPlayer),
            ("they ", PlayerRef::EventPlayer),
            ("he or she ", PlayerRef::EventPlayer),
            (
                "its controller ",
                PlayerRef::ControllerOf {
                    of: Box::new(Ref::EventObject),
                },
            ),
            (
                "their controller ",
                PlayerRef::ControllerOf {
                    of: Box::new(Ref::EventObject),
                },
            ),
            ("you ", PlayerRef::You),
        ] {
            if let Some(cost_str) = strip_prefix_word_ci(right, who_tok.trim()) {
                let def_sub = state.parse_sub_effects(eff_part, span.start, state.context, ctx);
                if def_sub.unparsed.is_empty() && !def_sub.steps.is_empty() {
                    let is_each_opp = eff_part.to_ascii_lowercase().starts_with("each opponent");
                    let is_each_pl = eff_part.to_ascii_lowercase().starts_with("each player");
                    let unless_who = if is_each_opp || is_each_pl {
                        PlayerRef::EachLoopPlayer
                    } else if matches!(default_who_ref, PlayerRef::EventPlayer)
                        && let Some(sp) = def_sub.targets.first()
                    {
                        match sp.kind {
                            mtg_ir::TargetKind::Player => PlayerRef::Target { index: 0 },
                            mtg_ir::TargetKind::Object => PlayerRef::ControllerOf {
                                of: Box::new(Ref::Target { index: 0 }),
                            },
                            _ => default_who_ref.clone(),
                        }
                    } else if let PlayerRef::ControllerOf { of } = &default_who_ref
                        && matches!(**of, Ref::EventObject)
                        && def_sub
                            .targets
                            .first()
                            .is_some_and(|sp| matches!(sp.kind, mtg_ir::TargetKind::Object))
                    {
                        PlayerRef::ControllerOf {
                            of: Box::new(Ref::Target { index: 0 }),
                        }
                    } else {
                        default_who_ref.clone()
                    };
                    let cost_trimmed = if let Some((c_left, x_expr)) = split_where_x_is(cost_str)
                        && parse_amount_str(x_expr, ctx, state).is_some()
                    {
                        c_left
                    } else {
                        cost_str
                    };
                    let norm_cost = normalize_punisher_cost_phrase(cost_trimmed);
                    let cost_parse =
                        crate::parser::cost::parse_cost_list(&norm_cost, span.start, ctx);
                    let (unless_cost, unless_effect, extra_targets) =
                        if !cost_parse.defs.is_empty() && cost_parse.unparsed.is_empty() {
                            (cost_parse.defs, Vec::new(), Vec::new())
                        } else {
                            let saved_obj = state.last_object.clone();
                            let saved_pl = state.last_player.clone();
                            if def_sub
                                .targets
                                .first()
                                .is_some_and(|sp| matches!(sp.kind, mtg_ir::TargetKind::Object))
                            {
                                state.last_object =
                                    Some((Ref::Target { index: 0 }, state.steps.len()));
                            }
                            if !matches!(unless_who, PlayerRef::You | PlayerRef::EventPlayer) {
                                state.last_player = Some(Selector::PlayerRef {
                                    player: unless_who.clone(),
                                });
                            }
                            let mut eff_sub =
                                state.parse_sub_effects(&norm_cost, span.start, state.context, ctx);
                            state.last_object = saved_obj;
                            state.last_player = saved_pl;
                            if eff_sub.unparsed.is_empty() && !eff_sub.steps.is_empty() {
                                let first_is_obj = def_sub.targets.first().is_some_and(|sp| {
                                    matches!(sp.kind, mtg_ir::TargetKind::Object)
                                });
                                for st in &mut eff_sub.steps {
                                    if matches!(st.op, EffectOp::DiscardHand { .. })
                                        && st.subject == you_sel()
                                        && !matches!(unless_who, PlayerRef::You)
                                    {
                                        st.subject = Selector::PlayerRef {
                                            player: unless_who.clone(),
                                        };
                                    }
                                    if first_is_obj && matches!(st.subject, Selector::EventObject) {
                                        st.subject = Selector::Target { index: 0 };
                                    }
                                    if st.actor.is_none()
                                        && matches!(
                                            st.op,
                                            EffectOp::Sacrifice { .. }
                                                | EffectOp::Discard { .. }
                                                | EffectOp::DiscardHand { .. }
                                        )
                                        && !matches!(unless_who, PlayerRef::You)
                                    {
                                        st.actor = Some(unless_who.clone());
                                    }
                                }
                                (Vec::new(), eff_sub.steps, eff_sub.targets)
                            } else {
                                continue;
                            }
                        };
                    let players_kind = if is_each_opp {
                        Some(PunisherPlayersKind::EachOpponent)
                    } else if is_each_pl {
                        Some(PunisherPlayersKind::EachPlayer)
                    } else {
                        None
                    };
                    let fixed_def: Vec<EffectStep> = if is_each_opp || is_each_pl {
                        def_sub
                            .steps
                            .into_iter()
                            .map(|mut s| {
                                s.subject = Selector::PlayerRef {
                                    player: PlayerRef::EachLoopPlayer,
                                };
                                s
                            })
                            .collect()
                    } else {
                        def_sub.steps
                    };
                    state.targets.extend(def_sub.targets);
                    state.targets.extend(extra_targets);
                    let repeat_count = state.pending_repeat.take().map(Box::new);
                    state.push_step(
                        make_step(
                            EffectOp::PunisherChoice {
                                spec: PunisherSpec {
                                    players: players_kind,
                                    default_steps: fixed_def,
                                    unless_cost,
                                    unless_effect,
                                    unless_who,
                                    repeat_count,
                                    may_first: false,
                                    mandatory_if_able: false,
                                    track_not_done_kind: None,
                                    track_done_kind: None,
                                },
                            },
                            Selector::None,
                            span,
                        ),
                        false,
                    );
                    return true;
                }
            }
        }
    }

    // 7. ExileUntil / Cascade / Discover / Dig / PileSplit / CastFree / GrantPlayFromExile / GrantGraveyardCast
    if let Some((lib_owner_s, until_part, rest_tail)) = if let Some(after_ex) =
        strip_prefix_word_ci(t, "exile cards from the top of")
        && let Some((until_pos, kw_len)) = find_word_ci(after_ex, " until you exile ")
            .map(|p| (p, " until you exile ".len()))
            .or_else(|| {
                find_word_ci(after_ex, " until they exile ")
                    .map(|p| (p, " until they exile ".len()))
            }) {
        let lib_s = after_ex[..until_pos].trim();
        let after_u = after_ex[until_pos + kw_len..].trim();
        let (up, rt) = {
            let mut split_pair = None;
            for (idx, ch) in after_u.char_indices() {
                if ch == ',' {
                    let r = after_u[idx + 1..].trim();
                    if [
                        "and ",
                        "then ",
                        "put ",
                        "you may ",
                        "that player ",
                        "they ",
                        "shuffle ",
                        "if ",
                        "until ",
                    ]
                    .iter()
                    .any(|p| starts_with_word_ci(r, p.trim()))
                    {
                        split_pair = Some((after_u[..idx].trim(), Some(r)));
                        break;
                    }
                }
            }
            split_pair.unwrap_or((after_u, None))
        };
        Some((lib_s, up, rt))
    } else {
        None
    } {
        let mut loop_kind_opt: Option<LoopPlayersKind> = None;
        let mut lib_owner_pref: Option<Box<Selector>> = None;
        let lib_low = lib_owner_s.to_ascii_lowercase();
        let owner_valid = if lib_low == "your library" {
            true
        } else if lib_low == "their library" {
            lib_owner_pref = state
                .single_player_ref()
                .map(|p| Box::new(Selector::PlayerRef { player: p }));
            lib_owner_pref.is_some()
        } else if lib_low == "each opponent's library" {
            loop_kind_opt = Some(LoopPlayersKind::EachOpponent);
            lib_owner_pref = Some(Box::new(Selector::PlayerRef {
                player: PlayerRef::EachLoopPlayer,
            }));
            true
        } else if let Some(pl_s) = strip_suffix_word_ci(lib_owner_s, "'s library")
            && let Some(psel) = parse_player_selector(pl_s, ctx, state)
        {
            lib_owner_pref = Some(Box::new(psel));
            true
        } else {
            false
        };
        let filter_s = strip_prefix_word_ci(until_part, "a")
            .or_else(|| strip_prefix_word_ci(until_part, "an"))
            .unwrap_or(until_part);
        let until_opts = FilterOpts {
            default_zone: ZoneMask::LIBRARY,
            allow_plural_and_disjunction: true,
            strip_trailing_card: true,
            ..Default::default()
        };
        let parsed_until = parse_object_phrase(filter_s, ctx, until_opts).or_else(|| {
            if filter_s.contains(',') {
                let norm = filter_s
                    .replace(", or ", " or ")
                    .replace(", ", " or ")
                    .replace(" or a ", " or ")
                    .replace(" or an ", " or ");
                parse_object_phrase(&norm, ctx, until_opts)
            } else {
                None
            }
        });
        if owner_valid && let Some(mut f) = parsed_until {
            f.zones = ZoneMask::empty();
            let tail_low = rest_tail.unwrap_or("").to_ascii_lowercase();
            let hit_action = if tail_low.contains("without paying its mana cost")
                || tail_low.contains("without paying their mana cost")
            {
                ExileUntilHitAction::CastFree
            } else if tail_low.contains("into your hand") {
                ExileUntilHitAction::Hand
            } else if tail_low.contains("onto the battlefield") {
                ExileUntilHitAction::Battlefield
            } else if tail_low.contains("play") || tail_low.contains("cast") {
                ExileUntilHitAction::PlayThisTurn
            } else {
                ExileUntilHitAction::StayExiled
            };
            let rest_dest = if tail_low.contains("graveyard") {
                ExileUntilRest::Graveyard
            } else if rest_tail.is_none() {
                ExileUntilRest::StayExiled
            } else {
                ExileUntilRest::LibraryBottomRandom
            };
            let mut st = make_step(
                EffectOp::ExileUntil {
                    spec: Box::new(ExileUntilSpec {
                        filter: Box::new(f),
                        library_owner: lib_owner_pref,
                        actor: None,
                        hit_action,
                        cast_free_condition: None,
                        fallback_to_hand: tail_low.contains("into your hand"),
                        spend_mana_as_any_color: tail_low.contains("any color")
                            || tail_low.contains("any type"),
                        without_paying_mana_cost: tail_low.contains("without paying"),
                        spells_only: tail_low.contains("cast"),
                        pay_life_equal_mana_value: tail_low.contains("pay life equal to"),
                        rest_destination: rest_dest,
                    }),
                },
                Selector::None,
                span,
            );
            if let Some(lk) = loop_kind_opt {
                st.bind_as = Some("exiled".to_string());
                state.push_step(
                    make_step(
                        EffectOp::ForEachPlayerLoop {
                            players: lk,
                            steps: vec![st],
                            choose_random_opponent: false,
                            exclude_attacked_last_combat: false,
                            exclude_event_player: false,
                            choose_object_to_bind: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
            } else {
                let idx = state.steps.len();
                state.push_step(st, false);
                state.last_object = Some((
                    Ref::Binding {
                        name: "exiled".to_string(),
                    },
                    idx,
                ));
            }
            return true;
        }
    }

    // GrantPlayFromExile / CastFree: "You may play/cast ... [if <cond>]"
    if (contains_word_ci(t, "you may play")
        || contains_word_ci(t, "you may cast")
        || contains_word_ci(t, "you may look at and play")
        || contains_word_ci(t, "you may look at and cast")
        || contains_word_ci(t, "its owner may play")
        || contains_word_ci(t, "its owner may cast"))
        && !contains_word_ci(t, ", then ")
        && !starts_with_word_ci(t, "exile ")
    {
        let is_owner_actor = contains_word_ci(t, "its owner may");
        let (main_t, gate_cond) = if let Some(after_cmdr) =
            strip_prefix_word_ci(t, "during any turn you attacked with a commander,")
        {
            (
                after_cmdr.trim(),
                Some(Condition::AttackedWithCommanderThisTurn),
            )
        } else if let Some(if_pos) = find_word_ci(t, " if ")
            && !starts_with_ci(&t[if_pos + 4..], "it ")
            && let Some(cond) = parse_condition_str(t[if_pos + 4..].trim(), ctx, state)
        {
            (t[..if_pos].trim_end_matches(',').trim(), Some(cond))
        } else {
            (t, None)
        };
        let free = contains_ascii_ci(main_t.as_bytes(), b"without paying");
        let any_color = contains_ascii_ci(main_t.as_bytes(), b"any color")
            || contains_ascii_ci(main_t.as_bytes(), b"any type");
        let pay_life_mv = contains_ascii_ci(main_t.as_bytes(), b"pay life equal to its mana value")
            || contains_ascii_ci(main_t.as_bytes(), b"lose life equal to its mana value");
        let dur = if contains_ascii_ci(main_t.as_bytes(), b"for as long as it remains exiled")
            || contains_ascii_ci(
                main_t.as_bytes(),
                b"for as long as that card remains exiled",
            )
            || contains_ascii_ci(main_t.as_bytes(), b"for as long as they remain exiled")
            || contains_ascii_ci(
                main_t.as_bytes(),
                b"for as long as those cards remain exiled",
            )
            || contains_ascii_ci(main_t.as_bytes(), b"until you exile another")
        {
            PlayFromExileDuration::AsLongAsExiled
        } else if contains_ascii_ci(main_t.as_bytes(), b"until your next end step")
            || contains_ascii_ci(main_t.as_bytes(), b"until the end of your next end step")
        {
            PlayFromExileDuration::UntilYourNextEndStep
        } else if contains_ascii_ci(main_t.as_bytes(), b"until the end of your next turn")
            || contains_ascii_ci(main_t.as_bytes(), b"until end of your next turn")
        {
            PlayFromExileDuration::UntilEndOfYourNextTurn
        } else {
            PlayFromExileDuration::ThisTurn
        };

        // CastFree from hand / command zone / graveyard target
        if free
            && !contains_ascii_ci(main_t.as_bytes(), b"exiled")
            && !contains_ascii_ci(main_t.as_bytes(), b"that card")
            && !contains_ascii_ci(main_t.as_bytes(), b"those cards")
            && !contains_ascii_ci(main_t.as_bytes(), b"them")
        {
            if contains_ascii_ci(main_t.as_bytes(), b"your commander from the command zone") {
                let f = ObjectFilter {
                    zones: ZoneMask::COMMAND,
                    flags: FilterFlags::IS_COMMANDER,
                    owner: Some(RelativeControl::You),
                    ..Default::default()
                };
                let mut st = make_step(
                    EffectOp::CastFree {
                        spec: Some(Box::new(CastFreeSpec {
                            copy_card_first: false,
                            without_paying_mana_cost: true,
                            filter: Some(Box::new(f)),
                            up_to_count: Some(1),
                            exile_if_put_into_graveyard: false,
                            alternative_mana_cost: None,
                            pay_life_equal_mana_value: pay_life_mv,
                            total_max_mv: None,
                            exiled_with_self: false,
                        })),
                        at_random: false,
                        cast_any_number_from_exiled: false,
                    },
                    you_sel(),
                    span,
                );
                if let Some(c) = gate_cond {
                    attach_gate_condition(&mut st.gate, c);
                }
                state.push_step(st, false);
                return true;
            }
            if let Some(after_cast) = strip_prefix_word_ci(main_t, "you may cast")
                && let Some(from_pos) = find_word_ci(after_cast, " from your hand")
            {
                let f_raw = after_cast[..from_pos].trim();
                let mut after_hand = after_cast[from_pos + " from your hand".len()..].trim();
                after_hand = strip_suffix_word_ci(after_hand, "without paying its mana cost")
                    .or_else(|| strip_suffix_word_ci(after_hand, "without paying their mana costs"))
                    .unwrap_or(after_hand);
                let total_max_mv = if after_hand.is_empty() {
                    None
                } else if let Some(mv_expr) =
                    strip_prefix_word_ci(after_hand, "with mana value equal to")
                {
                    let Some(amt) = parse_amount_str(mv_expr, ctx, state) else {
                        return false;
                    };
                    Some(Box::new(amt))
                } else {
                    return false;
                };
                let f_clean = strip_prefix_word_ci(f_raw, "a")
                    .or_else(|| strip_prefix_word_ci(f_raw, "an"))
                    .unwrap_or(f_raw);
                let toks = tokenize(f_clean, 0);
                let cp = ctx.interner.checkpoint();
                if let Some((mut f, used)) = parse_object_filter(
                    &toks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::HAND,
                        allow_spell_noun: true,
                        strip_trailing_card: true,
                        allow_plural_and_disjunction: true,
                        ..Default::default()
                    },
                    state,
                ) && used == toks.len()
                {
                    f.zones = ZoneMask::HAND;
                    if f.owner.is_none() {
                        f.owner = Some(RelativeControl::You);
                    }
                    if f.types_any.is_empty()
                        && f.types_none.is_empty()
                        && contains_word_ci(f_clean, "permanent")
                    {
                        f.types_any |= CardTypeMask::CREATURE
                            | CardTypeMask::ARTIFACT
                            | CardTypeMask::ENCHANTMENT
                            | CardTypeMask::PLANESWALKER
                            | CardTypeMask::BATTLE;
                    } else {
                        f.types_none |= CardTypeMask::LAND;
                    }
                    let mut st = make_step(
                        EffectOp::CastFree {
                            spec: Some(Box::new(CastFreeSpec {
                                copy_card_first: false,
                                without_paying_mana_cost: true,
                                filter: Some(Box::new(f)),
                                up_to_count: Some(1),
                                exile_if_put_into_graveyard: false,
                                alternative_mana_cost: None,
                                pay_life_equal_mana_value: pay_life_mv,
                                total_max_mv,
                                exiled_with_self: false,
                            })),
                            at_random: false,
                            cast_any_number_from_exiled: false,
                        },
                        you_sel(),
                        span,
                    );
                    if let Some(c) = gate_cond {
                        attach_gate_condition(&mut st.gate, c);
                    }
                    state.push_step(st, false);
                    return true;
                }
                ctx.interner.rollback(cp);
            }
        }

        let ursine_one_exiled = state.trigger_has_exiled_with_self
            && contains_ascii_ci(main_t.as_bytes(), b"one of them");
        let is_exiled_with_self = contains_ascii_ci(main_t.as_bytes(), b"exiled with ~")
            || contains_ascii_ci(main_t.as_bytes(), b"exiled with this ")
            || ursine_one_exiled;
        let has_prev_exile_bind = state.steps.last().is_some_and(|s| {
            matches!(s.op, EffectOp::Exile { .. } | EffectOp::Dig { .. }) && s.bind_as.is_some()
        });
        if contains_ascii_ci(main_t.as_bytes(), b"that card")
            || contains_ascii_ci(main_t.as_bytes(), b"those cards")
            || contains_ascii_ci(main_t.as_bytes(), b"the exiled card")
            || contains_ascii_ci(main_t.as_bytes(), b"the exiled cards")
            || contains_ascii_ci(main_t.as_bytes(), b"the cards exiled this way")
            || contains_ascii_ci(main_t.as_bytes(), b"cards exiled this way")
            || contains_ascii_ci(main_t.as_bytes(), b"cards exiled with ~")
            || contains_ascii_ci(main_t.as_bytes(), b"a card exiled with ~")
            || contains_ascii_ci(main_t.as_bytes(), b"the copy")
            || is_exiled_with_self
            || (contains_ascii_ci(main_t.as_bytes(), b"them")
                && (state.it_ref().is_some() || has_prev_exile_bind))
            || ((contains_word_ci(main_t, "play it") || contains_word_ci(main_t, "cast it"))
                && (state.it_ref().is_some() || has_prev_exile_bind))
        {
            let prev_exile_bind = state.steps.last().and_then(|s| {
                if matches!(s.op, EffectOp::Exile { .. }) {
                    s.bind_as.clone()
                } else {
                    None
                }
            });
            let subj = if is_exiled_with_self {
                let mut f = ObjectFilter {
                    zones: ZoneMask::EXILE,
                    ..Default::default()
                };
                if let Some(ex_pos) = find_word_ci(main_t, "exiled with ~")
                    .or_else(|| find_word_ci(main_t, "exiled with this "))
                {
                    let before_ex = main_t[..ex_pos].trim();
                    let raw_phrase = if let Some(p) = find_word_ci(before_ex, "from among ") {
                        before_ex[p + "from among ".len()..].trim()
                    } else if let Some(p) = find_word_ci(before_ex, "cast ") {
                        before_ex[p + "cast ".len()..].trim()
                    } else if let Some(p) = find_word_ci(before_ex, "play ") {
                        before_ex[p + "play ".len()..].trim()
                    } else {
                        before_ex
                    };
                    let clean_p = strip_prefix_word_ci(raw_phrase, "any number of")
                        .or_else(|| strip_prefix_word_ci(raw_phrase, "a"))
                        .or_else(|| strip_prefix_word_ci(raw_phrase, "an"))
                        .unwrap_or(raw_phrase)
                        .trim();
                    if !clean_p.is_empty()
                        && !(eq_ci(clean_p, "card")
                            || eq_ci(clean_p, "cards")
                            || eq_ci(clean_p, "spell")
                            || eq_ci(clean_p, "spells")
                            || eq_ci(clean_p, "that card")
                            || eq_ci(clean_p, "those cards"))
                    {
                        let toks = tokenize(clean_p, 0);
                        let cp = ctx.interner.checkpoint();
                        if !toks.is_empty()
                            && let Some((parsed_f, used)) = parse_object_filter(
                                &toks,
                                ctx,
                                FilterOpts {
                                    default_zone: ZoneMask::EXILE,
                                    allow_plural_and_disjunction: true,
                                    strip_trailing_card: true,
                                    ..Default::default()
                                },
                                state,
                            )
                            && used == toks.len()
                        {
                            f = parsed_f;
                            f.zones = ZoneMask::EXILE;
                        } else {
                            ctx.interner.rollback(cp);
                        }
                    }
                }
                if !f
                    .extra
                    .iter()
                    .any(|p| matches!(p, ObjectPredicate::ExiledWithSelf))
                {
                    f.extra.push(ObjectPredicate::ExiledWithSelf);
                }
                Selector::All {
                    filter: Box::new(f),
                }
            } else if is_owner_actor && let Some(ref bname) = prev_exile_bind {
                Selector::Binding {
                    name: bname.clone(),
                }
            } else if let Some(ref bname) = prev_exile_bind
                && (contains_ascii_ci(main_t.as_bytes(), b"that card")
                    || contains_word_ci(main_t, "play it"))
                && matches!(
                    state.steps.last().map(|s| &s.subject),
                    Some(Selector::Target { .. } | Selector::LibraryTop { .. })
                )
            {
                Selector::Binding {
                    name: bname.clone(),
                }
            } else {
                state
                    .it_ref()
                    .map(|r| ref_to_selector(&r))
                    .unwrap_or_else(|| Selector::Binding {
                        name: "exiled".to_string(),
                    })
            };
            let alt_mana = if let Some(pay_pos) = find_word_ci(main_t, " by paying ")
                && let Some(rather_pos) = find_word_ci(main_t, " rather than paying ")
                && pay_pos < rather_pos
            {
                let mana_s = main_t[pay_pos + " by paying ".len()..rather_pos].trim();
                let cp = ctx.interner.checkpoint();
                let parsed = crate::parser::cost::parse_cost_list(mana_s, span.start, ctx);
                if parsed.defs.len() == 1
                    && parsed.unparsed.is_empty()
                    && let mtg_ir::CostDef::Mana { cost, .. } = &parsed.defs[0]
                {
                    Some(cost.clone())
                } else {
                    ctx.interner.rollback(cp);
                    None
                }
            } else {
                None
            };
            if (free || alt_mana.is_some())
                && (contains_ascii_ci(main_t.as_bytes(), b"a card")
                    || contains_ascii_ci(main_t.as_bytes(), b"a spell")
                    || contains_ascii_ci(main_t.as_bytes(), b"the exiled card")
                    || contains_ascii_ci(main_t.as_bytes(), b"the copy")
                    || contains_ascii_ci(main_t.as_bytes(), b"any number of")
                    || ursine_one_exiled)
            {
                let total_max_mv = if let Some(tmv_pos) =
                    find_word_ci(main_t, "with total mana value ")
                {
                    let after_tmv = main_t[tmv_pos + "with total mana value ".len()..].trim();
                    let amt_str = if let Some(or_less_pos) = find_word_ci(after_tmv, " or less") {
                        after_tmv[..or_less_pos].trim()
                    } else {
                        after_tmv
                    };
                    parse_amount_str(amt_str, ctx, state).map(Box::new)
                } else {
                    None
                };
                let is_copy = contains_ascii_ci(main_t.as_bytes(), b"the copy");
                let has_exiled_total_cap = is_exiled_with_self && total_max_mv.is_some();
                let mut st = make_step(
                    EffectOp::CastFree {
                        spec: Some(Box::new(CastFreeSpec {
                            copy_card_first: is_copy,
                            without_paying_mana_cost: free,
                            filter: None,
                            up_to_count: if (alt_mana.is_some() && is_copy) || has_exiled_total_cap
                            {
                                None
                            } else {
                                Some(if contains_ascii_ci(main_t.as_bytes(), b"any number") {
                                    99
                                } else {
                                    1
                                })
                            },
                            exile_if_put_into_graveyard: contains_ascii_ci(
                                main_t.as_bytes(),
                                b"exile it instead",
                            ),
                            alternative_mana_cost: alt_mana,
                            pay_life_equal_mana_value: pay_life_mv,
                            total_max_mv,
                            exiled_with_self: is_exiled_with_self,
                        })),
                        at_random: false,
                        cast_any_number_from_exiled: contains_ascii_ci(
                            main_t.as_bytes(),
                            b"any number",
                        ) && !has_exiled_total_cap,
                    },
                    subj,
                    span,
                );
                if (has_exiled_total_cap || ursine_one_exiled)
                    && starts_with_word_ci(main_t, "you may")
                {
                    st.optional = Some(OptionalSpec {
                        chooser: PlayerRef::You,
                        cost: Vec::new(),
                        mode: OptionalMode::DoIfPaid,
                    });
                }
                if let Some(c) = gate_cond {
                    attach_gate_condition(&mut st.gate, c);
                }
                state.push_step(st, false);
                return true;
            }
            let mut st = make_step(
                EffectOp::GrantPlayFromExile {
                    spec: PlayFromExileSpec {
                        duration: dur,
                        spend_mana_as_any_color: any_color,
                        spells_only: contains_ascii_ci(main_t.as_bytes(), b"you may cast")
                            || contains_ascii_ci(main_t.as_bytes(), b"its owner may cast"),
                        without_paying_mana_cost: free,
                        alternative_mana_cost: None,
                        pay_life_equal_mana_value: pay_life_mv,
                        cost_reduction_generic: None,
                        plotted: false,
                        total_max_mv: None,
                    },
                    select: SelectionMod::default(),
                    cast_spell_cost_tax_for_opponents: None,
                },
                subj.clone(),
                span,
            );
            if is_owner_actor {
                let owner_ref = match &subj {
                    Selector::Binding { name } => Some(Ref::Binding { name: name.clone() }),
                    Selector::Target { index } => Some(Ref::Target { index: *index }),
                    Selector::EventObject => Some(Ref::EventObject),
                    Selector::SelfObj => Some(Ref::SelfObj),
                    _ => None,
                };
                if let Some(r) = owner_ref {
                    st.actor = Some(PlayerRef::OwnerOf { of: Box::new(r) });
                }
            }
            if let Some(c) = gate_cond {
                attach_gate_condition(&mut st.gate, c);
            }
            state.push_step(st, false);
            return true;
        }
    }

    // 8. Dig: "Look at / Reveal the top N cards of [your|target opponent's|target player's] library. [Put one/K of them into your hand and the rest...]"
    if let Some((is_reveal_top, after_look)) = strip_prefix_word_ci(t, "look at the top")
        .map(|r| (false, r))
        .or_else(|| strip_prefix_word_ci(t, "reveal the top").map(|r| (true, r)))
        && let Some((amt, dig_subj, rest_dig)) = (|| {
            let trimmed_look = after_look.trim_start();
            let (amt_val, after_card_word) =
                if let Some(r) = strip_prefix_word_ci(trimmed_look, "card of") {
                    (Amount::Const { n: 1 }, r)
                } else {
                    let pos = find_word_ci(trimmed_look, " cards of ")?;
                    let amt_s = trimmed_look[..pos].trim();
                    let amt = parse_amount_str(amt_s, ctx, state)?;
                    (amt, trimmed_look[pos + " cards of ".len()..].trim())
                };
            let lib_rest = after_card_word.trim();
            if let Some(r) = strip_prefix_word_ci(lib_rest, "your library") {
                let rt = r.trim();
                if starts_with_word_ci(trimmed_look, "card of") && rt.is_empty() {
                    return None;
                }
                return Some((amt_val, you_sel(), rt));
            }
            if let Some(pos_lib) = find_word_ci(lib_rest, "'s library") {
                let owner_s = lib_rest[..pos_lib].trim();
                let rt = lib_rest[pos_lib + "'s library".len()..].trim();
                if !rt.is_empty()
                    && (contains_word_ci(rt, "exile it")
                        || contains_word_ci(rt, "exile them")
                        || contains_word_ci(rt, "exile those cards"))
                {
                    return None;
                }
                if let Some(psel) = parse_player_selector(owner_s, ctx, state) {
                    return Some((amt_val, psel, rt));
                }
            }
            None
        })()
    {
        if !rest_dig.is_empty()
            && starts_with_word_ci(rest_dig.trim_start_matches(',').trim(), "where")
        {
            return false;
        }
        if rest_dig.is_empty() {
            let mut st = make_step(
                EffectOp::Dig {
                    spec: Box::new(DigSpec {
                        keep: 1,
                        up_to: false,
                        keep_filter: None,
                        keep_all_matching: false,
                        keep_label: None,
                        keep_to: DigKeepTo::Hand,
                        keep_tapped: false,
                        keep_attacking: false,
                        keep_attacking_player: None,
                        reveal_all: is_reveal_top,
                        reveal_kept: false,
                        rest: DigRestTo::LibraryBottom,
                        rest_random: false,
                        rest_order: None,
                        until_filter: None,
                        rest_to_hand: false,
                        shuffle_rest: false,
                        keep_max_mana_value: None,
                        keep_max_mv_strict_lt: false,
                        choose_one_of_exiled: false,
                        play_from_exile: None,
                        partitions: Vec::new(),
                        destination_buckets: Vec::new(),
                    }),
                    look_only: true,
                },
                dig_subj,
                span,
            );
            st.amount = Some(Box::new(amt));
            st.bind_as = Some("revealed".to_string());
            let idx = state.steps.len();
            state.push_step(st, true);
            state.pending_dig = Some(idx);
            return true;
        }
        let mut spec = build_dig_spec(rest_dig, ctx);
        if is_reveal_top {
            spec.reveal_all = true;
        }
        let mut st = make_step(
            EffectOp::Dig {
                spec: Box::new(spec),
                look_only: false,
            },
            dig_subj,
            span,
        );
        st.amount = Some(Box::new(amt));
        st.bind_as = Some(state.alloc_bind_name("dig"));
        state.push_step(st, true);
        return true;
    }

    if let Some((rev_left, x_expr_opt)) = if let Some((l, x_expr)) = split_where_x_is(t) {
        Some((l, Some(x_expr)))
    } else {
        Some((t, None))
    } && let Some(after_rev) = strip_prefix_word_ci(
        rev_left,
        "reveal cards from the top of your library until you reveal",
    )
    .or_else(|| strip_prefix_word_ci(rev_left, "reveal cards from the top of it until you reveal"))
    {
        let (until_raw, rest_dig) = if let Some((l, r)) = split_at_top_level_comma(after_rev) {
            (l.trim(), r.trim())
        } else {
            (after_rev.trim(), "")
        };
        let (has_wild_vote, until_raw) = if state
            .steps
            .iter()
            .any(|s| matches!(s.op, EffectOp::Vote { .. }))
            && let Some(r) = strip_suffix_word_ci(until_raw, "for each wild vote")
        {
            (true, r)
        } else {
            (false, until_raw)
        };
        let (is_x_until, filt_after_art) = if x_expr_opt.is_some()
            && let Some(r) = strip_prefix_word_ci(until_raw, "x")
        {
            (true, r)
        } else {
            let s = strip_prefix_word_ci(until_raw, "a")
                .or_else(|| strip_prefix_word_ci(until_raw, "an"))
                .unwrap_or(until_raw);
            (false, s)
        };
        let x_amt_opt = if is_x_until && let Some(xe) = x_expr_opt {
            parse_amount_str(xe, ctx, state)
        } else {
            None
        };
        if !is_x_until || x_amt_opt.is_some() {
            let cp = ctx.interner.checkpoint();
            if let Some(f) = parse_object_phrase(
                filt_after_art,
                ctx,
                FilterOpts {
                    default_zone: ZoneMask::empty(),
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: true,
                    ..Default::default()
                },
            ) {
                let amt = if has_wild_vote {
                    Amount::Const { n: 1 }
                } else {
                    x_amt_opt.unwrap_or(Amount::Const { n: 999 })
                };
                let keep_n = if is_x_until || has_wild_vote { 99 } else { 1 };
                if rest_dig.is_empty() {
                    let mut st = make_step(
                        EffectOp::Dig {
                            spec: Box::new(DigSpec {
                                keep: keep_n,
                                up_to: false,
                                keep_filter: None,
                                keep_all_matching: false,
                                keep_label: None,
                                keep_to: DigKeepTo::Hand,
                                keep_tapped: false,
                                keep_attacking: false,
                                keep_attacking_player: None,
                                reveal_all: true,
                                reveal_kept: false,
                                rest: DigRestTo::LibraryBottom,
                                rest_random: false,
                                rest_order: None,
                                until_filter: Some(Box::new(f)),
                                rest_to_hand: false,
                                shuffle_rest: false,
                                keep_max_mana_value: None,
                                keep_max_mv_strict_lt: false,
                                choose_one_of_exiled: false,
                                play_from_exile: None,
                                partitions: Vec::new(),
                                destination_buckets: Vec::new(),
                            }),
                            look_only: true,
                        },
                        you_sel(),
                        span,
                    );
                    st.amount = Some(Box::new(amt));
                    st.bind_as = Some("revealed".to_string());
                    let idx = state.steps.len();
                    state.push_step(st, true);
                    state.pending_dig = Some(idx);
                    return true;
                }
                let mut spec = build_dig_spec(rest_dig, ctx);
                if is_x_until {
                    spec.keep = keep_n;
                }
                spec.reveal_all = true;
                spec.until_filter = Some(Box::new(f));
                let mut st = make_step(
                    EffectOp::Dig {
                        spec: Box::new(spec),
                        look_only: false,
                    },
                    you_sel(),
                    span,
                );
                st.amount = Some(Box::new(amt));
                st.bind_as = Some(state.alloc_bind_name("dig"));
                state.push_step(st, true);
                return true;
            }
            ctx.interner.rollback(cp);
        }
    }

    if (starts_with_word_ci(t, "choose a card at random exiled with")
        || starts_with_word_ci(t, "choose a creature card at random exiled with"))
        && find_word_ci(t, "put it onto the battlefield").is_some()
    {
        let tapped = contains_word_ci(t, "tapped");
        state.push_step(
            make_step(
                EffectOp::Move {
                    from: Some(Zone::Exile),
                    to: Some(Zone::Battlefield),
                    select: SelectionMod::default(),
                    tapped,
                    under_your_control: true,
                    topmost_only: false,
                    may_shuffle: false,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: true,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                Selector::All {
                    filter: Box::new(ObjectFilter {
                        zones: ZoneMask::EXILE,
                        extra: vec![ObjectPredicate::ExiledWithSelf],
                        ..Default::default()
                    }),
                },
                span,
            ),
            false,
        );
        return true;
    }

    // Reflect Damage: "The next time a source of your choice would deal damage this turn, that damage is dealt to that source's controller instead"
    if starts_with_word_ci(
        t,
        "the next time a source of your choice would deal damage this turn",
    ) && find_word_ci(t, "is dealt to that source's controller instead").is_some()
    {
        state.push_step(
            make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::All,
                        combat_only: false,
                        scope: PreventScope::Any,
                        from_source: None,
                        also_prevent_dealt_by_subject: false,
                        choose_source: true,
                        next_damage_event_only: true,
                        on_prevented: None,
                        redirect_to: Some(PreventRedirectTo::SourceController),
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: false,
                        from_sources_you_dont_control: false,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }

    // Mirror Strike: "All combat damage that would be dealt to you this turn by <obj> is dealt to its controller instead"
    if let Some(after_by) = strip_prefix_word_ci(
        t,
        "all combat damage that would be dealt to you this turn by",
    )
    .or_else(|| {
        strip_prefix_word_ci(
            t,
            "all combat damage that would be dealt this turn to you by",
        )
    }) && let Some(src_raw) =
        strip_suffix_word_ci(after_by, "is dealt to its controller instead")
        && let Some(src_obj) = parse_object_selector(src_raw, ZoneMask::BATTLEFIELD, ctx, state)
    {
        state.push_step(
            make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::All,
                        combat_only: true,
                        scope: PreventScope::Subject,
                        from_source: Some(Box::new(src_obj.into_selector())),
                        also_prevent_dealt_by_subject: false,
                        choose_source: false,
                        next_damage_event_only: false,
                        on_prevented: None,
                        redirect_to: Some(PreventRedirectTo::SourceController),
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: false,
                        from_sources_you_dont_control: false,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }

    // 9. PartitionKeepByTypes (*Single Combat*, *Cataclysmic Gearhulk*, *Liliana, Dreadhorde General*, *Divine Reckoning*)
    if starts_with_word_ci(t, "each player chooses a creature")
        && find_word_ci(
            t,
            "from among the permanents they control, then sacrifices the rest",
        )
        .is_some()
    {
        state.push_step(
            make_step(
                EffectOp::PartitionKeepByTypes {
                    types: CardTypeMask::CREATURE,
                    keep_count_per_player: Some(Box::new(Amount::Const { n: 1 })),
                    chooser_you: false,
                    all_types: false,
                    nonland_only: false,
                    put_vow_counter: false,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(
        t,
        "each player chooses an artifact, a creature, an enchantment, and a planeswalker from among the nonland permanents they control, then sacrifices the rest",
    ) {
        state.push_step(
            make_step(
                EffectOp::PartitionKeepByTypes {
                    types: CardTypeMask::from_bits_truncate(
                        CardTypeMask::ARTIFACT.bits()
                            | CardTypeMask::CREATURE.bits()
                            | CardTypeMask::ENCHANTMENT.bits()
                            | CardTypeMask::PLANESWALKER.bits(),
                    ),
                    keep_count_per_player: None,
                    chooser_you: false,
                    all_types: false,
                    nonland_only: true,
                    put_vow_counter: false,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }
    if eq_ci(
        t,
        "each opponent chooses a permanent they control of each permanent type and sacrifices the rest",
    ) {
        let mut st = make_step(
            EffectOp::PartitionKeepByTypes {
                types: CardTypeMask::empty(),
                keep_count_per_player: None,
                chooser_you: false,
                all_types: true,
                nonland_only: false,
                put_vow_counter: false,
            },
            Selector::None,
            span,
        );
        st.actor = Some(PlayerRef::EachLoopPlayer);
        state.push_step(st, false);
        return true;
    }
    if let Some((is_event_player, after_ch)) = strip_prefix_word_ci(t, "each player chooses")
        .map(|r| (false, r))
        .or_else(|| strip_prefix_word_ci(t, "that player chooses").map(|r| (true, r)))
        && let Some(keep_raw) =
            strip_suffix_word_ci(after_ch, "they control, then sacrifices the rest")
    {
        let keep_body = strip_prefix_word_ci(keep_raw, "up to").unwrap_or(keep_raw);
        let mut parts = keep_body.split_whitespace();
        if let (Some(num_w), Some(type_w), None) = (parts.next(), parts.next(), parts.next())
            && let Some(n) = parse_small_number(num_w)
        {
            let tmask = if eq_ci(type_w, "land") || eq_ci(type_w, "lands") {
                Some(CardTypeMask::LAND)
            } else if eq_ci(type_w, "creature") || eq_ci(type_w, "creatures") {
                Some(CardTypeMask::CREATURE)
            } else if eq_ci(type_w, "artifact") || eq_ci(type_w, "artifacts") {
                Some(CardTypeMask::ARTIFACT)
            } else if eq_ci(type_w, "enchantment") || eq_ci(type_w, "enchantments") {
                Some(CardTypeMask::ENCHANTMENT)
            } else if eq_ci(type_w, "planeswalker") || eq_ci(type_w, "planeswalkers") {
                Some(CardTypeMask::PLANESWALKER)
            } else if eq_ci(type_w, "permanent") || eq_ci(type_w, "permanents") {
                Some(CardTypeMask::empty())
            } else {
                None
            };
            if let Some(types) = tmask {
                let mut st = make_step(
                    EffectOp::PartitionKeepByTypes {
                        types,
                        keep_count_per_player: Some(Box::new(Amount::Const { n })),
                        chooser_you: false,
                        all_types: false,
                        nonland_only: false,
                        put_vow_counter: false,
                    },
                    Selector::None,
                    span,
                );
                if is_event_player {
                    st.actor = Some(PlayerRef::EventPlayer);
                }
                state.push_step(st, false);
                return true;
            }
        }
    }

    // 10. ReselectAttackTarget (*Portal Manipulator*, *Portal Mage*, *Misleading Signpost*)
    if let Some(after_reselect) = strip_prefix_word_ci(t, "reselect which player or planeswalker")
        .or_else(|| strip_prefix_word_ci(t, "reselect which player or permanent"))
        && let Some(subj_s) = strip_suffix_word_ci(after_reselect, "is attacking")
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            let track = matches!(obj, ParsedObj::Target(_));
            state.push_step(
                make_step(EffectOp::ReselectAttackTarget, obj.into_selector(), span),
                track,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 11. RedirectTargets
    if let Some(rest_raw) = strip_prefix_word_ci(t, "you may change the target of")
        .map(|r| (r, true))
        .or_else(|| strip_prefix_word_ci(t, "change the target of").map(|r| (r, false)))
    {
        let (rest, is_opt) = rest_raw;
        let rest_trimmed = trim_trailing_period(rest).trim();
        let (tgt_part, force_self) = if let Some(p) = strip_suffix_word_ci(rest_trimmed, "to ~")
            .or_else(|| strip_suffix_word_ci(rest_trimmed, "to this creature"))
            .or_else(|| strip_suffix_word_ci(rest_trimmed, "to this permanent"))
            .or_else(|| strip_suffix_word_ci(rest_trimmed, "to it"))
        {
            (p.trim(), true)
        } else {
            (rest_trimmed, false)
        };
        if let Some(obj) = parse_object_selector(tgt_part, ZoneMask::STACK, ctx, state) {
            let track = matches!(obj, ParsedObj::Target(_));
            if let ParsedObj::Target(idx) = &obj {
                state.last_object = Some((Ref::Target { index: *idx }, state.steps.len()));
            }
            let sel = obj.into_selector();
            let mut st = make_step(
                EffectOp::RedirectTargets {
                    spec: RedirectTargetsSpec {
                        mode: RedirectMode::ChangeSingleTarget,
                        force_target_self: force_self,
                    },
                },
                sel,
                span,
            );
            if is_opt {
                st.optional = Some(OptionalSpec {
                    chooser: PlayerRef::You,
                    cost: Vec::new(),
                    mode: OptionalMode::DoIfPaid,
                });
            }
            state.push_step(st, track);
            return true;
        }
    }
    if let Some((rest, is_opt)) = strip_prefix_word_ci(t, "you may choose new targets for")
        .map(|r| (r, true))
        .or_else(|| strip_prefix_word_ci(t, "choose new targets for").map(|r| (r, false)))
    {
        let rest_trimmed = trim_trailing_period(rest).trim();
        let (tgt_part, force_self) = if let Some(p) = strip_suffix_word_ci(rest_trimmed, "to ~")
            .or_else(|| strip_suffix_word_ci(rest_trimmed, "to this creature"))
            .or_else(|| strip_suffix_word_ci(rest_trimmed, "to this permanent"))
        {
            (p.trim(), true)
        } else {
            (rest_trimmed, false)
        };
        if let Some(obj) = parse_object_selector(tgt_part, ZoneMask::STACK, ctx, state) {
            let track = matches!(obj, ParsedObj::Target(_));
            if let ParsedObj::Target(idx) = &obj {
                state.last_object = Some((Ref::Target { index: *idx }, state.steps.len()));
            }
            let sel = obj.into_selector();
            let mut st = make_step(
                EffectOp::RedirectTargets {
                    spec: RedirectTargetsSpec {
                        mode: RedirectMode::ChooseNewTargets,
                        force_target_self: force_self,
                    },
                },
                sel,
                span,
            );
            if is_opt {
                st.optional = Some(OptionalSpec {
                    chooser: PlayerRef::You,
                    cost: Vec::new(),
                    mode: OptionalMode::DoIfPaid,
                });
            }
            state.push_step(st, track);
            return true;
        }
    }

    // 12. DelayedNextSpellCopy (*Double Vision*, *Swarm Intelligence*, *Teach by Example*)
    if eq_ci(
        t,
        "when you next cast an instant or sorcery spell this turn, copy that spell",
    ) || eq_ci(
        t,
        "when you cast your next instant or sorcery spell this turn, copy it",
    ) {
        state.push_step(
            make_step(
                EffectOp::DelayedNextSpellCopy {
                    types: CardTypeMask::INSTANT | CardTypeMask::SORCERY,
                    not_types: CardTypeMask::empty(),
                    colors: ColorMask::empty(),
                    copy_count: 1,
                    may_choose_new_targets: true,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }

    // 13. DelayedTapManaTrigger (*Bubbling Muck*, *High Tide*, *Heartbeat of Spring*)
    if eq_ci(
        t,
        "until end of turn, whenever a player taps a swamp for mana, that player adds an additional {b}",
    ) {
        let swamp = ctx.interner.intern_subtype("Swamp");
        state.push_step(
            make_step(
                EffectOp::DelayedTapManaTrigger {
                    all_players: true,
                    land_subtype: Some(swamp),
                    mana: smallvec![ManaColor::B],
                    to_tapping_player: true,
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }

    // 14. Vote / VillainousChoice / PileSplit
    if let Some(after) = strip_prefix_word_ci(t, "starting with you, each player votes for")
        .or_else(|| strip_prefix_word_ci(t, "each player votes for"))
        && let Some((opt_a, opt_b)) = after.split_once(" or ")
    {
        state.push_step(
            make_step(
                EffectOp::Vote {
                    spec: VoteSpec {
                        options: vec![opt_a.trim().to_string(), opt_b.trim().to_string()],
                        extra_votes_for_actor: 0,
                        per_option_effect: Vec::new(),
                        per_winning_effect: Vec::new(),
                        tie_winner_index: None,
                    },
                },
                Selector::None,
                span,
            ),
            false,
        );
        return true;
    }

    // 15. Optional cost sentence: "You may <cost>. If you do, <effect>" handled across sentences or standalone PayCost
    if let Some((after_pay, chooser)) = strip_prefix_word_ci(t, "you may pay")
        .map(|r| (r, PlayerRef::You))
        .or_else(|| {
            strip_prefix_word_ci(t, "its controller may pay")
                .or_else(|| strip_prefix_word_ci(t, "their controller may pay"))
                .or_else(|| strip_prefix_word_ci(t, "that creature's controller may pay"))
                .or_else(|| strip_prefix_word_ci(t, "that permanent's controller may pay"))
                .map(|r| {
                    (
                        r,
                        PlayerRef::ControllerOf {
                            of: Box::new(state.it_ref().unwrap_or(Ref::EventObject)),
                        },
                    )
                })
        })
        .or_else(|| {
            strip_prefix_word_ci(t, "that player may pay")
                .or_else(|| strip_prefix_word_ci(t, "that opponent may pay"))
                .or_else(|| strip_prefix_word_ci(t, "they may pay"))
                .map(|r| {
                    (
                        r,
                        state.single_player_ref().unwrap_or(PlayerRef::EventPlayer),
                    )
                })
        })
    {
        if eq_ci(
            after_pay,
            "{x}, where x is less than or equal to the amount of life you gained",
        ) {
            let mut st = make_step(
                EffectOp::Grant {
                    keywords: SmallVec::new(),
                    remove_keywords: SmallVec::new(),
                    cant_have_or_gain: false,
                    duration: Some(Duration::EndOfTurn),
                    granted_ability_texts: Vec::new(),
                    choose_keyword_options: SmallVec::new(),
                    choose_lose_keyword_options: SmallVec::new(),
                    choose_protection_color: false,
                    remove_all_abilities: false,
                    can_attack_no_defender: false,
                    must_attack_this_turn: false,
                    must_be_blocked_this_turn: false,
                    must_block_this_turn: false,
                    must_block_self_this_turn: false,
                    cant_block_self_this_turn: false,
                    cant_be_blocked_by_opponents_creatures: false,
                    assigns_no_combat_damage_this_turn: false,
                    grant_suspend_if_missing: false,
                    exile_resolving_spell_to_linked: false,
                    grant_trigger_spell_sunburst: false,
                    pay_any_mana_for_damage: None,
                    pay_up_to_life_gained_mana_to_draw: true,
                    gambit_combat_directive: false,
                },
                Selector::SelfObj,
                span,
            );
            st.optional = None;
            let idx = state.steps.len();
            state.push_step(st, false);
            state.last_optional_step = Some(idx);
            state.defined_x = Some(Amount::LastEffectAmount);
            return true;
        }
        if let Some(col_s) = strip_prefix_word_ci(after_pay, "any amount of") {
            let color = match col_s.trim().to_ascii_uppercase().as_str() {
                "{W}" => Some(mtg_ir::ManaColor::W),
                "{U}" => Some(mtg_ir::ManaColor::U),
                "{B}" => Some(mtg_ir::ManaColor::B),
                "{R}" => Some(mtg_ir::ManaColor::R),
                "{G}" => Some(mtg_ir::ManaColor::G),
                "{C}" => Some(mtg_ir::ManaColor::C),
                _ => None,
            };
            if let Some(c) = color {
                let st = make_step(
                    EffectOp::Grant {
                        keywords: SmallVec::new(),
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: Some(Duration::EndOfTurn),
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: Some(c),
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    Selector::SelfObj,
                    span,
                );
                let idx = state.steps.len();
                state.push_step(st, true);
                state.last_optional_step = Some(idx);
                return true;
            }
        }
        let mut cost_parse = crate::parser::cost::parse_cost_list(after_pay, span.start, ctx);
        if (cost_parse.defs.is_empty() || !cost_parse.unparsed.is_empty())
            && !starts_with_word_ci(after_pay, "pay")
        {
            let with_pay = format!("pay {after_pay}");
            let try_pay = crate::parser::cost::parse_cost_list(&with_pay, span.start, ctx);
            if !try_pay.defs.is_empty() && try_pay.unparsed.is_empty() {
                cost_parse = try_pay;
            }
        }
        if (cost_parse.defs.is_empty() || !cost_parse.unparsed.is_empty())
            && let Some(pos) = find_word_ci(after_pay, " and ")
        {
            let rewritten = format!(
                "{}, pay {}",
                after_pay[..pos].trim(),
                after_pay[pos + 5..].trim()
            );
            cost_parse = crate::parser::cost::parse_cost_list(&rewritten, span.start, ctx);
        }
        if !cost_parse.defs.is_empty() && cost_parse.unparsed.is_empty() {
            let last_pr = (!matches!(chooser, PlayerRef::You)).then(|| chooser.clone());
            let mut st = make_step(EffectOp::PayCost, Selector::None, span);
            st.optional = Some(OptionalSpec {
                chooser,
                cost: cost_parse.defs,
                mode: OptionalMode::DoIfPaid,
            });
            let idx = state.steps.len();
            state.push_step(st, false);
            state.last_optional_step = Some(idx);
            if let Some(pr) = last_pr {
                state.last_player = Some(Selector::PlayerRef { player: pr });
            }
            return true;
        }
    }
    if let Some(after_may) = strip_prefix_word_ci(t, "you may")
        && (starts_with_word_ci(after_may.trim_start(), "remove")
            || starts_with_word_ci(after_may.trim_start(), "exile")
            || starts_with_word_ci(after_may.trim_start(), "tap"))
        && !contains_word_ci(after_may, "up to")
        && !contains_word_ci(after_may, "target")
    {
        let body = after_may.trim();
        let cp = ctx.interner.checkpoint();
        let cost_parse = crate::parser::cost::parse_cost_list(body, span.start, ctx);
        if cost_parse.defs.len() == 1
            && cost_parse.unparsed.is_empty()
            && matches!(
                cost_parse.defs[0],
                mtg_ir::CostDef::RemoveCounters { .. }
                    | mtg_ir::CostDef::TapOthers { .. }
                    | mtg_ir::CostDef::ExileFrom {
                        zone: Zone::Graveyard,
                        ..
                    }
            )
        {
            let is_exile_from = matches!(cost_parse.defs[0], mtg_ir::CostDef::ExileFrom { .. });
            let is_tap_x = matches!(
                &cost_parse.defs[0],
                mtg_ir::CostDef::TapOthers { count, .. } if matches!(**count, Amount::X)
            );
            let mut st = make_step(EffectOp::PayCost, Selector::None, span);
            st.optional = Some(OptionalSpec {
                chooser: PlayerRef::You,
                cost: cost_parse.defs,
                mode: OptionalMode::DoIfPaid,
            });
            let idx = state.steps.len();
            state.push_step(st, false);
            state.last_optional_step = Some(idx);
            if is_exile_from {
                state.last_object = Some((Ref::EventObject, idx));
            }
            if is_tap_x {
                state.defined_x = Some(Amount::CountedThisWay {
                    kind: CountedThisWayKind::TappedThisWay,
                });
            }
            return true;
        }
        ctx.interner.rollback(cp);
    }

    // 16. "Those tokens have \"...\"" (after CreateToken)
    if let Some(after) = strip_prefix_word_ci(t, "those tokens have")
        && let Some(q) = strip_outer_quotes(after)
        && matches!(
            state.steps.last().map(|s| &s.op),
            Some(EffectOp::CreateToken { token: Some(_), .. })
        )
    {
        state.compile_quoted(q, "Token", ctx);
        if let Some(prev) = state.steps.last_mut()
            && let EffectOp::CreateToken {
                token: Some(ref mut spec),
                ..
            } = prev.op
        {
            spec.quoted_abilities.push(q.to_string());
        }
        return true;
    }

    // 17. "It's still a land." / "They're still lands." (after Animate)
    if (eq_ci(t, "it's still a land") || eq_ci(t, "they're still lands"))
        && let Some(prev) = state.steps.last_mut()
        && let EffectOp::Animate {
            ref mut set_types,
            ref mut add_types,
            ref mut set_subtypes,
            ref mut add_subtypes,
            ref mut keep_existing_types,
            ref mut still_a_land,
            ..
        } = prev.op
    {
        if let Some(st) = set_types.take() {
            *add_types |= st;
        }
        if let Some(ss) = set_subtypes.take() {
            add_subtypes.extend(ss);
        }
        *keep_existing_types = true;
        *still_a_land = false;
        return true;
    }

    // 18. Trailing "do this only once each turn" handled in sentence loop too
    if eq_ci(t, "do this only once each turn") && !state.steps.is_empty() {
        let mut idx = if state.prev_sentence_step_start < state.steps.len() {
            state.prev_sentence_step_start
        } else {
            state.steps.len() - 1
        };
        while let Some(StepGate::IfPrecedingAccepted { step_index }) = state.steps[idx].gate {
            let root = step_index as usize;
            if root < idx {
                idx = root;
            } else {
                break;
            }
        }
        state.steps[idx].do_this_once_per_turn = true;
        return true;
    }

    if eq_ci(t, "you may choose new targets for the copy")
        || eq_ci(t, "you may choose new targets for that copy")
        || eq_ci(t, "you may choose new targets for the copies")
        || eq_ci(t, "you may choose new targets for it")
    {
        for prev in state.steps.iter_mut().rev().take(2) {
            match prev.op {
                EffectOp::CopySpell {
                    ref mut may_choose_new_targets,
                    ..
                }
                | EffectOp::DelayedNextSpellCopy {
                    ref mut may_choose_new_targets,
                    ..
                } => {
                    *may_choose_new_targets = true;
                    return true;
                }
                _ => {}
            }
        }
    }

    parse_extra_precon_ops(t, span, ctx, state)
}

fn count_energy_pips(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut n = 0i32;
    let mut i = 0;
    while i + 2 < bytes.len() {
        if bytes[i] == b'{'
            && (bytes[i + 1] == b'E' || bytes[i + 1] == b'e')
            && bytes[i + 2] == b'}'
        {
            n += 1;
            i += 3;
        } else {
            i += 1;
        }
    }
    n
}

fn parse_extra_precon_ops(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    if contains_word_ci(t, "emblem") && parse_emblem_clause(t, span, state) {
        return true;
    }

    // 1. GainEnergy: "you get {E}{E}" / "get {E}" / "target player gets {E}{E}"
    if (t.as_bytes().windows(3).any(|w| w == b"{E}" || w == b"{e}"))
        && let Some(e_pos) = find_word_ci(t, "gets {e}").or_else(|| find_word_ci(t, "get {e}"))
    {
        let who_s = t[..e_pos].trim();
        let after = t[e_pos..].trim();
        let pips_s = strip_prefix_word_ci(after, "gets")
            .or_else(|| strip_prefix_word_ci(after, "get"))
            .unwrap_or(after);
        let n = count_energy_pips(pips_s);
        if n > 0 {
            let mark_ge = state.mark(ctx);
            let subj_opt = if who_s.is_empty() {
                Some(you_sel())
            } else {
                parse_player_selector(who_s, ctx, state)
            };
            if let Some(subj) = subj_opt {
                let mut st = make_step(EffectOp::GainEnergy, subj, span);
                st.amount = Some(Box::new(Amount::Const { n }));
                state.push_step(st, false);
                return true;
            }
            state.rollback(mark_ge, ctx);
        }
    }

    // 2. Airbend / Cloak / Connive / Explore / Saddle / Prepare / Unprepare / IncreaseSpeed / Meld / Assimilate / EmpowerJace / Recruit / Heal / Flip
    if let Some(obj_s) = strip_prefix_word_ci(t, "airbend") {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(obj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(EffectOp::Airbend, obj.into_selector(), span),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(rest) = strip_prefix_word_ci(t, "cloak") {
        let amt = if starts_with_word_ci(rest, "the top card") {
            Amount::Const { n: 1 }
        } else if let Some(after_top) = strip_prefix_word_ci(rest, "the top") {
            let num_w = after_top.split_whitespace().next().unwrap_or("");
            parse_count_word(num_w).unwrap_or(Amount::Const { n: 1 })
        } else {
            Amount::Const { n: 1 }
        };
        let mut st = make_step(EffectOp::Cloak, you_sel(), span);
        st.amount = Some(Box::new(amt));
        state.push_step(st, true);
        return true;
    }
    if let Some((left_conn, x_expr)) = split_where_x_is(t)
        && let Some(subj_s) = strip_suffix_word_ci(left_conn, "connives x")
            .or_else(|| strip_suffix_word_ci(left_conn, "connive x"))
        && let Some(amt) = parse_amount_str(x_expr, ctx, state)
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            let mut st = make_step(
                EffectOp::Connive {
                    for_each_convoking_creature_steps: Vec::new(),
                },
                obj.into_selector(),
                span,
            );
            st.amount = Some(Box::new(amt));
            state.push_step(st, false);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) =
        strip_suffix_word_ci(t, "connives").or_else(|| strip_suffix_word_ci(t, "connive"))
    {
        if eq_ci(subj_s, "each creature that convoked this spell")
            || eq_ci(subj_s, "each creature that convoked ~")
        {
            let mut inner = make_step(
                EffectOp::Connive {
                    for_each_convoking_creature_steps: Vec::new(),
                },
                Selector::SelfObj,
                span,
            );
            inner.amount = Some(Box::new(Amount::Const { n: 1 }));
            state.push_step(
                make_step(
                    EffectOp::Connive {
                        for_each_convoking_creature_steps: vec![inner],
                    },
                    Selector::All {
                        filter: Box::new(ObjectFilter {
                            zones: ZoneMask::BATTLEFIELD,
                            types_any: CardTypeMask::CREATURE,
                            ..Default::default()
                        }),
                    },
                    span,
                ),
                false,
            );
            return true;
        }
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            let mut st = make_step(
                EffectOp::Connive {
                    for_each_convoking_creature_steps: Vec::new(),
                },
                obj.into_selector(),
                span,
            );
            st.amount = Some(Box::new(Amount::Const { n: 1 }));
            state.push_step(st, false);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) =
        strip_suffix_word_ci(t, "explores").or_else(|| strip_suffix_word_ci(t, "explore"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(EffectOp::Explore, obj.into_selector(), span),
                false,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) =
        strip_suffix_word_ci(t, "phases out").or_else(|| strip_suffix_word_ci(t, "phase out"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(
                    EffectOp::PhaseOut {
                        select: SelectionMod::default(),
                        cant_phase_in_while_source_controlled: false,
                    },
                    obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(rest) = strip_prefix_word_ci(t, "turn") {
        let (obj_s, face_up) = if let Some(p) = strip_suffix_word_ci(rest, "face up") {
            (Some(p), true)
        } else if let Some(p) = strip_suffix_word_ci(rest, "face down") {
            (Some(p), false)
        } else {
            (None, false)
        };
        if let Some(os) = obj_s {
            let mark = state.mark(ctx);
            if let Some(obj) = parse_object_selector(os, ZoneMask::BATTLEFIELD, ctx, state) {
                let singular_choice = matches!(obj, ParsedObj::All(_))
                    && (starts_with_word_ci(os, "a ") || starts_with_word_ci(os, "an "));
                state.push_step(
                    make_step(
                        EffectOp::TurnFace {
                            face_up,
                            select: SelectionMod {
                                choice_count: singular_choice
                                    .then(|| Box::new(Amount::Const { n: 1 })),
                                ..Default::default()
                            },
                        },
                        obj.into_selector(),
                        span,
                    ),
                    true,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    if eq_ci(t, "flip ~") || eq_ci(t, "flip it") {
        let subj = state
            .it_ref()
            .map(|r| ref_to_selector(&r))
            .unwrap_or(Selector::SelfObj);
        state.push_step(make_step(EffectOp::Flip, subj, span), false);
        return true;
    }
    if eq_ci(t, "prepare ~")
        || eq_ci(t, "prepare it")
        || eq_ci(t, "~ becomes prepared")
        || eq_ci(t, "it becomes prepared")
    {
        let subj = if eq_ci(t, "prepare it") || eq_ci(t, "it becomes prepared") {
            state
                .it_ref()
                .map(|r| ref_to_selector(&r))
                .unwrap_or(Selector::SelfObj)
        } else {
            Selector::SelfObj
        };
        state.push_step(make_step(EffectOp::Prepare, subj, span), false);
        return true;
    }
    if let Some(subj_s) = strip_suffix_word_ci(t, "becomes prepared")
        .or_else(|| strip_suffix_word_ci(t, "become prepared"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(EffectOp::Prepare, obj.into_selector(), span),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if eq_ci(t, "unprepare ~")
        || eq_ci(t, "unprepare it")
        || eq_ci(t, "~ becomes unprepared")
        || eq_ci(t, "it becomes unprepared")
        || eq_ci(t, "~ is no longer prepared")
        || eq_ci(t, "it is no longer prepared")
    {
        let subj = if starts_with_word_ci(t, "it") || eq_ci(t, "unprepare it") {
            state
                .it_ref()
                .map(|r| ref_to_selector(&r))
                .unwrap_or(Selector::SelfObj)
        } else {
            Selector::SelfObj
        };
        state.push_step(make_step(EffectOp::Unprepare, subj, span), false);
        return true;
    }
    if let Some(subj_s) = strip_suffix_word_ci(t, "becomes unprepared")
        .or_else(|| strip_suffix_word_ci(t, "become unprepared"))
        .or_else(|| strip_suffix_word_ci(t, "is no longer prepared"))
        .or_else(|| strip_suffix_word_ci(t, "are no longer prepared"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(EffectOp::Unprepare, obj.into_selector(), span),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(e_pos) = find_word_ci(t, " endures ") {
        let subj_s = t[..e_pos].trim();
        let amt_s = t[e_pos + " endures ".len()..].trim();
        let mark = state.mark(ctx);
        if let Some(amt) = parse_amount_str(amt_s, ctx, state) {
            let subj = if eq_ci(subj_s, "~") || eq_ci(subj_s, "it") {
                Some(if eq_ci(subj_s, "it") {
                    state
                        .it_ref()
                        .map(|r| ref_to_selector(&r))
                        .unwrap_or(Selector::SelfObj)
                } else {
                    Selector::SelfObj
                })
            } else {
                parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state)
                    .map(ParsedObj::into_selector)
            };
            if let Some(sel) = subj {
                let mut st = make_step(EffectOp::Endure, sel, span);
                st.amount = Some(Box::new(amt));
                state.push_step(st, false);
                return true;
            }
        }
        state.rollback(mark, ctx);
    }
    if eq_ci(t, "increase your speed") || eq_ci(t, "you start your engines") {
        state.push_step(make_step(EffectOp::IncreaseSpeed, you_sel(), span), false);
        return true;
    }
    if eq_ci(t, "saddle") || eq_ci(t, "saddle ~") {
        state.push_step(make_step(EffectOp::Saddle, Selector::SelfObj, span), false);
        return true;
    }
    if eq_ci(t, "empower jace") {
        state.push_step(make_step(EffectOp::EmpowerJace, you_sel(), span), false);
        return true;
    }
    if let Some(rest) = strip_prefix_word_ci(t, "empower jace")
        .or_else(|| strip_prefix_word_ci(t, "you empower jace"))
        && let Some(amt) = parse_amount_str(rest.trim(), ctx, state)
    {
        let mut st = make_step(EffectOp::EmpowerJace, you_sel(), span);
        st.amount = Some(Box::new(amt));
        state.push_step(st, true);
        return true;
    }
    if eq_ci(t, "recruit") || eq_ci(t, "you recruit") || eq_ci(t, "recruit once") {
        let mut st = make_step(EffectOp::Recruit, you_sel(), span);
        st.amount = Some(Box::new(Amount::Const { n: 1 }));
        state.push_step(st, true);
        return true;
    }
    if eq_ci(t, "recruit twice") || eq_ci(t, "you recruit twice") {
        let mut st = make_step(EffectOp::Recruit, you_sel(), span);
        st.amount = Some(Box::new(Amount::Const { n: 2 }));
        state.push_step(st, true);
        return true;
    }
    if let Some(rest) =
        strip_prefix_word_ci(t, "recruit").or_else(|| strip_prefix_word_ci(t, "you recruit"))
        && let Some(num_s) = strip_suffix_word_ci(rest.trim(), "times")
            .or_else(|| strip_suffix_word_ci(rest.trim(), "time"))
        && let Some(amt) = parse_amount_str(num_s.trim(), ctx, state)
    {
        let mut st = make_step(EffectOp::Recruit, you_sel(), span);
        st.amount = Some(Box::new(amt));
        state.push_step(st, true);
        return true;
    }
    if let Some(rest) = strip_prefix_word_ci(t, "assimilate") {
        let mark = state.mark(ctx);
        let subj = parse_object_selector(rest, ZoneMask::BATTLEFIELD, ctx, state)
            .map(ParsedObj::into_selector)
            .unwrap_or(Selector::SelfObj);
        if matches!(subj, Selector::SelfObj) {
            state.rollback(mark, ctx);
        }
        state.push_step(make_step(EffectOp::Assimilate, subj, span), true);
        return true;
    }
    if let Some(rest) = strip_prefix_word_ci(t, "heal") {
        let mark = state.mark(ctx);
        let subj = parse_object_selector(rest, ZoneMask::BATTLEFIELD, ctx, state)
            .map(ParsedObj::into_selector)
            .unwrap_or(Selector::SelfObj);
        if matches!(subj, Selector::SelfObj) {
            state.rollback(mark, ctx);
        }
        state.push_step(make_step(EffectOp::Heal, subj, span), false);
        return true;
    }
    if starts_with_word_ci(t, "exile")
        && let Some(m_pos) = find_word_ci(t, ", then meld them into ")
    {
        let result_name = t[m_pos + ", then meld them into ".len()..]
            .trim()
            .to_string();
        let partner_name = strip_prefix_word_ci(&t[..m_pos], "exile")
            .unwrap_or("")
            .trim()
            .to_string();
        state.push_step(
            make_step(
                EffectOp::Meld {
                    partner_name,
                    result_name,
                    tapped_and_attacking: find_word_ci(t, "tapped and attacking").is_some(),
                    partner_must_attack: false,
                },
                Selector::SelfObj,
                span,
            ),
            true,
        );
        return true;
    }

    if let Some(after_blk) = strip_prefix_word_ci(t, "all creatures able to block")
        && let Some(subj_s) = strip_suffix_word_ci(after_blk, "this turn do so")
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: SmallVec::new(),
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: Some(Duration::EndOfTurn),
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: true,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    obj.into_selector(),
                    span,
                ),
                true,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 3. CantRegenerate & ExileInsteadOfDying
    if let Some(subj_s) = strip_suffix_word_ci(t, "can't be regenerated this turn")
        .or_else(|| strip_suffix_word_ci(t, "can't be regenerated"))
    {
        if (eq_ci(subj_s, "it")
            || eq_ci(subj_s, "that creature")
            || eq_ci(subj_s, "that permanent")
            || eq_ci(subj_s, "those creatures"))
            && let Some(prev) = state.steps.last_mut()
            && let EffectOp::Destroy {
                ref mut cant_be_regenerated,
                ..
            } = prev.op
        {
            *cant_be_regenerated = true;
            return true;
        }
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state) {
            state.push_step(
                make_step(EffectOp::CantRegenerate, obj.into_selector(), span),
                false,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }
    if eq_ci(
        t,
        "if a creature dealt damage this way would die this turn, exile it instead",
    ) || eq_ci(
        t,
        "if any creature dealt damage this way would die this turn, exile it instead",
    ) || eq_ci(
        t,
        "if a permanent dealt damage this way would die this turn, exile it instead",
    ) || eq_ci(
        t,
        "if any permanent dealt damage this way would die this turn, exile it instead",
    ) || eq_ci(
        t,
        "if a creature or planeswalker dealt damage this way would die this turn, exile it instead",
    ) || eq_ci(
        t,
        "if any creature or planeswalker dealt damage this way would die this turn, exile it instead",
    ) {
        let mut dmg_indices = Vec::new();
        let mut idx = state.steps.len();
        while idx > 0 {
            idx -= 1;
            if matches!(state.steps[idx].op, EffectOp::Damage { .. }) {
                dmg_indices.push(idx);
            } else {
                break;
            }
        }
        if !dmg_indices.is_empty() {
            dmg_indices.reverse();
            for di in dmg_indices {
                let bind_name = state.steps[di]
                    .bind_as
                    .clone()
                    .unwrap_or_else(|| format!("b{di}"));
                state.steps[di].bind_as = Some(bind_name.clone());
                state.push_step(
                    make_step(
                        EffectOp::ExileInsteadOfDying { duration: None },
                        Selector::Binding { name: bind_name },
                        span,
                    ),
                    false,
                );
            }
            return true;
        }
    }
    if eq_ci(t, "when that creature dies this turn, exile it instead")
        || eq_ci(t, "if that creature would die this turn, exile it instead")
    {
        let subj = state
            .it_ref()
            .map(|r| ref_to_selector(&r))
            .unwrap_or(Selector::EventObject);
        state.push_step(
            make_step(
                EffectOp::ExileInsteadOfDying {
                    duration: Some(Duration::EndOfTurn),
                },
                subj,
                span,
            ),
            false,
        );
        return true;
    }
    if let Some(after_if) = strip_prefix_word_ci(t, "if")
        && let Some(subj_s) =
            strip_suffix_word_ci(after_if, "would die this turn, exile it instead").or_else(|| {
                strip_suffix_word_ci(after_if, "would die this turn, exile them instead")
            })
        && !starts_with_word_ci(subj_s, "a")
        && !starts_with_word_ci(subj_s, "an")
        && !starts_with_word_ci(subj_s, "any")
        && find_word_ci(subj_s, "dealt damage this way").is_none()
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let sel = obj.into_selector();
            let valid = match &sel {
                Selector::Target { index } => {
                    state.targets.get(*index as usize).is_some_and(|ts| {
                        ts.kind == TargetKind::Object
                            && (ts.filter.zones.is_empty()
                                || ts.filter.zones.contains(ZoneMask::BATTLEFIELD))
                    })
                }
                _ => true,
            };
            if valid {
                state.push_step(
                    make_step(EffectOp::ExileInsteadOfDying { duration: None }, sel, span),
                    true,
                );
                return true;
            }
        }
        state.rollback(mark, ctx);
    }

    // 4. PileSplit
    if starts_with_word_ci(t, "separate") && find_word_ci(t, "into two piles").is_some() {
        let opponent_chooses = find_word_ci(t, "you choose one of those piles").is_none();
        state.push_step(
            make_step(
                EffectOp::PileSplit {
                    spec: PileSplitSpec {
                        reveal: find_word_ci(t, "reveal").is_some(),
                        pile_maker: PileSide::You,
                        pile_chooser: if opponent_chooses {
                            PileSide::Opponent
                        } else {
                            PileSide::You
                        },
                        chosen_to: Zone::Hand,
                        other_to: if find_word_ci(t, "graveyard").is_some() {
                            DigRestTo::Graveyard
                        } else if find_word_ci(t, "exile").is_some() {
                            DigRestTo::Exile
                        } else {
                            DigRestTo::LibraryBottom
                        },
                        other_random_order: find_word_ci(t, "random order").is_some(),
                    },
                },
                you_sel(),
                span,
            ),
            true,
        );
        return true;
    }

    // 5. VillainousChoice: "<player> faces a villainous choice — <optA>, or <optB>"
    if let Some(vc_pos) = find_word_ci(t, " faces a villainous choice") {
        let p_str = t[..vc_pos].trim();
        let after = t[vc_pos + " faces a villainous choice".len()..]
            .trim_start_matches([' ', '—', '-', ':'])
            .trim();
        if let Some((opt_a_s, opt_b_s)) = after
            .split_once(", or ")
            .or_else(|| after.split_once(" or "))
        {
            let mark = state.mark(ctx);
            let subj = parse_player_selector(p_str, ctx, state).unwrap_or_else(you_sel);
            let p_a =
                state.parse_sub_effects(opt_a_s.trim(), span.start, AbilityContext::Triggered, ctx);
            let p_b =
                state.parse_sub_effects(opt_b_s.trim(), span.start, AbilityContext::Triggered, ctx);
            if !p_a.steps.is_empty() && !p_b.steps.is_empty() {
                state.push_step(
                    make_step(
                        EffectOp::VillainousChoice {
                            options: [p_a.steps, p_b.steps],
                            labels: [opt_a_s.trim().to_string(), opt_b_s.trim().to_string()],
                        },
                        subj,
                        span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    if (eq_ci(
        t,
        "if that spell would be put into a graveyard, exile it instead",
    ) || eq_ci(
        t,
        "if that spell would be put into a graveyard this turn, exile it instead",
    ) || eq_ci(
        t,
        "if that spell would be put into your graveyard, exile it instead",
    ) || eq_ci(
        t,
        "if that spell would be put into your graveyard this turn, exile it instead",
    ) || eq_ci(
        t,
        "if that spell would be put into its owner's graveyard, exile it instead",
    ) || eq_ci(
        t,
        "if that spell would be put into its owner's graveyard this turn, exile it instead",
    ) || eq_ci(
        t,
        "if it would be put into a graveyard this turn, exile it instead",
    ) || eq_ci(t, "if it would be put into a graveyard, exile it instead")
        || eq_ci(
            t,
            "if it would be put into your graveyard this turn, exile it instead",
        )
        || eq_ci(
            t,
            "if it would be put into your graveyard, exile it instead",
        ))
        && let Some(prev) = state.steps.last_mut()
    {
        match prev.op {
            EffectOp::GrantGraveyardCast {
                spec: Some(ref mut s),
                ..
            } => {
                s.exile_if_would_enter_graveyard = true;
                return true;
            }
            EffectOp::CastFree {
                spec: Some(ref mut s),
                ..
            } => {
                s.exile_if_put_into_graveyard = true;
                return true;
            }
            _ => {}
        }
    }
    if eq_ci(
        t,
        "exile it instead of putting it into a graveyard as it resolves",
    ) || eq_ci(
        t,
        "exile it instead of putting it into its owner's graveyard as it resolves",
    ) {
        state.push_step(
            make_step(
                EffectOp::Grant {
                    keywords: SmallVec::new(),
                    remove_keywords: SmallVec::new(),
                    cant_have_or_gain: false,
                    duration: Some(Duration::EndOfTurn),
                    granted_ability_texts: Vec::new(),
                    choose_keyword_options: SmallVec::new(),
                    choose_lose_keyword_options: SmallVec::new(),
                    choose_protection_color: false,
                    remove_all_abilities: false,
                    can_attack_no_defender: false,
                    must_attack_this_turn: false,
                    must_be_blocked_this_turn: false,
                    must_block_this_turn: false,
                    must_block_self_this_turn: false,
                    cant_block_self_this_turn: false,
                    cant_be_blocked_by_opponents_creatures: false,
                    assigns_no_combat_damage_this_turn: false,
                    grant_suspend_if_missing: false,
                    exile_resolving_spell_to_linked: true,
                    grant_trigger_spell_sunburst: false,
                    pay_any_mana_for_damage: None,
                    pay_up_to_life_gained_mana_to_draw: false,
                    gambit_combat_directive: false,
                },
                Selector::SelfObj,
                span,
            ),
            false,
        );
        return true;
    }

    // 6. GrantGraveyardCast
    if let Some((fb_subj_s, _dur)) = {
        let (body_no_dur, has_dur) = if let Some(r) = strip_suffix_word_ci(t, "until end of turn") {
            (r, true)
        } else {
            (t, false)
        };
        strip_suffix_word_ci(body_no_dur, "gains flashback")
            .or_else(|| strip_suffix_word_ci(body_no_dur, "gain flashback"))
            .filter(|s| contains_word_ci(s, "graveyard"))
            .map(|s| (s, has_dur))
    } && let Some(po) = parse_object_selector(fb_subj_s, ZoneMask::GRAVEYARD, ctx, state)
    {
        state.push_step(
            make_step(
                EffectOp::GrantGraveyardCast {
                    spec: Some(GraveyardCastGrantSpec {
                        until_end_of_next_turn: false,
                        flashback_equal_mana_cost: true,
                        alternative_mana_cost: None,
                        without_paying_mana_cost: false,
                        exile_if_would_enter_graveyard: true,
                    }),
                    grant_adventure_until_end_of_next_turn: false,
                },
                po.into_selector(),
                span,
            ),
            true,
        );
        return true;
    }
    let (gy_body, gy_next_turn_pref, gy_once_turn) =
        if let Some(r) = strip_prefix_word_ci(t, "until end of turn,") {
            (r.trim(), false, false)
        } else if let Some(r) = strip_prefix_word_ci(t, "until the end of your next turn,")
            .or_else(|| strip_prefix_word_ci(t, "until end of your next turn,"))
        {
            (r.trim(), true, false)
        } else if let Some(r) = strip_prefix_word_ci(t, "once during each of your turns,") {
            (r.trim(), false, true)
        } else {
            (t, false, false)
        };
    let gy_low_opt = if (starts_with_word_ci(gy_body, "you may cast")
        || starts_with_word_ci(gy_body, "you may play"))
        && find_word_ci(gy_body, "graveyard").is_some()
    {
        Some(gy_body.to_ascii_lowercase())
    } else {
        None
    };
    if let Some(gy_low) = gy_low_opt.as_deref()
        && (gy_low.contains("from your graveyard")
            || (gy_low.contains("target ")
                && (gy_low.contains("from a graveyard")
                    || gy_low.contains("from an opponent's graveyard"))))
    {
        if gy_low.contains("its adventure from your graveyard")
            || gy_low.contains("from your graveyard as an adventure")
            || gy_low.contains("his adventure from your graveyard")
            || gy_low.contains("her adventure from your graveyard")
            || gy_low.contains("their adventure from your graveyard")
            || gy_low.contains("~'s adventure from your graveyard")
            || gy_low.contains("this card's adventure from your graveyard")
        {
            state.push_step(
                make_step(
                    EffectOp::GrantGraveyardCast {
                        spec: Some(GraveyardCastGrantSpec {
                            until_end_of_next_turn: true,
                            flashback_equal_mana_cost: false,
                            alternative_mana_cost: None,
                            without_paying_mana_cost: false,
                            exile_if_would_enter_graveyard: false,
                        }),
                        grant_adventure_until_end_of_next_turn: true,
                    },
                    Selector::SelfObj,
                    span,
                ),
                false,
            );
            return true;
        }
        let mut subj = you_sel();
        if let Some(after_cast) = strip_prefix_word_ci(gy_body, "you may cast")
            .or_else(|| strip_prefix_word_ci(gy_body, "you may play"))
        {
            let clean_after = if let Some(wp) = find_word_ci(after_cast, " without paying") {
                after_cast[..wp].trim()
            } else {
                after_cast.trim()
            };
            if starts_with_word_ci(clean_after, "target")
                && let Some(fpos) = find_word_ci(clean_after, " from ")
                    .or_else(|| find_word_ci(clean_after, " in "))
            {
                let after_kw = if find_word_ci(clean_after, " from ") == Some(fpos) {
                    clean_after[fpos + 6..].trim()
                } else {
                    clean_after[fpos + 4..].trim()
                };
                let normalized_sel = format!("{} in {}", clean_after[..fpos].trim(), after_kw);
                if let Some(po) =
                    parse_object_selector(&normalized_sel, ZoneMask::GRAVEYARD, ctx, state)
                {
                    subj = po.into_selector();
                }
            } else if let Some(gy_pos) = find_word_ci(clean_after, " from your graveyard") {
                let mid = clean_after[..gy_pos].trim();
                let mut after_gy = clean_after[gy_pos + " from your graveyard".len()..].trim();
                for dur_sfx in [
                    "this turn",
                    "until end of turn",
                    "until the end of your next turn",
                    "until end of your next turn",
                ] {
                    if let Some(p) = strip_suffix_word_ci(after_gy, dur_sfx) {
                        after_gy = p.trim();
                    }
                }
                let mid_no_art = strip_prefix_word_ci(mid, "a")
                    .or_else(|| strip_prefix_word_ci(mid, "an"))
                    .unwrap_or(mid);
                let combined_filter = if !after_gy.is_empty()
                    && (starts_with_word_ci(after_gy, "with")
                        || starts_with_word_ci(after_gy, "without"))
                {
                    std::borrow::Cow::Owned(format!("{mid_no_art} {after_gy}"))
                } else {
                    std::borrow::Cow::Borrowed(mid_no_art)
                };
                if matches!(
                    mid.to_ascii_lowercase().as_str(),
                    "it" | "that card" | "that creature" | "that spell" | "that permanent"
                ) && let Some(po) = parse_object_selector(mid, ZoneMask::GRAVEYARD, ctx, state)
                {
                    subj = po.into_selector();
                } else if !eq_ci(&combined_filter, "cards") && !eq_ci(&combined_filter, "spells") {
                    let ftoks = tokenize(&combined_filter, 0);
                    let cp = ctx.interner.checkpoint();
                    if let Some((mut f, used)) = parse_object_filter(
                        &ftoks,
                        ctx,
                        FilterOpts {
                            default_zone: ZoneMask::GRAVEYARD,
                            allow_spell_noun: true,
                            strip_trailing_card: true,
                            allow_plural_and_disjunction: true,
                            ..Default::default()
                        },
                        state,
                    ) && used == ftoks.len()
                        && (!f.types_any.is_empty()
                            || !f.types_all.is_empty()
                            || !f.subtypes_any.is_empty()
                            || !f.subtypes_all.is_empty())
                    {
                        f.zones = ZoneMask::GRAVEYARD;
                        f.owner = Some(RelativeControl::You);
                        subj = Selector::All {
                            filter: Box::new(f),
                        };
                    } else {
                        ctx.interner.rollback(cp);
                    }
                }
            }
        }
        let is_timed_gy_grant = gy_next_turn_pref
            || gy_once_turn
            || gy_low.contains("this turn")
            || gy_low.contains("next turn")
            || gy_low.contains("until ")
            || gy_low.contains("flashback");
        let use_cast_free = !is_timed_gy_grant
            && (matches!(subj, Selector::All { .. })
                || (matches!(subj, Selector::Target { .. }) && !gy_low.contains("without paying")));
        if use_cast_free {
            let (final_subj, spec_filter, up_to_count, is_opt) = match subj {
                Selector::Target { .. } => (subj, None, None, true),
                Selector::All { mut filter } => {
                    let has_extra = filter.mana_value.is_some()
                        || filter.power.is_some()
                        || filter.toughness.is_some()
                        || !filter.colors_any.is_empty()
                        || !filter.colors_all.is_empty()
                        || !filter.colors_none.is_empty()
                        || !filter.subtypes_any.is_empty()
                        || !filter.subtypes_all.is_empty()
                        || !filter.subtypes_none.is_empty()
                        || !filter.supertypes_any.is_empty()
                        || !filter.supertypes_none.is_empty()
                        || !filter.extra.is_empty();
                    let extra_filter = if has_extra {
                        let sf = ObjectFilter {
                            mana_value: filter.mana_value.take(),
                            power: filter.power.take(),
                            toughness: filter.toughness.take(),
                            colors_any: std::mem::take(&mut filter.colors_any),
                            colors_all: std::mem::take(&mut filter.colors_all),
                            colors_none: std::mem::take(&mut filter.colors_none),
                            subtypes_any: std::mem::take(&mut filter.subtypes_any),
                            subtypes_all: std::mem::take(&mut filter.subtypes_all),
                            subtypes_none: std::mem::take(&mut filter.subtypes_none),
                            supertypes_any: std::mem::take(&mut filter.supertypes_any),
                            supertypes_none: std::mem::take(&mut filter.supertypes_none),
                            extra: std::mem::take(&mut filter.extra),
                            ..Default::default()
                        };
                        Some(Box::new(sf))
                    } else {
                        None
                    };
                    (Selector::All { filter }, extra_filter, Some(1), false)
                }
                other => (other, None, Some(1), false),
            };
            let mut st = make_step(
                EffectOp::CastFree {
                    spec: Some(Box::new(CastFreeSpec {
                        copy_card_first: false,
                        without_paying_mana_cost: gy_low.contains("without paying"),
                        filter: spec_filter,
                        up_to_count,
                        exile_if_put_into_graveyard: gy_low.contains("exile it instead"),
                        alternative_mana_cost: None,
                        pay_life_equal_mana_value: false,
                        total_max_mv: None,
                        exiled_with_self: false,
                    })),
                    at_random: false,
                    cast_any_number_from_exiled: false,
                },
                final_subj,
                span,
            );
            if is_opt {
                st.optional = Some(OptionalSpec {
                    chooser: PlayerRef::You,
                    cost: Vec::new(),
                    mode: OptionalMode::DoIfPaid,
                });
            }
            state.push_step(st, false);
            return true;
        }
        let mut st = make_step(
            EffectOp::GrantGraveyardCast {
                spec: Some(GraveyardCastGrantSpec {
                    until_end_of_next_turn: gy_next_turn_pref || gy_low.contains("next turn"),
                    flashback_equal_mana_cost: gy_low.contains("flashback"),
                    alternative_mana_cost: None,
                    without_paying_mana_cost: gy_low.contains("without paying"),
                    exile_if_would_enter_graveyard: gy_low.contains("exile it instead"),
                }),
                grant_adventure_until_end_of_next_turn: false,
            },
            subj,
            span,
        );
        if gy_once_turn {
            st.do_this_once_per_turn = true;
        }
        state.push_step(st, false);
        return true;
    }

    // 7. CastNameLock & 8. GrantPlayer common spell/turn rules
    let first_gp = t.split_whitespace().next().unwrap_or("");
    if eq_ci(first_gp, "opponents")
        || eq_ci(first_gp, "your")
        || eq_ci(first_gp, "you")
        || eq_ci(first_gp, "until")
        || eq_ci(first_gp, "spells")
        || eq_ci(first_gp, "players")
        || eq_ci(first_gp, "damage")
        || eq_ci(first_gp, "the")
        || eq_ci(first_gp, "when")
        || eq_ci(first_gp, "if")
        || eq_ci(first_gp, "creature")
        || eq_ci(first_gp, "noncreature")
    {
        // 7. CastNameLock
        if starts_with_ci(t, "opponents can't cast spells with the chosen name")
            || starts_with_ci(t, "your opponents can't cast spells with the chosen name")
        {
            let (_, dur) = parse_duration_suffix(t);
            state.push_step(
                make_step(
                    EffectOp::CastNameLock {
                        name_ref: Ref::SelfObj,
                        duration: dur.or(Some(Duration::UntilYourNextTurn)),
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        // 8. GrantPlayer common spell/turn rules
        let gp_rule = if eq_ci(t, "you may play an additional land this turn") {
            Some((vec![PlayerRuleKind::ExtraLandPlay], None, Some(1u16)))
        } else if let Some(mid_land) = strip_prefix_ci(t, "you may play ")
            .and_then(|r| strip_suffix_ci(r, " additional lands this turn"))
            && let Some(n) = parse_small_number(
                strip_prefix_ci(mid_land, "up to ")
                    .unwrap_or(mid_land)
                    .trim(),
            )
        {
            Some((vec![PlayerRuleKind::ExtraLandPlay], None, Some(n as u16)))
        } else if eq_ci(t, "you have no maximum hand size for the rest of the game")
            || eq_ci(t, "you get no maximum hand size for the rest of the game")
        {
            Some((vec![PlayerRuleKind::NoMaxHandSizeRestOfGame], None, None))
        } else if eq_ci(
            t,
            "until end of turn, you may cast spells as though they had flash",
        ) || eq_ci(t, "you may cast spells as though they had flash this turn")
            || eq_ci(t, "you may cast spells this turn as though they had flash")
        {
            Some((
                vec![PlayerRuleKind::CastAsThoughFlashThisTurn],
                Some(Duration::EndOfTurn),
                None,
            ))
        } else if eq_ci(t, "your life total can't change this turn") {
            Some((
                vec![PlayerRuleKind::LifeTotalCantChange],
                Some(Duration::EndOfTurn),
                None,
            ))
        } else if eq_ci(
            t,
            "you gain protection from everything until your next turn",
        ) {
            Some((
                vec![PlayerRuleKind::ProtectionFromEverything],
                Some(Duration::UntilYourNextTurn),
                None,
            ))
        } else if eq_ci(
            t,
            "until your next turn, your life total can't change and you gain protection from everything",
        ) {
            Some((
                vec![
                    PlayerRuleKind::LifeTotalCantChange,
                    PlayerRuleKind::ProtectionFromEverything,
                ],
                Some(Duration::UntilYourNextTurn),
                None,
            ))
        } else if eq_ci(t, "spells you cast this turn can't be countered") {
            Some((
                vec![PlayerRuleKind::SpellsCantBeCounteredThisTurn],
                Some(Duration::EndOfTurn),
                None,
            ))
        } else if eq_ci(t, "your opponents can't cast spells this turn") {
            Some((
                vec![PlayerRuleKind::OpponentsCantCastThisTurn],
                Some(Duration::EndOfTurn),
                None,
            ))
        } else if eq_ci(t, "players can't cast spells this turn")
            || eq_ci(t, "each player can't cast spells this turn")
        {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: vec![PlayerRuleKind::AllPlayersCantCastSpellsThisTurn],
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    Selector::Player {
                        filter: PlayerFilter {
                            relation: PlayerRelation::EachPlayer,
                        },
                    },
                    span,
                ),
                false,
            );
            return true;
        } else if eq_ci(t, "damage can't be prevented this turn") {
            Some((
                vec![PlayerRuleKind::DamageCantBePrevented],
                Some(Duration::EndOfTurn),
                None,
            ))
        } else if eq_ci(
            t,
            "the next artifact spell you cast this turn gains sunburst",
        ) || eq_ci(
            t,
            "when you next cast an artifact spell this turn, that spell gains sunburst",
        ) || eq_ci(
            t,
            "when you cast your next artifact spell this turn, that spell gains sunburst",
        ) {
            Some((
                vec![PlayerRuleKind::NextArtifactSpellGainsSunburst],
                None,
                None,
            ))
        } else if eq_ci(
            t,
            "you can't lose the game this turn and your opponents can't win the game this turn",
        ) || eq_ci(t, "you can't lose the game this turn")
        {
            Some((
                vec![PlayerRuleKind::CannotLoseGame],
                Some(Duration::EndOfTurn),
                None,
            ))
        } else {
            None
        };
        if let Some((rules, duration, extra_land_plays)) = gp_rule {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules,
                        duration,
                        extra_land_plays,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if eq_ci(t, "your opponents can't cast noncreature spells this turn")
            || eq_ci(t, "players can't cast noncreature spells this turn")
        {
            let rel = if starts_with_ci(t, "players") {
                PlayerRelation::EachPlayer
            } else {
                PlayerRelation::EachOpponent
            };
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: vec![PlayerRuleKind::CantCastNoncreatureSpellsThisTurn],
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    Selector::Player {
                        filter: PlayerFilter { relation: rel },
                    },
                    span,
                ),
                false,
            );
            return true;
        }

        if eq_ci(
            t,
            "until end of turn, target player can't cast instant or sorcery spells, and that player can't activate abilities that aren't mana abilities",
        ) {
            let tidx = state.targets.len() as u16;
            state.targets.push(TargetSpec {
                kind: TargetKind::Player,
                player: Some(PlayerFilter {
                    relation: PlayerRelation::Any,
                }),
                min: 1,
                max: 1,
                ..default_target_spec()
            });
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: vec![
                            PlayerRuleKind::CantCastInstantsOrSorceriesThisTurn,
                            PlayerRuleKind::CantActivateNonManaAbilitiesThisTurn,
                        ],
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    Selector::Target { index: tidx },
                    span,
                ),
                false,
            );
            return true;
        }

        if eq_ci(
            t,
            "if a creature would enter the battlefield under an opponent's control this turn, it enters under your control instead",
        ) || eq_ci(
            t,
            "if a creature would enter under an opponent's control this turn, it enters under your control instead",
        ) {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: Vec::new(),
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: true,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if let Some((noncreature_only, after_prefix)) =
            strip_prefix_ci(t, "noncreature spells your opponents cast cost ")
                .map(|r| (true, r))
                .or_else(|| {
                    strip_prefix_ci(t, "spells your opponents cast cost ").map(|r| (false, r))
                })
            && let Some(mid) = strip_suffix_ci(after_prefix, " more to cast until your next turn")
            && let Some(inner) = mid
                .trim()
                .strip_prefix('{')
                .and_then(|r| r.strip_suffix('}'))
            && let Ok(n) = inner.parse::<u16>()
        {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: Vec::new(),
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: Some((noncreature_only, n)),
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if let Some(after_with) = strip_prefix_ci(
            t,
            "when you next cast a creature spell this turn, that creature enters with ",
        ) && let Some(cnt_s) = strip_suffix_ci(after_with, " additional +1/+1 counters on it")
            .or_else(|| strip_suffix_ci(after_with, " additional +1/+1 counter on it"))
            && let Some(n) = if eq_ci(cnt_s.trim(), "an") || eq_ci(cnt_s.trim(), "a") {
                Some(1)
            } else {
                parse_small_number(cnt_s.trim())
            }
        {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: Vec::new(),
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: Some(Box::new(Amount::Const {
                            n,
                        })),
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if let Some(after_less) = strip_prefix_ci(
            t,
            "until end of turn, damage that would reduce your life total to less than ",
        ) && let Some(num_s) = after_less.split_whitespace().next()
            && let Ok(floor_n) = num_s.parse::<i32>()
            && ends_with_ci(after_less.as_bytes(), b" instead")
        {
            state.push_step(
                make_step(
                    EffectOp::PreventDamage {
                        spec: Box::new(DamagePreventionSpec {
                            mode: PreventMode::All,
                            combat_only: false,
                            scope: PreventScope::Subject,
                            from_source: None,
                            also_prevent_dealt_by_subject: false,
                            choose_source: false,
                            next_damage_event_only: false,
                            on_prevented: None,
                            redirect_to: None,
                            redirect_source_color_filter: ColorMask::empty(),
                            redirect_source_kind: None,
                            min_life_floor: Some(floor_n),
                            all_damage_to_you_and_perms: false,
                            you_and_planeswalkers_you_control: false,
                            from_sources_you_dont_control: false,
                            from_source_colors: ColorMask::empty(),
                            from_source_not_subtypes: SmallVec::new(),
                            on_prevented_creature: None,
                            on_prevented_noncreature: None,
                            on_prevented_to_damage_source_controller: false,
                        }),
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if eq_ci(t, "creature spells you cast this turn can't be countered") {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: vec![PlayerRuleKind::CreatureSpellsCantBeCounteredThisTurn],
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if eq_ci(
            t,
            "until end of turn, if one or more tokens would be created under your control, twice that many of those tokens are created instead",
        ) || eq_ci(
            t,
            "if one or more tokens would be created under your control this turn, twice that many of those tokens are created instead",
        ) {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: Vec::new(),
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: true,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if let Some(after_pays) = strip_prefix_ci(
            t,
            "until your next turn, creatures can't attack you unless their controller pays ",
        ) && let Some(cost_part) = strip_suffix_ci(after_pays, " for each of those creatures")
            && let Some(inner) = cost_part
                .trim()
                .strip_prefix('{')
                .and_then(|r| r.strip_suffix('}'))
            && let Ok(n) = inner.parse::<u16>()
        {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: Vec::new(),
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: Some(n),
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    span,
                ),
                false,
            );
            return true;
        }

        if eq_ci(
            t,
            "until your next turn, creatures your opponents control attack each combat if able",
        ) || eq_ci(
            t,
            "until your next turn, creatures your opponents control attack each combat if able and attack a player other than you if able",
        ) {
            let other_player = contains_word_ci(t, "attack a player other than you if able");
            state.push_step(
                make_step(
                    EffectOp::CombatRestriction {
                        spec: None,
                        duration: None,
                        choose_odd_or_even_cant_block: false,
                        must_attack_next_combat: false,
                        must_attack_player: None,
                        until_your_next_turn_directive: Some((true, other_player)),
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }

        if let Some(cond_s) = strip_prefix_word_ci(t, "you may cast ~ as though it had flash if")
            .or_else(|| {
                strip_prefix_word_ci(t, "you may cast this spell as though it had flash if")
            })
            && let Some(cond) = parse_condition_str(cond_s, ctx, state)
        {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: Vec::new(),
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: Some(Box::new(cond)),
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }

        if let Some(after_cost) = strip_prefix_word_ci(t, "the next spell you cast this turn costs")
            && let Some(fe_pos) = find_word_ci(after_cost, " less to cast for each ")
        {
            let pip_s = after_cost[..fe_pos].trim();
            let fe_raw = after_cost[fe_pos + " less to cast for each ".len()..].trim();
            let unit = pip_s
                .strip_prefix('{')
                .and_then(|r| r.strip_suffix('}'))
                .and_then(|r| r.parse::<i32>().ok());
            let cnt_amt = if eq_ci(fe_raw, "counter removed this way") {
                Some(Amount::CountersRemovedThisWay)
            } else {
                parse_amount_str(&format!("for each {fe_raw}"), ctx, state)
            };
            if let (Some(u), Some(a)) = (unit, cnt_amt) {
                let final_amt = if u == 1 {
                    a
                } else {
                    Amount::Mul {
                        factor: u,
                        of: Box::new(a),
                    }
                };
                state.push_step(
                    make_step(
                        EffectOp::GrantPlayer {
                            rules: Vec::new(),
                            duration: None,
                            extra_land_plays: None,
                            next_spell_types: None,
                            spend_mana_as_any_color_top_of_library: false,
                            steal_opponent_entering_creatures_until_eot: false,
                            opponents_spells_cost_more_until_next_turn: None,
                            attack_tax_until_your_next_turn: None,
                            next_spell_cost_reduction_generic: Some(Box::new(final_amt)),
                            next_creature_enters_with_plus_counters: None,
                            next_main_phase_add_mana: None,
                            double_tokens_this_turn: false,
                            flash_cast_condition: None,
                            next_spell_cascade: None,
                            extra_loyalty_activations_this_turn: None,
                            planar_action: None,
                        },
                        Selector::None,
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
    }

    // Surge of Salvation: "You and permanents you control gain hexproof [until end of turn]"
    {
        let (body, dur) = parse_duration_suffix(t);
        if let Some(kw_raw) = strip_prefix_word_ci(body, "you and permanents you control gain")
            && let Some(kws) = parse_keyword_list_ids(kw_raw, ctx)
            && kws.len() == 1
            && eq_ci(kw_raw, "hexproof")
        {
            let eff_dur = dur.or(Some(Duration::EndOfTurn));
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: vec![PlayerRuleKind::Hexproof],
                        duration: eff_dur,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            state.push_step(
                make_step(
                    EffectOp::Grant {
                        keywords: kws,
                        remove_keywords: SmallVec::new(),
                        cant_have_or_gain: false,
                        duration: eff_dur,
                        granted_ability_texts: Vec::new(),
                        choose_keyword_options: SmallVec::new(),
                        choose_lose_keyword_options: SmallVec::new(),
                        choose_protection_color: false,
                        remove_all_abilities: false,
                        can_attack_no_defender: false,
                        must_attack_this_turn: false,
                        must_be_blocked_this_turn: false,
                        must_block_this_turn: false,
                        must_block_self_this_turn: false,
                        cant_block_self_this_turn: false,
                        cant_be_blocked_by_opponents_creatures: false,
                        assigns_no_combat_damage_this_turn: false,
                        grant_suspend_if_missing: false,
                        exile_resolving_spell_to_linked: false,
                        grant_trigger_spell_sunburst: false,
                        pay_any_mana_for_damage: None,
                        pay_up_to_life_gained_mana_to_draw: false,
                        gambit_combat_directive: false,
                    },
                    Selector::All {
                        filter: Box::new(ObjectFilter {
                            zones: ZoneMask::BATTLEFIELD,
                            controller: Some(RelativeControl::You),
                            ..Default::default()
                        }),
                    },
                    span,
                ),
                false,
            );
            return true;
        }
    }

    // Reverse Damage: "The next time a source of your choice would deal damage to you this turn, prevent that damage"
    if eq_ci(
        t,
        "the next time a source of your choice would deal damage to you this turn, prevent that damage",
    ) {
        state.push_step(
            make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::All,
                        combat_only: false,
                        scope: PreventScope::Subject,
                        from_source: None,
                        also_prevent_dealt_by_subject: false,
                        choose_source: true,
                        next_damage_event_only: true,
                        on_prevented: None,
                        redirect_to: None,
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: false,
                        from_sources_you_dont_control: false,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }

    if eq_ci(t, "you gain life equal to the damage prevented this way")
        && let Some(last) = state.steps.last_mut()
        && let EffectOp::PreventDamage { spec } = &mut last.op
        && spec.on_prevented.is_none()
    {
        spec.on_prevented = Some(mtg_ir::OnPreventedRider {
            kind: mtg_ir::OnPreventedKind::GainLifeEqual,
            counter: None,
            recipient: None,
        });
        return true;
    }

    // Gatta and Luzzu: "If damage would be dealt to <subj> this turn, prevent that damage and put that many +1/+1 counters on it"
    if let Some(after_if) = strip_prefix_word_ci(t, "if damage would be dealt to")
        && let Some((subj_raw, tail)) = split_at_top_level_comma(after_if)
            .and_then(|(l, r)| strip_suffix_word_ci(l.trim(), "this turn").map(|s| (s, r.trim())))
        && (eq_ci(
            tail,
            "prevent that damage and put that many +1/+1 counters on it",
        ) || eq_ci(
            tail,
            "prevent that damage and put that many +1/+1 counters on that creature",
        ))
        && let Some(obj) = parse_object_selector(subj_raw, ZoneMask::BATTLEFIELD, ctx, state)
    {
        state.push_step(
            make_step(
                EffectOp::PreventDamage {
                    spec: Box::new(DamagePreventionSpec {
                        mode: PreventMode::All,
                        combat_only: false,
                        scope: PreventScope::Subject,
                        from_source: None,
                        also_prevent_dealt_by_subject: false,
                        choose_source: false,
                        next_damage_event_only: false,
                        on_prevented: Some(mtg_ir::OnPreventedRider {
                            kind: mtg_ir::OnPreventedKind::PutCountersEqual,
                            counter: Some(ctx.interner.intern_counter("+1/+1")),
                            recipient: None,
                        }),
                        redirect_to: None,
                        redirect_source_color_filter: ColorMask::empty(),
                        redirect_source_kind: None,
                        min_life_floor: None,
                        all_damage_to_you_and_perms: false,
                        you_and_planeswalkers_you_control: false,
                        from_sources_you_dont_control: false,
                        from_source_colors: ColorMask::empty(),
                        from_source_not_subtypes: SmallVec::new(),
                        on_prevented_creature: None,
                        on_prevented_noncreature: None,
                        on_prevented_to_damage_source_controller: false,
                    }),
                },
                obj.into_selector(),
                span,
            ),
            false,
        );
        return true;
    }

    // Endless Detour: "The owner of <target> puts it on their choice of the top or bottom of their library"
    if let Some(after_own) = strip_prefix_word_ci(t, "the owner of")
        && let Some(pos) = find_word_ci(
            after_own,
            " puts it on their choice of the top or bottom of their library",
        )
    {
        let obj_s = after_own[..pos].trim();
        let tail = after_own
            [pos + " puts it on their choice of the top or bottom of their library".len()..]
            .trim();
        if tail.is_empty()
            && let Some(obj) = parse_object_selector(obj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            state.push_step(
                make_step(
                    EffectOp::Move {
                        from: None,
                        to: Some(Zone::Library),
                        select: SelectionMod::default(),
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: false,
                        position: Some(mtg_ir::LibraryPosition::TopOrBottom),
                        from_top: None,
                        library_choice_by: Some(mtg_ir::LibraryChoiceBy::Owner),
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: None,
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: false,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    obj.into_selector(),
                    span,
                ),
                false,
            );
            return true;
        }
    }

    // Chaos Warp: "The owner of <target> shuffles it into their library" / "reveals the top card of their library" / "If it's a permanent card, they put it onto the battlefield"
    if let Some(after_own) = strip_prefix_word_ci(t, "the owner of")
        && let Some(pos) = find_word_ci(after_own, " shuffles it into their library")
    {
        let obj_s = after_own[..pos].trim();
        let tail = after_own[pos + " shuffles it into their library".len()..].trim();
        if tail.is_empty()
            && let Some(obj) = parse_object_selector(obj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let owner_ref = match &obj {
                ParsedObj::Target(index) => Ref::Target { index: *index },
                ParsedObj::Binding(name) => Ref::Binding { name: name.clone() },
                ParsedObj::SelfObj => Ref::SelfObj,
                ParsedObj::EventObject => Ref::EventObject,
                _ => Ref::Target { index: 0 },
            };
            let mut st = make_step(
                EffectOp::Move {
                    from: None,
                    to: Some(Zone::Library),
                    select: SelectionMod::default(),
                    tapped: false,
                    under_your_control: false,
                    topmost_only: false,
                    may_shuffle: true,
                    position: None,
                    from_top: None,
                    library_choice_by: None,
                    random_order: false,
                    entered_transformed: false,
                    entered_flipped: false,
                    enters_tapped_and_attacking: false,
                    as_enchantment_only: false,
                    unearth: false,
                    with_counters: None,
                    attached_to: None,
                    condition: None,
                    choose_at_random_from_exiled_with_self: false,
                    leave_chosen_in_graveyard_rest_to_hand: false,
                    split_exiled_cost_cards_to_bottom_and_battlefield: false,
                },
                obj.into_selector(),
                span,
            );
            st.actor = Some(PlayerRef::OwnerOf {
                of: Box::new(owner_ref),
            });
            state.push_step(st, false);
            return true;
        }
    }
    if eq_ci(t, "reveals the top card of their library")
        && let Some(prev) = state.steps.last()
        && let Some(owner_pr) = prev.actor.clone()
        && matches!(owner_pr, PlayerRef::OwnerOf { .. })
    {
        let mut st = make_step(
            EffectOp::Reveal {
                select: SelectionMod::default(),
                look_only: false,
                special_tag: None,
            },
            Selector::LibraryTop {
                player: Some(owner_pr),
            },
            span,
        );
        st.bind_as = Some(state.alloc_bind_name("b"));
        state.push_step(st, true);
        return true;
    }
    if eq_ci(
        t,
        "if it's a permanent card, they put it onto the battlefield",
    ) && let Some(prev) = state.steps.last()
        && matches!(prev.op, EffectOp::Reveal { .. })
        && let Selector::LibraryTop {
            player: Some(ref owner_pr),
        } = prev.subject
        && let Some(ref bname) = prev.bind_as
    {
        let mut st = make_step(
            EffectOp::Move {
                from: None,
                to: Some(Zone::Battlefield),
                select: SelectionMod::default(),
                tapped: false,
                under_your_control: false,
                topmost_only: false,
                may_shuffle: false,
                position: None,
                from_top: None,
                library_choice_by: None,
                random_order: false,
                entered_transformed: false,
                entered_flipped: false,
                enters_tapped_and_attacking: false,
                as_enchantment_only: false,
                unearth: false,
                with_counters: None,
                attached_to: None,
                condition: None,
                choose_at_random_from_exiled_with_self: false,
                leave_chosen_in_graveyard_rest_to_hand: false,
                split_exiled_cost_cards_to_bottom_and_battlefield: false,
            },
            Selector::Binding {
                name: bname.clone(),
            },
            span,
        );
        st.actor = Some(owner_pr.clone());
        st.gate = Some(StepGate::Condition {
            condition: Box::new(Condition::MatchesFilter {
                target: Some(Ref::Binding {
                    name: bname.clone(),
                }),
                filter: Box::new(ObjectFilter {
                    types_none: CardTypeMask::INSTANT | CardTypeMask::SORCERY,
                    ..Default::default()
                }),
                any: false,
            }),
        });
        state.push_step(st, false);
        return true;
    }

    // Terastodon: "For each permanent put into a graveyard this way, its controller creates <token>"
    if let Some(after_gy) = strip_prefix_word_ci(
        t,
        "for each permanent put into a graveyard this way, its controller creates",
    ) && state
        .steps
        .last()
        .is_some_and(|s| matches!(s.op, EffectOp::Destroy { .. } | EffectOp::Sacrifice { .. }))
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        let synth = format!("create {after_gy}");
        if parse_token_creation_clause(&synth, span, ctx, state) && state.steps.len() > before {
            let mut inner_steps = state.steps.split_off(before);
            for st in &mut inner_steps {
                st.subject = Selector::None;
                st.actor = Some(PlayerRef::EachLoopPlayer);
                st.amount = Some(Box::new(Amount::CountedThisWay {
                    kind: CountedThisWayKind::DestroyedControlledByPlayerThisWay,
                }));
            }
            state.push_step(
                make_step(
                    EffectOp::ForEachPlayerLoop {
                        players: LoopPlayersKind::EachPlayer,
                        steps: inner_steps,
                        choose_random_opponent: false,
                        exclude_attacked_last_combat: false,
                        exclude_event_player: false,
                        choose_object_to_bind: None,
                    },
                    Selector::None,
                    span,
                ),
                false,
            );
            return true;
        }
        state.rollback(mark, ctx);
    }

    // Tempting offer follow-ups: "For each opponent who (does|searches a library this way), <clauses>"
    if let Some(body) = strip_prefix_word_ci(t, "for each opponent who does,")
        .or_else(|| strip_prefix_word_ci(t, "for each opponent who searches a library this way,"))
        && state.steps.last().is_some_and(|s| {
            matches!(
                s.op,
                EffectOp::ForEachPlayerLoop {
                    players: LoopPlayersKind::EachOpponent,
                    ..
                }
            )
        })
    {
        let before = state.steps.len();
        let mark = state.mark(ctx);
        if parse_clauses_into(body.trim(), span.start, ctx, state) && state.steps.len() > before {
            for st in &mut state.steps[before..] {
                match &mut st.op {
                    EffectOp::Search { spec, .. } => {
                        spec.count = 99;
                        st.bind_as = None;
                        st.amount = Some(Box::new(Amount::CountedThisWay {
                            kind: CountedThisWayKind::OpponentsDidThisWay,
                        }));
                    }
                    EffectOp::CreateToken {
                        multiply_by_opponents_did_this_way,
                        ..
                    } => {
                        let is_x = matches!(st.amount.as_deref(), Some(Amount::X));
                        if is_x {
                            *multiply_by_opponents_did_this_way = true;
                            st.amount = Some(Box::new(Amount::Mul {
                                factor: 1,
                                of: Box::new(Amount::X),
                            }));
                        } else {
                            st.amount = Some(Box::new(Amount::CountedThisWay {
                                kind: CountedThisWayKind::OpponentsDidThisWay,
                            }));
                        }
                        st.bind_as = None;
                    }
                    EffectOp::Draw { .. } => {
                        st.amount = Some(Box::new(Amount::CountedThisWay {
                            kind: CountedThisWayKind::OpponentsDidThisWay,
                        }));
                    }
                    _ => {}
                }
            }
            return true;
        }
        state.rollback(mark, ctx);
    }

    if (eq_ci(
        t,
        "then each player who searched a library this way shuffles",
    ) || eq_ci(t, "each player who searched a library this way shuffles"))
        && state
            .steps
            .iter()
            .any(|s| matches!(s.op, EffectOp::Search { .. }))
    {
        return true;
    }

    if eq_ci(t, "round up each time")
        && state.steps.last().is_some_and(|s| {
            matches!(
                &s.op,
                EffectOp::CopyPermanent {
                    copy_mod: Some(cm),
                    ..
                } if cm.halve_pt == Some(mtg_ir::RoundMode::Up)
            )
        })
    {
        return true;
    }

    // Tyrant of Discord: "target opponent chooses a permanent they control at random and sacrifices it"
    if eq_ci(
        t,
        "target opponent chooses a permanent they control at random and sacrifices it",
    ) {
        let tidx = state.add_target(TargetSpec {
            kind: TargetKind::Player,
            filter: ObjectFilter::default(),
            player: Some(PlayerFilter {
                relation: PlayerRelation::Opponent,
            }),
            min: 1,
            max: 1,
            ..default_target_spec()
        });
        let mut st = make_step(
            EffectOp::Sacrifice {
                select: SelectionMod {
                    at_random: true,
                    ..Default::default()
                },
            },
            Selector::All {
                filter: Box::new(ObjectFilter {
                    zones: ZoneMask::BATTLEFIELD,
                    extra: vec![ObjectPredicate::ControllerRef {
                        player: PlayerRef::Target { index: tidx },
                    }],
                    ..Default::default()
                }),
            },
            span,
        );
        st.actor = Some(PlayerRef::Target { index: tidx });
        state.push_step(st, false);
        return true;
    }

    // Eumidian Wastewaker: "<p1> and <p2> each discard a card or sacrifice a permanent"
    if let Some(left_players) =
        strip_suffix_word_ci(t, "each discard a card or sacrifice a permanent")
        && let Some(and_pos) = find_word_ci(left_players, "and")
        && let (p1_s, p2_s) = (&left_players[..and_pos], &left_players[and_pos + 3..])
        && let Some(p1_sel) = parse_player_selector(p1_s.trim(), ctx, state)
        && let Some(p2_sel) = parse_player_selector(p2_s.trim(), ctx, state)
    {
        let to_ref = |sel: Selector| -> Option<PlayerRef> {
            match sel {
                Selector::PlayerRef { player } => Some(player),
                Selector::Target { index } => Some(PlayerRef::Target { index }),
                Selector::Player { filter } => match filter.relation {
                    PlayerRelation::You => Some(PlayerRef::You),
                    _ => None,
                },
                _ => None,
            }
        };
        if let (Some(who1), Some(who2)) = (to_ref(p1_sel), to_ref(p2_sel)) {
            for who in [who1, who2] {
                let mut sac_st = make_step(
                    EffectOp::Sacrifice {
                        select: SelectionMod::default(),
                    },
                    Selector::All {
                        filter: Box::new(ObjectFilter {
                            zones: ZoneMask::BATTLEFIELD,
                            extra: vec![ObjectPredicate::ControllerRef {
                                player: who.clone(),
                            }],
                            ..Default::default()
                        }),
                    },
                    span,
                );
                sac_st.actor = Some(who.clone());
                sac_st.amount = Some(Box::new(Amount::Const { n: 1 }));
                state.push_step(
                    make_step(
                        EffectOp::PunisherChoice {
                            spec: PunisherSpec {
                                players: None,
                                default_steps: vec![sac_st],
                                unless_cost: vec![mtg_ir::CostDef::Discard {
                                    count: Box::new(Amount::Const { n: 1 }),
                                    target: None,
                                    random: false,
                                    same_name_pair: false,
                                    same_name_as_controlled: None,
                                    different_names: false,
                                }],
                                unless_effect: Vec::new(),
                                unless_who: who.clone(),
                                repeat_count: None,
                                may_first: false,
                                mandatory_if_able: false,
                                track_not_done_kind: None,
                                track_done_kind: None,
                            },
                        },
                        Selector::PlayerRef { player: who },
                        span,
                    ),
                    false,
                );
            }
            return true;
        }
    }

    parse_batch3_effect_ops(t, span, ctx, state)
}

fn make_empty_grant(duration: Duration) -> EffectOp {
    EffectOp::Grant {
        keywords: SmallVec::new(),
        remove_keywords: SmallVec::new(),
        cant_have_or_gain: false,
        duration: Some(duration),
        granted_ability_texts: Vec::new(),
        choose_keyword_options: SmallVec::new(),
        choose_lose_keyword_options: SmallVec::new(),
        choose_protection_color: false,
        remove_all_abilities: false,
        can_attack_no_defender: false,
        must_attack_this_turn: false,
        must_be_blocked_this_turn: false,
        must_block_this_turn: false,
        must_block_self_this_turn: false,
        cant_block_self_this_turn: false,
        cant_be_blocked_by_opponents_creatures: false,
        assigns_no_combat_damage_this_turn: false,
        grant_suspend_if_missing: false,
        exile_resolving_spell_to_linked: false,
        grant_trigger_spell_sunburst: false,
        pay_any_mana_for_damage: None,
        pay_up_to_life_gained_mana_to_draw: false,
        gambit_combat_directive: false,
    }
}

fn make_empty_animate(duration: Duration) -> EffectOp {
    EffectOp::Animate {
        duration: Some(duration),
        add_types: CardTypeMask::empty(),
        set_types: None,
        remove_types: CardTypeMask::empty(),
        add_subtypes: SmallVec::new(),
        set_subtypes: None,
        set_colors: None,
        add_colors: ColorMask::empty(),
        add_keywords: SmallVec::new(),
        set_power: None,
        set_toughness: None,
        keep_existing_types: false,
        still_a_land: false,
        remove_all_abilities: false,
        granted_ability_texts: Vec::new(),
        choose_creature_type: false,
        choose_basic_land_type: false,
        choose_color: None,
    }
}

fn make_simple_move(from: Option<Zone>, to: Zone) -> EffectOp {
    EffectOp::Move {
        from,
        to: Some(to),
        select: SelectionMod::default(),
        tapped: false,
        under_your_control: false,
        topmost_only: false,
        may_shuffle: false,
        position: None,
        from_top: None,
        library_choice_by: None,
        random_order: false,
        entered_transformed: false,
        entered_flipped: false,
        enters_tapped_and_attacking: false,
        as_enchantment_only: false,
        unearth: false,
        with_counters: None,
        attached_to: None,
        condition: None,
        choose_at_random_from_exiled_with_self: false,
        leave_chosen_in_graveyard_rest_to_hand: false,
        split_exiled_cost_cards_to_bottom_and_battlefield: false,
    }
}

fn parse_batch3_effect_ops(
    t: &str,
    span: Span,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    // 1. Combat-directive Grant effects
    if let Some(subj_s) = strip_suffix_word_ci(t, "blocks ~ this turn if able")
        .or_else(|| strip_suffix_word_ci(t, "block ~ this turn if able"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let mut op = make_empty_grant(Duration::EndOfTurn);
            if let EffectOp::Grant {
                must_block_self_this_turn,
                ..
            } = &mut op
            {
                *must_block_self_this_turn = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) = strip_suffix_word_ci(t, "can't block ~ this turn") {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let mut op = make_empty_grant(Duration::EndOfTurn);
            if let EffectOp::Grant {
                cant_block_self_this_turn,
                ..
            } = &mut op
            {
                *cant_block_self_this_turn = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) =
        strip_suffix_word_ci(t, "can attack this turn as though it didn't have defender").or_else(
            || {
                strip_suffix_word_ci(
                    t,
                    "can attack this turn as though they didn't have defender",
                )
            },
        )
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let mut op = make_empty_grant(Duration::EndOfTurn);
            if let EffectOp::Grant {
                can_attack_no_defender,
                ..
            } = &mut op
            {
                *can_attack_no_defender = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) = strip_suffix_word_ci(t, "must be blocked this turn if able") {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let mut op = make_empty_grant(Duration::EndOfTurn);
            if let EffectOp::Grant {
                must_be_blocked_this_turn,
                ..
            } = &mut op
            {
                *must_be_blocked_this_turn = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) = strip_suffix_word_ci(t, "attacks this turn if able")
        .or_else(|| strip_suffix_word_ci(t, "attack this turn if able"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let mut op = make_empty_grant(Duration::EndOfTurn);
            if let EffectOp::Grant {
                must_attack_this_turn,
                ..
            } = &mut op
            {
                *must_attack_this_turn = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) = strip_suffix_word_ci(t, "blocks this turn if able")
        .or_else(|| strip_suffix_word_ci(t, "block this turn if able"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let mut op = make_empty_grant(Duration::EndOfTurn);
            if let EffectOp::Grant {
                must_block_this_turn,
                ..
            } = &mut op
            {
                *must_block_this_turn = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if let Some(subj_s) = strip_suffix_word_ci(t, "assigns no combat damage this turn")
        .or_else(|| strip_suffix_word_ci(t, "assign no combat damage this turn"))
    {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let mut op = make_empty_grant(Duration::EndOfTurn);
            if let EffectOp::Grant {
                assigns_no_combat_damage_this_turn,
                ..
            } = &mut op
            {
                *assigns_no_combat_damage_this_turn = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), false);
            return true;
        }
        state.rollback(mark, ctx);
    }
    if eq_ci(t, "if it doesn't have suspend, it gains suspend") {
        let subj = state
            .it_ref()
            .map(|r| ref_to_selector(&r))
            .unwrap_or(Selector::EventObject);
        let mut op = make_empty_grant(Duration::Permanent);
        if let EffectOp::Grant {
            grant_suspend_if_missing,
            ..
        } = &mut op
        {
            *grant_suspend_if_missing = true;
        }
        state.push_step(make_step(op, subj, span), false);
        return true;
    }

    // 2. Simple Animate (basic land type / creature type of choice / basic land subtype / single color)
    let (dur_pre, body_anim) = parse_duration_prefix(t);
    let (body_anim, dur_suf) = parse_duration_suffix(body_anim);
    let anim_dur = dur_pre.or(dur_suf);
    if let Some(dur) = anim_dur
        && let Some(pos) =
            find_word_ci(body_anim, " becomes ").or_else(|| find_word_ci(body_anim, " become "))
    {
        let subj_s = body_anim[..pos].trim();
        let rest = if body_anim[pos..].starts_with(" becomes ") {
            body_anim[pos + " becomes ".len()..].trim()
        } else {
            body_anim[pos + " become ".len()..].trim()
        };
        let mark = state.mark(ctx);
        if eq_ci(rest, "the basic land type of your choice")
            && let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let mut op = make_empty_animate(dur);
            if let EffectOp::Animate {
                choose_basic_land_type,
                ..
            } = &mut op
            {
                *choose_basic_land_type = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        if eq_ci(rest, "the creature type of your choice")
            && let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let mut op = make_empty_animate(dur);
            if let EffectOp::Animate {
                choose_creature_type,
                ..
            } = &mut op
            {
                *choose_creature_type = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        if eq_ci(rest, "the color of your choice")
            && let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let mut op = make_empty_animate(dur);
            if let EffectOp::Animate {
                keep_existing_types,
                choose_color,
                ..
            } = &mut op
            {
                *keep_existing_types = true;
                *choose_color = Some(mtg_ir::AnimateColorChoice::Single);
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        let no_art = strip_prefix_word_ci(rest, "an")
            .or_else(|| strip_prefix_word_ci(rest, "a"))
            .unwrap_or(rest)
            .trim();
        let basic_land_canon = if eq_ci(no_art, "plains") {
            Some("Plains")
        } else if eq_ci(no_art, "island") {
            Some("Island")
        } else if eq_ci(no_art, "swamp") {
            Some("Swamp")
        } else if eq_ci(no_art, "mountain") {
            Some("Mountain")
        } else if eq_ci(no_art, "forest") {
            Some("Forest")
        } else {
            None
        };
        if let Some(land_sub) = basic_land_canon
            && let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let sid = ctx.interner.intern_subtype(land_sub);
            let mut op = make_empty_animate(dur);
            if let EffectOp::Animate {
                set_subtypes,
                keep_existing_types,
                ..
            } = &mut op
            {
                *set_subtypes = Some(smallvec![sid]);
                *keep_existing_types = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        if let Some(col) = parse_color_word(rest)
            && let Some(obj) = parse_object_selector(subj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let mut op = make_empty_animate(dur);
            if let EffectOp::Animate {
                set_colors,
                keep_existing_types,
                ..
            } = &mut op
            {
                *set_colors = Some(col);
                *keep_existing_types = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), true);
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 3. Return the exiled card(s) to owner's hand / battlefield
    if eq_ci(t, "return the exiled card to its owner's hand")
        || eq_ci(t, "return the exiled cards to their owners' hands")
        || eq_ci(t, "return all cards exiled with ~ to their owners' hands")
    {
        let subj = Selector::All {
            filter: Box::new(ObjectFilter {
                zones: ZoneMask::EXILE,
                extra: vec![ObjectPredicate::ExiledWithSelf],
                ..Default::default()
            }),
        };
        state.push_step(
            make_step(make_simple_move(Some(Zone::Exile), Zone::Hand), subj, span),
            false,
        );
        return true;
    }
    if eq_ci(
        t,
        "return the exiled card to the battlefield under its owner's control",
    ) || eq_ci(
        t,
        "return the exiled cards to the battlefield under their owners' control",
    ) || eq_ci(
        t,
        "return the exiled card to the battlefield tapped under its owner's control",
    ) || eq_ci(
        t,
        "return the exiled cards to the battlefield tapped under their owners' control",
    ) {
        let tapped = find_word_ci(t, "tapped").is_some();
        let subj = Selector::All {
            filter: Box::new(ObjectFilter {
                zones: ZoneMask::EXILE,
                extra: vec![ObjectPredicate::ExiledWithSelf],
                ..Default::default()
            }),
        };
        let mut op = make_simple_move(Some(Zone::Exile), Zone::Battlefield);
        if let EffectOp::Move {
            tapped: ref mut op_tapped,
            ..
        } = op
        {
            *op_tapped = tapped;
        }
        state.push_step(make_step(op, subj, span), false);
        return true;
    }

    // 4. "<obj>'s owner puts it on their choice of the top or bottom of their library"
    if let Some(pos) = find_word_ci(
        t,
        "'s owner puts it on their choice of the top or bottom of their library",
    ) {
        let obj_s = t[..pos].trim();
        let tail = t[pos
            + "'s owner puts it on their choice of the top or bottom of their library".len()..]
            .trim();
        let mark = state.mark(ctx);
        if tail.is_empty()
            && let Some(obj) = parse_object_selector(obj_s, ZoneMask::BATTLEFIELD, ctx, state)
        {
            let mut op = make_simple_move(Some(Zone::Battlefield), Zone::Library);
            if let EffectOp::Move {
                position,
                library_choice_by,
                ..
            } = &mut op
            {
                *position = Some(mtg_ir::LibraryPosition::TopOrBottom);
                *library_choice_by = Some(mtg_ir::LibraryChoiceBy::Owner);
            }
            state.push_step(make_step(op, obj.into_selector(), span), false);
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 5. "<player> shuffles their graveyard into their library" & "<player> shuffles <cards> from their graveyard into their library"
    if let Some(who_s) = strip_suffix_word_ci(t, "shuffles their graveyard into their library")
        .or_else(|| strip_suffix_word_ci(t, "shuffle their graveyard into their library"))
    {
        let mark = state.mark(ctx);
        if let Some(p_sel) = parse_player_selector(who_s.trim(), ctx, state) {
            let p_ref = match p_sel {
                Selector::PlayerRef { player } => Some(player),
                Selector::Target { index } => Some(PlayerRef::Target { index }),
                Selector::Player { filter } if filter.relation == PlayerRelation::You => {
                    Some(PlayerRef::You)
                }
                _ => None,
            };
            if let Some(player) = p_ref {
                let mut op = make_simple_move(None, Zone::Library);
                if let EffectOp::Move { may_shuffle, .. } = &mut op {
                    *may_shuffle = true;
                }
                let subj = Selector::All {
                    filter: Box::new(ObjectFilter {
                        zones: ZoneMask::GRAVEYARD,
                        extra: vec![ObjectPredicate::ControllerRef { player }],
                        ..Default::default()
                    }),
                };
                state.push_step(make_step(op, subj, span), false);
                return true;
            }
        }
        state.rollback(mark, ctx);
    }
    if let Some(shuf_pos) = find_word_ci(t, " shuffles ")
        && let Some(mid) = strip_suffix_word_ci(
            t[shuf_pos + " shuffles ".len()..].trim(),
            "from their graveyard into their library",
        )
    {
        let who_s = t[..shuf_pos].trim();
        let mark = state.mark(ctx);
        if parse_player_selector(who_s, ctx, state).is_some()
            && let Some(obj) = parse_object_selector(mid.trim(), ZoneMask::GRAVEYARD, ctx, state)
        {
            let mut op = make_simple_move(Some(Zone::Graveyard), Zone::Library);
            if let EffectOp::Move { may_shuffle, .. } = &mut op {
                *may_shuffle = true;
            }
            state.push_step(make_step(op, obj.into_selector(), span), false);
            return true;
        }
        state.rollback(mark, ctx);
    }

    // 6. "<obj> deals damage to itself equal to its power"
    if let Some(subj_s) = strip_suffix_word_ci(t, "deals damage to itself equal to its power") {
        let mark = state.mark(ctx);
        if let Some(obj) = parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state) {
            let sel = obj.into_selector();
            let obj_ref = match &sel {
                Selector::Target { index } => Some(Ref::Target { index: *index }),
                Selector::Binding { name } => Some(Ref::Binding { name: name.clone() }),
                Selector::SelfObj => Some(Ref::SelfObj),
                Selector::EventObject => Some(Ref::EventObject),
                _ => None,
            };
            if let Some(r) = obj_ref {
                let mut st = make_step(
                    EffectOp::Damage {
                        source: Some(Box::new(sel.clone())),
                        also_players: None,
                        divided: false,
                        excess_to_controller: false,
                        excess_to_controller_if_trample: false,
                        or_planeswalker_controlled_by: None,
                        damage_attacked_target_by_self: false,
                        soulfire_exile_damage_per_target: false,
                        each_creature_deals: None,
                    },
                    sel,
                    span,
                );
                st.amount = Some(Box::new(Amount::Stat {
                    of: r,
                    stat: StatKind::Power,
                    lki: false,
                }));
                state.push_step(st, false);
                return true;
            }
        }
        state.rollback(mark, ctx);
    }

    // 7. "Discard all the cards in your hand, then draw that many cards"
    if eq_ci(
        t,
        "discard all the cards in your hand, then draw that many cards",
    ) || eq_ci(t, "discard your hand, then draw that many cards")
    {
        state.push_step(
            make_step(
                EffectOp::DiscardHand {
                    draw_that_many: true,
                    draw_after: None,
                },
                you_sel(),
                span,
            ),
            false,
        );
        return true;
    }

    // 8. "Prevent all [combat ]damage that would be dealt to and dealt by <obj> this turn" (Maze of Ith)
    if let Some(after_prev) = strip_prefix_word_ci(t, "prevent all") {
        let (combat_only, rest) = if let Some(r) = strip_prefix_word_ci(
            after_prev,
            "combat damage that would be dealt to and dealt by",
        ) {
            (true, Some(r))
        } else if let Some(r) =
            strip_prefix_word_ci(after_prev, "damage that would be dealt to and dealt by")
        {
            (false, Some(r))
        } else {
            (false, None)
        };
        if let Some(r) = rest
            && let Some(subj_s) = strip_suffix_word_ci(r.trim(), "this turn")
        {
            let mark = state.mark(ctx);
            if let Some(obj) =
                parse_object_selector(subj_s.trim(), ZoneMask::BATTLEFIELD, ctx, state)
            {
                state.push_step(
                    make_step(
                        EffectOp::PreventDamage {
                            spec: Box::new(DamagePreventionSpec {
                                mode: PreventMode::All,
                                combat_only,
                                scope: PreventScope::Subject,
                                from_source: None,
                                also_prevent_dealt_by_subject: true,
                                choose_source: false,
                                next_damage_event_only: false,
                                on_prevented: None,
                                redirect_to: None,
                                redirect_source_color_filter: ColorMask::empty(),
                                redirect_source_kind: None,
                                min_life_floor: None,
                                all_damage_to_you_and_perms: false,
                                you_and_planeswalkers_you_control: false,
                                from_sources_you_dont_control: false,
                                from_source_colors: ColorMask::empty(),
                                from_source_not_subtypes: SmallVec::new(),
                                on_prevented_creature: None,
                                on_prevented_noncreature: None,
                                on_prevented_to_damage_source_controller: false,
                            }),
                        },
                        obj.into_selector(),
                        span,
                    ),
                    false,
                );
                return true;
            }
            state.rollback(mark, ctx);
        }
    }

    // 9. "collect evidence N" / "you collect evidence N"
    if let Some(rest) = strip_prefix_word_ci(t, "collect evidence")
        .or_else(|| strip_prefix_word_ci(t, "you collect evidence"))
        && let Some(amt) = parse_amount_str(rest.trim(), ctx, state)
    {
        let mut st = make_step(EffectOp::CollectEvidence, you_sel(), span);
        st.amount = Some(Box::new(amt));
        state.push_step(st, false);
        return true;
    }

    // 10. "copy it for each time you've cast your commander from the command zone this game"
    if eq_ci(
        t,
        "copy it for each time you've cast your commander from the command zone this game",
    ) || eq_ci(
        t,
        "copy that spell for each time you've cast your commander from the command zone this game",
    ) {
        state.push_step(
            make_step(
                EffectOp::CopySpell {
                    count: Some(Box::new(Amount::CommanderCastCount)),
                    may_choose_new_targets: false,
                    non_legendary: false,
                    except_colors: ColorMask::empty(),
                    copy_event_ability: false,
                    copy_per_sacrificed_cost: false,
                    copy_all_controlled_spells_and_other_abilities: false,
                },
                Selector::EventObject,
                span,
            ),
            false,
        );
        return true;
    }

    // 11. Standalone "look at <player>'s hand" / "<player> reveals their hand"
    if let Some(after_look) = strip_prefix_word_ci(t, "look at")
        && let Some(who_s) = strip_suffix_word_ci(after_look.trim(), "'s hand")
    {
        let mark = state.mark(ctx);
        if let Some(p_sel) = parse_player_selector(who_s.trim(), ctx, state) {
            let p_ref = match p_sel {
                Selector::PlayerRef { player } => Some(player),
                Selector::Target { index } => Some(PlayerRef::Target { index }),
                Selector::Player { filter } if filter.relation == PlayerRelation::You => {
                    Some(PlayerRef::You)
                }
                _ => None,
            };
            if let Some(player) = p_ref {
                let subj = Selector::All {
                    filter: Box::new(ObjectFilter {
                        zones: ZoneMask::HAND,
                        extra: vec![ObjectPredicate::ControllerRef { player }],
                        ..Default::default()
                    }),
                };
                state.push_step(
                    make_step(
                        EffectOp::Reveal {
                            select: SelectionMod::default(),
                            look_only: true,
                            special_tag: None,
                        },
                        subj,
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
        state.rollback(mark, ctx);
    }
    if let Some(who_s) = strip_suffix_word_ci(t, "reveals their hand")
        .or_else(|| strip_suffix_word_ci(t, "reveal their hand"))
    {
        let mark = state.mark(ctx);
        if let Some(p_sel) = parse_player_selector(who_s.trim(), ctx, state) {
            let p_ref = match p_sel {
                Selector::PlayerRef { player } => Some(player),
                Selector::Target { index } => Some(PlayerRef::Target { index }),
                Selector::Player { filter } if filter.relation == PlayerRelation::You => {
                    Some(PlayerRef::You)
                }
                _ => None,
            };
            if let Some(player) = p_ref {
                let subj = Selector::All {
                    filter: Box::new(ObjectFilter {
                        zones: ZoneMask::HAND,
                        extra: vec![ObjectPredicate::ControllerRef { player }],
                        ..Default::default()
                    }),
                };
                state.push_step(
                    make_step(
                        EffectOp::Reveal {
                            select: SelectionMod::default(),
                            look_only: false,
                            special_tag: None,
                        },
                        subj,
                        span,
                    ),
                    false,
                );
                return true;
            }
        }
        state.rollback(mark, ctx);
    }

    false
}

fn normalize_punisher_cost_phrase(raw: &str) -> String {
    let mut s = raw.trim().to_string();
    for (from, to) in [
        ("pays ", "pay "),
        ("discards ", "discard "),
        ("sacrifices ", "sacrifice "),
        ("exiles ", "exile "),
        ("loses ", "lose "),
        ("taps ", "tap "),
        ("returns ", "return "),
        ("puts ", "put "),
    ] {
        if s.as_bytes()
            .get(..from.len())
            .is_some_and(|b| b.eq_ignore_ascii_case(from.as_bytes()))
        {
            s.replace_range(..from.len(), to);
        }
        for sep in [" or ", ", or ", " and ", ", and "] {
            let pat = format!("{sep}{from}");
            let rep = format!("{sep}{to}");
            if let Some(pos) = find_word_ci(&s, pat.trim_start())
                && pos > 0
                && s[..pos].ends_with(sep)
            {
                let start = pos - sep.len();
                if start + pat.len() <= s.len() {
                    s.replace_range(start..start + pat.len(), &rep);
                }
            } else if let Some(idx) = s.to_ascii_lowercase().find(&pat) {
                s.replace_range(idx..idx + pat.len(), &rep);
            }
        }
    }
    s
}

fn parse_clauses_into(
    text: &str,
    base_offset: u32,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    parse_clauses_into_depth(text, base_offset, 0, ctx, state)
}

fn parse_clauses_into_depth(
    text: &str,
    base_offset: u32,
    depth: usize,
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) -> bool {
    const MAX_CLAUSE_SPLIT_DEPTH: usize = 6;
    const MAX_AND_SPLIT_ATTEMPTS: usize = 12;
    if depth >= MAX_CLAUSE_SPLIT_DEPTH || state.clause_split_budget == 0 {
        return false;
    }
    state.clause_split_budget -= 1;
    if let Some(pos) = find_word_ci(text, ", and ") {
        let left = text[..pos].trim();
        let right = text[pos + ", and ".len()..].trim();
        if !left.is_empty() && !right.is_empty() {
            let mark = state.mark(ctx);
            let r_off = base_offset + (pos + ", and ".len()) as u32;
            let l_span = Span {
                start: base_offset,
                end: base_offset + pos as u32,
            };
            let r_span = Span {
                start: r_off,
                end: base_offset + text.len() as u32,
            };
            if parse_core_imperative(left, l_span, ctx, state)
                && (parse_core_imperative(right, r_span, ctx, state)
                    || parse_clauses_into_depth(right, r_off, depth + 1, ctx, state))
            {
                return true;
            }
            state.rollback(mark, ctx);
        }
    }
    if strip_prefix_word_ci(text, "you may reveal ").is_some()
        && find_word_ci(text, " and put ").is_some()
    {
        let full_span = Span {
            start: base_offset,
            end: base_offset + text.len() as u32,
        };
        let mark = state.mark(ctx);
        if parse_core_imperative(text, full_span, ctx, state) {
            return true;
        }
        state.rollback(mark, ctx);
    }
    let clauses = split_clauses_quote_aware(text, base_offset);
    if clauses.is_empty() {
        return false;
    }
    for (clause, cspan) in clauses {
        if try_complete_pending_dig(clause, ctx, state) {
            continue;
        }
        let cmark = state.mark(ctx);
        if parse_core_imperative(clause, cspan, ctx, state) {
            continue;
        }
        state.rollback(cmark, ctx);
        let mut split_ok = false;
        let c_bytes = clause.as_bytes();
        let mut search_from = 0usize;
        let mut attempts = 0usize;
        while attempts < MAX_AND_SPLIT_ATTEMPTS
            && let Some(pos) = find_ascii_ci_from(c_bytes, b" and ", search_from)
        {
            search_from = pos + 5;
            if clause[pos + 5..].starts_with('/') {
                continue;
            }
            let left = clause[..pos].trim();
            let right = clause[pos + 5..].trim();
            if left.is_empty() || right.is_empty() {
                continue;
            }
            attempts += 1;
            let smark = state.mark(ctx);
            let r_off = cspan.start + (pos + 5) as u32;
            let l_span = Span {
                start: cspan.start,
                end: cspan.start + pos as u32,
            };
            let r_span = Span {
                start: r_off,
                end: cspan.end,
            };
            if parse_core_imperative(left, l_span, ctx, state)
                && (parse_core_imperative(right, r_span, ctx, state)
                    || (starts_with_word_ci(right, "deals ")
                        && parse_core_imperative(&format!("~ {right}"), r_span, ctx, state))
                    || parse_clauses_into_depth(right, r_off, depth + 1, ctx, state))
            {
                split_ok = true;
                break;
            }
            state.rollback(smark, ctx);
        }
        if !split_ok {
            return false;
        }
    }
    true
}

fn parse_effects_inner(
    text: &str,
    offset: u32,
    context: AbilityContext,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    parse_effects_inner_with_cond(text, offset, context, trigger, None, ctx, quoted_compiler)
}

fn parse_effects_inner_with_cond(
    text: &str,
    offset: u32,
    context: AbilityContext,
    trigger: Option<&TriggerDef>,
    trigger_cond: Option<&Condition>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    let mut state = ParserState::new(context, trigger, quoted_compiler);
    state.trigger_had_counter = match trigger_cond {
        Some(Condition::HadCounterOnIt { counter }) => Some(*counter),
        _ => None,
    };
    state.trigger_has_exiled_with_self =
        matches!(trigger_cond, Some(Condition::HasCardsExiledWithSelf));
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return EffectParse::default();
    }

    let raw_sents = split_sentences(trimmed, offset);
    let sentences = split_quoted_sentence_endings(&raw_sents);
    parse_sentences_into(&sentences, ctx, &mut state);

    if !state.steps.is_empty() {
        prune_unused_bindings(&mut state.steps);
    }

    EffectParse {
        steps: state.steps,
        targets: state.targets,
        modal: state.modal,
        unparsed: state.unparsed,
    }
}

fn parse_sentences_into(
    sentences: &[NormalizedSentence],
    ctx: &mut ParseCtx<'_>,
    state: &mut ParserState<'_>,
) {
    let mut sent_idx = 0usize;
    while sent_idx < sentences.len() {
        let sent = &sentences[sent_idx];
        let s_text = sent.text.trim();
        if s_text.is_empty() {
            sent_idx += 1;
            continue;
        }
        {
            let s0_clean = trim_trailing_period(s_text);
            if eq_ci(
                s0_clean,
                "discard all the cards in your hand, then draw that many cards",
            ) || eq_ci(s0_clean, "discard your hand, then draw that many cards")
            {
                state.push_step(
                    make_step(
                        EffectOp::DiscardHand {
                            draw_that_many: true,
                            draw_after: None,
                        },
                        you_sel(),
                        sent.span,
                    ),
                    false,
                );
                sent_idx += 1;
                continue;
            }
        }
        if sent_idx + 1 < sentences.len() {
            let s0_clean = trim_trailing_period(s_text);
            if let Some(who_s) = strip_suffix_word_ci(s0_clean, "reveals their hand")
                .or_else(|| strip_suffix_word_ci(s0_clean, "reveal their hand"))
            {
                let s1_clean = trim_trailing_period(sentences[sent_idx + 1].text.trim());
                let dest_and_phrase = strip_suffix_word_ci(s1_clean, "from it and exile that card")
                    .or_else(|| strip_suffix_word_ci(s1_clean, "from it and exile it"))
                    .map(|p| (Zone::Exile, p))
                    .or_else(|| {
                        strip_suffix_word_ci(s1_clean, "from it and that player discards that card")
                            .or_else(|| {
                                strip_suffix_word_ci(s1_clean, "from it and discards that card")
                            })
                            .map(|p| (Zone::Graveyard, p))
                    });
                if let Some((destination, lead)) = dest_and_phrase
                    && let Some((optional_choice, card_phrase)) =
                        strip_prefix_word_ci(lead.trim(), "you may choose")
                            .map(|r| (true, r))
                            .or_else(|| {
                                strip_prefix_word_ci(lead.trim(), "you choose").map(|r| (false, r))
                            })
                {
                    let cp_mark = state.mark(ctx);
                    if let Some(subj) = parse_player_selector(who_s.trim(), ctx, state) {
                        let trimmed_card = strip_prefix_word_ci(card_phrase.trim(), "a")
                            .or_else(|| strip_prefix_word_ci(card_phrase.trim(), "an"))
                            .unwrap_or(card_phrase.trim())
                            .trim();
                        let filter_opt =
                            if eq_ci(trimmed_card, "card") || eq_ci(trimmed_card, "cards") {
                                Some(ObjectFilter::default())
                            } else {
                                let ftoks = tokenize(trimmed_card, 0);
                                if !ftoks.is_empty()
                                    && let Some((f, used)) = parse_object_filter(
                                        &ftoks,
                                        ctx,
                                        FilterOpts {
                                            default_zone: ZoneMask::empty(),
                                            allow_plural_and_disjunction: true,
                                            allow_spell_noun: false,
                                            strip_trailing_card: true,
                                            ..Default::default()
                                        },
                                        state,
                                    )
                                    && used == ftoks.len()
                                {
                                    Some(f)
                                } else {
                                    None
                                }
                            };
                        if let Some(filter) = filter_opt {
                            state.push_step(
                                make_step(
                                    EffectOp::RevealAndDiscard {
                                        spec: Some(mtg_ir::CoerciveDiscardSpec {
                                            chooser: PlayerRef::You,
                                            filter: Some(Box::new(filter)),
                                            optional_choice,
                                            destination,
                                        }),
                                        partial_reveal: None,
                                        coercive_count: None,
                                        include_graveyard: false,
                                        discard_all_matching_sacrificed_colors: false,
                                        discard_all_with_chosen_name: false,
                                    },
                                    subj,
                                    Span {
                                        start: sent.span.start,
                                        end: sentences[sent_idx + 1].span.end,
                                    },
                                ),
                                false,
                            );
                            sent_idx += 2;
                            continue;
                        }
                    }
                    state.rollback(cp_mark, ctx);
                }
            }
        }
        if sent_idx + 2 < sentences.len() {
            let s0_clean = trim_trailing_period(s_text);
            if let Some(who_s) = strip_suffix_word_ci(s0_clean, "reveals their hand")
                .or_else(|| strip_suffix_word_ci(s0_clean, "reveal their hand"))
            {
                let s1_clean = trim_trailing_period(sentences[sent_idx + 1].text.trim());
                let s2_raw = trim_trailing_period(sentences[sent_idx + 2].text.trim());
                let s2_clean = strip_prefix_word_ci(s2_raw, "if you do,")
                    .map(str::trim)
                    .unwrap_or(s2_raw);
                let dest_opt = if eq_ci(s2_clean, "that player discards that card")
                    || eq_ci(s2_clean, "they discard that card")
                    || eq_ci(s2_clean, "that player discards it")
                    || eq_ci(s2_clean, "they discard it")
                {
                    Some(Zone::Graveyard)
                } else if eq_ci(s2_clean, "that player exiles that card")
                    || eq_ci(s2_clean, "you exile that card")
                    || eq_ci(s2_clean, "exile that card")
                    || eq_ci(s2_clean, "exile it")
                    || eq_ci(s2_clean, "that player exiles it")
                {
                    Some(Zone::Exile)
                } else {
                    None
                };
                if let Some(destination) = dest_opt
                    && let Some((optional_choice, choose_body)) =
                        strip_prefix_word_ci(s1_clean, "you may choose")
                            .map(|r| (true, r))
                            .or_else(|| {
                                strip_prefix_word_ci(s1_clean, "you choose").map(|r| (false, r))
                            })
                    && let Some(card_phrase) = strip_suffix_word_ci(choose_body.trim(), "from it")
                {
                    let cp_mark = state.mark(ctx);
                    if let Some(subj) = parse_player_selector(who_s.trim(), ctx, state) {
                        let trimmed_card = strip_prefix_word_ci(card_phrase.trim(), "a")
                            .or_else(|| strip_prefix_word_ci(card_phrase.trim(), "an"))
                            .unwrap_or(card_phrase.trim())
                            .trim();
                        let filter_opt =
                            if eq_ci(trimmed_card, "card") || eq_ci(trimmed_card, "cards") {
                                Some(ObjectFilter::default())
                            } else {
                                let ftoks = tokenize(trimmed_card, 0);
                                if !ftoks.is_empty()
                                    && let Some((f, used)) = parse_object_filter(
                                        &ftoks,
                                        ctx,
                                        FilterOpts {
                                            default_zone: ZoneMask::empty(),
                                            allow_plural_and_disjunction: true,
                                            allow_spell_noun: false,
                                            strip_trailing_card: true,
                                            ..Default::default()
                                        },
                                        state,
                                    )
                                    && used == ftoks.len()
                                {
                                    Some(f)
                                } else {
                                    None
                                }
                            };
                        if let Some(filter) = filter_opt {
                            state.push_step(
                                make_step(
                                    EffectOp::RevealAndDiscard {
                                        spec: Some(mtg_ir::CoerciveDiscardSpec {
                                            chooser: PlayerRef::You,
                                            filter: Some(Box::new(filter)),
                                            optional_choice,
                                            destination,
                                        }),
                                        partial_reveal: None,
                                        coercive_count: None,
                                        include_graveyard: false,
                                        discard_all_matching_sacrificed_colors: false,
                                        discard_all_with_chosen_name: false,
                                    },
                                    subj,
                                    Span {
                                        start: sent.span.start,
                                        end: sentences[sent_idx + 2].span.end,
                                    },
                                ),
                                false,
                            );
                            sent_idx += 3;
                            continue;
                        }
                    }
                    state.rollback(cp_mark, ctx);
                }
            }
        }
        if sent_idx + 1 < sentences.len() {
            let s0_clean = trim_trailing_period(s_text);
            let s1_clean = trim_trailing_period(sentences[sent_idx + 1].text.trim());
            if (eq_ci(s0_clean, "choose a creature or planeswalker you control")
                || eq_ci(s0_clean, "choose a creature you control")
                || eq_ci(s0_clean, "choose a permanent you control"))
                && starts_with_word_ci(
                    s1_clean,
                    "all damage that would be dealt this turn to you and permanents you control is dealt to the chosen permanent instead",
                )
            {
                state.push_step(
                    make_step(
                        EffectOp::PreventDamage {
                            spec: Box::new(DamagePreventionSpec {
                                mode: PreventMode::All,
                                combat_only: false,
                                scope: PreventScope::Subject,
                                from_source: None,
                                also_prevent_dealt_by_subject: false,
                                choose_source: false,
                                next_damage_event_only: false,
                                on_prevented: None,
                                redirect_to: Some(PreventRedirectTo::ChosenPermanent),
                                redirect_source_color_filter: ColorMask::empty(),
                                redirect_source_kind: None,
                                min_life_floor: None,
                                all_damage_to_you_and_perms: true,
                                you_and_planeswalkers_you_control: false,
                                from_sources_you_dont_control: false,
                                from_source_colors: ColorMask::empty(),
                                from_source_not_subtypes: SmallVec::new(),
                                on_prevented_creature: None,
                                on_prevented_noncreature: None,
                                on_prevented_to_damage_source_controller: false,
                            }),
                        },
                        Selector::None,
                        Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        },
                    ),
                    false,
                );
                sent_idx += 2;
                continue;
            }
            if let Some(after_next) = strip_prefix_word_ci(
                s0_clean,
                "the next time a source of your choice would deal damage to",
            ) && let Some(to_pos) = find_word_ci(after_next, "this turn, prevent that damage")
                && after_next[to_pos + "this turn, prevent that damage".len()..]
                    .trim()
                    .is_empty()
                && starts_with_word_ci(s1_clean, "if damage")
                && find_word_ci(s1_clean, "is prevented this way,").is_some()
                && (strip_suffix_word_ci(s1_clean, "to that source's controller").is_some()
                    || strip_suffix_word_ci(s1_clean, "to the source's controller").is_some())
            {
                let subj_s = after_next[..to_pos].trim();
                let color_filter = if let Some(after_from) =
                    strip_prefix_word_ci(s1_clean, "if damage from a")
                        .or_else(|| strip_prefix_word_ci(s1_clean, "if damage from an"))
                {
                    let cw = after_from.split_whitespace().next().unwrap_or("");
                    parse_color_word(cw).unwrap_or(ColorMask::empty())
                } else {
                    ColorMask::empty()
                };
                let mark_dp = state.mark(ctx);
                if let Some(subj) = parse_any_recipient_selector(subj_s, ctx, state) {
                    state.push_step(
                        make_step(
                            EffectOp::PreventDamage {
                                spec: Box::new(DamagePreventionSpec {
                                    mode: PreventMode::All,
                                    combat_only: false,
                                    scope: PreventScope::Subject,
                                    from_source: None,
                                    also_prevent_dealt_by_subject: false,
                                    choose_source: true,
                                    next_damage_event_only: true,
                                    on_prevented: Some(mtg_ir::OnPreventedRider {
                                        kind: mtg_ir::OnPreventedKind::DealDamageEqual,
                                        counter: None,
                                        recipient: None,
                                    }),
                                    redirect_to: None,
                                    redirect_source_color_filter: color_filter,
                                    redirect_source_kind: None,
                                    min_life_floor: None,
                                    all_damage_to_you_and_perms: false,
                                    you_and_planeswalkers_you_control: false,
                                    from_sources_you_dont_control: false,
                                    from_source_colors: ColorMask::empty(),
                                    from_source_not_subtypes: SmallVec::new(),
                                    on_prevented_creature: None,
                                    on_prevented_noncreature: None,
                                    on_prevented_to_damage_source_controller: true,
                                }),
                            },
                            subj,
                            Span {
                                start: sent.span.start,
                                end: sentences[sent_idx + 1].span.end,
                            },
                        ),
                        false,
                    );
                    sent_idx += 2;
                    continue;
                }
                state.rollback(mark_dp, ctx);
            }
            if let Some(choose_rhs) = strip_prefix_word_ci(s0_clean, "each opponent chooses")
                && starts_with_word_ci(s1_clean, "return those")
                && (strip_suffix_word_ci(s1_clean, "to their owners' hands").is_some()
                    || strip_suffix_word_ci(s1_clean, "to their owners' hand").is_some())
            {
                let mut greatest_pred: Option<ObjectPredicate> = None;
                let mut obj_part = choose_rhs.trim();
                for (sep, stat) in [
                    (" with the greatest mana value among ", StatKind::ManaValue),
                    (" with the greatest power among ", StatKind::Power),
                    (" with the greatest toughness among ", StatKind::Toughness),
                ] {
                    if let Some(pos) = find_word_ci(choose_rhs, sep) {
                        let lhs = choose_rhs[..pos].trim();
                        let rhs = choose_rhs[pos + sep.len()..].trim();
                        if let Some(scope_s) = strip_suffix_word_ci(rhs, "they control") {
                            let stoks = tokenize(scope_s, 0);
                            let scp = ctx.interner.checkpoint();
                            if let Some((sf, sused)) = parse_object_filter(
                                &stoks,
                                ctx,
                                FilterOpts {
                                    default_zone: ZoneMask::BATTLEFIELD,
                                    allow_plural_and_disjunction: true,
                                    ..Default::default()
                                },
                                state,
                            ) && sused == stoks.len()
                            {
                                greatest_pred =
                                    Some(ObjectPredicate::GreatestStatAmongControlled {
                                        stat,
                                        scope_types: sf.types_any,
                                    });
                                obj_part = lhs;
                            } else {
                                ctx.interner.rollback(scp);
                            }
                        }
                        break;
                    }
                }
                if let Some(gp) = greatest_pred
                    && let Some(clean_obj) = strip_prefix_word_ci(obj_part, "a")
                        .or_else(|| strip_prefix_word_ci(obj_part, "an"))
                {
                    let toks = tokenize(clean_obj, 0);
                    let cp = ctx.interner.checkpoint();
                    if !toks.is_empty()
                        && let Some((mut f, used)) = parse_object_filter(
                            &toks,
                            ctx,
                            FilterOpts {
                                default_zone: ZoneMask::BATTLEFIELD,
                                allow_plural_and_disjunction: true,
                                ..Default::default()
                            },
                            state,
                        )
                        && used == toks.len()
                    {
                        if f.zones.is_empty() {
                            f.zones = ZoneMask::BATTLEFIELD;
                        }
                        f.extra.push(ObjectPredicate::ControllerRef {
                            player: PlayerRef::EachLoopPlayer,
                        });
                        f.extra.push(gp);
                        let combined_span = Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        };
                        let mut bounce_st = make_step(
                            EffectOp::Bounce {
                                select: SelectionMod::default(),
                            },
                            Selector::All {
                                filter: Box::new(f),
                            },
                            combined_span,
                        );
                        bounce_st.actor = Some(PlayerRef::EachLoopPlayer);
                        bounce_st.amount = Some(Box::new(Amount::Const { n: 1 }));
                        state.push_step(
                            make_step(
                                EffectOp::ForEachPlayerLoop {
                                    players: LoopPlayersKind::EachOpponent,
                                    steps: vec![bounce_st],
                                    choose_random_opponent: false,
                                    exclude_attacked_last_combat: false,
                                    exclude_event_player: false,
                                    choose_object_to_bind: None,
                                },
                                Selector::None,
                                combined_span,
                            ),
                            false,
                        );
                        sent_idx += 2;
                        continue;
                    }
                    ctx.interner.rollback(cp);
                }
            }
            if eq_ci(
                s0_clean,
                "for each player, you choose from among the permanents that player controls an artifact, a creature, an enchantment, and a planeswalker",
            ) && eq_ci(
                s1_clean,
                "then each player sacrifices all other nonland permanents they control",
            ) {
                state.push_step(
                    make_step(
                        EffectOp::PartitionKeepByTypes {
                            types: CardTypeMask::from_bits_truncate(
                                CardTypeMask::ARTIFACT.bits()
                                    | CardTypeMask::CREATURE.bits()
                                    | CardTypeMask::ENCHANTMENT.bits()
                                    | CardTypeMask::PLANESWALKER.bits(),
                            ),
                            keep_count_per_player: None,
                            chooser_you: true,
                            all_types: false,
                            nonland_only: true,
                            put_vow_counter: false,
                        },
                        Selector::None,
                        Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        },
                    ),
                    false,
                );
                sent_idx += 2;
                continue;
            }
            if eq_ci(
                s0_clean,
                "each player puts a vow counter on a creature they control and sacrifices the rest",
            ) && starts_with_word_ci(
                s1_clean,
                "each of those creatures can't attack you or planeswalkers you control for as long as it has a vow counter on it",
            ) {
                state.push_step(
                    make_step(
                        EffectOp::PartitionKeepByTypes {
                            types: CardTypeMask::CREATURE,
                            keep_count_per_player: Some(Box::new(Amount::Const { n: 1 })),
                            chooser_you: false,
                            all_types: false,
                            nonland_only: false,
                            put_vow_counter: true,
                        },
                        Selector::None,
                        Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        },
                    ),
                    false,
                );
                sent_idx += 2;
                continue;
            }
            if (eq_ci(s1_clean, "destroy the chosen permanents")
                || eq_ci(s1_clean, "exile the chosen permanents"))
                && contains_word_ci(s0_clean, "for each opponent, choose")
            {
                let (gate_cond, fe_body) = if starts_with_word_ci(s0_clean, "if ")
                    && let Some((cond_s, rest_s)) = split_at_top_level_comma(s0_clean)
                {
                    (parse_condition_str(cond_s, ctx, state), rest_s)
                } else {
                    (None, s0_clean)
                };
                if (!starts_with_word_ci(s0_clean, "if ") || gate_cond.is_some())
                    && let Some(choose_rhs) =
                        strip_prefix_word_ci(fe_body, "for each opponent, choose")
                    && let Some(obj_part) = strip_suffix_word_ci(choose_rhs, "that player controls")
                        .or_else(|| strip_suffix_word_ci(choose_rhs, "they control"))
                {
                    let obj_clean = strip_prefix_word_ci(obj_part, "a")
                        .or_else(|| strip_prefix_word_ci(obj_part, "an"))
                        .unwrap_or(obj_part);
                    let toks = tokenize(obj_clean, 0);
                    let cp = ctx.interner.checkpoint();
                    if !toks.is_empty()
                        && let Some((mut f, used)) = parse_object_filter(
                            &toks,
                            ctx,
                            FilterOpts {
                                default_zone: ZoneMask::BATTLEFIELD,
                                allow_plural_and_disjunction: true,
                                ..Default::default()
                            },
                            state,
                        )
                        && used == toks.len()
                    {
                        if f.zones.is_empty() {
                            f.zones = ZoneMask::BATTLEFIELD;
                        }
                        f.extra.push(ObjectPredicate::ControllerRef {
                            player: PlayerRef::EachLoopPlayer,
                        });
                        let combined_span = Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        };
                        let inner_op = if starts_with_word_ci(s1_clean, "exile") {
                            EffectOp::Exile {
                                select: SelectionMod {
                                    choice_count: Some(Box::new(Amount::Const { n: 1 })),
                                    ..Default::default()
                                },
                                duration: None,
                                until_source_leaves: false,
                                until_opponent_becomes_monarch: false,
                                exile_all_except_bottom: false,
                                face_down: false,
                                look_only: false,
                                exile_with_counters: None,
                            }
                        } else {
                            EffectOp::Destroy {
                                cant_be_regenerated: false,
                                select: SelectionMod {
                                    choice_count: Some(Box::new(Amount::Const { n: 1 })),
                                    ..Default::default()
                                },
                            }
                        };
                        let mut inner_st = make_step(
                            inner_op,
                            Selector::All {
                                filter: Box::new(f),
                            },
                            combined_span,
                        );
                        inner_st.amount = Some(Box::new(Amount::Const { n: 1 }));
                        let mut loop_st = make_step(
                            EffectOp::ForEachPlayerLoop {
                                players: LoopPlayersKind::EachOpponent,
                                steps: vec![inner_st],
                                choose_random_opponent: false,
                                exclude_attacked_last_combat: false,
                                exclude_event_player: false,
                                choose_object_to_bind: None,
                            },
                            Selector::None,
                            combined_span,
                        );
                        if let Some(c) = gate_cond {
                            attach_gate_condition(&mut loop_st.gate, c);
                        }
                        state.push_step(loop_st, false);
                        sent_idx += 2;
                        continue;
                    }
                    ctx.interner.rollback(cp);
                }
            }
            if (eq_ci(s0_clean, "if you do, copy it") || eq_ci(s0_clean, "copy it"))
                && starts_with_word_ci(s1_clean, "you may cast the copy")
            {
                sent_idx += 1;
                continue;
            }
            if let Some(after_if) = strip_prefix_word_ci(s0_clean, "if")
                && let Some((cond_s, body_s)) = split_at_top_level_comma(after_if)
                && eq_ci(body_s.trim(), "choose one of them at random and copy it")
                && eq_ci(
                    s1_clean,
                    "you may cast the copy without paying its mana cost",
                )
                && let Some(cond) = parse_condition_str(cond_s.trim(), ctx, state)
                && let Some((Ref::Binding { name: bname }, _)) = &state.last_object
            {
                let mut st = make_step(
                    EffectOp::CastFree {
                        spec: Some(Box::new(CastFreeSpec {
                            copy_card_first: true,
                            without_paying_mana_cost: true,
                            filter: None,
                            up_to_count: Some(1),
                            exile_if_put_into_graveyard: false,
                            alternative_mana_cost: None,
                            pay_life_equal_mana_value: false,
                            total_max_mv: None,
                            exiled_with_self: false,
                        })),
                        at_random: true,
                        cast_any_number_from_exiled: false,
                    },
                    Selector::Binding {
                        name: bname.clone(),
                    },
                    Span {
                        start: sent.span.start,
                        end: sentences[sent_idx + 1].span.end,
                    },
                );
                st.gate = Some(StepGate::Condition {
                    condition: Box::new(cond),
                });
                state.push_step(st, false);
                sent_idx += 2;
                continue;
            }
            if eq_ci(s0_clean, "an opponent chooses one of the exiled cards")
                && eq_ci(
                    s1_clean,
                    "you put that card on the bottom of your library and return the other to the battlefield tapped",
                )
            {
                state.push_step(
                    make_step(
                        EffectOp::Move {
                            from: None,
                            to: None,
                            select: SelectionMod::default(),
                            tapped: false,
                            under_your_control: false,
                            topmost_only: false,
                            may_shuffle: false,
                            position: None,
                            from_top: None,
                            library_choice_by: None,
                            random_order: false,
                            entered_transformed: false,
                            entered_flipped: false,
                            enters_tapped_and_attacking: false,
                            as_enchantment_only: false,
                            unearth: false,
                            with_counters: None,
                            attached_to: None,
                            condition: None,
                            choose_at_random_from_exiled_with_self: false,
                            leave_chosen_in_graveyard_rest_to_hand: false,
                            split_exiled_cost_cards_to_bottom_and_battlefield: true,
                        },
                        Selector::None,
                        Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        },
                    ),
                    false,
                );
                sent_idx += 2;
                continue;
            }
            if let Some(subj_s0) = strip_prefix_word_ci(s0_clean, "choose a counter on")
                && let Some(subj_s1) =
                    strip_prefix_word_ci(s1_clean, "put an additional counter of that kind on")
                && (eq_ci(subj_s1, "it")
                    || eq_ci(subj_s1, "that permanent")
                    || eq_ci(subj_s1, subj_s0))
            {
                let mark_ch = state.mark(ctx);
                if let Some(obj) = parse_object_selector(subj_s0, ZoneMask::BATTLEFIELD, ctx, state)
                {
                    let mut st = make_step(
                        EffectOp::PutCounters {
                            counter: None,
                            multi_counters: Vec::new(),
                            select: SelectionMod::default(),
                            divided: false,
                            allow_exile_counters: false,
                            remove_instead_of_add: false,
                            copy_counters_from: None,
                            choose_counter_on_subject_and_add_one: true,
                            conditional_counter_on_type: None,
                            cast_bolas_bonus_loyalty: false,
                        },
                        obj.into_selector(),
                        mtg_ir::Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        },
                    );
                    st.amount = Some(Box::new(Amount::Const { n: 1 }));
                    state.push_step(st, true);
                    sent_idx += 2;
                    continue;
                }
                state.rollback(mark_ch, ctx);
            }
            if eq_ci(
                s0_clean,
                "proliferate, then choose any number of permanents you control that had a counter put on them this way",
            ) && eq_ci(s1_clean, "those permanents phase out")
            {
                state.push_step(
                    make_step(EffectOp::Proliferate, Selector::None, sent.span),
                    false,
                );
                state.push_step(
                    make_step(
                        EffectOp::PhaseOut {
                            select: SelectionMod {
                                choice_count: Some(Box::new(Amount::Const { n: 99 })),
                                up_to: true,
                                ..Default::default()
                            },
                            cant_phase_in_while_source_controlled: false,
                        },
                        Selector::All {
                            filter: Box::new(ObjectFilter {
                                zones: ZoneMask::BATTLEFIELD,
                                controller: Some(RelativeControl::You),
                                ..Default::default()
                            }),
                        },
                        sentences[sent_idx + 1].span,
                    ),
                    false,
                );
                sent_idx += 2;
                continue;
            }
        }
        if trim_trailing_period(s_text)
            .eq_ignore_ascii_case("it can't phase in for as long as you control ~")
            && let Some(last_step) = state.steps.last_mut()
            && let EffectOp::PhaseOut {
                cant_phase_in_while_source_controlled,
                ..
            } = &mut last_step.op
        {
            *cant_phase_in_while_source_controlled = true;
            sent_idx += 1;
            continue;
        }
        let s_clean_choose = trim_trailing_period(s_text);
        if eq_ci(s_clean_choose, "it becomes plotted")
            && let Some(last_step) = state.steps.last_mut()
            && matches!(last_step.op, EffectOp::Exile { .. })
        {
            let bname = last_step
                .bind_as
                .get_or_insert_with(|| "exiled".to_string())
                .clone();
            let mut st = make_step(
                EffectOp::GrantPlayFromExile {
                    spec: PlayFromExileSpec {
                        duration: PlayFromExileDuration::AsLongAsExiled,
                        spend_mana_as_any_color: false,
                        spells_only: true,
                        without_paying_mana_cost: true,
                        alternative_mana_cost: None,
                        pay_life_equal_mana_value: false,
                        cost_reduction_generic: None,
                        plotted: true,
                        total_max_mv: None,
                    },
                    select: SelectionMod::default(),
                    cast_spell_cost_tax_for_opponents: None,
                },
                Selector::Binding {
                    name: bname.clone(),
                },
                sent.span,
            );
            st.actor = Some(PlayerRef::OwnerOf {
                of: Box::new(Ref::Binding { name: bname }),
            });
            state.push_step(st, false);
            sent_idx += 1;
            continue;
        }
        if let Some(after_tax) =
            strip_prefix_word_ci(s_clean_choose, "a spell cast by an opponent this way costs")
            && let Some(mana_s) = strip_suffix_word_ci(after_tax, "more to cast")
            && let Some(inner) = mana_s
                .trim()
                .strip_prefix('{')
                .and_then(|r| r.strip_suffix('}'))
            && let Ok(n) = inner.parse::<u16>()
            && let Some(last_step) = state.steps.last_mut()
            && let EffectOp::GrantPlayFromExile {
                cast_spell_cost_tax_for_opponents,
                ..
            } = &mut last_step.op
        {
            *cast_spell_cost_tax_for_opponents = Some(n);
            sent_idx += 1;
            continue;
        }
        if let Some(after_red) =
            strip_prefix_word_ci(s_clean_choose, "spells you cast this way cost")
            && let Some(mana_s) = strip_suffix_word_ci(after_red, "less to cast")
            && let Some(inner) = mana_s
                .trim()
                .strip_prefix('{')
                .and_then(|r| r.strip_suffix('}'))
            && let Ok(n) = inner.parse::<u16>()
            && let Some(last_step) = state.steps.last_mut()
            && let EffectOp::GrantPlayFromExile { spec, .. } = &mut last_step.op
        {
            spec.cost_reduction_generic = Some(n);
            sent_idx += 1;
            continue;
        }
        if eq_ci(
            s_clean_choose,
            "if you do, you can't cast additional spells this turn",
        ) || eq_ci(s_clean_choose, "you can't cast additional spells this turn")
        {
            state.push_step(
                make_step(
                    EffectOp::GrantPlayer {
                        rules: vec![PlayerRuleKind::CantCastAdditionalSpellsThisTurn],
                        duration: None,
                        extra_land_plays: None,
                        next_spell_types: None,
                        spend_mana_as_any_color_top_of_library: false,
                        steal_opponent_entering_creatures_until_eot: false,
                        opponents_spells_cost_more_until_next_turn: None,
                        attack_tax_until_your_next_turn: None,
                        next_spell_cost_reduction_generic: None,
                        next_creature_enters_with_plus_counters: None,
                        next_main_phase_add_mana: None,
                        double_tokens_this_turn: false,
                        flash_cast_condition: None,
                        next_spell_cascade: None,
                        extra_loyalty_activations_this_turn: None,
                        planar_action: None,
                    },
                    you_sel(),
                    sent.span,
                ),
                false,
            );
            sent_idx += 1;
            continue;
        }
        if eq_ci(s_clean_choose, "it's an enchantment")
            && let Some(last_step) = state.steps.last_mut()
            && let EffectOp::Move {
                to: Some(Zone::Battlefield),
                ref mut as_enchantment_only,
                ..
            } = last_step.op
        {
            *as_enchantment_only = true;
            sent_idx += 1;
            continue;
        }
        if sent_idx + 1 < sentences.len()
            && let Some(after_ch) = strip_prefix_word_ci(s_clean_choose, "choose")
            && let Some(clean_filt_s) = strip_suffix_word_ci(after_ch, "exiled this way")
            && let Some(last_ex_idx) = state
                .steps
                .iter()
                .rposition(|s| matches!(s.op, EffectOp::Exile { .. }))
        {
            let s1_clean = trim_trailing_period(sentences[sent_idx + 1].text.trim());
            if (starts_with_ci(s1_clean, "you may cast")
                || starts_with_ci(s1_clean, "you may play"))
                && (contains_ascii_ci(s1_clean.as_bytes(), b"that card")
                    || contains_ascii_ci(s1_clean.as_bytes(), b"play it")
                    || contains_ascii_ci(s1_clean.as_bytes(), b"cast it"))
            {
                let (up_to_ch, after_up) =
                    if let Some(r) = strip_prefix_word_ci(clean_filt_s, "up to") {
                        (true, r)
                    } else {
                        (false, clean_filt_s)
                    };
                let fw = after_up.split_whitespace().next().unwrap_or("");
                let (cnt_n, filt_body) = if eq_ci(fw, "a") || eq_ci(fw, "an") {
                    (Some(1i32), after_up[fw.len()..].trim())
                } else if let Some(n) = parse_small_number(fw) {
                    (Some(n), after_up[fw.len()..].trim())
                } else {
                    (None, after_up)
                };
                let cp_au = ctx.interner.checkpoint();
                let ftoks = tokenize(filt_body, 0);
                if let Some((filt, used)) = parse_object_filter(
                    &ftoks,
                    ctx,
                    FilterOpts {
                        default_zone: ZoneMask::empty(),
                        allow_plural_and_disjunction: true,
                        allow_spell_noun: false,
                        strip_trailing_card: true,
                        expand_outlaw_subtypes: false,
                    },
                    state,
                ) && used == ftoks.len()
                {
                    let bname = if let Some(existing) = state.steps[last_ex_idx].bind_as.clone() {
                        existing
                    } else {
                        let b = state.alloc_bind_name("exiled");
                        state.steps[last_ex_idx].bind_as = Some(b.clone());
                        b
                    };
                    let dur = if contains_ascii_ci(
                        s1_clean.as_bytes(),
                        b"for as long as it remains exiled",
                    ) || contains_ascii_ci(
                        s1_clean.as_bytes(),
                        b"for as long as they remain exiled",
                    ) {
                        PlayFromExileDuration::AsLongAsExiled
                    } else if contains_ascii_ci(
                        s1_clean.as_bytes(),
                        b"until the end of your next turn",
                    ) || contains_ascii_ci(
                        s1_clean.as_bytes(),
                        b"until end of your next turn",
                    ) {
                        PlayFromExileDuration::UntilEndOfYourNextTurn
                    } else {
                        PlayFromExileDuration::ThisTurn
                    };
                    let st = make_step(
                        EffectOp::GrantPlayFromExile {
                            spec: PlayFromExileSpec {
                                duration: dur,
                                spend_mana_as_any_color: contains_ascii_ci(
                                    s1_clean.as_bytes(),
                                    b"mana of any color",
                                ) || contains_ascii_ci(
                                    s1_clean.as_bytes(),
                                    b"mana as though it were mana of any",
                                ) || contains_ascii_ci(
                                    s1_clean.as_bytes(),
                                    b"mana of any type",
                                ),
                                spells_only: contains_ascii_ci(
                                    s1_clean.as_bytes(),
                                    b"you may cast",
                                ),
                                without_paying_mana_cost: contains_ascii_ci(
                                    s1_clean.as_bytes(),
                                    b"without paying",
                                ),
                                alternative_mana_cost: None,
                                pay_life_equal_mana_value: false,
                                cost_reduction_generic: None,
                                plotted: false,
                                total_max_mv: None,
                            },
                            select: SelectionMod {
                                choice_count: cnt_n.map(|n| Box::new(Amount::Const { n })),
                                up_to: up_to_ch,
                                filter: Some(Box::new(filt)),
                                ..Default::default()
                            },
                            cast_spell_cost_tax_for_opponents: None,
                        },
                        Selector::Binding { name: bname },
                        Span {
                            start: sent.span.start,
                            end: sentences[sent_idx + 1].span.end,
                        },
                    );
                    state.push_step(st, false);
                    sent_idx += 2;
                    continue;
                }
                ctx.interner.rollback(cp_au);
            }
        }
        if sent_idx + 1 < sentences.len()
            && !state.steps.is_empty()
            && let Some(after_when) = strip_prefix_word_ci(s_clean_choose, "when you do,")
            && starts_with_word_ci(after_when, "choose ")
            && contains_word_ci(after_when, "target")
        {
            let s1_clean = trim_trailing_period(sentences[sent_idx + 1].text.trim());
            let combined = format!("{after_when}. {s1_clean}");
            let comb_span = Span {
                start: sent.span.start,
                end: sentences[sent_idx + 1].span.end,
            };
            let mark_rt = state.mark(ctx);
            if attach_reflexive_trigger(
                ReflexiveEventFilter::WhenYouDo,
                None,
                &combined,
                comb_span,
                ctx,
                state,
            ) {
                sent_idx += 2;
                continue;
            }
            state.rollback(mark_rt, ctx);
        }
        if sent_idx + 1 < sentences.len()
            && let Some(after_on) = strip_prefix_word_ci(s_clean_choose, "choose a counter on")
        {
            let s1_clean = trim_trailing_period(sentences[sent_idx + 1].text.trim());
            if starts_with_ci(s1_clean, "remove that counter from ")
                && ends_with_ci(
                    s1_clean.as_bytes(),
                    b" or put another of those counters on it",
                )
                && let Some(obj) = parse_object_selector(
                    after_on.trim(),
                    ZoneMask::BATTLEFIELD | ZoneMask::EXILE,
                    ctx,
                    state,
                )
            {
                let sel = obj.into_selector();
                let mut st = make_step(
                    EffectOp::MoveCounters {
                        counter: None,
                        to_filter: None,
                        spec: Some(MoveCounterSpec {
                            from: Box::new(sel.clone()),
                            counter: CounterTarget::Any,
                            all: false,
                            up_to: false,
                            each_kind_not_on_dest: false,
                            one_or_more: false,
                            from_any_permanents: false,
                            choose_kind_on_permanent: false,
                            put_or_remove_kind: true,
                            any_number: false,
                        }),
                    },
                    sel,
                    Span {
                        start: sent.span.start,
                        end: sentences[sent_idx + 1].span.end,
                    },
                );
                st.amount = Some(Box::new(Amount::Const { n: 1 }));
                state.push_step(st, true);
                sent_idx += 2;
                continue;
            }
        }
        if sent_idx + 1 < sentences.len()
            && (starts_with_word_ci(s_clean_choose, "otherwise, an opponent chooses ")
                || starts_with_word_ci(s_clean_choose, "otherwise, target opponent chooses "))
            && eq_ci(
                trim_trailing_period(sentences[sent_idx + 1].text.trim()),
                "leave the chosen cards in your graveyard and put the rest into your hand",
            )
            && state.steps.len() > state.prev_sentence_step_start
            && let Some(StepGate::Condition { condition }) =
                state.steps[state.prev_sentence_step_start].gate.clone()
        {
            let comb_span = Span {
                start: sent.span.start,
                end: sentences[sent_idx + 1].span.end,
            };
            state.push_step(
                make_step(
                    EffectOp::Move {
                        from: None,
                        to: None,
                        select: SelectionMod::default(),
                        tapped: false,
                        under_your_control: false,
                        topmost_only: false,
                        may_shuffle: false,
                        position: None,
                        from_top: None,
                        library_choice_by: None,
                        random_order: false,
                        entered_transformed: false,
                        entered_flipped: false,
                        enters_tapped_and_attacking: false,
                        as_enchantment_only: false,
                        unearth: false,
                        with_counters: None,
                        attached_to: None,
                        condition: Some(Box::new(Condition::Not { of: condition })),
                        choose_at_random_from_exiled_with_self: false,
                        leave_chosen_in_graveyard_rest_to_hand: true,
                        split_exiled_cost_cards_to_bottom_and_battlefield: false,
                    },
                    Selector::None,
                    comb_span,
                ),
                false,
            );
            sent_idx += 2;
            continue;
        }
        if eq_ci(
            s_clean_choose,
            "that planeswalker enters with an additional loyalty counter on it",
        ) && state.in_trigger_context()
            && state
                .trigger
                .is_some_and(|tr| matches!(tr.event, EventKind::Cast))
            && state
                .steps
                .last()
                .is_some_and(|st| matches!(st.op, EffectOp::Exile { .. }))
        {
            let loyalty = ctx.interner.intern_counter("loyalty");
            let mut st = make_step(
                EffectOp::PutCounters {
                    counter: Some(loyalty),
                    multi_counters: Vec::new(),
                    select: SelectionMod::default(),
                    divided: false,
                    allow_exile_counters: false,
                    remove_instead_of_add: false,
                    copy_counters_from: None,
                    choose_counter_on_subject_and_add_one: false,
                    conditional_counter_on_type: None,
                    cast_bolas_bonus_loyalty: true,
                },
                Selector::EventObject,
                sent.span,
            );
            st.amount = Some(Box::new(Amount::Const { n: 1 }));
            state.push_step(st, false);
            sent_idx += 1;
            continue;
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::Fight {
                excess_damage_to_mana: edm @ None,
                ..
            } = &mut last_step.op
            && let Some(after_if) = strip_prefix_word_ci(s_clean_choose, "if")
            && find_word_ci(after_if, "is dealt excess damage this way, add that much").is_some()
            && let Some(c_pos) = find_word_ci(after_if, "add that much")
            && let Some(pips) =
                parse_mana_pip_sequence(after_if[c_pos + "add that much".len()..].trim())
            && pips.len() == 1
        {
            *edm = Some(pips[0]);
            sent_idx += 1;
            continue;
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::Damage {
                excess_to_controller,
                excess_to_controller_if_trample,
                ..
            } = &mut last_step.op
        {
            if eq_ci(
                s_clean_choose,
                "excess damage is dealt to that creature's controller instead",
            ) || eq_ci(
                s_clean_choose,
                "excess damage is dealt to that permanent's controller instead",
            ) {
                *excess_to_controller = true;
                sent_idx += 1;
                continue;
            }
            if eq_ci(
                s_clean_choose,
                "if the creature you control has trample, excess damage is dealt to that creature's controller instead",
            ) || eq_ci(
                s_clean_choose,
                "if that creature has trample, excess damage is dealt to that creature's controller instead",
            ) || eq_ci(
                s_clean_choose,
                "if ~ has trample, excess damage is dealt to that creature's controller instead",
            ) {
                *excess_to_controller_if_trample = true;
                sent_idx += 1;
                continue;
            }
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::CounterSpell {
                replacement_zone, ..
            } = &mut last_step.op
        {
            let rep_z = if eq_ci(
                s_clean_choose,
                "if that spell is countered this way, exile it instead of putting it into its owner's graveyard",
            ) || eq_ci(
                s_clean_choose,
                "if the spell is countered this way, exile it instead of putting it into its owner's graveyard",
            ) {
                Some(CounterReplacementZone::Exile)
            } else if eq_ci(
                s_clean_choose,
                "if that spell is countered this way, put it on top of its owner's library instead of putting it into its owner's graveyard",
            ) || eq_ci(
                s_clean_choose,
                "if that spell is countered this way, put it on the top of its owner's library instead of putting it into its owner's graveyard",
            ) || eq_ci(
                s_clean_choose,
                "if the spell is countered this way, put it on top of its owner's library instead of putting it into its owner's graveyard",
            ) {
                Some(CounterReplacementZone::LibraryTop)
            } else if eq_ci(
                s_clean_choose,
                "if that spell is countered this way, put it on the bottom of its owner's library instead of putting it into its owner's graveyard",
            ) || eq_ci(
                s_clean_choose,
                "if that spell is countered this way, put it on bottom of its owner's library instead of putting it into its owner's graveyard",
            ) || eq_ci(
                s_clean_choose,
                "if the spell is countered this way, put it on the bottom of its owner's library instead of putting it into its owner's graveyard",
            ) {
                Some(CounterReplacementZone::LibraryBottom)
            } else {
                None
            };
            if let Some(z) = rep_z {
                *replacement_zone = Some(z);
                sent_idx += 1;
                continue;
            }
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::Search { spec, .. } = &mut last_step.op
            && (eq_ci(
                s_clean_choose,
                "if you search your library this way, shuffle",
            ) || eq_ci(
                s_clean_choose,
                "if you search your library this way, shuffle your library",
            ) || eq_ci(
                s_clean_choose,
                "if you searched your library this way, shuffle",
            ) || eq_ci(
                s_clean_choose,
                "if you searched your library this way, shuffle your library",
            ))
            && spec.zones.contains(ZoneMask::LIBRARY)
        {
            spec.shuffle_only_if_library = true;
            sent_idx += 1;
            continue;
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::CounterSpell {
                on_countered_steal_filter: steal @ None,
                ..
            } = &mut last_step.op
            && let Some(after_if) = strip_prefix_word_ci(s_clean_choose, "if")
            && let Some(c_pos) = find_word_ci(
                after_if,
                " is countered this way, put that card onto the battlefield under your control instead of into its owner's graveyard",
            )
        {
            let raw_f = after_if[..c_pos].trim();
            let clean_f = strip_prefix_word_ci(raw_f, "an")
                .or_else(|| strip_prefix_word_ci(raw_f, "a"))
                .unwrap_or(raw_f);
            if let Some(f) = parse_object_phrase(
                clean_f,
                ctx,
                FilterOpts {
                    allow_spell_noun: true,
                    allow_plural_and_disjunction: true,
                    strip_trailing_card: true,
                    ..Default::default()
                },
            ) {
                *steal = Some(Box::new(f));
                sent_idx += 1;
                continue;
            }
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::Search { tapped, spec } = &mut last_step.op
        {
            let clean_shuf = strip_suffix_word_ci(s_clean_choose, ", then shuffle their libraries")
                .or_else(|| strip_suffix_word_ci(s_clean_choose, ", then shuffle their library"))
                .or_else(|| strip_suffix_word_ci(s_clean_choose, ", then shuffles"))
                .or_else(|| strip_suffix_word_ci(s_clean_choose, ", then shuffle"))
                .unwrap_or(s_clean_choose);
            let put_tapped = strip_suffix_word_ci(clean_shuf, "tapped")
                .map(|p| (true, p))
                .unwrap_or((false, clean_shuf));
            if eq_ci(
                put_tapped.1,
                "those players put those cards onto the battlefield",
            ) || eq_ci(
                put_tapped.1,
                "that player puts that card onto the battlefield",
            ) || eq_ci(put_tapped.1, "that player puts it onto the battlefield")
                || eq_ci(put_tapped.1, "they put those cards onto the battlefield")
            {
                spec.destinations = vec![SearchDestination {
                    zone: Zone::Battlefield,
                    tapped: put_tapped.0,
                    on_top: false,
                }];
                *tapped = put_tapped.0;
                last_step.span.end = sent.span.end;
                sent_idx += 1;
                continue;
            }
            if sent_idx + 1 < sentences.len()
                && starts_with_word_ci(
                    s_clean_choose,
                    "put one of them onto the battlefield tapped under an opponent's control if the",
                )
                && ends_with_ci(s_clean_choose.as_bytes(), b"cost was paid")
                && eq_ci(
                    trim_trailing_period(sentences[sent_idx + 1].text.trim()),
                    "put two of them onto the battlefield tapped under your control and the rest into your hand",
                )
            {
                spec.destinations = vec![
                    SearchDestination {
                        zone: Zone::Battlefield,
                        tapped: true,
                        on_top: false,
                    },
                    SearchDestination {
                        zone: Zone::Battlefield,
                        tapped: true,
                        on_top: false,
                    },
                    SearchDestination {
                        zone: Zone::Hand,
                        tapped: false,
                        on_top: false,
                    },
                ];
                *tapped = true;
                last_step.span.end = sentences[sent_idx + 1].span.end;
                sent_idx += 2;
                continue;
            }
        }
        if (eq_ci(
            s_clean_choose,
            "you may cast the exiled card without paying its mana cost",
        ) || eq_ci(
            s_clean_choose,
            "you may cast that card without paying its mana cost",
        )) && let Some(last_step) = state.steps.last_mut()
            && let EffectOp::Dig { spec, .. } = &mut last_step.op
            && spec.keep_to == DigKeepTo::Exile
            && let Some(uf) = spec.until_filter.take()
        {
            let rest_dest = match spec.rest {
                DigRestTo::Graveyard => ExileUntilRest::Graveyard,
                DigRestTo::Exile => ExileUntilRest::StayExiled,
                _ if spec.rest_random => ExileUntilRest::LibraryBottomRandom,
                _ => ExileUntilRest::LibraryBottomRandom,
            };
            last_step.op = EffectOp::ExileUntil {
                spec: Box::new(ExileUntilSpec {
                    filter: uf,
                    library_owner: None,
                    actor: None,
                    hit_action: ExileUntilHitAction::CastFree,
                    cast_free_condition: None,
                    fallback_to_hand: false,
                    spend_mana_as_any_color: false,
                    without_paying_mana_cost: false,
                    spells_only: true,
                    pay_life_equal_mana_value: false,
                    rest_destination: rest_dest,
                }),
            };
            last_step.subject = Selector::None;
            last_step.amount = None;
            last_step.bind_as = None;
            last_step.span.end = sent.span.end;
            state.last_optional_step = Some(state.steps.len() - 1);
            sent_idx += 1;
            continue;
        }
        if !state.steps.is_empty()
            && matches!(
                &state.steps.last().map(|s| &s.op),
                Some(EffectOp::ExileUntil { spec }) if spec.hit_action == ExileUntilHitAction::StayExiled
            )
        {
            if let Some(after_cast) = strip_prefix_word_ci(
                s_clean_choose,
                "you may cast it without paying its mana cost",
            )
            .or_else(|| {
                strip_prefix_word_ci(
                    s_clean_choose,
                    "you may cast that card without paying its mana cost",
                )
            }) {
                let rest_cond = after_cast.trim();
                let parsed_cond: Option<Option<Box<Condition>>> = if rest_cond.is_empty() {
                    Some(None)
                } else if let Some(after_mv) =
                    strip_prefix_word_ci(rest_cond, "if that spell's mana value is")
                    && let Some(amt_s) = strip_suffix_word_ci(after_mv, "or less")
                    && let Some(amt) = parse_amount_str(amt_s.trim(), ctx, state)
                {
                    Some(Some(Box::new(Condition::Compare {
                        left: Box::new(Amount::Stat {
                            of: Ref::SelfObj,
                            stat: mtg_ir::StatKind::ManaValue,
                            lki: false,
                        }),
                        op: mtg_ir::CompareOp::Le,
                        right: Box::new(amt),
                    })))
                } else {
                    None
                };
                if let Some(cond_opt) = parsed_cond
                    && let Some(last_step) = state.steps.last_mut()
                    && let EffectOp::ExileUntil { spec } = &mut last_step.op
                {
                    if let Some(cond) = cond_opt {
                        spec.cast_free_condition = Some(cond);
                    }
                    spec.hit_action = ExileUntilHitAction::CastFree;
                    last_step.span.end = sent.span.end;
                    state.last_optional_step = Some(state.steps.len() - 1);
                    sent_idx += 1;
                    continue;
                }
            } else if eq_ci(
                s_clean_choose,
                "until end of turn, you may cast that card without paying its mana cost",
            ) || eq_ci(
                s_clean_choose,
                "until end of turn, you may cast it without paying its mana cost",
            ) {
                if let Some(last_step) = state.steps.last_mut()
                    && let EffectOp::ExileUntil { spec } = &mut last_step.op
                {
                    spec.hit_action = ExileUntilHitAction::PlayThisTurn;
                    spec.without_paying_mana_cost = true;
                    spec.spells_only = true;
                    last_step.span.end = sent.span.end;
                    state.last_optional_step = Some(state.steps.len() - 1);
                    sent_idx += 1;
                    continue;
                }
            } else if (eq_ci(
                s_clean_choose,
                "you may cast that card by paying life equal to the spell's mana value rather than paying its mana cost",
            ) || eq_ci(
                s_clean_choose,
                "you may cast it by paying life equal to the spell's mana value rather than paying its mana cost",
            )) && let Some(last_step) = state.steps.last_mut()
                && let EffectOp::ExileUntil { spec } = &mut last_step.op
            {
                spec.hit_action = ExileUntilHitAction::CastFree;
                spec.pay_life_equal_mana_value = true;
                spec.spells_only = true;
                last_step.span.end = sent.span.end;
                state.last_optional_step = Some(state.steps.len() - 1);
                sent_idx += 1;
                continue;
            }
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::GrantGraveyardCast {
                spec: Some(spec), ..
            } = &mut last_step.op
            && (eq_ci(
                s_clean_choose,
                "the flashback cost is equal to that card's mana cost",
            ) || eq_ci(
                s_clean_choose,
                "the flashback cost is equal to its mana cost",
            ))
        {
            spec.flashback_equal_mana_cost = true;
            spec.exile_if_would_enter_graveyard = true;
            last_step.span.end = sent.span.end;
            sent_idx += 1;
            continue;
        }
        if (eq_ci(
            s_clean_choose,
            "then each player who owns a spell you cast this way loses life equal to its mana value",
        ) || eq_ci(
            s_clean_choose,
            "each player who owns a spell you cast this way loses life equal to its mana value",
        )) && state.steps.last().is_some_and(|s| {
            matches!(
                s.op,
                EffectOp::CastFree {
                    cast_any_number_from_exiled: true,
                    ..
                }
            )
        }) {
            let bname = if let Some(b) = state.steps.last().and_then(|s| s.bind_as.clone()) {
                b
            } else {
                let b = state.alloc_bind_name("cast");
                if let Some(last_step) = state.steps.last_mut() {
                    last_step.bind_as = Some(b.clone());
                }
                b
            };
            let mut lose_st = make_step(
                EffectOp::LoseLife,
                Selector::PlayerRef {
                    player: PlayerRef::OwnerOf {
                        of: Box::new(Ref::Binding {
                            name: bname.clone(),
                        }),
                    },
                },
                sent.span,
            );
            lose_st.amount = Some(Box::new(Amount::Stat {
                of: Ref::Binding { name: bname },
                stat: StatKind::ManaValue,
                lki: true,
            }));
            state.push_step(lose_st, false);
            sent_idx += 1;
            continue;
        }
        if let Some(pipe_pos) = s_clean_choose.find('|')
            && let Some(roll_idx) = state
                .steps
                .iter()
                .rposition(|s| matches!(s.op, EffectOp::RollDie { .. }))
        {
            let range_raw = s_clean_choose[..pipe_pos].trim();
            let parsed_range = if let Some(base) = range_raw.strip_suffix('+') {
                base.trim().parse::<u16>().ok().map(|m| (m, 999u16))
            } else if let Some((a, b)) = range_raw
                .split_once('—')
                .or_else(|| range_raw.split_once('–'))
                .or_else(|| range_raw.split_once('-'))
            {
                match (a.trim().parse::<u16>(), b.trim().parse::<u16>()) {
                    (Ok(lo), Ok(hi)) if lo <= hi => Some((lo, hi)),
                    _ => None,
                }
            } else {
                range_raw.parse::<u16>().ok().map(|m| (m, m))
            };
            if let Some((min, max)) = parsed_range {
                let leading_ws = sent.text.len() - sent.text.trim_start().len();
                let after_pipe = &s_clean_choose[pipe_pos + 1..];
                let body_ws = after_pipe.len() - after_pipe.trim_start().len();
                let first_body = after_pipe.trim();
                let body_start = sent.span.start + (leading_ws + pipe_pos + 1 + body_ws) as u32;
                let mut end_idx = sent_idx + 1;
                let mut row_sents = vec![NormalizedSentence {
                    text: first_body.to_string(),
                    span: Span {
                        start: body_start,
                        end: sent.span.end,
                    },
                }];
                while end_idx < sentences.len() && !sentences[end_idx].text.contains('|') {
                    row_sents.push(sentences[end_idx].clone());
                    end_idx += 1;
                }
                let initial_targets_len = state.targets.len();
                let mut sub_state =
                    ParserState::new(state.context, state.trigger, state.quoted_compiler);
                sub_state.targets = state.targets.clone();
                sub_state.last_object = state.last_object.clone();
                sub_state.last_player = state.last_player.clone();
                sub_state.defined_x = state.defined_x.clone();
                sub_state.bind_counter = state.bind_counter;
                sub_state.parent_exile_bindings = state.parent_exile_bindings.clone();
                sub_state.parent_exile_selectors = state.parent_exile_selectors.clone();
                for st in &state.steps {
                    if matches!(st.op, EffectOp::Exile { .. }) {
                        if let Some(ref b) = st.bind_as
                            && !sub_state.parent_exile_bindings.contains(b)
                        {
                            sub_state.parent_exile_bindings.push(b.clone());
                        }
                        if !matches!(st.subject, Selector::None)
                            && !sub_state.parent_exile_selectors.contains(&st.subject)
                        {
                            sub_state.parent_exile_selectors.push(st.subject.clone());
                        }
                    }
                }
                let cp_die = ctx.interner.checkpoint();
                parse_sentences_into(&row_sents, ctx, &mut sub_state);
                if sub_state.unparsed.is_empty()
                    && sub_state.targets.len() == initial_targets_len
                    && !sub_state.steps.is_empty()
                    && let EffectOp::RollDie { ref mut table, .. } = state.steps[roll_idx].op
                {
                    table.push(mtg_ir::DieRollBranch {
                        min: min.into(),
                        max: max.into(),
                        effect: sub_state.steps,
                    });
                    state.bind_counter = sub_state.bind_counter;
                    state.steps[roll_idx].span.end = sentences[end_idx - 1].span.end;
                    sent_idx = end_idx;
                    continue;
                }
                ctx.interner.rollback(cp_die);
            }
        }
        if let Some(last_step) = state.steps.last_mut()
            && let EffectOp::Move {
                to: Some(Zone::Battlefield),
                with_counters: wc @ None,
                ..
            } = &mut last_step.op
            && let (Some(parsed_wc), prefix) = extract_with_counters(s_clean_choose, ctx)
            && (eq_ci(prefix, "each of them enters")
                || eq_ci(prefix, "they enter")
                || eq_ci(prefix, "it enters")
                || eq_ci(prefix, "those creatures enter")
                || eq_ci(prefix, "that creature enters")
                || eq_ci(prefix, "each enters"))
        {
            *wc = Some(parsed_wc);
            sent_idx += 1;
            continue;
        }
        if eq_ci(s_clean_choose, "choose another target player")
            || eq_ci(s_clean_choose, "choose another target opponent")
        {
            let rel = if contains_word_ci(s_clean_choose, "opponent") {
                PlayerRelation::Opponent
            } else {
                PlayerRelation::Any
            };
            let mut sp = default_target_spec();
            sp.kind = TargetKind::Player;
            sp.player = Some(PlayerFilter { relation: rel });
            sp.other_target = true;
            let idx = state.add_target(sp);
            state.last_player = Some(Selector::Target { index: idx });
            sent_idx += 1;
            continue;
        }
        if let Some(after_choose) = strip_prefix_word_ci(s_clean_choose, "choose")
            && contains_word_ci(after_choose, "target")
        {
            let ctoks = tokenize(after_choose, 0);
            let cp_ch = ctx.interner.checkpoint();
            if !ctoks.is_empty()
                && let Some((sp, used)) = parse_target_spec(&ctoks, ctx, state)
                && used == ctoks.len()
            {
                let is_player = matches!(sp.kind, TargetKind::Player);
                let idx = state.add_target(sp);
                if is_player {
                    state.last_player = Some(Selector::Target { index: idx });
                } else {
                    state.last_object =
                        Some((Ref::Target { index: idx }, sent.span.start as usize));
                }
                sent_idx += 1;
                continue;
            }
            ctx.interner.rollback(cp_ch);
        }
        if eq_ci(s_clean_choose, "choose odd or even")
            && sent_idx + 1 < sentences.len()
            && eq_ci(
                trim_trailing_period(sentences[sent_idx + 1].text.trim()),
                "creatures with mana value of that quality can't block this turn",
            )
        {
            state.push_step(
                make_step(
                    EffectOp::CombatRestriction {
                        spec: None,
                        duration: Some(Duration::EndOfTurn),
                        choose_odd_or_even_cant_block: true,
                        must_attack_next_combat: false,
                        must_attack_player: None,
                        until_your_next_turn_directive: None,
                    },
                    Selector::None,
                    sent.span,
                ),
                false,
            );
            sent_idx += 2;
            continue;
        }
        if eq_ci(s_clean_choose, "choose an opponent at random")
            || eq_ci(s_clean_choose, "choose an opponent")
            || eq_ci(
                s_clean_choose,
                "choose an opponent at random that ~ didn't attack during your last combat",
            )
        {
            let is_random = contains_word_ci(s_clean_choose, "at random");
            let exclude_attacked =
                contains_word_ci(s_clean_choose, "didn't attack during your last combat");
            state.push_step(
                make_step(
                    EffectOp::ForEachPlayerLoop {
                        players: if is_random {
                            LoopPlayersKind::ChooseRandomOpponent
                        } else {
                            LoopPlayersKind::ChooseOpponent
                        },
                        steps: Vec::new(),
                        choose_random_opponent: is_random,
                        exclude_attacked_last_combat: exclude_attacked,
                        exclude_event_player: false,
                        choose_object_to_bind: None,
                    },
                    Selector::None,
                    sent.span,
                ),
                false,
            );
            state.last_player = Some(Selector::PlayerRef {
                player: PlayerRef::ChosenOpponent,
            });
            sent_idx += 1;
            continue;
        }
        if let Some(after_cant) =
            strip_prefix_word_ci(s_clean_choose, "if you can't choose an opponent this way,")
            && let Some(loop_idx) = state.steps.iter().rposition(|s| {
                matches!(
                    s.op,
                    EffectOp::ForEachPlayerLoop {
                        players: LoopPlayersKind::ChooseRandomOpponent
                            | LoopPlayersKind::ChooseOpponent,
                        ..
                    }
                )
            })
        {
            let before = state.steps.len();
            let mark = state.mark(ctx);
            if parse_clauses_into(after_cant.trim(), sent.span.start, ctx, state)
                && state.steps.len() > before
            {
                for st in &mut state.steps[before..] {
                    st.gate = Some(StepGate::IfPrecedingDeclined {
                        step_index: loop_idx as u16,
                    });
                }
                sent_idx += 1;
                continue;
            }
            state.rollback(mark, ctx);
        }
        if state.steps.len() > state.last_sentence_step_start {
            state.prev_sentence_step_start = state.last_sentence_step_start;
            state.last_sentence_step_start = state.steps.len();
            state.prev_sentence_target_start = state.last_sentence_target_start;
            state.last_sentence_target_start = state.targets.len();
        }

        // Sentence-level replacement branch: "If <cond>, [instead] <alt> [instead [of <N>]]" (Kicker / Gift / Bargain / Hazel / Spell mastery)
        let s_clean_body = trim_trailing_period(s_text);
        fn strip_instead_of_num(b: &str) -> Option<&str> {
            let pos = rfind_ascii_ci(b.as_bytes(), b" instead of ")?;
            let head = b[..pos].trim();
            let tail = b[pos + " instead of ".len()..].trim();
            parse_small_number(tail).map(|_| head)
        }
        let instead_if_pair: Option<(&str, &str)> = if starts_with_word_ci(s_clean_body, "if ")
            && let Some((cond_part, body_part)) = split_at_top_level_comma(s_clean_body)
            && let Some(body_no_instead) = strip_prefix_word_ci(body_part, "instead")
                .or_else(|| strip_suffix_word_ci(body_part, "instead"))
                .or_else(|| strip_instead_of_num(body_part))
                .map(|b| b.trim().trim_start_matches(',').trim())
            && !body_no_instead.is_empty()
        {
            Some((cond_part, body_no_instead))
        } else if let Some(pos) = find_word_ci(s_clean_body, " instead if ") {
            let body_no_instead = s_clean_body[..pos].trim();
            let cond_part = s_clean_body[pos + " instead ".len()..].trim();
            if !body_no_instead.is_empty() && !cond_part.is_empty() {
                Some((cond_part, body_no_instead))
            } else {
                None
            }
        } else {
            None
        };
        if let Some((cond_part, body_no_instead)) = instead_if_pair
            && state.last_sentence_step_start > state.prev_sentence_step_start
        {
            let prev_s_start = state.prev_sentence_step_start;
            let prev_s_end = state.last_sentence_step_start;
            let is_single_copy_or_token = prev_s_end == prev_s_start + 1
                && matches!(
                    state.steps[prev_s_start].op,
                    EffectOp::CopyPermanent { .. } | EffectOp::CreateToken { .. }
                )
                && matches!(
                    state.steps[prev_s_start].amount.as_deref(),
                    None | Some(Amount::Const { n: 1 })
                );
            let is_single_search = prev_s_end == prev_s_start + 1
                && matches!(state.steps[prev_s_start].op, EffectOp::Search { .. });
            let saved_last_obj = state.last_object.clone();
            if (is_single_copy_or_token
                || matches!(state.steps[prev_s_start].op, EffectOp::Move { .. }))
                && matches!(
                    state.steps[prev_s_start].op,
                    EffectOp::CopyPermanent { .. } | EffectOp::Move { .. }
                )
                && let Selector::Target { index } = state.steps[prev_s_start].subject
            {
                state.last_object = Some((Ref::Target { index }, prev_s_start));
            }
            if let Some(cond) = parse_condition_str(cond_part, ctx, state) {
                let prev_t_start = state.prev_sentence_target_start;
                let prev_t_end = state.last_sentence_target_start;
                let prev_dig = state.pending_dig;
                let mark_inst = state.mark(ctx);
                let parsed_alt = parse_core_imperative(body_no_instead, sent.span, ctx, state) || {
                    state.rollback(mark_inst.clone(), ctx);
                    parse_clauses_into(body_no_instead, sent.span.start, ctx, state)
                };
                if parsed_alt && state.steps.len() > prev_s_end {
                    let fold_amt_pair: Option<(Box<Amount>, Box<Amount>)> =
                        if is_single_copy_or_token && state.steps.len() == prev_s_end + 1 {
                            let same_kind = matches!(
                                (&state.steps[prev_s_start].op, &state.steps[prev_s_end].op),
                                (
                                    EffectOp::CopyPermanent { .. },
                                    EffectOp::CopyPermanent { .. }
                                ) | (EffectOp::CreateToken { .. }, EffectOp::CreateToken { .. })
                            );
                            if same_kind {
                                state.steps[prev_s_end]
                                    .amount
                                    .take()
                                    .map(|a| (a, Box::new(Amount::Const { n: 1 })))
                            } else {
                                None
                            }
                        } else {
                            None
                        };
                    if let Some((then_amt, else_amt)) = fold_amt_pair {
                        state.steps[prev_s_start].amount = Some(Box::new(Amount::Conditional {
                            condition: Box::new(cond),
                            then_amt,
                            else_amt,
                        }));
                        state.rollback(mark_inst, ctx);
                        state.last_object = saved_last_obj;
                        sent_idx += 1;
                        continue;
                    }
                    if is_single_search
                        && state.steps.len() == prev_s_end + 1
                        && let (first_half, second_half) = state.steps.split_at_mut(prev_s_end)
                        && let (
                            EffectOp::Search {
                                spec: spec0,
                                tapped: tap0,
                            },
                            EffectOp::Search {
                                spec: spec1,
                                tapped: tap1,
                            },
                        ) = (&first_half[prev_s_start].op, &mut second_half[0].op)
                        && spec0.filter == spec1.filter
                        && spec1.destinations.len() == 1
                        && spec1.destinations[0].zone == Zone::Hand
                        && !spec1.destinations[0].tapped
                        && !spec1.destinations[0].on_top
                    {
                        spec1.destinations = spec0.destinations.clone();
                        spec1.reveal = spec0.reveal;
                        *tap1 = *tap0;
                    }
                    if prev_s_end == prev_s_start + 1 && state.steps.len() == prev_s_end + 1 {
                        if let Some(b0) = state.steps[prev_s_start].bind_as.clone()
                            && state.steps[prev_s_end].bind_as.is_some()
                        {
                            state.steps[prev_s_end].bind_as = Some(b0.clone());
                            state.last_object = Some((Ref::Binding { name: b0 }, prev_s_start));
                        } else if let Some(b1) = state.steps[prev_s_end].bind_as.clone()
                            && state.steps[prev_s_start].bind_as.is_none()
                        {
                            state.steps[prev_s_start].bind_as = Some(b1.clone());
                            state.last_object = Some((Ref::Binding { name: b1 }, prev_s_end));
                        }
                    }
                    let mut neg_cond = Condition::Not {
                        of: Box::new(cond.clone()),
                    };
                    if let Condition::Not { of } = &neg_cond
                        && let Condition::Not { of: inner } = &**of
                    {
                        neg_cond = (**inner).clone();
                    }
                    for st in &mut state.steps[prev_s_start..prev_s_end] {
                        attach_gate_condition(&mut st.gate, neg_cond.clone());
                    }
                    for st in &mut state.steps[prev_s_end..] {
                        attach_gate_condition(&mut st.gate, cond.clone());
                    }
                    if state.targets.len() > prev_t_end {
                        for tidx in prev_t_start..prev_t_end {
                            let reused = state.steps[prev_s_end..].iter().any(|s| {
                                s.subject == Selector::Target { index: tidx as u16 }
                                    || s.actor == Some(PlayerRef::Target { index: tidx as u16 })
                            });
                            if !reused && state.targets[tidx].condition.is_none() {
                                state.targets[tidx].condition = Some(Box::new(neg_cond.clone()));
                            }
                        }
                        for tgt in &mut state.targets[prev_t_end..] {
                            if tgt.condition.is_none() {
                                tgt.condition = Some(Box::new(cond.clone()));
                            }
                        }
                    }
                    if prev_dig.is_some() && state.pending_dig != prev_dig {
                        state.alt_pending_dig = prev_dig;
                    }
                    sent_idx += 1;
                    continue;
                }
                state.rollback(mark_inst, ctx);
            }
            state.last_object = saved_last_obj;
        }

        if try_complete_pending_dig(s_text, ctx, state) {
            sent_idx += 1;
            continue;
        }

        if let Some(last_step) = state.steps.last_mut()
            && let Some(rt) = last_step.reflexive_trigger.as_mut()
            && !rt.effect.is_empty()
            && (!rt.targets.is_empty() || rt.effect.iter().any(|s| s.bind_as.is_some()))
            && (starts_with_word_ci(s_text, "it ")
                || starts_with_word_ci(s_text, "it's ")
                || starts_with_word_ci(s_text, "they ")
                || starts_with_word_ci(s_text, "that creature ")
                || starts_with_word_ci(s_text, "that permanent ")
                || starts_with_word_ci(s_text, "that artifact "))
            && !contains_word_ci(s_text, "this ")
        {
            let mut sub_state = ParserState::new(
                AbilityContext::Triggered,
                state.trigger,
                state.quoted_compiler,
            );
            sub_state.targets = rt.targets.clone();
            sub_state.steps = rt.effect.clone();
            sub_state.bind_counter = state.bind_counter;
            sub_state.defined_x = state.defined_x.clone();
            if let Some(bind) = rt.effect.iter().rev().find_map(|s| s.bind_as.as_ref()) {
                sub_state.last_object = Some((
                    Ref::Binding { name: bind.clone() },
                    sent.span.start as usize,
                ));
            } else if !rt.targets.is_empty() {
                sub_state.last_object = Some((
                    Ref::Target {
                        index: (rt.targets.len() - 1) as u16,
                    },
                    sent.span.start as usize,
                ));
            }
            let rt_mark = sub_state.mark(ctx);
            let parsed_rt = parse_core_imperative(s_text, sent.span, ctx, &mut sub_state) || {
                sub_state.rollback(rt_mark.clone(), ctx);
                parse_clauses_into(s_text, sent.span.start, ctx, &mut sub_state)
            };
            if parsed_rt && sub_state.steps.len() > rt.effect.len() {
                state.bind_counter = sub_state.bind_counter;
                rt.targets = sub_state.targets;
                rt.effect = sub_state.steps;
                if let Some(txt) = rt.text.as_mut() {
                    txt.push(' ');
                    txt.push_str(s_text);
                }
                sent_idx += 1;
                continue;
            }
            sub_state.rollback(rt_mark, ctx);
        }

        // Check whole-sentence parse first (e.g., "Repeat this process", delayed trigger, punisher, etc.)
        let mark = state.mark(ctx);
        if parse_core_imperative(s_text, sent.span, ctx, state) {
            sent_idx += 1;
            continue;
        }
        state.rollback(mark, ctx);

        // Try splitting into clauses (", then ", "; ", " and ")
        let mark2 = state.mark(ctx);
        if parse_clauses_into(s_text, sent.span.start, ctx, state) {
            sent_idx += 1;
            continue;
        }
        state.rollback(mark2, ctx);

        state.unparsed.push(sent.span);
        sent_idx += 1;
    }
}
// ============================================================================
// Section 8: Modals (Standard, Spree, Tiered, Pawprint, Expanded) & Spell Face
// ============================================================================

fn strip_bullet_marker(s: &str) -> (&str, u32) {
    let trimmed = s.trim_start();
    let ws = (s.len() - trimmed.len()) as u32;
    if let Some(after) = trimmed.strip_prefix('•') {
        let after_ws = after.trim_start();
        let extra = (after.len() - after_ws.len()) as u32;
        (after_ws, ws + '•'.len_utf8() as u32 + extra)
    } else if let Some(after) = trimmed.strip_prefix("- ") {
        (after.trim_start(), ws + 2)
    } else {
        (trimmed, ws)
    }
}

fn parse_modal_header_bounds(
    header: &str,
    mode_count: usize,
) -> Option<(u16, u16, bool, bool, bool)> {
    let h = trim_trailing_period(header)
        .trim_end_matches('—')
        .trim_end_matches("--")
        .trim();
    let allow_repeat = contains_ascii_ci(h.as_bytes(), b"same mode more than once");
    let once_per_turn_unique = contains_ascii_ci(h.as_bytes(), b"hasn't been chosen");
    let up_to = contains_ascii_ci(h.as_bytes(), b"up to ");

    if starts_with_ci(h, "choose one or more") {
        return Some((
            1,
            mode_count.max(1) as u16,
            allow_repeat,
            once_per_turn_unique,
            false,
        ));
    }
    if starts_with_ci(h, "choose one or both") {
        return Some((
            1,
            2.min(mode_count.max(1)) as u16,
            allow_repeat,
            once_per_turn_unique,
            false,
        ));
    }
    if starts_with_ci(h, "choose any number") {
        return Some((
            0,
            mode_count.max(1) as u16,
            allow_repeat,
            once_per_turn_unique,
            false,
        ));
    }
    if let Some(rest) = strip_prefix_ci(h, "choose up to ") {
        let num_w = rest.split([' ', '.', '—']).next().unwrap_or("");
        let n = parse_small_number(num_w)?.max(1) as u16;
        return Some((0, n, allow_repeat, once_per_turn_unique, true));
    }
    if let Some(rest) = strip_prefix_ci(h, "choose ") {
        let num_w = rest.split([' ', '.', '—']).next().unwrap_or("");
        if let Some(n) = parse_small_number(num_w)
            && n >= 1
        {
            let nu = n as u16;
            return Some((nu, nu, allow_repeat, once_per_turn_unique, up_to));
        }
        if eq_ci(num_w, "x") {
            return Some((
                1,
                mode_count.max(1) as u16,
                allow_repeat,
                once_per_turn_unique,
                false,
            ));
        }
    }
    None
}

fn parse_modal_inner(
    header: &str,
    bullets: &[ModalBullet<'_>],
    context: AbilityContext,
    _header_start: u32,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    if bullets.is_empty() {
        return EffectParse::default();
    }
    if let Some(expanded) = parse_expanded_modal_inner(
        header,
        bullets,
        context,
        _header_start,
        trigger,
        ctx,
        quoted_compiler,
    ) {
        return expanded;
    }

    let Some((min, max, allow_repeat, once_per_turn_unique, up_to)) =
        parse_modal_header_bounds(header, bullets.len())
    else {
        return EffectParse {
            unparsed: vec![Span {
                start: _header_start,
                end: _header_start + header.len() as u32,
            }],
            ..Default::default()
        };
    };

    let mut modes = Vec::with_capacity(bullets.len());
    let mut unparsed = Vec::new();
    for b in bullets {
        let (b_text, skip) = strip_bullet_marker(b.text);
        let b_clean = crate::parser::strip_leading_ability_word(b_text);
        let flavor_skip = (b_text.len() - b_clean.len()) as u32;
        let res = parse_effects_inner(
            b_clean,
            b.span.start + skip + flavor_skip,
            context,
            trigger,
            ctx,
            quoted_compiler,
        );
        if !res.unparsed.is_empty() || res.steps.is_empty() {
            unparsed.extend(res.unparsed);
            if res.steps.is_empty() {
                unparsed.push(b.span);
            }
        }
        modes.push(ModalMode {
            targets: res.targets,
            effect: res.steps,
            span: b.span,
        });
    }

    EffectParse {
        steps: Vec::new(),
        targets: Vec::new(),
        modal: Some(ModalDef {
            min,
            max,
            allow_repeat,
            once_per_turn_unique,
            up_to,
            conditional_choose_all: None,
            modes,
            per_mode_costs: Vec::new(),
            unchosen_permanent: false,
            opponent_chooses: None,
            pawprint_budget: None,
            pawprint_costs: Vec::new(),
            dynamic_max: None,
            random_mode: false,
            prefix_effect: Vec::new(),
            suffix_effect: Vec::new(),
            conditional_choose_range: None,
            conditional_not_random: None,
            different_player_targets_per_mode: false,
        }),
        unparsed,
    }
}

fn parse_bullet_cost_prefix(bullet: &str, is_spree: bool) -> Option<(&str, &str)> {
    let t = bullet.trim();
    let dash_pos = t.find('—').or_else(|| t.find(" - "))?;
    let dash_len = if t[dash_pos..].starts_with('—') {
        '—'.len_utf8()
    } else {
        3
    };
    let left = t[..dash_pos].trim();
    let right = t[dash_pos + dash_len..].trim();
    if is_spree {
        let cost_raw = left.strip_prefix('+')?.trim();
        Some((cost_raw, right))
    } else if left.starts_with('{') {
        Some((left, right))
    } else {
        None
    }
}

fn count_pawprints(s: &str) -> u16 {
    let mut count = 0u16;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i + 2 < bytes.len() {
        if bytes[i] == b'{'
            && (bytes[i + 1] == b'P' || bytes[i + 1] == b'p')
            && bytes[i + 2] == b'}'
        {
            count += 1;
            i += 3;
        } else {
            i += 1;
        }
    }
    count
}

fn parse_expanded_modal_inner(
    header: &str,
    bullets: &[ModalBullet<'_>],
    context: AbilityContext,
    header_start: u32,
    trigger: Option<&TriggerDef>,
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> Option<EffectParse> {
    if bullets.is_empty() {
        return None;
    }
    let h_trim = header.trim();

    // 1. Spree / Tiered ("+ {cost} — <effect>" or "{cost} — <effect>")
    let is_spree_bullets = bullets.iter().all(|b| {
        let (bt, _) = strip_bullet_marker(b.text);
        parse_bullet_cost_prefix(bt, true).is_some()
    });
    let is_tiered_bullets = !is_spree_bullets
        && bullets.iter().all(|b| {
            let (bt, _) = strip_bullet_marker(b.text);
            parse_bullet_cost_prefix(bt, false).is_some_and(|(c, _)| count_pawprints(c) == 0)
        });

    if is_spree_bullets || is_tiered_bullets {
        let mut modes = Vec::with_capacity(bullets.len());
        let mut per_mode_costs = Vec::with_capacity(bullets.len());
        let mut unparsed = Vec::new();
        for b in bullets {
            let (bt, skip) = strip_bullet_marker(b.text);
            let (cost_s, eff_s) = parse_bullet_cost_prefix(bt, is_spree_bullets)?;
            let c_parse = crate::parser::cost::parse_cost_list(cost_s, b.span.start + skip, ctx);
            if c_parse.defs.is_empty() || !c_parse.unparsed.is_empty() {
                unparsed.push(b.span);
            }
            per_mode_costs.push(c_parse.defs);
            let eff_offset = b.span.start + skip + (bt.len() - eff_s.len()) as u32;
            let eff_res =
                parse_effects_inner(eff_s, eff_offset, context, trigger, ctx, quoted_compiler);
            if !eff_res.unparsed.is_empty() || eff_res.steps.is_empty() {
                unparsed.extend(eff_res.unparsed);
                if eff_res.steps.is_empty() {
                    unparsed.push(b.span);
                }
            }
            modes.push(ModalMode {
                targets: eff_res.targets,
                effect: eff_res.steps,
                span: b.span,
            });
        }
        let max = if is_spree_bullets {
            modes.len() as u16
        } else {
            1
        };
        return Some(EffectParse {
            steps: Vec::new(),
            targets: Vec::new(),
            modal: Some(ModalDef {
                min: 1,
                max,
                allow_repeat: false,
                once_per_turn_unique: false,
                up_to: is_spree_bullets,
                conditional_choose_all: None,
                modes,
                per_mode_costs,
                unchosen_permanent: false,
                opponent_chooses: None,
                pawprint_budget: None,
                pawprint_costs: Vec::new(),
                dynamic_max: None,
                random_mode: false,
                prefix_effect: Vec::new(),
                suffix_effect: Vec::new(),
                conditional_choose_range: None,
                conditional_not_random: None,
                different_player_targets_per_mode: false,
            }),
            unparsed,
        });
    }

    // 2. Pawprint ("Choose up to five {P} worth of modes...")
    let h_low = h_trim.to_ascii_lowercase();
    if h_low.contains("{p}") || h_low.contains("worth of modes") {
        let mut budget = 5u16;
        if let Some(up_pos) = find_word_ci(h_trim, "choose up to ") {
            let after = &h_trim[up_pos + "choose up to ".len()..];
            let nw = after.split_whitespace().next().unwrap_or("");
            if let Some(n) = parse_small_number(nw) {
                budget = n.max(1) as u16;
            }
        }
        let mut modes = Vec::with_capacity(bullets.len());
        let mut pawprint_costs = Vec::with_capacity(bullets.len());
        let mut unparsed = Vec::new();
        for b in bullets {
            let (bt, skip) = strip_bullet_marker(b.text);
            let (cost_s, eff_s) = parse_bullet_cost_prefix(bt, false)?;
            let pp = count_pawprints(cost_s);
            if pp == 0 {
                return None;
            }
            pawprint_costs.push(pp);
            let eff_offset = b.span.start + skip + (bt.len() - eff_s.len()) as u32;
            let eff_res =
                parse_effects_inner(eff_s, eff_offset, context, trigger, ctx, quoted_compiler);
            unparsed.extend(eff_res.unparsed);
            modes.push(ModalMode {
                targets: eff_res.targets,
                effect: eff_res.steps,
                span: b.span,
            });
        }
        return Some(EffectParse {
            steps: Vec::new(),
            targets: Vec::new(),
            modal: Some(ModalDef {
                min: 0,
                max: bullets.len() as u16,
                allow_repeat: true,
                once_per_turn_unique: false,
                up_to: true,
                conditional_choose_all: None,
                modes,
                per_mode_costs: Vec::new(),
                unchosen_permanent: false,
                opponent_chooses: None,
                pawprint_budget: Some(budget),
                pawprint_costs,
                dynamic_max: None,
                random_mode: false,
                prefix_effect: Vec::new(),
                suffix_effect: Vec::new(),
                conditional_choose_range: None,
                conditional_not_random: None,
                different_player_targets_per_mode: false,
            }),
            unparsed,
        });
    }

    // 3. Expanded header variants: conditional choose-all / conditional range / dynamic X / random / opponent chooses
    let mut cond_all: Option<Box<Condition>> = None;
    let mut cond_range: Option<ConditionalModalRange> = None;
    let mut dynamic_max: Option<Box<Amount>> = None;
    let mut random_mode = false;
    let mut opponent_chooses: Option<OpponentChoosesModal> = None;
    let mut matched_expanded = false;

    if h_low.contains("at random") {
        random_mode = true;
        matched_expanded = true;
    }
    if h_low.starts_with("target opponent chooses") {
        opponent_chooses = Some(OpponentChoosesModal::TargetOpponent);
        matched_expanded = true;
    } else if h_low.starts_with("an opponent chooses") {
        opponent_chooses = Some(OpponentChoosesModal::Opponent);
        matched_expanded = true;
    }
    if h_low.contains("choose x") || h_low.contains("choose up to x") {
        dynamic_max = Some(Box::new(Amount::X));
        matched_expanded = true;
    }
    if let Some(if_pos) = find_word_ci(h_trim, ". if ") {
        let cond_tail = &h_trim[if_pos + 2..];
        if let Some((c_part_raw, act_part)) = split_at_top_level_comma(cond_tail) {
            let c_part = strip_suffix_word_ci(c_part_raw.trim(), "as you cast this spell")
                .or_else(|| strip_suffix_word_ci(c_part_raw.trim(), "as you activate this ability"))
                .unwrap_or(c_part_raw.trim());
            let mut st = ParserState::new(context, trigger, quoted_compiler);
            if let Some(cond) = parse_condition_str(c_part, ctx, &mut st) {
                let act_low = act_part.to_ascii_lowercase();
                if act_low.contains("choose all")
                    || act_low.contains("choose both")
                    || act_low.contains("choose any number")
                    || act_low.contains("choose one or more")
                {
                    cond_all = Some(Box::new(cond));
                    matched_expanded = true;
                } else if act_low.contains("choose two") {
                    cond_range = Some(ConditionalModalRange {
                        condition: Box::new(cond),
                        min: 2,
                        max: 2,
                    });
                    matched_expanded = true;
                } else if act_low.contains("choose up to two") {
                    cond_range = Some(ConditionalModalRange {
                        condition: Box::new(cond),
                        min: 0,
                        max: 2,
                    });
                    matched_expanded = true;
                }
            }
        }
    }

    if !matched_expanded {
        return None;
    }

    let (min, max, allow_repeat, once_per_turn_unique, up_to) =
        parse_modal_header_bounds(h_trim, bullets.len()).unwrap_or((1, 1, false, false, false));

    let mut modes = Vec::with_capacity(bullets.len());
    let mut unparsed = Vec::new();
    for b in bullets {
        let (b_text, skip) = strip_bullet_marker(b.text);
        let b_clean = crate::parser::strip_leading_ability_word(b_text);
        let flavor_skip = (b_text.len() - b_clean.len()) as u32;
        let res = parse_effects_inner(
            b_clean,
            b.span.start + skip + flavor_skip,
            context,
            trigger,
            ctx,
            quoted_compiler,
        );
        if !res.unparsed.is_empty() || res.steps.is_empty() {
            unparsed.extend(res.unparsed);
            if res.steps.is_empty() {
                unparsed.push(b.span);
            }
        }
        modes.push(ModalMode {
            targets: res.targets,
            effect: res.steps,
            span: b.span,
        });
    }

    if unparsed.is_empty() && modes.is_empty() {
        return None;
    }
    let _ = header_start;

    Some(EffectParse {
        steps: Vec::new(),
        targets: Vec::new(),
        modal: Some(ModalDef {
            min,
            max,
            allow_repeat,
            once_per_turn_unique,
            up_to,
            conditional_choose_all: cond_all,
            modes,
            per_mode_costs: Vec::new(),
            unchosen_permanent: false,
            opponent_chooses,
            pawprint_budget: None,
            pawprint_costs: Vec::new(),
            dynamic_max,
            random_mode,
            prefix_effect: Vec::new(),
            suffix_effect: Vec::new(),
            conditional_choose_range: cond_range,
            conditional_not_random: None,
            different_player_targets_per_mode: false,
        }),
        unparsed,
    })
}

fn parse_spell_face_inner(
    lines: &[NormalizedLine],
    ctx: &mut ParseCtx<'_>,
    quoted_compiler: &dyn QuotedAbilityCompiler,
) -> EffectParse {
    if lines.is_empty() {
        return EffectParse::default();
    }

    // Check for modal block among lines (bullet lines starting with "•")
    if let Some(first_bullet_idx) = lines
        .iter()
        .position(|l| l.text.trim_start().starts_with('•'))
        && first_bullet_idx > 0
    {
        let header_line = &lines[first_bullet_idx - 1];
        let mut end_bullet_idx = first_bullet_idx;
        while end_bullet_idx < lines.len()
            && lines[end_bullet_idx].text.trim_start().starts_with('•')
        {
            end_bullet_idx += 1;
        }
        let bullets: Vec<ModalBullet<'_>> = lines[first_bullet_idx..end_bullet_idx]
            .iter()
            .map(|l| ModalBullet {
                text: &l.text,
                span: l.span,
            })
            .collect();
        let modal_res = parse_modal_inner(
            &header_line.text,
            &bullets,
            AbilityContext::Spell,
            header_line.span.start,
            None,
            ctx,
            quoted_compiler,
        );
        if modal_res.modal.is_some() {
            return modal_res;
        }
    }

    // Standard non-modal spell: parse each line in sequence sharing ParserState so "that creature" / "if you do" work across lines!
    let mut state = ParserState::new(AbilityContext::Spell, None, quoted_compiler);
    let mut all_sentences = Vec::new();
    for line in lines {
        let trimmed = line.body.trim();
        if trimmed.is_empty() {
            continue;
        }
        let raw_sents = split_sentences(trimmed, line.body_span.start);
        all_sentences.extend(split_quoted_sentence_endings(&raw_sents));
    }
    parse_sentences_into(&all_sentences, ctx, &mut state);

    if !state.steps.is_empty() {
        prune_unused_bindings(&mut state.steps);
    }

    EffectParse {
        steps: state.steps,
        targets: state.targets,
        modal: None,
        unparsed: state.unparsed,
    }
}

fn collect_ref_bindings(r: &Ref, used: &mut std::collections::HashSet<String>) {
    if let Ref::Binding { name } = r {
        used.insert(name.clone());
    }
}

fn collect_player_ref_bindings(p: &PlayerRef, used: &mut std::collections::HashSet<String>) {
    match p {
        PlayerRef::ControllerOf { of } | PlayerRef::OwnerOf { of } => {
            collect_ref_bindings(of, used);
        }
        _ => {}
    }
}

fn collect_filter_bindings(f: &ObjectFilter, used: &mut std::collections::HashSet<String>) {
    if let Some(ref c) = f.mana_value {
        collect_amount_bindings(&c.value, used);
    }
    if let Some(ref c) = f.power {
        collect_amount_bindings(&c.value, used);
    }
    if let Some(ref c) = f.toughness {
        collect_amount_bindings(&c.value, used);
    }
    for p in &f.extra {
        match p {
            ObjectPredicate::SharesCardTypeWithBinding { binding } => {
                used.insert(binding.clone());
            }
            ObjectPredicate::PowerOrToughness { cmp }
            | ObjectPredicate::BasePowerOrToughness { cmp } => {
                collect_amount_bindings(&cmp.value, used);
            }
            ObjectPredicate::ControllerRef { player } | ObjectPredicate::OwnerRef { player } => {
                collect_player_ref_bindings(player, used);
            }
            ObjectPredicate::AnyOf { filters } => {
                for sub in filters {
                    collect_filter_bindings(sub, used);
                }
            }
            _ => {}
        }
    }
}

fn collect_selector_bindings(sel: &Selector, used: &mut std::collections::HashSet<String>) {
    match sel {
        Selector::Binding { name } => {
            used.insert(name.clone());
        }
        Selector::All { filter } => collect_filter_bindings(filter, used),
        Selector::PlayerRef { player } => collect_player_ref_bindings(player, used),
        Selector::LibraryTop { player: Some(p) } => collect_player_ref_bindings(p, used),
        _ => {}
    }
}

fn collect_amount_bindings(amt: &Amount, used: &mut std::collections::HashSet<String>) {
    match amt {
        Amount::ResultCount { of: Some(name) } => {
            used.insert(name.clone());
        }
        Amount::Stat { of, .. }
        | Amount::CountersOn { of, .. }
        | Amount::LkiTotalCounters { of }
        | Amount::DistinctCounterKindsOn { of } => {
            collect_ref_bindings(of, used);
        }
        Amount::Count { of }
        | Amount::TotalCountersAmong { filter: of }
        | Amount::CountersAmong { filter: of, .. }
        | Amount::CountersAmongControlled { filter: of, .. } => collect_filter_bindings(of, used),
        Amount::CardsIn { of, .. }
        | Amount::Life { of }
        | Amount::EnergyCount { player: of }
        | Amount::PlayerCounters { player: of, .. }
        | Amount::PlayerCounterDifference { player: of, .. }
        | Amount::Devotion {
            player: Some(of), ..
        } => collect_player_ref_bindings(of, used),
        Amount::Conditional {
            condition,
            then_amt,
            else_amt,
        } => {
            collect_condition_bindings(condition, used);
            collect_amount_bindings(then_amt, used);
            collect_amount_bindings(else_amt, used);
        }
        Amount::Difference { left, right } => {
            collect_amount_bindings(left, used);
            collect_amount_bindings(right, used);
        }
        Amount::Sum { args } | Amount::Min { args } | Amount::Max { args } => {
            for a in args {
                collect_amount_bindings(a, used);
            }
        }
        Amount::Negate { of } | Amount::Mul { of, .. } | Amount::Half { of, .. } => {
            collect_amount_bindings(of, used);
        }
        _ => {}
    }
}

fn collect_condition_bindings(cond: &Condition, used: &mut std::collections::HashSet<String>) {
    match cond {
        Condition::Compare { left, right, .. } => {
            collect_amount_bindings(left, used);
            collect_amount_bindings(right, used);
        }
        Condition::And { of } | Condition::Or { of } => {
            for c in of {
                collect_condition_bindings(c, used);
            }
        }
        Condition::Not { of } => collect_condition_bindings(of, used),
        Condition::MatchesFilter { target, filter, .. } => {
            if let Some(r) = target {
                collect_ref_bindings(r, used);
            }
            collect_filter_bindings(filter, used);
        }
        Condition::DiedThisWay { of: Some(r) } => collect_ref_bindings(r, used),
        _ => {}
    }
}

fn collect_steps_bindings(steps: &[EffectStep], used: &mut std::collections::HashSet<String>) {
    for step in steps {
        collect_selector_bindings(&step.subject, used);
        if let Some(ref p) = step.actor {
            collect_player_ref_bindings(p, used);
        }
        if let Some(ref amt) = step.amount {
            collect_amount_bindings(amt, used);
        }
        if let Some(ref opt) = step.optional {
            collect_player_ref_bindings(&opt.chooser, used);
        }
        if let Some(ref gate) = step.gate {
            match gate {
                StepGate::Condition { condition } => collect_condition_bindings(condition, used),
                StepGate::Combined {
                    condition: Some(c), ..
                } => collect_condition_bindings(c, used),
                _ => {}
            }
        }
        if let Some(ref rt) = step.reflexive_trigger {
            collect_steps_bindings(&rt.effect, used);
            if let Some(ref m) = rt.modal {
                collect_steps_bindings(&m.prefix_effect, used);
                collect_steps_bindings(&m.suffix_effect, used);
                for mode in &m.modes {
                    collect_steps_bindings(&mode.effect, used);
                }
            }
        }
        match &step.op {
            EffectOp::Damage {
                source: Some(s), ..
            } => collect_selector_bindings(s, used),
            EffectOp::Move {
                attached_to,
                condition,
                ..
            } => {
                if let Some(sel) = attached_to {
                    collect_selector_bindings(sel, used);
                }
                if let Some(cond) = condition {
                    collect_condition_bindings(cond, used);
                }
            }
            EffectOp::MoveCounters { spec: Some(sp), .. } => {
                collect_selector_bindings(&sp.from, used);
            }
            EffectOp::Exchange { spec } => {
                if let Some(sel) = &spec.second {
                    collect_selector_bindings(sel, used);
                }
            }
            EffectOp::Fight { with, .. } => collect_selector_bindings(with, used),
            EffectOp::Attach {
                attach_object: Some(sel),
                ..
            } => collect_selector_bindings(sel, used),
            EffectOp::BecomeCopy { copy_source, .. } => {
                collect_selector_bindings(copy_source, used);
            }
            EffectOp::CastNameLock { name_ref, .. } => collect_ref_bindings(name_ref, used),
            EffectOp::Connive {
                for_each_convoking_creature_steps,
            } => collect_steps_bindings(for_each_convoking_creature_steps, used),
            EffectOp::FlipCoin {
                win_effect,
                lose_effect,
                ..
            } => {
                collect_steps_bindings(win_effect, used);
                collect_steps_bindings(lose_effect, used);
            }
            EffectOp::RollDie { table, .. } => {
                for b in table {
                    collect_steps_bindings(&b.effect, used);
                }
            }
            EffectOp::VillainousChoice { options, .. } => {
                for opt in options {
                    collect_steps_bindings(opt, used);
                }
            }
            EffectOp::Vote { spec } => {
                for s in &spec.per_option_effect {
                    collect_steps_bindings(s, used);
                }
                for s in &spec.per_winning_effect {
                    collect_steps_bindings(s, used);
                }
            }
            EffectOp::DelayedTrigger {
                delayed: Some(d), ..
            } => collect_steps_bindings(&d.effect, used),
            EffectOp::ForEachPlayerLoop { steps, .. } | EffectOp::RepeatSequence { steps, .. } => {
                collect_steps_bindings(steps, used);
            }
            EffectOp::PunisherChoice { spec } => {
                collect_steps_bindings(&spec.default_steps, used);
                collect_steps_bindings(&spec.unless_effect, used);
                for c in &spec.unless_cost {
                    if let mtg_ir::CostDef::Sacrifice {
                        target: mtg_ir::CostObjectTarget::Filter { filter },
                        ..
                    } = c
                    {
                        collect_filter_bindings(filter, used);
                    }
                }
            }
            EffectOp::ConditionalSequence {
                condition,
                then_steps,
                else_steps,
            } => {
                collect_condition_bindings(condition, used);
                collect_steps_bindings(then_steps, used);
                collect_steps_bindings(else_steps, used);
            }
            EffectOp::GrantPlayer {
                next_main_phase_add_mana: Some((_, amt)),
                ..
            } => {
                collect_amount_bindings(amt, used);
            }
            _ => {}
        }
    }
}

fn clear_unused_bindings_in_steps(
    steps: &mut [EffectStep],
    used: &std::collections::HashSet<String>,
) {
    for step in steps.iter_mut() {
        if let Some(ref b) = step.bind_as
            && !used.contains(b)
        {
            step.bind_as = None;
        }
        if let Some(ref mut rt) = step.reflexive_trigger {
            clear_unused_bindings_in_steps(&mut rt.effect, used);
            if let Some(ref mut m) = rt.modal {
                clear_unused_bindings_in_steps(&mut m.prefix_effect, used);
                clear_unused_bindings_in_steps(&mut m.suffix_effect, used);
                for mode in &mut m.modes {
                    clear_unused_bindings_in_steps(&mut mode.effect, used);
                }
            }
        }
        match &mut step.op {
            EffectOp::Connive {
                for_each_convoking_creature_steps,
            } => clear_unused_bindings_in_steps(for_each_convoking_creature_steps, used),
            EffectOp::FlipCoin {
                win_effect,
                lose_effect,
                ..
            } => {
                clear_unused_bindings_in_steps(win_effect, used);
                clear_unused_bindings_in_steps(lose_effect, used);
            }
            EffectOp::RollDie { table, .. } => {
                for b in table {
                    clear_unused_bindings_in_steps(&mut b.effect, used);
                }
            }
            EffectOp::VillainousChoice { options, .. } => {
                for opt in options {
                    clear_unused_bindings_in_steps(opt, used);
                }
            }
            EffectOp::Vote { spec } => {
                for s in &mut spec.per_option_effect {
                    clear_unused_bindings_in_steps(s, used);
                }
                for s in &mut spec.per_winning_effect {
                    clear_unused_bindings_in_steps(s, used);
                }
            }
            EffectOp::DelayedTrigger {
                delayed: Some(d), ..
            } => clear_unused_bindings_in_steps(&mut d.effect, used),
            EffectOp::ForEachPlayerLoop { steps, .. } | EffectOp::RepeatSequence { steps, .. } => {
                clear_unused_bindings_in_steps(steps, used);
            }
            EffectOp::PunisherChoice { spec } => {
                clear_unused_bindings_in_steps(&mut spec.default_steps, used);
                clear_unused_bindings_in_steps(&mut spec.unless_effect, used);
            }
            EffectOp::ConditionalSequence {
                then_steps,
                else_steps,
                ..
            } => {
                clear_unused_bindings_in_steps(then_steps, used);
                clear_unused_bindings_in_steps(else_steps, used);
            }
            _ => {}
        }
    }
}

fn rename_ref_bindings(r: &mut Ref, map: &HashMap<String, String>) {
    if let Ref::Binding { name } = r
        && let Some(new_name) = map.get(name)
    {
        *name = new_name.clone();
    }
}

fn rename_player_ref_bindings(p: &mut PlayerRef, map: &HashMap<String, String>) {
    match p {
        PlayerRef::ControllerOf { of } | PlayerRef::OwnerOf { of } => {
            rename_ref_bindings(of, map);
        }
        _ => {}
    }
}

fn rename_filter_bindings(f: &mut ObjectFilter, map: &HashMap<String, String>) {
    if let Some(ref mut c) = f.mana_value {
        rename_amount_bindings(&mut c.value, map);
    }
    if let Some(ref mut c) = f.power {
        rename_amount_bindings(&mut c.value, map);
    }
    if let Some(ref mut c) = f.toughness {
        rename_amount_bindings(&mut c.value, map);
    }
    for p in &mut f.extra {
        match p {
            ObjectPredicate::SharesCardTypeWithBinding { binding } => {
                if let Some(new_name) = map.get(binding) {
                    *binding = new_name.clone();
                }
            }
            ObjectPredicate::PowerOrToughness { cmp }
            | ObjectPredicate::BasePowerOrToughness { cmp } => {
                rename_amount_bindings(&mut cmp.value, map);
            }
            ObjectPredicate::ControllerRef { player } | ObjectPredicate::OwnerRef { player } => {
                rename_player_ref_bindings(player, map);
            }
            ObjectPredicate::AnyOf { filters } => {
                for sub in filters {
                    rename_filter_bindings(sub, map);
                }
            }
            _ => {}
        }
    }
}

fn rename_selector_bindings(sel: &mut Selector, map: &HashMap<String, String>) {
    match sel {
        Selector::Binding { name } => {
            if let Some(new_name) = map.get(name) {
                *name = new_name.clone();
            }
        }
        Selector::All { filter } => rename_filter_bindings(filter, map),
        Selector::PlayerRef { player } => rename_player_ref_bindings(player, map),
        Selector::LibraryTop { player: Some(p) } => rename_player_ref_bindings(p, map),
        _ => {}
    }
}

fn rename_amount_bindings(amt: &mut Amount, map: &HashMap<String, String>) {
    match amt {
        Amount::ResultCount { of: Some(name) } => {
            if let Some(new_name) = map.get(name) {
                *name = new_name.clone();
            }
        }
        Amount::Stat { of, .. }
        | Amount::CountersOn { of, .. }
        | Amount::LkiTotalCounters { of }
        | Amount::DistinctCounterKindsOn { of } => rename_ref_bindings(of, map),
        Amount::Count { of }
        | Amount::TotalCountersAmong { filter: of }
        | Amount::CountersAmong { filter: of, .. }
        | Amount::CountersAmongControlled { filter: of, .. } => rename_filter_bindings(of, map),
        Amount::CardsIn { of, .. }
        | Amount::Life { of }
        | Amount::EnergyCount { player: of }
        | Amount::PlayerCounters { player: of, .. }
        | Amount::PlayerCounterDifference { player: of, .. }
        | Amount::Devotion {
            player: Some(of), ..
        } => rename_player_ref_bindings(of, map),
        Amount::Conditional {
            condition,
            then_amt,
            else_amt,
        } => {
            rename_condition_bindings(condition, map);
            rename_amount_bindings(then_amt, map);
            rename_amount_bindings(else_amt, map);
        }
        Amount::Difference { left, right } => {
            rename_amount_bindings(left, map);
            rename_amount_bindings(right, map);
        }
        Amount::Sum { args } | Amount::Min { args } | Amount::Max { args } => {
            for a in args {
                rename_amount_bindings(a, map);
            }
        }
        Amount::Negate { of } | Amount::Mul { of, .. } | Amount::Half { of, .. } => {
            rename_amount_bindings(of, map);
        }
        _ => {}
    }
}

fn rename_condition_bindings(cond: &mut Condition, map: &HashMap<String, String>) {
    match cond {
        Condition::Compare { left, right, .. } => {
            rename_amount_bindings(left, map);
            rename_amount_bindings(right, map);
        }
        Condition::And { of } | Condition::Or { of } => {
            for c in of {
                rename_condition_bindings(c, map);
            }
        }
        Condition::Not { of } => rename_condition_bindings(of, map),
        Condition::MatchesFilter { target, filter, .. } => {
            if let Some(r) = target {
                rename_ref_bindings(r, map);
            }
            rename_filter_bindings(filter, map);
        }
        Condition::DiedThisWay { of: Some(r) } => rename_ref_bindings(r, map),
        _ => {}
    }
}

fn collect_sequential_binding_renames(
    steps: &mut [EffectStep],
    next_id: &mut usize,
    map: &mut HashMap<String, String>,
) {
    for step in steps.iter_mut() {
        if let Some(ref mut b) = step.bind_as {
            let new_name = if let Some(existing) = map.get(b.as_str()) {
                existing.clone()
            } else {
                let n = format!("b{}", *next_id);
                *next_id += 1;
                map.insert(b.clone(), n.clone());
                n
            };
            *b = new_name;
        }
        if let Some(ref mut rt) = step.reflexive_trigger {
            collect_sequential_binding_renames(&mut rt.effect, next_id, map);
            if let Some(ref mut m) = rt.modal {
                collect_sequential_binding_renames(&mut m.prefix_effect, next_id, map);
                collect_sequential_binding_renames(&mut m.suffix_effect, next_id, map);
                for mode in &mut m.modes {
                    collect_sequential_binding_renames(&mut mode.effect, next_id, map);
                }
            }
        }
        match &mut step.op {
            EffectOp::Connive {
                for_each_convoking_creature_steps,
            } => {
                collect_sequential_binding_renames(for_each_convoking_creature_steps, next_id, map)
            }
            EffectOp::FlipCoin {
                win_effect,
                lose_effect,
                ..
            } => {
                collect_sequential_binding_renames(win_effect, next_id, map);
                collect_sequential_binding_renames(lose_effect, next_id, map);
            }
            EffectOp::RollDie { table, .. } => {
                for b in table {
                    collect_sequential_binding_renames(&mut b.effect, next_id, map);
                }
            }
            EffectOp::VillainousChoice { options, .. } => {
                for opt in options {
                    collect_sequential_binding_renames(opt, next_id, map);
                }
            }
            EffectOp::Vote { spec } => {
                for s in &mut spec.per_option_effect {
                    collect_sequential_binding_renames(s, next_id, map);
                }
                for s in &mut spec.per_winning_effect {
                    collect_sequential_binding_renames(s, next_id, map);
                }
            }
            EffectOp::DelayedTrigger {
                delayed: Some(d), ..
            } => collect_sequential_binding_renames(&mut d.effect, next_id, map),
            EffectOp::ForEachPlayerLoop { steps, .. } | EffectOp::RepeatSequence { steps, .. } => {
                collect_sequential_binding_renames(steps, next_id, map);
            }
            EffectOp::PunisherChoice { spec } => {
                collect_sequential_binding_renames(&mut spec.default_steps, next_id, map);
                collect_sequential_binding_renames(&mut spec.unless_effect, next_id, map);
            }
            EffectOp::ConditionalSequence {
                then_steps,
                else_steps,
                ..
            } => {
                collect_sequential_binding_renames(then_steps, next_id, map);
                collect_sequential_binding_renames(else_steps, next_id, map);
            }
            _ => {}
        }
    }
}

fn rename_bindings_in_steps(steps: &mut [EffectStep], map: &HashMap<String, String>) {
    for step in steps.iter_mut() {
        rename_selector_bindings(&mut step.subject, map);
        if let Some(ref mut p) = step.actor {
            rename_player_ref_bindings(p, map);
        }
        if let Some(ref mut amt) = step.amount {
            rename_amount_bindings(amt, map);
        }
        if let Some(ref mut opt) = step.optional {
            rename_player_ref_bindings(&mut opt.chooser, map);
        }
        if let Some(ref mut gate) = step.gate {
            match gate {
                StepGate::Condition { condition } => rename_condition_bindings(condition, map),
                StepGate::Combined {
                    condition: Some(c), ..
                } => rename_condition_bindings(c, map),
                _ => {}
            }
        }
        if let Some(ref mut rt) = step.reflexive_trigger {
            rename_bindings_in_steps(&mut rt.effect, map);
            if let Some(ref mut m) = rt.modal {
                rename_bindings_in_steps(&mut m.prefix_effect, map);
                rename_bindings_in_steps(&mut m.suffix_effect, map);
                for mode in &mut m.modes {
                    rename_bindings_in_steps(&mut mode.effect, map);
                }
            }
        }
        match &mut step.op {
            EffectOp::Damage {
                source: Some(s), ..
            } => rename_selector_bindings(s, map),
            EffectOp::Move {
                attached_to,
                condition,
                ..
            } => {
                if let Some(sel) = attached_to {
                    rename_selector_bindings(sel, map);
                }
                if let Some(cond) = condition {
                    rename_condition_bindings(cond, map);
                }
            }
            EffectOp::MoveCounters { spec: Some(sp), .. } => {
                rename_selector_bindings(&mut sp.from, map);
            }
            EffectOp::Exchange { spec } => {
                if let Some(sel) = &mut spec.second {
                    rename_selector_bindings(sel, map);
                }
            }
            EffectOp::Fight { with, .. } => rename_selector_bindings(with, map),
            EffectOp::Attach {
                attach_object: Some(sel),
                ..
            } => rename_selector_bindings(sel, map),
            EffectOp::BecomeCopy { copy_source, .. } => {
                rename_selector_bindings(copy_source, map);
            }
            EffectOp::CastNameLock { name_ref, .. } => rename_ref_bindings(name_ref, map),
            EffectOp::Connive {
                for_each_convoking_creature_steps,
            } => rename_bindings_in_steps(for_each_convoking_creature_steps, map),
            EffectOp::FlipCoin {
                win_effect,
                lose_effect,
                ..
            } => {
                rename_bindings_in_steps(win_effect, map);
                rename_bindings_in_steps(lose_effect, map);
            }
            EffectOp::RollDie { table, .. } => {
                for b in table {
                    rename_bindings_in_steps(&mut b.effect, map);
                }
            }
            EffectOp::VillainousChoice { options, .. } => {
                for opt in options {
                    rename_bindings_in_steps(opt, map);
                }
            }
            EffectOp::Vote { spec } => {
                for s in &mut spec.per_option_effect {
                    rename_bindings_in_steps(s, map);
                }
                for s in &mut spec.per_winning_effect {
                    rename_bindings_in_steps(s, map);
                }
            }
            EffectOp::DelayedTrigger {
                delayed: Some(d), ..
            } => rename_bindings_in_steps(&mut d.effect, map),
            EffectOp::ForEachPlayerLoop { steps, .. } | EffectOp::RepeatSequence { steps, .. } => {
                rename_bindings_in_steps(steps, map);
            }
            EffectOp::PunisherChoice { spec } => {
                rename_bindings_in_steps(&mut spec.default_steps, map);
                rename_bindings_in_steps(&mut spec.unless_effect, map);
                for c in &mut spec.unless_cost {
                    if let mtg_ir::CostDef::Sacrifice {
                        target: mtg_ir::CostObjectTarget::Filter { filter },
                        ..
                    } = c
                    {
                        rename_filter_bindings(filter, map);
                    }
                }
            }
            EffectOp::ConditionalSequence {
                condition,
                then_steps,
                else_steps,
            } => {
                rename_condition_bindings(condition, map);
                rename_bindings_in_steps(then_steps, map);
                rename_bindings_in_steps(else_steps, map);
            }
            EffectOp::GrantPlayer {
                next_main_phase_add_mana: Some((_, amt)),
                ..
            } => {
                rename_amount_bindings(amt, map);
            }
            _ => {}
        }
    }
}

fn has_any_binding(steps: &[EffectStep]) -> bool {
    for step in steps {
        if step.bind_as.is_some() {
            return true;
        }
        if let Some(ref rt) = step.reflexive_trigger {
            if has_any_binding(&rt.effect) {
                return true;
            }
            if let Some(ref m) = rt.modal
                && (has_any_binding(&m.prefix_effect)
                    || has_any_binding(&m.suffix_effect)
                    || m.modes.iter().any(|md| has_any_binding(&md.effect)))
            {
                return true;
            }
        }
        let nested = match &step.op {
            EffectOp::Connive {
                for_each_convoking_creature_steps,
            } => has_any_binding(for_each_convoking_creature_steps),
            EffectOp::FlipCoin {
                win_effect,
                lose_effect,
                ..
            } => has_any_binding(win_effect) || has_any_binding(lose_effect),
            EffectOp::RollDie { table, .. } => table.iter().any(|b| has_any_binding(&b.effect)),
            EffectOp::VillainousChoice { options, .. } => {
                options.iter().any(|o| has_any_binding(o))
            }
            EffectOp::Vote { spec } => {
                spec.per_option_effect.iter().any(|s| has_any_binding(s))
                    || spec.per_winning_effect.iter().any(|s| has_any_binding(s))
            }
            EffectOp::DelayedTrigger {
                delayed: Some(d), ..
            } => has_any_binding(&d.effect),
            EffectOp::ForEachPlayerLoop { steps, .. } | EffectOp::RepeatSequence { steps, .. } => {
                has_any_binding(steps)
            }
            EffectOp::PunisherChoice { spec } => {
                has_any_binding(&spec.default_steps) || has_any_binding(&spec.unless_effect)
            }
            EffectOp::ConditionalSequence {
                then_steps,
                else_steps,
                ..
            } => has_any_binding(then_steps) || has_any_binding(else_steps),
            _ => false,
        };
        if nested {
            return true;
        }
    }
    false
}

fn prune_unused_bindings(steps: &mut [EffectStep]) {
    if !has_any_binding(steps) {
        return;
    }
    let mut used = std::collections::HashSet::new();
    collect_steps_bindings(steps, &mut used);
    clear_unused_bindings_in_steps(steps, &used);
    let mut next_id = 0usize;
    let mut map = HashMap::new();
    collect_sequential_binding_renames(steps, &mut next_id, &mut map);
    map.retain(|k, v| k != v);
    if !map.is_empty() {
        rename_bindings_in_steps(steps, &map);
    }
}

// ============================================================================
// Section 9: Interpretability, Mana Completeness & Target Extraction
// ============================================================================

fn selector_supported(sel: &Selector) -> bool {
    matches!(
        sel,
        Selector::SelfObj
            | Selector::Binding { .. }
            | Selector::Target { .. }
            | Selector::All { .. }
            | Selector::Player { .. }
            | Selector::PlayerRef { .. }
            | Selector::LibraryTop { .. }
            | Selector::None
            | Selector::EventObject
            | Selector::AttachedTo
    )
}

fn step_produces_decision(step: &EffectStep) -> bool {
    if step.optional.is_some() {
        return true;
    }
    match &step.op {
        EffectOp::RevealAndDiscard { spec, .. } => spec.is_some(),
        EffectOp::Clash
        | EffectOp::FlipCoin { .. }
        | EffectOp::CollectEvidence
        | EffectOp::Forage
        | EffectOp::Blight
        | EffectOp::Discover
        | EffectOp::CastFree { .. }
        | EffectOp::Sacrifice { .. }
        | EffectOp::Discard { .. }
        | EffectOp::RemoveCounters { .. }
        | EffectOp::ExileUntil { .. }
        | EffectOp::ForEachPlayerLoop { .. }
        | EffectOp::PunisherChoice { .. }
        | EffectOp::Destroy { .. }
        | EffectOp::BecomeCopy { .. }
        | EffectOp::CounterSpell { .. }
        | EffectOp::Search { .. }
        | EffectOp::Draw { .. }
        | EffectOp::Proliferate
        | EffectOp::Reveal { .. } => true,
        EffectOp::Move {
            from, to, select, ..
        } => (*from == Some(Zone::Hand) && *to == Some(Zone::Battlefield) && select.up_to) || true,
        EffectOp::Dig { spec, .. } => spec.up_to || spec.keep_to == DigKeepTo::CastFree,
        EffectOp::MoveCounters { spec, .. } => spec.is_some(),
        EffectOp::Bounce { select }
        | EffectOp::Tap { select }
        | EffectOp::Untap { select }
        | EffectOp::PutCounters { select, .. } => select.choice_count.is_some() && select.up_to,
        EffectOp::Exile { select, .. } => {
            matches!(step.subject, Selector::Target { .. })
                || (select.choice_count.is_some() && select.up_to)
        }
        EffectOp::RedirectTargets { spec } => spec.mode == RedirectMode::ChooseNewTargets,
        EffectOp::Grant {
            pay_any_mana_for_damage,
            pay_up_to_life_gained_mana_to_draw,
            ..
        } => pay_any_mana_for_damage.is_some() || *pay_up_to_life_gained_mana_to_draw,
        EffectOp::ConditionalSequence {
            then_steps,
            else_steps,
            ..
        } => {
            then_steps.iter().any(step_produces_decision)
                || else_steps.iter().any(step_produces_decision)
        }
        _ => false,
    }
}

fn step_supported(step: &EffectStep) -> bool {
    if !selector_supported(&step.subject) {
        return false;
    }
    if let Some(ref opt) = step.optional
        && !opt.cost.is_empty()
        && !opt.cost.iter().all(is_supported_optional_cost)
    {
        return false;
    }
    if let Some(ref rt) = step.reflexive_trigger {
        if !trigger_targets_supported_impl(&rt.targets) {
            return false;
        }
        if let Some(ref m) = rt.modal {
            if !m.prefix_effect.is_empty() && !steps_supported(&m.prefix_effect) {
                return false;
            }
            if !m.suffix_effect.is_empty() && !steps_supported(&m.suffix_effect) {
                return false;
            }
        }
        let sub = EffectParse {
            steps: rt.effect.clone(),
            targets: rt.targets.clone(),
            modal: rt.modal.as_deref().cloned(),
            unparsed: Vec::new(),
        };
        if !statically_interpretable_impl(&sub, false) {
            return false;
        }
    }

    match &step.op {
        EffectOp::Attach {
            attach_object: Some(obj),
            ..
        } => selector_supported(obj),
        EffectOp::FlipCoin {
            win_effect,
            lose_effect,
            ..
        } => {
            (win_effect.is_empty() || steps_supported(win_effect))
                && (lose_effect.is_empty() || steps_supported(lose_effect))
        }
        EffectOp::RollDie { sides, table, .. } => {
            *sides >= 2 && (table.is_empty() || table.iter().all(|b| steps_supported(&b.effect)))
        }
        EffectOp::RetainMana { colors } => !colors.is_empty(),
        EffectOp::PayCost => step.optional.as_ref().is_some_and(|o| !o.cost.is_empty()),
        EffectOp::CumulativeUpkeep { cost, .. } => {
            !cost.is_empty() && cost.iter().all(is_supported_optional_cost)
        }
        EffectOp::AddMana { .. } => mana_step_complete_impl(step),
        EffectOp::MoveCounters {
            spec: Some(spec), ..
        } => selector_supported(&spec.from) && !matches!(step.subject, Selector::None),
        EffectOp::PutCounters {
            copy_counters_from: Some(src),
            ..
        } => selector_supported(src) && !matches!(step.subject, Selector::None),
        EffectOp::DelayedTrigger {
            delayed,
            inline_delayed,
            ..
        } => {
            let Some(d) = delayed else {
                return false;
            };
            if d.effect.is_empty() || !steps_supported(&d.effect) {
                return false;
            }
            if inline_delayed.is_some() {
                return true;
            }
            if d.trigger.event != EventKind::PhaseBegin {
                return false;
            }
            matches!(
                d.trigger.filter.detail,
                Some(EventDetail::Phase {
                    phase: Some(
                        GamePhase::EndStep
                            | GamePhase::Upkeep
                            | GamePhase::EndCombat
                            | GamePhase::BeginCombat
                            | GamePhase::Main1
                    ),
                    ..
                })
            )
        }
        EffectOp::ForEachPlayerLoop { steps, .. } => steps.is_empty() || steps_supported(steps),
        EffectOp::PunisherChoice { spec } => {
            (!spec.default_steps.is_empty() && steps_supported(&spec.default_steps))
                || (!spec.unless_effect.is_empty() && steps_supported(&spec.unless_effect))
                || !spec.unless_cost.is_empty()
        }
        EffectOp::RepeatSequence { steps, .. } => !steps.is_empty() && steps_supported(steps),
        EffectOp::ConditionalSequence {
            then_steps,
            else_steps,
            ..
        } => {
            !then_steps.is_empty()
                && steps_supported(then_steps)
                && (else_steps.is_empty() || steps_supported(else_steps))
        }
        _ => true,
    }
}

fn steps_supported(steps: &[EffectStep]) -> bool {
    if steps.is_empty() {
        return false;
    }
    for (i, s) in steps.iter().enumerate() {
        if !step_supported(s) {
            return false;
        }
        let check_idx = |idx: u16| -> bool {
            let u = idx as usize;
            u < i && step_produces_decision(&steps[u])
        };
        match &s.gate {
            Some(StepGate::IfPrecedingAccepted { step_index }) => {
                if !check_idx(*step_index) {
                    return false;
                }
            }
            Some(StepGate::IfPrecedingDeclined { step_index }) => {
                if !check_idx(*step_index) {
                    return false;
                }
            }
            Some(StepGate::Combined {
                if_preceding_accepted,
                if_preceding_declined,
                ..
            }) => {
                if let Some(a) = if_preceding_accepted
                    && !check_idx(*a)
                {
                    return false;
                }
                if let Some(d) = if_preceding_declined
                    && !check_idx(*d)
                {
                    return false;
                }
            }
            _ => {}
        }
    }
    true
}

fn statically_interpretable_impl(parse: &EffectParse, allow_optional_prefix: bool) -> bool {
    let _ = allow_optional_prefix;
    if !parse.unparsed.is_empty() {
        return false;
    }
    if let Some(ref m) = parse.modal {
        if !parse.steps.is_empty() {
            return parse.steps.iter().all(step_supported);
        }
        if m.modes.is_empty() || m.max < m.min {
            return false;
        }
        return m.modes.iter().all(|mode| {
            let sub = EffectParse {
                steps: mode.effect.clone(),
                targets: mode.targets.clone(),
                modal: None,
                unparsed: Vec::new(),
            };
            statically_interpretable_impl(&sub, allow_optional_prefix)
        });
    }
    if parse.steps.is_empty() {
        return false;
    }
    if parse.targets.len() > 1 && !parse.targets.iter().all(|t| t.max >= t.min && t.max >= 1) {
        return false;
    }
    steps_supported(&parse.steps)
}

fn trigger_targets_supported_impl(specs: &[TargetSpec]) -> bool {
    specs.iter().all(|sp| {
        if sp.kind == TargetKind::Player {
            return true;
        }
        let z = sp.filter.zones;
        z.is_empty()
            || z.intersects(
                ZoneMask::BATTLEFIELD | ZoneMask::GRAVEYARD | ZoneMask::STACK | ZoneMask::EXILE,
            )
    })
}

fn interpretable_trigger_impl(parse: &EffectParse) -> bool {
    if !trigger_targets_supported_impl(&parse.targets) {
        return false;
    }
    if let Some(ref m) = parse.modal {
        for mode in &m.modes {
            if !trigger_targets_supported_impl(&mode.targets) {
                return false;
            }
        }
    }
    statically_interpretable_impl(parse, true)
}

fn mana_step_complete_impl(step: &EffectStep) -> bool {
    match &step.op {
        EffectOp::AddMana { production, .. } => match production {
            ManaProduction::Fixed { symbols } => !symbols.is_empty(),
            ManaProduction::Choice { kind, colors } => {
                *kind != ManaChoiceKind::Colors || !colors.is_empty()
            }
            ManaProduction::Bundles { options } => {
                !options.is_empty() && options.iter().all(|b| !b.is_empty())
            }
            ManaProduction::Combination { any_color, colors } => *any_color || !colors.is_empty(),
            ManaProduction::OrChosenColor { colors } => !colors.is_empty(),
            ManaProduction::WithChosenColor { colors } => !colors.is_empty(),
            ManaProduction::FromExiledColors
            | ManaProduction::PerColorControlled
            | ManaProduction::LandProducedTypes
            | ManaProduction::ChosenColorAmount { .. }
            | ManaProduction::FromProducedEvent => true,
        },
        EffectOp::FreezeUntap { .. } => matches!(step.subject, Selector::SelfObj),
        _ => false,
    }
}

fn extract_unparsed_targets_impl(text: &str, ctx: &mut ParseCtx<'_>) -> Vec<TargetSpec> {
    let mut out = Vec::new();
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return out;
    }
    let toks = tokenize(trimmed, 0);
    let mut scope = crate::parser::filter::NullScope;
    let mut i = 0usize;
    while i < toks.len() {
        let cp = ctx.interner.checkpoint();
        if let Some((spec, used)) = parse_divided_targets(&toks[i..], ctx, &mut scope)
            && used > 0
        {
            out.push(spec);
            i += used;
            continue;
        }
        ctx.interner.rollback(cp);

        let cp2 = ctx.interner.checkpoint();
        if let Some((spec, used)) = parse_target_spec(&toks[i..], ctx, &mut scope)
            && used > 0
        {
            out.push(spec);
            i += used;
            continue;
        }
        ctx.interner.rollback(cp2);
        i += 1;
    }
    out
}
